use std::collections::{HashMap, HashSet};

use crate::ast::*;
use crate::codegen;
use crate::error::{Error, Result};
use crate::library;
use crate::modules::{IncludeScope, ModuleScope, Program};
use crate::parser::MAX_NESTING;

#[derive(Debug, Clone)]
struct MacroInfo {
    written: Expr,
    value: Option<Expr>,
    /// Cached error so repeated uses avoid recomputation.
    failed: Option<Error>,
    span: Span,
}

#[derive(Debug, Clone, PartialEq)]
enum Constant {
    Int(i64),
    Unit(u8),
    Float(f64),
    Char(u8),
    Bool(bool),
    Text(String),
}

impl Constant {
    fn of(e: &Expr) -> Option<Constant> {
        match (&e.kind, &e.ty) {
            (ExprKind::IntLit(n), Some(Type::Unit)) => u8::try_from(*n).ok().map(Constant::Unit),
            (ExprKind::IntLit(n), _) => Some(Constant::Int(*n)),
            (ExprKind::FloatLit(x), _) => Some(Constant::Float(*x)),
            (ExprKind::CharLit(c), _) => Some(Constant::Char(*c)),
            (ExprKind::BoolLit(b), _) => Some(Constant::Bool(*b)),
            (ExprKind::TextLit(t), _) => Some(Constant::Text(t.clone())),
            (ExprKind::Macro { value, .. }, _) => Constant::of(value),
            _ => None,
        }
    }

    fn ty(&self) -> Type {
        match self {
            Constant::Int(_) => Type::Int,
            Constant::Unit(_) => Type::Unit,
            Constant::Float(_) => Type::Float,
            Constant::Char(_) => Type::Char,
            Constant::Bool(_) => Type::Bool,
            Constant::Text(_) => Type::Text(None),
        }
    }

    fn literal(self, span: Span) -> Expr {
        let ty = self.ty();
        let kind = match self {
            Constant::Int(n) => ExprKind::IntLit(n),
            Constant::Unit(n) => ExprKind::IntLit(i64::from(n)),
            Constant::Float(x) => ExprKind::FloatLit(x),
            Constant::Char(c) => ExprKind::CharLit(c),
            Constant::Bool(b) => ExprKind::BoolLit(b),
            Constant::Text(t) => ExprKind::TextLit(t),
        };
        Expr {
            kind,
            span,
            ty: Some(ty),
        }
    }
}

#[derive(Clone)]
struct VariantInfo {
    kind: String,
    variant: Variant,
}

#[derive(Default)]
struct Scope {
    names: HashMap<String, VarInfo>,
    default: Option<(String, Span)>,
}

/// Provenance for enforcing that `fixed`-owned slices, maps, and pointers are never passed to mutable sinks.
#[derive(Clone, Debug, PartialEq)]
enum Own {
    Root(String),
    Param(usize, String),
    Sent {
        task: String,
        param: usize,
        from: Vec<Own>,
    },
    Kept(String),
    /// Copies clear ownership except when generic instantiation substitutes a closure (which still captures).
    Copied {
        task: String,
        ty: Type,
        from: Vec<Own>,
    },
}

type GivenTypes = (Vec<Type>, HashMap<String, Type>);

#[derive(Clone, Debug)]
enum HandedTo {
    Variable(String),
    Param { task: String, param: String },
    Place(String),
    Result(String),
    Written(String),
}

#[derive(Clone, Debug)]
struct Handed {
    span: Span,
    owners: Vec<Own>,
    to: HandedTo,
    copy: String,
    lambda: bool,
    no_region: Option<String>,
    generic: Option<(String, Type)>,
}

#[derive(Clone)]
struct VarInfo {
    ty: Type,
    mode: Mode,
    span: Span,
    /// False for region-only header parameters (`p: ^int@r`) where `new` cannot allocate.
    allocates: bool,
    result: bool,
    param: bool,
    passing: Passing,
    /// Resolved root path for `fixed&`/`flex&` bindings, chasing through aliases.
    refers: Option<Vec<Step>>,
    kept: bool,
    owners: Vec<Own>,
    family: Option<usize>,
    /// A copy a `[bind @r]` lambda keeps of what isn't a slice, map, or pointer, which it only reads.
    bind_reads: bool,
}

#[derive(Default)]
struct SliceFamily {
    added: Option<(String, Span)>,
    deleted: Option<(String, Span)>,
}

struct KeptLambda {
    region: String,
    mode: KeptMode,
    span: Span,
    outer: Vec<(String, VarInfo)>,
    within: Option<String>,
    uses: Vec<String>,
    places: Vec<KeptPlace>,
    owned: HashMap<String, Vec<Own>>,
}

enum TargetType {
    Discard,
    Place(Type),
    Tuple(Vec<TargetType>, Span),
}

type Declared = (String, Span, Type, Mode);

#[derive(Clone, Copy, PartialEq)]
enum TypePlace {
    Field,
    New,
    Shared,
    Header,
    Body,
}

#[derive(Default)]
pub struct Checker {
    shapes: HashMap<String, ShapeDef>,
    kinds: HashMap<String, KindDef>,
    patterns: HashMap<String, PatternDef>,
    task_spans: HashMap<String, Span>,
    /// Shapes/kinds that failed a pattern conformance check; skip verifying copied defaults to avoid duplicate errors.
    unfollowed: HashSet<String>,
    /// Concrete `this` type substituted while checking copied pattern default methods.
    this_type: Option<Type>,
    /// Pattern defaults may write `@this` on value-less generics before concrete followers are known.
    in_pattern_default: bool,
    /// Copied pattern default methods; headers may name `@this` inside another region, checked per call.
    default_copies: HashSet<String>,
    stand_ins_of: HashMap<String, Vec<(String, Type)>>,
    stand_ins: Vec<(String, Type)>,
    tasks: HashMap<String, TaskInfo>,
    type_params: Vec<TypeParam>,
    current_method: Option<Owner>,
    current_owner: Option<String>,
    regional: HashSet<String>,
    /// Shapes/kinds holding pointers (`regional`) or text (`Property@r` allocates in `r`, unanchored lasts for program).
    takes_region: HashSet<String>,
    /// Types with mutable contents (pointers, slices, arrays), which tuples reject.
    changeable: HashSet<String>,
    /// Shapes holding a `[flex @this]` lambda, in a field or in a shape of a field. A value of one is held as
    /// such a lambda is: in a flex variable, given as a place, never copied.
    held_types: HashSet<String>,
    variants: HashMap<String, VariantInfo>,
    macros: HashMap<String, MacroInfo>,
    modules: HashMap<String, ModuleScope>,
    private: HashSet<String>,
    current_module: String,
    scopes: Vec<Scope>,
    globals: HashMap<String, VarInfo>,
    current_ret: Option<Type>,
    result_names: Vec<String>,
    /// Unset named results on the current path; Vela has no zero values so all must be assigned.
    unset: HashSet<String>,
    moved: HashSet<String>,
    loop_scopes: Vec<usize>,
    type_places: TypePlaces,
    sizes: HashMap<String, u128>,
    each_iterator: Option<Type>,
    each_count: usize,
    /// `copy()` calls in the current statement awaiting region inference from destination.
    unsettled_copies: Vec<Span>,
    copy_words: HashMap<(usize, usize, usize), &'static str>,
    unsettled_types: Vec<(Span, String, String)>,
    pipe_target: Option<Type>,
    loop_place: Option<Type>,
    instances: Vec<(String, String, Vec<Type>, Span)>,
    noted_instances: HashSet<String>,
    /// Generic variant constructors whose type args are still inferred from destination.
    untold_kinds: Vec<(Span, String, String, String, String)>,
    making_shapes: Vec<String>,
    made_of: HashMap<String, Applied>,
    made_shapes: Vec<Item>,
    written_names: HashMap<String, String>,
    /// Generic-task copies into non-preserved regions; instantiated types there cannot hold regional data.
    loose_copies: HashMap<String, Vec<(String, String, bool, Span)>>,
    /// Accumulated errors; checking continues with `Type::Unknown` to avoid cascading diagnostics.
    errors: Vec<Error>,
    warnings: Vec<Error>,
    /// Deduplicated per-scope warnings suppressed unless `--repeat-warnings` is active.
    held_back: Vec<Error>,
    told_once: HashSet<(String, &'static str)>,
    slice_families: Vec<SliceFamily>,
    /// Declarations with broken headers/fields; uses fall back to `Type::Unknown` to prevent cascading errors.
    broken: HashSet<String>,
    defaults_checked: HashSet<String>,
    param_defaults: HashMap<String, Vec<Option<Expr>>>,
    in_default: Option<String>,
    in_shared: Option<(String, usize)>,
    /// Cached checked shared field initializers (`None` = failed and already reported).
    shared_values: HashMap<String, Option<Expr>>,
    shared_checking: Vec<String>,
    current_shape: Option<String>,
    current_type: Option<String>,
    /// Value-method call spans rewritten to plain calls, tracked across re-checks (other calls use `X.m`).
    on_values: HashSet<(usize, usize, usize)>,
    region_wanted: bool,
    current_lambda: Option<String>,
    current_task: String,
    param_index: HashMap<String, usize>,
    handed: Vec<Handed>,
    sends: HashMap<String, Vec<Own>>,
    natives: HashSet<String>,
    bound_owners: Vec<(Span, Vec<Own>)>,
    /// Saved at variable read span before value-block scope exits and local bindings disappear.
    read_owners: HashMap<(usize, usize, usize), Vec<Own>>,
    copies: HashMap<String, Vec<GivenTypes>>,
    /// Active tuple-item narrowings from `t.#k? is maybe T {x}` for subsequent conditions and block.
    narrowed: Vec<(String, usize, Type)>,
    group_turns: Vec<(String, usize)>,
    loops: Vec<Option<(String, Span)>>,
    loop_name: Option<(String, Span)>,
    /// Enclosing value-giving loops (`1`-based stack index, break types + spans).
    value_loops: Vec<(usize, Vec<(Type, Span)>)>,
    loop_gives: bool,
    loop_given: Option<(Type, Span)>,
    stepping: Option<usize>,
    lambda_outer: HashMap<String, HashSet<String>>,
    lambda_loops: HashMap<String, Vec<(String, Span)>>,
    kept_lambdas: HashMap<String, KeptLambda>,
    kept_order: Vec<String>,
    pub shortcut_lambdas: HashMap<String, TaskDef>,
    inferred_shortcut_lambdas: HashSet<String>,
    /// Shortcut lambdas already reached during checking (unreached ones sit behind failed statements).
    reached_shortcut_lambdas: HashSet<String>,
    kept_used: std::cell::RefCell<Vec<String>>,
    /// True while checking a variable read solely as a call target or `&` place (allows `[flex @r]` lambdas).
    calling: bool,
    /// Set while checking what a field is read from, or what a method is called on: a held value may be
    /// reached into there, as `it.f(…)` or `it.next()`, though it is never copied.
    reaching: bool,
    /// Set while checking a field that is called, `it.f(…)`.
    calling_field: bool,
    /// True while checking `xs.len`, which does not observe item reallocation from sibling slice aliases.
    reading_length: bool,
    kept_call: Option<String>,
    /// True while checking `args...`, the only valid read of a type-group parameter.
    spreading: bool,
    wrapped: Vec<(String, Vec<Expr>)>,
    wrapper_layers: HashMap<String, usize>,
    /// Wrapped tasks and their ordered chain of generated layer wrappers `[task, layer1, ...]`.
    wrapped_chains: Vec<(String, Vec<String>)>,
    start_values: Vec<StartValue>,
    /// Non-empty when checking startup-evaluated values outside any task (`<-` is disallowed).
    at_start: Option<&'static str>,
}

struct StartValue {
    task: String,
    wrapper: String,
    member: String,
    span: Span,
}

const DECORATOR_VALUES: &str = "a decorator's values";
const WRAPPER_VALUES: &str = "a wrapper's own values";

#[derive(Clone)]
struct TaskInfo {
    types: Vec<TypeParam>,
    params: Vec<(String, Type)>,
    passing: Vec<Passing>,
    ret: Type,
    owner: Option<Owner>,
}

const STR_NEEDS_REGION: &str = "'str' makes new text, so it names the region the text goes in, as in 'x.str() at r', 'x.str()@r', 'x.str(r)', or 'text(x) at r'";

const JSON_NEEDS_REGION: &str = "'json' makes new text, so it names the region the text goes in, as in 'x.json() at r', 'x.json()@r', 'x.json(r)', or 'to_json(x, r)'";

const JOIN_NEEDS_REGION: &str = "joining text makes new text, which goes in a region; name it after the last part, as in 'a + b at r', or after parentheses, as in '(a + b)@r'";

const UNSETTLED_COPY: &str = "can't tell which region to copy into, since nothing this copy goes into names one; name it, as in 'x.copy() at r' or 'x.copy()@r'";

/// Copies ignore block default regions because their destination determines their lifetime.
const COPY_IGNORES_DEFAULT: &str =
    "; a copy goes where the value it becomes goes, so a block's default region doesn't settle one";

#[derive(Clone, Copy)]
struct Branches {
    of: &'static str,
    each: &'static str,
    optional: bool,
}

const MATCH_BRANCHES: Branches = Branches {
    of: "match",
    each: "case",
    optional: false,
};
const WHEN_BRANCHES: Branches = Branches {
    of: "when",
    each: "branch",
    optional: false,
};
const LOOP_BRANCHES: Branches = Branches {
    of: "loop",
    each: "pass",
    optional: false,
};
const FINALLY_BRANCHES: Branches = Branches {
    of: "loop",
    each: "finally block",
    optional: false,
};
const OPTIONAL_LOOP_BRANCHES: Branches = Branches {
    of: "loop",
    each: "pass",
    optional: true,
};
const BOTH_LOOP_FORMS_WARNING: &str = "using both map-form loop values and a finally block; finally overrides the loop body return values";

impl Branches {
    fn needs_value(self) -> String {
        format!(
            "a {} of a {} used as a value gives it on its last line, or sends with '<-' on every path",
            self.each, self.of
        )
    }
}

fn shared_key(shape: &str, field: &str) -> String {
    format!("{}{}{}", shape, MODULE_SEPARATOR, field)
}

const FILE_SHAPE: &str = "std/files.File";

/// Bound generic monomorphization and recursive type-size growth (e.g. `f<(T, int)>` inside `f<T>`).
const MAX_INSTANCES: usize = 500;
const MAX_TYPE_DEPTH: usize = 24;

/// Cap on constructed type node count to bound type-checker complexity.
const MAX_TYPE_SIZE: usize = 1000;

/// Cap at 1 TiB so the C backend does not reject oversized value types.
const MAX_VALUE_BYTES: u128 = 1 << 40;

impl Checker {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn with_type_places(type_places: TypePlaces) -> Self {
        Checker {
            type_places,
            ..Self::default()
        }
    }

    pub fn errors(&self) -> &[Error] {
        &self.errors
    }

    fn record(&mut self, error: Error) {
        self.errors.push(error);
    }

    fn check_each(&mut self, values: &mut [Expr]) {
        for value in values {
            // Region args look like bare names; without task params, skip names already bound as regions.
            if matches!(&value.kind, ExprKind::Var(name) if self.lookup(name).is_some_and(|info| info.ty == Type::Region))
            {
                continue;
            }
            if let ExprKind::RegionAfter(region) = &value.kind {
                let known = self.visible_region(region, value.span, false);
                self.keep_going(known);
                continue;
            }
            let checked = match &mut value.kind {
                ExprKind::Ref(place) => self.check_expr(place),
                _ => self.check_expr(value),
            };
            self.keep_going(checked.map(|_| ()));
        }
    }

    fn or_unknown(&mut self, found: Result<Type>) -> Type {
        match found {
            Ok(ty) => ty,
            Err(error) => {
                self.record(error);
                Type::Unknown
            }
        }
    }

    fn keep_going(&mut self, result: Result<()>) -> bool {
        match result {
            Ok(()) => true,
            Err(error) => {
                self.record(error);
                false
            }
        }
    }

    pub fn check_program(program: &mut Program) -> Vec<Error> {
        Checker::check_program_warned(program).0
    }

    pub fn check_program_warned(program: &mut Program) -> (Vec<Error>, Vec<Error>) {
        let (errors, warnings, _) = Checker::check_program_held(program);
        (errors, warnings)
    }

    pub fn check_program_held(program: &mut Program) -> (Vec<Error>, Vec<Error>, Vec<Error>) {
        let mut checker = Checker::with_type_places(std::mem::take(&mut program.type_places));
        checker.modules = program
            .modules
            .iter()
            .map(|scope| (scope.name.clone(), scope.clone()))
            .collect();
        checker.declare_builtin_kinds();
        checker.patterns = program
            .patterns
            .iter()
            .map(|pattern| (pattern.name.clone(), pattern.clone()))
            .collect();
        checker.stand_ins_of = std::mem::take(&mut program.stand_ins);
        add_startups(&mut program.items);
        checker.add_wrappers(&mut program.items);
        checker.check_file(&mut program.items);
        // Skip post-check expansion and aliasing/ownership passes on broken programs to prevent spurious errors.
        if checker.errors.is_empty() {
            let made = checker.expand_instances(&mut program.items);
            checker.keep_going(made);
        }
        if checker.errors.is_empty() {
            checker.settle_owners();
        }
        // Always register monomorphized shapes/kinds so IDE analysis renders written generic names.
        program
            .items
            .extend(std::mem::take(&mut checker.made_shapes));
        if checker.errors.is_empty() {
            // Remove synthetic `START_VALUES` shape only after shared fields it may reference have been checked.
            if let Some(values) = checker.shapes.remove(START_VALUES) {
                program.items.push(Item::Shape(values));
            }
            // Inject built-in `ParseError`/`InputError` after checking so codegen emits them.
            program
                .items
                .extend(builtin_kinds().into_iter().map(Item::Kind));
        }
        program.type_places = checker.type_places;
        let written = std::mem::take(&mut checker.written_names);
        // Sort longest first so prefix names do not partially rewrite nested generic names.
        let mut made: Vec<(&String, &String)> = written.iter().collect();
        made.sort_by_key(|(name, _)| std::cmp::Reverse(name.len()));
        let mut errors = std::mem::take(&mut checker.errors);
        let warnings_at = errors.len();
        errors.append(&mut checker.warnings);
        let held_at = errors.len();
        errors.append(&mut checker.held_back);
        for error in &mut errors {
            for (name, form) in &made {
                if error.message.contains(name.as_str()) {
                    error.message = error.message.replace(name.as_str(), form);
                }
            }
            if let Some(scope) = error
                .span
                .and_then(|span| program.modules.iter().find(|scope| scope.file == span.file))
            {
                error.message = scope.spelling.text(&error.message);
            }
        }
        let held = errors.split_off(held_at);
        let warnings = errors.split_off(warnings_at);
        (
            in_source_order(errors),
            in_source_order(warnings),
            in_source_order(held),
        )
    }

    fn sees(&self, name: &str) -> bool {
        self.current_module.is_empty()
            || name.contains(MODULE_SEPARATOR)
            || BUILTIN_KIND_NAMES.contains(&name)
    }

    fn in_module(&self, name: &str) -> String {
        if let Some(full) = self
            .modules
            .get(&self.current_module)
            .and_then(|scope| scope.imported(name))
        {
            return full.to_string();
        }
        qualify(&self.current_module, name)
    }

    fn full_name(&self, name: &str) -> String {
        if name.contains(MODULE_SEPARATOR) {
            name.to_string()
        } else {
            self.in_module(name)
        }
    }

    fn variant_in_scope(&self, name: &str) -> Option<&VariantInfo> {
        if builtin_kind_of(name).is_some() {
            return self.variants.get(name);
        }
        self.variants.get(&self.in_module(name))
    }

    fn elsewhere(&self, name: &str) -> String {
        let Some(scope) = self.modules.get(&self.current_module) else {
            return String::new();
        };
        if name == unqualified(library::LOOP_RESULT) {
            return "; it is in Vela's library, and 'include std/loops {LoopResult}' brings it in"
                .to_string();
        }
        let declared = |full: &str| {
            !self.private.contains(full)
                && (self.tasks.contains_key(full)
                    || self.shapes.contains_key(full)
                    || self.kinds.contains_key(full)
                    || self.variants.contains_key(full))
        };
        let Some(include) = scope
            .includes
            .iter()
            .find(|include| declared(&qualify(&include.id, name)))
        else {
            return String::new();
        };
        let full = qualify(&include.id, name);
        match scope
            .imports
            .iter()
            .find(|(_, imported, _)| *imported == full)
        {
            Some((written, _, _)) if written == name => return String::new(),
            Some((alias, _, at)) => {
                return format!(
                    "; it is brought in as '{}' at {}:{}",
                    alias, at.line, at.col
                );
            }
            None => {}
        }
        match &include.local {
            Some(module) => format!(
                "; module '{}' has one: write '{}', or bring it in with 'include … ({})'",
                module, full, name
            ),
            None => format!(
                "; module '{}' has one: list it in 'include {} {{…}}'",
                include.written, include.written
            ),
        }
    }

    fn unknown_shape(&self, span: Span, name: &str) -> Error {
        match self.variants.get(name).filter(|_| self.sees(name)) {
            Some(info) => Error::at(
                span,
                format!(
                    "'{}' is a variant of kind '{}', not a shape; its values are written '{}(…)'",
                    info.variant.tag, info.kind, name
                ),
            ),
            None => Error::at(
                span,
                format!("unknown shape '{}'{}", name, self.elsewhere(name)),
            ),
        }
    }

    fn module_elsewhere(&self, name: &str) -> String {
        let Some(scope) = self.modules.get(&self.current_module) else {
            return String::new();
        };
        match scope
            .includes
            .iter()
            .find(|include| include.file_name == name && include.local.as_deref() != Some(name))
        {
            Some(IncludeScope {
                local: Some(alias),
                written,
                ..
            }) => format!("; module '{}' is included as '{}'", written, alias),
            Some(include) => format!(
                "; module '{}' is included with only its parts, which are named alone",
                include.written
            ),
            None => String::new(),
        }
    }

    fn module_used(&self, name: &str) -> Option<Span> {
        let scope = self.modules.get(&self.current_module)?;
        scope.included(name).map(|include| include.span)
    }

    fn place(&self, span: Span, part: &str) -> Span {
        let parts = self.type_places.get(&span.place_key());
        let found = |part: &str| {
            parts
                .and_then(|parts| parts.iter().find(|(name, _)| name == part))
                .map(|(_, at)| *at)
        };
        let spelled = self
            .modules
            .get(&self.current_module)
            .map(|scope| scope.spelling.name(part));
        found(part)
            .or_else(|| spelled.and_then(|spelled| found(&spelled)))
            .or_else(|| found(unqualified(part)))
            .unwrap_or(span)
    }

    pub fn check_file(&mut self, items: &mut [Item]) {
        self.collect_declarations(items);
        self.regional = regional_types(items);
        self.takes_region = textual_types(items)
            .union(&self.regional)
            .cloned()
            .collect();
        self.changeable = types_holding(items, holds_changeable);
        self.held_types = types_holding(items, holds_held_field);
        self.declare_patterns();
        self.check_global_region(items);
        for item in items.iter_mut() {
            if let Item::Task(t) = item {
                self.settle_receiver(t);
            }
        }
        self.check_declarations(items);
        self.settle_wrappers(items);
        // Field defaults run after decorators/wrappers settle because they may reference wrapped tasks.
        self.check_field_defaults(items);
        self.check_param_defaults(items);
        self.check_shared_fields(items);
        self.check_start_values(items);
        // Parser emits lambdas after enclosing code and outer-after-inner; check in reverse so `lambda_outer` is ready.
        let (lambdas, others): (Vec<&mut Item>, Vec<&mut Item>) = items
            .iter_mut()
            .partition(|item| matches!(item, Item::Task(t) if is_lambda(&t.name)));
        // Check pattern defaults once as generic-`this` tasks before follower copies so errors are not repeated.
        let (defaults, others): (Vec<&mut Item>, Vec<&mut Item>) = others
            .into_iter()
            .partition(|item| matches!(item, Item::Task(t) if t.name.contains(DEFAULT_MARK)));
        let mut failed: HashSet<(usize, usize, usize)> = HashSet::new();
        let copies_at = self.default_spans();
        for item in defaults
            .into_iter()
            .chain(others)
            .chain(lambdas.into_iter().rev())
        {
            if let Item::Task(t) = item {
                if t.shortcut {
                    if let Some(inferred) = self.shortcut_lambdas.get(&t.name) {
                        t.params = inferred.params.clone();
                        t.ret = inferred.ret.clone();
                        t.body = inferred.body.clone();
                    }
                    if self.inferred_shortcut_lambdas.contains(&t.name)
                        || !self.reached_shortcut_lambdas.contains(&t.name)
                    {
                        continue;
                    }
                }
                let copied = t.owner.is_some()
                    && !t.name.contains(DEFAULT_MARK)
                    && copies_at.contains(&t.span.place_key());
                if copied
                    && (failed.contains(&t.span.place_key())
                        || t.owner_type()
                            .is_some_and(|owner| self.unfollowed.contains(owner)))
                {
                    continue;
                }
                self.current_module = module_of(&t.name).to_string();
                let before = self.errors.len();
                let checked = self.check_task(t);
                self.keep_going(checked);
                if t.name.contains(DEFAULT_MARK) && self.errors.len() > before {
                    failed.insert(t.span.place_key());
                }
            }
        }
        self.current_module.clear();
        self.finish_kept();
        self.order_start_values(items);
    }

    /// Registers pattern signatures and maps methods as generic tasks over `THIS_TYPE` until call substitution.
    fn declare_patterns(&mut self) {
        let mut patterns: Vec<PatternDef> = self.patterns.values().cloned().collect();
        patterns.sort_by_key(|pattern| (pattern.span.file, pattern.span.line, pattern.span.col));
        for mut pattern in patterns {
            let module = std::mem::replace(
                &mut self.current_module,
                module_of(&pattern.name).to_string(),
            );
            let this = TypeParam {
                name: THIS_TYPE.to_string(),
                span: pattern.span,
                needs: Vec::new(),
                patterns: vec![Followed {
                    name: pattern.name.clone(),
                    types: pattern
                        .types
                        .iter()
                        .map(|param| Type::Param(param.name.clone()))
                        .collect(),
                    span: pattern.span,
                }],
                group: false,
            };
            let types: Vec<TypeParam> = std::iter::once(this.clone())
                .chain(pattern.types.iter().cloned())
                .collect();
            self.enter_type_params(&types);
            for field in &mut pattern.fields {
                match self.resolve_type(&field.ty, field.ty_span, TypePlace::Field) {
                    Ok(ty) => field.ty = ty,
                    Err(error) => self.record(error),
                }
            }
            self.type_params.clear();
            for method in &mut pattern.methods {
                let Some(own) = method.owner.as_ref().map(|owner| owner.name.clone()) else {
                    continue;
                };
                let mut call = method.clone();
                call.name = pattern_call(&pattern.name, &own);
                call.types = types
                    .iter()
                    .cloned()
                    .chain(method.types.iter().cloned())
                    .collect();
                call.body = Vec::new();
                self.written_names.insert(
                    call.name.clone(),
                    format!("{}{}{}", unqualified(&pattern.name), MODULE_SEPARATOR, own),
                );
                match self.check_header(&mut call) {
                    Ok(()) => {
                        method.params = call.params;
                        method.ret = call.ret;
                    }
                    Err(error) => {
                        self.broken.insert(call.name);
                        if method.body.is_empty() {
                            self.record(error);
                        }
                    }
                }
            }
            self.current_module = module;
            self.patterns.insert(pattern.name.clone(), pattern);
        }
    }

    fn pattern_with_method(&self, param: &str, method: &str, span: Span) -> Result<Option<String>> {
        let Some(declared) = self.type_param(param) else {
            return Ok(None);
        };
        let found: Vec<&String> = declared
            .patterns
            .iter()
            .map(|followed| &followed.name)
            .filter(|pattern| {
                self.patterns
                    .get(*pattern)
                    .is_some_and(|def| def.method(method).is_some())
            })
            .collect();
        match found.as_slice() {
            [] => Ok(None),
            [one] => Ok(Some((*one).clone())),
            [first, second, ..] => err(
                span,
                format!(
                    "'{}' follows patterns '{}' and '{}', which both ask for a method '{}', so this call doesn't say which it is; follow one of them here",
                    Type::Param(param.to_string()),
                    unqualified(first),
                    unqualified(second),
                    method
                ),
            ),
        }
    }

    /// Value-less generic type params have unknown region, so field reads on them cannot yield regional values.
    fn pattern_field(&self, param: &str, field: &str, span: Span) -> Result<Type> {
        let base = Type::Param(param.to_string());
        let patterns = self
            .type_param(param)
            .map(|declared| declared.patterns.clone())
            .unwrap_or_default();
        let Some(found) = patterns.iter().find_map(|followed| {
            self.patterns
                .get(&followed.name)
                .and_then(|def| def.fields.iter().find(|own| own.name == field))
        }) else {
            if patterns.is_empty() {
                return err(
                    span,
                    format!(
                        "type {} has no fields; a type a declaration takes has the fields of the patterns it follows, as in '<{}: Named>'",
                        base, base
                    ),
                );
            }
            let names: Vec<&str> = patterns
                .iter()
                .map(|followed| unqualified(&followed.name))
                .collect();
            return err(
                span,
                format!(
                    "type {} has no field '{}': none of the patterns it follows ({}) asks for one",
                    base,
                    field,
                    names.join(", ")
                ),
            );
        };
        let ty = found
            .ty
            .map_params(&mut |name| (name == THIS_TYPE).then(|| base.clone()));
        if param == THIS_TYPE {
            return Ok(self.field_in(&ty, &Some(THIS_WORD.to_string())));
        }
        if holds_text(&ty, &self.takes_region) || holds_pointers(&ty, &self.regional) {
            return err(
                span,
                format!(
                    "field '{}' is {}, which lives where the value holding it does, and a task taking {} doesn't know where that is; read it through a method the pattern asks for",
                    field, ty, base
                ),
            );
        }
        Ok(ty)
    }

    fn is_default(&self, t: &TaskDef) -> bool {
        t.owner.as_ref().is_some_and(|owner| !owner.shared)
            && self
                .patterns
                .values()
                .flat_map(|pattern| &pattern.methods)
                .any(|method| {
                    !method.body.is_empty() && method.span.place_key() == t.span.place_key()
                })
    }

    fn default_spans(&self) -> HashSet<(usize, usize, usize)> {
        self.patterns
            .values()
            .flat_map(|pattern| &pattern.methods)
            .filter(|method| !method.body.is_empty())
            .map(|method| method.span.place_key())
            .collect()
    }

    fn follows(&self, ty: &Type, pattern: &str) -> bool {
        if ty.unknown() || is_untold(ty) {
            return true;
        }
        if let Type::Param(name) | Type::Group(name) = ty {
            return self
                .type_param(name)
                .is_some_and(|param| param.patterns.iter().any(|own| own.name == pattern));
        }
        let Some(owner) = self.owner_of(ty) else {
            return false;
        };
        let source = self
            .made_of
            .get(&owner)
            .map_or(owner, |made| made.name.clone());
        let follows = self
            .shapes
            .get(&source)
            .map(|shape| &shape.follows)
            .or_else(|| self.kinds.get(&source).map(|kind| &kind.follows));
        follows.is_some_and(|follows| {
            follows
                .iter()
                .any(|(followed, _)| followed_name(followed) == Some(pattern))
        })
    }

    fn followed_by(&self, ty: &Type, pattern: &str) -> Option<Vec<Type>> {
        if let Type::Param(name) = ty {
            let declared = self.type_param(name)?;
            let followed = declared
                .patterns
                .iter()
                .find(|followed| followed.name == pattern)?;
            return Some(followed.types.iter().map(|ty| self.as_params(ty)).collect());
        }
        let unmade = self.unmade(ty);
        let (source, given) = match &unmade {
            Type::Named(name, _) => (name.clone(), Vec::new()),
            Type::Applied(applied) => (applied.name.clone(), applied.types.clone()),
            _ => return None,
        };
        let (follows, types) = match (self.shapes.get(&source), self.kinds.get(&source)) {
            (Some(shape), _) => (&shape.follows, &shape.types),
            (None, Some(kind)) => (&kind.follows, &kind.types),
            (None, None) => return None,
        };
        let (followed, _) = follows
            .iter()
            .find(|(followed, _)| followed_name(followed) == Some(pattern))?;
        let put = |name: &str| {
            types
                .iter()
                .position(|param| param.name == name)
                .and_then(|i| given.get(i).cloned())
        };
        Some(
            followed_types(followed)
                .iter()
                .map(|ty| ty.replace_names(&put).map_params(&mut |name| put(name)))
                .collect(),
        )
    }

    fn as_params(&self, ty: &Type) -> Type {
        ty.replace_names(&|name| {
            self.type_param(name)
                .map(|param| Type::Param(param.name.clone()))
        })
    }

    /// Verifies pattern conformance (skipping defaults already copied by `modules::follow_patterns`).
    fn check_follows(
        &mut self,
        name: &str,
        fields: Option<&[Field]>,
        follows: &[(Type, Span)],
    ) -> Result<()> {
        let mut asked: HashMap<String, String> = HashMap::new();
        let own_types = self
            .shapes
            .get(name)
            .map(|shape| shape.types.clone())
            .or_else(|| self.kinds.get(name).map(|kind| kind.types.clone()))
            .unwrap_or_default();
        for (followed, at) in follows {
            let Some(pattern_name) = followed_name(followed) else {
                continue;
            };
            let Some(pattern) = self.patterns.get(pattern_name).cloned() else {
                continue;
            };
            let written = unqualified(pattern_name);
            let given = followed_types(followed);
            if given.len() != pattern.types.len() {
                let names: Vec<&str> = pattern
                    .types
                    .iter()
                    .map(|param| param.name.as_str())
                    .collect();
                return err(
                    *at,
                    match (pattern.types.is_empty(), given.is_empty()) {
                        (true, _) => {
                            format!("pattern '{}' takes no types; leave out '<…>'", written)
                        }
                        (false, true) => format!(
                            "pattern '{0}' takes {1}, so name {2}, as in '{0}<{3}>'",
                            written,
                            count(names.len(), "type"),
                            if names.len() == 1 {
                                "it"
                            } else {
                                "all of them"
                            },
                            names.join(", ")
                        ),
                        (false, false) => format!(
                            "pattern '{}' takes {}, and is given {}",
                            written,
                            count(names.len(), "type"),
                            given.len()
                        ),
                    },
                );
            }
            let put: HashMap<String, Type> = pattern
                .types
                .iter()
                .map(|param| param.name.clone())
                .zip(given.iter().map(|ty| named_params(ty, &own_types)))
                .collect();
            let outer = std::mem::replace(&mut self.type_params, own_types.clone());
            let allowed = pattern
                .types
                .iter()
                .try_for_each(|param| match put.get(&param.name) {
                    Some(ty) => self.check_need("pattern", pattern_name, param, ty, *at),
                    None => Ok(()),
                });
            self.type_params = outer;
            allowed?;
            let pattern = with_given(&pattern, &put);
            if fields.is_none()
                && let Some(field) = pattern.fields.first()
            {
                return err(
                    *at,
                    format!(
                        "pattern '{}' asks for field '{}', and a kind has no fields; only a shape follows a pattern with fields",
                        written, field.name
                    ),
                );
            }
            for field in &pattern.fields {
                if let Some(other) = asked.insert(field.name.clone(), written.to_string()) {
                    return err(
                        *at,
                        format!(
                            "patterns '{}' and '{}' both ask for '{}'; '{}' follows each, so it would need two of it",
                            other,
                            written,
                            field.name,
                            unqualified(name)
                        ),
                    );
                }
                let Some(own) =
                    fields.and_then(|fields| fields.iter().find(|own| own.name == field.name))
                else {
                    return err(
                        *at,
                        format!(
                            "'{0}' follows pattern '{1}', which asks for field '{2}: {3}'; declare it in '{0}'",
                            unqualified(name),
                            written,
                            field.name,
                            field.ty
                        ),
                    );
                };
                if own.ty.without_regions() != field.ty.without_regions() {
                    return err(
                        own.ty_span,
                        format!(
                            "field '{}' is {} here, and pattern '{}', which '{}' follows, asks for it as {}",
                            own.name,
                            own.ty,
                            written,
                            unqualified(name),
                            field.ty
                        ),
                    );
                }
                if own.private {
                    return err(
                        own.span,
                        format!(
                            "field '{}' is one pattern '{}' asks for, so code using the pattern reads it, and it isn't 'priv'",
                            own.name, written
                        ),
                    );
                }
            }
            for method in &pattern.methods {
                let Some(own) = method.owner.as_ref().map(|owner| owner.name.clone()) else {
                    continue;
                };
                if let Some(other) = asked.insert(own.clone(), written.to_string()) {
                    return err(
                        *at,
                        format!(
                            "patterns '{}' and '{}' both ask for '{}'; '{}' follows each, so it would need two of it",
                            other,
                            written,
                            own,
                            unqualified(name)
                        ),
                    );
                }
                let full = method_name(name, &own);
                let Some(info) = self.tasks.get(&full).cloned() else {
                    let header = self.pattern_header(method, name);
                    return err(
                        *at,
                        format!(
                            "'{0}' follows pattern '{1}', which asks for method '{2}'; write it in '{0}', as in '{3}'",
                            unqualified(name),
                            written,
                            own,
                            header
                        ),
                    );
                };
                let span = self.task_spans.get(&full).copied().unwrap_or(*at);
                let mine = info.owner.clone().unwrap_or(Owner {
                    name: own.clone(),
                    alters: false,
                    alters_span: None,
                    shared: false,
                });
                if mine.shared {
                    return err(
                        span,
                        format!(
                            "'{}' is a shared method, and pattern '{}', which '{}' follows, asks for a method of every value of it, '{}'",
                            own,
                            written,
                            unqualified(name),
                            self.pattern_header(method, name)
                        ),
                    );
                }
                if self.private.contains(&full) {
                    return err(
                        span,
                        format!(
                            "method '{}' is one pattern '{}' asks for, so code using the pattern calls it, and it isn't 'priv'",
                            own, written
                        ),
                    );
                }
                if self.broken.contains(&full)
                    || self.broken.contains(&pattern_call(pattern_name, &own))
                    || (!method.body.is_empty() && span.place_key() == method.span.place_key())
                {
                    continue;
                }
                if !self.same_header(method, &info, name) {
                    return err(
                        span,
                        format!(
                            "method '{}' of '{}' has another header than pattern '{}' asks for: write it '{}'",
                            own,
                            unqualified(name),
                            written,
                            self.pattern_header(method, name)
                        ),
                    );
                }
            }
        }
        Ok(())
    }

    fn pattern_header(&self, method: &TaskDef, owner: &str) -> String {
        let this = Type::Named(
            unqualified(owner).to_string(),
            self.takes_region
                .contains(owner)
                .then(|| THIS_WORD.to_string()),
        );
        let put = |ty: &Type| {
            ty.replace_names(&|name| (name == THIS_TYPE).then(|| this.clone()))
                .map_params(&mut |name| (name == THIS_TYPE).then(|| this.clone()))
        };
        let params: Vec<String> = method
            .params
            .iter()
            .skip(1)
            .map(|param| {
                let word = match param.passing.word() {
                    "" => String::new(),
                    word => format!("{} ", word),
                };
                format!("{}{}: {}", word, param.name, put(&param.ty))
            })
            .collect();
        let alters = if method.owner.as_ref().is_some_and(|owner| owner.alters) {
            "alters "
        } else {
            ""
        };
        let name = method
            .owner
            .as_ref()
            .map_or("", |owner| owner.name.as_str());
        let ret = match &method.ret {
            Type::Nothing => String::new(),
            Type::Results(types) => format!(
                " -> {}",
                types
                    .iter()
                    .map(|ty| put(ty).to_string())
                    .collect::<Vec<_>>()
                    .join(", ")
            ),
            other => format!(" -> {}", put(other)),
        };
        let own = match method.types.is_empty() {
            true => String::new(),
            false => format!(
                "<{}>",
                method
                    .types
                    .iter()
                    .map(|param| param.name.as_str())
                    .collect::<Vec<_>>()
                    .join(", ")
            ),
        };
        format!("{}{}{}({}){}", alters, name, own, params.join(", "), ret)
    }

    fn same_header(&self, method: &TaskDef, info: &TaskInfo, owner: &str) -> bool {
        let alters = |owner: Option<&Owner>| owner.is_some_and(|owner| owner.alters);
        if alters(method.owner.as_ref()) != alters(info.owner.as_ref())
            || method.params.len() != info.params.len()
        {
            return false;
        }
        let owner_types = self
            .shapes
            .get(owner)
            .map(|shape| shape.types.len())
            .or_else(|| self.kinds.get(owner).map(|kind| kind.types.len()))
            .unwrap_or(0);
        let mine_own: Vec<&str> = info
            .types
            .iter()
            .skip(owner_types)
            .map(|param| param.name.as_str())
            .collect();
        if mine_own.len() != method.types.len() {
            return false;
        }
        let own_place = |names: Vec<&str>| -> HashMap<String, Type> {
            names
                .into_iter()
                .enumerate()
                .map(|(i, name)| (name.to_string(), Type::Param(format!("#{}", i))))
                .collect()
        };
        let asked_own = own_place(
            method
                .types
                .iter()
                .map(|param| param.name.as_str())
                .collect(),
        );
        let mine_own = own_place(mine_own);
        let this = info
            .params
            .first()
            .map_or_else(|| Type::named(owner), |(_, ty)| ty.clone());
        let put = |ty: &Type| {
            ty.map_params(&mut |name| {
                if name == THIS_TYPE {
                    Some(this.clone())
                } else {
                    asked_own.get(name).cloned()
                }
            })
            .replace_names(&|name| (name == THIS_TYPE).then(|| this.clone()))
        };
        let info = &TaskInfo {
            params: info
                .params
                .iter()
                .map(|(name, ty)| {
                    (
                        name.clone(),
                        ty.map_params(&mut |name| mine_own.get(name).cloned()),
                    )
                })
                .collect(),
            ret: info.ret.map_params(&mut |name| mine_own.get(name).cloned()),
            ..info.clone()
        };
        let regions = |names: Vec<&str>| -> HashMap<String, String> {
            names
                .into_iter()
                .enumerate()
                .map(|(i, name)| (name.to_string(), format!("#{}", i)))
                .collect()
        };
        let asked = regions(
            method
                .params
                .iter()
                .filter(|param| param.ty == Type::Region)
                .map(|param| param.name.as_str())
                .collect(),
        );
        let mine = regions(
            info.params
                .iter()
                .filter(|(_, ty)| *ty == Type::Region)
                .map(|(name, _)| name.as_str())
                .collect(),
        );
        let named = |ty: &Type, names: &HashMap<String, String>| {
            ty.map_regions(&mut |region| {
                Some(
                    names
                        .get(region)
                        .cloned()
                        .unwrap_or_else(|| region.to_string()),
                )
            })
        };
        let params = method
            .params
            .iter()
            .zip(&info.params)
            .zip(&info.passing)
            .skip(1)
            .all(|((asked_param, (_, ty)), passing)| {
                asked_param.passing == *passing
                    && named(&put(&asked_param.ty), &asked) == named(ty, &mine)
            });
        params && named(&put(&method.ret), &asked) == named(&info.ret, &mine)
    }

    fn check_copies_of(&self, task: &str, types: &[Type], at: Span) -> Result<()> {
        let Some(copies) = self.loose_copies.get(task) else {
            return Ok(());
        };
        let Some(info) = self.tasks.get(task) else {
            return Ok(());
        };
        let given: HashMap<&str, &Type> = info
            .types
            .iter()
            .map(|param| param.name.as_str())
            .zip(types)
            .collect();
        for (param, region, in_header, copy_at) in copies {
            let Some(ty) = given.get(param.as_str()) else {
                continue;
            };
            let Some(lives) = ty
                .regions()
                .into_iter()
                .find(|region| *region != ANY_REGION)
            else {
                continue;
            };
            let what = if *in_header {
                format!(
                    "nothing in its header keeps a '{}' in '{}', so that copy is only the value itself",
                    param, region
                )
            } else {
                format!(
                    "'{}' is declared inside '{}' and freed when it ends, so that copy is only the value itself",
                    region,
                    unqualified(task)
                )
            };
            let fix = if *in_header {
                format!(
                    "name the region in a parameter's type, as in 'xs: [{}]@{}', or write '{}' for {} itself",
                    param,
                    region,
                    unqualified(task),
                    ty
                )
            } else {
                format!(
                    "copy the value before the call, or write '{}' for {} itself",
                    unqualified(task),
                    ty
                )
            };
            return err(
                at,
                format!(
                    "'{}' copies a '{}' into region '{}' at {}:{}, and {}; this use gives {}, which is in region '{}'. So {}",
                    unqualified(task),
                    param,
                    region,
                    copy_at.line,
                    copy_at.col,
                    what,
                    ty,
                    lives,
                    fix
                ),
            );
        }
        Ok(())
    }

    fn expand_instances(&mut self, items: &mut Vec<Item>) -> Result<()> {
        let generic: HashMap<String, TaskDef> = items
            .iter()
            .filter_map(|item| match item {
                Item::Task(t) if !t.types.is_empty() => Some((t.name.clone(), t.clone())),
                _ => None,
            })
            .collect();
        let mut made: HashSet<String> = HashSet::new();
        let mut queue: Vec<(String, String, Vec<Type>, Span)> = self.instances.drain(..).collect();
        let mut tasks: Vec<Item> = Vec::new();
        while let Some((key, name, types, at)) = queue.pop() {
            if !made.insert(key.clone()) {
                continue;
            }
            if made.len() > MAX_INSTANCES {
                return err(
                    at,
                    format!(
                        "'{}' is used with more than {} different types, which no program needs; a generic task whose call gives a type built from its own, or a group with values added to it, never stops",
                        unqualified(&name),
                        MAX_INSTANCES
                    ),
                );
            }
            let Some(source) = generic.get(&name) else {
                return Err(Error::internal_at(
                    at,
                    format!(
                        "no generic task '{}' to make for {} types",
                        name,
                        types.len()
                    ),
                ));
            };
            self.check_copies_of(&name, &types, at)?;
            if types.iter().any(|ty| type_depth(ty) > MAX_TYPE_DEPTH) {
                return err(
                    at,
                    format!(
                        "this use of '{}' gives a type built up more than {} types deep; a generic task whose call gives a type built from its own never stops",
                        unqualified(&name),
                        MAX_TYPE_DEPTH
                    ),
                );
            }
            let mut task = source.clone();
            task.name = key;
            task.types = Vec::new();
            task.given = types.clone();
            let mut given: HashMap<String, Type> = source
                .types
                .iter()
                .map(|param| param.name.clone())
                .zip(types)
                .collect();
            for param in source.types.iter().filter(|param| param.group) {
                let types = group_types(&given, &param.name).unwrap_or_default();
                for (place, ty) in types.iter().enumerate() {
                    given.insert(group_item(&param.name, place), ty.clone());
                }
                given.insert(format!("{}{}", param.name, GROUP_MARK), Type::Tuple(types));
            }
            for ty in given.values_mut() {
                self.settle_applications(ty, at)?;
            }
            self.copies
                .entry(name.clone())
                .or_default()
                .push((task.given.clone(), given.clone()));
            let mut made = Made::default();
            self.substitute_task(&mut task, &given, &mut made)?;
            if let Some((read, place, given_count)) = made.past_items.first() {
                return err(
                    at,
                    format!(
                        "this use gives '{}' {}, and its tuple of them is read at item {} at {}:{}{}; read it there with '.#{}', a maybe, or inside 'when args.len > {}'",
                        unqualified(&name),
                        count(*given_count, "value"),
                        place,
                        read.line,
                        read.col,
                        self.file_named(read.file, at.file),
                        place,
                        place
                    ),
                );
            }
            for (span, what, param) in &made.reads_chosen {
                let Some((ty, declared)) = made.chosen.get(param) else {
                    continue;
                };
                let types: Vec<String> = task
                    .given
                    .iter()
                    .map(|ty| ty.without_regions().to_string())
                    .collect();
                let given = format!(
                    "where '{}' is given {}, at {}:{}{}",
                    unqualified(&name),
                    types.join(", "),
                    at.line,
                    at.col,
                    self.file_named(at.file, span.file)
                );
                let message =
                    chosen_message(what, param, ty, declared, self.size_of(ty), Some(given));
                self.warnings.push(Error::at(*span, message));
            }
            if let Some((compare, ty)) = made.placeless.first() {
                return err(
                    at,
                    format!(
                        "this use gives '{}' {}, which the '==' or '!=' at {}:{}{} compares by where it is, as it does arrays, shapes, and tuples, and a side there is a value made on the spot, with no place of its own; compare them item by item with '~=' there, and ask for '<T: similar>'",
                        unqualified(&name),
                        ty.without_regions(),
                        compare.line,
                        compare.col,
                        self.file_named(compare.file, at.file)
                    ),
                );
            }
            for (name, types, at) in made.needed {
                // Reject exponentially doubling tuple growth (`f((v, v))` inside `f`) before depth limit hits.
                let parts = |ty: &Type| match ty {
                    Type::Tuple(items) => items.iter().map(type_size).max().unwrap_or(0),
                    other => type_size(other),
                };
                if types.iter().any(|ty| parts(ty) > MAX_TYPE_SIZE) {
                    return err(
                        at,
                        format!(
                            "this use of '{}' gives a type of more than {} parts; a generic task whose call gives a type built from its own never stops",
                            unqualified(&name),
                            MAX_TYPE_SIZE
                        ),
                    );
                }
                queue.push((instance_name(&name, &types), name, types, at));
            }
            tasks.push(Item::Task(task));
        }
        items.extend(tasks);
        Ok(())
    }

    fn declare_builtin_kinds(&mut self) {
        for kind in builtin_kinds() {
            for variant in &kind.variants {
                let info = VariantInfo {
                    kind: kind.name.clone(),
                    variant: variant.clone(),
                };
                self.variants.insert(variant.tag.clone(), info);
            }
            self.kinds.insert(kind.name.clone(), kind);
        }
    }

    fn collect_declarations(&mut self, items: &[Item]) {
        let mut names: HashMap<String, Span> = HashMap::new();
        // Collect duplicate-name errors into `found` before recording so `self.names` can stay borrowed; keep first decl.
        let mut found: Vec<Error> = Vec::new();
        let mut declare = |name: &str, span: Span| -> Result<()> {
            let written = unqualified(name);
            if Type::builtin(written).is_some() {
                return err(
                    span,
                    format!("'{}' is a builtin type and cannot be redefined", written),
                );
            }
            if BUILTIN_TASKS.contains(&written) {
                return err(
                    span,
                    format!("'{}' is a builtin task and cannot be redefined", written),
                );
            }
            if BUILTIN_KIND_NAMES.contains(&written) {
                let what = match builtin_kind_of(written) {
                    Some(kind) => format!("a variant of the builtin kind '{}'", kind),
                    None => "a builtin kind".to_string(),
                };
                return err(
                    span,
                    format!("'{}' is {} and cannot be redefined", written, what),
                );
            }
            if let Some(at) = names.get(name) {
                return err(
                    span,
                    format!("'{}' is already defined at {}:{}", written, at.line, at.col),
                );
            }
            names.insert(name.to_string(), span);
            Ok(())
        };
        for item in items {
            let private = match item {
                Item::Task(t) => t.private,
                Item::Shape(s) => s.private,
                Item::Kind(k) => k.private,
                Item::Macro(m) => m.private,
                Item::GlobalRegion(_) => false,
            };
            if private {
                self.private.insert(item.name().to_string());
                if let Item::Kind(k) = item {
                    self.private.extend(
                        k.variants
                            .iter()
                            .enumerate()
                            .map(|(i, v)| variant_name(k, i, v)),
                    );
                }
            }
            let mut taken = |name: &str, span: Span| -> bool {
                match declare(name, span) {
                    Ok(()) => false,
                    Err(error) => {
                        found.push(error);
                        true
                    }
                }
            };
            match item {
                Item::Shape(s) => {
                    if taken(&s.name, s.span) {
                        continue;
                    }
                    self.shapes.insert(s.name.clone(), s.clone());
                }
                Item::Kind(k) => {
                    if taken(&k.name, k.span) {
                        continue;
                    }
                    for (i, v) in k.variants.iter().enumerate() {
                        let full = variant_name(k, i, v);
                        if i >= k.imitated && taken(&full, v.span) {
                            continue;
                        }
                        let info = VariantInfo {
                            kind: k.name.clone(),
                            variant: v.clone(),
                        };
                        self.variants.insert(full, info);
                    }
                    self.kinds.insert(k.name.clone(), k.clone());
                }
                Item::Task(t) => {
                    if taken(&t.name, t.span) {
                        continue;
                    }
                    self.task_spans.insert(t.name.clone(), t.span);
                    if let Some(owner) = &t.owner
                        && let Some(ty) = t.owner_type()
                    {
                        let written = format!("{}{}{}", ty, MODULE_SEPARATOR, owner.name);
                        self.written_names.insert(t.name.clone(), written);
                        let short = method_name(unqualified(ty), &owner.name);
                        self.written_names.insert(
                            short,
                            format!("{}{}{}", unqualified(ty), MODULE_SEPARATOR, owner.name),
                        );
                    }
                    let params = t
                        .params
                        .iter()
                        .map(|p| (p.name.clone(), p.ty.clone()))
                        .collect();
                    self.tasks.insert(
                        t.name.clone(),
                        TaskInfo {
                            types: t.types.clone(),
                            params,
                            passing: t.params.iter().map(|p| p.passing).collect(),
                            ret: t.ret.clone(),
                            owner: t.owner.clone(),
                        },
                    );
                    if t.shortcut {
                        self.shortcut_lambdas.insert(t.name.clone(), t.clone());
                    }
                }
                Item::Macro(m) => {
                    if taken(&m.name, m.span) {
                        continue;
                    }
                    self.macros.insert(
                        m.name.clone(),
                        MacroInfo {
                            written: m.value.clone(),
                            value: None,
                            failed: None,
                            span: m.span,
                        },
                    );
                }
                Item::GlobalRegion(_) => {}
            }
        }
        for error in found {
            self.record(error);
        }
    }

    fn check_declarations(&mut self, items: &mut [Item]) {
        for item in items.iter_mut() {
            let name = item.name().to_string();
            self.current_module = module_of(&name).to_string();
            let mut declared = self.check_private_types(item);
            if declared.is_ok() {
                declared = self.check_declaration(item);
            }
            if !self.keep_going(declared) {
                self.broken.insert(name);
            }
        }
        for item in items.iter() {
            let (name, fields, follows) = match item {
                Item::Shape(s) if !s.follows.is_empty() => {
                    (&s.name, Some(s.fields.as_slice()), &s.follows)
                }
                Item::Kind(k) if !k.follows.is_empty() => (&k.name, None, &k.follows),
                _ => continue,
            };
            if self.broken.contains(name) {
                continue;
            }
            self.current_module = module_of(name).to_string();
            let followed = self.check_follows(name, fields, follows);
            if !self.keep_going(followed) {
                self.unfollowed.insert(name.clone());
            }
        }
        let mut acyclic = HashSet::new();
        let mut order = Vec::new();
        for item in items.iter() {
            let name = match item {
                Item::Shape(s) => s.name.clone(),
                Item::Kind(k) => k.name.clone(),
                Item::Task(_) | Item::Macro(_) | Item::GlobalRegion(_) => continue,
            };
            if let Err((error, cycle)) = self.check_value_cycle(&name, &mut acyclic, &mut order) {
                self.record(error);
                for found in cycle {
                    acyclic.insert(found.clone());
                    self.broken.insert(found);
                }
                self.broken.insert(name);
            }
        }
        self.current_module.clear();
        self.check_sizes(&order);
        self.check_constructible(items);
    }

    /// Run last so literal field-default expansion cannot infinite-loop on cyclic by-value shapes (already `broken`).
    fn check_field_defaults(&mut self, items: &[Item]) {
        for item in items {
            if let Item::Shape(shape) = item {
                self.check_defaults_of(&shape.name);
            }
        }
    }

    fn check_param_defaults(&mut self, items: &mut [Item]) {
        for item in items.iter_mut() {
            let Item::Task(t) = item else { continue };
            if t.params.iter().all(|param| param.default.is_none()) || self.broken.contains(&t.name)
            {
                continue;
            }
            let module =
                std::mem::replace(&mut self.current_module, module_of(&t.name).to_string());
            self.enter_type_params(&t.types);
            let checked = self.check_defaults_of_task(t);
            self.type_params.clear();
            self.current_module = module;
            match checked {
                Ok(values) => {
                    self.param_defaults.insert(t.name.clone(), values);
                }
                Err(error) => {
                    self.keep_going(Err(error));
                    self.broken.insert(t.name.clone());
                }
            }
        }
    }

    #[inline(never)]
    fn check_defaults_of_task(&mut self, t: &mut TaskDef) -> Result<Vec<Option<Expr>>> {
        let names: Vec<String> = t
            .params
            .iter()
            .map(|param| param.name.clone())
            .filter(|name| name != THIS)
            .collect();
        let mut values = Vec::with_capacity(t.params.len());
        for param in &mut t.params {
            let Some(value) = &mut param.default else {
                values.push(None);
                continue;
            };
            let mut other = None;
            walk_expr(value, &mut |expr| {
                if let ExprKind::Var(name) = &expr.kind
                    && other.is_none()
                    && names.contains(name)
                {
                    other = Some((name.clone(), expr.span));
                }
            });
            if matches!(value.kind, ExprKind::Closure { .. }) {
                return err(
                    value.span,
                    format!(
                        "a lambda that keeps what it uses keeps it in a region, which the value parameter '{}' falls back on can't name, since it is worked out before the call; give a lambda that keeps nothing, or a task",
                        param.name
                    ),
                );
            }
            if let Some((other, at)) = other {
                return err(
                    at,
                    format!(
                        "the value parameter '{}' falls back on is worked out before the program runs, so it can't read parameter '{}', which a call gives",
                        param.name, other
                    ),
                );
            }
            self.check_default_value(
                value,
                &param.ty,
                &format!("parameter '{}'", param.name),
                "the task takes, which is a different type in every use",
            )?;
            // `none` defaults for `maybe T` depend on call-site `T`, so type-check per call instead of once.
            if !param.ty.params().is_empty() {
                values.push(Some(Expr::new(ExprKind::NoneLit, value.span)));
                continue;
            }
            values.push(Some(value.clone()));
        }
        Ok(values)
    }

    /// Outlined (`#[inline(never)]`) to avoid bloating caller stacks; safe from cycles since `broken` excludes cyclic shapes.
    #[inline(never)]
    fn check_defaults_of(&mut self, name: &str) {
        if self.broken.contains(name) || !self.defaults_checked.insert(name.to_string()) {
            return;
        }
        let Some(shape) = self.shapes.get(name).cloned() else {
            return;
        };
        if shape.fields.iter().all(|field| field.default.is_none()) {
            return;
        }
        let module = std::mem::replace(&mut self.current_module, module_of(name).to_string());
        let types = std::mem::take(&mut self.type_params);
        self.enter_type_params(&shape.types);
        let mut checked = Ok(());
        for (i, field) in shape.fields.iter().enumerate() {
            if let Some(value) = &field.default {
                let mut value = value.clone();
                if is_arithmetic(Some(&value))
                    && let Ok(folded) = self.fold_constant(&value, &mut Vec::new())
                {
                    value = folded.literal(value.span);
                    if let Some(kept) = self
                        .shapes
                        .get_mut(name)
                        .and_then(|shape| shape.fields.get_mut(i))
                    {
                        kept.default = Some(value.clone());
                    }
                }
                checked = self.check_field_default(&mut value, &field.ty, &field.name);
                if checked.is_err() {
                    break;
                }
            }
        }
        self.type_params = types;
        self.current_module = module;
        if !self.keep_going(checked) {
            self.broken.insert(name.to_string());
        }
    }

    fn check_declaration(&mut self, item: &mut Item) -> Result<()> {
        match item {
            Item::Shape(s) => {
                self.enter_type_params(&s.types);
                let fields = self.check_fields(&mut s.fields);
                self.type_params.clear();
                fields?;
                for member in &mut s.shared {
                    let field = &mut member.field;
                    field.ty = self.resolve_type(&field.ty, field.ty_span, TypePlace::Shared)?;
                    self.check_shared_type(&field.ty, field.ty_span, &field.name)?;
                }
                if let Some(shape) = self.shapes.get_mut(&s.name) {
                    shape.shared = s.shared.clone();
                }
                // Preserve pre-instantiation field types on `self.shapes` so `shape_instance` can substitute generic params later.
                if let Some(shape) = self.shapes.get_mut(&s.name) {
                    shape.fields = s.fields.clone();
                }
            }
            Item::Kind(k) => {
                if k.variants.is_empty() {
                    return err(k.span, format!("kind '{}' has no variants", k.name));
                }
                self.enter_type_params(&k.types);
                let payloads = k
                    .variants
                    .iter_mut()
                    .try_for_each(|v| self.check_fields(&mut v.payload));
                // A match takes a variant's values out as copies, so no variant holds what is never copied.
                if let Some(field) = k.variants.iter().flat_map(|v| &v.payload).find(|field| {
                    held_value(&field.ty, &self.held_types) || holds_held(&field.ty, &self.held_types)
                }) {
                    return err(
                        self.place(field.ty_span, "flex"),
                        format!(
                            "a variant can't hold {}, since a 'match' takes its values out as copies and such a lambda is never copied; hold it in a shape's field",
                            held_phrase(&field.ty)
                        ),
                    );
                }
                let imitated = payloads.and_then(|()| {
                    k.imitates.iter_mut().try_for_each(|(ty, at)| {
                        *ty = self.resolve_type(ty, *at, TypePlace::Field)?;
                        Ok(())
                    })
                });
                self.type_params.clear();
                imitated?;
                if let Some(kind) = self.kinds.get_mut(&k.name) {
                    kind.variants = k.variants.clone();
                    kind.imitates = k.imitates.clone();
                }
            }
            Item::Macro(m) if self.macros.contains_key(&m.name) => {
                m.value = self.macro_value(&m.name, &mut Vec::new())?
            }
            Item::Macro(_) => {}
            Item::GlobalRegion(_) => {}
            Item::Task(t) => {
                self.this_type = method_this(t);
                self.in_pattern_default = self.is_default(t);
                if self.in_pattern_default {
                    self.default_copies.insert(t.name.clone());
                }
                self.stand_ins = self.stand_ins_of.get(&t.name).cloned().unwrap_or_default();
                let read = self.check_task_declaration(t);
                self.this_type = None;
                self.in_pattern_default = false;
                self.stand_ins.clear();
                read?;
            }
        }
        Ok(())
    }

    fn check_task_declaration(&mut self, t: &mut TaskDef) -> Result<()> {
        // Inherited/imitated variant names share the `Kind.Name` namespace with shared methods.
        if let (Some(owner), Some(kind)) = (
            t.owner.as_ref().filter(|owner| owner.shared),
            t.owner_type().and_then(|kind| self.kinds.get(kind)),
        ) && let Some(variant) = kind
            .variants
            .iter()
            .take(kind.imitated)
            .find(|variant| variant.tag == owner.name)
        {
            let from = kind
                .imitates
                .iter()
                .find(|(_, at)| *at == variant.span)
                .map_or(String::new(), |(ty, _)| {
                    format!(", from '{}', which it imitates", ty)
                });
            return err(
                t.span,
                format!(
                    "'{0}' is already a variant of '{1}'{2}; '{1}.{0}(…)' makes the variant, so a shared method can't take its name",
                    owner.name,
                    unqualified(&kind.name),
                    from
                ),
            );
        }
        self.check_header(t)?;
        if t.name == "main" {
            if let Some(param) = t.params.first() {
                return err(param.span, "task 'main' cannot take parameters");
            }
            if t.ret != Type::Nothing {
                return err(t.ret_span(), "task 'main' cannot return a value");
            }
        }
        Ok(())
    }

    fn macro_value(&mut self, name: &str, through: &mut Vec<String>) -> Result<Expr> {
        let Some(info) = self.macros.get(name) else {
            return Err(Error::internal(format!("no macro '{}'", name)));
        };
        if let Some(value) = &info.value {
            return Ok(value.clone());
        }
        if let Some(error) = &info.failed {
            return Err(error.clone());
        }
        let (written, span) = (info.written.clone(), info.span);
        if let Some(first) = through.iter().position(|macro_name| macro_name == name) {
            let mut chain: Vec<&str> = through.iter().skip(first).map(|m| unqualified(m)).collect();
            chain.push(unqualified(name));
            return err(
                span,
                format!(
                    "macro '{}' is computed from itself: {}",
                    unqualified(name),
                    chain.join(" from ")
                ),
            );
        }
        if through.len() >= MAX_NESTING {
            return err(
                span,
                format!(
                    "a chain of macros, each computed from the next, is at most {} long, and '{}' is the {}st",
                    MAX_NESTING,
                    unqualified(name),
                    MAX_NESTING + 1
                ),
            );
        }
        through.push(name.to_string());
        let module = std::mem::replace(&mut self.current_module, module_of(name).to_string());
        let value = self.fold_constant(&written, through);
        self.current_module = module;
        through.pop();
        let value = value.map(|value| value.literal(span));
        if let Some(info) = self.macros.get_mut(name) {
            match &value {
                Ok(value) => info.value = Some(value.clone()),
                Err(error) => info.failed = Some(error.clone()),
            }
        }
        value
    }

    fn fold_constant(&mut self, e: &Expr, through: &mut Vec<String>) -> Result<Constant> {
        let span = e.span;
        let not_constant = |what: &str| -> Result<Constant> {
            err(
                span,
                format!(
                    "a macro's value is computed when compiling, from literals, other macros, and operators on them, so it can't be {}",
                    what
                ),
            )
        };
        match &e.kind {
            ExprKind::IntLit(_)
            | ExprKind::FloatLit(_)
            | ExprKind::CharLit(_)
            | ExprKind::BoolLit(_)
            | ExprKind::TextLit(_)
            | ExprKind::Macro { .. } => Constant::of(e)
                .ok_or_else(|| Error::internal_at(span, "a literal that is no constant")),
            ExprKind::Var(name) if self.macros.contains_key(name.as_str()) => {
                let value = self.macro_value(name, through)?;
                Constant::of(&value)
                    .ok_or_else(|| Error::internal_at(span, "a macro that is no constant"))
            }
            ExprKind::Var(name) if is_lambda(name) => {
                not_constant("a lambda, which is a task; write it where its value goes")
            }
            ExprKind::Var(name) => {
                not_constant(&format!("'{}', which is no macro", unqualified(name)))
            }
            ExprKind::Unary(op, operand) => {
                let value = self.fold_constant(operand, through)?;
                match (op, value) {
                    (UnaryOp::Neg, Constant::Int(n)) => n
                        .checked_neg()
                        .map(Constant::Int)
                        .ok_or_else(|| Error::at(span, "the value doesn't fit in an int")),
                    (UnaryOp::Neg, Constant::Float(x)) => Ok(Constant::Float(-x)),
                    (UnaryOp::Not, Constant::Bool(b)) => Ok(Constant::Bool(!b)),
                    (UnaryOp::Neg, other) => err(
                        span,
                        format!("'-' makes an int or a float negative, not a {}", other.ty()),
                    ),
                    (UnaryOp::Not, other) => {
                        err(span, format!("'not' is for a bool, not a {}", other.ty()))
                    }
                }
            }
            ExprKind::Binary(op, l, r) => {
                let (a, b) = (
                    self.fold_constant(l, through)?,
                    self.fold_constant(r, through)?,
                );
                fold_binary(*op, a, b, span)
            }
            ExprKind::Call { name, args, .. } if number_cast(name).is_some() => {
                let [arg] = args.as_slice() else {
                    return err(span, format!("'{}(…)' takes one value", name));
                };
                let value = self.fold_constant(arg, through)?;
                fold_cast(name, value, span)
            }
            ExprKind::Call { name, .. } => {
                not_constant(&format!("a call, '{}(…)'", unqualified(name)))
            }
            ExprKind::Join { .. } => not_constant(
                "text holding values; join text with '+', as in '#TITLE = NAME + \"!\"'",
            ),
            ExprKind::NoneLit => not_constant("'none'"),
            ExprKind::Array(_) | ExprKind::Repeat { .. } => not_constant("an array"),
            ExprKind::Tuple(_) => not_constant("a tuple"),
            _ => not_constant("anything that makes a value when the program runs"),
        }
    }

    fn check_sizes(&mut self, order: &[String]) {
        for name in order {
            let (bytes, span) = match (self.shapes.get(name), self.kinds.get(name)) {
                (Some(shape), _) => (fields_bytes(&shape.fields, &self.sizes), shape.span),
                (None, Some(kind)) => {
                    let largest = kind
                        .variants
                        .iter()
                        .map(|v| fields_bytes(&v.payload, &self.sizes))
                        .max()
                        .unwrap_or(0);
                    (largest.saturating_add(8), kind.span)
                }
                (None, None) => continue,
            };
            if bytes > MAX_VALUE_BYTES {
                self.record(Error::at(
                    span,
                    format!(
                        "'{}' is too large: a value of it would take more than 1 TiB of memory",
                        unqualified(name)
                    ),
                ));
                self.broken.insert(name.clone());
                continue;
            }
            self.sizes.insert(name.clone(), bytes);
        }
    }

    fn check_size(&self, ty: &Type, span: Span) -> Result<()> {
        if value_bytes(ty, &self.sizes) > MAX_VALUE_BYTES {
            return err(
                span,
                format!(
                    "{} is too large: a value of it would take more than 1 TiB of memory; a slice in a region can be as long as memory allows",
                    ty
                ),
            );
        }
        Ok(())
    }

    fn check_private_types(&self, item: &Item) -> Result<()> {
        let (private, what, name, fields): (bool, &str, &str, Vec<&Field>) = match item {
            // Private owners keep their methods inaccessible externally anyway, so private param/return types are allowed.
            Item::Task(t) if t.owner.is_some() => {
                let hidden = t.owner_type().is_some_and(|ty| self.private.contains(ty));
                let receiver = usize::from(t.owner.as_ref().is_some_and(|owner| !owner.shared));
                (
                    t.private || hidden,
                    "method",
                    &t.name,
                    t.params.iter().skip(receiver).collect(),
                )
            }
            Item::Task(t) => (t.private, "task", &t.name, t.params.iter().collect()),
            Item::Shape(s) => (
                s.private,
                "shape",
                &s.name,
                s.fields
                    .iter()
                    .chain(s.shared.iter().map(|m| &m.field))
                    .filter(|f| !f.private)
                    .collect(),
            ),
            Item::Kind(k) => (
                k.private,
                "kind",
                &k.name,
                k.variants.iter().flat_map(|v| &v.payload).collect(),
            ),
            Item::Macro(_) | Item::GlobalRegion(_) => return Ok(()),
        };
        if private {
            return Ok(());
        }
        let mut written: Vec<(&Type, Span)> = fields.iter().map(|f| (&f.ty, f.ty_span)).collect();
        if let Item::Task(t) = item {
            written.extend(
                t.ret
                    .results()
                    .iter()
                    .enumerate()
                    .map(|(i, ty)| (ty, t.result_span(i))),
            );
        }
        for (ty, span) in written {
            let hidden = named_types(ty).into_iter().find(|n| {
                self.shapes.get(*n).is_some_and(|s| s.private)
                    || self.kinds.get(*n).is_some_and(|k| k.private)
            });
            if let Some(hidden) = hidden {
                let fix = if matches!(item, Item::Shape(_)) {
                    "make the field 'priv' too, or the type public"
                } else {
                    "make it 'priv' too, or the type public"
                };
                return err(
                    self.place(span, hidden),
                    format!(
                        "{} '{}' is public, but '{}' is private to its file, so other files couldn't name it; {}",
                        what,
                        unqualified(name),
                        unqualified(hidden),
                        fix
                    ),
                );
            }
        }
        Ok(())
    }

    fn check_struct_init(
        &mut self,
        span: Span,
        name: &mut String,
        written: &mut Vec<TypeArg>,
        fields: &mut Vec<FieldInit>,
    ) -> Result<Type> {
        if self.sees(name) && self.kinds.contains_key(name.as_str()) {
            return refuse(|| {
                Error::at(
                    span,
                    format!(
                        "'{}' is a kind, not a shape; create its values with its variants",
                        name
                    ),
                )
            });
        }
        let mut shape = self
            .shapes
            .get(name.as_str())
            .filter(|_| self.sees(name))
            .ok_or_else(|| self.unknown_shape(span, name))?
            .clone();
        self.check_defaults_of(name);
        if self.broken.contains(name.as_str()) {
            let mut values: Vec<&mut Expr> =
                fields.iter_mut().map(|field| &mut field.value).collect();
            for value in &mut values {
                let checked = self.check_expr(value);
                self.keep_going(checked.map(|_| ()));
            }
            return Ok(Type::Unknown);
        }
        let mut given_types: Option<Vec<Type>> = None;
        if !shape.types.is_empty() {
            let types = self.literal_types(span, name, written, &shape, fields)?;
            if types.iter().any(|ty| !ty.params().is_empty()) {
                *written = types.iter().map(|ty| (ty.clone(), span)).collect();
                given_types = Some(types);
            } else {
                let made = self.shape_instance(name, &types, span)?;
                *name = made.clone();
                written.clear();
                shape = self.shapes.get(&made).cloned().unwrap_or(shape);
            }
        } else if let Some((ty, at)) = written.first() {
            return refuse(|| {
                Error::at(
                    *at,
                    format!(
                        "shape '{}' takes no types, so '< … >' has nothing to name; write '{}' alone",
                        unqualified(name),
                        ty
                    ),
                )
            });
        }
        // Private fields without defaults restrict construction to the declaring module.
        let outside = module_of(name) != self.current_module;
        if outside
            && let Some(hidden) = shape
                .fields
                .iter()
                .find(|f| f.private && f.default.is_none())
        {
            return refuse(|| {
                Error::at(
                    span,
                    format!(
                        "'{}' can't be built outside its file, since its field '{}' is private and falls back on no value; a task of its module can build it, or that field can name the value it falls back on",
                        name, hidden.name
                    ),
                )
            });
        }
        let mut seen: HashMap<String, Span> = HashMap::new();
        let mut declared = Vec::new();
        for field in fields.iter() {
            let Some(field_def) = shape.fields.iter().find(|f| f.name == field.name) else {
                if shape
                    .shared
                    .iter()
                    .any(|member| member.field.name == field.name)
                {
                    return refuse(|| {
                        Error::at(
                            field.span,
                            format!(
                                "'{0}' is a shared field of '{1}', one value for the whole program rather than part of each value, so no literal gives it; it is '{1}.{0}'",
                                field.name, name
                            ),
                        )
                    });
                }
                return refuse(|| {
                    Error::at(
                        field.span,
                        format!("shape '{}' has no field '{}'", name, field.name),
                    )
                });
            };
            if let Some(at) = seen.get(&field.name) {
                return refuse(|| {
                    Error::at(
                        field.span,
                        format!(
                            "field '{}' is already given at {}:{}",
                            field.name, at.line, at.col
                        ),
                    )
                });
            }
            if field_def.private && outside && !field.filled {
                return refuse(|| {
                    Error::at(
                        field.span,
                        format!(
                            "'{}' is a private field of '{}', which only its own file can give; leave it out and it falls back on its own value",
                            field.name, name
                        ),
                    )
                });
            }
            // `read` fields with defaults cannot be overridden in struct literals so shape invariants stay private.
            if field_def.read && field_def.default.is_some() && !field.filled {
                return refuse(|| {
                    Error::at(
                        field.span,
                        format!(
                            "'{}' is a read-only field of '{1}' that falls back on its own value, so no literal gives it; only the alters methods of '{1}' change it",
                            field.name, name
                        ),
                    )
                });
            }
            seen.insert(field.name.clone(), field.span);
            declared.push(field_def.clone());
        }
        // Materialize omitted default fields here so codegen never inspects missing fields.
        for field_def in &shape.fields {
            if seen.contains_key(&field_def.name) {
                continue;
            }
            let Some(default) = &field_def.default else {
                return refuse(|| {
                    Error::at(
                        span,
                        format!("missing field '{}' in '{}'", field_def.name, name),
                    )
                });
            };
            fields.push(FieldInit {
                name: field_def.name.clone(),
                span,
                value: default.clone(),
                filled: true,
            });
            declared.push(field_def.clone());
        }
        if let Some(types) = &given_types {
            let given: HashMap<&str, &Type> = shape
                .types
                .iter()
                .map(|param| param.name.as_str())
                .zip(types)
                .collect();
            for field in &mut declared {
                field.ty = field
                    .ty
                    .map_params(&mut |name| given.get(name).map(|ty| (*ty).clone()));
            }
        }
        let written = fields.iter().filter(|field| !field.filled).count();
        let mut values: Vec<&mut Expr> = fields.iter_mut().map(|field| &mut field.value).collect();
        let region =
            self.check_fields_of_value(&mut values, &declared, Some((written, module_of(name))))?;
        match given_types {
            Some(types) => {
                let region = self.region_of_applied(name, &shape, region);
                Ok(Type::Applied(Box::new(Applied {
                    name: name.clone(),
                    types,
                    region,
                })))
            }
            None => Ok(Type::Named(
                name.clone(),
                self.region_of_value(name, region),
            )),
        }
    }

    fn region_of_applied(&self, name: &str, shape: &ShapeDef, region: String) -> Option<String> {
        let may_hold = self.takes_region.contains(name)
            || shape
                .fields
                .iter()
                .any(|field| !field.ty.params().is_empty());
        may_hold.then_some(region)
    }

    fn resolve_applied(
        &mut self,
        applied: &Applied,
        span: Span,
        place: TypePlace,
        inside: Option<&str>,
    ) -> Result<Type> {
        let name = &applied.name;
        let at = self.place(span, name);
        if self.type_param(name).is_some() {
            return err(
                at,
                format!(
                    "'{}' is a type this declaration takes, so it takes no types of its own",
                    name
                ),
            );
        }
        let Some((word, params, parts)) = self.takes_types(name).filter(|_| self.sees(name)) else {
            return Err(self.unknown_shape(at, name));
        };
        if params.is_empty() {
            return err(
                at,
                format!(
                    "{} '{}' takes no types, so '< … >' has nothing to name",
                    word,
                    unqualified(name)
                ),
            );
        }
        if params.len() != applied.types.len() {
            let names: Vec<&str> = params.iter().map(|param| param.name.as_str()).collect();
            return err(
                at,
                format!(
                    "{} '{}' takes {}, so name {}, as in '{}<{}>'",
                    word,
                    unqualified(name),
                    count(params.len(), "type"),
                    if params.len() == 1 {
                        "it"
                    } else {
                        "all of them"
                    },
                    unqualified(name),
                    names.join(", ")
                ),
            );
        }
        // Generic args share the enclosing value's region (e.g. `Box<text>@r` puts `text` in `r`).
        if let Some(named) = applied
            .types
            .iter()
            .flat_map(Type::regions)
            .find(|named| applied.region.as_deref() != Some(*named))
        {
            let given: Vec<String> = applied
                .types
                .iter()
                .map(|ty| ty.without_regions().to_string())
                .collect();
            return err(
                self.place(span, &format!("@{}", named)),
                format!(
                    "a type given lives in the region of the value holding it, so it names no region; write '{}<{}>@{}'",
                    unqualified(name),
                    given.join(", "),
                    named
                ),
            );
        }
        let region = applied.region.as_deref().or(inside);
        let mut types = Vec::new();
        for ty in &applied.types {
            types.push(self.resolve_regions(ty, span, place, region)?);
        }
        for (param, ty) in params.iter().zip(&types) {
            self.check_need(word, name, param, ty, at)?;
        }
        if types.iter().any(|ty| !ty.params().is_empty()) {
            let may_hold = self.takes_region.contains(name.as_str())
                || parts.iter().any(|ty| !ty.params().is_empty());
            if may_hold && region.is_none() && matches!(place, TypePlace::Header | TypePlace::Body)
            {
                return err(
                    at,
                    format!(
                        "'{0}<{1}>' may hold text or pointers, since the types given may, so it names the region its values live in: write '{0}<{1}>@r', with 'r' a region the header names (such as an 'r: region' parameter)",
                        unqualified(name),
                        types
                            .iter()
                            .map(Type::to_string)
                            .collect::<Vec<_>>()
                            .join(", ")
                    ),
                );
            }
            return Ok(Type::Applied(Box::new(applied.with_types(types))));
        }
        let key = self.instance(name, &types, at)?;
        self.resolve_regions(
            &Type::Named(key, applied.region.clone()),
            span,
            place,
            inside,
        )
    }

    fn takes_types(&self, name: &str) -> Option<(&'static str, Vec<TypeParam>, Vec<Type>)> {
        if let Some(shape) = self.shapes.get(name) {
            return Some((
                "shape",
                shape.types.clone(),
                shape.fields.iter().map(|field| field.ty.clone()).collect(),
            ));
        }
        let kind = self.kinds.get(name)?;
        Some((
            "kind",
            kind.types.clone(),
            kind.variants
                .iter()
                .flat_map(|variant| variant.payload.iter().map(|field| field.ty.clone()))
                .collect(),
        ))
    }

    fn instance(&mut self, name: &str, types: &[Type], at: Span) -> Result<String> {
        if self.kinds.contains_key(name) {
            return self.kind_instance(name, types, at);
        }
        self.shape_instance(name, types, at)
    }

    fn kind_instance(&mut self, name: &str, types: &[Type], at: Span) -> Result<String> {
        let types: Vec<Type> = types.iter().map(Type::without_regions).collect();
        let key = instance_name(name, &types);
        if self.kinds.contains_key(&key) {
            return Ok(key);
        }
        let Some(source) = self.kinds.get(name).cloned() else {
            return Err(Error::internal_at(
                at,
                format!("no kind '{}' to make for {} types", name, types.len()),
            ));
        };
        if types
            .iter()
            .any(|ty| type_depth(ty) > MAX_TYPE_DEPTH || type_size(ty) > MAX_TYPE_SIZE)
        {
            return err(
                at,
                format!(
                    "this use of '{}' gives a type built up more than {} types deep; a kind whose variant gives it a type built from its own never stops",
                    unqualified(name),
                    MAX_TYPE_DEPTH
                ),
            );
        }
        if self.made_shapes.len() >= MAX_INSTANCES {
            return err(
                at,
                format!(
                    "more than {} shapes and kinds are made for the types they are given, which no program needs; a kind whose variant gives it a type built from its own never stops",
                    MAX_INSTANCES
                ),
            );
        }
        if self.making_shapes.len() >= MAX_TYPE_DEPTH {
            let names = source
                .types
                .iter()
                .map(|param| param.name.clone())
                .collect::<Vec<_>>()
                .join(", ");
            return err(
                at,
                format!(
                    "'{0}' would need more than {1} kinds made for it, one inside the next: a variant of it gives it a type built from its own, which never stops. A variant can name the kind with the types it takes, as in 'maybe ^{0}<{2}>'",
                    unqualified(name),
                    MAX_TYPE_DEPTH,
                    names
                ),
            );
        }
        // Register before resolving variants so pointer self-recursion resolves to this instance.
        let written = format!(
            "{}<{}>",
            name,
            types
                .iter()
                .map(Type::to_string)
                .collect::<Vec<_>>()
                .join(", ")
        );
        self.written_names.insert(key.clone(), written);
        self.made_of.insert(
            key.clone(),
            Applied {
                name: name.to_string(),
                types: types.clone(),
                region: None,
            },
        );
        let made = KindDef {
            name: key.clone(),
            types: Vec::new(),
            given: types.clone(),
            variants: Vec::new(),
            span: source.span,
            private: source.private,
            imitates: Vec::new(),
            follows: Vec::new(),
            imitated: source.imitated,
        };
        self.kinds.insert(key.clone(), made);
        self.making_shapes.push(key.clone());
        let given: HashMap<String, Type> = source
            .types
            .iter()
            .map(|param| param.name.clone())
            .zip(types)
            .collect();
        let mut variants = Vec::new();
        let mut found = Ok(());
        for variant in &source.variants {
            let mut payload = Vec::new();
            for field in &variant.payload {
                let outer = std::mem::replace(&mut self.type_params, source.types.clone());
                let read = self.resolve_type(&field.ty, field.ty_span, TypePlace::Field);
                self.type_params = outer;
                let ty = read.map(|ty| ty.map_params(&mut |param| given.get(param).cloned()));
                match ty.and_then(|ty| self.resolve_type(&ty, field.ty_span, TypePlace::Field)) {
                    Ok(ty) => payload.push(Field {
                        ty,
                        ..field.clone()
                    }),
                    Err(error) => found = Err(error),
                }
            }
            variants.push(Variant {
                payload,
                ..variant.clone()
            });
        }
        self.making_shapes.pop();
        if let Err(error) = found {
            self.kinds.remove(&key);
            self.written_names.remove(&key);
            self.made_of.remove(&key);
            return Err(error);
        }
        if let Some(kind) = self.kinds.get_mut(&key) {
            kind.variants = variants.clone();
        }
        let payloads: Vec<&Field> = variants
            .iter()
            .flat_map(|variant| &variant.payload)
            .collect();
        if payloads
            .iter()
            .any(|field| holds_pointers(&field.ty, &self.regional))
        {
            self.regional.insert(key.clone());
        }
        if self.regional.contains(&key)
            || payloads
                .iter()
                .any(|field| holds_text(&field.ty, &self.takes_region))
        {
            self.takes_region.insert(key.clone());
        }
        if payloads
            .iter()
            .any(|field| holds_changeable(&field.ty, &self.changeable))
        {
            self.changeable.insert(key.clone());
        }
        let largest = variants
            .iter()
            .map(|variant| fields_bytes(&variant.payload, &self.sizes))
            .max()
            .unwrap_or(0);
        let bytes = largest.saturating_add(8);
        if bytes > MAX_VALUE_BYTES {
            return err(
                at,
                format!(
                    "'{}' is too large: a value of it would take more than 1 TiB of memory",
                    key
                ),
            );
        }
        self.sizes.insert(key.clone(), bytes);
        if let Err((error, _)) = self.check_value_cycle(&key, &mut HashSet::new(), &mut Vec::new())
        {
            return Err(error);
        }
        if let Some(kind) = self.kinds.get(&key) {
            self.made_shapes.push(Item::Kind(kind.clone()));
        }
        Ok(key)
    }

    /// Shared monomorphization across regions: field types drop regions and inherit the enclosing value's region.
    fn shape_instance(&mut self, name: &str, types: &[Type], at: Span) -> Result<String> {
        let types: Vec<Type> = types.iter().map(Type::without_regions).collect();
        let key = instance_name(name, &types);
        if self.shapes.contains_key(&key) {
            return Ok(key);
        }
        let Some(source) = self.shapes.get(name).cloned() else {
            return Err(Error::internal_at(
                at,
                format!("no shape '{}' to make for {} types", name, types.len()),
            ));
        };
        if types
            .iter()
            .any(|ty| type_depth(ty) > MAX_TYPE_DEPTH || type_size(ty) > MAX_TYPE_SIZE)
        {
            return err(
                at,
                format!(
                    "this use of '{}' gives a type built up more than {} types deep; a shape whose field gives it a type built from its own never stops",
                    unqualified(name),
                    MAX_TYPE_DEPTH
                ),
            );
        }
        if self.made_shapes.len() >= MAX_INSTANCES {
            return err(
                at,
                format!(
                    "more than {} shapes are made for the types they are given, which no program needs; a shape whose field gives it a type built from its own never stops",
                    MAX_INSTANCES
                ),
            );
        }
        // Self-recursion with identical args reuses this instance; infinite structural growth hits `MAX_TYPE_DEPTH`.
        if self.making_shapes.len() >= MAX_TYPE_DEPTH {
            let names = source
                .types
                .iter()
                .map(|param| param.name.clone())
                .collect::<Vec<_>>()
                .join(", ");
            return err(
                at,
                format!(
                    "'{0}' would need more than {1} shapes made for it, one inside the next: a field of it gives it a type built from its own, which never stops. A field can name the shape with the types it takes, as in 'maybe ^{0}<{2}>'",
                    unqualified(name),
                    MAX_TYPE_DEPTH,
                    names
                ),
            );
        }
        let written = format!(
            "{}<{}>",
            name,
            types
                .iter()
                .map(Type::to_string)
                .collect::<Vec<_>>()
                .join(", ")
        );
        self.written_names.insert(key.clone(), written);
        self.made_of.insert(
            key.clone(),
            Applied {
                name: name.to_string(),
                types: types.clone(),
                region: None,
            },
        );
        let made = ShapeDef {
            name: key.clone(),
            types: Vec::new(),
            given: types.clone(),
            fields: Vec::new(),
            shared: Vec::new(),
            span: source.span,
            private: source.private,
            follows: Vec::new(),
        };
        self.shapes.insert(key.clone(), made);
        self.making_shapes.push(key.clone());
        let fields = self.instance_fields(&source, types);
        self.making_shapes.pop();
        let fields = match fields {
            Ok(fields) => fields,
            // Roll back incomplete instance so later references see the same error rather than an empty shape.
            Err(error) => {
                self.shapes.remove(&key);
                self.written_names.remove(&key);
                self.made_of.remove(&key);
                return Err(error);
            }
        };
        if let Some(shape) = self.shapes.get_mut(&key) {
            shape.fields = fields.clone();
        }
        if fields
            .iter()
            .any(|field| holds_pointers(&field.ty, &self.regional))
        {
            self.regional.insert(key.clone());
        }
        if self.regional.contains(&key)
            || fields
                .iter()
                .any(|field| holds_text(&field.ty, &self.takes_region))
        {
            self.takes_region.insert(key.clone());
        }
        if fields
            .iter()
            .any(|field| holds_changeable(&field.ty, &self.changeable))
        {
            self.changeable.insert(key.clone());
        }
        let bytes = fields_bytes(&fields, &self.sizes);
        if bytes > MAX_VALUE_BYTES {
            return err(
                at,
                format!(
                    "'{}' is too large: a value of it would take more than 1 TiB of memory",
                    key
                ),
            );
        }
        self.sizes.insert(key.clone(), bytes);
        if let Err((error, _)) = self.check_value_cycle(&key, &mut HashSet::new(), &mut Vec::new())
        {
            return Err(error);
        }
        if let Some(shape) = self.shapes.get(&key) {
            self.made_shapes.push(Item::Shape(shape.clone()));
        }
        Ok(key)
    }

    fn literal_types(
        &mut self,
        span: Span,
        name: &str,
        written: &mut [TypeArg],
        shape: &ShapeDef,
        fields: &mut [FieldInit],
    ) -> Result<Vec<Type>> {
        let mut given: HashMap<String, Type> = HashMap::new();
        if let Some((_, at)) = written.first() {
            if written.len() != shape.types.len() {
                let names: Vec<&str> = shape
                    .types
                    .iter()
                    .map(|param| param.name.as_str())
                    .collect();
                return err(
                    *at,
                    format!(
                        "shape '{}' takes {}, so name all of them, as in '{}<{}> {{ … }}'",
                        unqualified(name),
                        count(shape.types.len(), "type"),
                        unqualified(name),
                        names.join(", ")
                    ),
                );
            }
            for ((ty, at), param) in written.iter_mut().zip(&shape.types) {
                *ty = self.resolve_type(ty, *at, TypePlace::Field)?;
                self.check_need("shape", name, param, ty, *at)?;
                given.insert(param.name.clone(), ty.clone());
            }
            for ((ty, at), param) in written.iter().zip(&shape.types) {
                self.check_bound_types(name, &shape.types, param, ty, &given, *at)?;
            }
            return Ok(shape
                .types
                .iter()
                .filter_map(|param| given.get(&param.name).cloned())
                .collect());
        }
        // Save copy/untold state and re-check against instantiated fields once inferred.
        let copies = self.unsettled_copies.len();
        let untold = self.unsettled_types.len();
        let kinds = self.untold_kinds.len();
        let mut found = Ok(());
        for field in fields.iter_mut() {
            let Some(declared) = shape.fields.iter().find(|f| f.name == field.name) else {
                continue;
            };
            self.solve_bounds(&shape.types, &mut given);
            if let Err(error) =
                self.prepare_shortcut_lambda(&mut field.value, &in_copy(&declared.ty, &given))
            {
                found = Err(error);
                break;
            }
            match self.check_expr(&mut field.value) {
                Ok(ty) => {
                    let mut told = HashMap::new();
                    self.match_params(&declared.ty, &ty, &mut told);
                    for (param, ty) in told {
                        if !ty.params().iter().any(|name| name.starts_with(UNTOLD)) {
                            given.entry(param).or_insert(ty);
                        }
                    }
                }
                Err(error) => {
                    found = Err(error);
                    break;
                }
            }
        }
        self.unsettled_copies.truncate(copies);
        self.unsettled_types.truncate(untold);
        self.untold_kinds.truncate(kinds);
        found?;
        self.solve_bounds(&shape.types, &mut given);
        let mut types = Vec::new();
        for param in &shape.types {
            let Some(ty) = given.get(&param.name) else {
                return err(
                    span,
                    format!(
                        "can't tell which type '{}' is for this '{}', since no field it is given names one; write it, as in '{}<int> {{ … }}'",
                        param.name,
                        unqualified(name),
                        unqualified(name)
                    ),
                );
            };
            self.check_need("shape", name, param, ty, span)?;
            types.push(ty.clone());
        }
        Ok(types)
    }

    fn instance_fields(&mut self, source: &ShapeDef, types: Vec<Type>) -> Result<Vec<Field>> {
        let given: HashMap<String, Type> = source
            .types
            .iter()
            .map(|param| param.name.clone())
            .zip(types)
            .collect();
        let mut fields = Vec::new();
        for field in &source.fields {
            let outer = std::mem::replace(&mut self.type_params, source.types.clone());
            let read = self.resolve_type(&field.ty, field.ty_span, TypePlace::Field);
            self.type_params = outer;
            let ty = read?.map_params(&mut |param| given.get(param).cloned());
            let ty = self.resolve_type(&ty, field.ty_span, TypePlace::Field)?;
            fields.push(Field {
                ty,
                ..field.clone()
            });
        }
        Ok(fields)
    }

    /// Reconstructs user-written `Applied` types from internal monomorphized names for unification and diagnostics.
    fn unmade(&self, ty: &Type) -> Type {
        let boxed = |ty: &Type| Box::new(self.unmade(ty));
        match ty {
            Type::Named(name, region) => match self.made_of.get(name) {
                Some(made) => Type::Applied(Box::new(Applied {
                    name: made.name.clone(),
                    types: made
                        .types
                        .iter()
                        .map(|ty| {
                            let ty = self.unmade(ty);
                            match region {
                                Some(region) => {
                                    let ty = self.in_region(&ty, region);
                                    // Preserve enclosing region on regional instances so `FilterIter` over `SliceIter` keeps `@r`.
                                    match &ty {
                                        Type::Applied(applied)
                                            if applied.region.is_none()
                                                && (holds_text(&ty, &self.takes_region)
                                                    || holds_pointers(&ty, &self.regional)) =>
                                        {
                                            Type::Applied(Box::new(Applied {
                                                region: Some(region.clone()),
                                                ..(**applied).clone()
                                            }))
                                        }
                                        _ => ty,
                                    }
                                }
                                None => ty,
                            }
                        })
                        .collect(),
                    region: region.clone(),
                })),
                None => ty.clone(),
            },
            Type::Applied(applied) => Type::Applied(Box::new(Applied {
                name: applied.name.clone(),
                types: applied.types.iter().map(|ty| self.unmade(ty)).collect(),
                region: applied.region.clone(),
            })),
            Type::Ptr(inner, region) => Type::Ptr(boxed(inner), region.clone()),
            Type::Slice(inner, region) => Type::Slice(boxed(inner), region.clone()),
            Type::Map(key, value, region) => Type::Map(boxed(key), boxed(value), region.clone()),
            Type::Array(inner, count) => Type::Array(boxed(inner), *count),
            Type::Range(inner) => Type::Range(boxed(inner)),
            Type::Maybe(inner) => Type::Maybe(boxed(inner)),
            Type::Fail(inner) => Type::Fail(boxed(inner)),
            Type::Or(value, error) => Type::Or(boxed(value), boxed(error)),
            Type::Tuple(items) => Type::Tuple(items.iter().map(|ty| self.unmade(ty)).collect()),
            Type::Results(types) => Type::Results(types.iter().map(|ty| self.unmade(ty)).collect()),
            Type::Task(task) => Type::Task(Box::new(TaskType {
                params: task.params.iter().map(|ty| self.unmade(ty)).collect(),
                taken: task.taken.clone(),
                ret: self.unmade(&task.ret),
            })),
            Type::Closure(closure) => {
                let task = TaskType {
                    params: closure
                        .task
                        .params
                        .iter()
                        .map(|ty| self.unmade(ty))
                        .collect(),
                    taken: closure.task.taken.clone(),
                    ret: self.unmade(&closure.task.ret),
                };
                Type::Closure(Box::new(ClosureType {
                    task,
                    region: closure.region.clone(),
                    mode: closure.mode,
                }))
            }
            other => other.clone(),
        }
    }

    fn match_regions(&self, named: &Type, value: &Type, regions: &mut HashMap<String, String>) {
        unify_regions(&self.unmade(named), &self.unmade(value), regions);
    }

    fn match_params(&self, named: &Type, value: &Type, given: &mut HashMap<String, Type>) {
        unify_params(&self.unmade(named), &self.unmade(value), given);
    }

    fn settle_applications(&mut self, ty: &mut Type, at: Span) -> Result<()> {
        match ty {
            Type::Applied(applied) => {
                for ty in &mut applied.types {
                    self.settle_applications(ty, at)?;
                }
                if applied.types.iter().any(|ty| !ty.params().is_empty()) {
                    return Ok(());
                }
                let applied = applied.clone();
                let key = self.instance(&applied.name, &applied.types, at)?;
                // Concrete generic instances retain a region whenever their substituted fields hold regional values or text.
                let holds = self.takes_region.contains(&key)
                    || self.shapes.get(&key).is_some_and(|shape| {
                        shape.fields.iter().any(|field| {
                            holds_text(&field.ty, &self.takes_region)
                                || holds_pointers(&field.ty, &self.regional)
                        })
                    });
                // Preserve `@this` on method receivers so higher-order callbacks (e.g. `Indexed<T>@this`) keep their region.
                let region = applied.region.filter(|region| holds || region == THIS_WORD);
                *ty = Type::Named(key, region);
                Ok(())
            }
            Type::Ptr(inner, _)
            | Type::Slice(inner, _)
            | Type::Array(inner, _)
            | Type::Range(inner)
            | Type::Maybe(inner)
            | Type::Fail(inner) => self.settle_applications(inner, at),
            Type::Map(key, value, _) => {
                if let Some(why) = key_problem(key, &|_| false) {
                    return err(
                        at,
                        format!(
                            "a map's key is compared and hashed, so it is an int, a unit, a char, a bool, text, a pointer, or a tuple of them, not {}, which this use gives",
                            why
                        ),
                    );
                }
                self.settle_applications(key, at)?;
                self.settle_applications(value, at)
            }
            Type::Or(value, error) => {
                self.settle_applications(value, at)?;
                self.settle_applications(error, at)
            }
            Type::Tuple(types) | Type::Results(types) => types
                .iter_mut()
                .try_for_each(|ty| self.settle_applications(ty, at)),
            Type::Task(task) => {
                task.params
                    .iter_mut()
                    .try_for_each(|ty| self.settle_applications(ty, at))?;
                self.settle_applications(&mut task.ret, at)
            }
            Type::Closure(closure) => {
                closure
                    .task
                    .params
                    .iter_mut()
                    .try_for_each(|ty| self.settle_applications(ty, at))?;
                self.settle_applications(&mut closure.task.ret, at)
            }
            _ => Ok(()),
        }
    }

    /// Shared fields outlive all local regions and hold no handles, so they cannot contain local regions or `File`.
    fn check_shared_type(&self, ty: &Type, span: Span, field: &str) -> Result<()> {
        if holds_pointers(ty, &self.regional) {
            return err(
                span,
                format!(
                    "shared field '{}' can't hold a pointer or a slice, or a value holding one: those live in a region, and a shared field lives as long as the program, which no region does",
                    field
                ),
            );
        }
        if self.holds_file(ty) {
            return err(
                span,
                format!(
                    "shared field '{}' can't hold a 'File', which the region it is opened in closes, and a shared field lives as long as the program",
                    field
                ),
            );
        }
        Ok(())
    }

    fn holds_file(&self, ty: &Type) -> bool {
        self.holds_file_in(ty, &mut Vec::new())
    }

    fn holds_file_in<'t>(&'t self, ty: &'t Type, seen: &mut Vec<&'t str>) -> bool {
        match ty {
            Type::Named(name, _) if name == FILE_SHAPE => true,
            Type::Named(name, _) => {
                if seen.contains(&name.as_str()) {
                    return false;
                }
                seen.push(name);
                let fields = self
                    .shapes
                    .get(name)
                    .into_iter()
                    .flat_map(|shape| &shape.fields);
                let payloads = self
                    .kinds
                    .get(name)
                    .into_iter()
                    .flat_map(|kind| kind.variants.iter().flat_map(|variant| &variant.payload));
                fields
                    .chain(payloads)
                    .any(|field| self.holds_file_in(&field.ty, seen))
            }
            Type::Maybe(inner) | Type::Array(inner, _) => self.holds_file_in(inner, seen),
            Type::Or(value, error) => {
                self.holds_file_in(value, seen) || self.holds_file_in(error, seen)
            }
            Type::Tuple(items) => items.iter().any(|item| self.holds_file_in(item, seen)),
            _ => false,
        }
    }

    fn check_fields(&mut self, fields: &mut [Field]) -> Result<()> {
        let mut seen: HashMap<String, Span> = HashMap::new();
        for field in fields.iter_mut() {
            if let Some(at) = seen.get(&field.name) {
                return err(
                    field.span,
                    format!(
                        "field '{}' is already defined at {}:{}",
                        field.name, at.line, at.col
                    ),
                );
            }
            seen.insert(field.name.clone(), field.span);
            field.ty = self.resolve_type(&field.ty, field.ty_span, TypePlace::Field)?;
        }
        Ok(())
    }

    fn check_field_default(&mut self, value: &mut Expr, ty: &Type, field: &str) -> Result<()> {
        self.check_default_value(
            value,
            ty,
            &format!("field '{}'", field),
            "the shape takes, which is a different type in every value",
        )
    }

    fn check_default_value(
        &mut self,
        value: &mut Expr,
        ty: &Type,
        what: &str,
        which: &str,
    ) -> Result<()> {
        let at = value.span;
        // `none` is the only valid default for generic `maybe T` parameters.
        let fits_any = matches!(ty, Type::Maybe(_)) && matches!(value.kind, ExprKind::NoneLit);
        if !ty.params().is_empty() && !fits_any {
            return err(
                at,
                format!(
                    "{} is of a type {}, so it has no value to fall back on",
                    what, which
                ),
            );
        }
        if is_arithmetic(Some(value))
            && let Ok(folded) = self.fold_constant(value, &mut Vec::new())
        {
            *value = folded.literal(at);
        }
        let outer = self.in_default.replace(what.to_string());
        let checked = self.check_expr(value);
        self.in_default = outer;
        checked?;
        if !constant_value(value) {
            let tasks = if what.starts_with("parameter") {
                ", a task, a lambda that keeps nothing"
            } else {
                ""
            };
            return err(
                at,
                format!(
                    "the value {} falls back on must be one the compiler works out without running the program: a number, text, 'true', 'false', 'none', a variant{}, arithmetic on numbers and macros, or a tuple, an array, or a literal of those",
                    what, tasks
                ),
            );
        }
        self.coerce(value, ty)?;
        Ok(())
    }

    /// Parser attaches `@this` to every method receiver; strip it here for non-regional, non-generic types.
    fn settle_receiver(&self, task: &mut TaskDef) {
        if task.owner.as_ref().is_none_or(|owner| owner.shared) {
            return;
        }
        let Some(Type::Named(name, region)) = task.params.first_mut().map(|param| &mut param.ty)
        else {
            return;
        };
        if !self.takes_region.contains(name.as_str()) {
            *region = None;
        }
    }

    fn check_header(&mut self, t: &mut TaskDef) -> Result<()> {
        self.enter_type_params(&t.types);
        let checked = self
            .check_bounds_allow(&t.types)
            .and_then(|()| self.check_header_in_scope(t));
        self.type_params.clear();
        checked
    }

    fn check_header_in_scope(&mut self, t: &mut TaskDef) -> Result<()> {
        let mut marked: Option<&Field> = None;
        for param in t.params.iter().filter(|param| param.default_region) {
            if param.ty != Type::Region {
                return err(
                    param.span,
                    format!(
                        "only a region can be a task's default region, as in 'r: region {}'; '{}' is a parameter of type {}",
                        DEFAULT, param.name, param.ty
                    ),
                );
            }
            if let Some(first) = marked {
                return err(
                    param.span,
                    format!(
                        "this task already has a default region, '{}', at {}:{}",
                        first.name, first.span.line, first.span.col
                    ),
                );
            }
            marked = Some(param);
        }
        if t.name == "main" && !t.types.is_empty() {
            return err(
                t.span,
                "'main' is where the program starts, so it takes no types",
            );
        }
        let mut grouped = false;
        for param in &t.params {
            let Type::Group(group) = &param.ty else {
                continue;
            };
            if std::mem::replace(&mut grouped, true) {
                return err(
                    param.span,
                    format!(
                        "a task takes one group of values, and '{}: {}...' is a second; name the others one by one",
                        param.name, group
                    ),
                );
            }
            if param.passing != Passing::Copy {
                return err(
                    param.span,
                    format!(
                        "a group's values are read as copies the task can't change, so '{}' can't be '{}'; a task value given them takes them as places where it takes places, as 'next: (P...) -> R' given a task taking 'flex& n: int'",
                        param.name,
                        param.passing.word()
                    ),
                );
            }
        }
        let region_params: Vec<&str> = t
            .params
            .iter()
            .filter(|p| p.ty == Type::Region)
            .map(|p| p.name.as_str())
            .collect();
        let mut named: Vec<String> = region_params.iter().map(|name| name.to_string()).collect();
        if t.types.first().is_some_and(|param| param.name == THIS_TYPE) || self.is_default(t) {
            named.push(THIS_WORD.to_string());
        }
        if let Some(kept) = &t.kept {
            if let Some(param) = t.params.iter().find(|param| param.name == kept.region) {
                return err(
                    param.span,
                    format!(
                        "'{0}' is the region this lambda keeps what it uses in, '[@{0}]', so a parameter of its own is named otherwise",
                        kept.region
                    ),
                );
            }
            named.push(kept.region.clone());
        }
        let mut resolved = Vec::new();
        for param in &t.params {
            if param.ty == Type::Region {
                resolved.push(Type::Region);
                continue;
            }
            let ty = self.resolve_type(&param.ty, param.ty_span, TypePlace::Header)?;
            // Mutable-capture closures cannot be copied, so they require `flex&`.
            // A shape holding one may also be given to read, 'fixed& c', since nothing calls its lambda there.
            let place_ok = param.passing == Passing::FlexRef
                || (param.passing == Passing::FixedRef && !held_lambda(&ty));
            if held_value(&ty, &self.held_types) && !place_ok && param.name != THIS {
                return err(
                    param.span,
                    format!(
                        "'{0}' is {2}, which changes what it keeps and is never copied, so it is given as a place, 'flex& {0}: {1}'",
                        param.name,
                        ty,
                        held_phrase(&ty)
                    ),
                );
            }
            for region in ty.regions() {
                if let Some(other) = t
                    .params
                    .iter()
                    .find(|p| p.name == region && p.ty != Type::Region)
                {
                    return err(
                        self.place(param.ty_span, &format!("@{}", region)),
                        format!("'{}' is a parameter, not a region", other.name),
                    );
                }
                if !named.iter().any(|n| n == region) {
                    named.push(region.to_string());
                }
            }
            resolved.push(ty);
        }
        let several = matches!(t.ret, Type::Results(_));
        let written: Vec<(Type, Span)> = t
            .ret
            .results()
            .iter()
            .cloned()
            .zip((0..).map(|i| t.result_span(i)))
            .collect();
        let mut results = Vec::new();
        for (i, (result, span)) in written.into_iter().enumerate() {
            if result == Type::Region {
                return err(
                    span,
                    "a task can't send a region; regions are only parameters, as in 'task build(r: region)'",
                );
            }
            if result == Type::Nothing {
                return err(
                    span,
                    "'nothing' is only allowed as a task's whole return type, so it can't be one of several results",
                );
            }
            let ret = self.resolve_type(&result, span, TypePlace::Header)?;
            if let Some(region) = ret
                .regions()
                .into_iter()
                .find(|r| !named.iter().any(|n| n == r))
            {
                let at = self.place(span, &format!("@{}", region));
                if t.params.iter().any(|p| p.name == region) {
                    return err(at, format!("'{}' is a parameter, not a region", region));
                }
                let which = match t.results.get(i).and_then(|r| r.name.as_ref()) {
                    Some((name, _)) => format!("result '{}'", name),
                    None if several => format!("result {}", i + 1),
                    None => "the result".to_string(),
                };
                if region == THIS_WORD && t.owner.as_ref().is_some_and(|owner| owner.shared) {
                    return err(
                        at,
                        format!(
                            "{} lives in '@{}', the region of the value a method is called on, and a shared method has none; take a region, as in 'r: region', and name it",
                            which, THIS_WORD
                        ),
                    );
                }
                if is_lambda(&t.name) {
                    return err(
                        at,
                        format!(
                            "{1} lives in region '{0}', which the lambda isn't given; take it as a parameter, as in '({0}: region) -> …'",
                            region, which
                        ),
                    );
                }
                return err(
                    at,
                    format!(
                        "{1} lives in region '{0}', which the task isn't given; take it as a parameter, as in '{0}: region'",
                        region, which
                    ),
                );
            }
            results.push(ret);
        }
        t.ret = match results.len() {
            0 => Type::Nothing,
            1 => results.into_iter().next().unwrap_or(Type::Nothing),
            _ => Type::Results(results),
        };
        if !sends_value(&t.ret)
            && let Some((name, at)) = t.result_names().next()
        {
            return err(
                *at,
                format!(
                    "a '{}' task succeeds by reaching its end or a bare '<-', so '{}' has no value to name",
                    t.ret, name
                ),
            );
        }
        for (param, ty) in t.params.iter_mut().zip(resolved) {
            param.ty = ty;
        }
        // Hide internal wrapper chains generated by `str` layers from public signatures.
        if t.owner.as_ref().is_some_and(|owner| !owner.shared && owner.name == STR) && !t.name.contains(LAYER) {
            check_str_method(t)?;
        }
        if t.owner.as_ref().is_some_and(|owner| !owner.shared && owner.name == JSON) && !t.name.contains(LAYER) {
            check_json_method(t)?;
        }
        let params = t
            .params
            .iter()
            .map(|p| (p.name.clone(), p.ty.clone()))
            .collect();
        self.tasks.insert(
            t.name.clone(),
            TaskInfo {
                types: t.types.clone(),
                params,
                passing: t.params.iter().map(|p| p.passing).collect(),
                ret: t.ret.clone(),
                owner: t.owner.clone(),
            },
        );
        Ok(())
    }

    fn enter_type_params(&mut self, types: &[TypeParam]) {
        self.type_params = types.to_vec();
    }

    fn type_param(&self, name: &str) -> Option<&TypeParam> {
        let name = name.split(GROUP_ITEM).next().unwrap_or(name);
        self.type_params.iter().find(|param| param.name == name)
    }

    /// Validates written regions: `Field`/`New` forbid regions; `Body` requires visible regions; drops region on value types.
    fn resolve_type(&mut self, ty: &Type, span: Span, place: TypePlace) -> Result<Type> {
        // Pattern type params resolve against follower substitutions, keeping receiver's own generic names intact.
        let given;
        let ty = match self.stand_ins.as_slice() {
            [] => ty,
            _ if self.this_type.as_ref() == Some(ty) => ty,
            stand_ins => {
                given = ty.replace_names(&|name| {
                    stand_ins
                        .iter()
                        .find(|(param, _)| param == name)
                        .map(|(_, ty)| ty.clone())
                });
                &given
            }
        };
        let followed;
        let ty = match &self.this_type {
            Some(this) if mentions_name(ty, THIS_TYPE) => {
                followed = put_this(ty, this);
                &followed
            }
            _ => ty,
        };
        self.check_type(ty, span)?;
        if matches!(place, TypePlace::Body | TypePlace::New) {
            self.check_size(ty, span)?;
        }
        self.resolve_regions(ty, span, place, None)
    }

    fn resolve_task_type(
        &mut self,
        task: &TaskType,
        span: Span,
        kept: Option<&str>,
    ) -> Result<TaskType> {
        let params = task
            .params
            .iter()
            .map(|param| self.resolve_regions(param, span, TypePlace::Header, None))
            .collect::<Result<Vec<_>>>()?;
        let ret = self.resolve_regions(&task.ret, span, TypePlace::Header, None)?;
        let mut regions: Vec<&str> = Vec::new();
        for (i, _) in task.params.iter().enumerate() {
            let Some(region) = task.region(i) else {
                continue;
            };
            if regions.contains(&region) {
                return err(
                    self.place(span, &format!("@{}", region)),
                    format!(
                        "this task's type takes region '{}' twice; each region it takes has a name of its own",
                        region
                    ),
                );
            }
            regions.push(region);
        }
        let named: Vec<&str> = params
            .iter()
            .flat_map(Type::regions)
            .chain(regions.iter().copied())
            .chain(kept)
            .collect();
        if let Some(region) = ret
            .regions()
            .into_iter()
            .find(|region| !named.contains(region))
        {
            return err(
                self.place(span, &format!("@{}", region)),
                format!(
                    "what this task sends lives in region '{}', which none of its parameters names, so no call could say which region that is",
                    region
                ),
            );
        }
        let taken = task
            .taken
            .iter()
            .zip(&params)
            .map(|(how, param)| self.taken_for(how, param))
            .collect();
        Ok(TaskType { params, taken, ret })
    }

    /// Collapses `flex`/`bind` on scalar/whole types to `Value`, and `bind&` on non-content types to `FixedRef`.
    fn taken_for(&self, how: &Taken, ty: &Type) -> Taken {
        match how {
            Taken::Flex | Taken::Bind if !self.twofold(ty) => Taken::Value,
            Taken::Place(Passing::BindRef) if !self.bind_has_contents(ty) => {
                Taken::Place(Passing::FixedRef)
            }
            how => how.clone(),
        }
    }

    fn resolve_regions(
        &mut self,
        ty: &Type,
        span: Span,
        place: TypePlace,
        inside: Option<&str>,
    ) -> Result<Type> {
        let given = |region: &Option<String>| -> Result<()> {
            match (place, region) {
                (TypePlace::Field, Some(region)) => err(
                    self.place(span, &format!("@{}", region)),
                    format!(
                        "a field lives in the region of the value holding it, so its type names no region; remove '@{}'",
                        region
                    ),
                ),
                (TypePlace::Shared, Some(region)) => err(
                    self.place(span, &format!("@{}", region)),
                    format!(
                        "a shared field lives as long as the program, which no region does, so its type names none; remove '@{}'",
                        region
                    ),
                ),
                (TypePlace::New, Some(region))
                    if region == THIS_WORD && self.in_pattern_default =>
                {
                    Ok(())
                }
                (TypePlace::New, Some(region)) => err(
                    self.place(span, &format!("@{}", region)),
                    format!(
                        "the value 'new' makes lives in the region it allocates in, so its type names no region; remove '@{}'",
                        region
                    ),
                ),
                (TypePlace::Body, Some(region)) => {
                    self.visible_region(region, self.place(span, &format!("@{}", region)), false)
                }
                _ => Ok(()),
            }
        };
        let needs_region = matches!(place, TypePlace::Header | TypePlace::Body);
        match ty {
            Type::Applied(applied) => {
                let applied = applied.clone();
                self.resolve_applied(&applied, span, place, inside)
            }
            Type::Ptr(inner, region) => {
                given(region)?;
                if needs_region && region.is_none() {
                    return err(
                        span,
                        format!(
                            "a pointer lives in a region, so its type names one, as in '{}@r'",
                            ty
                        ),
                    );
                }
                if let (Some(region), Some(inside)) = (region, inside)
                    && region != inside
                {
                    return err(
                        self.place(span, &format!("@{}", region)),
                        format!(
                            "everything a value in region '{0}' holds is in '{0}', its pointers too; write '@{0}' for '@{1}'",
                            inside, region
                        ),
                    );
                }
                let inner = self.resolve_regions(inner, span, place, region.as_deref())?;
                Ok(Type::Ptr(Box::new(inner), region.clone()))
            }
            Type::Slice(inner, region) => {
                given(region)?;
                if needs_region && region.is_none() {
                    return err(
                        span,
                        format!(
                            "a slice lives in a region, so its type names one, as in '{}@r'",
                            ty
                        ),
                    );
                }
                if let (Some(region), Some(inside)) = (region, inside)
                    && region != inside
                {
                    return err(
                        self.place(span, &format!("@{}", region)),
                        format!(
                            "everything a value in region '{0}' holds is in '{0}', its slices too; write '@{0}' for '@{1}'",
                            inside, region
                        ),
                    );
                }
                let inner = self.resolve_regions(inner, span, place, region.as_deref())?;
                Ok(Type::Slice(Box::new(inner), region.clone()))
            }
            Type::Map(key, value, region) => {
                given(region)?;
                if needs_region && region.is_none() {
                    return err(
                        span,
                        format!(
                            "a map lives in a region, so its type names one, as in '{}@r'",
                            ty
                        ),
                    );
                }
                if let (Some(region), Some(inside)) = (region, inside)
                    && region != inside
                {
                    return err(
                        self.place(span, &format!("@{}", region)),
                        format!(
                            "everything a value in region '{0}' holds is in '{0}', its maps too; write '@{0}' for '@{1}'",
                            inside, region
                        ),
                    );
                }
                let key = self.resolve_regions(key, span, place, region.as_deref())?;
                let value = self.resolve_regions(value, span, place, region.as_deref())?;
                Ok(Type::Map(Box::new(key), Box::new(value), region.clone()))
            }
            Type::Array(inner, count) => Ok(Type::Array(
                Box::new(self.resolve_regions(inner, span, place, inside)?),
                *count,
            )),
            Type::Text(region) => {
                given(region)?;
                // Pattern defaults may accept follower `text@this` inside another `@r`, validated at call sites.
                if let (Some(region), Some(inside)) = (region, inside)
                    && region != inside
                    && !(region == THIS_WORD && self.in_pattern_default)
                {
                    return err(
                        self.place(span, &format!("@{}", region)),
                        format!(
                            "everything a value in region '{0}' holds is in '{0}', its text too; remove '@{1}'",
                            inside, region
                        ),
                    );
                }
                Ok(Type::Text(
                    region.clone().or_else(|| inside.map(str::to_string)),
                ))
            }
            Type::Named(name, region) if self.type_param(name).is_some() => {
                // Regions on bare `T` belong to whatever type fills `T`; enclosing containers (`[T]@r`) apply their own region.
                if let Some(region) = region.as_deref().filter(|region| inside != Some(region)) {
                    return err(
                        self.place(span, &format!("@{}", region)),
                        format!(
                            "'{0}' is a type this task takes, and what a '{0}' holds is in the region of the type given for it, so it names none; remove '@{1}'",
                            name, region
                        ),
                    );
                }
                Ok(Type::Param(name.clone()))
            }
            Type::Named(name, region) => {
                if let Some((word, params, _)) = self
                    .takes_types(name)
                    .filter(|(_, params, _)| !params.is_empty())
                {
                    let names: Vec<&str> = params.iter().map(|param| param.name.as_str()).collect();
                    return err(
                        self.place(span, name),
                        format!(
                            "{} '{}' takes {}, so name {}, as in '{}<{}>'",
                            word,
                            unqualified(name),
                            count(params.len(), "type"),
                            if params.len() == 1 {
                                "it"
                            } else {
                                "all of them"
                            },
                            unqualified(name),
                            names.join(", ")
                        ),
                    );
                }
                given(region)?;
                if !self.regional.contains(name) {
                    if self.takes_region.contains(name) {
                        if let (Some(region), Some(inside)) = (region, inside)
                            && region != inside
                        {
                            return err(
                                self.place(span, &format!("@{}", region)),
                                format!(
                                    "everything a value in region '{0}' holds is in '{0}', '{2}' too; remove '@{1}'",
                                    inside, region, name
                                ),
                            );
                        }
                        return Ok(Type::Named(
                            name.clone(),
                            region.clone().or_else(|| inside.map(str::to_string)),
                        ));
                    }
                    // Pattern defaults allow `@this` on value-less generics (`MapIter<this, T, R>@this`) before concrete followers.
                    if region.as_deref() == Some(THIS_WORD) && self.in_pattern_default {
                        return Ok(Type::named(name));
                    }
                    if let Some(region) = region
                        && inside != Some(region.as_str())
                    {
                        return err(
                            self.place(span, &format!("@{}", region)),
                            format!(
                                "'{}' holds no pointers or text, so it lives in no region; remove '@{}'",
                                name, region
                            ),
                        );
                    }
                    return Ok(Type::named(name));
                }
                if needs_region && region.is_none() {
                    return err(
                        self.place(span, name),
                        format!(
                            "'{0}' holds pointers, so it lives in a region; name it, as in '{0}@r'",
                            name
                        ),
                    );
                }
                Ok(ty.clone())
            }
            // Do not rename `this` in pattern defaults: it binds to the caller's receiver region per call site.
            Type::Task(task) => {
                let task = self.resolve_task_type(task, span, None)?;
                let task = match self.in_pattern_default {
                    true => task.normalized_beside(Some(THIS_WORD)),
                    false => task.normalized(),
                };
                Ok(Type::Task(Box::new(task)))
            }
            Type::Closure(closure) => {
                // `[@this]` field closures live in the owner's region; safe to copy because owner copies share region.
                // A `[bind @this]` one changes only what copies share, so it is copied too; a `[flex @this]` one
                // makes the value holding it held, never copied (see `held_types`).
                if place == TypePlace::Field && closure.region == THIS_WORD {
                    let task = self.resolve_task_type(&closure.task, span, Some(THIS_WORD))?;
                    return Ok(Type::Closure(Box::new(
                        ClosureType {
                            task,
                            region: THIS_WORD.to_string(),
                            mode: closure.mode,
                        }
                        .normalized(),
                    )));
                }
                if place == TypePlace::Shared {
                    return err(
                        self.place(span, &format!("@{}", closure.region)),
                        format!(
                            "a shared field lives in no value, so it can't hold a lambda that keeps what it uses, '{}'; hold a task value, '{}'",
                            ty,
                            Type::Task(Box::new(closure.task.clone()))
                        ),
                    );
                }
                if place == TypePlace::Field {
                    return err(
                        self.place(span, &format!("@{}", closure.region)),
                        format!(
                            "a field's lambda keeps what it uses in the region of the value holding it, so it names that one, '[@{}]', as in 'f: [@{}]{}'",
                            THIS_WORD,
                            THIS_WORD,
                            Type::Task(Box::new(closure.task.clone()))
                        ),
                    );
                }
                if place != TypePlace::New {
                    given(&Some(closure.region.clone()))?;
                }
                if let Some(inside) = inside.filter(|inside| *inside != closure.region) {
                    return err(
                        self.place(span, &format!("@{}", closure.region)),
                        format!(
                            "everything a value in region '{0}' holds is in '{0}', what a lambda keeps too; write '@{0}' for '@{1}'",
                            inside, closure.region
                        ),
                    );
                }
                let task = self.resolve_task_type(&closure.task, span, Some(&closure.region))?;
                Ok(Type::Closure(Box::new(
                    ClosureType {
                        task,
                        region: closure.region.clone(),
                        mode: closure.mode,
                    }
                    .normalized(),
                )))
            }
            Type::Maybe(inner) => Ok(Type::Maybe(Box::new(
                self.resolve_regions(inner, span, place, inside)?,
            ))),
            Type::Tuple(items) => Ok(Type::Tuple(
                items
                    .iter()
                    .map(|item| self.resolve_regions(item, span, place, inside))
                    .collect::<Result<_>>()?,
            )),
            Type::Or(value, error) => Ok(Type::Or(
                Box::new(self.resolve_regions(value, span, place, inside)?),
                Box::new(self.resolve_regions(error, span, place, inside)?),
            )),
            other => Ok(other.clone()),
        }
    }

    fn visible_region(&self, name: &str, span: Span, allocating: bool) -> Result<()> {
        match self.lookup(name) {
            Some(info) if info.ty == Type::Region => {
                if allocating && !info.allocates {
                    if name == THIS_WORD && self.called_on_a_value() {
                        return err(span, self.cannot_allocate_in_this("allocate where the value is kept, and give the method what you made"));
                    }
                    if self.current_lambda.is_some() {
                        return err(
                            span,
                            format!(
                                "this lambda can't allocate in '{0}', which it only names in its types; take it as a parameter, '{0}: region'",
                                name
                            ),
                        );
                    }
                    return err(
                        span,
                        format!(
                            "this task can't allocate in '{0}', which it only names in its types; take it as a parameter, '{0}: region'",
                            name
                        ),
                    );
                }
                Ok(())
            }
            Some(_) => err(span, format!("'{}' is a variable, not a region", name)),
            None if self
                .current_lambda
                .as_ref()
                .and_then(|lambda| self.lambda_outer.get(lambda))
                .is_some_and(|outer| outer.contains(name)) =>
            {
                if let Some(kept) = self
                    .current_lambda
                    .as_ref()
                    .and_then(|lambda| self.kept_lambdas.get(lambda))
                {
                    return err(
                        span,
                        format!(
                            "region '{0}' belongs to the code around this lambda, which keeps what it uses in '{1}' and sees no other region of it; use '{1}', declare a region of its own inside it, or take one as a parameter, '{0}: region'",
                            name, kept.region
                        ),
                    );
                }
                err(
                    span,
                    format!(
                        "region '{0}' belongs to the code around this lambda, and a lambda takes nothing from it; declare a region of its own inside it, or take one as a parameter, '{0}: region'; a lambda that keeps what it uses names the region it keeps it in, '[@{0}](…)'",
                        name
                    ),
                )
            }
            None => err(
                span,
                format!("unknown region '{0}'; declare it with 'region {0}'", name),
            ),
        }
    }

    fn in_region(&self, ty: &Type, region: &str) -> Type {
        in_region(ty, region, &self.takes_region)
    }

    fn check_type(&self, ty: &Type, span: Span) -> Result<()> {
        if holds_held(ty, &self.held_types) {
            return err(
                span,
                format!(
                    "{} holds a '[flex @r]' lambda, or a shape holding one, inside another value, but such a lambda changes what it keeps and is never copied, so it is held alone, in a 'flex' variable",
                    ty
                ),
            );
        }
        match ty {
            Type::Nothing => err(
                self.place(span, "nothing"),
                "'nothing' is only allowed as a return type",
            ),
            Type::Closure(closure) => {
                self.check_type(&Type::Task(Box::new(closure.task.clone())), span)
            }
            Type::Region => err(
                self.place(span, "region"),
                "'region' is only the type of a task's parameter, as in 'task build(r: region)'",
            ),
            Type::Results(_) => err(
                span,
                "several types, separated by commas, are only a task's results",
            ),
            Type::Ptr(inner, _) => self.check_type(inner, span),
            Type::Map(key, value, _) => {
                if let Some(why) = key_problem(key, &|name| self.type_param(name).is_some()) {
                    return err(
                        span,
                        format!(
                            "a map's key is compared and hashed, so it is an int, a unit, a char, a bool, text, a pointer, or a tuple of them, not {}",
                            why
                        ),
                    );
                }
                if **value == Type::Nothing {
                    return err(
                        self.place(span, "nothing"),
                        "a map can't hold 'nothing', which has no value",
                    );
                }
                self.check_type(key, span)?;
                self.check_type(value, span)
            }
            Type::Array(inner, _) | Type::Slice(inner, _) => match inner.as_ref() {
                Type::Nothing => {
                    let what = if matches!(ty, Type::Array(..)) {
                        "an array"
                    } else {
                        "a slice"
                    };
                    err(
                        self.place(span, "nothing"),
                        format!("{} can't hold 'nothing', which has no value", what),
                    )
                }
                _ => self.check_type(inner, span),
            },
            Type::Maybe(inner) => match inner.as_ref() {
                Type::Maybe(_) => err(span, "a maybe can't hold another maybe"),
                Type::Nothing => err(
                    self.place(span, "nothing"),
                    "a maybe can't hold 'nothing', which has no value",
                ),
                _ => self.check_type(inner, span),
            },
            Type::Or(value, error) => {
                // Error operator `~` does not associate/nest; flat `T ~ E` only.
                if matches!(value.as_ref(), Type::Or(..)) || matches!(error.as_ref(), Type::Or(..))
                {
                    return err(
                        self.place(span, "~"),
                        "a type has one error type: '~' can't appear twice",
                    );
                }
                if **value != Type::Nothing {
                    self.check_type(value, span)?;
                }
                match error.as_ref() {
                    Type::Nothing => {
                        return err(self.place(span, "~"), "the error type can't be 'nothing'");
                    }
                    Type::Maybe(_) => {
                        return err(self.place(span, "~"), "the error type can't be a maybe");
                    }
                    _ => self.check_type(error, span)?,
                }
                // Identical non-regional types on both sides would make literal values ambiguous, except regional `text`.
                if value == error
                    || (value.without_regions() == error.without_regions()
                        && self.fits_any_region(value))
                {
                    return err(
                        self.place(span, "~"),
                        format!(
                            "the error type must differ from the value type, as in '{} ~ ParseError'",
                            value
                        ),
                    );
                }
                Ok(())
            }
            Type::Tuple(items) => {
                for item in items {
                    self.check_type(item, span)?;
                    if let Some(what) = self.changeable_item(item) {
                        return err(
                            span,
                            format!("a tuple's items never change, so it can't hold {}", what),
                        );
                    }
                }
                Ok(())
            }
            Type::Task(task) => {
                for (i, param) in task.params.iter().enumerate() {
                    match param {
                        _ if task.region(i).is_some() => {}
                        Type::Nothing => {
                            return err(
                                self.place(span, "nothing"),
                                "a task takes no 'nothing', which has no value; '()' takes no values, as in '() -> int'",
                            );
                        }
                        Type::Region => {
                            return err(
                                self.place(span, "region"),
                                "a task's type writes a region it takes as '@r', named so that what it sends can live there, as in '(@r, int) -> [int]@r'",
                            );
                        }
                        _ => self.check_type(param, span)?,
                    }
                }
                match &task.ret {
                    Type::Nothing => Ok(()),
                    Type::Region => err(
                        self.place(span, "region"),
                        "a task can't send a region; regions are only parameters, as in 'task build(r: region)'",
                    ),
                    Type::Or(value, _) if **value == Type::Nothing => {
                        self.check_type(&task.ret, span)
                    }
                    ret => self.check_type(ret, span),
                }
            }
            Type::Group(name) => match self.type_param(name) {
                Some(param) if param.group => Ok(()),
                Some(_) => err(
                    self.place(span, name),
                    format!(
                        "'{0}' is one type, not a group; a task takes a group of types as '<{0}...>'",
                        name
                    ),
                ),
                None => err(
                    self.place(span, name),
                    format!(
                        "unknown group of types '{0}'; a task takes one as '<{0}...>'",
                        name
                    ),
                ),
            },
            Type::Named(name, _)
                if self.group_turns.iter().any(|(group, _)| group == name)
                    && self.type_param(name).is_some_and(|param| param.group) =>
            {
                Ok(())
            }
            Type::Named(name, _) if self.type_param(name).is_some_and(|param| param.group) => err(
                self.place(span, name),
                format!(
                    "'{0}' is a group of types, so a header writes it '{0}...': a parameter's whole type, as in 'args: {0}...', or in a task's type, as in '({0}...) -> R' or '(int, {0}...) -> R'; '{0}' alone is one value's type, written only inside 'each v in args', as the type 'v' has",
                    name
                ),
            ),
            Type::Named(name, _) if self.type_param(name).is_some() => Ok(()),
            Type::Applied(applied) => applied
                .types
                .iter()
                .try_for_each(|ty| self.check_type(ty, span)),
            Type::Named(name, _)
                if !self.sees(name)
                    || (!self.shapes.contains_key(name) && !self.kinds.contains_key(name)) =>
            {
                match self.variants.get(name).filter(|_| self.sees(name)) {
                    Some(info) => err(
                        self.place(span, name),
                        format!(
                            "'{}' is a variant, not a type; its type is its kind, '{}'",
                            info.variant.tag, info.kind
                        ),
                    ),
                    None => err(
                        self.place(span, name),
                        format!("unknown type '{}'{}", name, self.elsewhere(name)),
                    ),
                }
            }
            _ => Ok(()),
        }
    }

    fn changeable_item(&self, ty: &Type) -> Option<String> {
        match ty {
            Type::Applied(applied) => {
                let fields = self.applied_parts(applied)?;
                let found = fields.iter().find_map(|ty| self.changeable_item(ty))?;
                Some(format!("'{}', which holds {}", ty, found))
            }
            // Generic params can hold mutable state unless constrained `frozen`.
            Type::Param(name) if !self.allows(Need::Frozen, ty) => Some(format!(
                "'{}', which {}",
                name,
                self.why_not(Need::Frozen, ty)
            )),
            Type::Group(name) if !self.allows(Need::Frozen, ty) => Some(format!(
                "'{}...', which {}",
                name,
                self.why_not(Need::Frozen, ty)
            )),
            Type::Ptr(..) => Some(format!("a pointer ({}), whose value can change", ty)),
            Type::Slice(..) => Some(format!("a slice ({}), whose items can change", ty)),
            Type::Map(..) => Some(format!("a map ({}), whose values can change", ty)),
            Type::Array(..) => Some(format!("an array ({})", ty)),
            Type::Nothing => Some("'nothing', which has no value".to_string()),
            Type::Named(name, _) if self.changeable.contains(name) => Some(format!(
                "'{}', which holds a pointer, a slice, or an array",
                unqualified(name)
            )),
            Type::Maybe(inner) => self.changeable_item(inner),
            Type::Or(value, error) => self
                .changeable_item(value)
                .filter(|_| **value != Type::Nothing)
                .or_else(|| self.changeable_item(error)),
            Type::Tuple(items) => items.iter().find_map(|item| self.changeable_item(item)),
            _ => None,
        }
    }

    fn fits_any_region(&self, ty: &Type) -> bool {
        match ty {
            Type::Text(_) => true,
            Type::Named(name, _) => self.takes_region.contains(name),
            Type::Maybe(inner) | Type::Array(inner, _) => self.fits_any_region(inner),
            Type::Or(value, error) => self.fits_any_region(value) || self.fits_any_region(error),
            Type::Tuple(items) => items.iter().any(|item| self.fits_any_region(item)),
            _ => false,
        }
    }

    /// Iterative cycle check using an explicit stack to prevent compiler overflow on deep type chains.
    fn check_value_cycle(
        &self,
        root: &str,
        acyclic: &mut HashSet<String>,
        order: &mut Vec<String>,
    ) -> std::result::Result<(), (Error, Vec<String>)> {
        if acyclic.contains(root) {
            return Ok(());
        }
        type Entered<'a> = (&'a str, Vec<(&'a str, Span)>, usize);
        let mut path: Vec<Entered> = vec![(root, self.contained_types(root), 0)];
        let mut on_path: HashSet<&str> = HashSet::from([root]);
        while let Some((_, targets, next)) = path.last_mut() {
            let Some(&(target, span)) = targets.get(*next) else {
                if let Some((name, _, _)) = path.pop() {
                    on_path.remove(name);
                    acyclic.insert(name.to_string());
                    order.push(name.to_string());
                }
                continue;
            };
            *next += 1;
            if on_path.contains(target) {
                let start = path
                    .iter()
                    .position(|(name, _, _)| *name == target)
                    .unwrap_or_default();
                let chain: Vec<&str> = path
                    .iter()
                    .skip(start)
                    .map(|(name, _, _)| *name)
                    .chain([target])
                    .collect();
                let takes = self.shapes.get(target).map_or(String::new(), |shape| {
                    match shape.types.is_empty() {
                        true => String::new(),
                        false => format!(
                            "<{}>",
                            shape
                                .types
                                .iter()
                                .map(|param| param.name.clone())
                                .collect::<Vec<_>>()
                                .join(", ")
                        ),
                    }
                });
                let error = Error::at(
                    span,
                    format!(
                        "'{}' contains itself by value ({}); use a pointer such as 'maybe ^{}{}'",
                        target,
                        chain.join(" -> "),
                        target,
                        takes
                    ),
                );
                // Report cycle once at closing edge and skip re-walking cycle members.
                return Err((error, chain.into_iter().map(str::to_string).collect()));
            }
            if !acyclic.contains(target) {
                on_path.insert(target);
                path.push((target, self.contained_types(target), 0));
            }
        }
        Ok(())
    }

    fn contained_types(&self, name: &str) -> Vec<(&str, Span)> {
        let fields: Vec<&Field> = match (self.shapes.get(name), self.kinds.get(name)) {
            (Some(shape), _) => shape.fields.iter().collect(),
            (None, Some(kind)) => kind.variants.iter().flat_map(|v| &v.payload).collect(),
            (None, None) => Vec::new(),
        };
        fields
            .into_iter()
            .flat_map(|field| {
                contained_by_value(&field.ty)
                    .into_iter()
                    .map(|target| (target, field.ty_span))
            })
            .collect()
    }

    /// Worklist reachability from base/pointer-free variants to reject uninhabitable self-referential shapes/kinds.
    fn check_constructible(&mut self, items: &[Item]) {
        let mut types: Vec<(&str, Vec<Vec<Type>>)> = Vec::new();
        for item in items {
            match item {
                Item::Shape(s) => types.push((
                    s.name.as_str(),
                    vec![s.fields.iter().map(|f| f.ty.clone()).collect()],
                )),
                Item::Kind(k) => types.push((
                    k.name.as_str(),
                    k.variants
                        .iter()
                        .map(|v| v.payload.iter().map(|f| f.ty.clone()).collect())
                        .collect(),
                )),
                Item::Task(_) | Item::Macro(_) | Item::GlobalRegion(_) => {}
            }
        }
        for made in self.made_of.keys() {
            if let Some(shape) = self.shapes.get(made) {
                types.push((
                    made.as_str(),
                    vec![shape.fields.iter().map(|f| f.ty.clone()).collect()],
                ));
            } else if let Some(kind) = self.kinds.get(made) {
                types.push((
                    made.as_str(),
                    kind.variants
                        .iter()
                        .map(|v| v.payload.iter().map(|f| f.ty.clone()).collect())
                        .collect(),
                ));
            }
        }
        let mut users: HashMap<&str, Vec<usize>> = HashMap::new();
        for (i, (_, ways)) in types.iter().enumerate() {
            for ty in ways.iter().flatten() {
                for name in named_types(ty) {
                    users.entry(name).or_default().push(i);
                }
            }
        }
        let mut can: HashSet<&str> = BUILTIN_KIND_NAMES
            .iter()
            .copied()
            .filter(|name| builtin_kind_of(name).is_none())
            .collect();
        let mut pending: Vec<usize> = (0..types.len()).collect();
        while let Some(i) = pending.pop() {
            let Some((name, ways)) = types.get(i) else {
                continue;
            };
            if ways
                .iter()
                .any(|holds| holds.iter().all(|ty| constructible(ty, &can)))
                && can.insert(name)
            {
                pending.extend(users.get(name).into_iter().flatten().copied());
            }
        }
        let mut found = Vec::new();
        for item in items {
            if self.broken.contains(item.name()) {
                continue;
            }
            match item {
                Item::Shape(s) if !can.contains(s.name.as_str()) => {
                    if let Some(field) = s.fields.iter().find(|f| !constructible(&f.ty, &can)) {
                        found.push((
                            s.name.clone(),
                            Error::at(
                                field.ty_span,
                                format!(
                                    "'{}' can never be created: field '{}' needs an existing {}; make it 'maybe {}'",
                                    s.name, field.name, field.ty, field.ty
                                ),
                            ),
                        ));
                    }
                }
                Item::Kind(k) if !can.contains(k.name.as_str()) => {
                    found.push((
                        k.name.clone(),
                        Error::at(
                            k.span,
                            format!("'{}' can never be created: every variant needs an existing value that can't be created either; use 'maybe' for a value that can be missing", k.name),
                        ),
                    ));
                }
                _ => {}
            }
        }
        for (name, error) in found {
            self.record(error);
            self.broken.insert(name);
        }
    }

    fn check_task(&mut self, task: &mut TaskDef) -> Result<()> {
        self.enter_type_params(&task.types);
        let unsettled = self.broken.contains(&task.name);
        let known = |ty: &Type| if unsettled { Type::Unknown } else { ty.clone() };
        if task.shortcut {
            for param in &task.params {
                if param.ty.unknown() {
                    return err(
                        param.span,
                        format!(
                            "cannot infer parameter type for '{}' in shortcut lambda; specify types with a full lambda, as in '(x: int) -> int <- ... fi', or give the variable a type",
                            param.name
                        ),
                    );
                }
            }
        }
        for param in &task.params {
            self.check_size(&param.ty, param.ty_span)?;
        }
        for (i, result) in task.ret.results().iter().enumerate() {
            self.check_size(result, task.result_span(i))?;
        }
        self.current_ret = Some(known(&task.ret));
        self.current_lambda = is_lambda(&task.name).then(|| task.name.clone());
        self.current_task = task.name.clone();
        self.param_index = task
            .params
            .iter()
            .enumerate()
            .map(|(i, param)| (param.name.clone(), i))
            .collect();
        self.current_method = task.owner.clone();
        self.this_type = method_this(task);
        self.in_pattern_default = self.is_default(task);
        self.stand_ins = self
            .stand_ins_of
            .get(&task.name)
            .cloned()
            .unwrap_or_default();
        self.current_owner = task
            .owner
            .as_ref()
            .filter(|owner| owner.alters)
            .and(task.params.first())
            .and_then(|this| self.owner_of(&this.ty));
        self.current_type = task.owner_type().map(str::to_string);
        self.current_shape = match &task.owner {
            Some(owner) if owner.shared => task
                .owner_type()
                .filter(|ty| self.shapes.contains_key(*ty))
                .map(str::to_string),
            Some(_) => task.params.first().and_then(|this| self.owner_of(&this.ty)),
            None => None,
        };
        // Parameters share function-body scope to match C local scoping.
        self.scopes = vec![Scope::default()];
        self.loops.clear();
        self.loop_scopes.clear();
        self.moved.clear();
        self.loop_name = None;
        self.stepping = None;
        if task.kept.is_some() {
            match self.kept_scope(&task.name).filter(|_| !unsettled) {
                Some(around) => self.scopes.insert(0, around),
                None => {
                    self.scopes.clear();
                    self.current_ret = None;
                    return Ok(());
                }
            }
        }
        for param in &task.params {
            if param.ty == Type::Region && param.passing != Passing::Copy {
                let why = if param.passing.changes() {
                    "never changes"
                } else {
                    "is given as it is"
                };
                self.record(Error::at(
                    param.span,
                    format!(
                        "a region {}, so '{}' can't be '{}'",
                        why,
                        param.name,
                        param.passing.word()
                    ),
                ));
            }
            if param.ty == Type::Region {
                self.define_region(&param.name, param.span, true)?;
                if let Some(info) = self
                    .scopes
                    .last_mut()
                    .and_then(|scope| scope.names.get_mut(&param.name))
                {
                    info.param = true;
                }
            } else {
                let alters =
                    param.name == THIS && task.owner.as_ref().is_some_and(|owner| owner.alters);
                let mode = if alters || matches!(param.passing, Passing::Flex | Passing::FlexRef) {
                    Mode::Flex
                } else if matches!(param.passing, Passing::Bind | Passing::BindRef) {
                    Mode::Bind
                } else {
                    Mode::Fixed
                };
                if param.name != DISCARD {
                    self.define_param(
                        &param.name,
                        known(&param.ty),
                        mode,
                        param.passing,
                        param.span,
                    )?;
                }
            }
        }
        for param in &task.params {
            for region in param.ty.regions() {
                if self.lookup(region).is_none() {
                    self.define_region(region, param.ty_span, false)?;
                }
            }
        }
        // Header `r: region default` occupies the body's default-region slot; body cannot declare another.
        if let Some((name, at)) = task
            .params
            .iter()
            .find(|param| param.default_region)
            .map(|param| (param.name.clone(), param.span))
        {
            self.set_default_region(&name, at)?;
        }
        self.result_names = task.result_names().map(|(name, _)| name.clone()).collect();
        self.unset = self.result_names.iter().cloned().collect();
        for (result, ty) in task.results.iter().zip(task.ret.results()) {
            if let Some((name, at)) = &result.name {
                self.define_result(name, known(ty), *at)?;
            }
        }
        if task.native {
            self.natives.insert(task.name.clone());
            self.scopes.clear();
            self.current_ret = None;
            self.current_method = None;
            self.current_owner = None;
            self.current_shape = None;
            self.current_type = None;
            self.result_names.clear();
            self.unset.clear();
            return Ok(());
        }
        let before = self.errors.len();
        if is_startup(&task.name) {
            self.check_startup(&mut task.body, &task.passes);
        } else {
            let checked = self.check_block(&mut task.body);
            if task.shortcut
                && task.ret.unknown()
                && let Some(ret) = self.current_ret.as_ref()
                && !ret.unknown()
            {
                task.ret = ret.clone();
            }
            let used = std::mem::take(&mut *self.kept_used.borrow_mut());
            if let Some(kept) = self.kept_lambdas.get_mut(&task.name) {
                for place in kept
                    .places
                    .iter()
                    .filter(|place| !used.contains(&place.name))
                {
                    self.warnings.push(Error::at(place.span, format!("this lambda keeps '{0}' as a place, '{1} {0}', and never uses it; leave it out of the list", place.name, place.passing.word())));
                }
                kept.uses = used;
            }
            checked?;
        }
        let owner_broken = task.owner.is_some()
            && method_parts(&task.name).is_some_and(|(of, _)| self.broken.contains(of));
        let whole = self.errors.len() == before && !unsettled && !owner_broken;
        // Verify generic body copies into non-header regions only if body checked without errors.
        if !task.types.is_empty() && whole {
            let mut made = Made::default();
            self.substitute_task(task, &HashMap::new(), &mut made)?;
            let kept = keeps_params(task);
            let named = header_regions(task);
            let loose: Vec<(String, String, bool, Span)> = made
                .copies
                .into_iter()
                .filter(|(param, region, _)| {
                    !kept
                        .get(param)
                        .is_some_and(|regions| regions.contains(region))
                })
                .map(|(param, region, at)| {
                    let in_header = named.contains(&region);
                    (param, region, in_header, at)
                })
                .collect();
            if !loose.is_empty() {
                self.loose_copies.insert(task.name.clone(), loose);
            }
        }
        self.scopes.clear();
        self.current_lambda = None;
        self.current_task.clear();
        self.current_ret = None;
        self.current_method = None;
        self.current_owner = None;
        self.current_shape = None;
        self.current_type = None;
        let ends_well = if self.result_names.is_empty() {
            if whole && sends_value(&task.ret) && !always_sends(&task.body) {
                err(
                    task.span,
                    format!(
                        "{} can finish without sending a value",
                        shown_task(&task.name)
                    ),
                )
            } else {
                Ok(())
            }
        } else if whole
            && !always_sends(&task.body)
            && let Some(name) = self.first_unset()
        {
            err(
                task.span,
                format!(
                    "{} can finish without setting '{}'",
                    shown_task(&task.name),
                    name
                ),
            )
        } else {
            Ok(())
        };
        self.result_names.clear();
        self.unset.clear();
        ends_well
    }

    fn branch_state(&mut self, block: &Block, entry: &HashSet<String>) -> Option<HashSet<String>> {
        let after = std::mem::replace(&mut self.unset, entry.clone());
        (!always_leaves(block)).then_some(after)
    }

    fn join_branches(&mut self, entry: HashSet<String>, branches: Vec<Option<HashSet<String>>>) {
        let mut after: Option<HashSet<String>> = None;
        for branch in branches.into_iter().flatten() {
            after.get_or_insert_with(HashSet::new).extend(branch);
        }
        self.unset = after.unwrap_or(entry);
    }

    fn push_scope(&mut self) {
        self.scopes.push(Scope::default());
    }

    fn pop_scope(&mut self) {
        self.scopes.pop();
    }

    /// Hide outer value-loop around loop headers (`each` source / `start`) so headers cannot `break` into it.
    fn hide_value_loop(&mut self, gives: bool) -> Option<usize> {
        let depth = self.loops.len() + 1;
        match self.value_loops.last_mut() {
            Some((at, _)) if gives && *at == depth => Some(std::mem::replace(at, usize::MAX)),
            _ => None,
        }
    }

    fn show_value_loop(&mut self, hidden: Option<usize>) {
        if let (Some(depth), Some((at, _))) = (hidden, self.value_loops.last_mut()) {
            *at = depth;
        }
    }

    fn enter_loop(&mut self) {
        let name = self.loop_name.take();
        self.loops.push(name);
        self.loop_scopes.push(self.scopes.len());
    }

    fn is_moved(&self, name: &str) -> bool {
        self.moved.contains(name)
    }

    fn declared_outside_loop(&self, name: &str) -> bool {
        let Some(&loop_depth) = self.loop_scopes.last() else {
            return false;
        };
        for (i, scope) in self.scopes.iter().enumerate() {
            if scope.names.contains_key(name) {
                return i < loop_depth;
            }
        }
        false
    }

    fn check_parted(
        &mut self,
        parted: &mut PartedLoop,
        named: Option<(String, Span)>,
        gives: bool,
        span: Span,
    ) -> Result<()> {
        if let Some((name, at)) = unused_in_loop(parted) {
            return err(
                at,
                format!(
                    "'{}' is declared for this loop, and no part of it uses it; leave it out",
                    name
                ),
            );
        }
        // `parted` `start` and `step` are not blocks, so disallow region declarations in them.
        if let Some(region) = parted
            .start
            .iter()
            .chain(&parted.step)
            .find(|item| matches!(item.kind, StmtKind::Region { .. }))
        {
            return err(
                region.span,
                "a loop's start and step declare no region, as they are no block of their own; declare it before the loop, or in its body for each pass",
            );
        }
        for item in parted.start.iter_mut() {
            let mut places = Vec::new();
            match &item.kind {
                StmtKind::Assign(targets, _) => targets
                    .iter()
                    .for_each(|target| target_places(target, &mut places)),
                StmtKind::Step { target, .. } => places.push(target),
                _ => {}
            }
            if let Some((name, at)) = places.iter().find_map(|place| match &place.kind {
                ExprKind::Var(name) if self.lookup(name).is_none() => {
                    Some((name.clone(), place.span))
                }
                _ => None,
            }) {
                return err(
                    at,
                    format!(
                        "unknown variable '{0}'; a loop's start sets names already declared, and declares its own after 'flex' or 'fixed', as in 'loop flex {0} = 0 || …'",
                        name
                    ),
                );
            }
            if let (StmtKind::Binding { names, .. }, Some((loop_name, at))) = (&item.kind, &named) {
                let mut declared = Vec::new();
                names
                    .iter()
                    .for_each(|bound| bound_names(bound, &mut declared));
                if let Some((name, span)) = declared.into_iter().find(|(name, _)| name == loop_name)
                {
                    return err(
                        span,
                        format!(
                            "'{}' is already the name of a loop around this, at {}:{}",
                            name, at.line, at.col
                        ),
                    );
                }
            }
            let hidden = self.hide_value_loop(gives);
            let checked = self.check_stmt(item);
            self.show_value_loop(hidden);
            checked?;
        }
        let unchanging = parted.cond.as_ref().and_then(|cond| {
            unchanging_reads(
                cond,
                &parted.body,
                &parted.step,
                named.as_ref().map(|(name, _)| name.as_str()),
            )
        });
        let entry = self.unset.clone();
        let stepping = self.stepping;
        self.loops.push(named);
        self.loop_scopes.push(self.scopes.len());
        let result = self.check_parted_passes(parted, gives, span);
        self.loops.pop();
        self.loop_scopes.pop();
        self.stepping = stepping;
        self.unset = entry;
        result?;
        if let Some(finally) = &mut parted.finally {
            let given = self.loop_given.take();
            self.check_finally(finally, gives, &parted.body, given, span)?;
        }
        match &parted.cond {
            None if !parted.endless && parted.start.is_empty() && parted.step.is_empty() => {
                self.warnings.push(Error::at(span, ENDLESS_UNSAID))
            }
            None => {}
            Some(cond) if says_true(cond) => {
                if parted.start.is_empty() && parted.step.is_empty() {
                    self.warnings.push(Error::at(span, ENDLESS_UNSAID));
                }
            }
            Some(cond) => {
                if let Some(names) = unchanging {
                    self.warn_unchanging(&names, cond.value.span);
                }
            }
        }
        Ok(())
    }

    fn check_parted_passes(
        &mut self,
        parted: &mut PartedLoop,
        gives: bool,
        span: Span,
    ) -> Result<()> {
        let has_finally = parted.finally.is_some();
        let branches = if !gives {
            None
        } else if has_finally {
            Some(OPTIONAL_LOOP_BRANCHES)
        } else {
            Some(LOOP_BRANCHES)
        };
        let given = match &mut parted.cond {
            Some(cond) => self.check_condition(cond, &mut parted.body, branches)?,
            None => {
                if let Some(branches) = branches {
                    self.push_scope();
                    let res = self.value_block_tail(&mut parted.body, span, branches);
                    self.pop_scope();
                    res?
                } else {
                    self.check_scoped_block(&mut parted.body).map(|()| None)?
                }
            }
        };
        // `continue` targets `step`, so forbid `continue` and scope `step` vars to a single iteration.
        self.stepping = Some(self.loops.len());
        for item in parted.step.iter_mut() {
            if let StmtKind::Binding { names, .. } = &item.kind {
                let at = names.first().map_or(item.span, |bound| bound.span);
                return err(
                    at,
                    "a loop's step runs to its end at once, so a name declared there ends before anything can use it; declare it in the start, after 'flex'",
                );
            }
            self.check_stmt(item)?;
        }
        self.loop_given = given;
        Ok(())
    }

    /// Checked outside the loop so `break`/`continue` hit enclosing loops; overriding loop value warns.
    fn check_finally(
        &mut self,
        finally: &mut Block,
        gives: bool,
        body: &Block,
        body_given: Option<(Type, Span)>,
        span: Span,
    ) -> Result<()> {
        let entry = self.unset.clone();
        self.push_scope();
        let given = if gives {
            self.value_block_tail(finally, span, FINALLY_BRANCHES)
        } else {
            self.check_block(finally).map(|()| None)
        };
        self.pop_scope();
        self.unset = entry;
        let given = given?;
        let body_gave = body_given.is_some() || body.last().is_some_and(|last| gives_value(last) || matches!(&last.kind, StmtKind::Expr(e) if e.ty.as_ref().is_some_and(|t| *t != Type::Nothing)));
        if gives && body_gave && given.is_some() {
            self.warnings.push(Error::at(span, BOTH_LOOP_FORMS_WARNING));
        }
        self.loop_given = given;
        Ok(())
    }

    fn warn_unchanging(&mut self, names: &[String], at: Span) {
        let plain = |info: &VarInfo| {
            info.refers.is_none()
                && !info.kept
                && matches!(info.passing, Passing::Copy | Passing::Flex | Passing::Fixed)
                && !matches!(
                    info.ty,
                    Type::Ptr(..)
                        | Type::Slice(..)
                        | Type::Map(..)
                        | Type::Task(_)
                        | Type::Closure(_)
                        | Type::Unknown
                )
        };
        if !names
            .iter()
            .all(|name| self.lookup(name).is_some_and(plain))
        {
            return;
        }
        if self
            .scopes
            .iter()
            .flat_map(|scope| scope.names.values())
            .any(|info| info.refers.is_some())
            || self
                .kept_lambdas
                .values()
                .any(|kept| kept.places.iter().any(|place| names.contains(&place.name)))
        {
            return;
        }
        let read: Vec<String> = names.iter().map(|name| format!("'{}'", name)).collect();
        self.warnings.push(Error::at(
            at,
            format!("this loop never ends: its condition reads only {}, which nothing in the loop changes, and nothing in it leaves the loop", read.join(" and ")),
        ));
    }

    fn check_loop_value(&mut self, value: &mut ValueLoop, span: Span) -> Result<Type> {
        let place = self.loop_place.take();
        let never_ends = match &value.stmt.kind {
            StmtKind::Parted(parted) => parted.cond.as_ref().is_none_or(says_true),
            StmtKind::Loop(cond, _, _) => says_true(cond),
            _ => false,
        };
        if never_ends && !value.gives {
            return err(
                span,
                "a loop that never ends by itself ends only by a 'break' or a '<-', so a plan B after it would run every time it ends; do what it does before the 'break' instead",
            );
        }
        if never_ends {
            return err(
                span,
                "a loop that never ends by itself gives no value, since no pass of it is the final one; give it a condition, as in 'loop i < n', and stop it early with 'break = v'",
            );
        }
        if let Some((name, at)) = value.name.as_ref().filter(|_| value.arrow) {
            self.push_scope();
            let free = self.define(name, Type::Unknown, Mode::Fixed, *at);
            self.pop_scope();
            free?;
        }
        self.loop_name = value.name.clone();
        self.value_loops.push((self.loops.len() + 1, Vec::new()));
        self.loop_gives = value.gives;
        self.loop_given = None;
        let result = self.check_stmt_kind(&mut value.stmt);
        self.loop_gives = false;
        self.loop_name = None;
        let breaks = self
            .value_loops
            .pop()
            .map(|(_, breaks)| breaks)
            .unwrap_or_default();
        let given = self.loop_given.take();
        if let StmtKind::Each(_, _, range, _, _) = &value.stmt.kind
            && matches!(range.ty, Some(Type::Group(_)))
        {
            return err(
                range.span,
                "a loop through the values of a group gives no value, since each pass is written out for a value of its own; give the values on to a task, or gather what the passes give in a variable",
            );
        }
        result?;
        let (given, at) = match (value.gives, given) {
            (false, _) => (Type::Nothing, span),
            (true, Some(given)) => given,
            (true, None) => {
                return err(
                    span,
                    if value.finally().is_some() {
                        "the finally block of this loop never gives its value"
                    } else {
                        "every pass of this loop leaves, with '<-', 'break' or 'continue', so its last line never gives its value"
                    },
                );
            }
        };
        let (given, manual_error) = match given {
            Type::Or(value_ty, error) => (*value_ty, Some(*error)),
            Type::Fail(_) => {
                return err(
                    at,
                    if value.finally().is_some() {
                        "the finally block of this loop fails, so it never gives a value; give one on a path of its own"
                    } else {
                        "the last line of every pass of this loop fails, so it never gives a value; give one on a path of its own"
                    },
                );
            }
            other => (other, None),
        };
        if matches!(given, Type::None) {
            return err(
                at,
                if value.finally().is_some() {
                    "the finally block of this loop gives only none, which doesn't say its type; give a value, or 'none' beside one in a 'when'"
                } else {
                    "the last line of this loop gives only none, which doesn't say its type; give a value, or 'none' beside one in a 'when'"
                },
            );
        }
        let given = if value.finally().is_some() || !value.gives {
            given
        } else {
            self.map_collection(value, given, place.as_ref(), span)?
        };
        value.open = (
            !breaks.iter().any(|(ty, _)| *ty != Type::None),
            manual_error.is_none(),
        );
        let manual = match manual_error.as_ref() {
            None => Type::Bool,
            Some(error) => self.manual_type(error, value, at)?,
        };
        let mut broke: Option<Type> = None;
        for (ty, at) in &breaks {
            let ty = match ty {
                Type::None => continue,
                Type::Maybe(inner) => (**inner).clone(),
                other => other.clone(),
            };
            broke = Some(match broke {
                None => ty,
                Some(before) => self.join(&before, &ty).filter(|joined| !matches!(joined, Type::Maybe(_) | Type::Or(..))).ok_or_else(|| {
                    Error::at(*at, format!("this 'break' gives {}, and another gives {}; the breaks of a loop give one type", ty, before))
                })?,
            });
        }
        let broke = broke.unwrap_or(Type::Bool);
        if holds_untold(&broke)
            && let Some((ty, at)) = breaks.iter().find(|(ty, _)| holds_untold(ty))
        {
            if self.errors.iter().any(|error| error.span == Some(*at)) {
                return Ok(Type::Unknown);
            }
            return err(
                *at,
                format!(
                    "this 'break' gives a variant whose values don't say all of its types, and nothing tells a loop's breaks more; write them, as in '{}'",
                    untold_written(ty)
                ),
            );
        }
        let mut failures = Vec::new();
        if let Some(finally) = value.finally() {
            last_values(finally, &mut failures);
        } else if let Some(body) = value.body() {
            last_values(body, &mut failures);
        }
        let manual_at = failures.iter().find(|e| may_fail(e)).map_or(at, |e| e.span);
        let held: Vec<(String, Span)> = breaks
            .iter()
            .chain([&(manual.clone(), manual_at)])
            .flat_map(|(ty, at)| {
                ty.regions()
                    .into_iter()
                    .map(|region| (region.to_string(), *at))
            })
            .filter(|(region, _)| region != ANY_REGION)
            .collect();
        for (region, at) in &held {
            if !unnamed_region(region) && self.lookup(region).is_none() {
                return err(
                    *at,
                    format!(
                        "this value is in region '{}', which is freed when the pass ends, so it can't be what the loop fails with",
                        region
                    ),
                );
            }
        }
        if let Some((first, _)) = held.first()
            && let Some((other, other_at)) = held.iter().find(|(region, _)| region != first)
        {
            return err(
                *other_at,
                format!(
                    "this value is in region '{}', and another the loop fails with is in region '{}'; what a loop fails with is in one region, so give both in the same one",
                    other, first
                ),
            );
        }
        let region = held
            .first()
            .map_or(ANY_REGION.to_string(), |(region, _)| region.clone());
        let result = Applied {
            name: library::LOOP_RESULT.to_string(),
            types: vec![broke, manual],
            region: Some(region),
        };
        let result = self.made_kinds(Type::Applied(Box::new(result)), span)?;
        let ty = Type::Or(Box::new(given), Box::new(result));
        if value.gives {
            if let Some(finally) = value.finally_mut() {
                self.settle_value(finally, &ty)?;
            } else if let Some(body) = value.body_mut() {
                self.settle_value(body, &map_pass(&ty, manual_error.is_some()))?;
            }
        }
        // Value-loop outputs outlive every iteration, so they cannot reference loop-local regions.
        if let Some(region) = ty.regions().into_iter().find(|region| {
            !unnamed_region(region) && *region != ANY_REGION && self.lookup(region).is_none()
        }) {
            let at = breaks
                .iter()
                .find(|(ty, _)| ty.regions().contains(&region))
                .map_or(at, |(_, at)| *at);
            return err(
                at,
                format!(
                    "this value is in region '{}', which is freed when the pass ends, so it can't be the loop's value",
                    region
                ),
            );
        }
        Ok(ty)
    }

    /// Infers slice vs constant array for map-form loops; `continue` skips slice items or produces `none` in array items.
    fn map_collection(
        &mut self,
        value: &ValueLoop,
        item: Type,
        place: Option<&Type>,
        span: Span,
    ) -> Result<Type> {
        let count = match &value.stmt.kind {
            StmtKind::Each(_, _, range, _, _) => match (&range.ty, &range.kind) {
                (Some(Type::Array(_, count)), _) => Some(*count),
                (_, ExprKind::Range(start, end)) => {
                    match (constant_int(start), constant_int(end)) {
                        (Some(a), Some(b)) => match b
                            .checked_sub(a)
                            .and_then(|n| u64::try_from(n).ok())
                            .filter(|n| *n > 0)
                        {
                            Some(n) => Some(n),
                            None => {
                                return err(
                                    range.span,
                                    format!(
                                        "the range {}..{} is empty, so this loop never runs and has no items to give",
                                        a, b
                                    ),
                                );
                            }
                        },
                        _ => None,
                    }
                }
                _ => None,
            },
            _ => None,
        };
        let maybe_item = || match &item {
            Type::Maybe(_) => item.clone(),
            other => Type::Maybe(Box::new(other.clone())),
        };
        let continued = continues_loop(value);
        let in_default = |this: &mut Self| {
            this.region_or_default(None, span, || "this loop makes a slice, since how many items it gives is known only as it runs, so it needs a region: write its type, as in 'fixed xs: [int]@r = each …'".to_string())
        };
        Ok(match (place, count) {
            (Some(Type::Slice(_, region)), _) => {
                let region = match region {
                    Some(region) => region.clone(),
                    None => in_default(self)?,
                };
                Type::Slice(Box::new(item), Some(region))
            }
            (Some(Type::Array(..)), None) => {
                return err(
                    span,
                    "how many items this loop gives is known only as it runs, so it makes a slice, not an array; write its type as one, as in '[int]@r'",
                );
            }
            (Some(Type::Array(placed, _)), Some(count)) if matches!(**placed, Type::Maybe(_)) => {
                Type::Array(Box::new(maybe_item()), count)
            }
            (Some(Type::Array(..)), Some(count)) if let Some(at) = continued => {
                return err(
                    at,
                    format!(
                        "this 'continue' leaves its pass without an item, and an array of {0} has one for every pass; write its type with maybe items, as in '[maybe {0}#{1}]', where a pass left so is none, or as a slice, as in '[{0}]@r', which leaves it out",
                        item, count
                    ),
                );
            }
            (_, Some(count)) if continued.is_some() => Type::Array(Box::new(maybe_item()), count),
            (_, Some(count)) => Type::Array(Box::new(item), count),
            (_, None) => Type::Slice(Box::new(item), Some(in_default(self)?)),
        })
    }

    fn manual_type(&self, error: &Type, value: &ValueLoop, at: Span) -> Result<Type> {
        let wrong = || {
            err(
                at,
                "the last line of a loop that gives a value fails only with 'LoopResult.Manual(…)', which 'include std/loops {LoopResult}' brings in; 'break = v' stops it with a value",
            )
        };
        let Type::Applied(result) = self.unmade(error) else {
            return wrong();
        };
        if result.name != library::LOOP_RESULT {
            return wrong();
        }
        let mut failures = Vec::new();
        if let Some(finally) = value.finally() {
            last_values(finally, &mut failures);
        } else if let Some(body) = value.body() {
            last_values(body, &mut failures);
        }
        for failure in failures {
            let fails = may_fail(failure);
            let failure = match &failure.kind {
                ExprKind::Wrap(inner) => inner,
                _ => failure,
            };
            match &failure.kind {
                ExprKind::Fail(inner) => match &inner.kind {
                    ExprKind::Construct { tag, .. } if tag == "Manual" => {}
                    ExprKind::Construct { tag, .. } => {
                        return err(
                            inner.span,
                            format!(
                                "'{}' says what the loop did, so its last line fails only with 'LoopResult.Manual(…)'; 'break = v' stops it with a value",
                                tag
                            ),
                        );
                    }
                    _ => {
                        return err(
                            inner.span,
                            "the last line of a loop that gives a value fails only with 'fail LoopResult.Manual(…)' written there, which says the loop failed by its own choice",
                        );
                    }
                },
                _ if fails => {
                    return err(
                        failure.span,
                        "this may fail, and the last line of a loop that gives a value fails only with 'fail LoopResult.Manual(…)' written there; give it a plan B, as in 'x { 0 }'",
                    );
                }
                _ => {}
            }
        }
        Ok(result
            .types
            .get(1)
            .cloned()
            .filter(|ty| !is_untold(ty))
            .unwrap_or(Type::Bool))
    }

    fn check_break_value(
        &mut self,
        name: Option<&(String, Span)>,
        value: Option<&mut Expr>,
    ) -> Result<()> {
        let target = match name {
            None => Some(self.loops.len()),
            Some((name, _)) => self
                .loops
                .iter()
                .rposition(|named| named.as_ref().is_some_and(|(given, _)| given == name))
                .map(|i| i + 1),
        };
        let Some(value) = value else { return Ok(()) };
        let Some(at) = self
            .value_loops
            .iter()
            .rposition(|(at, _)| Some(*at) == target)
        else {
            return err(
                value.span,
                "this loop gives no value, so its 'break' gives none; a loop gives one where it is a value, as in 'fixed r = loop … fi'",
            );
        };
        let ty = self.check_expr(value)?;
        if matches!(ty, Type::Nothing | Type::Fail(_) | Type::Or(..)) {
            return err(
                value.span,
                format!(
                    "a 'break' gives a value the loop fails with, and this is {}",
                    ty
                ),
            );
        }
        let params = ty.params();
        if let Some((group, _)) = self.group_turns.iter().find(|(group, around)| {
            target.is_some_and(|target| target <= *around) && params.contains(&group.as_str())
        }) {
            return err(
                value.span,
                format!(
                    "this 'break' gives the loop around the loop through the group's values a value of type {0}, which each value of the group makes another type; give it a value of one type, as in 'v.str() at r'",
                    group
                ),
            );
        }
        if let Some((_, breaks)) = self.value_loops.get_mut(at) {
            breaks.push((ty, value.span));
        }
        Ok(())
    }

    fn check_jump(&mut self, word: &str, name: Option<&(String, Span)>, span: Span) -> Result<()> {
        let (what, verb) = if word == "break" {
            ("stops a loop", "stop")
        } else {
            ("goes on with a loop's next pass", "go on with")
        };
        if self.loops.is_empty() {
            if self.current_lambda.is_some() {
                return err(
                    span,
                    format!(
                        "'{}' {}, and there is none around it in this lambda; a lambda's body is a task of its own, so it can't {} a loop around the lambda",
                        word, what, verb
                    ),
                );
            }
            return err(
                span,
                format!("'{}' {}, and there is none around it here", word, what),
            );
        }
        let target = match name {
            None => Some(self.loops.len()),
            Some((name, _)) => self
                .loops
                .iter()
                .rposition(|named| named.as_ref().is_some_and(|(given, _)| given == name))
                .map(|i| i + 1),
        };
        if word == "continue" && target.is_some() && target == self.stepping {
            return err(
                span,
                "'continue' goes to this loop's step, and this is its step; leave it out, or 'break' to stop the loop",
            );
        }
        let Some((name, at)) = name else {
            return Ok(());
        };
        if self.loops.iter().flatten().any(|(given, _)| given == name) {
            return Ok(());
        }
        if self.loop_around_lambda(name).is_some() {
            return err(
                *at,
                format!(
                    "'{0}' names a loop around this lambda, and a lambda's body is a task of its own, so it can't {1} that loop; only the loops inside the lambda can be named here",
                    name, verb
                ),
            );
        }
        if self.lookup(name).is_some() {
            return err(
                *at,
                format!(
                    "'{}' is a variable, not the name of a loop around this; a loop is named before its word, as in 'outer => each x in xs'",
                    name
                ),
            );
        }
        let named: Vec<String> = self
            .loops
            .iter()
            .flatten()
            .map(|(given, _)| format!("'{}'", given))
            .collect();
        let around = match named.as_slice() {
            [] => format!(
                "none of the loops around it has a name; a loop is named before its word, as in '{} => each x in xs'",
                name
            ),
            [one] => format!("the one named loop around it is {}", one),
            many => format!("the named loops around it are {}", many.join(", ")),
        };
        err(
            *at,
            format!(
                "no loop around this '{}' is named '{}': {}",
                word, name, around
            ),
        )
    }

    fn note_lambda_loops(&mut self, lambda: &str) {
        let mut named: Vec<(String, Span)> = self
            .current_lambda
            .as_ref()
            .and_then(|current| self.lambda_loops.get(current))
            .cloned()
            .unwrap_or_default();
        named.extend(self.loops.iter().flatten().cloned());
        self.lambda_loops.insert(lambda.to_string(), named);
    }

    fn loop_around_lambda(&self, name: &str) -> Option<Span> {
        let lambda = self.current_lambda.as_ref()?;
        self.lambda_loops
            .get(lambda)?
            .iter()
            .find(|(given, _)| given == name)
            .map(|(_, at)| *at)
    }

    fn check_scoped_block(&mut self, block: &mut Block) -> Result<()> {
        self.push_scope();
        let result = self.check_block(block);
        self.pop_scope();
        result
    }

    fn check_block_with(&mut self, bindings: Vec<Declared>, block: &mut Block) -> Result<()> {
        self.push_scope();
        let result = bindings
            .into_iter()
            .filter(|(name, _, _, _)| name != DISCARD)
            .try_for_each(|(name, span, ty, mode)| self.define(&name, ty, mode, span))
            .and_then(|()| self.check_block(block));
        self.pop_scope();
        result
    }

    /// Declares a local with no shadowing against visible locals, variants, macros, kinds, shapes, tasks, modules, or loops.
    fn define(&mut self, name: &str, ty: Type, mode: Mode, span: Span) -> Result<()> {
        if let Some(info) = self.variant_in_scope(name) {
            let at = info.variant.span;
            if at.file != span.file {
                return err(
                    span,
                    format!(
                        "'{}' is already the name of a variant of kind '{}'",
                        name, info.kind
                    ),
                );
            }
            return err(
                span,
                format!("'{}' is already defined at {}:{}", name, at.line, at.col),
            );
        }
        let full = self.in_module(name);
        if let Some(info) = self.macros.get(&full) {
            let at = info.span;
            if at.file != span.file {
                return err(
                    span,
                    format!(
                        "'{}' is already the name of a macro this file includes",
                        name
                    ),
                );
            }
            return err(
                span,
                format!(
                    "'{}' is already defined at {}:{}, as a macro",
                    name, at.line, at.col
                ),
            );
        }
        if self.kinds.contains_key(&full) {
            return err(
                span,
                format!(
                    "'{0}' is the name of a kind, so '{0}.x' would name its variant; choose another name",
                    name
                ),
            );
        }
        if self.shapes.contains_key(&full) {
            return err(
                span,
                format!(
                    "'{0}' is the name of a shape, so '{0}.x' would name its shared field; choose another name",
                    name
                ),
            );
        }
        if (is_task(&ty)
            || matches!(ty, Type::Closure(_))
            || matches!(&ty, Type::Maybe(inner) if is_task(inner)))
            && self.tasks.contains_key(&full)
        {
            return err(
                span,
                format!(
                    "'{0}' is the name of a task, so '{0}(…)' would call it rather than this task value; choose another name",
                    name
                ),
            );
        }
        if let Some(at) = self.module_used(name) {
            return err(
                span,
                format!(
                    "'{}' is the name of a module this file includes, at {}:{}",
                    name, at.line, at.col
                ),
            );
        }
        if self.lookup(name).is_none()
            && let Some(lambda) = self
                .current_lambda
                .as_ref()
                .filter(|lambda| self.kept_lambdas.contains_key(*lambda))
            && self
                .lambda_outer
                .get(lambda)
                .is_some_and(|outer| outer.contains(name))
        {
            return err(
                span,
                format!(
                    "'{}' is already a name in the code around this lambda, and a lambda that keeps what it uses reuses none of those names, even ones it doesn't keep; name this one otherwise",
                    name
                ),
            );
        }
        let clash = match (
            self.loops.iter().flatten().find(|(given, _)| given == name),
            self.loop_around_lambda(name),
        ) {
            (Some((_, at)), _) => Some(format!(
                "'{}' is already the name of a loop around this, at {}:{}",
                name, at.line, at.col
            )),
            (None, Some(at)) => Some(format!(
                "'{}' is already the name of a loop around this lambda, at {}:{}",
                name, at.line, at.col
            )),
            (None, None) => None,
        };
        if let Some(existing) = self.lookup(name) {
            let at = existing.span;
            let what = match existing {
                _ if existing.kept => {
                    "a variable of the code around this lambda, which the lambda may keep, declared"
                }
                _ if existing.ty == Type::Region => "the name of a region",
                _ if existing.result => "a result of this task, declared",
                _ => "defined",
            };
            return err(
                span,
                format!("'{}' is already {} at {}:{}", name, what, at.line, at.col),
            );
        }
        let Some(scope) = self.scopes.last_mut() else {
            return Err(Error::internal(format!(
                "'{}' defined outside of a task",
                name
            )));
        };
        let allocates = ty == Type::Region;
        let owners = match self.bound_owners.iter().position(|(at, _)| *at == span) {
            Some(i) => self.bound_owners.swap_remove(i).1,
            None => Vec::new(),
        };
        scope.names.insert(
            name.to_string(),
            VarInfo {
                ty,
                mode,
                span,
                allocates,
                result: false,
                param: false,
                passing: Passing::Copy,
                refers: None,
                kept: false,
                owners,
                family: None,
                bind_reads: false,
            },
        );
        match clash {
            Some(clash) => err(span, clash),
            None => Ok(()),
        }
    }

    fn define_param(
        &mut self,
        name: &str,
        ty: Type,
        mode: Mode,
        passing: Passing,
        span: Span,
    ) -> Result<()> {
        self.define(name, ty, mode, span)?;
        if let Some(info) = self
            .scopes
            .last_mut()
            .and_then(|scope| scope.names.get_mut(name))
        {
            info.param = true;
            info.passing = passing;
        }
        Ok(())
    }

    fn define_result(&mut self, name: &str, ty: Type, span: Span) -> Result<()> {
        self.define(name, ty, Mode::Fixed, span)?;
        if let Some(info) = self
            .scopes
            .last_mut()
            .and_then(|scope| scope.names.get_mut(name))
        {
            info.result = true;
        }
        Ok(())
    }

    fn first_unset(&self) -> Option<&str> {
        self.result_names
            .iter()
            .find(|name| self.unset.contains(*name))
            .map(String::as_str)
    }

    fn define_region(&mut self, name: &str, span: Span, allocates: bool) -> Result<()> {
        self.define(name, Type::Region, Mode::Fixed, span)?;
        if let Some(info) = self
            .scopes
            .last_mut()
            .and_then(|scope| scope.names.get_mut(name))
        {
            info.allocates = allocates;
        }
        Ok(())
    }

    fn lookup(&self, name: &str) -> Option<&VarInfo> {
        for scope in self.scopes.iter().rev() {
            if let Some(info) = scope.names.get(name) {
                if info.kept && !self.kept_used.borrow().iter().any(|used| used == name) {
                    self.kept_used.borrow_mut().push(name.to_string());
                }
                return Some(info);
            }
        }
        self.globals.get(name)
    }

    fn default_region(&self) -> Option<String> {
        self.scopes
            .iter()
            .rev()
            .find_map(|scope| scope.default.as_ref())
            .map(|(name, _)| name.clone())
    }

    /// Sets block default region; at most one per block so identical syntax does not span lifetimes.
    fn set_default_region(&mut self, name: &str, span: Span) -> Result<()> {
        if let Some((already, at)) = self.scopes.last().and_then(|scope| scope.default.clone()) {
            return err(
                span,
                format!(
                    "this block already has a default region, '{}', named at {}:{}; write 'at {}' on the lines that go there, or declare it in an inner block",
                    already, at.line, at.col, name
                ),
            );
        }
        if let Some(scope) = self.scopes.last_mut() {
            scope.default = Some((name.to_string(), span));
        }
        Ok(())
    }

    fn settle_call_region(
        &mut self,
        span: Span,
        what: &str,
        args: &mut Vec<Expr>,
        params: &[(String, Type)],
    ) -> Result<()> {
        let last = params.last().filter(|(_, ty)| *ty == Type::Region);
        if let Some(at) = region_after(args) {
            if last.is_none() {
                return err(
                    at,
                    format!(
                        "{} takes no region last, so no region is named after its call",
                        what
                    ),
                );
            }
            if args.len() > params.len() {
                return err(
                    at,
                    format!(
                        "{} is given its region in the parentheses already, so this is a second one; name it once",
                        what
                    ),
                );
            }
            if let Some(arg) = args.last_mut()
                && let ExprKind::RegionAfter(region) = &mut arg.kind
            {
                arg.kind = ExprKind::Var(std::mem::take(region));
            }
            return Ok(());
        }
        // Keep arity diagnostic accurate if final arg is a region where task expects none or expects a trailing region.
        let takes_one_there = args
            .len()
            .checked_sub(1)
            .and_then(|at| params.get(at))
            .is_some_and(|(_, ty)| *ty == Type::Region);
        let gives_region = !takes_one_there
            && args.last().is_some_and(|arg| matches!(&arg.kind, ExprKind::Var(name) if self.lookup(name).is_some_and(|info| info.ty == Type::Region)));
        if let Some((param, _)) = last
            && args.len() + 1 == params.len()
            && !gives_region
        {
            let region = self.region_or_default(None, span, || {
                format!("{} takes the region it makes memory in last, as '{}'; name it after the call, as in '… at r' or '…@r', or in the parentheses", what, param)
            });
            self.region_wanted |= region.is_err();
            let region = region?;
            args.push(Expr::new(ExprKind::Var(region), span));
        }
        Ok(())
    }

    fn region_or_default(
        &mut self,
        written: Option<&String>,
        span: Span,
        needed: impl FnOnce() -> String,
    ) -> Result<String> {
        if let Some(region) = written {
            return Ok(region.clone());
        }
        match self.default_region() {
            Some(region) => Ok(region),
            None => err(span, format!("{}{}", needed(), self.or_make_it_default())),
        }
    }

    fn unsettled_copy(&self, at: Span) -> String {
        let first = match self.copy_words.get(&(at.file, at.line, at.col)) {
            Some(word) => format!(
                "can't tell which region the new value goes in, since nothing it goes into names one; name it, as in 'xs.{0}(…) at r' or 'xs.{0}(…)@r'",
                word
            ),
            None => UNSETTLED_COPY.to_string(),
        };
        match self.default_region() {
            Some(_) => format!("{}{}", first, COPY_IGNORES_DEFAULT),
            None => first,
        }
    }

    fn or_make_it_default(&self) -> String {
        match self.innermost_region() {
            Some(name) => format!(
                "; or make a region the block's default, as in 'region {} {}'",
                name, DEFAULT
            ),
            None => String::new(),
        }
    }

    fn innermost_region(&self) -> Option<&str> {
        // Map iteration order is unspecified, so pick last declared region.
        self.scopes
            .iter()
            .rev()
            .find_map(|scope| {
                scope
                    .names
                    .iter()
                    .filter(|(_, info)| info.ty == Type::Region && info.allocates)
                    .max_by_key(|(_, info)| (info.span.line, info.span.col))
            })
            .map(|(name, _)| name.as_str())
    }

    fn lookup_or_err(&self, name: &str, span: Span) -> Result<&VarInfo> {
        if let Some(info) = self.lookup(name)
            && info.ty == Type::Region
        {
            return err(
                span,
                format!(
                    "'{0}' is a region, not a value; allocate in it with 'new T(…) at {0}'",
                    name
                ),
            );
        }
        self.lookup(name).ok_or_else(|| {
            if name == THIS {
                Error::at(span, self.not_a_method(THIS))
            } else if self.sees(name) && self.variants.contains_key(name) {
                Error::at(span, format!("'{}' is a variant, not a variable", name))
            } else if self.sees(name) && self.macros.contains_key(name) {
                Error::at(span, format!("'{}' is a macro, a value that never changes, not a variable", unqualified(name)))
            } else if self.module_used(name).is_some() {
                Error::at(span, format!("'{0}' is a module, not a variable; name something in it, as in '{0}.name'", name))
            } else if self.kinds.contains_key(&self.full_name(name)) {
                Error::at(span, format!("'{0}' is a kind, not a variable; name one of its variants, as in '{0}.Variant'", name))
            } else if let Some(shape) = self.shapes.get(&self.full_name(name)) {
                let example = match shape.fields.first() {
                    Some(field) => format!("{} {{ {}: … }}", name, field.name),
                    None => format!("{} {{}}", name),
                };
                Error::at(span, format!("'{}' is a shape, not a variable; a literal names its fields on one line, as in '{}'", name, example))
            } else {
                let hint = match self.module_elsewhere(name) {
                    hint if hint.is_empty() => self.elsewhere(name),
                    hint => hint,
                };
                if let Some(outer) = self.current_lambda.as_ref().and_then(|lambda| self.lambda_outer.get(lambda))
                    && outer.contains(name)
                {
                    if self.current_lambda.as_ref().is_some_and(|lambda| self.kept_lambdas.contains_key(lambda)) {
                        return Error::at(span, format!("'{0}' is a result of the task around this lambda, which a lambda doesn't keep; keep a variable of it first, as in 'fixed kept = {0}', and use that", name));
                    }
                    return Error::at(span, format!("'{0}' belongs to the code around this lambda, and a lambda takes nothing from it; give '{0}' as a parameter, or call a task that takes it; a lambda that keeps what it uses names the region it keeps its copies in, as in '[@r](…)'", name));
                }
                Error::at(span, format!("unknown variable '{}'{}", name, hint))
            }
        })
    }

    // Record errors and declare failed-binding names as `Type::Unknown` so later statements keep checking.
    fn check_block(&mut self, block: &mut [Stmt]) -> Result<()> {
        for stmt in block {
            let checked = self.check_stmt(stmt);
            if !self.keep_going(checked) {
                self.declare_unchecked(stmt);
            }
        }
        Ok(())
    }

    fn declare_unchecked(&mut self, stmt: &Stmt) {
        let StmtKind::Binding { names, mode, .. } = &stmt.kind else {
            return;
        };
        for bound in names.iter().flat_map(Bound::leaves) {
            if bound.name != DISCARD && self.lookup(&bound.name).is_none() {
                let _ = self.define(&bound.name, Type::Unknown, *mode, bound.span);
            }
        }
    }

    fn check_stmt(&mut self, stmt: &mut Stmt) -> Result<()> {
        let before = self.unsettled_copies.len();
        let types_before = self.unsettled_types.len();
        let kinds_before = self.untold_kinds.len();
        let result = self.check_stmt_kind(stmt);
        let unsettled = self.unsettled_copies.get(before).copied();
        let untold = self.unsettled_types.get(types_before).cloned();
        let untold_kind = self.untold_kinds.get(kinds_before).cloned();
        self.unsettled_copies.truncate(before);
        self.unsettled_types.truncate(types_before);
        self.untold_kinds.truncate(kinds_before);
        // Prioritize untold generic-variant inference error unless the statement already hit a clearer type-unknown error.
        if let (Err(error), Some((at, kind, tag, param, example))) = (&result, &untold_kind)
            && ((!error.message.starts_with("expected type")
                && !error.message.starts_with("cannot infer")
                && error.message.contains(&format!("{}<", unqualified(kind)))
                && ["<…", "…>", ", …"]
                    .iter()
                    .any(|untold| error.message.contains(untold)))
                || error.message.starts_with("cannot tell the type of"))
        {
            return err(*at, untold_kind_message(kind, tag, param, example));
        }
        result?;
        if let Some((at, kind, tag, param, example)) = untold_kind {
            return err(at, untold_kind_message(&kind, &tag, &param, &example));
        }
        if let Some(at) = unsettled {
            return err(at, self.unsettled_copy(at));
        }
        match untold {
            Some((at, task, param)) => err(at, self.untold_type(&task, &param)),
            None => Ok(()),
        }
    }

    /// Desugars `x++`/`x--`/`x op= v`; rejects side effects in LHS since desugaring duplicates the place.
    fn step_to_assignment(&mut self, stmt: &mut Stmt) -> Result<()> {
        let StmtKind::Step {
            target,
            op,
            value,
            symbol,
            at,
        } = &mut stmt.kind
        else {
            return Ok(());
        };
        let (op, symbol, at) = (*op, *symbol, *at);
        if let Some(inside) = changing_part(target) {
            let example = if matches!(symbol, "++" | "--") {
                format!("xs[i]{}", symbol)
            } else {
                format!("xs[i] {} …", symbol)
            };
            return err(
                inside,
                format!(
                    "'{}' names its place twice, reading and then setting it, so the place can't call a task or change anything; keep that part in a variable first, as in 'fixed i = next()' and then '{}'",
                    symbol, example
                ),
            );
        }
        let ty = self.check_expr(&mut target.clone())?;
        let counts = matches!(symbol, "++" | "--");
        if counts && !(ty.is_integer() || matches!(ty, Type::Char | Type::Unknown)) {
            let hint = match ty {
                _ if ty.is_float() => format!(
                    "; for a float, write 'x {} 1.0'",
                    if symbol == "++" { "+=" } else { "-=" }
                ),
                _ => String::new(),
            };
            return err(
                at,
                format!(
                    "'{}' counts a whole number or a char by one, and this is {}{}",
                    symbol,
                    a_type(&ty),
                    hint
                ),
            );
        }
        if ty.is_float()
            && op != BinaryOp::Pow
            && let ExprKind::IntLit(n) = value.kind
        {
            return err(
                value.span,
                format!(
                    "'{}' on a float takes a float, and {} is an int; write it '{}.0', as in 'x {} {}.0'",
                    symbol, n, n, symbol, n
                ),
            );
        }
        let place = target.clone();
        let value = std::mem::replace(value, Expr::new(ExprKind::NoneLit, at));
        let changed = match &ty {
            Type::Text(region) if op == BinaryOp::Add => {
                let Some(region) = region.clone() else {
                    return err(
                        at,
                        "'+=' joins text into the region the text is in, and this text lasts as long as the program, in no region; keep it in a region, as in 'flex t: text@r = …', or write 't = t + u at r'",
                    );
                };
                let mut parts = vec![place];
                step_parts(value, &region, at, &mut parts);
                Expr::new(
                    ExprKind::Join {
                        parts,
                        region,
                        region_span: at,
                    },
                    at,
                )
            }
            Type::Text(_) => {
                return err(
                    at,
                    format!(
                        "'{}' works on numbers; text is only joined, with '+='",
                        symbol
                    ),
                );
            }
            Type::Slice(_item, region) if op == BinaryOp::Add => {
                let Some(region) = region.clone() else {
                    return err(
                        at,
                        "'+=' joins into the region the slice is in, and this slice has no region; keep it in a region, as in 'flex s: [int]@r = …'",
                    );
                };
                let parts = vec![place, value];
                Expr::new(
                    ExprKind::Join {
                        parts,
                        region,
                        region_span: at,
                    },
                    at,
                )
            }
            Type::Slice(..) => {
                return err(
                    at,
                    format!(
                        "'{}' works on numbers; slices are only joined, with '+='",
                        symbol
                    ),
                );
            }
            _ => Expr::new(ExprKind::Binary(op, Box::new(place), Box::new(value)), at),
        };
        let target = std::mem::replace(target, Expr::new(ExprKind::NoneLit, at));
        stmt.kind = StmtKind::Assign(vec![Target::Place(target)], vec![changed]);
        Ok(())
    }

    fn check_stmt_kind(&mut self, stmt: &mut Stmt) -> Result<()> {
        if matches!(stmt.kind, StmtKind::Step { .. }) {
            self.step_to_assignment(stmt)?;
        }
        let span = stmt.span;
        match &mut stmt.kind {
            StmtKind::Step { .. } => Err(Error::internal_at(span, "a step left as it was")),
            StmtKind::Expr(e) => {
                if let ExprKind::Fail(inner) = &e.kind
                    && let ExprKind::Var(name) = &inner.kind
                    && self.lookup(name).is_none()
                {
                    return err(
                        e.span,
                        format!(
                            "'fail {0}' makes a failure, but nothing here is named '{0}'; a plan B names its failure with 'failure {0}' on its first line, and '<- fail {0}' sends one",
                            name
                        ),
                    );
                }
                self.check_expr(e)?;
                self.check_expr_stmt(e)
            }
            StmtKind::Binding {
                names,
                mode,
                reference: true,
                init,
                ..
            } => self.check_reference(names, *mode, init),
            StmtKind::Binding {
                names, mode, init, colon, ..
            } => {
                let mut from_loop = HashSet::new();
                let each_given = init.len() == names.len();
                for (i, bound) in names.iter_mut().enumerate() {
                    let Some(value) = init.get_mut(i).filter(|_| each_given) else {
                        continue;
                    };
                    if let ExprKind::PlanB { value, .. } = &mut value.kind
                        && let ExprKind::LoopValue(value) = &mut value.kind
                    {
                        if bound.parts.is_empty() && bound.name != DISCARD {
                            name_value_loop(value, &bound.name, bound.span)?;
                        }
                        continue;
                    }
                    let ExprKind::LoopValue(value) = &mut value.kind else {
                        continue;
                    };
                    if bound.parts.is_empty() && bound.name != DISCARD {
                        name_value_loop(value, &bound.name, bound.span)?;
                    }
                    if let Some(Type::Or(given, error)) = &bound.ty
                        && matches!(error.as_ref(), Type::Named(name, None) if name == library::LOOP_RESULT)
                    {
                        bound.ty = Some((**given).clone());
                        from_loop.insert(i);
                    }
                }
                if *colon {
                    let def_region = self.default_region().ok_or_else(|| {
                        Error::at(
                            span,
                            format!(
                                "':=' allocates into the default region, but no default region is active in this block; declare 'region r {}' or use 'new T(expr) at r'",
                                DEFAULT
                            ),
                        )
                    })?;
                    for (bound, value) in names.iter_mut().zip(init.iter_mut()) {
                        match &mut bound.ty {
                            Some(Type::Ptr(pointee, region)) => {
                                if region.is_none() {
                                    *region = Some(def_region.clone());
                                }
                                let pointee_ty = pointee.as_ref().clone();
                                let inner_val = std::mem::replace(value, Expr::new(ExprKind::NoneLit, value.span));
                                value.kind = ExprKind::New {
                                    ty: Box::new(pointee_ty),
                                    ty_span: bound.ty_span.unwrap_or(bound.span),
                                    value: Box::new(inner_val),
                                    region: Some(def_region.clone()),
                                    region_span: value.span,
                                };
                            }
                            Some(Type::Slice(_item, region)) => {
                                if region.is_none() {
                                    *region = Some(def_region.clone());
                                }
                                if let ExprKind::Array(values) = &mut value.kind {
                                    let inner = Expr::new(ExprKind::Array(std::mem::take(values)), value.span);
                                    value.kind = ExprKind::Shortcut {
                                        value: Box::new(inner),
                                        region: Some(def_region.clone()),
                                        region_span: value.span,
                                    };
                                }
                            }
                            Some(Type::Map(_k, _v, region)) => {
                                if region.is_none() {
                                    *region = Some(def_region.clone());
                                }
                                if let ExprKind::Pairs(pairs) = &mut value.kind {
                                    let inner = Expr::new(ExprKind::Pairs(std::mem::take(pairs)), value.span);
                                    value.kind = ExprKind::Shortcut {
                                        value: Box::new(inner),
                                        region: Some(def_region.clone()),
                                        region_span: value.span,
                                    };
                                }
                            }
                            Some(ty) => {
                                return err(
                                    bound.ty_span.unwrap_or(bound.span),
                                    format!("':=' allocates into a region and produces a pointer, slice, or map; use '=' to assign a direct value, or '^{}' for a pointer", ty),
                                );
                            }
                            None => {
                                match &mut value.kind {
                                    ExprKind::Array(values) => {
                                        let inner = Expr::new(ExprKind::Array(std::mem::take(values)), value.span);
                                        value.kind = ExprKind::Shortcut {
                                            value: Box::new(inner),
                                            region: Some(def_region.clone()),
                                            region_span: value.span,
                                        };
                                    }
                                    ExprKind::Pairs(pairs) => {
                                        let inner = Expr::new(ExprKind::Pairs(std::mem::take(pairs)), value.span);
                                        value.kind = ExprKind::Shortcut {
                                            value: Box::new(inner),
                                            region: Some(def_region.clone()),
                                            region_span: value.span,
                                        };
                                    }
                                    ExprKind::Shortcut { region, .. } => {
                                        if region.is_none() {
                                            *region = Some(def_region.clone());
                                        }
                                    }
                                    _ => {
                                        return err(
                                            value.span,
                                            "':=' with a scalar value or shape literal requires an explicit pointer type annotation (such as 'bind x: ^int := 4') to prevent ambiguity with whole values",
                                        );
                                    }
                                }
                            }
                        }
                    }
                }
                for bound in names.iter_mut() {
                    self.resolve_bound_types(bound)?;
                }
                if let Some(marked) = init
                    .iter()
                    .find(|value| matches!(value.kind, ExprKind::Ref(_)))
                {
                    let word = mode.word();
                    let name = names.first().map_or("y", |bound| bound.name.as_str());
                    return err(
                        marked.span,
                        format!(
                            "'{0} {1}' takes a copy, so leave out '&'; '{0}& {1} = &…' is another name for the place",
                            word, name
                        ),
                    );
                }
                for (bound, value) in names.iter().zip(init.iter_mut()) {
                    if let Some(ty) = &bound.ty {
                        self.prepare_shortcut_lambda(value, ty)?;
                    }
                }
                if let ([bound], [value]) = (names.as_slice(), init.as_slice())
                    && let Some(ty) = &bound.ty
                {
                    self.loop_place = loop_value(value).map(|_| success_of(ty));
                }
                if let ([bound], [value]) = (names.as_slice(), init.as_slice())
                    && matches!(value.kind, ExprKind::Pipe(_))
                    && let Some(Type::Or(_, error)) = &bound.ty
                {
                    self.pipe_target = Some((**error).clone());
                }
                let given = self.value_types(init, names.len(), span, true);
                self.pipe_target = None;
                self.loop_place = None;
                let given = given?;
                let forwarded = init.len() < names.len();
                let list_span = init.first().map_or(span, |value| value.span);
                let mut declared = Vec::new();
                for i in 0..names.len() {
                    let Some(actual) = given.get(i).cloned() else {
                        continue;
                    };
                    let value_span = if forwarded {
                        list_span
                    } else {
                        init.get(i).map_or(span, |value| value.span)
                    };
                    if let Some(group) = names.get_mut(i).filter(|bound| !bound.parts.is_empty()) {
                        self.unpack_bound(group, &actual, value_span, &mut declared)?;
                        continue;
                    }
                    let Some((name, at, annotated)) =
                        names.get(i).map(|b| (b.name.clone(), b.span, b.ty.clone()))
                    else {
                        continue;
                    };
                    let annotated = match (annotated, &actual) {
                        (Some(given), Type::Or(_, result)) if from_loop.contains(&i) => {
                            Some(Type::Or(Box::new(given), result.clone()))
                        }
                        (annotated, _) => annotated,
                    };
                    let ty = match annotated {
                        Some(annotated) => {
                            match init.get_mut(i).filter(|_| !forwarded) {
                                Some(value) => self.coerce(value, &annotated)?,
                                None => {
                                    fits_or_err(&actual, &annotated, value_span, given_by(init))?
                                }
                            }
                            annotated
                        }
                        None if name == DISCARD => actual,
                        None if matches!(
                            init.get(i).filter(|_| !forwarded).map(|value| &value.kind),
                            Some(ExprKind::Copy { region: None, .. })
                        ) =>
                        {
                            return err(value_span, self.unsettled_copy(value_span));
                        }
                        None => {
                            if let Some(val) = init.get(i).filter(|_| !forwarded)
                                && let Some(lambda_name) = self.shortcut_lambda_name(val)
                                && let Some(task) = self.shortcut_lambdas.get(lambda_name)
                                && let Some(untyped) = task.params.iter().find(|p| p.ty.unknown())
                            {
                                return err(
                                    val.span,
                                    format!(
                                        "cannot infer parameter type for '{}' in shortcut lambda; specify types with a full lambda, as in '(x: int) -> int <- ... fi', or give the variable a type",
                                        untyped.name
                                    ),
                                );
                            }
                            self.inferred_type(&name, &actual, value_span)?
                        }
                    };
                    if name == DISCARD && matches!(ty, Type::Or(..)) {
                        return err(value_span, dropped_error(&ty));
                    }
                    if let Some(bound) = names.get_mut(i) {
                        bound.ty = Some(ty.clone());
                    }
                    declared.push((name, at, ty));
                }
                for (i, bound) in names.iter().enumerate() {
                    let Some(value) = (if forwarded { init.first() } else { init.get(i) }) else {
                        continue;
                    };
                    let has_contents = bound.ty.as_ref().map_or_else(
                        || given.get(i).is_some_and(|ty| self.bind_has_contents(ty)),
                        |ty| self.bind_has_contents(ty),
                    );
                    if mode.can_change_contents(has_contents) {
                        if let Some(ty) = given
                            .get(i)
                            .filter(|_| bound.name != DISCARD || !bound.parts.is_empty())
                        {
                            self.hand_as(value, ty, HandedTo::Variable(bound_text(bound)));
                        }
                        continue;
                    }
                    let owners = self.owners(value);
                    if !owners.is_empty() {
                        let mut spans = Vec::new();
                        bound_spans(bound, &mut spans);
                        self.bound_owners
                            .extend(spans.into_iter().map(|at| (at, owners.clone())));
                    }
                }
                for (name, at, ty) in declared {
                    if held_value(&ty, &self.held_types) && *mode != Mode::Flex {
                        return err(
                            at,
                            format!(
                                "'{0}' is {1}, which changes what it keeps, so it is held in a 'flex' variable: 'flex {0} = …'",
                                name,
                                held_phrase(&ty)
                            ),
                        );
                    }
                    if holds_held(&ty, &self.held_types) {
                        return err(
                            at,
                            format!(
                                "'{}' would hold a '[flex @r]' lambda, or a shape holding one, inside another value, which is copied with it; such a value is held alone, in a 'flex' variable",
                                name
                            ),
                        );
                    }
                    if name != DISCARD {
                        self.moved.remove(&name);
                        self.define(&name, ty, *mode, at)?;
                    }
                }
                if !forwarded {
                    for (bound, value) in names.iter().zip(init.iter()) {
                        if let Some(from) = Checker::shared_slice_of(value) {
                            self.link_slices(from, &bound.name);
                        }
                    }
                }
                Ok(())
            }
            StmtKind::Assign(targets, values) => {
                for (target, value) in targets.iter().zip(values.iter_mut()) {
                    let value = match &mut value.kind {
                        ExprKind::PlanB { value, .. } => value,
                        _ => value,
                    };
                    if let (
                        Target::Place(Expr {
                            kind: ExprKind::Var(name),
                            span,
                            ..
                        }),
                        ExprKind::LoopValue(value),
                    ) = (target, &mut value.kind)
                    {
                        name_value_loop(value, name, *span)?;
                    }
                }
                let mut places = Vec::new();
                let mut assigned: HashMap<String, Span> = HashMap::new();
                for target in targets.iter_mut() {
                    places.push(self.check_target(target, &mut assigned)?);
                }
                for name in assigned.keys() {
                    self.moved.remove(name);
                }
                // Map multi-target assignments cannot auto-insert new keys.
                if targets.len() > 1
                    && let Some(at) = targets.iter().find_map(|target| match target {
                        Target::Place(Expr {
                            kind: ExprKind::Index(map, _),
                            span,
                            ..
                        }) if matches!(map.ty, Some(Type::Map(..))) => Some(*span),
                        _ => None,
                    })
                {
                    return err(
                        at,
                        "a map's value is set on a line of its own, as in 'm[k] = v', since it may add the key",
                    );
                }
                if let Some(marked) = values
                    .iter()
                    .find(|value| matches!(value.kind, ExprKind::Ref(_)))
                {
                    let reference = targets.iter().find_map(|target| match target {
                        Target::Place(Expr {
                            kind: ExprKind::Var(name),
                            ..
                        }) if self.lookup(name).is_some_and(|info| info.refers.is_some()) => {
                            Some(name.clone())
                        }
                        _ => None,
                    });
                    return err(
                        marked.span,
                        match reference {
                            Some(name) => format!("'{0}' names one place for as long as it lasts, and '{0} = …' writes a value there, so leave out '&'", name),
                            None => "'=' writes a value, so leave out '&'; a name for a place is declared, as in 'flex& y = &x'".to_string(),
                        },
                    );
                }
                let given = self.value_types(values, targets.len(), span, true)?;
                let forwarded = values.len() < targets.len();
                let list_span = values.first().map_or(span, |value| value.span);
                for (i, place) in places.into_iter().enumerate() {
                    let Some(actual) = given.get(i).cloned() else {
                        continue;
                    };
                    let value_span = if forwarded {
                        list_span
                    } else {
                        values.get(i).map_or(span, |value| value.span)
                    };
                    let place = match place {
                        TargetType::Tuple(parts, at) => {
                            self.unpack_target(&parts, at, &actual, value_span)?;
                            continue;
                        }
                        TargetType::Discard => None,
                        TargetType::Place(ty) => Some(ty),
                    };
                    let Some(expected) = place else {
                        if matches!(actual, Type::Or(..)) {
                            return err(value_span, dropped_error(&actual));
                        }
                        continue;
                    };
                    match values.get_mut(i).filter(|_| !forwarded) {
                        Some(value) => self.coerce(value, &expected)?,
                        None => fits_or_err(&actual, &expected, value_span, given_by(values))?,
                    }
                    let to = match targets.get(i) {
                        Some(Target::Place(Expr {
                            kind: ExprKind::Var(name),
                            ..
                        })) => HandedTo::Variable(name.clone()),
                        Some(Target::Place(place)) => HandedTo::Place(self.value_text(place)),
                        _ => continue,
                    };
                    if let Some(value) = if forwarded {
                        values.first()
                    } else {
                        values.get(i)
                    } {
                        self.hand_as(value, &expected, to);
                    }
                }
                // Direct `ys = xs` aliases slice storage; other RHS expressions detach into independent buffers.
                if let (
                    [
                        Target::Place(Expr {
                            kind: ExprKind::Var(name),
                            ..
                        }),
                    ],
                    [value],
                ) = (targets.as_slice(), values.as_slice())
                    && self.is_slice_var(name)
                {
                    let name = name.clone();
                    self.set_family(&name, None);
                    if let Some(from) = Checker::shared_slice_of(value) {
                        let from = from.to_string();
                        self.link_slices(&from, &name);
                    }
                }
                Ok(())
            }
            StmtKind::SetResults(names, values) => self.check_set_results(span, names, values),
            StmtKind::When(arms, else_block) => {
                self.check_when(span, arms, else_block, None).map(|_| ())
            }
            StmtKind::Block(body) => self.check_scoped_block(body),
            StmtKind::Loop(cond, body, finally) => {
                let gives = std::mem::take(&mut self.loop_gives);
                if always_holds(cond)
                    && let Some(pattern) = &cond.pattern
                {
                    return err(
                        pattern.span,
                        "a tuple's items always match, so this loop would never end; take the tuple apart with 'fixed' instead",
                    );
                }
                let unchanging = unchanging_reads(
                    cond,
                    body,
                    &[],
                    self.loop_name.as_ref().map(|(name, _)| name.as_str()),
                );
                let entry = self.unset.clone();
                let has_finally = finally.is_some();
                self.enter_loop();
                let branches = if !gives {
                    None
                } else if has_finally {
                    Some(OPTIONAL_LOOP_BRANCHES)
                } else {
                    Some(LOOP_BRANCHES)
                };
                let result = self.check_condition(cond, body, branches);
                self.loops.pop();
                self.loop_scopes.pop();
                self.unset = entry;
                let body_given = result?;
                match finally {
                    Some(finally) => self.check_finally(finally, gives, body, body_given, span)?,
                    None => self.loop_given = body_given,
                }
                if says_true(cond) {
                    self.warnings.push(Error::at(span, ENDLESS_UNSAID));
                } else if let Some(names) = unchanging {
                    self.warn_unchanging(&names, cond.value.span);
                }
                Ok(())
            }
            StmtKind::Parted(parted) => {
                let named = self.loop_name.take();
                let gives = std::mem::take(&mut self.loop_gives);
                self.push_scope();
                let result = self.check_parted(parted, named, gives, span);
                self.pop_scope();
                result
            }
            StmtKind::Named(name, inner) => {
                self.push_scope();
                let free = self.define(name, Type::Unknown, Mode::Fixed, span);
                self.pop_scope();
                if let Err(error) = free {
                    self.record(error);
                }
                self.loop_name = Some((name.clone(), span));
                let result = self.check_stmt(inner);
                self.loop_name = None;
                result
            }
            StmtKind::Break(name, value) => {
                let name = name.clone();
                self.check_jump("break", name.as_ref(), span)?;
                self.check_break_value(name.as_ref(), value.as_deref_mut())
            }
            StmtKind::Continue(name) => {
                let name = name.clone();
                self.check_jump("continue", name.as_ref(), span)
            }
            StmtKind::Turns(_) => Err(Error::internal_at(
                span,
                "a loop written out for a group's values, checked",
            )),
            StmtKind::Each(name, second, range, body, finally) => {
                let named = self.loop_name.take();
                let gives = std::mem::take(&mut self.loop_gives);
                let hidden = self.hide_value_loop(gives);
                self.each_iterator = None;
                let source = self.check_each_source(name, second.as_ref(), range);
                self.show_value_loop(hidden);
                let (item, value) = source?;
                // Iterator loops desugar into `endless` + `.next() { break }`, advance via `alters next`, and forbid value/finally forms.
                if self.each_iterator.take().is_some() {
                    if gives || finally.is_some() {
                        return err(
                            span,
                            "an 'each' over an iterator advances it: it gives no loop value and its end is a break, so a 'finally' never runs; gather what it gives with 'it.collect(r)', or use the iterator's other consumers",
                        );
                    }
                    self.loop_name = named;
                    self.loop_gives = gives;
                    let StmtKind::Each(name, _, range, body, finally) =
                        std::mem::replace(&mut stmt.kind, StmtKind::Turns(Vec::new()))
                    else {
                        return Err(Error::internal_at(span, "an each that is no longer one"));
                    };
                    // Bind rvalue iterators once before looping (`xs.map(...)`); re-read lvalue places (`it`, `box.it`) each pass.
                    let (head, source) = match range.kind {
                        ExprKind::Var(_)
                        | ExprKind::Field(..)
                        | ExprKind::Index(..)
                        | ExprKind::Deref(..) => (Vec::new(), range),
                        _ => {
                            let temp = format!("each__{}", self.each_count);
                            self.each_count += 1;
                            let bind = Stmt::new(
                                StmtKind::Binding {
                                    names: vec![Bound {
                                        name: temp.clone(),
                                        span,
                                        ty: None,
                                        ty_span: None,
                                        parts: Vec::new(),
                                    }],
                                    mode: Mode::Flex,
                                    reference: false,
                                    init: vec![range],
                                    colon: false,
                                },
                                span,
                            );
                            (vec![bind], Expr::new(ExprKind::Var(temp), span))
                        }
                    };
                    let next = Expr::new(
                        ExprKind::MethodCall {
                            value: Box::new(source),
                            name: "next".to_string(),
                            args: Vec::new(),
                            dotted: None,
                        },
                        span,
                    );
                    let until_none = Expr::new(
                        ExprKind::PlanB {
                            value: Box::new(next),
                            error: None,
                            body: vec![Stmt::new(StmtKind::Break(None, None), span)],
                        },
                        span,
                    );
                    let binding = Stmt::new(
                        StmtKind::Binding {
                            names: vec![Bound {
                                name,
                                span,
                                ty: None,
                                ty_span: None,
                                parts: Vec::new(),
                            }],
                            mode: Mode::Fixed,
                            reference: false,
                            init: vec![until_none],
                            colon: false,
                        },
                        span,
                    );
                    let mut passes = vec![binding];
                    passes.extend(body);
                    stmt.kind = StmtKind::Parted(Box::new(PartedLoop {
                        start: head,
                        cond: None,
                        step: Vec::new(),
                        body: passes,
                        finally,
                        endless: true,
                    }));
                    return self.check_stmt(stmt);
                }
                if name == DISCARD && value.is_none() {
                    return err(
                        span,
                        "'_' drops a map's key or value, as in 'each _, v in m'; a loop over this gives one item each pass, so name it",
                    );
                }
                let turn = match &range.ty {
                    Some(Type::Group(group)) => Some(group.clone()),
                    _ => None,
                };
                if let Some(group) = &turn {
                    if self.group_turns.iter().any(|(turned, _)| turned == group) {
                        return err(
                            range.span,
                            format!(
                                "this goes through the values of the group '{0}...' inside a loop through them, where '{0}' alone would be the type of two values at once; give the turn's value and the group on to a task of its own that goes through them, as in 'each_with(v, args...)'",
                                group
                            ),
                        );
                    }
                    self.group_turns.push((group.clone(), self.loops.len()));
                }
                let entry = self.unset.clone();
                self.loops.push(named);
                self.loop_scopes.push(self.scopes.len());
                self.push_scope();
                let mut each_names: Vec<Declared> =
                    vec![(name.clone(), span, item.clone(), Mode::Fixed)];
                if let (Some((second, at)), Some(value)) = (second.as_ref(), value.as_ref()) {
                    each_names.push((second.clone(), *at, value.clone(), Mode::Fixed));
                }
                self.bind_from(&each_names, range);
                let mut result = if name == DISCARD {
                    Ok(())
                } else {
                    self.define(name, item, Mode::Fixed, span)
                };
                if let (Ok(()), Some((second, at)), Some(value)) = (&result, second.as_ref(), value)
                    && second != DISCARD
                {
                    result = self.define(second, value, Mode::Fixed, *at);
                }
                let has_finally = finally.is_some();
                let mut body_given = None;
                let result = result.and_then(|()| {
                    if !gives {
                        return self.check_block(body);
                    }
                    let branches = if has_finally {
                        OPTIONAL_LOOP_BRANCHES
                    } else {
                        LOOP_BRANCHES
                    };
                    body_given = self.value_block_tail(body, span, branches)?;
                    Ok(())
                });
                self.pop_scope();
                self.loops.pop();
                self.loop_scopes.pop();
                self.unset = entry;
                if turn.is_some() {
                    self.group_turns.pop();
                }
                result?;
                match finally {
                    Some(finally) => self.check_finally(finally, gives, body, body_given, span),
                    None => {
                        self.loop_given = body_given;
                        Ok(())
                    }
                }
            }
            StmtKind::Match(expr, cases) => self.check_match(span, expr, cases, None).map(|_| ()),
            StmtKind::Send(values) => {
                if let Some(what) = self.at_start {
                    return err(
                        span,
                        format!(
                            "'<-' leaves a task, and {} are worked out where the program starts, outside every task; give a value instead, as in 'int(t) {{ 0 }}'",
                            what
                        ),
                    );
                }
                let ret = self.current_ret.clone().unwrap_or(Type::Nothing);
                let expected = ret.results();
                if values.is_empty() {
                    if !self.result_names.is_empty() {
                        return match self.first_unset() {
                            Some(name) => err(span, format!("'{}' might not be set here", name)),
                            None => Ok(()),
                        };
                    }
                    return match (sends_value(&ret), expected.len()) {
                        (false, _) => Ok(()),
                        (true, 1) => err(span, "expected a value after '<-'"),
                        (true, n) => err(
                            span,
                            format!(
                                "expected {} after '<-', one for each result",
                                count(n, "value")
                            ),
                        ),
                    };
                }
                let first = values.first().map_or(span, |value| value.span);
                if expected.is_empty() {
                    return err(
                        first,
                        "this task has no return type, so '<-' cannot take a value",
                    );
                }
                if let ([e], [ret]) = (values.as_mut_slice(), expected) {
                    let mut ret = ret.clone();
                    if let (ExprKind::Pipe(_), Type::Or(_, error)) = (&e.kind, &ret) {
                        self.pipe_target = Some((**error).clone());
                    }
                    self.loop_place = loop_value(e).map(|_| success_of(&ret));
                    self.prepare_shortcut_lambda(e, &ret)?;
                    let ety = self.check_expr(e);
                    self.pipe_target = None;
                    self.loop_place = None;
                    let ety = ety?;
                    if ret.unknown() {
                        ret = ety.clone();
                        if let Some(current_ret) = self.current_ret.as_mut() {
                            *current_ret = ety.clone();
                        }
                    }
                    if !sends_value(&ret)
                        && !matches!(ety, Type::Fail(_))
                        && !fits_regions(&ety, &ret)
                    {
                        return err(
                            e.span,
                            "this task sends no value when it succeeds; write a bare '<-', or '<- fail …' to send an error",
                        );
                    }
                    self.coerce(e, &ret)?;
                    self.note_sent(values);
                    return Ok(());
                }
                let expected = expected.to_vec();
                let given = self.value_types(values, expected.len(), span, false).map_err(|mut error| {
                    if let [Type::Tuple(_)] = expected.as_slice() {
                        error.message.push_str("; this task sends one tuple, so write its values in parentheses, as in '<- (a, b)'");
                    }
                    error
                })?;
                let forwarded = values.len() < expected.len();
                for (i, want) in expected.iter().enumerate() {
                    let Some(actual) = given.get(i).cloned() else {
                        continue;
                    };
                    match values.get_mut(i).filter(|_| !forwarded) {
                        Some(value) => self.coerce(value, want)?,
                        None => fits_or_err(&actual, want, first, Given::Sent)?,
                    }
                }
                self.note_sent(values);
                Ok(())
            }
            StmtKind::Region { names } => {
                for decl in names {
                    self.define_region(&decl.name, decl.span, true)?;
                    if decl.default {
                        self.set_default_region(&decl.name, decl.span)?;
                    }
                }
                Ok(())
            }
        }
    }

    fn check_when(
        &mut self,
        span: Span,
        arms: &mut [WhenArm],
        else_block: &mut Option<Block>,
        gives: Option<Branches>,
    ) -> Result<Option<Type>> {
        let last = arms.len().saturating_sub(1);
        for (i, arm) in arms.iter().enumerate() {
            if let Some(pattern) = &arm.cond.pattern
                && always_holds(&arm.cond)
                && (i < last || else_block.is_some())
            {
                let after = if i < last {
                    "the arms after it"
                } else {
                    "its 'else'"
                };
                return err(
                    pattern.span,
                    format!(
                        "a tuple's items always match, so this 'when' always holds and {} would never run; take the tuple apart with 'fixed' instead",
                        after
                    ),
                );
            }
        }
        if gives.is_some() && else_block.is_none() {
            return err(
                span,
                "a 'when' used as a value needs an 'else': without one, nothing gives the value when the condition doesn't hold",
            );
        }
        let entry = self.unset.clone();
        let mut all_moved = self.moved.clone();
        let mut given = Vec::new();
        let mut states = Vec::new();
        for (i, arm) in arms.iter_mut().enumerate() {
            let value = match gives {
                None => self
                    .check_condition(&mut arm.cond, &mut arm.body, None)
                    .map(|_| None)?,
                Some(_) => {
                    let found = self.check_condition(&mut arm.cond, &mut arm.body, gives);
                    self.note_branch(found, arm.span)
                }
            };
            all_moved.extend(self.moved.iter().cloned());
            given.extend(value.map(|(ty, at)| (i, ty, at)));
            let state = self.branch_state(&arm.body, &entry);
            states.push(state.filter(|_| known_condition(&arm.cond) != Some(false)));
        }
        match else_block {
            Some(else_b) => {
                let value = match gives {
                    Some(branches) => {
                        let found = self.check_value_block(Vec::new(), else_b, span, branches);
                        self.note_branch(found, span)
                    }
                    None => self.check_scoped_block(else_b).map(|()| None)?,
                };
                all_moved.extend(self.moved.iter().cloned());
                given.extend(value.map(|(ty, at)| (arms.len(), ty, at)));
                states.push(self.branch_state(else_b, &entry));
            }
            None if arms
                .iter()
                .any(|arm| known_condition(&arm.cond) == Some(true)) => {}
            None => states.push(Some(entry.clone())),
        }
        self.moved = all_moved;
        self.join_branches(entry, states);
        let Some(branches) = gives else {
            return Ok(None);
        };
        let settled = self.settle_branches(span, &given, branches)?;
        let Some(settled) = settled else {
            return Ok(None);
        };
        let settled = self.made_kinds(settled, span)?;
        for (i, _, _) in given
            .iter()
            .filter(|(_, ty, _)| !ty.unknown() && *ty != settled)
        {
            match (arms.get_mut(*i), else_block.as_mut()) {
                (Some(arm), _) => self.settle_value(&mut arm.body, &settled)?,
                (None, Some(else_b)) => self.settle_value(else_b, &settled)?,
                (None, None) => {}
            }
        }
        self.escaping_region(span, &given, &settled, branches)?;
        Ok(Some(settled))
    }

    fn note_branch(
        &mut self,
        found: Result<Option<(Type, Span)>>,
        at: Span,
    ) -> Option<(Type, Span)> {
        match found {
            Ok(value) => value,
            Err(error) => {
                self.record(error);
                Some((Type::Unknown, at))
            }
        }
    }

    /// Run after block scope closes so locals in block-local regions cannot escape as the branch result.
    fn settle_value(&mut self, block: &mut Block, settled: &Type) -> Result<()> {
        let Some(last) = block.last_mut() else {
            return Ok(());
        };
        match &mut last.kind {
            StmtKind::Expr(e) if e.ty.is_none() => Ok(()),
            StmtKind::Expr(e) => self.coerce(e, settled),
            _ => self.settle_branch_values(last, settled),
        }
    }

    /// Push coercion into `Choice` arms so `none` or `fail e` arms coerce independently.
    fn settle_branch_values(&mut self, stmt: &mut Stmt, settled: &Type) -> Result<()> {
        match &mut stmt.kind {
            StmtKind::When(arms, Some(else_block)) => {
                for arm in arms.iter_mut() {
                    self.settle_value(&mut arm.body, settled)?;
                }
                self.settle_value(else_block, settled)
            }
            StmtKind::Match(_, cases) => cases
                .iter_mut()
                .try_for_each(|case| self.settle_value(&mut case.body, settled)),
            _ => Ok(()),
        }
    }

    fn escaping_region(
        &mut self,
        at: Span,
        given: &[(usize, Type, Span)],
        settled: &Type,
        branches: Branches,
    ) -> Result<()> {
        let escaping = settled
            .regions()
            .into_iter()
            .find(|region| !unnamed_region(region) && self.lookup(region).is_none());
        match escaping {
            Some(region) => err(
                given
                    .iter()
                    .find(|(_, ty, _)| ty.regions().contains(&region))
                    .map_or(at, |(_, _, span)| *span),
                format!(
                    "this value is in region '{}', which is freed when the {} ends, so it can't be the {}'s value",
                    region, branches.each, branches.of
                ),
            ),
            None => Ok(()),
        }
    }

    fn check_condition(
        &mut self,
        cond: &mut Condition,
        body: &mut Block,
        gives: Option<Branches>,
    ) -> Result<Option<(Type, Span)>> {
        let narrowed = self.narrowed.len();
        let result = self.check_condition_parts(cond, body, gives);
        self.narrowed.truncate(narrowed);
        let result = result?;
        self.settle_type_tests(cond, body);
        Ok(result)
    }

    fn check_condition_parts(
        &mut self,
        cond: &mut Condition,
        body: &mut Block,
        gives: Option<Branches>,
    ) -> Result<Option<(Type, Span)>> {
        if !cond.single() {
            let at = cond.value.span;
            self.push_scope();
            let result = self.check_parts(cond).and_then(|()| match gives {
                Some(branches) => self.check_value_block(Vec::new(), body, at, branches),
                None => self.check_scoped_block(body).map(|()| None),
            });
            self.pop_scope();
            return result;
        }
        let found = self.check_expr(&mut cond.value);
        let ty = self.or_unknown(found);
        let Some(pattern) = &mut cond.pattern else {
            self.expect_type(&ty, &Type::Bool, cond.value.span)?;
            return match gives {
                Some(branches) => {
                    self.check_value_block(Vec::new(), body, cond.value.span, branches)
                }
                None => self.check_scoped_block(body).map(|()| None),
            };
        };
        if matches!(pattern.kind, PatternKind::Any) {
            return err(
                pattern.span,
                "'_' matches anything, so this condition would always hold",
            );
        }
        let bindings = self.part_bindings(&ty, &mut cond.value, pattern)?;
        self.bind_from(&bindings, &cond.value);
        match gives {
            Some(branches) => self.check_value_block(bindings, body, pattern.span, branches),
            None => self.check_block_with(bindings, body).map(|()| None),
        }
    }

    fn check_parts(&mut self, cond: &mut Condition) -> Result<()> {
        let mut part = Some(cond);
        while let Some(current) = part {
            let found = self.check_expr(&mut current.value);
            let ty = self.or_unknown(found);
            match &mut current.pattern {
                None => self.expect_type(&ty, &Type::Bool, current.value.span)?,
                Some(pattern) if matches!(pattern.kind, PatternKind::Any) => {
                    return err(
                        pattern.span,
                        "'_' matches anything, so this condition would always hold",
                    );
                }
                Some(pattern) => {
                    let bindings = self.part_bindings(&ty, &mut current.value, pattern)?;
                    self.bind_from(&bindings, &current.value);
                    for (name, span, ty, mode) in bindings {
                        if name != DISCARD {
                            self.define(&name, ty, mode, span)?;
                        }
                    }
                }
            }
            part = current.and.as_deref_mut();
        }
        Ok(())
    }

    fn check_value_block(
        &mut self,
        bindings: Vec<Declared>,
        body: &mut Block,
        at: Span,
        branches: Branches,
    ) -> Result<Option<(Type, Span)>> {
        self.push_scope();
        let result = bindings
            .into_iter()
            .filter(|(name, _, _, _)| name != DISCARD)
            .try_for_each(|(name, span, ty, mode)| self.define(&name, ty, mode, span))
            .and_then(|()| self.value_block_tail(body, at, branches));
        self.pop_scope();
        result
    }

    fn check_expr_stmt(&self, e: &Expr) -> Result<()> {
        match &e.kind {
            ExprKind::Call { name, .. } if matches!(e.ty, Some(Type::Or(..))) => {
                err(e.span, ignored_error(name))
            }
            ExprKind::Invoke { callee, .. } if matches!(e.ty, Some(Type::Or(..))) => {
                let name = match &callee.kind {
                    ExprKind::Var(name) => name.clone(),
                    _ => "this task".to_string(),
                };
                err(e.span, ignored_error(&name))
            }
            ExprKind::Invoke { .. } => Ok(()),
            ExprKind::Pipe(call) if matches!(e.ty, Some(Type::Or(..))) => err(
                e.span,
                format!(
                    "the error this pipe may fail with is ignored; handle it with a plan B after its last step, as in '… |> {}(…) {{ failure e … }}', or with match",
                    piped_name(call)
                ),
            ),
            ExprKind::Pipe(_) => Ok(()),
            ExprKind::Call { name, .. } if number_cast(name).is_some() => err(
                e.span,
                format!(
                    "the number '{}' gives is unused; only a task call can be used as a statement",
                    name
                ),
            ),
            ExprKind::Scan { .. } if matches!(e.ty, Some(Type::Or(..))) => {
                err(e.span, ignored_error(SCAN))
            }
            ExprKind::Call { .. } | ExprKind::Edit { .. } | ExprKind::Scan { .. } => Ok(()),
            ExprKind::MethodCall { .. } => Ok(()),
            ExprKind::PlanB { value, .. }
                if e.ty == Some(Type::Nothing)
                    || matches!(
                        value.kind,
                        ExprKind::Call { .. }
                            | ExprKind::Scan { .. }
                            | ExprKind::MethodCall { .. }
                            | ExprKind::LoopValue(_)
                    ) =>
            {
                Ok(())
            }
            ExprKind::Binary(BinaryOp::Eq, ..) => {
                err(e.span, "the result of '==' is unused; use '=' to assign")
            }
            ExprKind::Copy { value, .. } if matches!(&value.kind, ExprKind::Edit { op, .. } if op.makes_copy()) =>
            {
                let ExprKind::Edit { items, op, .. } = &value.kind else {
                    return Ok(());
                };
                let map = matches!(items.ty, Some(Type::Map(..)));
                let what = if map { "map" } else { "slice" };
                let change = match (op, map) {
                    (EditOp::Added, true) => "'m[k] = v'".to_string(),
                    (_, true) => format!("'{}.del(…)'", self.value_text(items)),
                    (EditOp::Added, false) => format!("'{}.add(…)'", self.value_text(items)),
                    (_, false) => format!("'{}.del(…)'", self.value_text(items)),
                };
                err(
                    e.span,
                    format!(
                        "'{0}' makes a new {1} and leaves '{2}' as it was, so on a line of its own it does nothing; keep the new one, as in 'fixed changed = {2}.{0}(…) at r', or change the {1} itself with {3}",
                        op.word(),
                        what,
                        self.value_text(items),
                        change
                    ),
                )
            }
            ExprKind::Fail(_) => err(
                e.span,
                "'fail …' makes a failure, which a line of its own drops; send it with '<- fail …', or stop a loop that gives a value with 'break = …'",
            ),
            _ => err(
                e.span,
                "this value is unused; only a task call can be used as a statement",
            ),
        }
    }

    fn value_block_tail(
        &mut self,
        body: &mut Block,
        at: Span,
        branches: Branches,
    ) -> Result<Option<(Type, Span)>> {
        let Some((last, rest)) = body.split_last_mut() else {
            if branches.optional {
                return Ok(None);
            }
            return err(at, branches.needs_value());
        };
        last_loop_gives(last);
        self.check_block(rest)?;
        // Value-block tail `when`/`match` transfers values through arms unless all arms diverge via `<-`/`break`/`continue`.
        if gives_value(last) && always_leaves(std::slice::from_ref(last)) {
            self.check_stmt(last)?;
            return Ok(None);
        }
        if gives_value(last) && !branches.optional {
            let span = last.span;
            return Ok(self.check_branching_value(last)?.map(|ty| (ty, span)));
        }
        if let StmtKind::Expr(e) = &mut last.kind {
            let ty = self.check_expr(e)?;
            if ty == Type::Nothing {
                if branches.optional {
                    self.check_expr_stmt(e)?;
                    return Ok(None);
                }
                return err(
                    e.span,
                    format!(
                        "the last line of a {} gives its value, but this has none",
                        branches.each
                    ),
                );
            }
            return Ok(Some((ty, e.span)));
        }
        self.check_stmt(last)?;
        if !always_leaves(body) {
            if branches.optional {
                return Ok(None);
            }
            return err(at, branches.needs_value());
        }
        Ok(None)
    }

    fn check_branching_value(&mut self, stmt: &mut Stmt) -> Result<Option<Type>> {
        let span = stmt.span;
        match &mut stmt.kind {
            StmtKind::When(arms, else_block) => {
                self.check_when(span, arms, else_block, Some(WHEN_BRANCHES))
            }
            StmtKind::Match(subject, cases) => {
                self.check_match(span, subject, cases, Some(MATCH_BRANCHES))
            }
            _ => Err(Error::internal_at(
                span,
                "a statement that is not a 'when' or a 'match' used as a value",
            )),
        }
    }

    fn settle_branches(
        &self,
        at: Span,
        given: &[(usize, Type, Span)],
        branches: Branches,
    ) -> Result<Option<Type>> {
        let mut settled: Option<Type> = None;
        for (_, ty, _) in given.iter().filter(|(_, ty, _)| !ty.unknown()) {
            let Some(sofar) = &settled else {
                settled = Some(ty.clone());
                continue;
            };
            match self.join(sofar, ty) {
                Some(joined) => settled = Some(joined),
                None => break,
            }
        }
        if let Some(ty) = &settled
            && unsettled(ty)
            && given.iter().any(|(_, ty, _)| ty.unknown())
        {
            return Ok(None);
        }
        let Some(settled) = settled else {
            if given.is_empty() {
                return err(
                    at,
                    format!(
                        "every {} of this {} leaves, with '<-', 'break' or 'continue', so nothing gives it a value",
                        branches.each, branches.of
                    ),
                );
            }
            return Ok(None);
        };
        for (_, ty, span) in given.iter().filter(|(_, ty, _)| !ty.unknown()) {
            if !fits(ty, &settled) && self.join(ty, &settled).as_ref() != Some(&settled) {
                return err(
                    *span,
                    format!(
                        "this {} gives {}, and another gives {}; every {} of a {} used as a value gives one type",
                        branches.each, ty, settled, branches.each, branches.of
                    ),
                );
            }
        }
        Ok(Some(settled))
    }

    /// Pattern bindings for `value is pattern`, handling tuple-item type tests and past-end `none`.
    fn part_bindings(
        &mut self,
        ty: &Type,
        value: &mut Expr,
        pattern: &mut Pattern,
    ) -> Result<Vec<Declared>> {
        let at = pattern.span;
        if let PatternKind::Typed {
            ty: written, form, ..
        } = &mut pattern.kind
        {
            let (resolved, bindings) = self.type_test_bindings(value, written, form, at)?;
            *written = resolved;
            return Ok(bindings);
        }
        if matches!(pattern.kind, PatternKind::None) && past_end(value) {
            value.ty = Some(Type::None);
            self.coerce(value, &Type::Maybe(Box::new(Type::Bool)))?;
            return Ok(Vec::new());
        }
        self.pattern_bindings(ty, pattern, false)
    }

    fn type_test_bindings(
        &mut self,
        value: &Expr,
        written: &Type,
        form: &TypedForm,
        at: Span,
    ) -> Result<(Type, Vec<Declared>)> {
        let Some((tuple, place)) = safe_read_of(value) else {
            return err(value.span, TYPE_TEST_ON_A_READ);
        };
        let Type::Maybe(wanted) = self.resolve_type(written, at, TypePlace::Body)? else {
            let held = match written {
                Type::Or(value, error) => match &**value {
                    Type::Maybe(inner) => format!("({} ~ {})", inner, error),
                    _ => format!("({})", written),
                },
                _ => written.to_string(),
            };
            return err(
                at,
                format!(
                    "a tuple's item read with '.#' is a maybe, so its type is written as one, as in 'maybe {}'",
                    held
                ),
            );
        };
        if !wanted.params().is_empty() {
            return err(
                at,
                format!(
                    "a type test names a type the program knows, such as 'maybe int'; '{}' is given by each use",
                    wanted
                ),
            );
        }
        // Concrete tuple items retain their region; unknown (`group`/generic) items get `UNNAMED_REGION` so borrows cannot escape.
        let held = match item_state(value) {
            Some(Some(found)) if same_ignoring_regions(&found, &wanted) => found,
            Some(_) => (*wanted).clone(),
            None => self.in_region(&wanted.without_regions(), UNNAMED_REGION),
        };
        self.narrowed.push((tuple, place, held.clone()));
        let bindings = match form {
            TypedForm::Only => Vec::new(),
            TypedForm::Named(names) if !names.parts.is_empty() => {
                return err(
                    names.span,
                    "the read is a maybe, so one name takes it; to take the item apart, write it in braces, as in 'is maybe (int, text) {(a, b)}'",
                );
            }
            TypedForm::Named(names) => vec![(
                names.name.clone(),
                names.span,
                Type::Maybe(Box::new(held)),
                names.mode,
            )],
            TypedForm::Value(names) => self.bound_names(names, &held, Mode::Fixed)?,
        };
        Ok(((Type::Maybe(wanted)), bindings))
    }

    /// Constant-folds tuple-item type tests when concrete item types are known; falsified branches drop their body.
    fn settle_type_tests(&mut self, cond: &mut Condition, body: &mut Block) {
        let mut part = Some(cond);
        while let Some(current) = part {
            if let Some(Pattern {
                kind: PatternKind::Typed { ty, form, .. },
                ..
            }) = &current.pattern
            {
                let Type::Maybe(wanted) = ty else { return };
                let Some(state) = item_state(&current.value) else {
                    return;
                };
                let holds = match (&state, form) {
                    (None, TypedForm::Value(_)) => false,
                    (None, _) => true,
                    (Some(found), _) => same_ignoring_regions(found, wanted),
                };
                let span = current.value.span;
                if !holds {
                    let mut never = Expr::new(ExprKind::BoolLit(false), span);
                    never.ty = Some(Type::Bool);
                    current.value = never;
                    current.pattern = None;
                    current.and = None;
                    body.clear();
                    return;
                }
                match form.clone() {
                    TypedForm::Only => {
                        let mut always = Expr::new(ExprKind::BoolLit(true), span);
                        always.ty = Some(Type::Bool);
                        current.value = always;
                        current.pattern = None;
                    }
                    TypedForm::Named(names) => {
                        let held = state.clone().unwrap_or_else(|| (**wanted).clone());
                        let read = std::mem::replace(
                            &mut current.value,
                            Expr::new(ExprKind::NoneLit, span),
                        );
                        current.value = match read.kind {
                            ExprKind::Wrap(_) => read,
                            _ => Expr {
                                kind: ExprKind::Wrap(Box::new(Expr {
                                    ty: Some(Type::None),
                                    ..read
                                })),
                                span,
                                ty: None,
                            },
                        };
                        current.value.ty = Some(Type::Maybe(Box::new(held)));
                        if let Some(pattern) = &mut current.pattern {
                            pattern.kind = PatternKind::Tuple(names);
                        }
                    }
                    TypedForm::Value(names) => {
                        if let Some(pattern) = &mut current.pattern {
                            pattern.kind = PatternKind::Value(names);
                        }
                    }
                }
            }
            part = current.and.as_deref_mut();
        }
    }

    fn pattern_bindings(
        &self,
        subject: &Type,
        pattern: &Pattern,
        in_case: bool,
    ) -> Result<Vec<Declared>> {
        let span = pattern.span;
        if subject.unknown() {
            return Ok(pattern
                .bindings()
                .into_iter()
                .map(|names| (names.name.clone(), names.span, Type::Unknown, names.mode))
                .collect());
        }
        if let PatternKind::Value(names) | PatternKind::Fail(names) = &pattern.kind
            && names.parts.is_empty()
            && self.variant_in_scope(&names.name).is_some()
        {
            let (keyword, whole) = if matches!(pattern.kind, PatternKind::Fail(_)) {
                ("failure e", "error")
            } else {
                ("{value}", "value")
            };
            return err(
                names.span,
                format!(
                    "'{}' is a variant, but '{}' names the whole {}; give it a name, then match on it",
                    names.name, keyword, whole
                ),
            );
        }
        match (&pattern.kind, subject) {
            (PatternKind::Any | PatternKind::None, Type::Maybe(_)) => Ok(Vec::new()),
            (PatternKind::Any, _) => Ok(Vec::new()),
            (PatternKind::Variant { kind, tag, binds }, Type::Named(kind_name, region))
                if self.kinds.contains_key(kind_name) =>
            {
                let from = self
                    .made_of
                    .get(kind_name)
                    .map_or(kind_name.as_str(), |made| made.name.as_str());
                if let Some((written, at)) = kind.as_deref()
                    && written != from
                {
                    return err(
                        *at,
                        format!(
                            "this case form names kind '{}', but the value's kind is '{}'",
                            written, kind_name
                        ),
                    );
                }
                let variant = self
                    .kinds
                    .get(kind_name)
                    .and_then(|kind| kind.variants.iter().find(|v| v.tag == *tag))
                    .ok_or_else(|| {
                        Error::at(
                            span,
                            format!("kind '{}' has no variant '{}'", kind_name, tag),
                        )
                    })?;
                if binds.len() != variant.payload.len() {
                    let what = if in_case {
                        format!("case '{}'", tag)
                    } else {
                        format!("'{}'", tag)
                    };
                    return err(
                        span,
                        format!(
                            "{} expects {}, got {}",
                            what,
                            count(variant.payload.len(), "binding"),
                            binds.len()
                        ),
                    );
                }
                binds
                    .iter()
                    .zip(&variant.payload)
                    .map(|(names, field)| {
                        self.bound_names(names, &self.field_in(&field.ty, region), Mode::Fixed)
                    })
                    .collect::<Result<Vec<_>>>()
                    .map(|bound| bound.concat())
            }
            (PatternKind::Variant { kind, tag, binds }, Type::Applied(applied))
                if self.kinds.contains_key(&applied.name) =>
            {
                if let Some((written, at)) = kind.as_deref()
                    && *written != applied.name
                {
                    return err(
                        *at,
                        format!(
                            "this case form names kind '{}', but the value's kind is '{}'",
                            written, subject
                        ),
                    );
                }
                let def = self
                    .kinds
                    .get(&applied.name)
                    .cloned()
                    .unwrap_or_else(|| KindDef {
                        name: String::new(),
                        types: Vec::new(),
                        given: Vec::new(),
                        variants: Vec::new(),
                        span,
                        private: false,
                        imitates: Vec::new(),
                        follows: Vec::new(),
                        imitated: 0,
                    });
                let variant = def.variants.iter().find(|v| v.tag == *tag).ok_or_else(|| {
                    Error::at(
                        span,
                        format!("kind '{}' has no variant '{}'", applied.name, tag),
                    )
                })?;
                if binds.len() != variant.payload.len() {
                    let what = if in_case {
                        format!("case '{}'", tag)
                    } else {
                        format!("'{}'", tag)
                    };
                    return err(
                        span,
                        format!(
                            "{} expects {}, got {}",
                            what,
                            count(variant.payload.len(), "binding"),
                            binds.len()
                        ),
                    );
                }
                let names: HashMap<&str, &Type> = def
                    .types
                    .iter()
                    .map(|param| param.name.as_str())
                    .zip(&applied.types)
                    .collect();
                binds
                    .iter()
                    .zip(&variant.payload)
                    .map(|(names_bound, field)| {
                        let ty = field
                            .ty
                            .map_params(&mut |param| names.get(param).map(|ty| (*ty).clone()));
                        self.bound_names(
                            names_bound,
                            &self.field_in(&ty, &applied.region),
                            Mode::Fixed,
                        )
                    })
                    .collect::<Result<Vec<_>>>()
                    .map(|bound| bound.concat())
            }
            (
                PatternKind::Variant {
                    kind: Some(written),
                    tag,
                    ..
                },
                other,
            ) => {
                let (kind, at) = &**written;
                match self.kinds.get(kind) {
                    Some(declared) if declared.variants.iter().any(|v| v.tag == *tag) => err(
                        span,
                        format!(
                            "'{}' is a variant of kind '{}', but this value is {}",
                            tag, kind, other
                        ),
                    ),
                    _ => err(*at, format!("kind '{}' has no variant '{}'", kind, tag)),
                }
            }
            (PatternKind::Variant { tag, .. }, other) => {
                if self.variant_in_scope(tag).is_some() {
                    err(
                        span,
                        format!("'{}' is a variant, but this value is {}", tag, other),
                    )
                } else if BUILTIN_TYPE_WORDS.contains(&tag.as_str()) {
                    err(
                        span,
                        format!(
                            "unknown variant '{0}'; a type is tested on a tuple's item read with '.#', which is a maybe, as in 'is maybe {0} {{x}}'",
                            tag
                        ),
                    )
                } else {
                    err(span, format!("unknown variant '{}'", tag))
                }
            }
            (PatternKind::Value(names), Type::Maybe(inner)) => {
                self.bound_names(names, inner, Mode::Fixed)
            }
            (PatternKind::Value(names), Type::Or(value, _)) => {
                if **value == Type::Nothing && names.name != DISCARD {
                    return err(names.span, "this success has no value to name; write '{_}'");
                }
                self.bound_names(names, value, Mode::Fixed)
            }
            (PatternKind::Fail(names), Type::Or(_, error)) => {
                self.bound_names(names, error, Mode::Fixed)
            }
            (PatternKind::Tuple(names), _) => self.bound_names(names, subject, Mode::Fixed),
            (PatternKind::Value(_), other) => err(
                span,
                format!(
                    "'{{…}}' matches the value in a maybe or a 'T ~ E', but this value is {}",
                    other
                ),
            ),
            (PatternKind::Typed { .. }, _) => err(span, TYPE_TEST_ON_A_READ),
            (PatternKind::None, Type::None) => err(
                span,
                "this value is always none, so there is nothing to match",
            ),
            (PatternKind::None, other) => err(
                span,
                format!("'none' matches an empty maybe, but this value is {}", other),
            ),
            (PatternKind::Fail(_), other) => err(
                span,
                format!(
                    "'failure …' matches the error of a 'T ~ E', but this value is {}",
                    other
                ),
            ),
        }
    }

    fn bound_names(&self, names: &Names, ty: &Type, mode: Mode) -> Result<Vec<Declared>> {
        let mode = if names.mode.can_change_contents(true) {
            names.mode
        } else {
            mode
        };
        if names.parts.is_empty() {
            return Ok(vec![(names.name.clone(), names.span, ty.clone(), mode)]);
        }
        let items = self.tuple_items(ty, names.parts.len(), names.span)?;
        names
            .parts
            .iter()
            .zip(&items)
            .map(|(part, item)| self.bound_names(part, item, mode))
            .collect::<Result<Vec<_>>>()
            .map(|bound| bound.concat())
    }

    fn check_assign_target(&mut self, expr: &mut Expr) -> Result<Type> {
        self.check_place_target(expr, true)
    }

    fn check_place_target(&mut self, expr: &mut Expr, sets_key: bool) -> Result<Type> {
        let written = self.written_text(expr);
        let ty = self.check_written(expr, &written, sets_key)?;
        self.hand_written(expr, None);
        Ok(ty)
    }

    fn check_written(&mut self, expr: &mut Expr, written: &str, sets_key: bool) -> Result<Type> {
        let span = expr.span;
        match &mut expr.kind {
            ExprKind::Var(name) => {
                let info = self.lookup_or_err(name, span)?;
                if info.result {
                    return err(
                        span,
                        format!("'{0}' is a result; set it with '{0} <- …'", name),
                    );
                }
                if !info.mode.can_assign() {
                    if name == THIS {
                        return Err(self.this_cannot_change(span, &format!("assigning '{}'", THIS)));
                    }
                    let message = if info.mode == Mode::Bind {
                        format!(
                            "cannot assign to 'bind' variable '{}' as a whole; a 'bind' name stays bound to one value",
                            name
                        )
                    } else {
                        format!(
                            "cannot assign to immutable variable '{}'{}",
                            name,
                            self.param_hint(name, info)
                        )
                    };
                    return err(span, message);
                }

                let ty = info.ty.clone();
                expr.ty = Some(ty.clone());
                Ok(ty)
            }
            ExprKind::Field(base, field) => {
                if matches!(&base.kind, ExprKind::Var(name) if name == THIS)
                    && !self
                        .lookup(THIS)
                        .is_some_and(|info| info.mode.can_change_contents(true))
                {
                    return Err(self.this_cannot_change(
                        span,
                        &format!("assigning '{}{}'", MODULE_SEPARATOR, field),
                    ));
                }
                let base_ty = self.check_field_base(base, written)?;
                let ty = self.field_type(&base_ty, field, span)?;
                self.read_only_field(&base_ty, field, span)?;
                match base_ty {
                    Type::Tuple(_) => {
                        return err(
                            span,
                            "a tuple's items never change; give the whole tuple a new value instead, as in 't = (1, 2)'",
                        );
                    }
                    Type::Array(..) => {
                        return err(
                            span,
                            "'len' can't be assigned: an array's length is part of its type",
                        );
                    }
                    Type::Slice(..) => {
                        return err(
                            span,
                            "'len' can't be assigned: a slice's length changes with 'xs.add(…)' and 'xs.del(…)', or by slicing it, as in 'xs = xs[0..2]'",
                        );
                    }
                    Type::Map(..) => {
                        return err(
                            span,
                            "'len' can't be assigned: it is how many keys the map holds, which 'm[k] = v' and 'm.del(k)' change",
                        );
                    }
                    Type::Text(_) => {
                        return err(
                            span,
                            "'len' can't be assigned: it is how many bytes the text has, and text never changes; give the variable other text instead",
                        );
                    }
                    _ => {}
                }
                expr.ty = Some(ty.clone());
                Ok(ty)
            }
            ExprKind::Deref(pointer) => {
                self.written_through(pointer, written, None)?;
                self.check_expr(expr)
            }
            ExprKind::Shared { shape, field } => {
                let (shape, field) = (shape.clone(), field.clone());
                let ty = self.check_expr(expr)?;
                self.changeable_shared(&shape, &field, span, "", true)?;
                Ok(ty)
            }
            ExprKind::Index(base, index) => {
                if matches!(index.kind, ExprKind::Range(..)) {
                    match self.check_expr(base)? {
                        Type::Text(_) => {
                            return err(
                                span,
                                "a part of text can't be assigned, since text never changes; give the variable other text instead, as in 't = t[0..2]'",
                            );
                        }
                        Type::Map(..) => {
                            return err(
                                span,
                                "a map has no parts: '[…]' takes one key, as in 'm[k] = v'",
                            );
                        }
                        _ => {}
                    }
                    return err(
                        span,
                        "a slice of values can't be assigned; assign its items one at a time, as in 'xs[i] = v'",
                    );
                }
                let base_ty = self.check_item_base(base, written, sets_key)?;
                if matches!(base_ty, Type::Text(_)) {
                    return err(
                        span,
                        "a byte of text can't be assigned, since text never changes; build other text instead, as in 't = t[0..2] + \"x\" at r'",
                    );
                }
                let ty = self.check_index(base, &base_ty, index, span)?;
                if let Type::Map(key, _, _) = &base_ty {
                    self.coerce(index, key)?;
                }
                expr.ty = Some(ty.clone());
                Ok(ty)
            }
            ExprKind::Lookup(..) => err(
                span,
                "'[#…]' gives the item in a maybe, a value made here, not the place it is in; assign the item with 'xs[i] = v'",
            ),
            _ => err(
                span,
                "only a variable, a field, an item of an array or slice, or the value a pointer points to (p^) can be assigned",
            ),
        }
    }

    /// Forbids mutating `read` fields or their contents outside the owning shape's `alters` methods.
    fn read_only_field(&self, base: &Type, field: &str, span: Span) -> Result<()> {
        if let Some(owner) = self
            .owner_of(base)
            .filter(|owner| self.current_owner.as_ref() != Some(owner))
            && self
                .declared_field(&owner, field)
                .is_some_and(|declared| declared.read)
        {
            return err(
                span,
                format!(
                    "'{}' is a read-only field of '{1}', which only the alters methods of '{1}' change",
                    field, owner
                ),
            );
        }
        Ok(())
    }

    fn check_item_base(&mut self, base: &mut Expr, written: &str, sets_key: bool) -> Result<Type> {
        if let ExprKind::Var(name) = &base.kind {
            let info = self.lookup_or_err(name, base.span)?;
            if matches!(info.ty, Type::Array(..)) || (sets_key && matches!(info.ty, Type::Map(..)))
            {
                if info.result {
                    return err(
                        base.span,
                        format!("'{0}' is a result; set it with '{0} <- …'", name),
                    );
                }
                let has_contents = self.bind_has_contents(&info.ty);
                if !info.mode.can_change_contents(has_contents) && matches!(info.ty, Type::Map(..))
                {
                    let hint = match self.param_hint(name, info) {
                        hint if hint.is_empty() => {
                            "; keep the map in a 'flex' variable to change it".to_string()
                        }
                        hint => hint,
                    };
                    return err(
                        base.span,
                        format!("'m[k] = v' changes '{}', which is immutable{}", name, hint),
                    );
                }
                if !info.mode.can_change_contents(has_contents) {
                    return err(
                        base.span,
                        format!(
                            "cannot assign to an item of immutable variable '{}'{}",
                            name,
                            self.param_hint(name, info)
                        ),
                    );
                }
            }
            let ty = self.check_expr(base)?;
            if matches!(ty, Type::Slice(..) | Type::Map(..)) {
                self.written_through(base, written, None)?;
            }
            return Ok(ty);
        }
        let ty = self.check_expr(base)?;
        if matches!(ty, Type::Array(..) | Type::Map(..)) {
            self.assignable_array(base, written)?;
        }
        if matches!(ty, Type::Slice(..)) {
            self.written_through(base, written, None)?;
        }
        Ok(ty)
    }

    fn assignable_array(&self, place: &Expr, written: &str) -> Result<()> {
        match &place.kind {
            ExprKind::Var(name) => {
                let info = self.lookup_or_err(name, place.span)?;
                if info.result {
                    return err(
                        place.span,
                        format!("'{0}' is a result; set it with '{0} <- …'", name),
                    );
                }
                if !info
                    .mode
                    .can_change_contents(self.bind_has_contents(&info.ty))
                {
                    return err(
                        place.span,
                        format!(
                            "cannot assign to an item of immutable variable '{}'{}",
                            name,
                            self.param_hint(name, info)
                        ),
                    );
                }
                Ok(())
            }
            ExprKind::Deref(pointer) => self.written_through(pointer, written, None),
            ExprKind::Shared { shape, field } => {
                self.changeable_shared(shape, field, place.span, "", false)
            }
            ExprKind::Field(base, field) => {
                if let Some(ty) = &base.ty {
                    self.read_only_field(ty, field, place.span)?;
                }
                self.assignable_array(base, written)
            }
            ExprKind::Index(base, _)
                if matches!(base.ty, Some(Type::Slice(..) | Type::Map(..))) =>
            {
                self.written_through(base, written, None)
            }
            ExprKind::Index(base, _) => self.assignable_array(base, written),
            _ => err(place.span, "cannot assign to an item of a temporary value"),
        }
    }

    /// Rejects mutating pointers/slices/maps rooted at `fixed` bindings, `fixed&`, non-`flex` params, or non-`alters` `this`.
    fn written_through(&self, place: &Expr, written: &str, method: Option<&str>) -> Result<()> {
        match &place.kind {
            ExprKind::Var(name) => {
                let info = self.lookup_or_err(name, place.span)?;
                if info
                    .mode
                    .can_change_contents(self.bind_has_contents(&info.ty))
                    || info.result
                {
                    return Ok(());
                }
                if name == THIS {
                    let what = match method {
                        Some(method) => format!("calling '{}' on '{}'", method, written),
                        None => format!("writing '{}'", written),
                    };
                    return Err(self.this_cannot_change(place.span, &what));
                }
                let change = match method {
                    Some(method) => format!(
                        "'{}' changes '{}', the value it is called on, and",
                        method, written
                    ),
                    None => format!("cannot change '{}':", written),
                };
                if info.mode == Mode::Hold {
                    return err(
                        place.span,
                        format!(
                            "{} cannot change contents of 'hold' variable '{}'; 'hold' allows reassigning the variable by whole, not its contents",
                            change, name
                        ),
                    );
                }
                err(
                    place.span,
                    format!(
                        "{} nothing changes through immutable variable '{}', at any depth{}",
                        change,
                        name,
                        self.param_hint(name, info)
                    ),
                )
            }
            ExprKind::Field(base, _) | ExprKind::Index(base, _) | ExprKind::Deref(base) => {
                self.written_through(base, written, method)
            }
            ExprKind::Shared { shape, field } => {
                self.changeable_shared(shape, field, place.span, "", false)
            }
            _ => Ok(()),
        }
    }

    /// Provenance analysis over `fixed`-owned slices, maps, and pointers (`empty` for freshly created or mutable roots).
    fn owners(&self, e: &Expr) -> Vec<Own> {
        let holds = e.ty.as_ref().is_some_and(|ty| self.twofold(ty));
        let lambda = matches!(e.ty, Some(Type::Closure(_)));
        if !holds && !lambda {
            return Vec::new();
        }
        let all = |values: &mut dyn Iterator<Item = &Expr>| {
            values
                .flat_map(|value| self.owners(value))
                .collect::<Vec<Own>>()
        };
        match &e.kind {
            ExprKind::Var(name) => {
                match self
                    .read_owners
                    .get(&(e.span.file, e.span.line, e.span.col))
                {
                    Some(owners) => owners.clone(),
                    None => self
                        .lookup(name)
                        .map_or_else(Vec::new, |info| self.name_owners(name, info)),
                }
            }
            ExprKind::Ref(place) => self.owners(place),
            ExprKind::Field(base, _)
            | ExprKind::Index(base, _)
            | ExprKind::Lookup(base, _)
            | ExprKind::Deref(base) => self.owners(base),
            ExprKind::Call { name, args, .. } => self.call_owners(name, args),
            ExprKind::Invoke { callee, args } => {
                all(&mut std::iter::once(callee.as_ref()).chain(args.iter()))
            }
            ExprKind::Closure { lambda, .. } => vec![Own::Kept(lambda.clone())],
            ExprKind::Array(items) | ExprKind::Tuple(items) => all(&mut items.iter()),
            ExprKind::Construct { args, .. } => all(&mut args.iter()),
            ExprKind::StructInit { fields, .. } => {
                all(&mut fields.iter().map(|field| &field.value))
            }
            ExprKind::Pairs(pairs) => all(&mut pairs.iter().flat_map(|(key, value)| [key, value])),
            ExprKind::Repeat { value, .. }
            | ExprKind::Wrap(value)
            | ExprKind::Widen(value)
            | ExprKind::Pipe(value)
            | ExprKind::Piped(value)
            | ExprKind::Kept { value, .. }
            | ExprKind::Shortcut { value, .. }
            | ExprKind::Spread(value)
            | ExprKind::Fail(value) => self.owners(value),
            ExprKind::MapOp { map, op, .. } => match (op, &map.ty) {
                (MapOp::Keys, Some(Type::Map(key, _, _))) if self.twofold(key) => self.owners(map),
                (MapOp::Values, Some(Type::Map(_, value, _))) if self.twofold(value) => {
                    self.owners(map)
                }
                _ => Vec::new(),
            },
            ExprKind::New { ty, value, .. } => match ty.as_ref() {
                map @ Type::Map(..) if !matches!(value.kind, ExprKind::Pairs(_)) => {
                    self.copied_owners(map, value)
                }
                Type::Slice(item, _)
                    if !matches!(value.kind, ExprKind::Array(_) | ExprKind::Repeat { .. }) =>
                {
                    self.copied_owners(item, value)
                }
                _ => self.owners(value),
            },
            ExprKind::Copy { value, .. } => value
                .ty
                .as_ref()
                .map_or_else(Vec::new, |ty| self.copied_owners(ty, value)),
            ExprKind::PlanB { value, body, .. } => {
                let mut given = Vec::new();
                last_values(body, &mut given);
                all(&mut std::iter::once(value.as_ref()).chain(given))
            }
            ExprKind::Choice(stmt) => {
                let mut given = Vec::new();
                last_values(std::slice::from_ref(stmt.as_ref()), &mut given);
                all(&mut given.into_iter())
            }
            ExprKind::LoopValue(value) => {
                let mut given = Vec::new();
                loop_values(&value.stmt, &mut given);
                all(&mut given.into_iter())
            }
            ExprKind::MethodCall { value, args, .. } => {
                all(&mut std::iter::once(value.as_ref()).chain(args.iter()))
            }
            _ => Vec::new(),
        }
    }

    fn name_owners(&self, name: &str, info: &VarInfo) -> Vec<Own> {
        if info
            .mode
            .can_change_contents(self.bind_has_contents(&info.ty))
            || info.result
        {
            return Vec::new();
        }
        let mut owners = info.owners.clone();
        let ty = info.ty.clone();
        let index = self.param_index.get(name).filter(|_| info.param);
        if self.twofold(&ty) && (index.is_some() || !self.only_lambdas(&ty)) {
            owners.push(match index {
                Some(i) => Own::Param(*i, name.to_string()),
                None => Own::Root(name.to_string()),
            });
        }
        owners
    }

    /// Ownership for full copies: empty unless `ty` contains or instantiates a closure.
    fn copied_owners(&self, ty: &Type, value: &Expr) -> Vec<Own> {
        if has_closure(ty) {
            return self.owners(value);
        }
        if ty.params().is_empty() && !self.may_hold(ty, true) {
            return Vec::new();
        }
        let from = self.owners(value);
        if from.is_empty() {
            return from;
        }
        vec![Own::Copied {
            task: self.current_task.clone(),
            ty: ty.clone(),
            from,
        }]
    }

    fn copies_a_lambda(&self, task: &str, ty: &Type) -> bool {
        self.copies.get(task).is_some_and(|copies| {
            copies
                .iter()
                .any(|(_, given)| has_closure(&in_copy(ty, given)))
        })
    }

    fn call_owners(&self, task: &str, args: &[Expr]) -> Vec<Own> {
        let one_each = self
            .tasks
            .get(task)
            .is_some_and(|info| info.params.len() == args.len())
            && !args
                .iter()
                .any(|arg| matches!(arg.kind, ExprKind::Spread(_)));
        args.iter()
            .enumerate()
            .flat_map(|(param, arg)| {
                let from = self.owners(arg);
                match (from.is_empty(), one_each) {
                    (true, _) => Vec::new(),
                    (false, true) => vec![Own::Sent {
                        task: task.to_string(),
                        param,
                        from,
                    }],
                    (false, false) => from,
                }
            })
            .collect()
    }

    fn param_hint(&self, name: &str, info: &VarInfo) -> String {
        param_hint_for(name, info, holds_pointers(&info.ty, &self.regional))
    }

    fn copied_text(&self, value: &Expr) -> String {
        match self.value_text(value) {
            _ if matches!(value.kind, ExprKind::PlanB { .. }) => OWNER_MARK.to_string(),
            text if text == "…" => OWNER_MARK.to_string(),
            text => text,
        }
    }

    fn value_text(&self, e: &Expr) -> String {
        if let Some(path) = place_path(e) {
            return path_text(&path);
        }
        match &e.kind {
            ExprKind::Call { name, args, .. } => {
                let shared = self
                    .tasks
                    .get(name)
                    .and_then(|info| info.owner.as_ref())
                    .is_some_and(|owner| owner.shared);
                match (method_parts(name), args.first()) {
                    (Some(_), _) if shared => format!("{}(…)", called_name(name)),
                    (Some((_, method)), Some(value)) => {
                        format!("{}.{}(…)", self.value_text(value), method)
                    }
                    _ => format!("{}(…)", name),
                }
            }
            ExprKind::Invoke { callee, .. } => format!("{}(…)", self.value_text(callee)),
            ExprKind::MethodCall { name, .. } => format!("….{}(…)", name),
            ExprKind::PlanB { value, .. }
            | ExprKind::Wrap(value)
            | ExprKind::Widen(value)
            | ExprKind::Pipe(value)
            | ExprKind::Piped(value)
            | ExprKind::Kept { value, .. } => self.value_text(value),
            ExprKind::Lookup(base, index) => match index.kind {
                ExprKind::IntLit(n) => format!("{}[#{}]", self.value_text(base), n),
                _ => format!("{}[#…]", self.value_text(base)),
            },
            _ => "…".to_string(),
        }
    }

    fn written_text(&self, e: &Expr) -> String {
        if let Some(path) = place_path(e) {
            return path_text(&path);
        }
        match &e.kind {
            ExprKind::Field(base, field) => format!("{}.{}", self.written_text(base), field),
            ExprKind::Index(base, index) => match index.kind {
                ExprKind::IntLit(n) => format!("{}[{}]", self.written_text(base), n),
                _ => format!("{}[…]", self.written_text(base)),
            },
            ExprKind::Deref(base) => format!("{}^", self.written_text(base)),
            _ => self.value_text(e),
        }
    }

    fn hand(&mut self, value: &Expr, to: HandedTo) {
        let ty = value.ty.clone().unwrap_or(Type::Unknown);
        self.hand_as(value, &ty, to);
    }

    fn hand_as(&mut self, value: &Expr, ty: &Type, to: HandedTo) {
        if !self.twofold(ty) {
            return;
        }
        let owners = self.owners(value);
        if !owners.is_empty() {
            let copied = if matches!(value.ty, Some(Type::Results(_))) {
                OWNER_MARK.to_string()
            } else {
                self.copied_text(value)
            };
            let handed = self.handed(value.span, owners, to, &copied, ty);
            self.handed.push(handed);
        }
    }

    fn handed(
        &self,
        span: Span,
        owners: Vec<Own>,
        to: HandedTo,
        copied: &str,
        ty: &Type,
    ) -> Handed {
        let lambda = self.only_lambdas(ty) || has_closure(ty);
        let copied = if lambda { OWNER_MARK } else { copied };
        let (region, none_here) = match ty {
            Type::Closure(closure) => self.copy_region_here(&closure.task.ret),
            _ => self.copy_region_here(ty),
        };
        let copy = format!("{}.copy() at {}", copied, region);
        let no_region = none_here.then_some(region);
        Handed {
            span,
            owners,
            to,
            copy,
            lambda,
            no_region,
            generic: self.generic_part(ty),
        }
    }

    fn copy_region_here(&self, ty: &Type) -> (String, bool) {
        let usable = |name: &str| {
            self.lookup(name)
                .is_some_and(|info| info.ty == Type::Region && info.allocates)
        };
        if let Some(region) = ty
            .regions()
            .into_iter()
            .find(|region| !unnamed_region(region) && *region != THIS_WORD && usable(region))
        {
            return (region.to_string(), false);
        }
        let here = self
            .scopes
            .iter()
            .rev()
            .flat_map(|scope| scope.names.iter())
            .find(|(name, info)| {
                info.ty == Type::Region
                    && info.allocates
                    && !unnamed_region(name)
                    && *name != THIS_WORD
            });
        here.map_or_else(
            || (copy_region(ty).to_string(), true),
            |(name, _)| (name.clone(), false),
        )
    }

    fn twofold(&self, ty: &Type) -> bool {
        holds_twofold(ty, &self.regional, true) || self.may_hold(ty, true)
    }

    fn only_lambdas(&self, ty: &Type) -> bool {
        self.twofold(ty) && !holds_twofold(ty, &self.regional, false) && !self.may_hold(ty, false)
    }

    fn bind_has_contents(&self, ty: &Type) -> bool {
        has_contents(ty, &|name| self.shapes.contains_key(name))
    }

    fn may_hold(&self, ty: &Type, lambdas: bool) -> bool {
        match ty {
            Type::Param(name) | Type::Named(name, _) => self.type_params.iter().any(|param| {
                param.name == *name && !param.needs.iter().any(|(need, _)| *need == Need::Frozen)
            }),
            Type::Applied(applied) => applied.types.iter().any(|ty| self.may_hold(ty, lambdas)),
            Type::Maybe(inner) | Type::Array(inner, _) | Type::Fail(inner) => {
                self.may_hold(inner, lambdas)
            }
            Type::Or(value, error) => {
                self.may_hold(value, lambdas) || self.may_hold(error, lambdas)
            }
            Type::Tuple(items) | Type::Results(items) => {
                items.iter().any(|item| self.may_hold(item, lambdas))
            }
            Type::Closure(closure) => lambdas && self.may_hold(&closure.task.ret, lambdas),
            _ => false,
        }
    }

    fn generic_part(&self, ty: &Type) -> Option<(String, Type)> {
        (!holds_twofold(ty, &self.regional, true) && self.may_hold(ty, true))
            .then(|| (self.current_task.clone(), ty.clone()))
    }

    fn bind_from(&mut self, bindings: &[Declared], source: &Expr) {
        let owners = self.owners(source);
        if owners.is_empty() {
            return;
        }
        for (name, at, ty, mode) in bindings {
            if name == DISCARD || !self.twofold(ty) {
                continue;
            }
            if mode.can_change_contents(self.bind_has_contents(ty)) {
                let handed = self.handed(
                    *at,
                    owners.clone(),
                    HandedTo::Variable(name.clone()),
                    &self.copied_text(source),
                    ty,
                );
                self.handed.push(handed);
            } else {
                self.bound_owners.push((*at, owners.clone()));
            }
        }
    }

    fn note_sent(&mut self, values: &[Expr]) {
        let sent: Vec<Own> = values.iter().flat_map(|value| self.owners(value)).collect();
        if !sent.is_empty() {
            self.sends
                .entry(self.current_task.clone())
                .or_default()
                .extend(sent);
        }
    }

    fn hand_written(&mut self, place: &Expr, method: Option<&str>) {
        let mut root = place;
        while let ExprKind::Field(base, _)
        | ExprKind::Index(base, _)
        | ExprKind::Lookup(base, _)
        | ExprKind::Deref(base) = &root.kind
        {
            root = base;
        }
        if matches!(root.kind, ExprKind::Var(_) | ExprKind::Shared { .. })
            || std::ptr::eq(root, place)
        {
            return;
        }
        let made = self.value_text(root);
        let lead = match method {
            Some(method) => format!("'{}' changes what '{}' gives back", method, made),
            None => format!("cannot change what '{}' gives back", made),
        };
        let owners = self.owners(root);
        if !owners.is_empty() {
            let generic = root.ty.as_ref().and_then(|ty| self.generic_part(ty));
            self.handed.push(Handed {
                span: root.span,
                owners,
                to: HandedTo::Written(lead),
                copy: String::new(),
                lambda: false,
                no_region: None,
                generic,
            });
        }
    }

    /// Fixed-point dataflow over task returns (`<-`) to forbid passing `fixed`-owned handles to mutable sinks.
    fn settle_owners(&mut self) {
        let mut sends_back: HashMap<String, HashSet<usize>> = HashMap::new();
        loop {
            let mut grown = false;
            for (task, sent) in &self.sends {
                let params = self.tasks.get(task).map_or(0, |info| info.params.len());
                for param in 0..params {
                    if sends_back
                        .get(task)
                        .is_some_and(|back| back.contains(&param))
                    {
                        continue;
                    }
                    if self.reaches_param(sent, param, &sends_back) {
                        sends_back.entry(task.clone()).or_default().insert(param);
                        grown = true;
                    }
                }
            }
            if !grown {
                break;
            }
        }
        let mut errors = Vec::new();
        for handed in &self.handed {
            let Some((owner, of_param)) = self.owner_of_handed(&handed.owners, &sends_back) else {
                continue;
            };
            let given = match &handed.generic {
                None => String::new(),
                Some((task, ty)) => {
                    let copy = self.copies.get(task).and_then(|copies| {
                        copies.iter().find(|(_, given)| {
                            holds_twofold(&in_copy(ty, given), &self.regional, true)
                        })
                    });
                    let Some((types, _)) = copy else { continue };
                    let types: Vec<String> = types
                        .iter()
                        .map(|ty| ty.without_regions().to_string())
                        .collect();
                    format!(
                        ", where '{}' is given {}",
                        unqualified(task),
                        types.join(", ")
                    )
                }
            };
            let owner_text = owner.clone();
            let copy = handed.copy.replace(OWNER_MARK, &owner_text);
            let region = handed
                .no_region
                .as_ref()
                .map_or_else(String::new, |region| {
                    format!(", in a region the task takes, as in '{}: region'", region)
                });
            let rule = "nothing changes through what a fixed name owns";
            let lambda = format!(
                "a lambda that may send back what fixed '{}' owns",
                owner_text
            );
            let send_copy = format!(
                "have the lambda send back a copy, as in '<- {}'{}",
                copy, region
            );
            let message = match &handed.to {
                HandedTo::Variable(name) if handed.lambda => format!(
                    "'{}' is given {}, and {}; make '{}' fixed, or {}",
                    name, lambda, rule, name, send_copy
                ),
                HandedTo::Param { task, param } if handed.lambda => {
                    format!(
                        "'{}' may change what its parameter '{}' sends back, so it can't be given {}; take it as '{}' without 'flex', or {}",
                        task, param, lambda, param, send_copy
                    )
                }
                HandedTo::Place(place) if handed.lambda => format!(
                    "'{}' changes, so it can't be given {}: {}; {}",
                    place, lambda, rule, send_copy
                ),
                HandedTo::Result(name) if handed.lambda => format!(
                    "'{}' is a result, which the task may change, so it can't be given {}; {}",
                    name, lambda, send_copy
                ),
                HandedTo::Variable(name) => format!(
                    "'{}' is given what fixed '{}' owns, and {}; give it a copy: '{}'{}",
                    name, owner_text, rule, copy, region
                ),
                HandedTo::Param { task, param } => {
                    let keep = match of_param {
                        true if owner == THIS => "make the method 'alters'".to_string(),
                        true => format!("take '{0}' as 'flex {0}'", owner_text),
                        false => format!("keep '{}' in a flex variable", owner_text),
                    };
                    let what = match param
                        .strip_prefix("value ")
                        .and_then(|k| k.parse::<usize>().ok())
                    {
                        Some(k) => format!("its {} value", ordinal(k)),
                        None => format!("its parameter '{}'", param),
                    };
                    format!(
                        "'{}' changes what {} reaches, so it can't be given what fixed '{}' owns; give it a copy, '{}'{}, or {}",
                        task, what, owner_text, copy, region, keep
                    )
                }
                HandedTo::Place(place) => format!(
                    "'{}' changes, so it can't be given what fixed '{}' owns: {}; give it a copy: '{}'{}",
                    place, owner_text, rule, copy, region
                ),
                HandedTo::Result(name) => format!(
                    "'{}' is a result, which the task may change, so it can't be given what fixed '{}' owns; give it a copy: '{}'{}",
                    name, owner_text, copy, region
                ),
                HandedTo::Written(lead) => format!(
                    "{}: it is what fixed '{}' owns, and {}, at any depth",
                    lead, owner_text, rule
                ),
            };
            let message = message.replacen(" owns", &format!(" owns{}", given), 1);
            errors.push(Error::at(handed.span, message));
        }
        for kept in self
            .kept_lambdas
            .values()
            .filter(|kept| kept.mode != KeptMode::Plain)
        {
            let word = if kept.mode == KeptMode::Bind {
                "bind"
            } else {
                "flex"
            };
            for name in &kept.uses {
                let Some((_, info)) = kept.outer.iter().find(|(outer, _)| outer == name) else {
                    continue;
                };
                if info
                    .mode
                    .can_change_contents(self.bind_has_contents(&info.ty))
                    || info.result
                    || !holds_twofold(&info.ty, &self.regional, true)
                {
                    continue;
                }
                let rule = "nothing changes through what a fixed name owns";
                let message = if self.only_lambdas(&info.ty) {
                    format!(
                        "a '[{3} @{1}]' lambda may change what its copies hold, so it can't keep a copy of fixed '{0}', a lambda that may send back what a fixed name owns, and {2}; make it a '[@{1}]' lambda",
                        name, kept.region, rule, word
                    )
                } else {
                    let copy = format!("{}.copy() at {}", name, copy_region(&info.ty));
                    format!(
                        "a '[{4} @{1}]' lambda may change what its copies hold, so it can't keep a copy of fixed '{0}', and {3}; make it a '[@{1}]' lambda, or keep a copy of its own, as in 'flex mine = {2}', and use that",
                        name, kept.region, copy, rule, word
                    )
                };
                errors.push(Error::at(kept.span, message));
            }
        }
        let mut seen = HashSet::new();
        errors.retain(|error| {
            seen.insert((
                error.span.map(|span| (span.file, span.line, span.col)),
                error.message.clone(),
            ))
        });
        self.errors.extend(errors);
    }

    fn reaches_param(
        &self,
        owners: &[Own],
        param: usize,
        sends_back: &HashMap<String, HashSet<usize>>,
    ) -> bool {
        owners.iter().any(|own| match own {
            Own::Param(i, _) => *i == param,
            Own::Sent {
                task,
                param: given,
                from,
            } => {
                self.may_send_back(task, *given, sends_back)
                    && self.reaches_param(from, param, sends_back)
            }
            Own::Kept(lambda) => self.reaches_param(&self.lambda_sends(lambda), param, sends_back),
            Own::Copied { task, ty, from } => {
                self.copies_a_lambda(task, ty) && self.reaches_param(from, param, sends_back)
            }
            Own::Root(_) => false,
        })
    }

    fn may_send_back(
        &self,
        task: &str,
        param: usize,
        sends_back: &HashMap<String, HashSet<usize>>,
    ) -> bool {
        self.natives.contains(task)
            || sends_back
                .get(task)
                .is_some_and(|back| back.contains(&param))
    }

    fn owner_of_handed(
        &self,
        owners: &[Own],
        sends_back: &HashMap<String, HashSet<usize>>,
    ) -> Option<(String, bool)> {
        owners.iter().find_map(|own| match own {
            Own::Root(name) => Some((name.clone(), false)),
            Own::Param(_, name) => Some((name.clone(), true)),
            Own::Sent { task, param, from } => self
                .may_send_back(task, *param, sends_back)
                .then(|| self.owner_of_handed(from, sends_back))
                .flatten(),
            Own::Kept(lambda) => self.owner_of_handed(&self.lambda_sends(lambda), sends_back),
            Own::Copied { task, ty, from } => self
                .copies_a_lambda(task, ty)
                .then(|| self.owner_of_handed(from, sends_back))
                .flatten(),
        })
    }

    /// Computes return ownership for `lambda` in outer scope, resolving captured outer variables to outer owners.
    fn lambda_sends(&self, lambda: &str) -> Vec<Own> {
        let Some(kept) = self.kept_lambdas.get(lambda) else {
            return Vec::new();
        };
        let sent = self.sends.get(lambda).map_or(&[][..], Vec::as_slice);
        self.around_lambda(kept, lambda, sent)
    }

    fn around_lambda(&self, kept: &KeptLambda, lambda: &str, owners: &[Own]) -> Vec<Own> {
        owners
            .iter()
            .flat_map(|own| match own {
                Own::Root(name) => kept.owned.get(name).cloned().unwrap_or_default(),
                Own::Param(..) => Vec::new(),
                Own::Sent { task, param, from } => {
                    let from = self.around_lambda(kept, lambda, from);
                    if from.is_empty() {
                        Vec::new()
                    } else {
                        vec![Own::Sent {
                            task: task.clone(),
                            param: *param,
                            from,
                        }]
                    }
                }
                Own::Kept(inner)
                    if self
                        .kept_lambdas
                        .get(inner)
                        .is_some_and(|inner| inner.within.as_deref() == Some(lambda)) =>
                {
                    self.around_lambda(kept, lambda, &self.lambda_sends(inner))
                }
                Own::Kept(_) => vec![own.clone()],
                Own::Copied { task, ty, from } => {
                    let from = self.around_lambda(kept, lambda, from);
                    if from.is_empty() {
                        Vec::new()
                    } else {
                        vec![Own::Copied {
                            task: task.clone(),
                            ty: ty.clone(),
                            from,
                        }]
                    }
                }
            })
            .collect()
    }

    /// Calling a `[bind @r]` lambda changes what its copies share, so it is called through a place that may
    /// change contents, as `xs[0] = 1` needs one: a flex or bind name, or a value such a name holds.
    fn check_bind_call(&self, callee: &Expr, ty: &Type) -> Result<()> {
        let mut base = callee;
        while let ExprKind::Field(inner, _) | ExprKind::Index(inner, _) = &base.kind {
            base = inner;
        }
        let ExprKind::Var(name) = &base.kind else {
            return Ok(());
        };
        let Some(info) = self.lookup(name) else {
            return Ok(());
        };
        if info.mode.can_change_contents(true) {
            return Ok(());
        }
        let (called, changes) = match (&callee.kind, held_lambda(ty)) {
            (ExprKind::Var(_), _) => (format!("'{}' is", name), "what its copies share"),
            (_, true) => (format!("this lambda, held in '{}', is", name), "what it keeps"),
            (_, false) => (format!("this lambda, held in '{}', is", name), "what its copies share"),
        };
        if name == THIS {
            return Err(self.this_cannot_change(
                callee.span,
                &format!("calling a '{}' lambda it holds", held_kind(ty)),
            ));
        }
        err(
            callee.span,
            format!(
                "{0} a '{1}' lambda, and calling it changes {2}, so it is called through a place that changes, a 'flex' or 'bind' name, which '{3}' isn't{4}",
                called,
                held_kind(ty),
                changes,
                name,
                self.param_hint(name, info)
            ),
        )
    }

    fn check_field_base(&mut self, base: &mut Expr, written: &str) -> Result<Type> {
        let span = base.span;
        match &base.kind {
            ExprKind::Var(name) => {
                let info = self.lookup_or_err(name, span)?;
                // Defer non-shape bases (pointers/kinds) so `field_type` produces the better diagnostic.
                let is_shape = match &info.ty {
                    Type::Named(ty, _) => self.shapes.contains_key(ty),
                    Type::Applied(applied) => self.shapes.contains_key(&applied.name),
                    _ => false,
                };
                if is_shape && info.result {
                    return err(
                        span,
                        format!("'{0}' is a result; set it with '{0} <- …'", name),
                    );
                }
                if is_shape
                    && !info
                        .mode
                        .can_change_contents(self.bind_has_contents(&info.ty))
                {
                    let msg = if info.mode == Mode::Hold {
                        format!(
                            "cannot assign to a field of 'hold' variable '{}'; a 'hold' variable can only be reassigned by whole, declare it with 'flex' to change contents",
                            name
                        )
                    } else {
                        format!(
                            "cannot assign to a field of immutable variable '{}'{}",
                            name,
                            self.param_hint(name, info)
                        )
                    };
                    return err(span, msg);
                }
                self.check_expr(base)
            }
            ExprKind::Field(..) | ExprKind::Deref(_) | ExprKind::Index(..) => {
                self.check_written(base, written, false)
            }
            ExprKind::Shared { shape, field } => {
                let (shape, field) = (shape.clone(), field.clone());
                let ty = self.check_expr(base)?;
                self.changeable_shared(&shape, &field, span, "", false)?;
                Ok(ty)
            }
            _ => err(span, "cannot assign to a field of a temporary value"),
        }
    }

    fn check_match(
        &mut self,
        span: Span,
        expr: &mut Expr,
        cases: &mut [Case],
        gives: Option<Branches>,
    ) -> Result<Option<Type>> {
        let found = self.check_expr(expr);
        let ety = self.or_unknown(found);
        let unknown = ety.unknown();
        let needed: Vec<String> = match &ety {
            _ if unknown => Vec::new(),
            Type::Named(name, _) => match self.kinds.get(name) {
                Some(kind) => kind.variants.iter().map(|v| v.tag.clone()).collect(),
                None => {
                    return err(
                        expr.span,
                        format!(
                            "'match' needs a kind, a maybe, or a 'T ~ E', but '{}' is a shape",
                            name
                        ),
                    );
                }
            },
            Type::Applied(applied) if self.kinds.contains_key(&applied.name) => self
                .kinds
                .get(&applied.name)
                .map(|kind| kind.variants.iter().map(|v| v.tag.clone()).collect())
                .unwrap_or_default(),
            Type::Maybe(_) => vec!["{…}".to_string(), "none".to_string()],
            Type::Or(..) => vec!["{…}".to_string(), "failure …".to_string()],
            Type::Tuple(_) => {
                return err(
                    expr.span,
                    format!(
                        "match requires a kind, a maybe, or a 'T ~ E' value, got {}; take a tuple apart with 'fixed', as in 'fixed (a, b) = t'",
                        ety
                    ),
                );
            }
            other => {
                return err(
                    expr.span,
                    format!(
                        "match requires a kind, a maybe, or a 'T ~ E' value, got {}",
                        other
                    ),
                );
            }
        };
        let mut seen: HashSet<String> = HashSet::new();
        let mut matched_all = false;
        let entry = self.unset.clone();
        let mut branches = Vec::new();
        let mut given = Vec::new();
        for (i, case) in cases.iter_mut().enumerate() {
            if matched_all {
                return err(
                    case.pattern.span,
                    "this case comes after '_', which already matches everything",
                );
            }
            let bindings = self.pattern_bindings(&ety, &case.pattern, true)?;
            self.bind_from(&bindings, expr);
            let label = case.pattern.label();
            if matches!(case.pattern.kind, PatternKind::Any) {
                if !unknown && needed.iter().all(|n| seen.contains(n)) {
                    return err(
                        case.pattern.span,
                        "every case is already covered, so '_' never matches",
                    );
                }
                matched_all = true;
            } else if seen.contains(&label) {
                return err(case.pattern.span, format!("duplicate case '{}'", label));
            }
            seen.insert(label);
            match gives {
                Some(words) => {
                    let found =
                        self.check_value_block(bindings, &mut case.body, case.pattern.span, words);
                    let value = self.note_branch(found, case.pattern.span);
                    given.extend(value.map(|(ty, at)| (i, ty, at)));
                }
                None => {
                    if let [
                        Stmt {
                            kind: StmtKind::Expr(value),
                            ..
                        },
                    ] = case.body.as_slice()
                        && value.span.line == case.pattern.span.line
                    {
                        return err(
                            value.span,
                            "a case gives a value with '=' only where the match is one itself, as in 'fixed name = match …'; the cases of a match on its own hold statements, written on the lines below it",
                        );
                    }
                    self.check_block_with(bindings, &mut case.body)?;
                }
            }
            branches.push(self.branch_state(&case.body, &entry));
        }
        self.join_branches(entry, branches);
        if !matched_all && let Some(missing) = needed.iter().find(|n| !seen.contains(*n)) {
            return err(span, format!("missing case '{}' in match", missing));
        }
        let Some(words) = gives else { return Ok(None) };
        let Some(settled) = self.settle_branches(span, &given, words)? else {
            return Ok(None);
        };
        let settled = self.made_kinds(settled, span)?;
        for (i, _, _) in given
            .iter()
            .filter(|(_, ty, _)| !ty.unknown() && *ty != settled)
        {
            if let Some(case) = cases.get_mut(*i) {
                self.settle_value(&mut case.body, &settled)?;
            }
        }
        self.escaping_region(span, &given, &settled, words)?;
        Ok(Some(settled))
    }

    fn check_expr(&mut self, expr: &mut Expr) -> Result<Type> {
        let ty = self.check_expr_multi(expr)?;
        let Type::Results(types) = &ty else {
            return Ok(ty);
        };
        let what = match &expr.kind {
            ExprKind::Call { name, .. } => format!("'{}'", name),
            _ => "this call".to_string(),
        };
        err(
            expr.span,
            format!(
                "{} sends {} values; receive them with 'fixed {} = …'",
                what,
                types.len(),
                example_names(types.len())
            ),
        )
    }

    fn check_expr_multi(&mut self, expr: &mut Expr) -> Result<Type> {
        self.prepare_shortcut_lambda(expr, &Type::Unknown)?;
        self.resolve_constructor(expr);
        self.resolve_empty_plan_b(expr);
        self.resolve_task_use(expr);
        if matches!(&expr.kind, ExprKind::Field(_, field) if field == TYPE_WORD) {
            return self.check_type_of(expr);
        }
        let ty = self.infer_expr(expr)?;
        if matches!(
            expr.kind,
            ExprKind::Array(_) | ExprKind::Repeat { .. } | ExprKind::New { .. }
        ) {
            self.warn_char_array(&ty, expr.span);
        }
        if let ExprKind::Var(name) = &expr.kind
            && let Some(info) = self.lookup(name)
        {
            let owners = self.name_owners(name, info);
            if !owners.is_empty() {
                self.read_owners
                    .insert((expr.span.file, expr.span.line, expr.span.col), owners);
            }
        }
        expr.ty = Some(ty.clone());
        Ok(ty)
    }

    fn warn_char_array(&mut self, ty: &Type, span: Span) {
        let chars = match ty {
            Type::Array(items, _) | Type::Slice(items, _) | Type::Ptr(items, _) => {
                match items.as_ref() {
                    Type::Array(inner, _) => **inner == Type::Char,
                    other => *other == Type::Char,
                }
            }
            _ => false,
        };
        if chars {
            let message = "this builds text by hand as chars; 'text' holds characters already, with its length, parts, 't[i]', joining, and '==', so prefer it, as in 'fixed word = \"abc\"' (said once in each file)";
            self.warn_once(
                format!("file {}", span.file),
                "chars",
                span,
                message.to_string(),
            );
        }
    }

    fn var_info(&self, name: &str) -> Option<&VarInfo> {
        self.scopes
            .iter()
            .rev()
            .find_map(|scope| scope.names.get(name))
    }

    fn set_family(&mut self, name: &str, family: Option<usize>) {
        if let Some(info) = self
            .scopes
            .iter_mut()
            .rev()
            .find_map(|scope| scope.names.get_mut(name))
        {
            info.family = family;
        }
    }

    fn is_slice_var(&self, name: &str) -> bool {
        self.var_info(name)
            .is_some_and(|info| matches!(info.ty, Type::Slice(..)))
    }

    /// Tracks slices sharing backing buffers via direct copy or slicing to warn on post-`add`/`del` aliasing hazards.
    fn link_slices(&mut self, from: &str, to: &str) {
        if !self.is_slice_var(from) || !self.is_slice_var(to) {
            return;
        }
        let family = match self.var_info(from).and_then(|info| info.family) {
            Some(family) => family,
            None => {
                self.slice_families.push(SliceFamily::default());
                self.slice_families.len() - 1
            }
        };
        self.set_family(from, Some(family));
        self.set_family(to, Some(family));
    }

    fn shared_slice_of(value: &Expr) -> Option<&str> {
        match &value.kind {
            ExprKind::Var(name) => Some(name),
            ExprKind::Index(base, index) if matches!(index.kind, ExprKind::Range(..)) => {
                match &base.kind {
                    ExprKind::Var(name) => Some(name),
                    _ => None,
                }
            }
            _ => None,
        }
    }

    fn written_slice(place: &Expr) -> Option<(&str, Span)> {
        let mut at = place;
        loop {
            match &at.kind {
                ExprKind::Field(base, _) => at = base,
                ExprKind::Index(base, _) => match (&base.kind, &base.ty) {
                    (ExprKind::Var(name), Some(Type::Slice(..))) => return Some((name, base.span)),
                    (_, Some(Type::Array(..))) => at = base,
                    _ => return None,
                },
                _ => return None,
            }
        }
    }

    /// Records `add`/`del` edits; `del()` pops the tail without shifting, while `added`/`without` leave originals unchanged.
    fn note_slice_edit(&mut self, name: &str, op: EditOp, indexed: bool, span: Span) {
        if op.makes_copy() {
            return;
        }
        let Some(info) = self.var_info(name) else {
            return;
        };
        if !matches!(info.ty, Type::Slice(..)) {
            return;
        }
        let (family, flex_param, ty) = (
            info.family,
            info.param && info.passing == Passing::Flex,
            info.ty.clone(),
        );
        if flex_param {
            let (rule, what) = match op {
                EditOp::Add | EditOp::Added => (
                    "add on a flex parameter",
                    "an 'add' leaves its items shared with the caller's only when it finds room in place; when it needs more room it copies them to a block of its own, so what the task writes afterwards may or may not be seen by the caller",
                ),
                EditOp::Del | EditOp::Without if indexed => (
                    "del on a flex parameter",
                    "a 'del' moves the items after the one taken out in the memory the caller's slice shares, so the caller's slice sees them moved, though its length stays as it was",
                ),
                EditOp::Del | EditOp::Without => (
                    "del on a flex parameter",
                    "a 'del' gives the last item's space back to the room the caller's slice may share, so a later 'add' may go over an item the caller still counts, though its length stays as it was",
                ),
            };
            let message = format!(
                "'{0}' is the task's own copy of the caller's slice, and {1}; to change the caller's slice, take the caller's place, 'flex& {0}: {2}', or work on a copy of its own, '{0}.copy() at r'",
                name, what, ty
            );
            self.warn_once(self.current_task.clone(), rule, span, message);
        }
        if let Some(family) = family
            && let Some(shared) = self.slice_families.get_mut(family)
        {
            match op {
                EditOp::Add => shared.added = Some((name.to_string(), span)),
                EditOp::Del if indexed => shared.deleted = Some((name.to_string(), span)),
                EditOp::Del | EditOp::Added | EditOp::Without => {}
            }
        }
    }

    fn warn_deleted_use(&mut self, name: &str, at: Span, family: usize) {
        let Some((deleter, deleted_at)) = self
            .slice_families
            .get(family)
            .and_then(|shared| shared.deleted.clone())
        else {
            return;
        };
        if deleter == name {
            return;
        }
        let message = format!(
            "this uses '{0}' after '{1}.del(…)' at {2}:{3}; '{0}' and '{1}' were made of one slice and share its items, and 'del' moves the items after the one taken out in that shared memory, so '{0}' sees them moved; use the slice you changed, or give the copy items of its own, as in 'flex ys = xs.copy() at r'",
            name, deleter, deleted_at.line, deleted_at.col
        );
        self.warn_once(self.current_task.clone(), "use after del", at, message);
    }

    fn note_slice_use(&mut self, name: &str, span: Span) {
        if let Some(info) = self.var_info(name)
            && matches!(info.ty, Type::Slice(..))
            && let Some(family) = info.family
        {
            self.warn_deleted_use(name, span, family);
        }
    }

    fn note_slice_write(&mut self, place: &Expr) {
        let Some((name, at)) = Checker::written_slice(place) else {
            return;
        };
        let Some(family) = self.var_info(name).and_then(|info| info.family) else {
            return;
        };
        let Some(added) = self
            .slice_families
            .get(family)
            .and_then(|shared| shared.added.clone())
        else {
            self.warn_deleted_use(name, at, family);
            return;
        };
        let (adder, added_at) = added;
        let others = if adder == name {
            format!(
                "a copy or part of '{0}' made earlier shares its items only while an add finds room in place, so the write may or may not be seen through it",
                name
            )
        } else {
            format!(
                "'{0}' and '{1}' were made of one slice and share items only while an add finds room in place, so the write may or may not be seen through '{1}'",
                name, adder
            )
        };
        let message = format!(
            "this writes an item of '{0}' after '{1}.add(…)' at {2}:{3}; {4}; use the slice you changed, or give the copy items of its own, as in 'flex ys = xs.copy() at r'",
            name, adder, added_at.line, added_at.col, others
        );
        self.warn_once(self.current_task.clone(), "write after add", at, message);
        self.warn_deleted_use(name, at, family);
    }

    /// Emits warning once per `rule`+`scope`, archiving repeats into `held_back` for `--repeat-warnings`.
    fn warn_once(&mut self, scope: String, rule: &'static str, span: Span, message: String) {
        let first = self.told_once.insert((scope, rule));
        if self
            .warnings
            .iter()
            .chain(&self.held_back)
            .any(|told| told.span == Some(span) && told.message == message)
        {
            return;
        }
        let warning = Error::at(span, message);
        if first {
            self.warnings.push(warning);
        } else {
            self.held_back.push(warning);
        }
    }

    /// Evaluates `value.type` at compile time without regions; rejects `&x` places.
    fn check_type_of(&mut self, expr: &mut Expr) -> Result<Type> {
        let ExprKind::Field(base, _) = &mut expr.kind else {
            return Err(Error::internal_at(expr.span, "a '.type' that isn't one"));
        };
        if let ExprKind::Ref(place) = &base.kind {
            let example =
                place_path(place).map_or_else(|| "x".to_string(), |path| path_text(&path));
            return err(
                base.span,
                format!(
                    "an address, '&{0}', is only shown, turned into text with 'str', or compared with '=='; the type of the place is '{0}.type'",
                    example
                ),
            );
        }
        let ty = self.check_expr(base)?;
        if ty.unknown() {
            return Ok(Type::Unknown);
        }
        if matches!(ty, Type::Nothing) {
            return err(base.span, "this has no value, so no type to read");
        }
        expr.kind = match ty.params().is_empty() {
            true => ExprKind::TextLit(self.written_type(&ty)),
            false => ExprKind::TypeOf(Box::new(ty)),
        };
        expr.ty = Some(Type::Text(None));
        Ok(Type::Text(None))
    }

    fn written_type(&self, ty: &Type) -> String {
        self.unmade(&ty.without_regions())
            .map_names(&|name| unqualified(name).to_string())
            .to_string()
    }

    fn value_types(
        &mut self,
        values: &mut [Expr],
        wanted: usize,
        span: Span,
        unpacks: bool,
    ) -> Result<Vec<Type>> {
        let mut given = Vec::new();
        if let ([only], false) = (&mut *values, wanted == 1) {
            let ty = self.check_expr_multi(only)?;
            match ty {
                Type::Results(types) => given = types,
                Type::Unknown => given = vec![Type::Unknown; wanted],
                Type::Tuple(items) if unpacks && group_in_tuple(&items).is_some() => {
                    return err(only.span, GROUP_TUPLE_UNPACKED);
                }
                Type::Tuple(items) if unpacks => {
                    if items.len() != wanted {
                        return err(
                            only.span,
                            format!(
                                "this tuple has {} items, but {} take them",
                                items.len(),
                                count(wanted, "name")
                            ),
                        );
                    }
                    given = items;
                }
                Type::Tuple(_) => {
                    return err(
                        only.span,
                        format!(
                            "expected {}, got one tuple; a tuple is one value, so send its items, as in '<- t.0, t.1'",
                            count(wanted, "value")
                        ),
                    );
                }
                other => given.push(other),
            }
        } else {
            for value in values.iter_mut() {
                given.push(self.check_expr(value)?);
            }
        }
        if given.len() != wanted {
            let at = values.get(wanted).map_or(span, |extra| extra.span);
            return err(
                at,
                format!("expected {}, got {}", count(wanted, "value"), given.len()),
            );
        }
        Ok(given)
    }

    fn resolve_bound_types(&mut self, bound: &mut Bound) -> Result<()> {
        if let Some(annotated) = &mut bound.ty {
            *annotated = self.resolve_type(
                annotated,
                bound.ty_span.unwrap_or(bound.span),
                TypePlace::Body,
            )?;
        }
        bound
            .parts
            .iter_mut()
            .try_for_each(|part| self.resolve_bound_types(part))
    }

    fn unpack_bound(
        &mut self,
        bound: &mut Bound,
        actual: &Type,
        at: Span,
        declared: &mut Vec<(String, Span, Type)>,
    ) -> Result<()> {
        if bound.parts.is_empty() {
            let ty = match &bound.ty {
                Some(annotated) => {
                    if !fits_regions(actual, annotated) {
                        return err(
                            at,
                            format!(
                                "expected type {}, got {} for '{}'{}",
                                annotated,
                                actual,
                                bound.name,
                                mismatch_hint(actual, annotated)
                            ),
                        );
                    }
                    annotated.clone()
                }
                None if bound.name == DISCARD => actual.clone(),
                None => self.inferred_type(&bound.name, actual, at)?,
            };
            if bound.name == DISCARD && matches!(ty, Type::Or(..)) {
                return err(at, dropped_error(&ty));
            }
            bound.ty = Some(ty.clone());
            declared.push((bound.name.clone(), bound.span, ty));
            return Ok(());
        }
        let items = self.tuple_items(actual, bound.parts.len(), bound.span)?;
        bound.ty = Some(self.lasting(actual));
        for (part, item) in bound.parts.iter_mut().zip(&items) {
            self.unpack_bound(part, item, at, declared)?;
        }
        Ok(())
    }

    fn tuple_items(&self, actual: &Type, names: usize, at: Span) -> Result<Vec<Type>> {
        match actual {
            _ if actual.unknown() => Ok(vec![Type::Unknown; names]),
            Type::Tuple(items) if group_in_tuple(items).is_some() => err(at, GROUP_TUPLE_UNPACKED),
            Type::Tuple(items) if items.len() == names => Ok(items.clone()),
            Type::Tuple(items) => err(
                at,
                format!(
                    "this tuple has {} items, but '( … )' takes {}",
                    items.len(),
                    names
                ),
            ),
            other => err(
                at,
                format!(
                    "'( … )' takes the items of a tuple, but this value is {}{}",
                    other,
                    extract_hint(&[other])
                ),
            ),
        }
    }

    fn check_target(
        &mut self,
        target: &mut Target,
        assigned: &mut HashMap<String, Span>,
    ) -> Result<TargetType> {
        match target {
            Target::Discard(_) => Ok(TargetType::Discard),
            Target::Place(place) => {
                if let ExprKind::Var(name) = &place.kind
                    && let Some(at) = assigned.insert(name.clone(), place.span)
                {
                    return err(
                        place.span,
                        format!("'{}' is already assigned at {}:{}", name, at.line, at.col),
                    );
                }
                let ty = self.check_assign_target(place)?;
                self.note_slice_write(place);
                Ok(TargetType::Place(ty))
            }
            Target::Tuple(parts, at) => {
                let at = *at;
                let parts = parts
                    .iter_mut()
                    .map(|part| self.check_target(part, assigned))
                    .collect::<Result<_>>()?;
                Ok(TargetType::Tuple(parts, at))
            }
        }
    }

    fn unpack_target(
        &self,
        parts: &[TargetType],
        at: Span,
        actual: &Type,
        value_span: Span,
    ) -> Result<()> {
        let items = self.tuple_items(actual, parts.len(), at)?;
        for (part, item) in parts.iter().zip(&items) {
            match part {
                TargetType::Discard if matches!(item, Type::Or(..)) => {
                    return err(value_span, dropped_error(item));
                }
                TargetType::Discard => {}
                TargetType::Place(expected) => {
                    if !fits_regions(item, expected) {
                        return err(
                            value_span,
                            format!(
                                "expected type {}, got {}{}",
                                expected,
                                item,
                                mismatch_hint(item, expected)
                            ),
                        );
                    }
                }
                TargetType::Tuple(inner, inner_at) => {
                    self.unpack_target(inner, *inner_at, item, value_span)?
                }
            }
        }
        Ok(())
    }

    fn check_set_results(
        &mut self,
        span: Span,
        names: &[Binding],
        values: &mut [Expr],
    ) -> Result<()> {
        let mut expected = Vec::new();
        let mut seen: HashMap<&str, Span> = HashMap::new();
        for (name, at) in names {
            if let Some(before) = seen.insert(name, *at) {
                return err(
                    *at,
                    format!(
                        "'{}' is already set at {}:{}",
                        name, before.line, before.col
                    ),
                );
            }
            let Some(info) = self.lookup(name).filter(|info| info.result) else {
                return err(*at, self.not_a_result(name));
            };
            expected.push(info.ty.clone());
        }
        let given = self.value_types(values, expected.len(), span, false)?;
        let forwarded = values.len() < expected.len();
        let list_span = values.first().map_or(span, |value| value.span);
        for (i, want) in expected.iter().enumerate() {
            let Some(actual) = given.get(i).cloned() else {
                continue;
            };
            match values.get_mut(i).filter(|_| !forwarded) {
                Some(value) => self.coerce(value, want)?,
                None => fits_or_err(&actual, want, list_span, Given::Sent)?,
            }
            if let (Some((name, _)), Some(value)) = (
                names.get(i),
                if forwarded {
                    values.first()
                } else {
                    values.get(i)
                },
            ) {
                self.hand_as(value, want, HandedTo::Result(name.clone()));
            }
        }
        for (name, _) in names {
            self.unset.remove(name);
        }
        Ok(())
    }

    fn not_a_result(&self, name: &str) -> String {
        if self.lookup(name).is_some() {
            return format!(
                "'{0}' isn't a result of this task; assign it with '{0} = …'",
                name
            );
        }
        match self.result_names.as_slice() {
            [] => format!(
                "'{}' isn't a result of this task, which names none; a header names them, as in '-> total: int'",
                name
            ),
            names => format!(
                "'{}' isn't a result of this task; its results are {}",
                name,
                names.join(", ")
            ),
        }
    }

    fn untold_example(&self, ty: &Type) -> Option<String> {
        let Type::Applied(applied) = ty else {
            return None;
        };
        let (_, kind, _, _, example) = self
            .untold_kinds
            .iter()
            .rev()
            .find(|(_, kind, ..)| *kind == applied.name)?;
        Some(format!("{}<{}>", unqualified(kind), example))
    }

    fn inferred_type(&self, name: &str, actual: &Type, at: Span) -> Result<Type> {
        // Literal text without a region promotes to program-lifetime `text`.
        let actual = &self.lasting(actual);
        match actual {
            Type::None => err(at, format!("cannot infer the type of '{}' from none; give it a type, such as '{}: maybe int'", name, name)),
            Type::Fail(error) => err(
                at,
                format!("cannot infer the type of '{}' from 'fail …'; give it a type, such as '{}: int ~ {}'", name, name, error),
            ),
            Type::Task(task) if task.params.iter().any(|p| p.unknown()) => {
                err(at, "cannot infer parameter type in shortcut lambda; specify types with a full lambda, as in '(x: int) -> int <- ... fi', or give the variable a type".to_string())
            }
            Type::Closure(closure) if closure.task.params.iter().any(|p| p.unknown()) => {
                err(at, "cannot infer parameter type in shortcut lambda; specify types with a full lambda, as in '(x: int) -> int <- ... fi', or give the variable a type".to_string())
            }
            Type::Nothing => err(at, "this expression has no value (its type is 'nothing')"),
            other if holds_untold(other) => err(
                at,
                format!(
                    "cannot infer the type of '{0}', since its value doesn't say every type its kind takes; give it a type, such as '{0}: {1}', or write them, as in '{2}'",
                    name,
                    self.untold_example(other).unwrap_or_else(|| settled_example(other).to_string()),
                    self.untold_example(other).map_or_else(|| untold_written(other), |example| format!("{}.…", example))
                ),
            ),
            other if unsettled(other) => err(
                at,
                format!("cannot infer the type of '{0}' from none or 'fail …' in its value; give it a type, such as '{0}: {1}'", name, settled_example(other)),
            ),
            other if other.regions().contains(&ANY_REGION) => {
                let example = other.map_regions(&mut |region| Some(if region == ANY_REGION { "r" } else { region }.to_string()));
                err(
                    at,
                    format!(
                        "cannot tell which region '{0}' lives in, since its value holds no pointers yet; give it a type, such as '{0}: {1}'",
                        name, example
                    ),
                )
            }
            other => Ok(other.clone()),
        }
    }

    fn lasting(&self, ty: &Type) -> Type {
        lasting(ty, &self.regional)
    }

    fn resolve_constructor(&self, expr: &mut Expr) {
        // Replace macro refs with folded constants while preserving `ExprKind::Macro` for C codegen.
        if let ExprKind::Var(name) = &expr.kind
            && self.lookup(name).is_none()
            && self.sees(name)
            && let Some(value) = self
                .macros
                .get(name.as_str())
                .and_then(|info| info.value.clone())
        {
            expr.kind = ExprKind::Macro {
                name: name.clone(),
                value: Box::new(value),
            };
            return;
        }
        let variant = |name: &str| {
            self.variants
                .get(name)
                .filter(|_| self.sees(name))
                .map(|info| (info.kind.clone(), info.variant.tag.clone()))
        };
        let resolved = match &mut expr.kind {
            ExprKind::Var(name) if self.lookup(name).is_none() => {
                variant(name).map(|(kind, tag)| (kind, tag, Vec::new()))
            }
            ExprKind::Call { name, args, .. } => {
                variant(name).map(|(kind, tag)| (kind, tag, std::mem::take(args)))
            }
            _ => None,
        };
        if let Some((kind, tag, args)) = resolved {
            expr.kind = ExprKind::Construct {
                kind,
                tag,
                args,
                types: Vec::new(),
            };
        }
    }

    fn resolve_task_use(&self, expr: &mut Expr) {
        match &mut expr.kind {
            ExprKind::Var(name) if self.lookup(name).is_none() => {
                let full = self.full_name(name);
                // Bare shared method names appear only inside decorators (`X.m` elsewhere); layer wrappers also match.
                if self.tasks.get(&full).is_some_and(|info| info.owner.as_ref().is_none_or(|owner| owner.shared) || full.contains(LAYER)) {
                    expr.kind = ExprKind::TaskValue(full);
                }
            }
            ExprKind::Call { name, types, args }
                if types.is_empty()
                    && !self.tasks.contains_key(name.as_str())
                    && method_parts(name).is_some_and(|(owner, field)| {
                        self.shapes.get(owner).is_some_and(|shape| shape.shared.iter().any(|member| member.field.name == field && (is_task(&member.field.ty) || matches!(&member.field.ty, Type::Maybe(inner) if is_task(inner)))))
                    }) =>
            {
                let Some((owner, field)) = method_parts(name) else { return };
                let callee = Expr::new(ExprKind::Shared { shape: owner.to_string(), field: field.to_string() }, expr.span);
                let args = std::mem::take(args);
                expr.kind = ExprKind::Invoke { callee: Box::new(callee), args };
            }
            ExprKind::Call { name, types, args } if types.is_empty() => {
                let Some(info) = self.lookup(name) else { return };
                let holds_task = is_task(&info.ty) || matches!(&info.ty, Type::Maybe(inner) if is_task(inner));
                let calls_other = self.tasks.contains_key(&self.full_name(name)) || BUILTIN_TASKS.contains(&name.as_str()) || number_cast(name).is_some();
                if info.ty == Type::Region || (!holds_task && calls_other) {
                    return;
                }
                let callee = Expr::new(ExprKind::Var(std::mem::take(name)), expr.span);
                let args = std::mem::take(args);
                expr.kind = ExprKind::Invoke { callee: Box::new(callee), args };
            }
            _ => {}
        }
    }

    fn check_startup(&mut self, body: &mut Block, passes: &[bool]) {
        for stmt in body.iter_mut() {
            let fits = self.decorator_fits(stmt);
            if self.keep_going(fits) {
                let StmtKind::Expr(call) = &mut stmt.kind else {
                    continue;
                };
                let recorded = self.errors.len();
                self.at_start = Some(DECORATOR_VALUES);
                let checked = self
                    .check_expr_multi(call)
                    .map(|_| ())
                    .map_err(|error| at_start_error(error, DECORATOR_VALUES));
                self.at_start = None;
                self.said_at_start(recorded, DECORATOR_VALUES);
                self.keep_going(checked);
            }
        }
        for (stmt, passes) in body
            .iter()
            .zip(passes.iter().chain(std::iter::repeat(&false)))
        {
            let StmtKind::Expr(call) = &stmt.kind else {
                continue;
            };
            let ExprKind::Call { name, .. } = &call.kind else {
                continue;
            };
            match call.ty.as_ref() {
                Some(Type::Or(value, error)) if **value == Type::Nothing => self.note_written_strs(&error.clone(), call.span),
                Some(Type::Nothing) if *passes => self.warnings.push(Error::at(
                    call.span,
                    format!("'?' lets a failure of '{}' pass, but it sends nothing, so it never fails; leave the '?' out", unqualified(name)),
                )),
                Some(Type::Nothing | Type::Unknown) | None => {}
                Some(ty) => {
                    let message = format!(
                        "a startup decorator sends nothing, or 'nothing ~ E' when it can fail, since it runs where the program starts and nothing takes what it sends; '{}' sends {}",
                        unqualified(name),
                        ty
                    );
                    self.record(Error::at(call.span, message));
                }
            }
        }
    }

    fn group_call_info(
        &self,
        info: &TaskInfo,
        args: &[Expr],
        written: &[TypeArg],
        span: Span,
        callee: &str,
    ) -> Result<Option<TaskInfo>> {
        let Some(at) = info
            .params
            .iter()
            .position(|(_, ty)| matches!(ty, Type::Group(_)))
        else {
            return Ok(None);
        };
        let Some((value, Type::Group(group))) = info.params.get(at) else {
            return Ok(None);
        };
        if !written.is_empty() {
            return err(
                span,
                format!(
                    "{} takes a group of types, '{}...', which a call doesn't write yet; leave the types out, and the values say them",
                    callee, group
                ),
            );
        }
        let fixed = info.params.len() - 1;
        if args.len() < fixed {
            let after = fixed - at;
            let expects = match (at, after) {
                (_, 0) => format!(
                    "{}, then any number of values for '{}'",
                    count(at, "argument"),
                    value
                ),
                (0, _) => format!(
                    "any number of values for '{}', then {}",
                    value,
                    count(after, "argument")
                ),
                _ => format!(
                    "{}, any number of values for '{}', then {}",
                    count(at, "argument"),
                    value,
                    count(after, "argument")
                ),
            };
            let got = match args
                .iter()
                .filter(|arg| !matches!(arg.kind, ExprKind::Spread(_)))
                .count()
            {
                alone if alone < args.len() => format!("{} and a group's values", alone),
                all => all.to_string(),
            };
            return err(span, format!("{} expects {}, got {}", callee, expects, got));
        }
        let names: Vec<String> = (0..args.len() - fixed)
            .map(|i| format!("{}{}{}", group, GROUP_ITEM, i))
            .collect();
        let items = |ty: &Type| {
            ty.map_groups(&mut |name| {
                (name == group)
                    .then(|| names.iter().map(|name| Type::Param(name.clone())).collect())
            })
        };
        let mut types = Vec::new();
        for param in &info.types {
            if param.name == *group && names.is_empty() {
                types.push(param.clone());
            } else if param.name == *group {
                types.extend(names.iter().map(|name| TypeParam {
                    name: name.clone(),
                    span: param.span,
                    needs: param.needs.clone(),
                    patterns: param.patterns.clone(),
                    group: false,
                }));
            } else {
                types.push(param.clone());
            }
        }
        let mut params: Vec<(String, Type)> = info
            .params
            .iter()
            .take(at)
            .map(|(name, ty)| (name.clone(), items(ty)))
            .collect();
        params.extend(
            names
                .iter()
                .enumerate()
                .map(|(i, name)| (format!("{} {}", value, i + 1), Type::Param(name.clone()))),
        );
        params.extend(
            info.params
                .iter()
                .skip(at + 1)
                .map(|(name, ty)| (name.clone(), items(ty))),
        );
        let mut passing: Vec<Passing> = info.passing.iter().take(at).copied().collect();
        passing.extend(names.iter().map(|_| Passing::Copy));
        passing.extend(info.passing.iter().skip(at + 1).copied());
        Ok(Some(TaskInfo {
            types,
            params,
            passing,
            ret: items(&info.ret),
            owner: info.owner.clone(),
        }))
    }

    /// Spreading `args...` matches a callee's group parameter; self-recursive extra args are rejected as infinite growth.
    fn check_spread_given(
        &self,
        name: &str,
        callee: &str,
        info: &TaskInfo,
        args: &[Expr],
        spread: usize,
    ) -> Result<()> {
        let Some(at) = args.get(spread).map(|arg| arg.span) else {
            return Ok(());
        };
        let Some(group) = info
            .types
            .iter()
            .find(|param| param.group || param.name.contains(GROUP_ITEM))
        else {
            return err(
                at,
                format!(
                    "{} takes a set number of values, and how many a group holds is known only where it is filled in; give a group's values to a task taking a group, as in 'next(args...)', or name them one by one",
                    callee
                ),
            );
        };
        let group = group.name.split(GROUP_ITEM).next().unwrap_or(&group.name);
        let fixed = info.params.iter().take_while(|(_, ty)| !matches!(ty, Type::Param(param) if param.starts_with(&format!("{}{}", group, GROUP_ITEM)))).count();
        let item = format!("{}{}", group, GROUP_ITEM);
        let after = info
            .params
            .iter()
            .rev()
            .take_while(|(_, ty)| !matches!(ty, Type::Param(param) if param.starts_with(&item)))
            .count();
        if let Some((param, _)) = info
            .params
            .get(spread)
            .filter(|_| spread < fixed || spread >= info.params.len() - after)
        {
            return err(
                at,
                format!(
                    "a group's values go to the group {} takes, between the values it names one by one, and they would be given as '{}' here",
                    callee, param
                ),
            );
        }
        let grown = (spread - fixed) + (info.params.len() - after - spread - 1);
        if grown > 0 && self.full_name(name) == self.current_task {
            return err(
                at,
                format!(
                    "{} gives its own group {} more than it was given, so its group would grow at each call and never be filled in; give it 'args...' alone",
                    callee,
                    count(grown, "value")
                ),
            );
        }
        Ok(())
    }

    /// Tuple safe-index `t.#k`: wraps in-bounds reads in `maybe` (`Wrap`), leaves out-of-bounds as `none`, defers groups.
    fn check_safe_item(&mut self, expr: &mut Expr) -> Result<Type> {
        let span = expr.span;
        let ExprKind::Field(base, item) = &mut expr.kind else {
            return Err(Error::internal_at(span, "a tuple's item read as no field"));
        };
        let base_ty = self.check_expr(base)?;
        let Ok(place) = item.trim_start_matches(SAFE_ITEM).parse::<usize>() else {
            return Err(Error::internal_at(
                span,
                "a tuple's item read in a maybe without its place",
            ));
        };
        let narrowed = match &base.kind {
            ExprKind::Var(tuple) => self
                .narrowed
                .iter()
                .rev()
                .find(|(name, at, _)| name == tuple && *at == place)
                .map(|(_, _, ty)| ty.clone()),
            _ => None,
        };
        let items = match &base_ty {
            Type::Unknown => return Ok(Type::Unknown),
            Type::Tuple(items) if group_in_tuple(items).is_some() => {
                let group = group_in_tuple(items).unwrap_or_default();
                let item = narrowed.unwrap_or_else(|| Type::Param(group_item(&group, place)));
                return Ok(Type::Maybe(Box::new(item)));
            }
            Type::Tuple(items) => items.clone(),
            other => {
                return err(
                    span,
                    format!(
                        "'.#{}' reads an item of a tuple in a maybe, but this value is {}{}",
                        place,
                        other,
                        extract_hint(&[other])
                    ),
                );
            }
        };
        let Some(found) = items.get(place).cloned() else {
            let Some(narrowed) = narrowed else {
                return Ok(Type::None);
            };
            let told = Type::Maybe(Box::new(narrowed));
            expr.ty = Some(Type::None);
            self.coerce(expr, &told)?;
            return Ok(told);
        };
        let read_as = match narrowed {
            Some(narrowed) if !same_ignoring_regions(&found, &narrowed) => {
                Type::Maybe(Box::new(narrowed))
            }
            _ => Type::Maybe(Box::new(found.clone())),
        };
        let taken = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
        if let ExprKind::Field(base, _) = taken {
            let mut read = Expr::new(ExprKind::Field(base, place.to_string()), span);
            read.ty = Some(found);
            expr.kind = ExprKind::Wrap(Box::new(read));
        }
        Ok(read_as)
    }

    fn group_of(&self, e: &Expr) -> Option<String> {
        let ExprKind::Var(name) = &e.kind else {
            return None;
        };
        match &self.lookup(name)?.ty {
            Type::Group(group) => Some(group.clone()),
            _ => None,
        }
    }

    fn check_group_member(&mut self, base: &mut Expr, member: &str, span: Span) -> Result<Type> {
        let Some(group) = self.group_of(base) else {
            return Err(Error::internal_at(
                span,
                "a group's member read from no group",
            ));
        };
        base.ty = Some(Type::Group(group.clone()));
        match member {
            LEN => Ok(Type::Int),
            GROUP_TUPLE if !self.allows(Need::Frozen, &Type::Group(group.clone())) => err(
                span,
                format!(
                    "a tuple's items never change, so making one of the values of the group '{0}...' asks each of its types to be frozen: '<{0}...: frozen>'",
                    group
                ),
            ),
            GROUP_TUPLE => Ok(group_tuple_type(&group)),
            _ => err(
                span,
                format!(
                    "the values of the group '{}...' have 'len', how many they are, and 'tuple', and nothing else to read with '.'; give them on whole, as in 'next(args...)'",
                    group
                ),
            ),
        }
    }

    fn check_spread(&mut self, inner: &mut Expr, span: Span) -> Result<Type> {
        let outer = std::mem::replace(&mut self.spreading, true);
        let ty = self.check_expr(inner);
        self.spreading = outer;
        match ty? {
            ty @ (Type::Group(_) | Type::Unknown) => Ok(ty),
            ty => err(
                span,
                format!(
                    "'...' gives the values of a group on whole, as in 'next(args...)', and this is a value of type {}",
                    ty
                ),
            ),
        }
    }

    /// Outlines wrapped task bodies into nested `__layer__k` tasks so all calls/values traverse the wrapper chain.
    fn add_wrappers(&mut self, items: &mut Vec<Item>) {
        let mut layers = Vec::new();
        for item in items.iter_mut() {
            let Item::Task(task) = item else { continue };
            if task.wrappers.is_empty() {
                continue;
            }
            let calls = std::mem::take(&mut task.wrappers);
            let at = calls.first().map_or(task.span, |call| call.span);
            if !task.types.is_empty() {
                let message = match method_parts(&task.name) {
                    Some((owner, method)) if task.owner.is_some() => format!(
                        "'{}' is a method of '{}', which takes types, so it can't have wrappers yet: each wrapper is given it as a value, and only a task that takes none can be one",
                        method,
                        unqualified(owner)
                    ),
                    _ => format!(
                        "task '{}' takes types, so it can't have wrappers yet: each wrapper is given it as a value, and only a task that takes none can be one",
                        unqualified(&task.name)
                    ),
                };
                self.record(Error::at(at, message));
                continue;
            }
            if task.native {
                self.record(Error::at(
                    at,
                    format!(
                        "native task '{}' has no body of Vela's to wrap",
                        unqualified(&task.name)
                    ),
                ));
                continue;
            }
            let count = calls.len();
            let unnamed = |task: &TaskDef| {
                task.ret
                    .results()
                    .iter()
                    .enumerate()
                    .map(|(i, _)| ResultDef {
                        name: None,
                        ty_span: task.result_span(i),
                    })
                    .collect::<Vec<_>>()
            };
            let mut inner = task.clone();
            inner.name = layer_name(&task.name, count);
            inner.private = true;
            inner.decorators = Vec::new();
            inner.passes = Vec::new();
            for k in 1..count {
                let mut layer = task.clone();
                layer.name = layer_name(&task.name, k);
                layer.private = true;
                layer.decorators = Vec::new();
                layer.passes = Vec::new();
                layer.body = Vec::new();
                layer.results = unnamed(task);
                layers.push(layer);
            }
            for k in 1..=count {
                let layer = layer_name(&task.name, k);
                self.written_names.insert(
                    unqualified(&layer).to_string(),
                    unqualified(&task.name).to_string(),
                );
            }
            task.results = unnamed(task);
            task.body = Vec::new();
            layers.push(inner);
            self.wrapped.push((task.name.clone(), calls));
        }
        items.extend(layers.into_iter().map(Item::Task));
    }

    fn settle_wrappers(&mut self, items: &mut [Item]) {
        let places: HashMap<String, usize> = items
            .iter()
            .enumerate()
            .filter(|(_, item)| matches!(item, Item::Task(_)))
            .map(|(i, item)| (item.name().to_string(), i))
            .collect();
        for (task, calls) in self.wrappers_first() {
            self.current_module = module_of(&task).to_string();
            let settled = self
                .settle_wrapped(items, &places, &task, &calls)
                .and_then(|()| self.wrapped_privately(items, &places, &task, &calls));
            if !self.keep_going(settled) {
                self.broken.insert(task.clone());
                for k in 1..calls.len() {
                    self.broken.insert(layer_name(&task, k));
                }
            }
        }
        self.current_module.clear();
    }

    fn wrapped_privately(
        &self,
        items: &[Item],
        places: &HashMap<String, usize>,
        task: &str,
        calls: &[Expr],
    ) -> Result<()> {
        let Some(Item::Task(t)) = places.get(task).and_then(|&at| items.get(at)) else {
            return Ok(());
        };
        if t.private || t.owner_type().is_some_and(|ty| self.private.contains(ty)) {
            return Ok(());
        }
        let Some(info) = self.tasks.get(task) else {
            return Ok(());
        };
        let hidden = info.ret.results().iter().flat_map(named_types).find(|n| {
            self.shapes.get(*n).is_some_and(|s| s.private)
                || self.kinds.get(*n).is_some_and(|k| k.private)
        });
        match (hidden, calls.first()) {
            (Some(hidden), Some(call)) => err(
                call.span,
                format!(
                    "task '{}' is public, and its wrappers make it send '{}', which is private to its file, so other files couldn't name it; make the task 'priv' too, or the type public",
                    unqualified(task),
                    unqualified(hidden)
                ),
            ),
            _ => Ok(()),
        }
    }

    /// Topologically orders wrapped tasks after any wrappers they invoke so layer return types settle bottom-up.
    fn wrappers_first(&mut self) -> Vec<(String, Vec<Expr>)> {
        let wrapped = std::mem::take(&mut self.wrapped);
        let order: Vec<String> = wrapped.iter().map(|(task, _)| task.clone()).collect();
        let mut pending: HashMap<String, Vec<Expr>> = wrapped.into_iter().collect();
        let mut settled = Vec::new();
        for task in order {
            self.wrapper_first(&task, &mut pending, &mut settled);
        }
        settled
    }

    fn wrapper_first(
        &self,
        task: &str,
        pending: &mut HashMap<String, Vec<Expr>>,
        settled: &mut Vec<(String, Vec<Expr>)>,
    ) {
        let Some(calls) = pending.remove(task) else {
            return;
        };
        let module = module_of(task);
        for call in &calls {
            if let ExprKind::Call { name, .. } = &call.kind {
                let full = match self
                    .modules
                    .get(module)
                    .and_then(|scope| scope.imported(name))
                {
                    _ if name.starts_with(MEMBER_WRAPPER) => match method_parts(task) {
                        Some((owner, _)) => {
                            method_name(owner, name.trim_start_matches(MEMBER_WRAPPER))
                        }
                        None => continue,
                    },
                    _ if name.contains(MODULE_SEPARATOR) => name.clone(),
                    Some(imported) => imported.to_string(),
                    None => qualify(module, name),
                };
                self.wrapper_first(&full, pending, settled);
            }
        }
        settled.push((task.to_string(), calls));
    }

    fn settle_wrapped(
        &mut self,
        items: &mut [Item],
        places: &HashMap<String, usize>,
        task: &str,
        calls: &[Expr],
    ) -> Result<()> {
        if self.broken.contains(task) {
            return Ok(());
        }
        let Some(info) = self.tasks.get(task) else {
            return Ok(());
        };
        if let (Type::Results(_), Some(call)) = (&info.ret, calls.first()) {
            let what = match (method_parts(task), &info.owner) {
                (Some((_, method)), Some(owner)) if !owner.shared => format!("method '{}'", method),
                _ => format!("task '{}'", unqualified(task)),
            };
            return err(
                call.span,
                format!(
                    "{} sends several values, so it can't have wrappers yet: each wrapper is given it as a task value, which sends one value or nothing",
                    what
                ),
            );
        }
        let (types, taken) = self.task_params_taken(info);
        let params: Vec<(String, Type)> = info
            .params
            .iter()
            .zip(&types)
            .map(|((name, _), ty)| (name.clone(), ty.clone()))
            .collect();
        let layers = calls.len();
        let mut sends = self
            .tasks
            .get(&layer_name(task, layers))
            .map_or(Type::Unknown, |inner| inner.ret.clone());
        let written_task = unqualified(task);
        for (k, call) in calls.iter().enumerate().rev() {
            let ExprKind::Call { name, args, .. } = &call.kind else {
                return Err(Error::internal_at(call.span, "a wrapper that is no call"));
            };
            let written = unqualified(name);
            let member = name.strip_prefix(MEMBER_WRAPPER);
            let full = match member {
                Some(method) => self.member_wrapper(task, method, call.span)?,
                None => self.full_name(name),
            };
            if self.broken.contains(&full) {
                self.broken.insert(task.to_string());
                for k in 1..layers {
                    self.broken.insert(layer_name(task, k));
                }
                return Ok(());
            }
            let Some(wrapper) = self.tasks.get(&full).cloned() else {
                if BUILTIN_TASKS.contains(&name.as_str()) || number_cast(name).is_some() {
                    return err(
                        call.span,
                        format!(
                            "'{}' is built in, so it can't be a wrapper: a wrapper is a task or a shared method the program declares",
                            name
                        ),
                    );
                }
                if let Some((owner, field)) = self.shared_field(&full) {
                    return err(
                        call.span,
                        format!(
                            "'{}.{}' is a shared field, not a method, so it can't be a wrapper: a wrapper is a task or a shared method",
                            owner, field
                        ),
                    );
                }
                if method_parts(&full).is_some() {
                    return Err(self.unknown_task(&full, &[], call.span));
                }
                if let Some((says, written)) = self.own_shared_method(name, task) {
                    return err(
                        call.span,
                        format!(
                            "unknown task '{}'; {}, so it is written '$({})'",
                            name, says, written
                        ),
                    );
                }
                return err(
                    call.span,
                    format!(
                        "unknown task '{}'; a wrapper is a task that takes the task it wraps first",
                        name
                    ),
                );
            };
            if member.is_none() && wrapper.owner.as_ref().is_some_and(|owner| !owner.shared) {
                return err(
                    call.span,
                    format!(
                        "'{}' is a method of every value, called on one, so it can't be a wrapper of a task; it wraps a method of its own type, written '$(.{})' above it",
                        name,
                        wrapper
                            .owner
                            .as_ref()
                            .map_or("", |owner| owner.name.as_str())
                    ),
                );
            }
            // Member wrappers receive the wrapped value as receiver instead of first forwarded parameter.
            let skip = usize::from(member.is_some());
            let values = types.len() - skip;
            let (whose, besides) = match (member, method_parts(task)) {
                (Some(_), Some((_, method))) => (
                    format!("method '{}'", method),
                    " besides the value it is called on",
                ),
                _ => (format!("task '{}'", written_task), ""),
            };
            let this = wrapper
                .params
                .first()
                .map(|(_, ty)| ty.clone())
                .filter(|_| member.is_some());
            let wrapper = match member {
                Some(_) => TaskInfo {
                    params: wrapper.params.iter().skip(1).cloned().collect(),
                    passing: wrapper.passing.iter().skip(1).copied().collect(),
                    ..wrapper
                },
                None => wrapper,
            };
            match wrapper.params.first() {
                Some((_, ty)) if is_task(ty) => {}
                Some((_, Type::Closure(closure))) => {
                    return err(
                        call.span,
                        format!(
                            "wrapper '{}' takes {} first, the type of a lambda that keeps what it uses, and the rest of the chain is a task, which keeps nothing; take it as '{}'",
                            written,
                            Type::Closure(closure.clone()),
                            Type::Task(Box::new(closure.task.clone()))
                        ),
                    );
                }
                other => {
                    let takes =
                        other.map_or("nothing".to_string(), |(_, ty)| format!("{} first", ty));
                    let message = match member {
                        Some(method) => format!(
                            "method '{0}' takes {1} after its value, so it can't be a wrapper: a method wrapping another takes the rest of the chain first, a task taking the value first, as in '{0}(next: (flex& T@a, int) -> int, n: int) -> int'",
                            method, takes
                        ),
                        None => format!(
                            "task '{}' takes {}, so it can't be a wrapper: a wrapper takes the rest of the chain first, a task of the type of the task it wraps, as in 'task {}(next: (int) -> int, n: int) -> int'",
                            written, takes, written
                        ),
                    };
                    return err(call.span, message);
                }
            }
            let tail = match self.wrapper_tail(
                &wrapper,
                params.get(skip..).unwrap_or_default(),
                taken.get(skip..).unwrap_or_default(),
                written,
                written_task,
                call.span,
            )? {
                Some(tail) => tail,
                None => {
                    let message = match wrapper.params.len().checked_sub(1 + values) {
                        None => format!(
                            "wrapper '{}' takes {} after the next task, and {} takes {}{}, which a wrapper takes after its own values",
                            written,
                            count(wrapper.params.len() - 1, "value"),
                            whose,
                            count(values, "value"),
                            besides
                        ),
                        Some(own) => format!(
                            "wrapper '{}' takes the next task, {} of its own, then the {} of {}{}; {} given",
                            written,
                            count(own, "value"),
                            count(values, "value"),
                            whose,
                            besides,
                            count(args.len(), "value")
                        ),
                    };
                    return err(call.span, message);
                }
            };
            let grouped = tail.group.is_some();
            if tail.own != args.len() {
                let message = if grouped {
                    format!(
                        "wrapper '{}' takes the next task, {} of its own, then the task's values; {} given",
                        written,
                        count(tail.own, "value"),
                        count(args.len(), "value")
                    )
                } else {
                    format!(
                        "wrapper '{}' takes the next task, {} of its own, then the {} of {}{}; {} given",
                        written,
                        count(tail.own, "value"),
                        count(values, "value"),
                        whose,
                        besides,
                        count(args.len(), "value")
                    )
                };
                return err(call.span, message);
            }
            if matches!(wrapper.ret, Type::Results(_)) {
                return err(
                    call.span,
                    format!(
                        "wrapper '{}' sends several values, and a wrapper sends one value or nothing, as a task value does",
                        written
                    ),
                );
            }
            // Resolve wrapper type/region params against next-layer signature in caller naming order.
            let named_next = Type::Task(Box::new(TaskType {
                params: types.clone(),
                taken: taken.clone(),
                ret: sends.clone(),
            }));
            let next = named_next.normalized_tasks();
            if wrapper.types.is_empty()
                && !sends.unknown()
                && let Some((_, first)) = wrapper.params.first()
                && *first != next
            {
                let chain = if k + 1 == layers {
                    format!("task '{}'", written_task)
                } else {
                    format!("what comes after wrapper '{}'", written)
                };
                let unnamed = match (first, &next) {
                    (Type::Task(mine), Type::Task(theirs)) => mine
                        .params
                        .iter()
                        .zip(&theirs.params)
                        .any(|(mine, theirs)| {
                            mine.regions().is_empty() && !theirs.regions().is_empty()
                        }),
                    _ => false,
                };
                let regions = match &next {
                    Type::Task(task)
                        if unnamed && strip_all_regions(first) == strip_all_regions(&next) =>
                    {
                        let example = task.params.iter().find_map(|ty| match ty {
                            Type::Named(name, Some(_)) => Some(format!("{}@a", unqualified(name))),
                            _ => None,
                        });
                        format!(
                            "; they differ in their regions only: a value of a type holding text or pointers, as the value a method is called on, may be in any region the caller gives, so the wrapper names one, as in '{}'",
                            example.unwrap_or_else(|| "text@a".to_string())
                        )
                    }
                    _ => task_way_hint(&next, first),
                };
                return err(
                    call.span,
                    format!(
                        "{} is a {}, and wrapper '{}' takes a {} first{}",
                        chain, next, written, first, regions
                    ),
                );
            }
            if !sends.unknown() {
                for &(mine, theirs) in &tail.pairs {
                    let theirs = theirs + skip;
                    let (Some((param, ty)), Some(passing), Some((value, given)), Some(how)) = (
                        wrapper.params.get(mine),
                        wrapper.passing.get(mine),
                        params.get(theirs),
                        taken.get(theirs),
                    ) else {
                        continue;
                    };
                    let same_way = match (self.taken_for(&taken_by(param, ty, *passing), ty), how) {
                        (Taken::Region(_), Taken::Region(_)) => true,
                        (mine, theirs) => mine == *theirs,
                    };
                    let differs = (wrapper.types.is_empty() || ty.params().is_empty())
                        && !ty.unknown()
                        && !given.unknown()
                        && strip_all_regions(ty) != strip_all_regions(given);
                    if differs || !same_way {
                        let task_param = shown_param(value, given, task_passing(how));
                        let wrapper_param = shown_param(param, ty, *passing);
                        return err(
                            call.span,
                            format!(
                                "task '{}' takes '{}', and wrapper '{}' takes '{}' in its place",
                                written_task, task_param, written, wrapper_param
                            ),
                        );
                    }
                }
            }
            let mut given = HashMap::new();
            let mut regions = HashMap::new();
            let mut pairs: Vec<(&Type, &Type)> = wrapper
                .params
                .first()
                .map(|(_, ty)| (ty, &named_next))
                .into_iter()
                .collect();
            pairs.extend(tail.pairs.iter().filter_map(|&(mine, theirs)| {
                Some((&wrapper.params.get(mine)?.1, types.get(theirs + skip)?))
            }));
            pairs.extend(this.as_ref().zip(types.first()));
            for (pattern, actual) in pairs.into_iter().filter(|(_, actual)| !actual.unknown()) {
                unify_params(pattern, actual, &mut given);
                unify_regions(pattern, actual, &mut regions);
            }
            for &(mine, theirs) in &tail.pairs {
                if let (Some((param, Type::Region)), Some((given_name, Type::Region))) =
                    (wrapper.params.get(mine), params.get(theirs + skip))
                {
                    regions.insert(param.clone(), given_name.clone());
                }
            }
            let sent = self.settled_type(&wrapper.ret, &regions, &given, call.span)?;
            if let Some(param) = sent.params().first() {
                return err(
                    call.span,
                    format!(
                        "wrapper '{}' sends a {}, and '{}' is given by none of the next task and the task's values, so what it sends is not known here",
                        written, sent, param
                    ),
                );
            }
            if let Some((param, ty)) = wrapper.types.iter().find_map(|param| {
                given
                    .get(&param.name)
                    .filter(|ty| ty.regions().contains(&OWN_REGION))
                    .map(|ty| (&param.name, ty))
            }) {
                return err(call.span, own_region_type("wrapper", written, param, ty));
            }
            if sent.regions().contains(&ANY_REGION) {
                return err(
                    call.span,
                    format!(
                        "wrapper '{}' sends a value in a region none of the task's values is in, so the task can't send it",
                        written
                    ),
                );
            }
            let layer = if k == 0 {
                task.to_string()
            } else {
                layer_name(task, k)
            };
            if layer == "main" && sent != Type::Nothing {
                return err(
                    call.span,
                    format!(
                        "task 'main' cannot return a value, and wrapper '{}' sends {}",
                        written, sent
                    ),
                );
            }
            let mut given_args = vec![Expr::new(ExprKind::Var(layer_name(task, k + 1)), call.span)];
            given_args.extend(args.iter().cloned());
            given_args.extend(
                params
                    .iter()
                    .zip(&taken)
                    .skip(skip)
                    .map(|((param, _), how)| {
                        let value = Expr::new(ExprKind::Var(param.clone()), call.span);
                        match how {
                            Taken::Place(_) => Expr::new(ExprKind::Ref(Box::new(value)), call.span),
                            _ => value,
                        }
                    }),
            );
            let wrapped = match member {
                Some(method) => {
                    let value = Expr::new(ExprKind::Var(THIS.to_string()), call.span);
                    Expr::new(
                        ExprKind::MethodCall {
                            value: Box::new(value),
                            name: method.to_string(),
                            args: given_args,
                            dotted: None,
                        },
                        call.span,
                    )
                }
                None => Expr::new(
                    ExprKind::Call {
                        name: name.clone(),
                        types: Vec::new(),
                        args: given_args,
                    },
                    call.span,
                ),
            };
            let body = match sent {
                Type::Nothing => Stmt::new(StmtKind::Expr(wrapped), call.span),
                _ => Stmt::new(StmtKind::Send(vec![wrapped]), call.span),
            };
            if let Some(info) = self.tasks.get_mut(&layer) {
                info.ret = sent.clone();
            }
            if let Some(Item::Task(def)) = places.get(&layer).and_then(|&i| items.get_mut(i)) {
                def.results = if sent == Type::Nothing {
                    Vec::new()
                } else {
                    vec![ResultDef {
                        name: None,
                        ty_span: call.span,
                    }]
                };
                def.ret = sent.clone();
                def.body = vec![body];
            }
            self.wrapper_layers.insert(layer, types.len());
            sends = sent;
        }
        let callers = (0..layers)
            .map(|k| {
                if k == 0 {
                    task.to_string()
                } else {
                    layer_name(task, k)
                }
            })
            .collect();
        self.wrapped_chains.push((task.to_string(), callers));
        Ok(())
    }

    /// Resolves `$(.method)` on the wrapped method's own type; `alters` must match between wrapper and target.
    fn member_wrapper(&self, task: &str, method: &str, at: Span) -> Result<String> {
        let wrapped = self.tasks.get(task).and_then(|info| info.owner.clone());
        let (Some(wrapped), Some((owner, _))) =
            (wrapped.filter(|owner| !owner.shared), method_parts(task))
        else {
            let what = if self
                .tasks
                .get(task)
                .is_some_and(|info| info.owner.is_some())
            {
                "a shared method, called on no value"
            } else {
                "no method"
            };
            return err(
                at,
                format!(
                    "'.{}' names a method of the value the wrapped method is called on, and '{}' is {}; name a task, as in '$({})'",
                    method,
                    unqualified(task),
                    what,
                    method
                ),
            );
        };
        let full = method_name(owner, method);
        let Some(found) = self.tasks.get(&full).and_then(|info| info.owner.clone()) else {
            let what = if self.kinds.contains_key(owner) {
                "kind"
            } else {
                "shape"
            };
            return err(
                at,
                format!(
                    "{} '{}' has no method '{}'",
                    what,
                    unqualified(owner),
                    method
                ),
            );
        };
        if found.shared {
            return err(
                at,
                format!(
                    "'{0}' is a shared method of '{1}', called on no value, so it is named on its type, as in '$({1}.{0})'",
                    method,
                    unqualified(owner)
                ),
            );
        }
        match (wrapped.alters, found.alters) {
            (true, false) => err(
                at,
                format!(
                    "method '{}' alters the value it is called on, so a method wrapping it alters it too, 'alters {}(…)': with a value that never changes, it would see the value change under it",
                    wrapped.name, method
                ),
            ),
            (false, true) => err(
                at,
                format!(
                    "method '{0}' alters the value it is called on, and method '{1}' doesn't, so '{1}' may be called on a value that never changes, which '{0}' would change; a method wrapping '{1}' doesn't alter it",
                    method, wrapped.name
                ),
            ),
            _ => Ok(full),
        }
    }

    fn wrapper_tail(
        &self,
        wrapper: &TaskInfo,
        params: &[(String, Type)],
        taken: &[Taken],
        written: &str,
        written_task: &str,
        at: Span,
    ) -> Result<Option<WrapperTail>> {
        let Some(group) = wrapper
            .params
            .iter()
            .position(|(_, ty)| matches!(ty, Type::Group(_)))
        else {
            let Some(own) = wrapper.params.len().checked_sub(1 + params.len()) else {
                return Ok(None);
            };
            return Ok(Some(WrapperTail {
                own,
                pairs: (0..params.len()).map(|i| (1 + own + i, i)).collect(),
                group: None,
            }));
        };
        let Some((_, Type::Group(name))) = wrapper.params.get(group) else {
            return Ok(None);
        };
        let Some((next_name, Type::Task(next))) = wrapper.params.first() else {
            return Ok(None);
        };
        let Some(inner) = next
            .params
            .iter()
            .position(|ty| *ty == Type::Group(name.clone()))
        else {
            return err(
                at,
                format!(
                    "wrapper '{0}' takes the task's values in its group '{1}...', so '{2}' takes that group too, as in '{2}: ({1}...) -> R'",
                    written, name, next_name
                ),
            );
        };
        let (before, after) = (inner, next.params.len() - inner - 1);
        let named_after = wrapper.params.len() - group - 1;
        if named_after != after || group < 1 + before {
            return err(
                at,
                format!(
                    "wrapper '{}' names {} before its group and {} after it, and the type of '{}' names {} before the group and {} after it: the values named around the group are the task's, named as the next task's type names them, after the wrapper's own values",
                    written,
                    count(group.saturating_sub(1), "value"),
                    count(named_after, "value"),
                    next_name,
                    count(before, "value"),
                    count(after, "value")
                ),
            );
        }
        let own = group - 1 - before;
        if params.len() < before + after {
            return err(
                at,
                format!(
                    "task '{}' takes {}, and wrapper '{}' names {} around its group",
                    written_task,
                    count(params.len(), "value"),
                    written,
                    before + after
                ),
            );
        }
        let end = params.len() - after;
        if let Some(k) = (before..end).find(|&k| matches!(taken.get(k), Some(Taken::Region(_))))
            && let (Some(ahead), Some((region, _))) = (params.get(..k), params.get(k))
        {
            let how = |i: usize| match taken.get(i) {
                Some(Taken::Place(passing)) => format!("{} ", passing.word()),
                _ => String::new(),
            };
            let types: String = ahead
                .iter()
                .enumerate()
                .map(|(i, (_, ty))| format!("{}{}, ", how(i), ty))
                .collect();
            let names: String = ahead
                .iter()
                .enumerate()
                .map(|(i, (param, ty))| {
                    format!(
                        "{}{}: {}, ",
                        how(i),
                        if param == THIS { "v" } else { param },
                        ty
                    )
                })
                .collect();
            return err(
                at,
                format!(
                    "task '{0}' takes the region '{1}', which would be in the group of wrapper '{2}', and a group never holds a region; '{2}' names it as a parameter of its own, and '{3}' names it in its type, as in '{3}: ({5}@a, {4}...) -> R, {6}{1}: region, args: {4}...'",
                    written_task, region, written, next_name, name, types, names
                ),
            );
        }
        let mut pairs: Vec<(usize, usize)> = (0..before).map(|i| (1 + own + i, i)).collect();
        pairs.extend((0..after).map(|k| (group + 1 + k, end + k)));
        Ok(Some(WrapperTail {
            own,
            pairs,
            group: Some(group),
        }))
    }

    /// Evaluates wrapper custom args at startup: constants inline at call sites; dynamic values cache in `START_VALUES`.
    fn check_start_values(&mut self, items: &mut [Item]) {
        let places: HashMap<String, usize> = items
            .iter()
            .enumerate()
            .filter(|(_, item)| matches!(item, Item::Task(_)))
            .map(|(i, item)| (item.name().to_string(), i))
            .collect();
        let mut chains = std::mem::take(&mut self.wrapped_chains);
        chains.sort_by_key(|(task, _)| places.get(task).copied().unwrap_or(usize::MAX));
        let mut members = Vec::new();
        for (task, callers) in &chains {
            self.current_module = module_of(task).to_string();
            for caller in callers {
                let Some(&takes) = self.wrapper_layers.get(caller) else {
                    continue;
                };
                let Some(Item::Task(def)) = places.get(caller).and_then(|&i| items.get_mut(i))
                else {
                    continue;
                };
                let Some(call) = wrapper_call(&mut def.body) else {
                    continue;
                };
                let (wrapper, name, args, skip) = match &mut call.kind {
                    ExprKind::Call { name, args, .. } => {
                        (self.full_name(name), name.clone(), args, 0)
                    }
                    ExprKind::MethodCall { name, args, .. } => match method_parts(task) {
                        Some((owner, _)) => {
                            let full = method_name(owner, name);
                            let shown = codegen::notice_name(&full);
                            (full, shown, args, 1)
                        }
                        None => continue,
                    },
                    _ => continue,
                };
                let params: Vec<Type> = self
                    .tasks
                    .get(&wrapper)
                    .map(|info| {
                        info.params
                            .iter()
                            .skip(skip)
                            .map(|(_, ty)| ty.clone())
                            .collect()
                    })
                    .unwrap_or_default();
                let passing: Vec<Passing> = self
                    .tasks
                    .get(&wrapper)
                    .map(|info| info.passing.iter().skip(skip).copied().collect())
                    .unwrap_or_default();
                let own = args.len().saturating_sub(1 + takes - skip);
                let mut known = HashMap::new();
                if let (
                    Some(first),
                    Some(Expr {
                        kind: ExprKind::Var(next) | ExprKind::TaskValue(next),
                        span,
                        ..
                    }),
                ) = (params.first(), args.first())
                    && let Ok(next) = self.task_value_type(&self.full_name(next), *span)
                {
                    self.match_params(first, &next, &mut known);
                }
                for (i, arg) in args.iter_mut().enumerate().skip(1).take(own) {
                    if let Some(mark) = passing
                        .get(i)
                        .filter(|passing| passing.is_ref())
                        .map(|passing| passing.word())
                    {
                        self.record(Error::at(
                            arg.span,
                            format!("wrapper '{}' takes this as a place, with '{}', but {} are worked out once, where the program starts, so none is a place; take it as a value, or name the place inside the wrapper", codegen::notice_name(&wrapper), mark, WRAPPER_VALUES),
                        ));
                        if !matches!(arg.kind, ExprKind::Ref(_)) {
                            let span = arg.span;
                            *arg = Expr::new(ExprKind::Ref(Box::new(arg.clone())), span);
                        }
                        continue;
                    }
                    let expected = params
                        .get(i)
                        .map(|ty| ty.map_params(&mut |name| known.get(name).cloned()))
                        .filter(|ty| ty.params().is_empty() && !ty.unknown())
                        .map(|ty| ty.without_regions());
                    let mut value = arg.clone();
                    let checked = self.check_start_value(&mut value, expected.as_ref());
                    if checked.is_ok() && constant_value(&value) {
                        *arg = value;
                        continue;
                    }
                    let span = arg.span;
                    let ty = match checked {
                        Ok(()) => value.ty.clone().unwrap_or(Type::Unknown),
                        Err(error) => {
                            self.record(error);
                            Type::Unknown
                        }
                    };
                    let member = format!("v{}", members.len() + 1);
                    let place = format!(
                        "wrapper '{}' on task '{}'",
                        codegen::notice_name(&wrapper),
                        codegen::notice_name(task)
                    );
                    let field = Field {
                        name: member.clone(),
                        ty,
                        span,
                        ty_span: span,
                        private: false,
                        read: false,
                        default_region: false,
                        passing: Passing::Copy,
                        default: Some(value),
                    };
                    members.push(SharedField {
                        field,
                        flex: false,
                        bind: false,
                        start: Some(place),
                    });
                    self.start_values.push(StartValue {
                        task: task.clone(),
                        wrapper: name.clone(),
                        member: member.clone(),
                        span,
                    });
                    *arg = Expr::new(
                        ExprKind::Shared {
                            shape: START_VALUES.to_string(),
                            field: member,
                        },
                        span,
                    );
                }
            }
        }
        self.current_module.clear();
        if !members.is_empty() {
            let values = ShapeDef {
                name: START_VALUES.to_string(),
                types: Vec::new(),
                given: Vec::new(),
                fields: Vec::new(),
                shared: members,
                span: Span::default(),
                private: false,
                follows: Vec::new(),
            };
            self.shapes.insert(START_VALUES.to_string(), values);
        }
    }

    fn said_at_start(&mut self, recorded: usize, what: &str) {
        for error in self.errors.iter_mut().skip(recorded) {
            *error = at_start_error(error.clone(), what);
        }
    }

    fn check_start_value(&mut self, value: &mut Expr, expected: Option<&Type>) -> Result<()> {
        let copies = self.unsettled_copies.len();
        let types = self.unsettled_types.len();
        let recorded = self.errors.len();
        self.scopes = vec![Scope::default()];
        self.at_start = Some(WRAPPER_VALUES);
        let checked = self.check_expr(value).and_then(|_| match expected {
            Some(ty) => self.coerce(value, ty),
            None => Ok(()),
        });
        self.at_start = None;
        self.said_at_start(recorded, WRAPPER_VALUES);
        self.scopes.clear();
        let uncopied = self.unsettled_copies.get(copies).copied();
        let untold = self.unsettled_types.get(types).cloned();
        self.unsettled_copies.truncate(copies);
        self.unsettled_types.truncate(types);
        checked.map_err(|error| at_start_error(error, WRAPPER_VALUES))?;
        if let Some(at) = uncopied {
            return err(at, self.unsettled_copy(at));
        }
        if let Some((at, task, param)) = untold {
            return err(at, self.untold_type(&task, &param));
        }
        let ty = value.ty.clone().unwrap_or(Type::Unknown);
        if ty == Type::Nothing {
            return err(
                value.span,
                "this sends nothing, so it is no value a wrapper can be given",
            );
        }
        if unsettled(&ty) {
            return err(
                value.span,
                format!(
                    "can't tell which type this value is: the wrapper takes it as whatever type the value says, and '{}' doesn't say all of it",
                    ty
                ),
            );
        }
        if holds_pointers(&ty, &self.regional)
            || ty.regions().iter().any(|region| *region != ANY_REGION)
            || self.holds_file(&ty)
        {
            return err(
                value.span,
                format!(
                    "{} are worked out once, where the program starts, and kept as long as it runs, which no region lasts, so none can hold a pointer, a slice, text of a region, a 'File', or a value holding one; this one is {}",
                    WRAPPER_VALUES,
                    a_type(&ty)
                ),
            );
        }
        Ok(())
    }

    /// Topologically orders dynamic `START_VALUES` initializers by call-graph dependencies (rejects cycles).
    fn order_start_values(&mut self, items: &[Item]) {
        if self.start_values.is_empty() || !self.errors.is_empty() {
            return;
        }
        let mut graph = CallGraph::of(items, self);
        let Some(def) = self.shapes.get(START_VALUES) else {
            return;
        };
        let values: HashMap<&str, &Expr> = def
            .shared
            .iter()
            .filter_map(|member| {
                member
                    .field
                    .default
                    .as_ref()
                    .map(|value| (member.field.name.as_str(), value))
            })
            .collect();
        let mut all = Calls::default();
        let mut named = Vec::new();
        for value in values.values() {
            walk_expr(value, &mut |e| {
                self.note_calls(e, &mut all);
                note_value(e, &mut named);
            });
        }
        graph.settle_values(&all, named);
        let mut units: Vec<&str> = Vec::new();
        for start in &self.start_values {
            if !units.contains(&start.task.as_str()) {
                units.push(&start.task);
            }
        }
        let mut needs: HashMap<&str, Vec<(&str, &StartValue)>> = HashMap::new();
        let mut mistakes = Vec::new();
        for start in &self.start_values {
            let Some(value) = values.get(start.member.as_str()) else {
                continue;
            };
            let mut roots = Calls::default();
            walk_expr(value, &mut |e| self.note_calls(e, &mut roots));
            let reached = graph.reach(&roots);
            if reached.contains_key(&start.task) {
                let through = graph.path(&reached, &start.task);
                mistakes.push(Error::at(
                    start.span,
                    format!(
                        "this value of wrapper '{0}' is worked out where the program starts, before task '{1}' can run, and it calls '{1}'{2}, whose wrappers read it; give a value that doesn't call it, or work it out inside the wrapper",
                        unqualified(&start.wrapper),
                        start.task,
                        through
                    ),
                ));
                continue;
            }
            for unit in units
                .iter()
                .filter(|unit| **unit != start.task && reached.contains_key(**unit))
            {
                needs
                    .entry(start.task.as_str())
                    .or_default()
                    .push((unit, start));
            }
        }
        if mistakes.is_empty() {
            match start_order(&units, &needs) {
                Ok(order) => {
                    let rank: HashMap<&str, usize> = order
                        .iter()
                        .enumerate()
                        .map(|(i, unit)| (*unit, i))
                        .collect();
                    let mut ranked: Vec<(usize, usize, String)> = self
                        .start_values
                        .iter()
                        .enumerate()
                        .map(|(i, start)| {
                            (
                                rank.get(start.task.as_str()).copied().unwrap_or(usize::MAX),
                                i,
                                start.member.clone(),
                            )
                        })
                        .collect();
                    ranked.sort();
                    let position: HashMap<String, usize> = ranked
                        .into_iter()
                        .enumerate()
                        .map(|(at, (_, _, member))| (member, at))
                        .collect();
                    if let Some(def) = self.shapes.get_mut(START_VALUES) {
                        def.shared.sort_by_key(|member| {
                            position
                                .get(&member.field.name)
                                .copied()
                                .unwrap_or(usize::MAX)
                        });
                    }
                }
                Err(circle) => {
                    let parts: Vec<String> = circle
                        .iter()
                        .map(|(start, called)| {
                            format!(
                                "a value of wrapper '{}' on task '{}' calls '{}'",
                                unqualified(&start.wrapper),
                                start.task,
                                called
                            )
                        })
                        .collect();
                    let at = circle
                        .first()
                        .map_or(Span::default(), |(start, _)| start.span);
                    mistakes.push(Error::at(
                        at,
                        format!(
                            "these wrapper values are worked out where the program starts, and each needs another worked out first, in a circle: {}; work one of them out inside its wrapper instead",
                            parts.join(", and ")
                        ),
                    ));
                }
            }
        }
        for mistake in mistakes {
            self.record(mistake);
        }
    }

    fn note_calls(&self, e: &Expr, calls: &mut Calls) {
        let wrote = |ty: &Type, calls: &mut Calls| {
            let mut found = Vec::new();
            self.str_methods(ty, &mut Vec::new(), &mut found);
            calls.tasks.extend(found);
        };
        match &e.kind {
            ExprKind::Call { name, types, args } => {
                if self.tasks.contains_key(name) {
                    calls.tasks.push(name.clone());
                }
                for (ty, _) in types {
                    wrote(ty, calls);
                }
                if name == "show" {
                    for arg in args {
                        if let Some(ty) = &arg.ty {
                            wrote(ty, calls);
                        }
                    }
                }
            }
            ExprKind::TaskValue(name) | ExprKind::Closure { lambda: name, .. } => {
                calls.tasks.push(name.clone())
            }
            ExprKind::Invoke { .. } => calls.invokes = true,
            ExprKind::ToText { value, .. } | ExprKind::ToJson { value, .. } => {
                if let Some(ty) = &value.ty {
                    wrote(ty, calls);
                }
            }
            _ => {}
        }
    }

    fn str_methods(&self, ty: &Type, seen: &mut Vec<String>, found: &mut Vec<String>) {
        match ty {
            Type::Maybe(inner) | Type::Array(inner, _) | Type::Slice(inner, _) => {
                self.str_methods(inner, seen, found)
            }
            Type::Map(key, value, _) => {
                self.str_methods(key, seen, found);
                self.str_methods(value, seen, found);
            }
            Type::Tuple(items) => items
                .iter()
                .for_each(|item| self.str_methods(item, seen, found)),
            Type::Named(name, _) if !seen.contains(name) => {
                seen.push(name.clone());
                let own = self
                    .made_of
                    .get(name)
                    .map_or(name.as_str(), |made| made.name.as_str());
                let method = method_name(own, STR);
                if self.tasks.contains_key(&method) {
                    found.push(method);
                } else {
                    for part in self.written_parts(ty).unwrap_or_default() {
                        self.str_methods(&part, seen, found);
                    }
                }
            }
            _ => {}
        }
    }

    fn decorator_fits(&self, stmt: &Stmt) -> Result<()> {
        let StmtKind::Expr(call) = &stmt.kind else {
            return Ok(());
        };
        let ExprKind::Call { name, args, .. } = &call.kind else {
            return Ok(());
        };
        // `main` runs after startup decorators, so decorators cannot target `main`.
        if let Some(ExprKind::Var(decorated)) = args.first().map(|arg| &arg.kind)
            && self.full_name(decorated) == "main"
        {
            return err(
                call.span,
                "'main' takes no startup decorator: the decorators run before 'main', where the program starts, and nothing calls 'main' as a value; call what the decorator would do first thing in 'main' instead",
            );
        }
        if self
            .tasks
            .get(&self.full_name(name))
            .and_then(|info| info.owner.as_ref())
            .is_some_and(|owner| !owner.shared)
        {
            return err(
                call.span,
                format!(
                    "'{}' is a method of every value, called on one, so it can't be a decorator; a shared method can",
                    name
                ),
            );
        }
        if let Some((owner, field)) = self.shared_field(&self.full_name(name)) {
            return err(
                call.span,
                format!(
                    "'{}.{}' is a shared field, not a method, so it can't be a decorator: a decorator is a task or a shared method",
                    owner, field
                ),
            );
        }
        if BUILTIN_TASKS.contains(&name.as_str()) || number_cast(name).is_some() {
            return err(
                call.span,
                format!(
                    "'{}' is built in, so it can't be a decorator: a decorator is a task or a shared method the program declares",
                    name
                ),
            );
        }
        if !self.tasks.contains_key(&self.full_name(name))
            && self.macros.contains_key(name.as_str())
        {
            return err(
                call.span,
                format!(
                    "'{}' is a macro, a value that never changes, so it can't be a decorator: a decorator is a task or a shared method",
                    name
                ),
            );
        }
        if let Some(ExprKind::Var(decorated)) = args.first().map(|arg| &arg.kind)
            && let Some(hint) = self.own_shared_method(name, decorated)
        {
            if hint.1.starts_with(MEMBER_WRAPPER) {
                return err(
                    call.span,
                    format!(
                        "'{}' is a method of every value, called on one, so it can't be a startup decorator, which runs where no value is yet; a shared method can",
                        name
                    ),
                );
            }
            return err(
                call.span,
                format!(
                    "unknown task '{}'; {}, so it is written '${}'",
                    name, hint.0, hint.1
                ),
            );
        }
        let Some(info) = self.tasks.get(&self.full_name(name)).filter(|info| {
            info.types.is_empty() && info.owner.as_ref().is_none_or(|owner| owner.shared)
        }) else {
            return Ok(());
        };
        let Some(ExprKind::Var(decorated)) = args.first().map(|arg| &arg.kind) else {
            return Ok(());
        };
        let own = format!("{}{}", self.current_module, MODULE_SEPARATOR);
        let written = name.strip_prefix(own.as_str()).unwrap_or(name);
        let first = match info.params.first() {
            Some((_, ty)) if is_task(ty) => ty,
            Some((_, Type::Closure(closure))) => {
                return err(
                    call.span,
                    format!(
                        "decorator '{}' takes {} first, the type of a lambda that keeps what it uses, and the task below it is a task, which keeps nothing; take it as '{}'",
                        written,
                        Type::Closure(closure.clone()),
                        Type::Task(Box::new(closure.task.clone()))
                    ),
                );
            }
            other => {
                let takes = other.map_or("nothing".to_string(), |(_, ty)| format!("{} first", ty));
                return err(
                    call.span,
                    format!(
                        "task '{}' takes {}, so it can't be a decorator: a decorator takes the task written below it first, as in 'task {}(f: (int) -> int)'",
                        written, takes, written
                    ),
                );
            }
        };
        let needed = self
            .param_defaults
            .get(&self.full_name(name))
            .and_then(|defaults| defaults.iter().position(Option::is_some))
            .unwrap_or(info.params.len());
        if args.len() > info.params.len() || args.len() < needed {
            let values = info.params.len() - 1;
            let takes = if values == 0 {
                "the task and nothing else, so it is written '$".to_string() + written + "'"
            } else if needed <= 1 {
                format!(
                    "the task and up to {}, written '${}' or '${}(…)'",
                    count(values, "value"),
                    written,
                    written
                )
            } else if needed < info.params.len() {
                format!(
                    "the task and {} to {} values, written '${}(…)'",
                    needed - 1,
                    values,
                    written
                )
            } else {
                format!(
                    "the task and {}, written '${}(…)'",
                    count(values, "value"),
                    written
                )
            };
            return err(
                call.span,
                format!(
                    "decorator '{}' takes {}, got {}",
                    written,
                    takes,
                    count(args.len() - 1, "value")
                ),
            );
        }
        let value = self.task_value_type(&self.full_name(decorated), call.span)?;
        if !value.unknown() && value != *first {
            return err(
                call.span,
                format!(
                    "task '{}' is a {}, and decorator '{}' takes a {} first",
                    unqualified(decorated),
                    value,
                    written,
                    first
                ),
            );
        }
        Ok(())
    }

    fn task_value_type(&self, name: &str, span: Span) -> Result<Type> {
        if self.broken.contains(name) {
            return Ok(Type::Unknown);
        }
        let Some(info) = self.tasks.get(name) else {
            return Err(Error::internal_at(
                span,
                format!("no task '{}' to name as a value", name),
            ));
        };
        let written = unqualified(name);
        if !info.types.is_empty() {
            return err(
                span,
                format!(
                    "task '{}' takes types, so it can't be a value yet; only a task that takes none can",
                    written
                ),
            );
        }
        if matches!(info.ret, Type::Results(_)) {
            let base = name.split(LAYER).next().unwrap_or(name);
            let what = match (method_parts(base), &info.owner) {
                (Some((_, method)), Some(owner)) if !owner.shared => format!("method '{}'", method),
                _ => format!("task '{}'", unqualified(base)),
            };
            return err(
                span,
                format!(
                    "{} sends several values, so it can't be a value yet; a task value sends one value or nothing",
                    what
                ),
            );
        }
        let (params, taken) = self.task_params_taken(info);
        Ok(Type::Task(Box::new(
            TaskType {
                params,
                taken,
                ret: info.ret.clone(),
            }
            .normalized(),
        )))
    }

    fn task_params_taken(&self, info: &TaskInfo) -> (Vec<Type>, Vec<Taken>) {
        let alters = info
            .owner
            .as_ref()
            .is_some_and(|owner| owner.alters && !owner.shared);
        info.params
            .iter()
            .zip(info.passing.iter().chain(std::iter::repeat(&Passing::Copy)))
            .map(|((param, ty), passing)| match ty {
                Type::Named(name, Some(_))
                    if param == THIS
                        && !self.regional.contains(name)
                        && !self.takes_region.contains(name) =>
                {
                    (
                        Type::Named(name.clone(), None),
                        if alters {
                            Taken::Place(Passing::FlexRef)
                        } else {
                            Taken::Value
                        },
                    )
                }
                _ if param == THIS && alters => (ty.clone(), Taken::Place(Passing::FlexRef)),
                _ => (
                    ty.clone(),
                    self.taken_for(&taken_by(param, ty, *passing), ty),
                ),
            })
            .unzip()
    }

    /// Resolves `[@r](...)` closure captures and verifies outer visibility.
    fn check_closure(
        &mut self,
        lambda: &str,
        region: &str,
        mode: KeptMode,
        places: &[KeptPlace],
        span: Span,
    ) -> Result<Type> {
        let mode_word = match mode {
            KeptMode::Plain => "",
            KeptMode::Flex => "flex ",
            KeptMode::Bind => "bind ",
        };
        let written = format!("[{}@{}]", mode_word, region);
        if self.at_start.is_some() {
            return err(
                span,
                format!(
                    "'{}' keeps what the lambda uses in a region; give a task by its name, or a plain lambda",
                    written
                ),
            );
        }
        match self.lookup(region) {
            Some(info) if info.ty == Type::Region => {}
            Some(_) => {
                return err(
                    span,
                    format!(
                        "'{}' keeps what the lambda uses in a region, and '{}' is a variable",
                        written, region
                    ),
                );
            }
            None => {
                return err(
                    span,
                    format!(
                        "'{}' keeps what the lambda uses in region '{}', which isn't one here; declare it with 'region {}', or take it as a parameter",
                        written, region, region
                    ),
                );
            }
        }
        self.visible_region(region, span, true)?;
        for place in places {
            self.check_kept_place(place, region)?;
        }
        let mut seen_regions: Vec<String> = vec![region.to_string()];
        for place in places {
            if let Some(info) = self
                .scopes
                .iter()
                .rev()
                .find_map(|scope| scope.names.get(&place.name))
            {
                seen_regions.extend(
                    info.ty
                        .regions()
                        .into_iter()
                        .filter(|name| !unnamed_region(name))
                        .map(str::to_string),
                );
            }
        }
        let mut outer: Vec<(String, VarInfo)> = Vec::new();
        let mut seen: HashSet<&str> = HashSet::new();
        for scope in self.scopes.iter().rev() {
            for (name, info) in &scope.names {
                if !seen.insert(name.as_str()) {
                    continue;
                }
                if info.result
                    || (info.ty == Type::Region && !seen_regions.contains(name))
                    || name == SHOWN
                    || name == THIS
                {
                    continue;
                }
                outer.push((name.clone(), info.clone()));
            }
        }
        outer.sort_by_key(|(_, info)| (info.span.line, info.span.col));
        let names = self
            .scopes
            .iter()
            .flat_map(|scope| scope.names.keys().cloned())
            .collect();
        self.lambda_outer.insert(lambda.to_string(), names);
        self.note_lambda_loops(lambda);
        let within = self
            .current_lambda
            .clone()
            .filter(|current| self.kept_lambdas.contains_key(current));
        let owned = outer
            .iter()
            .map(|(name, info)| (name.clone(), self.name_owners(name, info)))
            .collect();
        let uses = self
            .kept_lambdas
            .get(lambda)
            .map(|kept| kept.uses.clone())
            .unwrap_or_default();
        self.kept_lambdas.insert(
            lambda.to_string(),
            KeptLambda {
                region: region.to_string(),
                mode,
                span,
                outer,
                within,
                uses,
                places: places.to_vec(),
                owned,
            },
        );
        self.kept_order.retain(|name| name != lambda);
        self.kept_order.push(lambda.to_string());
        if self.broken.contains(lambda) {
            return Ok(Type::Unknown);
        }
        let Some(info) = self.tasks.get(lambda) else {
            return Err(Error::internal_at(span, format!("no lambda '{}'", lambda)));
        };
        let (params, taken) = self.task_params_taken(info);
        let task = TaskType {
            params,
            taken,
            ret: info.ret.clone(),
        };
        Ok(Type::Closure(Box::new(
            ClosureType {
                task,
                region: region.to_string(),
                mode,
            }
            .normalized(),
        )))
    }

    /// Captured `places` must originate outside the closure's capture `region` so references never dangle.
    fn check_kept_place(&self, place: &KeptPlace, region: &str) -> Result<()> {
        let name = &place.name;
        let word = place.passing.word();
        let _ = self.lookup(name);
        let at = |name: &str| {
            self.scopes
                .iter()
                .enumerate()
                .rev()
                .find_map(|(i, scope)| scope.names.get(name).map(|info| (i, info)))
        };
        let Some((depth, info)) = at(name) else {
            return err(
                place.span,
                format!(
                    "unknown variable '{}'; a lambda keeps as a place a variable of the code around it",
                    name
                ),
            );
        };
        if info.ty == Type::Region {
            return err(
                place.span,
                format!(
                    "'{}' is a region, which a lambda names alone, as in '[@{}]', and keeps nothing of as a place",
                    name, name
                ),
            );
        }
        if info.result {
            return err(
                place.span,
                format!(
                    "'{}' is a result of this task, which only '<-' sets, so a lambda doesn't keep it as a place",
                    name
                ),
            );
        }
        if place.passing == Passing::FlexRef {
            let mut var = Expr::new(ExprKind::Var(name.clone()), place.span);
            var.ty = Some(info.ty.clone());
            self.given_place(&var, &Taker::Kept(name))
                .map_err(|error| Error {
                    span: Some(place.span),
                    ..error
                })?;
        } else if place.passing == Passing::BindRef && self.bind_has_contents(&info.ty) {
            let mut var = Expr::new(ExprKind::Var(name.clone()), place.span);
            var.ty = Some(info.ty.clone());
            self.given_place(&var, &Taker::KeptBind(name))
                .map_err(|error| Error {
                    span: Some(place.span),
                    ..error
                })?;
        }
        let Some((region_depth, region_info)) = at(region) else {
            return Ok(());
        };
        let refuse = |why: String| {
            err(
                place.span,
                format!(
                    "this lambda keeps '{0}' as a place, '{1} {0}', so it ends before '{0}' does, and it ends with region '{2}', which {3}; declare a region after '{0}', in its block, and keep the lambda there",
                    name, word, region, why
                ),
            )
        };
        if region_info.param {
            return refuse("is given to the task, so it outlives the task's variables".to_string());
        }
        if region_info.kept {
            return refuse("the lambda around this one keeps what it uses in, so it outlives what is declared inside that lambda".to_string());
        }
        let after = region_depth > depth
            || (region_depth == depth
                && (region_info.span.line, region_info.span.col) > (info.span.line, info.span.col));
        if !after {
            return refuse(format!(
                "is declared before '{}', at {}:{}",
                name, region_info.span.line, region_info.span.col
            ));
        }
        Ok(())
    }

    fn kept_scope(&self, lambda: &str) -> Option<Scope> {
        let kept = self.kept_lambdas.get(lambda)?;
        let mut around = Scope::default();
        for (name, info) in &kept.outer {
            let mut info = info.clone();
            info.kept = true;
            info.bind_reads = false;
            info.param = false;
            info.passing = Passing::Copy;
            info.refers = None;
            if info.ty == Type::Region {
                info.allocates = info.allocates || *name == kept.region;
            } else if let Some(place) = kept.places.iter().find(|place| place.name == *name) {
                info.passing = place.passing;
                info.mode = match place.passing {
                    Passing::FlexRef => Mode::Flex,
                    Passing::BindRef => Mode::Bind,
                    _ => Mode::Fixed,
                };
            } else {
                // A `[bind @r]` lambda changes only what its copies share with every copy of it: the items of a
                // slice, a map, what a pointer points to. Its own copy of anything else it only reads, which is
                // what lets a bind lambda be copied.
                info.mode = match kept.mode {
                    KeptMode::Flex => Mode::Flex,
                    KeptMode::Bind if shared_contents(&info.ty) => Mode::Bind,
                    KeptMode::Bind => {
                        info.bind_reads = true;
                        Mode::Fixed
                    }
                    KeptMode::Plain => Mode::Fixed,
                };
            }
            around.names.insert(name.clone(), info);
        }
        Some(around)
    }

    fn check_kept_use(&self, name: &str, ty: &Type, span: Span) -> Result<()> {
        let Some(kept) = self
            .current_lambda
            .as_ref()
            .and_then(|lambda| self.kept_lambdas.get(lambda))
        else {
            return Ok(());
        };
        if *ty == Type::Region || kept.places.iter().any(|place| place.name == name) {
            return Ok(());
        }
        if let Some(other) = ty
            .regions()
            .into_iter()
            .find(|region| *region != kept.region && !unnamed_region(region))
        {
            return err(
                span,
                format!(
                    "'{0}' is in region '{1}', and this lambda keeps what it uses in '{2}', where nothing points into '{1}'; copy it into '{2}' first, as in 'fixed mine = {0}.copy() at {2}', and use that, or keep '{0}' as a place, '[fixed& {0}, @{2}]', with '{2}' declared after it",
                    name, other, kept.region
                ),
            );
        }
        if held_value(ty, &self.held_types) {
            return err(
                span,
                format!(
                    "'{0}' is {1}, which is never copied, so a lambda can't keep a copy of it; give it as a parameter, 'flex& {0}', or keep it as a place, '[flex& {0}, @s]', in a region declared after it",
                    name,
                    held_phrase(ty)
                ),
            );
        }
        Ok(())
    }

    fn finish_kept(&mut self) {
        // Walk inner-to-outer so enclosing closures inherit everything captured by nested closures.
        for lambda in self.kept_order.clone().iter().rev() {
            let Some(kept) = self.kept_lambdas.get(lambda) else {
                continue;
            };
            let Some(within) = kept.within.clone() else {
                continue;
            };
            let passed: Vec<(String, Type)> = kept
                .uses
                .iter()
                .filter_map(|name| {
                    kept.outer
                        .iter()
                        .find(|(outer, info)| outer == name && info.kept)
                        .map(|(name, info)| (name.clone(), info.ty.clone()))
                })
                .collect();
            let span = kept.span;
            let inner = kept.region.clone();
            let mut mistakes = Vec::new();
            if let Some(around) = self.kept_lambdas.get_mut(&within) {
                for (name, ty) in passed {
                    let place = around.places.iter().any(|place| place.name == name);
                    if !place && ty != Type::Region {
                        let refused = ty
                            .regions()
                            .into_iter()
                            .any(|region| region != inner && !unnamed_region(region));
                        if let Some(other) = ty
                            .regions()
                            .into_iter()
                            .find(|region| *region != around.region && !unnamed_region(region))
                            .filter(|_| !refused)
                        {
                            mistakes.push(Error::at(span, format!("this lambda uses '{0}', which the lambda around it keeps for it, and '{0}' is in region '{1}', where that lambda, kept in '{2}', keeps nothing; copy it into '{2}' first, as in 'fixed mine = {0}.copy() at {2}'", name, other, around.region)));
                            continue;
                        }
                        if held_value(&ty, &self.held_types) && !refused {
                            mistakes.push(Error::at(span, format!("this lambda uses '{}', {}, which the lambda around it would keep a copy of, and it is never copied", name, held_phrase(&ty))));
                            continue;
                        }
                    }
                    if !around.uses.contains(&name) {
                        around.uses.push(name);
                    }
                }
            }
            for mistake in mistakes {
                self.record(mistake);
            }
        }
        for lambda in &self.kept_order {
            let Some(kept) = self.kept_lambdas.get(lambda) else {
                continue;
            };
            let region_field = |name: &str| Field {
                name: name.to_string(),
                ty: Type::Region,
                span: kept.span,
                ty_span: kept.span,
                private: false,
                read: false,
                default_region: false,
                passing: Passing::Copy,
                default: None,
            };
            let mut fields = vec![region_field(&kept.region)];
            for (name, info) in &kept.outer {
                if info.ty == Type::Region && *name != kept.region && info.allocates {
                    fields.push(region_field(name));
                }
            }
            for (name, info) in &kept.outer {
                if !kept.uses.contains(name) || info.ty == Type::Region {
                    continue;
                }
                let place = kept
                    .places
                    .iter()
                    .find(|place| place.name == *name)
                    .map(|place| place.passing);
                fields.push(Field {
                    name: name.clone(),
                    ty: match place {
                        Some(_) => Type::Ptr(Box::new(info.ty.clone()), None),
                        None => info.ty.clone(),
                    },
                    passing: place.unwrap_or(Passing::Copy),
                    span: kept.span,
                    ty_span: kept.span,
                    private: false,
                    read: false,
                    default_region: false,
                    default: None,
                });
            }
            let shape = ShapeDef {
                name: kept_name(lambda),
                types: Vec::new(),
                given: Vec::new(),
                fields,
                shared: Vec::new(),
                span: kept.span,
                private: true,
                follows: Vec::new(),
            };
            self.made_shapes.push(Item::Shape(shape));
        }
    }

    fn shortcut_lambda_name<'a>(&self, expr: &'a Expr) -> Option<&'a str> {
        let name = match &expr.kind {
            ExprKind::Var(name) | ExprKind::TaskValue(name) => name.as_str(),
            ExprKind::Closure { lambda, .. } => lambda.as_str(),
            _ => return None,
        };
        if self.shortcut_lambdas.contains_key(name) {
            Some(name)
        } else {
            None
        }
    }

    fn is_shortcut_lambda(&self, expr: &Expr) -> bool {
        self.shortcut_lambda_name(expr).is_some()
    }

    fn prepare_shortcut_lambda(&mut self, expr: &mut Expr, expected: &Type) -> Result<()> {
        let Some(name) = self.shortcut_lambda_name(expr).map(str::to_string) else {
            return Ok(());
        };
        self.reached_shortcut_lambdas.insert(name.clone());
        if self.inferred_shortcut_lambdas.contains(&name) {
            return Ok(());
        }
        let Some(mut task) = self.shortcut_lambdas.get(&name).cloned() else {
            return Ok(());
        };

        if let ExprKind::Closure {
            lambda,
            region,
            mode,
            places,
        } = &expr.kind
            && !self.kept_lambdas.contains_key(lambda)
        {
            let (lambda, region, mode, places) =
                (lambda.clone(), region.clone(), *mode, places.clone());
            let _ = self.check_closure(&lambda, &region, mode, &places, expr.span);
        }

        let mut cur_expected = expected;
        while let Type::Maybe(inner) | Type::Or(inner, _) = cur_expected {
            cur_expected = inner;
        }
        // Expected closure param/return regions are distinct from the closure's own capture region.
        let renamed;
        if let Some(kept) = task.kept.as_ref().map(|kept| kept.region.clone()) {
            renamed = match cur_expected {
                Type::Closure(closure) => cur_expected.map_regions(&mut |region| {
                    Some(if region == closure.region {
                        kept.clone()
                    } else {
                        region.to_string()
                    })
                }),
                Type::Task(task_ty) => Type::Task(Box::new(task_ty.normalized_avoiding(&kept))),
                other => other.clone(),
            };
            cur_expected = &renamed;
        }

        match cur_expected {
            Type::Task(task_ty) if task_ty.params.len() == task.params.len() => {
                for (p, exp_ty) in task.params.iter_mut().zip(&task_ty.params) {
                    if p.ty.unknown() && !exp_ty.unknown() && !matches!(exp_ty, Type::Param(_)) {
                        p.ty = exp_ty.clone();
                    }
                }
                if task.ret.unknown()
                    && !task_ty.ret.unknown()
                    && !matches!(task_ty.ret, Type::Param(_))
                {
                    task.ret = task_ty.ret.clone();
                }
            }
            Type::Closure(closure_ty) if closure_ty.task.params.len() == task.params.len() => {
                for (p, exp_ty) in task.params.iter_mut().zip(&closure_ty.task.params) {
                    if p.ty.unknown() && !exp_ty.unknown() && !matches!(exp_ty, Type::Param(_)) {
                        p.ty = exp_ty.clone();
                    }
                }
                if task.ret.unknown()
                    && !closure_ty.task.ret.unknown()
                    && !matches!(closure_ty.task.ret, Type::Param(_))
                {
                    task.ret = closure_ty.task.ret.clone();
                }
            }
            _ => {}
        }

        if !task.params.iter().any(|p| p.ty.unknown()) {
            self.infer_shortcut_lambda(&name, task)?;
            if let Some(info) = self.tasks.get(&name).cloned() {
                let (params, taken) = self.task_params_taken(&info);
                let task_type = TaskType {
                    params,
                    taken,
                    ret: info.ret.clone(),
                };
                if let Some(kept) = self
                    .shortcut_lambdas
                    .get(&name)
                    .and_then(|t| t.kept.as_ref())
                {
                    let closure = ClosureType {
                        task: task_type,
                        region: kept.region.clone(),
                        mode: kept.mode,
                    };
                    expr.ty = Some(Type::Closure(Box::new(closure.normalized())));
                } else {
                    expr.ty = Some(Type::Task(Box::new(task_type.normalized())));
                }
            }
        }
        Ok(())
    }

    fn infer_shortcut_lambda(&mut self, name: &str, mut task: TaskDef) -> Result<()> {
        if let Some(info) = self.tasks.get_mut(name) {
            info.params = task
                .params
                .iter()
                .map(|p| (p.name.clone(), p.ty.clone()))
                .collect();
            info.passing = task.params.iter().map(|p| p.passing).collect();
            info.ret = task.ret.clone();
        }

        if task.kept.is_none() {
            let seen = self
                .scopes
                .iter()
                .flat_map(|scope| scope.names.keys().cloned())
                .collect();
            self.lambda_outer.insert(name.to_string(), seen);
        }
        let saved_scopes = std::mem::take(&mut self.scopes);
        let saved_current_task = std::mem::replace(&mut self.current_task, task.name.clone());
        let saved_current_lambda = self.current_lambda.replace(task.name.clone());
        let saved_current_ret = self.current_ret.take();
        let saved_param_index = std::mem::take(&mut self.param_index);
        let saved_current_method = self.current_method.clone();
        let saved_this_type = self.this_type.clone();
        let saved_in_pattern_default = self.in_pattern_default;
        let saved_current_owner = self.current_owner.clone();
        let saved_current_shape = self.current_shape.clone();
        let saved_current_type = self.current_type.clone();
        let saved_result_names = std::mem::take(&mut self.result_names);
        let saved_unset = std::mem::take(&mut self.unset);
        let saved_loops = std::mem::take(&mut self.loops);
        let saved_loop_name = self.loop_name.take();
        let saved_stepping = self.stepping.take();

        // Expected param/return types come from call context, keeping resolved shapes without re-checking as header types.
        for p in task.params.iter_mut() {
            if !p.ty.unknown() {
                let mut ty = p.ty.clone();
                self.settle_applications(&mut ty, p.ty_span)?;
                p.ty = ty;
            }
        }
        if !task.ret.unknown() {
            let mut ret = task.ret.clone();
            self.settle_applications(&mut ret, task.span)?;
            task.ret = ret;
        }
        let res = self.check_task(&mut task);

        if let Some(inferred_ret) = self.current_ret.as_ref()
            && !inferred_ret.unknown()
        {
            task.ret = inferred_ret.clone();
        }
        if task.ret.unknown()
            && let Some(Stmt {
                kind: StmtKind::Send(values),
                ..
            }) = task.body.first()
            && let Some(ty) = values.first().and_then(|val| val.ty.as_ref())
            && !ty.unknown()
        {
            task.ret = ty.clone();
        }

        self.scopes = saved_scopes;
        self.current_task = saved_current_task;
        self.current_lambda = saved_current_lambda;
        self.current_ret = saved_current_ret;
        self.param_index = saved_param_index;
        self.current_method = saved_current_method;
        self.this_type = saved_this_type;
        self.in_pattern_default = saved_in_pattern_default;
        self.current_owner = saved_current_owner;
        self.current_shape = saved_current_shape;
        self.current_type = saved_current_type;
        self.result_names = saved_result_names;
        self.unset = saved_unset;
        self.loops = saved_loops;
        self.loop_name = saved_loop_name;
        self.stepping = saved_stepping;

        self.inferred_shortcut_lambdas.insert(name.to_string());
        res?;

        if let Some(info) = self.tasks.get_mut(name) {
            info.params = task
                .params
                .iter()
                .map(|p| (p.name.clone(), p.ty.clone()))
                .collect();
            info.passing = task.params.iter().map(|p| p.passing).collect();
            info.ret = task.ret.clone();
        }
        self.shortcut_lambdas.insert(name.to_string(), task);
        self.inferred_shortcut_lambdas.insert(name.to_string());
        Ok(())
    }

    fn check_invoke(&mut self, callee: &mut Expr, args: &mut [Expr], span: Span) -> Result<Type> {
        if self.is_shortcut_lambda(callee) {
            let mut arg_types = Vec::new();
            for arg in args.iter_mut() {
                arg_types.push(self.check_expr(arg)?);
            }
            let expected = Type::Task(Box::new(TaskType {
                params: arg_types.clone(),
                taken: vec![Taken::Place(Passing::Copy); arg_types.len()],
                ret: Type::Unknown,
            }));
            self.prepare_shortcut_lambda(callee, &expected)?;
        }
        self.calling = matches!(callee.kind, ExprKind::Var(_));
        self.calling_field = matches!(callee.kind, ExprKind::Field(..));
        let ty = self.check_expr(callee);
        self.calling = false;
        self.calling_field = false;
        let ty = ty?;
        if ty.unknown() {
            self.check_each(args);
            return Ok(Type::Unknown);
        }
        if bind_lambda(&ty) || (held_lambda(&ty) && !matches!(callee.kind, ExprKind::Var(_))) {
            self.check_bind_call(callee, &ty)?;
        }
        let named = match &callee.kind {
            ExprKind::Var(name) => format!("'{}'", name),
            _ => "this value".to_string(),
        };
        let kept = match &ty {
            Type::Closure(closure) => Some(closure.region.clone()),
            _ => None,
        };
        let task = match &ty {
            Type::Task(task) => task.clone(),
            Type::Closure(closure) => Box::new(closure.task.clone()),
            Type::Maybe(inner) if is_task(inner) => {
                return err(
                    callee.span,
                    format!(
                        "{} is a {}, which may be none; extract the task first, as in 'when f is {{g}}' or 'f {{ … }}'",
                        named, ty
                    ),
                );
            }
            _ => {
                return err(
                    callee.span,
                    format!(
                        "{} is of type {}, not a task, so it can't be called",
                        named, ty
                    ),
                );
            }
        };
        if let Some(at) = region_after(args) {
            return err(
                at,
                "a call of a task value names every region it gives in its parentheses, as in 'g(r, 3)'; a region after a call gives a named task the region it takes last",
            );
        }
        if args.len() != task.params.len() {
            if task
                .params
                .iter()
                .any(|param| matches!(param, Type::Group(_)))
            {
                return err(
                    span,
                    format!(
                        "{} is a task of type {}, which takes {} named one by one and a group's values where its type writes the group, as in 'next(args...)', got {}",
                        named,
                        ty,
                        count(task.params.len() - 1, "value"),
                        match args
                            .iter()
                            .filter(|arg| !matches!(arg.kind, ExprKind::Spread(_)))
                            .count()
                        {
                            given if given == args.len() => count(given, "value"),
                            given => format!("{} and a group's values", count(given, "value")),
                        }
                    ),
                );
            }
            return err(
                span,
                format!(
                    "{} is a task of type {}, which takes {}, got {}",
                    named,
                    ty,
                    count(task.params.len(), "argument"),
                    args.len()
                ),
            );
        }
        let info = TaskInfo {
            types: Vec::new(),
            params: task
                .params
                .iter()
                .enumerate()
                .map(|(i, ty)| {
                    (
                        task.region(i)
                            .map_or_else(|| format!("value {}", i + 1), str::to_string),
                        ty.clone(),
                    )
                })
                .collect(),
            passing: (0..task.params.len()).map(|i| task.passing(i)).collect(),
            ret: task.ret.clone(),
            owner: None,
        };
        self.kept_call = kept;
        let sent = self.check_call_args(span, &callee_text(callee), &mut Vec::new(), args, &info);
        self.kept_call = None;
        sent
    }

    /// Disambiguates `name {}` between empty struct literal and variable Plan B (parser parses both as `StructInit`).
    fn resolve_empty_plan_b(&self, expr: &mut Expr) {
        let ExprKind::StructInit { name, fields, .. } = &mut expr.kind else {
            return;
        };
        if !fields.is_empty()
            || (self.sees(name) && self.shapes.contains_key(name.as_str()))
            || self.lookup(name).is_none()
        {
            return;
        }
        let value = Expr::new(ExprKind::Var(std::mem::take(name)), expr.span);
        expr.kind = ExprKind::PlanB {
            value: Box::new(value),
            error: None,
            body: Vec::new(),
        };
    }

    fn infer_expr(&mut self, expr: &mut Expr) -> Result<Type> {
        let span = expr.span;
        if matches!(expr.kind, ExprKind::MethodCall { .. }) {
            self.check_method_call(expr)?;
            self.on_values.insert(span.place_key());
        }
        let on_a_value = self.on_values.contains(&span.place_key());
        if matches!(expr.kind, ExprKind::Shared { .. }) {
            return self.check_shared_use(expr);
        }
        if matches!(expr.kind, ExprKind::Pairs(_)) {
            let value = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
            expr.kind = ExprKind::Shortcut {
                value: Box::new(Expr::new(value, span)),
                region: None,
                region_span: span,
            };
        }
        if matches!(expr.kind, ExprKind::Shortcut { .. }) {
            self.expand_shortcut(expr)?;
        }
        if let Some(ty) = self.resolve_map_field(expr)? {
            return Ok(ty);
        }
        if matches!(&expr.kind, ExprKind::Field(_, item) if item.starts_with(SAFE_ITEM)) {
            return self.check_safe_item(expr);
        }
        match &mut expr.kind {
            ExprKind::Spread(inner) => self.check_spread(inner, span),
            ExprKind::IntLit(_) => Ok(Type::Int),
            ExprKind::FloatLit(_) => Ok(Type::Float),
            ExprKind::CharLit(_) => Ok(Type::Char),
            ExprKind::BoolLit(_) => Ok(Type::Bool),
            ExprKind::TextLit(_) => Ok(Type::Text(None)),
            ExprKind::NoneLit => Ok(Type::None),
            ExprKind::RegionAfter(_) => err(
                span,
                "a region is named after a call only when the call takes one last",
            ),
            ExprKind::Ref(_) => err(
                span,
                "'&' marks a place given to a 'flex&' or 'fixed&' parameter, as in 'f(&a)', named by a reference, as in 'flex& y = &a', or whose address is shown or compared, as in 'show(&a)' or '&a == &b'; anywhere else, write the value itself",
            ),
            ExprKind::Shared { .. } => Err(Error::internal_at(
                span,
                "a shared field read as another value",
            )),
            ExprKind::TypeOf(_) => Ok(Type::Text(None)),
            ExprKind::Macro { value, .. } => Ok(value.ty.clone().unwrap_or(Type::Unknown)),
            ExprKind::Closure {
                lambda,
                region,
                mode,
                places,
            } => {
                let (lambda, region, mode, places) =
                    (lambda.clone(), region.clone(), *mode, places.clone());
                self.check_closure(&lambda, &region, mode, &places, span)
            }
            ExprKind::Kept { value, .. } => Ok(value.ty.clone().unwrap_or(Type::Unknown)),
            ExprKind::TaskValue(name) => self.check_task_value(name, span),
            ExprKind::Invoke { callee, args } => self.check_invoke(callee, args, span),
            ExprKind::Var(name)
                if self.lookup(name).is_none()
                    && self.sees(name)
                    && self.macros.contains_key(name.as_str()) =>
            {
                Ok(Type::Unknown)
            }
            ExprKind::Var(name) => self.check_var(name, span),
            ExprKind::Field(base, field) => self.check_field_access(base, field, span),
            ExprKind::Index(base, index) => {
                let base_ty = self.check_expr(base)?;
                self.check_index(base, &base_ty, index, span)
            }
            ExprKind::Lookup(base, index) => {
                let base_ty = self.check_expr(base)?;
                self.check_lookup(&base_ty, index, span)
            }
            ExprKind::Array(values) => self.check_array(values, span),
            ExprKind::Tuple(values) => self.check_tuple(values),
            ExprKind::Repeat { value, count } => self.check_repeat(value, count, span),
            ExprKind::Call { name, types, args } => {
                self.check_task_call(span, on_a_value, name, types, args)
            }
            ExprKind::Unary(..) => self.check_unary(expr),
            ExprKind::Construct { kind, args, .. } if self.broken.contains(kind.as_str()) => {
                self.check_each(args);
                Ok(Type::Unknown)
            }
            ExprKind::Construct {
                kind,
                tag,
                args,
                types,
            } => self.check_construct(kind, tag, args, types, span),
            ExprKind::New {
                ty,
                ty_span,
                value,
                region,
                region_span,
            } => self.check_new(ty, *ty_span, value, region, *region_span),
            ExprKind::Shortcut { .. } | ExprKind::Pairs(_) => {
                Err(Error::internal_at(span, "a shortcut that was not expanded"))
            }
            ExprKind::MapOp {
                map,
                op,
                key,
                region,
                region_span,
            } => {
                let (op, region_span) = (*op, *region_span);
                self.check_map_op(map, op, key.as_deref_mut(), region, region_span)
            }
            ExprKind::Deref(e) => self.check_deref(e, span),
            ExprKind::StructInit {
                name,
                types,
                fields,
            } => self.check_struct_init(span, name, types, fields),
            ExprKind::Range(..) => err(
                span,
                "a range can only be used in 'each' or to take part of an array or slice, as in 'xs[1..3]'",
            ),
            ExprKind::Own(inner) => self.check_own(inner, span),
            ExprKind::Fail(error) => self.check_fail(error),
            ExprKind::PlanB { value, error, body } => {
                self.check_plan_b(span, value, error.as_ref(), body)
            }
            ExprKind::Choice(stmt) => {
                Ok(self.check_branching_value(stmt)?.unwrap_or(Type::Unknown))
            }
            ExprKind::LoopValue(value) => self.check_loop_value(value, span),
            ExprKind::Edit { items, op, args } => self.check_edit(span, items, *op, args),
            ExprKind::Scan {
                args,
                region,
                region_span,
            } => self.check_scan(span, args, region, *region_span),
            ExprKind::Join {
                parts,
                region,
                region_span,
            } => self.check_join(parts, region, *region_span),
            ExprKind::Binary(..) => self.check_binary_expr(expr),
            ExprKind::ToText {
                value,
                region,
                region_span,
            } => self.check_to_text(value, region, *region_span),
            ExprKind::ToJson {
                value,
                region,
                region_span,
            } => self.check_to_json(value, region, *region_span),
            ExprKind::Copy {
                value,
                region,
                region_span,
            } => self.check_copy(span, value, region.as_deref(), *region_span),
            ExprKind::Wrap(_) => expr
                .ty
                .clone()
                .ok_or_else(|| Error::internal_at(span, "a wrapped value has no type")),
            ExprKind::Widen(_) => expr
                .ty
                .clone()
                .ok_or_else(|| Error::internal_at(span, "a widened value has no type")),
            ExprKind::Pipe(_) => self.check_pipe(expr),
            ExprKind::Piped(_) => expr
                .ty
                .clone()
                .ok_or_else(|| Error::internal_at(span, "a piped value outside its pipe")),
            ExprKind::MethodCall { value, args, .. }
                if value.ty.as_ref().is_some_and(Type::unknown) =>
            {
                self.check_each(args);
                Ok(Type::Unknown)
            }
            ExprKind::MethodCall { name, .. } => Err(Error::internal_at(
                span,
                format!("the method call '{}' was not rewritten", name),
            )),
        }
    }

    #[inline(never)]
    fn check_task_value(&mut self, name: &str, span: Span) -> Result<Type> {
        if is_lambda(name) {
            let seen = self
                .scopes
                .iter()
                .flat_map(|scope| scope.names.keys().cloned())
                .collect();
            self.lambda_outer.insert(name.to_string(), seen);
            self.note_lambda_loops(name);
        }
        self.task_value_type(name, span)
    }

    #[inline(never)]
    fn check_field_access(
        &mut self,
        base: &mut Expr,
        field: &mut String,
        span: Span,
    ) -> Result<Type> {
        if self.group_of(base).is_some() {
            if field == GROUP_TUPLE_WRITTEN {
                *field = GROUP_TUPLE.to_string();
            }
            return self.check_group_member(base, field, span);
        }
        if field == GROUP_TUPLE_WRITTEN {
            let message = match &base.kind {
                ExprKind::Var(name) => format!("'({0}...)' makes a tuple of a group's values, as '(args...)' does, and '{0}' is no group's values", name),
                _ => "'(...)' around a value and three dots makes a tuple of a group's values, as '(args...)' does, and this is no group's values".to_string(),
            };
            return err(base.span, message);
        }
        if !self.called_on_a_value()
            && matches!(&base.kind, ExprKind::Var(name) if name == THIS)
        {
            return err(
                span,
                self.not_a_method(&format!("{}{}", MODULE_SEPARATOR, field)),
            );
        }
        let reached = std::mem::take(&mut self.reaching);
        let called = std::mem::take(&mut self.calling_field);
        self.reading_length = field == LEN && matches!(base.kind, ExprKind::Var(_));
        self.reaching = matches!(base.kind, ExprKind::Var(_) | ExprKind::Field(..));
        let base_ty = self.check_expr(base);
        self.reaching = false;
        self.reading_length = false;
        let ty = self.field_type(&base_ty?, field, span)?;
        if held_value(&ty, &self.held_types) && !reached && !called {
            return err(
                span,
                format!(
                    "'{0}' is {1}, which changes what it keeps and is never copied, so it stays in the value holding it: {2}",
                    field,
                    held_phrase(&ty),
                    if held_lambda(&ty) {
                        format!("call it, '….{}(…)'", field)
                    } else {
                        format!("use its fields and methods, as '….{}.x', or give it as a place, '&….{}'", field, field)
                    }
                ),
            );
        }
        Ok(ty)
    }

    /// Split from `task_call_setup` because `check_call_args` recurses through nested calls and must keep small stack frames.
    fn check_task_call(
        &mut self,
        span: Span,
        on_a_value: bool,
        name: &str,
        types: &mut Vec<TypeArg>,
        args: &mut Vec<Expr>,
    ) -> Result<Type> {
        let (info, group) = match self.task_call_setup(span, on_a_value, name, types, args)? {
            CallSetup::Checked(ty) => return Ok(ty),

            CallSetup::Call(info, group) => (info, group),
        };
        self.check_call_args(span, name, types, args, &info)
            .map_err(|error| group_hint(error, group.as_ref()))
    }

    fn task_call_setup(
        &mut self,
        span: Span,
        on_a_value: bool,
        name: &str,
        types: &mut [TypeArg],
        args: &mut Vec<Expr>,
    ) -> Result<CallSetup> {
        if let Some(at) = region_after(args)
            && (name == "show" || number_cast(name).is_some())
        {
            let what = if name == "show" {
                "'show' writes each value in a region of its own".to_string()
            } else {
                format!("'{}(…)' makes a number, which holds no memory", name)
            };
            return err(at, format!("{}, so no region is named after it", what));
        }
        if name == "show" {
            for arg in args.iter_mut() {
                self.check_shown(arg)?;
            }
            return Ok(CallSetup::Checked(Type::Nothing));
        }
        if name == CHAN_NEW {
            let Some((elem_ty, _)) = types.first().cloned() else {
                return err(
                    span,
                    "'chan_new' takes one type argument naming what the channel carries, as in 'chan_new<int>(10)'",
                );
            };
            if types.len() != 1 {
                return err(
                    span,
                    "'chan_new' takes one type argument naming what the channel carries, as in 'chan_new<int>(10)'",
                );
            }
            if args.len() != 1 {
                return err(span, format!("'chan_new' takes 1 argument (capacity), got {}", args.len()));
            }
            let Some(arg0) = args.first_mut() else { unreachable!() };
            let cap_ty = self.check_expr(arg0)?;
            if !cap_ty.is_integer() && !cap_ty.unknown() {
                return err(arg0.span, "channel capacity must be an integer");
            }
            return Ok(CallSetup::Checked(Type::Chan(Box::new(elem_ty))));
        }
        if name == SEND {
            if self.tasks.contains_key(name) {
                // User defined a task named "send", let it fall through to regular task call
            } else if args.len() == 2 {
                let Some((arg0, rest)) = args.split_first_mut() else { unreachable!() };
                let Some(arg1) = rest.first_mut() else { unreachable!() };
                let chan_ty = self.check_expr(arg0)?;
                let elem_ty = match &chan_ty {
                    Type::Chan(inner) => inner.as_ref().clone(),
                    Type::Unknown => Type::Unknown,
                    _ => return err(arg0.span, format!("'send' takes a channel as its first argument, got {}", chan_ty)),
                };
                let item_ty = self.check_expr(arg1)?;
                if let Type::Own(payload) = &elem_ty {
                    if !matches!(arg1.kind, ExprKind::Own(_)) {
                        return err(
                            arg1.span,
                            format!("expected 'own' value for channel payload of type '{}'; write 'own ...'", elem_ty),
                        );
                    }
                    if !fits(&item_ty, payload) && !item_ty.unknown() {
                        return err(arg1.span, format!("cannot send value of type {} on channel carrying {}", item_ty, payload));
                    }
                } else if !elem_ty.unknown() && !fits(&item_ty, &elem_ty) && !item_ty.unknown() {
                    return err(arg1.span, format!("cannot send value of type {} on channel carrying {}", item_ty, elem_ty));
                }
                return Ok(CallSetup::Checked(Type::Bool));
            }
        }
        if name == RECV && !self.tasks.contains_key(name) && args.len() == 1 {
            let Some(arg0) = args.first_mut() else { unreachable!() };
            let chan_ty = self.check_expr(arg0)?;
            if matches!(&chan_ty, Type::Chan(_) | Type::Unknown) {
                let elem_ty = match &chan_ty {
                    Type::Chan(inner) => inner.as_ref().clone(),
                    _ => Type::Unknown,
                };
                let ret_ty = match elem_ty {
                    Type::Own(payload) => *payload,
                    other => other,
                };
                return Ok(CallSetup::Checked(ret_ty));
            }
        }
        if name == TRY_RECV && !self.tasks.contains_key(name) && args.len() == 1 {
            let Some(arg0) = args.first_mut() else { unreachable!() };
            let chan_ty = self.check_expr(arg0)?;
            if matches!(&chan_ty, Type::Chan(_) | Type::Unknown) {
                let elem_ty = match &chan_ty {
                    Type::Chan(inner) => inner.as_ref().clone(),
                    _ => Type::Unknown,
                };
                let item_ty = match elem_ty {
                    Type::Own(payload) => *payload,
                    other => other,
                };
                return Ok(CallSetup::Checked(Type::Maybe(Box::new(item_ty))));
            }
        }
        if name == CLOSE && !self.tasks.contains_key(name) && args.len() == 1 {
            let Some(arg0) = args.first_mut() else { unreachable!() };
            let chan_ty = self.check_expr(arg0)?;
            if matches!(&chan_ty, Type::Chan(_) | Type::Unknown) {
                return Ok(CallSetup::Checked(Type::Nothing));
            }
        }
        if let Some(into) = number_cast(name) {
            return self
                .check_number_cast(&into, types, args, span)
                .map(CallSetup::Checked);
        }
        let info = self
            .tasks
            .get(name)
            .filter(|_| self.sees(name))
            .ok_or_else(|| self.unknown_task(name, types, span))?
            .clone();
        if let Some(owner) = info.owner.as_ref().filter(|_| !on_a_value)
            && let Some((of, _)) = method_parts(name)
        {
            let written = format!("{}{}{}", unqualified(of), MODULE_SEPARATOR, owner.name);
            if !owner.shared {
                return err(
                    span,
                    format!(
                        "'{0}' is called on a value of '{1}', as in 'x.{2}(…)'; only a shared method, written 'shared {2}(…)', is called on '{1}' itself",
                        written,
                        unqualified(of),
                        owner.name
                    ),
                );
            }
            if self.private.contains(name) && module_of(of) != self.current_module {
                return err(
                    span,
                    format!(
                        "'{}' is a private method of '{}', which only its own file can use",
                        owner.name,
                        unqualified(of)
                    ),
                );
            }
        }
        if self.broken.contains(name) {
            self.check_each(args);
            return Ok(CallSetup::Checked(Type::Unknown));
        }
        let callee = match method_parts(name).filter(|_| !on_a_value) {
            Some((of, method)) => {
                format!("method '{}{}{}'", unqualified(of), MODULE_SEPARATOR, method)
            }
            None => format!("task '{}'", name),
        };
        let spreads = args
            .iter()
            .any(|arg| matches!(arg.kind, ExprKind::Spread(_)));
        let group = match info.params.last() {
            Some((_, Type::Group(group))) if !spreads => Some((
                group.clone(),
                args.len() + 1 - info.params.len().min(args.len() + 1),
            )),
            _ => None,
        };
        let info = match self.group_call_info(&info, args, types, span, &callee)? {
            Some(expanded) => expanded,
            None => info,
        };
        if let Some(spread) = args
            .iter()
            .position(|arg| matches!(arg.kind, ExprKind::Spread(_)))
        {
            self.check_spread_given(name, &callee, &info, args, spread)?;
        }
        self.settle_call_region(span, &callee, args, &info.params)?;
        self.fill_defaults(name, args);
        if args.len() != info.params.len() {
            // Catch `f(a < b, c > (d))` misparsed as generic type args.
            if let Some((name, at)) = args.iter().find_map(|arg| match &arg.kind {
                ExprKind::Call { name, types, .. }
                    if !types.is_empty()
                        && self.lookup(name).is_some()
                        && !self.tasks.contains_key(name.as_str()) =>
                {
                    Some((name, arg.span))
                }
                _ => None,
            }) {
                return err(at, misread_comparison(name));
            }
            return err(
                span,
                format!(
                    "{} expects {}, got {}",
                    callee,
                    self.expected_args(name, info.params.len(), 0),
                    args.len()
                ),
            );
        }
        Ok(CallSetup::Call(info, group))
    }

    fn fill_defaults(&self, task: &str, args: &mut Vec<Expr>) {
        let Some(defaults) = self.param_defaults.get(task) else {
            return;
        };
        if args
            .iter()
            .any(|arg| matches!(arg.kind, ExprKind::Spread(_)))
        {
            return;
        }
        while let Some(Some(value)) = defaults.get(args.len()) {
            args.push(value.clone());
        }
    }

    fn expected_args(&self, task: &str, all: usize, skip: usize) -> String {
        let all = all.saturating_sub(skip);
        let needed = self
            .param_defaults
            .get(task)
            .and_then(|defaults| defaults.iter().position(Option::is_some))
            .map(|first| first.saturating_sub(skip));
        match needed {
            Some(0) => format!("up to {}", count(all, "argument")),
            Some(needed) if needed < all => format!("{} to {} arguments", needed, all),
            _ => count(all, "argument"),
        }
    }

    fn filled_default(&self, task: &str, i: usize, arg: &Expr) -> bool {
        self.param_defaults
            .get(task)
            .and_then(|defaults| defaults.get(i))
            .and_then(Option::as_ref)
            .is_some_and(|value| value.span == arg.span)
    }

    fn own_shared_method(&self, name: &str, decorated: &str) -> Option<(String, String)> {
        if name.contains(MODULE_SEPARATOR) || self.tasks.contains_key(&self.full_name(name)) {
            return None;
        }
        let (owner, _) = method_parts(decorated)?;
        let info = self.tasks.get(&method_name(owner, name))?;
        if info.owner.as_ref().is_some_and(|owner| !owner.shared) {
            return Some((
                format!(
                    "'{}' is a method of every value of '{}', called on the value the wrapped method is",
                    name,
                    unqualified(owner)
                ),
                format!(".{}", name),
            ));
        }
        let written = format!("{}.{}", unqualified(owner), name);
        Some((
            format!(
                "'{}' is a shared method of '{}', named on it everywhere",
                name,
                unqualified(owner)
            ),
            written,
        ))
    }

    fn shared_field<'n>(&self, name: &'n str) -> Option<(&'n str, &'n str)> {
        if self.tasks.contains_key(name) {
            return None;
        }
        method_parts(name).filter(|(owner, field)| {
            self.shapes.get(*owner).is_some_and(|shape| {
                shape
                    .shared
                    .iter()
                    .any(|member| member.field.name == *field)
            })
        })
    }

    fn unknown_task(&self, name: &str, types: &[TypeArg], span: Span) -> Error {
        // Catch old `send (x)` syntax misparsed as a call.
        if let Some((owner, method)) = method_parts(name) {
            if self.shared_field(name).is_some() {
                return Error::at(
                    span,
                    format!(
                        "'{0}.{1}' is a shared field, not a method, so it is read as '{0}.{1}', without '(…)'",
                        owner, method
                    ),
                );
            }
            let what = if self.kinds.contains_key(owner) {
                "kind"
            } else {
                "shape"
            };
            let or_variant = if what == "kind" { "variant or " } else { "" };
            return Error::at(
                span,
                format!(
                    "{} '{}' has no {}shared method '{}'",
                    what, owner, or_variant, method
                ),
            );
        }
        if let Some(of) = &self.current_type
            && let Some(method) = self
                .tasks
                .get(&method_name(of, name))
                .and_then(|info| info.owner.as_ref())
        {
            let how = match (method.shared, self.called_on_a_value()) {
                (true, _) => format!("'{}.{}(…)'", unqualified(of), name),
                (false, true) => format!("'.{}(…)', or 'x.{}(…)' on another value", name, name),
                (false, false) => format!("'x.{}(…)', on a value of it", name),
            };
            return Error::at(
                span,
                format!(
                    "'{}' is a method of '{}', so a call names what it is called on, as in {}",
                    name,
                    unqualified(of),
                    how
                ),
            );
        }
        if !types.is_empty() && self.lookup(name).is_some() {
            return Error::at(span, misread_comparison(name));
        }
        let hint = match name {
            "send" => "; a task sends its result with '<-'".to_string(),
            "free" => "; Vela has no 'free': memory in a region is freed when the block declaring the region closes".to_string(),
            _ if self.module_used(name).is_some() => format!("; '{0}' is a module, so name a task in it, as in '{0}.name(…)'", name),
            _ if self.macros.contains_key(name) => "; it is a macro, a value that never changes, so it is used without '()'".to_string(),
            _ => self.elsewhere(name),
        };
        Error::at(span, format!("unknown task '{}'{}", name, hint))
    }

    fn check_var(&mut self, name: &str, span: Span) -> Result<Type> {
        if self.is_moved(name) {
            return err(
                span,
                format!(
                    "use of moved value '{0}'; '{0}' was moved with 'own {0}'",
                    name
                ),
            );
        }
        let calling = std::mem::take(&mut self.calling);
        let reaching = std::mem::take(&mut self.reaching);
        let length_only = std::mem::take(&mut self.reading_length);
        let info = self.lookup_or_err(name, span)?;
        let (ty, kept, mode) = (info.ty.clone(), info.kept, info.mode);
        if kept {
            self.check_kept_use(name, &ty, span)?;
        }
        if !held_lambda(&ty) && held_value(&ty, &self.held_types) && !calling && !reaching {
            return err(
                span,
                format!(
                    "'{0}' holds a '[flex @r]' lambda, which changes what it keeps, so '{0}' is never copied: use its fields and methods, as '{0}.field', or give it as a place, '&{0}', to a 'flex& x: {1}' parameter",
                    name, ty
                ),
            );
        }
        // `[flex @r]`/`[bind @r]` closures cannot be copied and must be used via calls or `&` places.
        if held_lambda(&ty) && !calling {
            return err(
                span,
                format!(
                    "'{0}' is a '{2}' lambda, which changes what it keeps, so it is never copied: call it, '{0}(…)', or give it as a place, '&{0}', to a 'flex& f: {1}' parameter",
                    name,
                    ty,
                    held_word(&ty)
                ),
            );
        }
        // Calling mutating closures requires a mutable place.
        if held_lambda(&ty) && !mode.can_change_contents(true) {
            return err(
                span,
                format!(
                    "'{0}' is a '{1}' lambda, and calling it changes what it keeps, so it is called through a place that changes, a 'flex' variable or a 'flex&', which '{0}' isn't",
                    name,
                    held_word(&ty)
                ),
            );
        }
        if self.unset.contains(name) {
            return err(span, format!("'{}' might not be set here", name));
        }
        if let Type::Group(group) = &ty
            && !self.spreading
        {
            return err(
                span,
                format!(
                    "'{0}' holds the values of the group '{1}...', which go on whole to a task that takes them, as in 'next({0}...)', or are counted, '{0}.len'",
                    name, group
                ),
            );
        }
        if !length_only {
            self.note_slice_use(name, span);
        }
        Ok(ty)
    }

    fn check_construct(
        &mut self,
        kind: &str,
        tag: &str,
        args: &mut [Expr],
        written: &mut [TypeArg],
        span: Span,
    ) -> Result<Type> {
        let def = self
            .kinds
            .get(kind)
            .cloned()
            .ok_or_else(|| Error::internal_at(span, format!("unknown kind '{}'", kind)))?;
        let variant = def
            .variants
            .iter()
            .find(|v| v.tag == *tag)
            .cloned()
            .ok_or_else(|| Error::internal_at(span, format!("unknown variant '{}'", tag)))?;
        if let Some(at) = region_after(args) {
            return err(
                at,
                format!(
                    "variant '{}' makes a value, not memory, so no region is named after it",
                    tag
                ),
            );
        }
        if args.len() != variant.payload.len() {
            return err(
                span,
                format!(
                    "variant '{}' expects {}, got {}",
                    tag,
                    count(variant.payload.len(), "argument"),
                    args.len()
                ),
            );
        }
        if def.types.is_empty() {
            if let Some((_, at)) = written.first() {
                return err(
                    *at,
                    format!(
                        "kind '{}' takes no types, so '< … >' has nothing to name; write '{}.{}'",
                        unqualified(kind),
                        unqualified(kind),
                        tag
                    ),
                );
            }
            let mut values: Vec<&mut Expr> = args.iter_mut().collect();
            let region = self.check_fields_of_value(&mut values, &variant.payload, None)?;
            return Ok(Type::Named(
                kind.to_string(),
                self.region_of_value(kind, region),
            ));
        }
        let (given, hints) = self.variant_types(kind, &def, &variant, written, args)?;
        if def
            .types
            .iter()
            .all(|param| given.contains_key(&param.name))
        {
            let types: Vec<Type> = def
                .types
                .iter()
                .filter_map(|param| given.get(&param.name).cloned())
                .collect();
            return self.made_variant(kind, tag, &types, args, false, span);
        }
        let untold = def
            .types
            .iter()
            .find(|param| !given.contains_key(&param.name))
            .map(|param| param.name.clone())
            .unwrap_or_default();
        let example: Vec<String> = def
            .types
            .iter()
            .map(|param| {
                given
                    .get(&param.name)
                    .or_else(|| hints.get(&param.name))
                    .map_or(Type::Int, |ty| settled_example(&ty.without_regions()))
                    .to_string()
            })
            .collect();
        self.untold_kinds.push((
            span,
            kind.to_string(),
            tag.to_string(),
            untold,
            example.join(", "),
        ));
        let types = def
            .types
            .iter()
            .map(|param| {
                given
                    .get(&param.name)
                    .cloned()
                    .unwrap_or_else(|| Type::Param(format!("{}{}", UNTOLD, param.name)))
            })
            .collect();
        Ok(Type::Applied(Box::new(Applied {
            name: kind.to_string(),
            types,
            region: None,
        })))
    }

    fn variant_types(
        &mut self,
        kind: &str,
        def: &KindDef,
        variant: &Variant,
        written: &mut [TypeArg],
        args: &mut [Expr],
    ) -> Result<(HashMap<String, Type>, HashMap<String, Type>)> {
        let mut given: HashMap<String, Type> = HashMap::new();
        if let Some((_, at)) = written.first() {
            if written.len() != def.types.len() {
                let names: Vec<&str> = def.types.iter().map(|param| param.name.as_str()).collect();
                return err(
                    *at,
                    format!(
                        "kind '{}' takes {}, so name {}, as in '{}<{}>.{}'",
                        unqualified(kind),
                        count(def.types.len(), "type"),
                        if def.types.len() == 1 {
                            "it"
                        } else {
                            "all of them"
                        },
                        unqualified(kind),
                        names.join(", "),
                        variant.tag
                    ),
                );
            }
            for ((ty, at), param) in written.iter_mut().zip(&def.types) {
                *ty = self.resolve_type(ty, *at, TypePlace::Field)?;
                self.check_need("kind", kind, param, ty, *at)?;
                given.insert(param.name.clone(), ty.clone());
            }
            return Ok((given, HashMap::new()));
        }
        let copies = self.unsettled_copies.len();
        let untold = self.unsettled_types.len();
        let kinds = self.untold_kinds.len();
        let mut found = Ok(());
        let mut unsettled_values = Vec::new();
        for (arg, field) in args.iter_mut().zip(&variant.payload) {
            match self.check_expr(arg) {
                Ok(ty) if unsettled(&ty) && matches!(field.ty, Type::Param(_)) => {
                    unsettled_values.push((field.ty.to_string(), ty))
                }
                Ok(ty) => self.match_params(&field.ty, &ty, &mut given),
                Err(error) => {
                    found = Err(error);
                    break;
                }
            }
        }
        self.unsettled_copies.truncate(copies);
        self.unsettled_types.truncate(untold);
        self.untold_kinds.truncate(kinds);
        found?;
        let mut hints: HashMap<String, Type> = unsettled_values.into_iter().collect();
        given.retain(|param, ty| {
            let told = !ty.params().iter().any(|name| name.starts_with(UNTOLD));
            if !told {
                hints.insert(param.clone(), ty.clone());
            }
            told
        });
        for param in &def.types {
            if let Some(ty) = given.get(&param.name) {
                self.check_need(
                    "kind",
                    kind,
                    param,
                    ty,
                    args.first().map_or(variant.span, |arg| arg.span),
                )?;
            }
        }
        Ok((given, hints))
    }

    fn made_variant(
        &mut self,
        kind: &str,
        tag: &str,
        types: &[Type],
        args: &mut [Expr],
        checked: bool,
        span: Span,
    ) -> Result<Type> {
        let def = self
            .kinds
            .get(kind)
            .cloned()
            .ok_or_else(|| Error::internal_at(span, format!("unknown kind '{}'", kind)))?;
        let payload = |def: &KindDef| {
            def.variants
                .iter()
                .find(|v| v.tag == *tag)
                .map(|variant| variant.payload.clone())
                .unwrap_or_default()
        };
        if types.iter().any(|ty| !ty.params().is_empty()) {
            let names: HashMap<&str, &Type> = def
                .types
                .iter()
                .map(|param| param.name.as_str())
                .zip(types)
                .collect();
            let payload: Vec<Field> = payload(&def)
                .into_iter()
                .map(|field| Field {
                    ty: field
                        .ty
                        .map_params(&mut |param| names.get(param).map(|ty| (*ty).clone())),
                    ..field
                })
                .collect();
            let mut values: Vec<&mut Expr> = args.iter_mut().collect();
            let region = if checked {
                self.fields_region(&mut values, &payload)?
            } else {
                self.check_fields_of_value(&mut values, &payload, None)?
            };
            let may_hold = self.takes_region.contains(kind)
                || def
                    .variants
                    .iter()
                    .flat_map(|variant| &variant.payload)
                    .any(|field| !field.ty.params().is_empty());
            return Ok(Type::Applied(Box::new(Applied {
                name: kind.to_string(),
                types: types.to_vec(),
                region: may_hold.then_some(region),
            })));
        }
        let key = self.kind_instance(kind, types, span)?;
        let made = self
            .kinds
            .get(&key)
            .cloned()
            .ok_or_else(|| Error::internal_at(span, format!("no kind made for '{}'", kind)))?;
        let mut values: Vec<&mut Expr> = args.iter_mut().collect();
        let region = if checked {
            self.fields_region(&mut values, &payload(&made))?
        } else {
            self.check_fields_of_value(&mut values, &payload(&made), None)?
        };
        Ok(Type::Named(key.clone(), self.region_of_value(&key, region)))
    }

    /// Propagates expected types down into untold generic variants (`Option.None`, `Either.Left`) before statement end.
    fn settle_variant(&mut self, expr: &mut Expr, expected: &Type) -> Result<()> {
        if let (ExprKind::Fail(inner), Type::Or(_, error) | Type::Fail(error)) =
            (&mut expr.kind, expected)
            && inner.ty.as_ref().is_some_and(untold_kind)
        {
            self.settle_variant(inner, error)?;
            expr.ty = inner.ty.clone().map(|ty| Type::Fail(Box::new(ty)));
            return Ok(());
        }
        let none = match &expr.kind {
            ExprKind::Wrap(inner) => matches!(inner.kind, ExprKind::NoneLit),
            kind => matches!(kind, ExprKind::NoneLit),
        };
        if none
            && expr.ty.as_ref().is_some_and(holds_untold)
            && matches!(expected, Type::Maybe(_))
            && !holds_untold(expected)
        {
            expr.ty = Some(expected.clone());
            return Ok(());
        }
        if let ExprKind::Wrap(inner) = &mut expr.kind
            && let Some(Type::Or(value, error)) = &expr.ty
            && untold_kind(error)
            && let Type::Or(_, told) = expected
            && !holds_untold(told)
        {
            let own = Type::Or(value.clone(), told.clone());
            self.settle_variant(inner, &own)?;
            expr.ty = Some(own);
            return Ok(());
        }
        if let ExprKind::Wrap(inner) = &mut expr.kind
            && inner.ty.as_ref().is_some_and(untold_kind)
        {
            self.settle_variant(inner, expected)?;
            if let Some(told) = inner.ty.clone() {
                expr.ty = match expr.ty.take() {
                    Some(Type::Maybe(_)) => Some(Type::Maybe(Box::new(told))),
                    Some(Type::Or(_, error)) => Some(Type::Or(Box::new(told), error)),
                    other => other,
                };
            }
            return Ok(());
        }
        if let ExprKind::LoopValue(value) = &mut expr.kind
            && value.gives
            && let Some(Type::Or(given, result)) = expr.ty.clone()
            && let Type::Or(place, place_error) = expected
        {
            let told_given = holds_untold(&given) && !holds_untold(place);
            let told_result = match (self.unmade(&result), self.unmade(place_error)) {
                (Type::Applied(mine), Type::Applied(placed))
                    if value.open != (false, false)
                        && mine.name == library::LOOP_RESULT
                        && placed.name == mine.name =>
                {
                    let pick = |i: usize, open: bool| {
                        if open {
                            placed.types.get(i)
                        } else {
                            mine.types.get(i)
                        }
                        .cloned()
                        .unwrap_or(Type::Bool)
                    };
                    let types = vec![pick(0, value.open.0), pick(1, value.open.1)];
                    let region = mine
                        .region
                        .clone()
                        .filter(|region| region != ANY_REGION)
                        .or_else(|| placed.region.clone());
                    (types != mine.types).then(|| {
                        Type::Applied(Box::new(Applied {
                            name: mine.name.clone(),
                            types,
                            region,
                        }))
                    })
                }
                _ => None,
            };
            if told_given || told_result.is_some() {
                let result = match told_result {
                    Some(told) => self.made_kinds(told, expr.span)?,
                    None => *result,
                };
                let own = Type::Or(
                    if told_given {
                        place.clone()
                    } else {
                        given.clone()
                    },
                    Box::new(result.clone()),
                );
                if let Some(finally) = value.finally_mut() {
                    last_values_mut(finally, &mut |e| {
                        if let (ExprKind::Wrap(_), Some(Type::Or(value, _))) = (&e.kind, &e.ty) {
                            e.ty = Some(Type::Or(value.clone(), Box::new(result.clone())));
                        }
                    });
                    self.settle_value(finally, &own)?;
                } else {
                    let pass = map_pass(&own, !value.open.1);
                    if let Some(body) = value.body_mut() {
                        self.settle_value(body, &pass)?;
                    }
                }
                expr.ty = Some(own);
            }
            return Ok(());
        }
        if let (ExprKind::Tuple(items), Type::Tuple(places)) = (&mut expr.kind, expected)
            && expr.ty.as_ref().is_some_and(holds_untold)
            && items.len() == places.len()
        {
            for (item, place) in items.iter_mut().zip(places) {
                self.settle_variant(item, place)?;
            }
            if let Some(told) = items
                .iter()
                .map(|item| item.ty.clone())
                .collect::<Option<Vec<Type>>>()
            {
                expr.ty = Some(Type::Tuple(told));
            }
            return Ok(());
        }
        let choice = matches!(&expr.kind, ExprKind::Choice(_));
        let (sent, place, own) = match expr.ty.clone() {
            Some(Type::Applied(sent))
                if sent
                    .types
                    .iter()
                    .any(|ty| is_untold(ty) || untold_inside(ty)) =>
            {
                (sent, expected.clone(), expected.clone())
            }
            Some(Type::Maybe(inner)) if choice && untold_kind(&inner) => match *inner {
                Type::Applied(sent) => (sent, expected.clone(), expected.clone()),
                _ => return Ok(()),
            },
            Some(Type::Or(value, error)) if choice && untold_kind(&error) => {
                match (*error, expected) {
                    (Type::Applied(sent), Type::Or(_, place)) => {
                        (sent, (**place).clone(), Type::Or(value, place.clone()))
                    }
                    _ => return Ok(()),
                }
            }
            Some(Type::Maybe(inner))
                if choice && matches!(&*inner, Type::Or(_, error) if untold_kind(error)) =>
            {
                match (*inner, expected) {
                    (Type::Or(_, error), Type::Or(_, place)) => match *error {
                        Type::Applied(sent) => (sent, (**place).clone(), expected.clone()),
                        _ => return Ok(()),
                    },
                    _ => return Ok(()),
                }
            }
            _ => return Ok(()),
        };
        let span = expr.span;
        let Some(types) = self.told_types(&sent, &place) else {
            return Ok(());
        };
        if let ExprKind::Choice(stmt) = &mut expr.kind {
            self.settle_branch_values(stmt, &own)?;
            expr.ty = Some(own);
            return Ok(());
        }
        if !untold_inside(expr.ty.as_ref().unwrap_or(&Type::Unknown)) {
            return Ok(());
        }
        {
            let def = self
                .kinds
                .get(&sent.name)
                .cloned()
                .ok_or_else(|| Error::internal_at(span, "a variant of no kind"))?;
            for (param, ty) in def.types.iter().zip(&types) {
                self.check_need("kind", &sent.name, param, ty, span)?;
            }
            let ExprKind::Construct { tag, args, .. } = &mut expr.kind else {
                return Ok(());
            };
            let tag = tag.clone();
            if let Some(variant) = def.variants.iter().find(|variant| variant.tag == tag) {
                let names: HashMap<&str, &Type> = def
                    .types
                    .iter()
                    .map(|param| param.name.as_str())
                    .zip(&types)
                    .collect();
                for (arg, field) in args.iter_mut().zip(&variant.payload) {
                    if arg.ty.as_ref().is_some_and(untold_inside) {
                        let place = field
                            .ty
                            .map_params(&mut |param| names.get(param).map(|ty| (*ty).clone()));
                        self.settle_variant(arg, &place)?;
                    }
                }
            }
            let ty = self.made_variant(&sent.name, &tag, &types, args, true, span)?;
            expr.ty = Some(ty);
            if let Some(at) = self.untold_kinds.iter().rposition(|(at, ..)| *at == span) {
                self.untold_kinds.remove(at);
            }
        }
        Ok(())
    }

    fn told_types(&self, sent: &Applied, expected: &Type) -> Option<Vec<Type>> {
        let mut places = vec![expected.clone()];
        match expected {
            Type::Maybe(inner) => places.push((**inner).clone()),
            Type::Or(value, _) => {
                places.push((**value).clone());
                if let Type::Maybe(inner) = value.as_ref() {
                    places.push((**inner).clone());
                }
            }
            _ => {}
        }
        places.into_iter().find_map(|place| {
            let Type::Applied(named) = self.unmade(&place) else {
                return None;
            };
            if named.name != sent.name || named.types.len() != sent.types.len() {
                return None;
            }
            let told = sent.types.iter().zip(&named.types).all(|(sent, named)| {
                is_untold(sent)
                    || (untold_inside(sent)
                        && self.join_told(sent, &named.without_regions()).is_some())
                    || fits(&sent.without_regions(), &named.without_regions())
                    || fits(&named.without_regions(), &sent.without_regions())
            });
            let types: Vec<Type> = sent
                .types
                .iter()
                .zip(&named.types)
                .map(|(sent, named)| {
                    if is_untold(sent) || untold_inside(sent) {
                        named.without_regions()
                    } else {
                        sent.clone()
                    }
                })
                .collect();
            (told && !types.iter().any(|ty| is_untold(ty) || holds_untold(ty))).then_some(types)
        })
    }

    fn join(&self, a: &Type, b: &Type) -> Option<Type> {
        if untold_inside(a) || untold_inside(b) {
            match (a, b) {
                (Type::Maybe(x), Type::Maybe(y)) => {
                    return self.join(x, y).map(|joined| Type::Maybe(Box::new(joined)));
                }
                (Type::Maybe(x), Type::None) | (Type::None, Type::Maybe(x)) => {
                    return Some(Type::Maybe(x.clone()));
                }
                (Type::Maybe(x), other) | (other, Type::Maybe(x))
                    if !matches!(other, Type::Or(..) | Type::Fail(_)) =>
                {
                    return self
                        .join(x, other)
                        .map(|joined| Type::Maybe(Box::new(joined)));
                }
                _ => {}
            }
            if let (Type::Applied(left), Type::Applied(right)) = (self.unmade(a), self.unmade(b))
                && left.name == right.name
                && left.types.len() == right.types.len()
            {
                let types = left
                    .types
                    .iter()
                    .zip(&right.types)
                    .map(|(x, y)| self.join_told(x, y))
                    .collect::<Option<Vec<Type>>>()?;
                for (side, applied) in [(b, &right), (a, &left)] {
                    if !untold_inside(side)
                        && types
                            .iter()
                            .zip(&applied.types)
                            .all(|(joined, own)| joined.without_regions() == own.without_regions())
                    {
                        return Some(side.clone());
                    }
                }
                let region = left
                    .region
                    .clone()
                    .or_else(|| right.region.clone())
                    .or_else(|| {
                        types
                            .iter()
                            .flat_map(Type::regions)
                            .find(|region| !unnamed_region(region))
                            .map(str::to_string)
                    });
                return Some(Type::Applied(Box::new(Applied {
                    name: left.name.clone(),
                    types,
                    region,
                })));
            }
        }
        let failing_untold =
            |ty: &Type| matches!(ty, Type::Fail(error) | Type::Or(_, error) if untold_kind(error));
        if failing_untold(a) || failing_untold(b) {
            match (a, b) {
                (Type::Fail(x), Type::Fail(y)) => {
                    return self.join(x, y).map(|error| Type::Fail(Box::new(error)));
                }
                (Type::Or(value, x), Type::Fail(y)) | (Type::Fail(y), Type::Or(value, x)) => {
                    return self
                        .join(x, y)
                        .map(|error| Type::Or(value.clone(), Box::new(error)));
                }
                (Type::Or(v, x), Type::Or(w, y)) => {
                    return Some(Type::Or(
                        Box::new(self.join(v, w)?),
                        Box::new(self.join(x, y)?),
                    ));
                }
                _ => {}
            }
        }
        if let Some(joined) = join_types(a, b) {
            return Some(joined);
        }
        let value = |ty: &Type| match ty {
            Type::Maybe(inner) | Type::Or(inner, _) => inner.as_ref().clone(),
            other => other.clone(),
        };
        let into = |ty: &Type, into: &Type| match ty {
            Type::Maybe(_) => Type::Maybe(Box::new(into.clone())),
            Type::Or(_, error) => Type::Or(Box::new(into.clone()), error.clone()),
            _ => into.clone(),
        };
        let (left, right) = (value(a), value(b));
        if self.widens(&left, &right) {
            return join_types(&into(a, &in_region_of(&right, &left)), b);
        }
        if self.widens(&right, &left) {
            return join_types(a, &into(b, &in_region_of(&left, &right)));
        }
        None
    }

    fn join_told(&self, x: &Type, y: &Type) -> Option<Type> {
        match (is_untold(x), is_untold(y)) {
            (true, _) => Some(y.clone()),
            (false, true) => Some(x.clone()),
            _ if untold_inside(x) || untold_inside(y) => self.join(x, y),
            _ if fits(&x.without_regions(), &y.without_regions()) => Some(y.clone()),
            _ if fits(&y.without_regions(), &x.without_regions()) => Some(x.clone()),
            _ => None,
        }
    }

    fn untold_kind_error(&self, at: Span) -> Option<Error> {
        let (at, kind, tag, param, example) = self
            .untold_kinds
            .iter()
            .rev()
            .find(|(span, ..)| *span == at)?;
        Some(Error::at(
            *at,
            untold_kind_message(kind, tag, param, example),
        ))
    }

    fn made_kinds(&mut self, ty: Type, at: Span) -> Result<Type> {
        Ok(match ty {
            Type::Applied(applied)
                if applied.types.iter().all(|ty| ty.params().is_empty())
                    && self
                        .kinds
                        .get(&applied.name)
                        .is_some_and(|def| !def.types.is_empty()) =>
            {
                let key = self.kind_instance(&applied.name, &applied.types, at)?;
                let region = applied
                    .region
                    .and_then(|region| self.region_of_value(&key, region));
                Type::Named(key, region)
            }
            Type::Maybe(inner) => Type::Maybe(Box::new(self.made_kinds(*inner, at)?)),
            Type::Or(value, error) => Type::Or(
                Box::new(self.made_kinds(*value, at)?),
                Box::new(self.made_kinds(*error, at)?),
            ),
            Type::Array(items, count) => Type::Array(Box::new(self.made_kinds(*items, at)?), count),
            Type::Tuple(items) => Type::Tuple(
                items
                    .into_iter()
                    .map(|item| self.made_kinds(item, at))
                    .collect::<Result<_>>()?,
            ),
            other => other,
        })
    }

    fn check_new(
        &mut self,
        ty: &mut Box<Type>,
        ty_span: Span,
        value: &mut Expr,
        region: &mut Option<String>,
        region_span: Span,
    ) -> Result<Type> {
        **ty = self.resolve_type(ty, ty_span, TypePlace::New)?;
        if matches!(**ty, Type::Or(..)) {
            return err(
                ty_span,
                format!(
                    "'new' can't make a pointer to '{}'; extract the value first, or keep it in a shape's field",
                    ty
                ),
            );
        }
        if value.span == ty_span
            && matches!(&value.kind, ExprKind::StructInit { fields, .. } if fields.is_empty())
        {
            self.check_empty_shape(ty, ty_span)?;
        }
        let written = ty.to_string();
        let allocates = self.region_or_default(region.as_ref(), region_span, || {
            format!(
                "'new' needs a region to allocate in, as in 'new {0}(…) at r' or 'new@r {0}(…)'",
                written
            )
        })?;
        *region = Some(allocates.clone());
        self.visible_region(&allocates, region_span, true)?;
        // `new` values in `r` must not retain outer regions, except pattern-default `text@this` validated at calls.
        if let Some(other) = ty
            .regions()
            .into_iter()
            .find(|kept| *kept != allocates && !(*kept == THIS_WORD && self.in_pattern_default))
        {
            return err(
                self.place(ty_span, &format!("@{}", other)),
                format!(
                    "everything a value in region '{0}' holds is in '{0}', what a lambda keeps too; write '@{0}' for '@{1}'",
                    allocates, other
                ),
            );
        }
        if let Type::Map(key, value_ty, _) = &**ty {
            let key = self.in_region(key, &allocates);
            let value_ty = self.in_region(value_ty, &allocates);
            let map = Type::Map(
                Box::new(key.clone()),
                Box::new(value_ty.clone()),
                Some(allocates),
            );
            self.check_map_source(value, &key, &value_ty, &map)?;
            return Ok(map);
        }
        if let Type::Slice(items, _) = &**ty {
            let items = self.in_region(items, &allocates);
            let slice = Type::Slice(Box::new(items.clone()), Some(allocates));
            self.check_slice_source(value, &items, &slice)?;
            return Ok(slice);
        }
        let pointee = self.in_region(ty, &allocates);
        self.check_expr(value)?;
        self.coerce(value, &pointee)?;
        Ok(Type::Ptr(Box::new(pointee), Some(allocates)))
    }

    fn check_empty_shape(&mut self, ty: &Type, span: Span) -> Result<()> {
        let name = match ty {
            Type::Named(name, _) => name.as_str(),
            Type::Applied(applied) => applied.name.as_str(),
            _ => "",
        };
        let Some(shape) = self
            .shapes
            .get(name)
            .filter(|_| !self.kinds.contains_key(name))
        else {
            return err(
                span,
                format!(
                    "'new' needs the value to put in the region, as in 'new {}(…) at r'; only a slice, a map, or a shape whose fields all fall back on values can be made empty, as in 'new [int] at r' or 'new [text: int] at r'",
                    ty
                ),
            );
        };
        let outside = module_of(name) != self.current_module;
        if let Some(field) = shape
            .fields
            .iter()
            .find(|field| field.default.is_none())
            .filter(|field| !(field.private && outside))
        {
            return err(
                span,
                format!(
                    "a 'new' with no value makes a '{0}' of the values its fields fall back on, and field '{1}' falls back on none; give the value, as in 'new {0}({0} {{ {1}: … }})'",
                    unqualified(name),
                    field.name
                ),
            );
        }
        Ok(())
    }

    fn check_deref(&mut self, e: &mut Expr, span: Span) -> Result<Type> {
        let ty = self.check_expr(e)?;
        if ty.unknown() {
            return Ok(Type::Unknown);
        }
        if let Type::Maybe(inner) = &ty
            && inner.ptr_inner().is_some()
        {
            return err(
                span,
                format!(
                    "this pointer is a {}, which may be none; extract it first, as in 'when p is {{q}}' or 'p {{ … }}'",
                    ty
                ),
            );
        }
        if let Type::Or(value, _) = &ty
            && value.ptr_inner().is_some()
        {
            return err(
                span,
                format!(
                    "this pointer is a {}, which may be an error; extract it first, as in 'p {{ … }}' or 'match'",
                    ty
                ),
            );
        }
        let hint = if matches!(ty, Type::Slice(..)) {
            "; read an item of a slice with 'xs[i]'"
        } else {
            ""
        };
        ty.ptr_inner().cloned().ok_or_else(|| {
            Error::at(
                span,
                format!(
                    "'^' reads the value a pointer points to, but this value is {}{}",
                    ty, hint
                ),
            )
        })
    }

    fn check_pipe(&mut self, expr: &mut Expr) -> Result<Type> {
        let span = expr.span;
        let target = self.pipe_target.take();
        let ExprKind::Pipe(call) = &mut expr.kind else {
            return Err(Error::internal_at(span, "a pipe that is no pipe"));
        };
        let callee = piped_callee(call);
        let position = piped_position(call);
        let Some(piped) = piped_arg(call) else {
            return Err(Error::internal_at(
                span,
                "a pipe giving its value to no call",
            ));
        };
        let ExprKind::Piped(value) = &mut piped.kind else {
            return Err(Error::internal_at(
                span,
                "a pipe giving its value to no call",
            ));
        };
        if matches!(value.kind, ExprKind::Pipe(_)) {
            self.pipe_target = target.clone();
        }
        let checked = self.check_expr_multi(value);
        self.pipe_target = None;
        let (given, failure) = match checked? {
            Type::Or(given, error) => (*given, Some(*error)),
            Type::Results(types) => {
                let what = match &value.kind {
                    ExprKind::Call { name, .. } => format!("'{}'", called_name(name)),
                    _ => "this call".to_string(),
                };
                return err(
                    value.span,
                    format!(
                        "{} sends {} values, and a pipe gives the call after it one; receive them first, with 'fixed {} = …'",
                        what,
                        types.len(),
                        example_names(types.len())
                    ),
                );
            }
            other => (other, None),
        };
        if given == Type::Nothing {
            return err(
                value.span,
                format!(
                    "this gives nothing when it succeeds, so the pipe has no value to give {}",
                    callee
                ),
            );
        }
        if matches!(given, Type::Fail(_)) {
            return err(
                value.span,
                "a pipe gives a value to the call after it, and this is a failure only; send it with '<- fail …'",
            );
        }
        piped.ty = Some(given.clone());
        let call_span = call.span;
        let sent = self.check_expr(call).map_err(|error| {
            let typed = error.span == Some(span) && error.message.starts_with("expected type ");
            let counted = error.span == Some(call_span) && error.message.contains(" expects ") && error.message.contains(", got ");
            if typed && matches!(given, Type::Maybe(_)) {
                let takes = error.message.trim_start_matches("expected type ").split(',').next().unwrap_or("another type").to_string();
                return Error::at(
                    span,
                    format!(
                        "the pipe gives {} a value of type {} as argument {}, where it takes {}; a pipe carries failures but not absence, so read the maybe in its step with a plan B, as in '… |> f() {{ 0 }} |> g()'",
                        callee, given, position, takes
                    ),
                );
            }
            if typed {
                return Error { message: format!("{}; the pipe gives this value to {} as argument {}", error.message, callee, position), ..error };
            }
            if counted {
                return Error { message: format!("{}, the value the pipe gives as argument {} among them", error.message, position), ..error };
            }
            error
        })?;
        let Some(failure) = failure else {
            return Ok(sent);
        };
        Ok(match sent {
            Type::Or(value, error) => Type::Or(
                value,
                Box::new(self.pipe_failure(span, &failure, &error, target.as_ref())?),
            ),
            Type::Unknown => Type::Unknown,
            other => Type::Or(
                Box::new(other),
                Box::new(self.pipe_failure(span, &failure, &failure, target.as_ref())?),
            ),
        })
    }

    fn pipe_failure(
        &self,
        span: Span,
        before: &Type,
        after: &Type,
        target: Option<&Type>,
    ) -> Result<Type> {
        let fits = |error: &Type, into: &Type| {
            error.unknown() || fits_regions(error, into) || self.widens(error, into)
        };
        if let Some(target) = target.filter(|target| fits(before, target) && fits(after, target)) {
            return Ok(target.clone());
        }
        if fits(before, after) {
            return Ok(after.clone());
        }
        if fits(after, before) {
            return Ok(before.clone());
        }
        let both = [before, after].map(|error| self.written_type(error));
        if let Some(target) = target {
            let target = self.written_type(target);
            return err(
                span,
                format!(
                    "the steps of this pipe fail with '{0}' and with '{1}', and '{2}', the kind its value goes into, doesn't imitate both; declare it as one that does, as in 'kind {2}::{0} & {1}'",
                    both[0], both[1], target
                ),
            );
        }
        err(
            span,
            format!(
                "the steps of this pipe fail with '{0}' and with '{1}', and a pipe fails with one; declare a kind that imitates both, as in 'kind StepError::{0} & {1}', and name it where the pipe's value goes, as in 'fixed v: int ~ StepError = …'",
                both[0], both[1]
            ),
        )
    }

    fn check_own(&mut self, inner: &mut Expr, span: Span) -> Result<Type> {
        let name = match &inner.kind {
            ExprKind::Var(name) => name.clone(),
            _ => {
                return err(
                    span,
                    "cannot move non-variable expression with 'own'; 'own' transfers ownership of a named variable",
                );
            }
        };
        if self.globals.contains_key(&name) {
            return err(
                span,
                format!("cannot transfer ownership of global variable '{}' with 'own'", name),
            );
        }
        if self.is_moved(&name) {
            return err(
                span,
                format!("use of moved value '{0}'; '{0}' was moved with 'own {0}'", name),
            );
        }
        if !self.loops.is_empty() && self.declared_outside_loop(&name) {
            return err(
                span,
                format!("cannot move '{0}' inside a loop; '{0}' was declared outside the loop", name),
            );
        }
        let info = self.lookup_or_err(&name, inner.span)?;
        if info.passing.is_ref() {
            return err(
                span,
                format!("cannot move through reference '{}'", name),
            );
        }
        let ty = info.ty.clone();
        inner.ty = Some(ty.clone());
        self.moved.insert(name);
        Ok(Type::Own(Box::new(ty)))
    }

    fn check_fail(&mut self, error: &mut Expr) -> Result<Type> {
        let ty = self.check_expr(error)?;
        if matches!(
            ty,
            Type::Nothing | Type::None | Type::Fail(_) | Type::Maybe(_) | Type::Or(..)
        ) {
            return err(
                error.span,
                format!("'fail' needs an error value, got {}", ty),
            );
        }
        Ok(Type::Fail(Box::new(ty)))
    }

    fn resolve_map_field(&mut self, expr: &mut Expr) -> Result<Option<Type>> {
        let span = expr.span;
        // Check map `.keys`/`.values` base once here to avoid quadratic re-checks on chained calls.
        if let ExprKind::Field(base, word) = &mut expr.kind
            && let Some(op @ (MapOp::Keys | MapOp::Values)) = MapOp::from_word(word)
            && (self.called_on_a_value()
                || !matches!(&base.kind, ExprKind::Var(name) if name == THIS))
        {
            let base_ty = self.check_expr(base)?;
            if !matches!(base_ty, Type::Map(..)) {
                return self.field_type(&base_ty, word, span).map(Some);
            }
            let taken = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
            if let ExprKind::Field(map, _) = taken {
                expr.kind = ExprKind::MapOp {
                    map,
                    op,
                    key: None,
                    region: None,
                    region_span: span,
                };
            }
        }
        Ok(None)
    }

    fn check_tuple(&mut self, values: &mut [Expr]) -> Result<Type> {
        let mut items = Vec::new();
        for value in values.iter_mut() {
            let ty = self.check_expr(value)?;
            if let Some(what) = self.changeable_item(&ty).filter(|_| !holds_untold(&ty)) {
                return err(
                    value.span,
                    format!("a tuple's items never change, so it can't hold {}", what),
                );
            }
            items.push(ty);
        }
        Ok(Type::Tuple(items))
    }

    /// Separated from `infer_expr` so deeply nested expressions do not multiply stack frames.
    fn check_array(&mut self, values: &mut [Expr], span: Span) -> Result<Type> {
        let mut joined: Option<Type> = None;
        for value in values.iter_mut() {
            let ty = self.check_expr(value)?;
            joined = Some(match joined {
                None => ty,
                Some(before) => self.join(&before, &ty).ok_or_else(|| {
                    Error::at(value.span, format!("an array's values have one type, but this one is {} and the ones before it are {}", ty, before))
                })?,
            });
        }
        let items = self.made_kinds(joined.unwrap_or(Type::Nothing), span)?;
        if items == Type::Nothing {
            return err(span, "an array can't hold 'nothing', which has no value");
        }
        if !unsettled(&items) {
            for value in values.iter_mut() {
                self.coerce(value, &items)?;
            }
        }
        let ty = Type::Array(
            Box::new(items),
            u64::try_from(values.len()).unwrap_or(u64::MAX),
        );
        self.check_size(&ty, span)?;
        Ok(ty)
    }

    fn check_repeat(&mut self, value: &mut Expr, count: &mut Expr, span: Span) -> Result<Type> {
        let items = self.check_expr(value)?;
        if items == Type::Nothing {
            return err(
                value.span,
                "an array can't hold 'nothing', which has no value",
            );
        }
        let count_ty = self.check_expr(count)?;
        self.expect_type(&count_ty, &Type::Int, count.span)?;
        let Some(n) = constant_int(count) else {
            let written = if unsettled(&items) {
                "T".to_string()
            } else {
                items.without_regions().to_string()
            };
            return err(
                count.span,
                format!(
                    "an array's count is known before the program runs, as in '[0#8]'; for a count known only as it runs, make a slice in a region, as in 'new [{}]([…#n]) at r'",
                    written
                ),
            );
        };
        let Some(n) = u64::try_from(n).ok().filter(|n| *n > 0) else {
            return err(
                count.span,
                "an array holds at least one value, so its count is 1 or more",
            );
        };
        let ty = Type::Array(Box::new(items), n);
        self.check_size(&ty, span)?;
        Ok(ty)
    }

    fn check_text_part(
        &mut self,
        region: &Option<String>,
        index: &mut Expr,
        span: Span,
    ) -> Result<Type> {
        let ExprKind::Range(from, to) = &mut index.kind else {
            let ty = self.check_expr(index)?;
            self.expect_type(&ty, &Type::Int, index.span)?;
            if let Some(value) = constant_int(index).filter(|value| *value < 0) {
                return err(
                    index.span,
                    format!("index {} is out of range: it is less than 0", value),
                );
            }
            let _ = span;
            return Ok(Type::Char);
        };
        for bound in [&mut **from, &mut **to] {
            let ty = self.check_expr(bound)?;
            self.expect_type(&ty, &Type::Int, bound.span)?;
        }
        let (start, end) = (constant_int(from), constant_int(to));
        for (value, at) in [(start, from.span), (end, to.span)] {
            if let Some(value) = value.filter(|value| *value < 0) {
                return err(
                    at,
                    format!("text bound {} is out of range: it is less than 0", value),
                );
            }
        }
        if let (Some(start), Some(end)) = (start, end)
            && end < start
        {
            return err(
                index.span,
                format!("text {}..{} ends before it starts", start, end),
            );
        }
        index.ty = Some(Type::Range(Box::new(Type::Int)));
        Ok(Type::Text(region.clone()))
    }

    fn expand_shortcut(&mut self, expr: &mut Expr) -> Result<()> {
        let span = expr.span;
        if matches!(&expr.kind, ExprKind::Shortcut { value, .. } if matches!(value.kind, ExprKind::Pairs(_)))
        {
            return self.expand_map_shortcut(expr);
        }
        let ExprKind::Shortcut { value, .. } = &mut expr.kind else {
            return Ok(());
        };
        let copies = self.unsettled_copies.len();
        let found = self.check_expr(value);
        self.unsettled_copies.truncate(copies);
        let items = match found? {
            Type::Array(items, _) => *items,
            _ => Type::Unknown,
        };
        if matches!(items, Type::None | Type::Fail(_)) {
            return err(
                span,
                "can't tell the type of a slice's items from none or 'fail …'; name it, as in 'new [maybe int]([none]) at r'",
            );
        }
        let taken = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
        let ExprKind::Shortcut {
            value,
            region,
            region_span,
        } = taken
        else {
            return Err(Error::internal_at(span, "a shortcut that is no longer one"));
        };
        let region = self.region_or_default(region.as_ref(), region_span, || {
            "a slice written by its values goes in a region, as in '[1, 2, ...] at r' or '[1, 2, ...]@r'".to_string()
        })?;
        let region = Some(region);
        let ty = Type::Slice(Box::new(items.without_regions()), None);
        expr.kind = ExprKind::New {
            ty: Box::new(ty),
            ty_span: span,
            value,
            region,
            region_span,
        };
        Ok(())
    }

    fn check_each_source(
        &mut self,
        name: &str,
        second: Option<&(String, Span)>,
        range: &mut Expr,
    ) -> Result<(Type, Option<Type>)> {
        if let Some(group) = self.group_of(range) {
            range.ty = Some(Type::Group(group.clone()));
            if let Some((second, at)) = second {
                return err(
                    *at,
                    format!(
                        "'each {}, {}' names a key and its value, which only a map gives; a group gives one value at a time, so name one",
                        name, second
                    ),
                );
            }
            return Ok((Type::Param(group), None));
        }
        let one = |ty: Type| -> Result<(Type, Option<Type>)> {
            match second {
                Some((second, at)) => err(
                    *at,
                    format!(
                        "'each {}, {}' names a key and its value, which only a map gives; this gives one item at a time, so name one",
                        name, second
                    ),
                ),
                None => Ok((ty, None)),
            }
        };
        let map_pair = |key: Type, value: Type, span: Span| -> Result<(Type, Option<Type>)> {
            match second {
                Some(_) => Ok((key, Some(value))),
                None => err(
                    span,
                    format!(
                        "a map gives a key and its value each pass, so name both, as in 'each {}, value in …'; for its keys alone, go through '.keys', as in 'each {} in m.keys'",
                        name, name
                    ),
                ),
            }
        };
        // `Range` is only valid as an `each` source, so check it here rather than in `infer_expr`.
        if let ExprKind::Range(start, end) = &mut range.kind {
            for bound in [start, end] {
                let bty = self.check_expr(bound)?;
                self.expect_type(&bty, &Type::Int, bound.span)?;
            }
            range.ty = Some(Type::Range(Box::new(Type::Int)));
            return one(Type::Int);
        }
        if let ExprKind::Field(base, word) = &mut range.kind
            && let Some(op @ (MapOp::Keys | MapOp::Values)) = MapOp::from_word(word)
            && let Type::Map(key, value, region) = self.check_expr(base)?
        {
            let item = if op == MapOp::Keys { *key } else { *value };
            let taken = std::mem::replace(&mut range.kind, ExprKind::NoneLit);
            if let ExprKind::Field(map, _) = taken {
                range.kind = ExprKind::MapOp {
                    map,
                    op,
                    key: None,
                    region: None,
                    region_span: range.span,
                };
            }
            range.ty = Some(Type::Slice(Box::new(item.clone()), region));
            return one(item);
        }
        if let ExprKind::Ref(place) = &mut range.kind {
            let ty = self.check_expr(place)?;
            if !ty.unknown() && !self.is_place(place) {
                let what = no_place(place);
                return err(
                    place.span,
                    format!(
                        "'each v in &…' goes through a place as it is at each pass: a variable, a field or an item of one, or what a pointer points to, and this is {}; write 'each v in …' to go through a value",
                        what
                    ),
                );
            }
            range.ty = Some(ty.clone());
            return match ty {
                Type::Array(items, _) | Type::Slice(items, _) => one(*items),
                Type::Map(key, value, _) => map_pair(*key, *value, range.span),
                other if other.unknown() => Ok((Type::Unknown, second.map(|_| Type::Unknown))),
                other => err(
                    range.span,
                    format!(
                        "'each v in &…' goes through the items of an array, a slice, or a map as they are at each pass, but this value is {}",
                        other
                    ),
                ),
            };
        }
        match self.check_expr(range)? {
            Type::Array(items, _) | Type::Slice(items, _) if unsettled(&items) => err(
                range.span,
                format!(
                    "cannot tell the type of '{}' from none or 'fail …'; give the array a type first",
                    name
                ),
            ),
            Type::Array(items, _) | Type::Slice(items, _) => one(*items),
            Type::Map(key, value, _) => map_pair(*key, *value, range.span),
            other if other.unknown() => Ok((Type::Unknown, second.map(|_| Type::Unknown))),
            // Signal `check_stmt_kind` to desugar `each x in it` using `Iterator.next()`.
            other => {
                if let Some(types) = self.followed_by(&other, "std/collections.Iterator") {
                    if let Some((second, at)) = second {
                        return err(
                            *at,
                            format!(
                                "'each {}, {}' names a key and its value, which only a map gives; an iterator gives one item at a time, so name one",
                                name, second
                            ),
                        );
                    }
                    let item = types.first().cloned().unwrap_or(Type::Unknown);
                    self.each_iterator = Some(item.clone());
                    return Ok((item, None));
                }
                err(
                    range.span,
                    format!(
                        "each goes through a range, such as 0..n, the items of an array or slice, a map's keys and values, or an iterator from std/collections, but this value is {}{}",
                        other,
                        extract_hint(&[&other])
                    ),
                )
            }
        }
    }

    fn expand_map_shortcut(&mut self, expr: &mut Expr) -> Result<()> {
        let span = expr.span;
        let ExprKind::Shortcut { value, .. } = &mut expr.kind else {
            return Ok(());
        };
        let ExprKind::Pairs(pairs) = &value.kind else {
            return Ok(());
        };
        let side = |pick: fn(&(Expr, Expr)) -> &Expr| {
            Expr::new(
                ExprKind::Array(pairs.iter().map(|pair| pick(pair).clone()).collect()),
                span,
            )
        };
        let (mut keys, mut values) = (side(|pair| &pair.0), side(|pair| &pair.1));
        let copies = self.unsettled_copies.len();
        let found = self
            .check_expr(&mut keys)
            .and_then(|keys| Ok((keys, self.check_expr(&mut values)?)));
        self.unsettled_copies.truncate(copies);
        let (key_ty, value_ty) = match found? {
            (Type::Array(key, _), Type::Array(value, _)) => (*key, *value),
            _ => (Type::Unknown, Type::Unknown),
        };
        for (ty, what) in [(&key_ty, "keys"), (&value_ty, "values")] {
            if matches!(ty, Type::None | Type::Fail(_)) {
                return err(
                    span,
                    format!(
                        "can't tell the type of a map's {} from none or 'fail …'; name it, as in 'new [text: maybe int]([\"a\": none]) at r'",
                        what
                    ),
                );
            }
        }
        let taken = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
        let ExprKind::Shortcut {
            value,
            region,
            region_span,
        } = taken
        else {
            return Err(Error::internal_at(span, "a shortcut that is no longer one"));
        };
        let region = self.region_or_default(region.as_ref(), region_span, || {
            "a map written by its pairs goes in a region, as in '[\"a\": 1] at r' or '[\"a\": 1]@r'".to_string()
        })?;
        let ty = Type::Map(
            Box::new(key_ty.without_regions()),
            Box::new(value_ty.without_regions()),
            None,
        );
        expr.kind = ExprKind::New {
            ty: Box::new(ty),
            ty_span: span,
            value,
            region: Some(region),
            region_span,
        };
        Ok(())
    }

    fn check_map_source(
        &mut self,
        value: &mut Expr,
        key: &Type,
        value_ty: &Type,
        map: &Type,
    ) -> Result<()> {
        let ExprKind::Pairs(pairs) = &mut value.kind else {
            let ty = self.check_expr(value)?;
            return match &ty {
                Type::Map(k, v, _)
                    if k.without_regions() == key.without_regions()
                        && v.without_regions() == value_ty.without_regions() =>
                {
                    Ok(())
                }
                _ if ty.unknown() => Ok(()),
                Type::Map(..) => err(
                    value.span,
                    format!(
                        "a new {} copies the keys and values of a map of the same types, but this map is {}",
                        map.without_regions(),
                        ty.without_regions()
                    ),
                ),
                _ => err(
                    value.span,
                    format!(
                        "a new map is made from its pairs, as in 'new {}([k: v])', or from another map it copies, but this value is {}",
                        map.without_regions(),
                        ty
                    ),
                ),
            };
        };
        let mut written: HashMap<String, Span> = HashMap::new();
        for (k, v) in pairs.iter_mut() {
            self.check_expr(k)?;
            self.coerce(k, key)?;
            self.check_expr(v)?;
            self.coerce(v, value_ty)?;
            // Reject duplicate literal map keys since later entries silently overwrite earlier ones.
            if let Some(text) = constant_key(k) {
                if let Some(at) = written.get(&text) {
                    return err(
                        k.span,
                        format!(
                            "the key {} is written twice, first at {}:{}; a map holds one value for each key",
                            text, at.line, at.col
                        ),
                    );
                }
                written.insert(text, k.span);
            }
        }
        value.ty = Some(map.clone());
        Ok(())
    }

    fn check_map_op(
        &mut self,
        map: &mut Expr,
        op: MapOp,
        key: Option<&mut Expr>,
        region: &mut Option<String>,
        region_span: Span,
    ) -> Result<Type> {
        let ty = self.check_expr(map)?;
        let Type::Map(key_ty, value_ty, _) = &ty else {
            if ty.unknown() {
                return Ok(Type::Unknown);
            }
            return err(
                map.span,
                format!(
                    "'{}' asks a map, but this value is {}{}",
                    op.word(),
                    ty,
                    extract_hint(&[&ty])
                ),
            );
        };
        if op == MapOp::Has {
            let Some(key) = key else {
                return Err(Error::internal_at(map.span, "'has' without its key"));
            };
            self.check_key(key_ty, key)?;
            return Ok(Type::Bool);
        }
        let item = if op == MapOp::Keys {
            (**key_ty).clone()
        } else {
            (**value_ty).clone()
        };
        let word = op.word();
        let made = self.region_or_default(region.as_ref(), region_span, || {
            format!("'{0}' makes a slice, so it names the region it goes in, as in 'm.{0} at r' or 'm.{0}@r'; 'each k in m.{0}' goes through them without one", word)
        })?;
        self.visible_region(&made, region_span, true)?;
        *region = Some(made.clone());
        // Slices from `m.keys`/`m.values` share element/text lifetimes with the map's own region.
        if let Some(held) = item
            .regions()
            .into_iter()
            .find(|held| *held != made && *held != ANY_REGION)
        {
            let side = if op == MapOp::Keys { "keys" } else { "values" };
            return err(
                region_span,
                format!(
                    "the map's {0} hold what is in region '{1}', and 'm.{2}' holds them, not copies, so it goes there too, as in 'm.{2} at {1}'; to keep them in '{3}', copy that, as in '(m.{2} at {1}).copy() at {3}'",
                    side, held, word, made
                ),
            );
        }
        Ok(Type::Slice(Box::new(item), Some(made)))
    }

    /// Lookup compares keys without storing them, so any region fits.
    fn check_key(&mut self, wanted: &Type, key: &mut Expr) -> Result<()> {
        if matches!(key.kind, ExprKind::Range(..)) {
            return err(
                key.span,
                "a map has no parts: '[…]' takes one key, as in 'm[k]'",
            );
        }
        let ty = self.check_expr(key)?;
        if ty.unknown() || wanted.unknown() || ty.without_regions() == wanted.without_regions() {
            return Ok(());
        }
        self.coerce(key, wanted).map_err(|error| Error {
            message: error
                .message
                .replacen("expected type", "expected a key of type", 1),
            ..error
        })
    }

    fn check_lookup(&mut self, base_ty: &Type, index: &mut Expr, span: Span) -> Result<Type> {
        if let Type::Map(key, value, _) = base_ty {
            self.check_key(key, index)?;
            return Ok(Type::Maybe(value.clone()));
        }
        let ty = self.check_expr(index)?;
        if base_ty.unknown() {
            return Ok(Type::Unknown);
        }
        self.expect_type(&ty, &Type::Int, index.span)?;
        let item = match base_ty {
            Type::Text(_) => Type::Char,
            Type::Array(items, _) if matches!(**items, Type::None | Type::Fail(_)) => {
                return err(
                    span,
                    "cannot tell the type of this item from none or 'fail …'; give the array a type first",
                );
            }
            Type::Array(items, _) | Type::Slice(items, _) => (**items).clone(),
            Type::Ptr(inner, _) if matches!(**inner, Type::Array(..)) => {
                return err(
                    span,
                    format!(
                        "this value is a pointer, {}; look into the array it points to, as in 'p^[#i]'",
                        base_ty
                    ),
                );
            }
            Type::Map(..) => {
                return Err(Error::internal_at(span, "a map's lookup read as an item's"));
            }
            other => {
                return err(
                    span,
                    format!(
                        "'[#…]' reads an item of an array, a slice, or text, but this value is {}{}",
                        other,
                        extract_hint(&[other])
                    ),
                );
            }
        };
        Ok(Type::Maybe(Box::new(item)))
    }

    fn check_index(
        &mut self,
        base: &Expr,
        base_ty: &Type,
        index: &mut Expr,
        span: Span,
    ) -> Result<Type> {
        if base_ty.unknown() {
            let checked = self.check_expr(index);
            self.keep_going(checked.map(|_| ()));
            return Ok(Type::Unknown);
        }
        if let Type::Text(region) = base_ty {
            return self.check_text_part(region, index, span);
        }
        if let Type::Map(key, value, _) = base_ty {
            self.check_key(key, index)?;
            return Ok((**value).clone());
        }
        let items = match base_ty {
            Type::Array(items, _) if matches!(**items, Type::None | Type::Fail(_)) => {
                return err(
                    span,
                    "cannot tell the type of this item from none or 'fail …'; give the array a type first",
                );
            }
            Type::Array(items, _) | Type::Slice(items, _) => (**items).clone(),
            Type::Ptr(inner, _) if matches!(**inner, Type::Array(..)) => {
                return err(
                    span,
                    format!(
                        "this value is a pointer, {}; index the array it points to, as in 'p^[i]'",
                        base_ty
                    ),
                );
            }
            other => {
                return err(
                    span,
                    format!(
                        "'[…]' reads an item of an array or slice, but this value is {}{}",
                        other,
                        extract_hint(&[other])
                    ),
                );
            }
        };
        let count = match base_ty {
            Type::Array(_, count) => Some(*count),
            _ => None,
        };
        let out_of_range = |value: i64, at: Span, what: &str| -> Result<()> {
            let beyond = u64::try_from(value).map_or(true, |value| {
                count.is_some_and(|count| value > count || (what == "index" && value == count))
            });
            if !beyond {
                return Ok(());
            }
            match count {
                Some(count) => err(
                    at,
                    format!(
                        "{} {} is out of range 0..{} for {}",
                        what, value, count, base_ty
                    ),
                ),
                None => err(
                    at,
                    format!("{} {} is out of range: it is less than 0", what, value),
                ),
            }
        };
        let ExprKind::Range(from, to) = &mut index.kind else {
            let ty = self.check_expr(index)?;
            self.expect_type(&ty, &Type::Int, index.span)?;
            if let Some(value) = constant_int(index) {
                out_of_range(value, index.span, "index")?;
            }
            return Ok(items);
        };
        for bound in [&mut **from, &mut **to] {
            let ty = self.check_expr(bound)?;
            self.expect_type(&ty, &Type::Int, bound.span)?;
        }
        let (start, end) = (constant_int(from), constant_int(to));
        for (value, at) in [(start, from.span), (end, to.span)] {
            if let Some(value) = value {
                out_of_range(value, at, "slice bound")?;
            }
        }
        if let (Some(start), Some(end)) = (start, end)
            && end < start
        {
            return err(
                index.span,
                format!("slice {}..{} ends before it starts", start, end),
            );
        }
        index.ty = Some(Type::Range(Box::new(Type::Int)));
        // Map rehashing packs buckets, so slicing arrays stored inside map values would dangle.
        if !matches!(base_ty, Type::Slice(..)) && in_map_value(base) {
            return err(
                span,
                format!(
                    "a slice can't point into a value in a map, which moves when the map grows or is packed; copy the array into a slice first, as in 'new [{}](m[k]) at r'",
                    items.without_regions()
                ),
            );
        }
        let region = match base_ty {
            Type::Slice(_, region) => region.clone(),
            _ => match place_region(base) {
                Some(region) => Some(region),
                None => {
                    return err(
                        span,
                        format!(
                            "a slice points into a region, but this array isn't in one; copy it into a slice, as in 'new [{}](xs) at r', or keep the array in a region with 'new {}(…) at r'",
                            items.without_regions(),
                            base_ty.without_regions()
                        ),
                    );
                }
            },
        };
        Ok(Type::Slice(Box::new(items), region))
    }

    fn check_edit(
        &mut self,
        span: Span,
        items: &mut Expr,
        op: EditOp,
        args: &mut [Expr],
    ) -> Result<Type> {
        let word = op.word();
        if op.makes_copy() {
            return Err(Error::internal_at(
                span,
                format!("'{}' outside the copy it makes", word),
            ));
        }
        let ty = match &items.kind {
            ExprKind::Var(name) => {
                let name = name.clone();
                let info = self.lookup_or_err(&name, items.span)?;
                if info.result {
                    return err(
                        items.span,
                        format!("'{0}' is a result; set it with '{0} <- …'", name),
                    );
                }
                // Closure-captured slices share elements with outer scope but not length.
                if info.kept
                    && info.passing == Passing::Copy
                    && info.mode == Mode::Flex
                    && matches!(info.ty, Type::Slice(..))
                {
                    return err(
                        items.span,
                        format!(
                            "'{0}' changes '{1}', the copy this lambda keeps of a slice of the code around it, whose length only the slice itself changes; make the slice inside the lambda, take it as a parameter, 'flex& {1}', or keep the slice as a place, '[flex& {1}, @s]', in a region declared after it",
                            word, name
                        ),
                    );
                }
                let needs_flex = matches!(info.ty, Type::Slice(..));
                let has_contents = self.bind_has_contents(&info.ty);
                if (needs_flex && info.mode != Mode::Flex)
                    || (!needs_flex
                        && !info.mode.can_change_contents(has_contents)
                        && matches!(info.ty, Type::Map(..)))
                {
                    if info.param && info.passing == Passing::FixedRef {
                        return err(
                            items.span,
                            format!(
                                "'{0}' changes '{1}', a 'fixed&' parameter, which only reads the caller's place; one that changes it is written 'flex& {1}: {2}'",
                                word, name, info.ty
                            ),
                        );
                    }
                    if info.mode == Mode::Bind {
                        return err(
                            items.span,
                            format!(
                                "'{0}' changes the length of '{1}', a 'bind' slice, which stays bound to one value, so only its items change; make a new slice with the change, as in 'fixed changed = {1}.{2}(…) at r', or keep the slice in a 'flex' variable to change its length",
                                word,
                                name,
                                if op == EditOp::Add {
                                    "added"
                                } else {
                                    "without"
                                }
                            ),
                        );
                    }
                    if info.param || info.refers.is_some() {
                        let what = if info.param {
                            "a parameter, which never changes"
                        } else {
                            "a 'fixed&'"
                        };
                        return err(
                            items.span,
                            format!(
                                "'{}' changes '{}', {}{}",
                                word,
                                name,
                                what,
                                self.param_hint(&name, info)
                            ),
                        );
                    }
                    let what = if matches!(info.ty, Type::Map(..)) {
                        "map"
                    } else {
                        "slice"
                    };
                    return err(
                        items.span,
                        format!(
                            "'{}' changes '{}', which is immutable; keep the {} in a 'flex' variable to change it",
                            word, name, what
                        ),
                    );
                }
                let checked = self.check_expr(items)?;
                self.note_slice_edit(&name, op, !args.is_empty(), span);
                checked
            }
            ExprKind::Index(_, index) if matches!(index.kind, ExprKind::Range(..)) => {
                self.check_expr(items)?;
                return err(
                    items.span,
                    format!(
                        "'{}' changes the slice where it is kept, so it can't change a part taken of one; keep the part in a variable first, as in 'flex part = xs[a..b]'",
                        word
                    ),
                );
            }
            ExprKind::Field(..) | ExprKind::Deref(_) | ExprKind::Index(..) => {
                self.check_place_target(items, false).map_err(|mut error| {
                    if let Some(rest) = error.message.strip_prefix("cannot assign to ") {
                        error.message = format!("'{}' can't change {}", word, rest);
                    } else if error.message.starts_with("'len' can't be assigned") {
                        error.message =
                            format!("'{}' changes a slice, but this value is int", word);
                    }
                    error
                })?
            }
            _ => {
                let ty = self.check_expr(items)?;
                if matches!(ty, Type::Slice(..)) {
                    return err(
                        items.span,
                        format!(
                            "'{}' changes the slice where it is kept, so it needs a variable, a field, or an item holding the slice, not a temporary value",
                            word
                        ),
                    );
                }
                ty
            }
        };
        if let Type::Map(key, value, _) = &ty {
            return match (op, &mut *args) {
                (EditOp::Del, [k]) => {
                    self.check_key(key, k)?;
                    Ok(Type::Maybe(value.clone()))
                }
                (EditOp::Del, _) => err(
                    span,
                    format!(
                        "'del' takes the key to take out of the map, as in 'm.del(k)', got {}",
                        count(args.len(), "argument")
                    ),
                ),
                (EditOp::Add, _) => err(
                    span,
                    "a map adds a key, or gives it a new value, with 'm[k] = v'",
                ),
                (EditOp::Added | EditOp::Without, _) => Err(Error::internal_at(
                    span,
                    format!("'{}' outside the copy it makes", word),
                )),
            };
        }
        let (item, region) = match &ty {
            Type::Slice(item, region) => ((**item).clone(), region.clone()),
            _ if ty.unknown() => {
                self.check_each(args);
                return Ok(Type::Nothing);
            }
            Type::Array(..) => {
                return err(
                    span,
                    format!(
                        "an array's length is part of its type, so '{}' can't change it; make a slice in a region, as in 'new [{}](xs) at r'",
                        word,
                        item_type_example(&ty)
                    ),
                );
            }
            other => {
                return err(
                    span,
                    format!(
                        "'{}' changes a slice, but this value is {}{}",
                        word,
                        other,
                        extract_hint(&[other])
                    ),
                );
            }
        };
        let (index, value) = match (op, &mut *args) {
            (EditOp::Add, [value]) => (None, Some(value)),
            (EditOp::Add, [index, value]) => (Some(index), Some(value)),
            (EditOp::Del, []) => (None, None),
            (EditOp::Del, [index]) => (Some(index), None),
            (EditOp::Add, _) => {
                return err(
                    span,
                    format!(
                        "'add' takes the value, or an index and the value, as in 'xs.add(v)' or 'xs.add(i, v)', got {}",
                        count(args.len(), "argument")
                    ),
                );
            }
            (EditOp::Del, _) => {
                return err(
                    span,
                    format!(
                        "'del' takes an index, or nothing for the last item, as in 'xs.del(i)' or 'xs.del()', got {}",
                        count(args.len(), "argument")
                    ),
                );
            }
            (EditOp::Added | EditOp::Without, _) => {
                return Err(Error::internal_at(
                    span,
                    format!("'{}' outside the copy it makes", word),
                ));
            }
        };
        if let Some(index) = index {
            let index_ty = self.check_expr(index)?;
            self.expect_type(&index_ty, &Type::Int, index.span)?;
            if let Some(n) = constant_int(index)
                && n < 0
            {
                return err(
                    index.span,
                    format!("index {} is out of range: it is less than 0", n),
                );
            }
        }
        let Some(value) = value else { return Ok(item) };
        self.check_expr(value)?;
        self.coerce(value, &item)?;
        self.hand(value, HandedTo::Place(self.value_text(items)));
        match region.as_deref() {
            Some(region) if region != ANY_REGION => match self.lookup(region) {
                Some(info)
                    if info.ty == Type::Region
                        && !info.allocates
                        && region == THIS_WORD
                        && self.called_on_a_value() =>
                {
                    err(
                        span,
                        format!(
                            "adding to a slice may need more room in its region, and {}",
                            self.cannot_allocate_in_this(
                                "add to it where the value is kept, outside the method"
                            )
                        ),
                    )
                }
                Some(info) if info.ty == Type::Region && !info.allocates => err(
                    span,
                    format!(
                        "adding to a slice may need more room in its region '{0}', which this task only names in its types; take it as a parameter, '{0}: region'",
                        region
                    ),
                ),
                _ => self
                    .visible_region(region, span, true)
                    .map(|()| Type::Nothing),
            },
            _ => err(
                span,
                format!(
                    "adding to a slice may need more room in its region, but which region this slice is in isn't known here; keep it in a variable whose type names the region, as in 'flex xs: {}@r = …'",
                    Type::Slice(Box::new(item.without_regions()), None)
                ),
            ),
        }
    }

    fn check_scan(
        &mut self,
        span: Span,
        args: &mut [Expr],
        region: &mut Option<String>,
        region_span: Span,
    ) -> Result<Type> {
        let (prompt, rest) = match args {
            [] => return err(span, SCAN_TAKES),
            [prompt, rest @ ..] => (prompt, rest),
        };
        if let ExprKind::Var(name) = &prompt.kind
            && Type::builtin(name).is_some()
            && self.lookup(name).is_none()
        {
            return err(
                prompt.span,
                format!(
                    "'scan' shows a text prompt first, as in 'scan(\"Age: \", {})'",
                    name
                ),
            );
        }
        let shows = self.check_expr(prompt)?;
        if !matches!(shows, Type::Text(_)) && !shows.unknown() {
            return err(
                prompt.span,
                format!(
                    "'scan' shows a text prompt, as in 'scan(\"Name: \") at r', but this value is {}{}",
                    shows,
                    extract_hint(&[&shows])
                ),
            );
        }
        let number = match rest {
            [] => None,
            [named] => Some(scanned_type(named)?),
            _ => {
                return err(
                    span,
                    format!("{}, got {}", SCAN_TAKES, count(args.len(), "argument")),
                );
            }
        };
        match number {
            None => {
                let keeps = self.region_or_default(region.as_ref(), region_span, || {
                    "'scan' keeps the line it reads in a region, so it names one, as in 'scan(\"Name: \") at r' or 'scan(\"Name: \")@r'".to_string()
                })?;
                *region = Some(keeps.clone());
                self.visible_region(&keeps, region_span, true)?;
                Ok(Type::Maybe(Box::new(Type::Text(Some(keeps)))))
            }
            Some(number) if region.is_some() => err(
                region_span,
                format!(
                    "a number needs no memory, so 'scan' reading one names no region: write 'scan(\"Age: \", {})'",
                    number
                ),
            ),
            Some(number) => Ok(Type::Or(
                Box::new(number),
                Box::new(Type::Named(INPUT_ERROR.to_string(), None)),
            )),
        }
    }

    fn check_shown(&mut self, arg: &mut Expr) -> Result<()> {
        if matches!(arg.kind, ExprKind::Ref(_)) {
            return self.check_address(arg).map(|_| ());
        }
        if matches!(arg.kind, ExprKind::Spread(_)) {
            return match self.check_expr(arg)? {
                Type::Group(group) if !self.allows(Need::Shown, &Type::Group(group.clone())) => {
                    err(
                        arg.span,
                        format!(
                            "show writes each value of the group '{0}...', so the group asks each of its types to be shown: '<{0}...: shown>'",
                            group
                        ),
                    )
                }
                _ => Ok(()),
            };
        }
        let copies = self.unsettled_copies.len();
        let types = self.unsettled_types.len();
        let ty = self.check_expr(arg)?;
        if ty.unknown() {
            return Ok(());
        }
        if past_end(arg) {
            return self.coerce(arg, &Type::Maybe(Box::new(Type::Bool)));
        }
        // User-defined `str` runs inside a transient line region freed when `show` ends (see `codegen::gen_show`).
        if self.has_own_str(&ty) {
            self.unsettled_copies.truncate(copies);
            self.unsettled_types.truncate(types);
            return self.show_with_str(arg);
        }
        if self.writable(&ty) {
            self.note_written_strs(&ty, arg.span);
            return Ok(());
        }
        if let Some(untold) = self.untold_param(&ty) {
            return err(arg.span, untold);
        }
        let own = match self
            .owner_of(&ty)
            .filter(|owner| self.shapes.contains_key(owner) || self.kinds.contains_key(owner))
        {
            Some(owner) => format!(
                "; or give {} '{}' its own method 'str(r: region) -> text@r'",
                if self.kinds.contains_key(&owner) {
                    "kind"
                } else {
                    "shape"
                },
                unqualified(&owner)
            ),
            None => String::new(),
        };
        err(
            arg.span,
            format!("show can't write {}{}", self.why_unwritable(&ty), own),
        )
    }

    fn why_unwritable(&self, ty: &Type) -> String {
        let part = self.unwritable_part(ty).unwrap_or_else(|| ty.clone());
        let holds = if part == *ty {
            String::new()
        } else {
            format!(", since it holds {}", part)
        };
        let hint = match &part {
            Type::Param(_) => format!("; {} {}", part, self.why_not(Need::Shown, &part)),
            Type::Or(..) if part == *ty => extract_hint(&[ty]),
            Type::Or(..) => {
                "; a value that can fail is read first, with a plan B, match, or is".to_string()
            }
            Type::Maybe(inner) if matches!(inner.as_ref(), Type::Or(..)) => extract_hint(&[&part]),
            Type::Nothing => "; this has no value".to_string(),
            _ => self.no_own_str(&part),
        };
        format!("{} as text{}{}", ty, holds, hint)
    }

    fn writable(&self, ty: &Type) -> bool {
        self.unwritable_part(ty).is_none()
    }

    fn unwritable_part(&self, ty: &Type) -> Option<Type> {
        self.unwritable_in(ty, &mut Vec::new())
    }

    // Track visited shapes/kinds in `seen` to allow recursive structures (e.g. via slices).
    fn unwritable_in(&self, ty: &Type, seen: &mut Vec<String>) -> Option<Type> {
        match ty {
            _ if ty.is_numeric() => None,
            Type::Char
            | Type::Bool
            | Type::Text(_)
            | Type::Ptr(..)
            | Type::Task(_)
            | Type::Closure(_) => None,
            Type::Maybe(inner) | Type::Array(inner, _) | Type::Slice(inner, _) => {
                self.unwritable_in(inner, seen)
            }
            Type::Map(key, value, _) => self
                .unwritable_in(key, seen)
                .or_else(|| self.unwritable_in(value, seen)),
            Type::Tuple(items) => items.iter().find_map(|item| self.unwritable_in(item, seen)),
            Type::Param(_) | Type::Group(_) if self.allows(Need::Shown, ty) => None,
            Type::Named(..) | Type::Applied(_) if self.has_own_str(ty) => None,
            Type::Applied(_) if untold_kind(ty) => None,
            Type::Named(..) | Type::Applied(_) => {
                let name = match ty {
                    Type::Applied(applied) => &applied.name,
                    Type::Named(name, _) => name,
                    _ => return Some(ty.clone()),
                };
                if seen.contains(name) {
                    return None;
                }
                let Some(parts) = self.written_parts(ty) else {
                    return Some(ty.clone());
                };
                seen.push(name.clone());
                let found = parts.iter().find_map(|part| self.unwritable_in(part, seen));
                seen.pop();
                found
            }
            _ => Some(ty.clone()),
        }
    }

    fn written_parts(&self, ty: &Type) -> Option<Vec<Type>> {
        let (name, given): (&str, &[Type]) = match ty {
            Type::Named(name, _) => (name, &[]),
            Type::Applied(applied) => (&applied.name, &applied.types),
            _ => return None,
        };
        if let Some(shape) = self.shapes.get(name) {
            let names: HashMap<&str, &Type> = shape
                .types
                .iter()
                .map(|param| param.name.as_str())
                .zip(given)
                .collect();
            return Some(
                shape
                    .fields
                    .iter()
                    .filter(|field| !field.private)
                    .map(|field| {
                        field
                            .ty
                            .map_params(&mut |param| names.get(param).map(|ty| (*ty).clone()))
                    })
                    .collect(),
            );
        }
        let kind = self.kinds.get(name)?;
        let names: HashMap<&str, &Type> = kind
            .types
            .iter()
            .map(|param| param.name.as_str())
            .zip(given)
            .collect();
        Some(
            kind.variants
                .iter()
                .flat_map(|variant| {
                    variant.payload.iter().map(|field| {
                        field
                            .ty
                            .map_params(&mut |param| names.get(param).map(|ty| (*ty).clone()))
                    })
                })
                .collect(),
        )
    }

    fn applied_parts(&self, applied: &Applied) -> Option<Vec<Type>> {
        let (_, params, parts) = self.takes_types(&applied.name)?;
        let names: HashMap<&str, &Type> = params
            .iter()
            .map(|param| param.name.as_str())
            .zip(&applied.types)
            .collect();
        Some(
            parts
                .iter()
                .map(|ty| ty.map_params(&mut |param| names.get(param).map(|ty| (*ty).clone())))
                .collect(),
        )
    }

    fn has_own_str(&self, ty: &Type) -> bool {
        self.owner_of(ty)
            .is_some_and(|owner| self.tasks.contains_key(&method_name(&owner, STR)))
    }

    /// Collects instantiated `str` methods needed when displaying compound types containing generic shapes.
    fn written_strs(
        &self,
        ty: &Type,
        seen: &mut Vec<String>,
        found: &mut Vec<(String, Vec<Type>)>,
    ) {
        match ty {
            Type::Maybe(inner) | Type::Array(inner, _) | Type::Slice(inner, _) => {
                self.written_strs(inner, seen, found)
            }
            Type::Map(key, value, _) => {
                self.written_strs(key, seen, found);
                self.written_strs(value, seen, found);
            }
            Type::Tuple(items) => items
                .iter()
                .for_each(|item| self.written_strs(item, seen, found)),
            Type::Named(name, _) if !seen.contains(name) => {
                seen.push(name.clone());
                if let Some(made) = self.made_of.get(name)
                    && self.tasks.contains_key(&method_name(&made.name, STR))
                {
                    found.push((method_name(&made.name, STR), made.types.clone()));
                } else if !self.has_own_str(ty) {
                    for part in self.written_parts(ty).unwrap_or_default() {
                        self.written_strs(&part, seen, found);
                    }
                }
            }
            _ => {}
        }
    }

    fn note_written_strs(&mut self, ty: &Type, at: Span) {
        let mut found = Vec::new();
        self.written_strs(ty, &mut Vec::new(), &mut found);
        for (method, types) in found {
            let given: Vec<TypeArg> = types.into_iter().map(|ty| (ty, at)).collect();
            self.note_instance(at, &method, &given);
        }
    }

    fn no_own_str(&self, ty: &Type) -> String {
        let Some(owner) = self
            .owner_of(ty)
            .filter(|owner| self.shapes.contains_key(owner) || self.kinds.contains_key(owner))
        else {
            return String::new();
        };
        let what = if self.kinds.contains_key(&owner) {
            "kind"
        } else {
            "shape"
        };
        format!(
            "; {} '{}' has no method 'str', which says how its values are written; give it one, written 'str(r: region) -> text@r'",
            what,
            unqualified(&owner)
        )
    }

    fn show_with_str(&mut self, arg: &mut Expr) -> Result<()> {
        let span = arg.span;
        if self.lookup(SHOWN).is_none() {
            self.define_region(SHOWN, span, true)?;
        }
        let value = std::mem::replace(arg, Expr::new(ExprKind::NoneLit, span));
        arg.kind = ExprKind::MethodCall {
            value: Box::new(value),
            name: STR.to_string(),
            args: vec![Expr::new(ExprKind::Var(SHOWN.to_string()), span)],
            dotted: None,
        };
        self.check_expr(arg)?;
        Ok(())
    }

    /// Outlined (`#[inline(never)]`) to bound stack growth on deep concatenation/interpolation chains.
    #[inline(never)]
    fn check_join(
        &mut self,
        parts: &mut Vec<Expr>,
        region: &mut String,
        region_span: Span,
    ) -> Result<Type> {
        if let Some(field) = &self.in_default {
            return err(
                parts.first().map_or(region_span, |part| part.span),
                format!(
                    "joined text, or text holding values, is made while the program runs, so {} can't fall back on it; its default is text written whole, as in '\"n\"'",
                    field
                ),
            );
        }
        if region.is_empty() {
            *region = self.region_or_default(None, region_span, || {
                "text holding values is new text, so it names the region it goes in, as in '\"n = {n}\" at r' or '\"n = {n}\"@r'".to_string()
            })?;
            let pieces = std::mem::take(parts);
            crate::parser::interpolated_parts(pieces, region, region_span, parts);
        }
        let region = region.as_str();
        let mut numbers = true;
        let mut other = None;
        let wanted = std::mem::take(&mut self.region_wanted);
        let mut failed = None;
        for part in parts.iter_mut() {
            let ty = match self.check_expr(part) {
                Ok(ty) => ty,
                Err(error) if self.region_wanted && failed.is_none() => {
                    failed = Some(error);
                    continue;
                }
                Err(error) => {
                    self.region_wanted = wanted;
                    return Err(error);
                }
            };
            numbers &= ty.is_numeric();
            if !matches!(ty, Type::Text(_)) && other.is_none() && !ty.unknown() {
                other = Some((ty, part.span));
            }
        }
        self.region_wanted = wanted;
        if let Some(error) = failed {
            if numbers && other.is_some() {
                return err(
                    region_span,
                    format!(
                        "numbers are added without a region, so 'at {0}' after '+' names the region of none of them; a call that takes its region last names it with '@' right after it, as in 'f(x)@{0}'",
                        region
                    ),
                );
            }
            return Err(error);
        }
        if parts.iter().all(|p| matches!(p.ty, Some(Type::Array(..)))) {
            return err(
                region_span,
                "arrays are kept on the stack without a region, so 'at ...' is not used with '+'; write 'a + b'",
            );
        }
        let has_slice = parts.iter().any(|p| matches!(p.ty, Some(Type::Slice(..))));
        if has_slice {
            let mut slice_item: Option<Type> = None;
            for part in parts.iter() {
                if let Some(Type::Slice(item, _)) = &part.ty {
                    if let Some(existing) = &slice_item {
                        if existing.without_regions() != item.without_regions() {
                            return err(
                                part.span,
                                format!(
                                    "'+' joins slices of {}, but this slice holds {}",
                                    existing, item
                                ),
                            );
                        }
                    } else {
                        slice_item = Some((**item).clone());
                    }
                }
            }
            let Some(item_ty) = slice_item else {
                return err(region_span, "no slice parts in join");
            };
            for part in parts.iter_mut() {
                let Some(ty) = part.ty.as_ref() else {
                    continue;
                };
                if let Type::Slice(it, _) = ty {
                    if it.without_regions() != item_ty.without_regions() {
                        return err(
                            part.span,
                            format!(
                                "'+' joins slices of {}, but this slice holds {}",
                                item_ty, it
                            ),
                        );
                    }
                } else if matches!(ty, Type::Array(..)) {
                    return err(
                        part.span,
                        "expected a slice or item, got an array; an array never becomes a slice: write the values as a slice, as in '[1, 2, ...] at r', or copy them into one, as in 'new [T](xs) at r'",
                    );
                } else {
                    if self.widens(ty, &item_ty) {
                        self.coerce(part, &item_ty)?;
                    } else if ty.without_regions() != item_ty.without_regions() {
                        return err(
                            part.span,
                            format!(
                                "'+' joins slices of {}, but this value is {}",
                                item_ty, ty
                            ),
                        );
                    }
                }
            }
            self.visible_region(region, region_span, true)?;
            return Ok(Type::Slice(Box::new(item_ty), Some(region.to_string())));
        }
        if numbers {
            return err(
                region_span,
                format!(
                    "numbers are added without a region; 'at {}' after '+' is for joining text",
                    region
                ),
            );
        }
        if let Some((ty, at)) = other {
            return err(
                at,
                format!(
                    "'+' joins text, but this value is {}{}",
                    ty,
                    self.to_text_hint(&ty)
                ),
            );
        }
        self.visible_region(region, region_span, true)?;
        // `"{s}"` or `t.str() at r` directly splices bytes during join, skipping redundant temporary allocation.
        for part in parts.iter_mut() {
            let ExprKind::ToText { value, .. } = &part.kind else {
                continue;
            };
            if matches!(value.ty, Some(Type::Text(_))) {
                let ExprKind::ToText { value, .. } =
                    std::mem::replace(&mut part.kind, ExprKind::NoneLit)
                else {
                    continue;
                };
                *part = *value;
            }
        }
        Ok(Type::Text(Some(region.to_string())))
    }

    fn to_text_hint(&self, ty: &Type) -> String {
        if matches!(ty, Type::Fail(_)) {
            return "; 'fail' takes only the value right after it, so write 'fail (a + b)@r'"
                .to_string();
        }
        if self.has_builtin_str(ty) || self.has_own_str(ty) {
            return "; turn it into text first, as in 'n.str() at r'".to_string();
        }
        extract_hint(&[ty])
    }

    fn check_copy(
        &mut self,
        span: Span,
        value: &mut Expr,
        region: Option<&str>,
        region_span: Span,
    ) -> Result<Type> {
        let changed = match &mut value.kind {
            ExprKind::Edit { items, op, args } if op.makes_copy() => {
                let op = *op;
                self.copy_words
                    .insert((span.file, span.line, span.col), op.word());
                Some((self.check_changed(span, items, op, args)?, op.word()))
            }
            _ => None,
        };
        let (ty, word) = match changed {
            Some((ty, word)) => {
                value.ty = Some(ty.clone());
                (ty, word)
            }
            None => (self.check_expr(value)?, COPY),
        };
        if ty.unknown() {
            return Ok(Type::Unknown);
        }
        if unsettled(&ty) {
            return err(
                value.span,
                format!(
                    "cannot tell the type of this value from none or 'fail …', so it can't be copied; give it a type first, as in 'x: {}'",
                    settled_example(&ty)
                ),
            );
        }
        if has_closure(&ty) {
            return err(
                span,
                format!(
                    "'{}' can't copy {}: what a lambda that keeps what it uses keeps stays in its region, which its type names; make the lambda again in the other region",
                    word, ty
                ),
            );
        }
        if !holds_pointers(&ty, &self.regional)
            && !holds_text(&ty, &self.takes_region)
            && ty.params().is_empty()
        {
            let what = match ty {
                Type::Nothing => "this has no value".to_string(),
                _ => format!(
                    "this value is {}, which holds no text, slice, or pointer; use it as it is",
                    ty
                ),
            };
            return err(
                span,
                format!("'copy' copies what a value holds in a region, but {}", what),
            );
        }
        let bare = ty.without_regions();
        match region {
            Some(region) => {
                self.visible_region(region, region_span, true)?;
                Ok(self.in_region(&bare, region))
            }
            None => {
                self.unsettled_copies.push(span);
                Ok(self.in_region(&bare, ANY_REGION))
            }
        }
    }

    fn check_changed(
        &mut self,
        span: Span,
        items: &mut Expr,
        op: EditOp,
        args: &mut [Expr],
    ) -> Result<Type> {
        let word = op.word();
        let ty = self.check_expr(items)?;
        if ty.unknown() {
            self.check_each(args);
            return Ok(ty);
        }
        match &ty {
            Type::Map(key, value, _) => {
                match (op, &mut *args) {
                    (EditOp::Added, [k, v]) => {
                        self.check_key(key, k)?;
                        self.check_copied_into(v, value)?;
                    }
                    (EditOp::Without, [k]) => self.check_key(key, k)?,
                    (EditOp::Added, _) => {
                        return err(
                            span,
                            format!(
                                "'added' on a map takes the key and its value, as in 'm.added(k, v)', got {}",
                                count(args.len(), "argument")
                            ),
                        );
                    }
                    _ => {
                        return err(
                            span,
                            format!(
                                "'without' on a map takes the key to leave out, as in 'm.without(k)', got {}",
                                count(args.len(), "argument")
                            ),
                        );
                    }
                }
                Ok(ty)
            }
            Type::Slice(item, _) => {
                let item = (**item).clone();
                let (index, value) = match (op, &mut *args) {
                    (EditOp::Added, [value]) => (None, Some(value)),
                    (EditOp::Added, [index, value]) => (Some(index), Some(value)),
                    (EditOp::Without, []) => (None, None),
                    (EditOp::Without, [index]) => (Some(index), None),
                    (EditOp::Added, _) => {
                        return err(
                            span,
                            format!(
                                "'added' takes the value, or an index and the value, as in 'xs.added(v)' or 'xs.added(i, v)', got {}",
                                count(args.len(), "argument")
                            ),
                        );
                    }
                    _ => {
                        return err(
                            span,
                            format!(
                                "'without' takes an index, or nothing for the last item, as in 'xs.without(i)' or 'xs.without()', got {}",
                                count(args.len(), "argument")
                            ),
                        );
                    }
                };
                if let Some(index) = index {
                    let index_ty = self.check_expr(index)?;
                    self.expect_type(&index_ty, &Type::Int, index.span)?;
                    if let Some(n) = constant_int(index)
                        && n < 0
                    {
                        return err(
                            index.span,
                            format!("index {} is out of range: it is less than 0", n),
                        );
                    }
                }
                if let Some(value) = value {
                    self.check_copied_into(value, &item)?;
                }
                Ok(ty)
            }
            Type::Array(..) => err(
                span,
                format!(
                    "an array's length is part of its type, so '{}' can't make one of another length; make a slice in a region, as in 'new [{}](xs) at r'",
                    word,
                    item_type_example(&ty)
                ),
            ),
            other => err(
                span,
                format!(
                    "'{}' makes a new slice or map, but this value is {}{}",
                    word,
                    other,
                    extract_hint(&[other])
                ),
            ),
        }
    }

    fn check_copied_into(&mut self, value: &mut Expr, item: &Type) -> Result<()> {
        let ty = self.check_expr(value)?;
        if ty.unknown() || item.unknown() || same_ignoring_regions(&ty, item) {
            return Ok(());
        }
        self.coerce(value, item)
    }

    fn settle_copies(&mut self, expr: &mut Expr, expected: &Type) -> Result<()> {
        match (&mut expr.kind, expected) {
            (
                ExprKind::Copy {
                    region: region @ None,
                    ..
                },
                _,
            ) => {
                let mut regions = expected.regions();
                regions.sort_unstable();
                regions.dedup();
                match regions.as_slice() {
                    [] => err(
                        expr.span,
                        format!(
                            "'copy' makes its copy in a region, but a {} here lasts as long as the program, as a literal does; give the place a region, as in '{}'",
                            expected,
                            expected.map_regions_of_names(&mut |_| Some("r".to_string()))
                        ),
                    ),
                    [one] if *one != ANY_REGION => {
                        let one = one.to_string();
                        self.visible_region(&one, expr.span, true)?;
                        if let Some(at) = self
                            .unsettled_copies
                            .iter()
                            .rposition(|at| *at == expr.span)
                        {
                            self.unsettled_copies.remove(at);
                        }
                        *region = Some(one);
                        expr.ty = Some(expected.clone());
                        Ok(())
                    }
                    _ => Ok(()),
                }
            }
            (ExprKind::Array(values), Type::Array(items, _)) => values
                .iter_mut()
                .try_for_each(|value| self.settle_copies(value, items)),
            (ExprKind::Repeat { value, .. }, Type::Array(items, _)) => {
                self.settle_copies(value, items)
            }
            (ExprKind::Tuple(values), Type::Tuple(items)) => values
                .iter_mut()
                .zip(items)
                .try_for_each(|(value, item)| self.settle_copies(value, item)),
            (ExprKind::Wrap(inner), Type::Maybe(value) | Type::Or(value, _)) => {
                self.settle_copies(inner, value)
            }
            (ExprKind::Widen(inner), _) => {
                match inner.ty.as_ref().map(|from| in_region_of(from, expected)) {
                    Some(into) => self.settle_copies(inner, &into),
                    None => Ok(()),
                }
            }
            (ExprKind::Choice(stmt), _) => self.settle_branch_values(stmt, expected),
            (ExprKind::StructInit { name, fields, .. }, Type::Named(_, Some(region))) => {
                let Some(shape) = self.shapes.get(name.as_str()).cloned() else {
                    return Ok(());
                };
                fields.iter_mut().try_for_each(|field| {
                    match shape.fields.iter().find(|f| f.name == field.name) {
                        Some(declared) => self
                            .settle_copies(&mut field.value, &self.in_region(&declared.ty, region)),
                        None => Ok(()),
                    }
                })
            }
            (ExprKind::Construct { tag, args, .. }, Type::Named(kind, Some(region))) => {
                let Some(variant) = self
                    .kinds
                    .get(kind.as_str())
                    .and_then(|k| k.variants.iter().find(|v| v.tag == *tag))
                    .cloned()
                else {
                    return Ok(());
                };
                args.iter_mut()
                    .zip(&variant.payload)
                    .try_for_each(|(arg, field)| {
                        self.settle_copies(arg, &self.in_region(&field.ty, region))
                    })
            }
            _ => Ok(()),
        }
    }

    fn check_slice_source(&mut self, value: &mut Expr, items: &Type, slice: &Type) -> Result<()> {
        if let ExprKind::Repeat { value: item, count } = &mut value.kind {
            self.check_expr(item)?;
            self.coerce(item, items)?;
            let count_ty = self.check_expr(count)?;
            self.expect_type(&count_ty, &Type::Int, count.span)?;
            if let Some(n) = constant_int(count)
                && n < 0
            {
                return err(count.span, format!("count {} is negative", n));
            }
            value.ty = Some(slice.clone());
            return Ok(());
        }
        if matches!(&value.kind, ExprKind::Array(values) if values.is_empty()) {
            value.ty = Some(slice.clone());
            return Ok(());
        }
        let ty = self.check_expr(value)?;
        // Copying `new [T](slice)` isolates contents in the target region (except closures); array literals hold elements as-is.
        let copies = !matches!(value.kind, ExprKind::Array(_))
            && !has_closure(items)
            && (holds_pointers(items, &self.regional) || holds_text(items, &self.takes_region));
        match &ty {
            Type::Array(source, _) | Type::Slice(source, _)
                if copies && fits_regions(&source.without_regions(), &items.without_regions()) =>
            {
                Ok(())
            }
            Type::Array(_, count) => {
                self.coerce(value, &Type::Array(Box::new(items.clone()), *count))
            }
            Type::Slice(source, _) if fits_regions(source, items) => Ok(()),
            Type::Slice(source, _) => err(
                value.span,
                format!(
                    "expected type {}, got {}{}",
                    slice,
                    ty,
                    mismatch_hint(source, items)
                ),
            ),
            _ if ty.unknown() => Ok(()),
            other => err(
                value.span,
                format!(
                    "'new [{}](…)' makes a slice from '[value#count]', an array, or a slice, but this value is {}",
                    items, other
                ),
            ),
        }
    }

    fn check_plan_b(
        &mut self,
        span: Span,
        value: &mut Expr,
        error: Option<&Binding>,
        body: &mut Block,
    ) -> Result<Type> {
        let found = self.check_expr(value);
        let value_ty = self.or_unknown(found);
        if past_end(value) {
            return self.past_end_plan_b(span, value, error, body);
        }
        let (extracted, error_ty) = match &value_ty {
            Type::Maybe(inner) => ((**inner).clone(), None),
            Type::Or(ok, fail) => ((**ok).clone(), Some((**fail).clone())),
            _ if value_ty.unknown() => (Type::Unknown, Some(Type::Unknown)),
            other => {
                return err(
                    value.span,
                    format!(
                        "this value is {}, not a maybe or a 'T ~ E', so it needs no plan B",
                        other
                    ),
                );
            }
        };
        let mut bindings = Vec::new();
        if let Some((name, at)) = error {
            let Some(error_ty) = error_ty else {
                return err(
                    *at,
                    format!(
                        "a {} has no error to name; 'failure e' names the error of a 'T ~ E'",
                        value_ty
                    ),
                );
            };
            if self.variant_in_scope(name).is_some() {
                return err(
                    *at,
                    format!(
                        "'{}' is a variant; to send an error, write '<- fail {}'",
                        name, name
                    ),
                );
            }
            bindings.push((name.clone(), *at, error_ty, Mode::Fixed));
        }
        let entry = self.unset.clone();
        self.push_scope();
        let result = bindings
            .into_iter()
            .filter(|(name, _, _, _)| name != DISCARD)
            .try_for_each(|(name, at, ty, mode)| self.define(&name, ty, mode, at))
            .and_then(|()| self.check_plan_b_body(span, &extracted, body));
        self.pop_scope();
        self.unset = entry;
        let Some((settled, at)) = result? else {
            return Ok(extracted);
        };
        if let Some(region) = settled
            .regions()
            .into_iter()
            .find(|region| !unnamed_region(region) && self.lookup(region).is_none())
        {
            return err(
                at,
                format!(
                    "this value is in region '{}', which is freed when the plan B ends, so it can't be the plan B's value",
                    region
                ),
            );
        }
        if !value_ty.params().is_empty() {
            let held = match &settled {
                Type::Maybe(inner) if !matches!(extracted, Type::Maybe(_)) => (**inner).clone(),
                _ => settled.clone(),
            };
            let told = match &value_ty {
                Type::Maybe(_) => Type::Maybe(Box::new(held)),
                Type::Or(_, error) => Type::Or(Box::new(held), error.clone()),
                other => other.clone(),
            };
            self.settle_types(value, &told)?;
        }
        Ok(settled)
    }

    fn past_end_plan_b(
        &mut self,
        span: Span,
        value: &mut Expr,
        error: Option<&Binding>,
        body: &mut Block,
    ) -> Result<Type> {
        if let Some((_, at)) = error {
            return err(
                *at,
                "a maybe has no error to name; 'failure e' names the error of a 'T ~ E'",
            );
        }
        let open = Type::Param(PAST_END.to_string());
        let entry = self.unset.clone();
        self.push_scope();
        let result = self.check_plan_b_body(span, &open, body);
        self.pop_scope();
        self.unset = entry;
        let (settled, at) = result?.unwrap_or((Type::Nothing, span));
        if settled.params().contains(&PAST_END) {
            return err(
                at,
                "this tuple has no such item, so its plan B always runs, and gives the value: one of a type, not 'none'",
            );
        }
        let held = match &settled {
            Type::Nothing => Type::Bool,
            Type::Maybe(inner) => (**inner).clone(),
            other => other.clone(),
        };
        self.coerce(value, &Type::Maybe(Box::new(held)))?;
        Ok(settled)
    }

    fn check_plan_b_body(
        &mut self,
        span: Span,
        extracted: &Type,
        body: &mut Block,
    ) -> Result<Option<(Type, Span)>> {
        if *extracted == Type::Nothing {
            return self.check_block(body).map(|()| None);
        }
        if let Some(last) = body.last_mut() {
            last_loop_gives(last);
        }
        if extracted.unknown() {
            let Some((last, rest)) = body.split_last_mut() else {
                return Ok(None);
            };
            self.check_block(rest)?;
            if let StmtKind::Expr(e) = &mut last.kind {
                self.check_expr(e)?;
                return Ok(None);
            }
            self.check_stmt(last)?;
            return Ok(None);
        }
        let Some((last, rest)) = body.split_last_mut() else {
            return err(
                span,
                format!(
                    "a plan B needs a value of type {} on its last line, or a '<-'",
                    extracted
                ),
            );
        };
        self.check_block(rest)?;
        if let StmtKind::Expr(e) = &mut last.kind {
            let ty = self.check_expr(e)?;
            if ty == Type::Nothing {
                return err(
                    e.span,
                    format!(
                        "the last line of a plan B gives its value, but this has none; expected a value of type {}",
                        extracted
                    ),
                );
            }
            // `v { none }` widens the whole expression to `maybe` if not already optional.
            if let Some(maybe) = gives_a_maybe(extracted, &ty) {
                return self.coerce(e, &maybe).map(|()| Some((maybe, e.span)));
            }
            if extracted
                .params()
                .iter()
                .any(|name| self.type_param(name).is_none())
            {
                let mut given = HashMap::new();
                self.match_params(extracted, &ty, &mut given);
                let settled = extracted.map_params(&mut |name| given.get(name).cloned());
                if settled != *extracted {
                    return self.coerce(e, &settled).map(|()| Some((settled, e.span)));
                }
            }
            if extracted.regions().contains(&ANY_REGION) {
                let mut regions = HashMap::new();
                self.match_regions(extracted, &ty, &mut regions);
                let settled = extracted.map_regions(&mut |region| {
                    Some(
                        regions
                            .get(region)
                            .cloned()
                            .unwrap_or_else(|| region.to_string()),
                    )
                });
                if settled != *extracted {
                    return self.coerce(e, &settled).map(|()| Some((settled, e.span)));
                }
            }
            return self.coerce(e, extracted).map(|()| None);
        }
        if gives_value(last) && always_leaves(std::slice::from_ref(last)) {
            self.check_stmt(last)?;
            return Ok(None);
        }
        if gives_value(last) {
            let span = last.span;
            let given = self.check_branching_value(last)?;
            if let Some(maybe) = given.and_then(|ty| gives_a_maybe(extracted, &ty)) {
                return self
                    .settle_value(body, &maybe)
                    .map(|()| Some((maybe, span)));
            }
            return self.settle_value(body, extracted).map(|()| None);
        }
        self.check_stmt(last)?;
        if !always_leaves(body) {
            let or_loop = if self.loops.is_empty() {
                ""
            } else {
                ", or leave with 'break' or 'continue'"
            };
            return err(
                span,
                format!(
                    "a plan B must end with a value of type {}, or send with '<-' on every path{}",
                    extracted, or_loop
                ),
            );
        }
        Ok(None)
    }

    fn check_unary(&mut self, expr: &mut Expr) -> Result<Type> {
        let span = expr.span;
        let op = match &expr.kind {
            ExprKind::Unary(op, _) => *op,
            _ => {
                return Err(Error::internal_at(
                    span,
                    "a unary operation that is not one",
                ));
            }
        };
        let e = match &mut expr.kind {
            ExprKind::Unary(_, e) => e,
            _ => {
                return Err(Error::internal_at(
                    span,
                    "a unary operation that is not one",
                ));
            }
        };
        let ty = self.check_expr(e)?;
        if ty.unknown() {
            return Ok(Type::Unknown);
        }
        match op {
            UnaryOp::Neg => {
                if !ty.is_numeric() {
                    if self.operator_neg(&ty) {
                        let taken = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
                        let ExprKind::Unary(_, operand) = taken else {
                            return Err(Error::internal_at(
                                span,
                                "a negation that is no longer one",
                            ));
                        };
                        expr.kind = ExprKind::MethodCall {
                            value: operand,
                            name: "neg".to_string(),
                            args: Vec::new(),
                            dotted: None,
                        };
                        return self.infer_expr(expr);
                    }
                    return err(
                        span,
                        format!(
                            "negation requires a number, got {}{}",
                            ty,
                            extract_hint(&[&ty])
                        ),
                    );
                }
                if ty.is_unsigned_int() {
                    return err(
                        span,
                        format!(
                            "{} is never negative, so it can't be negated; turn it into an int first, as in '-int(x)'",
                            a_type(&ty)
                        ),
                    );
                }
                match constant_int(e) {
                    Some(value) if ty == Type::Int => fits_int(-i128::from(value), span)?,
                    Some(value) => fits_type(-i128::from(value), &ty, span)?,
                    None => {}
                }
                Ok(ty)
            }
            UnaryOp::Not => {
                self.expect_type(&ty, &Type::Bool, e.span)?;
                Ok(Type::Bool)
            }
        }
    }

    /// Resolves operator-overloading trait methods (`plus`, `cmp`, `neg`) from direct methods or followed patterns (e.g. `Numeric`).
    fn operator_method(&self, op: BinaryOp, ty: &Type) -> Option<&'static str> {
        let name = match op {
            BinaryOp::Add => "plus",
            BinaryOp::Sub => "minus",
            BinaryOp::Mul => "times",
            BinaryOp::Div => "div",
            BinaryOp::Mod => "rem",
            BinaryOp::Lt | BinaryOp::Le | BinaryOp::Gt | BinaryOp::Ge => "cmp",
            _ => return None,
        };
        if matches!(
            ty,
            Type::Text(_)
                | Type::Task(_)
                | Type::Closure(_)
                | Type::Array(..)
                | Type::Slice(..)
        ) {
            return None;
        }
        if let Some(owner) = self.owner_of(ty) {
            let task_name = method_name(&owner, name);
            if let Some(task) = self.tasks.get(&task_name)
                && task.params.len() == 2
            {
                return Some(name);
            }
        }
        self.patterns.values().find_map(|pattern| {
            let has = pattern
                .method(name)
                .is_some_and(|method| method.params.len() == 2);
            (has && self.followed_by(ty, &pattern.name).is_some()).then_some(name)
        })
    }

    /// Why a shape's own operator method can't answer the operator, when it can't: the method takes
    /// another value of the shape, and 'cmp' gives an int, below 0, 0, or above 0.
    fn operator_misfit(&self, method: &str, ty: &Type) -> Option<String> {
        let owner = self.owner_of(ty)?;
        let task = self.tasks.get(&method_name(&owner, method))?;
        let (_, other) = task.params.get(1)?;
        let written = unqualified(&owner);
        if other.without_regions() != ty.without_regions() {
            return Some(format!(
                "this operator on two {0} values calls '{0}.{1}', which must take another {0}, '{1}(other: {0})', but this one takes {2}; call it by name, as in 'x.{1}(y)'",
                written, method, other
            ));
        }
        if method == "cmp" && task.ret != Type::Int {
            return Some(format!(
                "this comparison calls '{0}.cmp', which gives an int, below 0, 0, or above 0, as 'cmp(other: {0}) -> int' does, but this one gives {1}",
                written, task.ret
            ));
        }
        None
    }

    fn operator_neg(&self, ty: &Type) -> bool {
        if matches!(
            ty,
            Type::Text(_)
                | Type::Task(_)
                | Type::Closure(_)
                | Type::Array(..)
                | Type::Slice(..)
        ) {
            return false;
        }
        if let Some(owner) = self.owner_of(ty) {
            let task_name = method_name(&owner, "neg");
            if let Some(task) = self.tasks.get(&task_name)
                && task.params.len() == 1
            {
                return true;
            }
        }
        self.patterns.values().any(|pattern| {
            pattern
                .method("neg")
                .is_some_and(|method| method.params.len() == 1)
                && self.followed_by(ty, &pattern.name).is_some()
        })
    }

    fn check_binary_expr(&mut self, expr: &mut Expr) -> Result<Type> {
        let span = expr.span;
        let ExprKind::Binary(op, l, r) = &mut expr.kind else {
            return Err(Error::internal_at(
                span,
                "a binary operation that is not one",
            ));
        };
        let op = *op;
        if op == BinaryOp::NotSimilar
            && let ExprKind::Var(name) = &l.kind
            && self.lookup(name).is_none()
            && [name.clone(), self.in_module(name)]
                .iter()
                .any(|name| self.tasks.contains_key(name) || self.shapes.contains_key(name))
        {
            return err(
                span,
                format!(
                    "'< … >' names the types a use gives, as in '{}<int>'; leave it out to let the values say which they are",
                    unqualified(name)
                ),
            );
        }
        if matches!(op, BinaryOp::Eq | BinaryOp::Ne)
            && [&**l, &**r]
                .into_iter()
                .any(|side| matches!(side.kind, ExprKind::Ref(_)))
        {
            return self.check_address_compare(l, r, span);
        }
        let lt = self.check_expr(l)?;
        let rt = self.check_expr(r)?;
        self.check_binary_expr_typed(expr, op, lt, rt, span)
    }

    #[inline(never)]
    fn check_binary_expr_typed(
        &mut self,
        expr: &mut Expr,
        op: BinaryOp,
        mut lt: Type,
        mut rt: Type,
        span: Span,
    ) -> Result<Type> {
        let ExprKind::Binary(_, l, r) = &mut expr.kind else {
            return Err(Error::internal_at(
                span,
                "a binary operation that is not one",
            ));
        };
        if holds_untold(&lt) && !holds_untold(&rt) {
            self.settle_variant(l, &rt)?;
            lt = l.ty.clone().unwrap_or(lt);
        } else if holds_untold(&rt) && !holds_untold(&lt) {
            self.settle_variant(r, &lt)?;
            rt = r.ty.clone().unwrap_or(rt);
        } else if holds_untold(&lt)
            && holds_untold(&rt)
            && let Some(joined) = self.join(&lt, &rt).filter(|joined| !holds_untold(joined))
        {
            let joined = self.made_kinds(joined, span)?;
            self.settle_variant(l, &joined)?;
            self.settle_variant(r, &joined)?;
            lt = l.ty.clone().unwrap_or(lt);
            rt = r.ty.clone().unwrap_or(rt);
        }
        if lt.unknown() || rt.unknown() {
            return Ok(match op {
                BinaryOp::Eq
                | BinaryOp::Ne
                | BinaryOp::Similar
                | BinaryOp::NotSimilar
                | BinaryOp::Lt
                | BinaryOp::Le
                | BinaryOp::Gt
                | BinaryOp::Ge
                | BinaryOp::And
                | BinaryOp::Or => Type::Bool,
                _ => Type::Unknown,
            });
        }
        if matches!(
            op,
            BinaryOp::Eq | BinaryOp::Ne | BinaryOp::Similar | BinaryOp::NotSimilar
        ) {
            if self.widens(&lt, &rt) {
                self.coerce(l, &in_region_of(&rt, &lt))?;
                lt = l.ty.clone().unwrap_or(lt);
            } else if self.widens(&rt, &lt) {
                self.coerce(r, &in_region_of(&lt, &rt))?;
                rt = r.ty.clone().unwrap_or(rt);
            }
        }
        if op == BinaryOp::Add && (matches!(lt, Type::Text(_)) || matches!(rt, Type::Text(_))) {
            if let Some(other) = [&lt, &rt]
                .into_iter()
                .find(|ty| !matches!(ty, Type::Text(_)))
            {
                return err(
                    span,
                    format!(
                        "'+' joins text to text, but the other value is {}{}",
                        other,
                        self.to_text_hint(other)
                    ),
                );
            }
            let region = self.region_or_default(None, span, || JOIN_NEEDS_REGION.to_string())?;
            return self.join_into(expr, region, span);
        }
        if op == BinaryOp::Add {
            if let (Type::Array(item1, n), Type::Array(item2, m)) = (&lt, &rt) {
                if item1.without_regions() != item2.without_regions() {
                    return err(
                        span,
                        format!(
                            "'+' joins arrays of one item type, but this array holds {} and the other holds {}",
                            item2, item1
                        ),
                    );
                }
                let total = match n.checked_add(*m) {
                    Some(t) => t,
                    None => return err(span, "joined array length exceeds maximum array size"),
                };
                let res_ty = Type::Array(item1.clone(), total);
                self.check_size(&res_ty, span)?;
                expr.ty = Some(res_ty.clone());
                return Ok(res_ty);
            }
            if matches!(lt, Type::Array(..)) && !matches!(rt, Type::Slice(..)) {
                return err(
                    span,
                    format!(
                        "'+' joins arrays of one item type, but one value is {} and the other is {}",
                        lt, rt
                    ),
                );
            }
            if matches!(rt, Type::Array(..)) && !matches!(lt, Type::Slice(..)) {
                return err(
                    span,
                    format!(
                        "'+' joins arrays of one item type, but one value is {} and the other is {}",
                        rt, lt
                    ),
                );
            }
            let left_slice = matches!(lt, Type::Slice(..));
            let right_slice = matches!(rt, Type::Slice(..));
            if left_slice || right_slice {
                if matches!(lt, Type::Array(..)) || matches!(rt, Type::Array(..)) {
                    return err(
                        span,
                        "expected a slice or item, got an array; an array never becomes a slice: write the values as a slice, as in '[1, 2, ...] at r', or copy them into one, as in 'new [T](xs) at r'",
                    );
                }
                let item_match = match (&lt, &rt) {
                    (Type::Slice(item_l, _), Type::Slice(item_r, _)) => {
                        item_l.without_regions() == item_r.without_regions()
                    }
                    (Type::Slice(item_l, _), item) => {
                        item_l.without_regions() == item.without_regions()
                    }
                    (item, Type::Slice(item_r, _)) => {
                        item_r.without_regions() == item.without_regions()
                    }
                    _ => false,
                };
                if !item_match {
                    let (expected_item, other_ty) = if let Type::Slice(item, _) = &lt {
                        (item, &rt)
                    } else if let Type::Slice(item, _) = &rt {
                        (item, &lt)
                    } else {
                        unreachable!()
                    };
                    return err(
                        span,
                        format!(
                            "'+' joins slices of {}, but the other value is {}",
                            expected_item, other_ty
                        ),
                    );
                }
                let region = self.region_or_default(None, span, || {
                    "joining slices makes a new slice, which goes in a region; name it after the last part, as in 'xs + ys at r', or name a default region for the block, as in 'region r default'".to_string()
                })?;
                return self.join_into(expr, region, span);
            }
        }
        if op == BinaryOp::Mul {
            if let Type::Array(item, m) = &lt {
                let Some(n) = constant_int(r) else {
                    return err(
                        r.span,
                        "repeating an array with '*' requires a constant number of times known at compile time, as in 'arr * 3'",
                    );
                };
                let Some(n) = u64::try_from(n).ok().filter(|n| *n > 0) else {
                    return err(
                        r.span,
                        "an array holds at least one value, so it can only be repeated 1 or more times",
                    );
                };
                let total = match m.checked_mul(n) {
                    Some(t) => t,
                    None => return err(span, "repeated array length exceeds maximum array size"),
                };
                let res_ty = Type::Array(item.clone(), total);
                self.check_size(&res_ty, span)?;
                expr.ty = Some(res_ty.clone());
                return Ok(res_ty);
            }
            if let Type::Array(item, m) = &rt {
                let Some(n) = constant_int(l) else {
                    return err(
                        l.span,
                        "repeating an array with '*' requires a constant number of times known at compile time, as in '3 * arr'",
                    );
                };
                let Some(n) = u64::try_from(n).ok().filter(|n| *n > 0) else {
                    return err(
                        l.span,
                        "an array holds at least one value, so it can only be repeated 1 or more times",
                    );
                };
                let total = match m.checked_mul(n) {
                    Some(t) => t,
                    None => return err(span, "repeated array length exceeds maximum array size"),
                };
                let res_ty = Type::Array(item.clone(), total);
                self.check_size(&res_ty, span)?;
                expr.ty = Some(res_ty.clone());
                return Ok(res_ty);
            }
        }
        if matches!(
            op,
            BinaryOp::Add
                | BinaryOp::Sub
                | BinaryOp::Mul
                | BinaryOp::Div
                | BinaryOp::Mod
                | BinaryOp::Lt
                | BinaryOp::Le
                | BinaryOp::Gt
                | BinaryOp::Ge
        ) && (!lt.is_numeric() || !rt.is_numeric())
            && lt.without_regions() == rt.without_regions()
            && let Some(method) = self.operator_method(op, &lt)
        {
            if let Some(why) = self.operator_misfit(method, &lt) {
                return err(span, why);
            }
            let taken = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
            let ExprKind::Binary(_, l, r) = taken else {
                return Err(Error::internal_at(
                    span,
                    "an operation that is no longer one",
                ));
            };
            let call = Expr::new(
                ExprKind::MethodCall {
                    value: l,
                    name: method.to_string(),
                    args: vec![*r],
                    dotted: None,
                },
                span,
            );
            if method == "cmp" {
                expr.kind = ExprKind::Binary(
                    op,
                    Box::new(call),
                    Box::new(Expr::new(ExprKind::IntLit(0), span)),
                );
                return self.check_binary_expr(expr);
            }
            expr.kind = call.kind;
            return self.infer_expr(expr);
        }
        self.check_binary(op, l, r, span, &lt, &rt)
    }

    fn join_into(&mut self, expr: &mut Expr, region: String, span: Span) -> Result<Type> {
        self.visible_region(&region, span, true)?;
        let taken = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
        let ExprKind::Binary(_, l, r) = taken else {
            return Err(Error::internal_at(
                span,
                "a join that is no binary operation",
            ));
        };
        let mut parts = Vec::new();
        for side in [*l, *r] {
            match side.kind {
                ExprKind::Join {
                    parts: inner,
                    region: theirs,
                    ..
                } if theirs == region => parts.extend(inner),
                ExprKind::ToText { value, .. } if matches!(value.ty, Some(Type::Text(_))) => {
                    parts.push(*value)
                }
                _ => parts.push(side),
            }
        }
        let mut region_slot = region;
        let ty = self.check_join(&mut parts, &mut region_slot, span)?;
        expr.kind = ExprKind::Join {
            parts,
            region: region_slot,
            region_span: span,
        };
        expr.ty = Some(ty.clone());
        Ok(ty)
    }

    fn check_binary(
        &mut self,
        op: BinaryOp,
        l: &mut Expr,
        r: &mut Expr,
        span: Span,
        lt: &Type,
        rt: &Type,
    ) -> Result<Type> {
        let (mut lt, mut rt) = (lt.clone(), rt.clone());
        if op == BinaryOp::Pow {
            // Only unannotated right-hand exponents inherit an unsigned/sized base type; bases stay `int`.
            if lt.is_integer() && lt != Type::Int && numeric_literal(r, &lt)? {
                rt = lt.clone();
            } else if lt == Type::Float32 && float32_literal(r) {
                rt = Type::Float32;
            }
            return check_power(l, r, &lt, &rt, span);
        }
        let integer_in = |ty: &Type| match ty {
            Type::Maybe(inner) if inner.is_integer() => Some((**inner).clone()),
            other if other.is_integer() => Some(other.clone()),
            _ => None,
        };
        if let Some(target) = integer_in(&lt)
            && numeric_literal(r, &target)?
        {
            rt = target;
        } else if let Some(target) = integer_in(&rt)
            && numeric_literal(l, &target)?
        {
            lt = target;
        } else if lt == Type::Float32 && float32_literal(r) {
            rt = Type::Float32;
        } else if rt == Type::Float32 && float32_literal(l) {
            lt = Type::Float32;
        }
        match op {
            BinaryOp::Pow => Err(Error::internal_at(
                span,
                "a power checked as other arithmetic",
            )),
            BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul | BinaryOp::Div | BinaryOp::Mod
                if lt == Type::Char || rt == Type::Char =>
            {
                char_arithmetic(op, l, r, &lt, &rt, span)
            }
            BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul | BinaryOp::Div | BinaryOp::Mod => {
                if !lt.is_numeric() || !rt.is_numeric() {
                    if let Some(untold) = self.untold_param(&lt).or_else(|| self.untold_param(&rt))
                    {
                        return err(span, untold);
                    }
                    if let Some(name) = [&lt, &rt].iter().find_map(|ty| match ty {
                        Type::Param(name) => Some(name),
                        _ => None,
                    }) {
                        return err(
                            span,
                            format!(
                                "arithmetic requires numeric operands; '{}' is a type this task takes, and no word asks a type for arithmetic, so a task that does it takes numbers ('int' or 'float') rather than a type it is given",
                                name
                            ),
                        );
                    }
                    if lt.without_regions() != rt.without_regions()
                        && let Some((at, of, other, method)) = [
                            (l.span, &lt, &rt, self.operator_method(op, &lt)),
                            (r.span, &rt, &lt, self.operator_method(op, &rt)),
                        ]
                        .into_iter()
                        .find_map(|(at, of, other, method)| {
                            method.map(|method| (at, of, other, method))
                        })
                    {
                        return err(
                            at,
                            format!(
                                "{} and {} don't mix in arithmetic: {} answers the operator with '{}', which takes its own type on both sides; call the method, as in 'x.{}(y)', turning the other value into {} first",
                                a_type(of),
                                other,
                                a_type(of),
                                method,
                                method,
                                a_type(of)
                            ),
                        );
                    }
                    return err(
                        span,
                        format!(
                            "arithmetic requires numeric operands{}",
                            extract_hint(&[&lt, &rt])
                        ),
                    );
                }
                if lt != rt {
                    let at = if lt == Type::Int { l.span } else { r.span };
                    if (lt == Type::Int && rt == Type::Float)
                        || (lt == Type::Float && rt == Type::Int)
                    {
                        return err(
                            at,
                            "an int and a float don't mix in arithmetic: turn one into the other first, as in 'float(n) + 2.5' (or 'n + int(2.5)', which truncates)",
                        );
                    }
                    if (lt == Type::Int && rt == Type::Unit)
                        || (lt == Type::Unit && rt == Type::Int)
                    {
                        return err(
                            at,
                            "an int and a unit don't mix in arithmetic: turn one into the other first, as in 'int(b) + x' or 'b + unit(x)'",
                        );
                    }
                    if (lt == Type::Float && rt == Type::Unit)
                        || (lt == Type::Unit && rt == Type::Float)
                    {
                        return err(
                            at,
                            "a float and a unit don't mix in arithmetic: turn one into the other first, as in 'float(b) + x' or 'b + unit(x)'",
                        );
                    }
                    return err(
                        at,
                        format!(
                            "{} and {} don't mix in arithmetic: turn one into the other first, as in '{}(b) + a'",
                            a_type(&lt),
                            a_type(&rt),
                            lt
                        ),
                    );
                }
                if lt.is_integer() {
                    check_constant_arithmetic(op, l, r, &lt, span)?;
                    return Ok(lt);
                }
                if lt.is_float() {
                    return Ok(lt);
                }
                Ok(lt)
            }
            BinaryOp::Eq | BinaryOp::Ne => {
                let none_and_maybe = matches!(
                    (&lt, &rt),
                    (Type::None, Type::Maybe(_)) | (Type::Maybe(_), Type::None)
                );
                if none_and_maybe {
                    return Ok(Type::Bool);
                }
                if lt == Type::None || rt == Type::None {
                    return err(span, "'none' can only be compared with a maybe value");
                }
                if let Some(maybe) = [&lt, &rt].into_iter().find(|t| matches!(t, Type::Maybe(_))) {
                    return err(
                        span,
                        format!(
                            "'==' compares a {} only with none; extract its value first, as in 'x {{ … }} == v', or compare what it holds with '~=', as in 'x ~= v'",
                            maybe
                        ),
                    );
                }
                // Equality reads without storing, so pointers/slices/texts across differing regions still compare.
                if lt.without_regions() != rt.without_regions() {
                    self.expect_type(&rt, &lt, r.span)?;
                }
                let symbol = if op == BinaryOp::Eq { "==" } else { "!=" };
                if !self.comparable(&lt) {
                    if let Some(untold) = self.untold_param(&lt).or_else(|| self.untold_param(&rt))
                    {
                        return err(span, untold);
                    }
                    let hint = match &lt {
                        Type::Param(_) => format!("; it {}", self.why_not(Need::Same, &lt)),
                        Type::Named(name, _) if self.kinds.contains_key(name) => {
                            "; a kind is compared by its variant and what that carries, and one of its variants carries a value that can fail, which is read first".to_string()
                        }
                        _ => extract_hint(&[&lt]),
                    };
                    return err(
                        span,
                        format!("'{}' can't compare values of type {}{}", symbol, lt, hint),
                    );
                }
                if self.by_place(&lt) {
                    let what = self.compared_by_place(symbol, &lt);
                    if !same_root(l, r) {
                        for side in [&*l, &*r] {
                            self.warn_chosen(side, &what);
                        }
                    }
                    for side in [&*l, &*r] {
                        if !self.is_place(side) {
                            return err(
                                side.span,
                                format!(
                                    "{}, as it does arrays, shapes, and tuples (and kinds carrying them), and this one is a value made here, with no place of its own; '~=' compares two values item by item",
                                    what
                                ),
                            );
                        }
                    }
                }
                Ok(Type::Bool)
            }
            BinaryOp::Similar | BinaryOp::NotSimilar => {
                let symbol = if op == BinaryOp::Similar { "~=" } else { "<>" };
                let none_and_maybe = matches!(
                    (&lt, &rt),
                    (Type::None, Type::Maybe(_)) | (Type::Maybe(_), Type::None)
                );
                if none_and_maybe {
                    return Ok(Type::Bool);
                }
                if lt == Type::None || rt == Type::None {
                    return err(span, "'none' can only be compared with a maybe value");
                }
                let (lt, rt) = self.widen_literal(l, r, lt, rt);
                let (lt, wrapped) = match (&lt, &rt) {
                    (Type::Maybe(inner), plain) | (plain, Type::Maybe(inner))
                        if !matches!(plain, Type::Maybe(_)) =>
                    {
                        let maybe = Type::Maybe(inner.clone());
                        if inner.without_regions() != plain.without_regions() {
                            return err(
                                span,
                                format!(
                                    "'{}' compares {} with {}, {}, or none, not with {}{}",
                                    symbol,
                                    maybe,
                                    inner,
                                    maybe,
                                    plain,
                                    extract_hint(&[plain])
                                ),
                            );
                        }
                        wrap(
                            if matches!(lt, Type::Maybe(_)) {
                                &mut *r
                            } else {
                                &mut *l
                            },
                            &maybe,
                        );
                        (maybe, true)
                    }
                    (Type::Maybe(inner), other @ Type::Maybe(_))
                    | (other @ Type::Maybe(_), Type::Maybe(inner))
                        if inner.without_regions() == other.without_regions() =>
                    {
                        let maybe = Type::Maybe(inner.clone());
                        let lt_holds_rt = matches!(&lt, Type::Maybe(held) if held.without_regions() == rt.without_regions());
                        wrap(if lt_holds_rt { &mut *r } else { &mut *l }, &maybe);
                        (maybe, true)
                    }
                    (Type::Maybe(inner), other @ Type::Maybe(theirs))
                        if inner.without_regions() != theirs.without_regions() =>
                    {
                        return err(
                            span,
                            format!(
                                "'{}' compares {} with {}, {}, or none, not with {}",
                                symbol, lt, inner, lt, other
                            ),
                        );
                    }
                    _ => (lt, false),
                };
                if !wrapped && lt.without_regions() != rt.without_regions() {
                    self.expect_type(&rt, &lt, r.span)?;
                }
                if let Some(part) = self.unsimilar_part(&lt) {
                    if let Some(untold) = self.untold_param(&lt).or_else(|| self.untold_param(&rt))
                    {
                        return err(span, untold);
                    }
                    let holds = if part == lt {
                        String::new()
                    } else {
                        format!(", since it holds {}", part)
                    };
                    let hint = match &part {
                        Type::Param(_) => {
                            format!("; {} {}", part, self.why_not(Need::Similar, &part))
                        }
                        _ => extract_hint(&[&part]),
                    };
                    return err(
                        span,
                        format!(
                            "'{}' can't compare values of type {} item by item{}{}",
                            symbol, lt, holds, hint
                        ),
                    );
                }
                Ok(Type::Bool)
            }
            BinaryOp::Lt | BinaryOp::Gt | BinaryOp::Le | BinaryOp::Ge => {
                let symbol = match op {
                    BinaryOp::Lt => "<",
                    BinaryOp::Gt => ">",
                    BinaryOp::Le => "<=",
                    _ => ">=",
                };
                if !self.allows(Need::Ordered, &lt) {
                    if let Some(untold) = self.untold_param(&lt).or_else(|| self.untold_param(&rt))
                    {
                        return err(span, untold);
                    }
                    if let Type::Param(_) = &lt {
                        return err(
                            span,
                            format!(
                                "'{}' compares numbers, chars, or text; {} {}",
                                symbol,
                                lt,
                                self.why_not(Need::Ordered, &lt)
                            ),
                        );
                    }
                    if matches!(lt, Type::Tuple(_)) {
                        return err(
                            span,
                            format!(
                                "'{}' compares numbers, chars, or text; a tuple is only compared with '==' and '!=', or item by item, as in 't.0 < u.0'",
                                symbol
                            ),
                        );
                    }
                    return err(
                        span,
                        format!(
                            "'{}' compares numbers, chars, or text, not {}{}",
                            symbol,
                            lt,
                            extract_hint(&[&lt])
                        ),
                    );
                }
                if !matches!((&lt, &rt), (Type::Text(_), Type::Text(_))) {
                    self.expect_type(&rt, &lt, r.span)?;
                }
                Ok(Type::Bool)
            }
            BinaryOp::And | BinaryOp::Or => {
                self.expect_type(&lt, &Type::Bool, l.span)?;
                self.expect_type(&rt, &Type::Bool, r.span)?;
                Ok(Type::Bool)
            }
        }
    }

    fn field_type(&self, base: &Type, field: &str, span: Span) -> Result<Type> {
        if base.unknown()
            || self
                .owner_of(base)
                .is_some_and(|owner| self.broken.contains(&owner))
        {
            return Ok(Type::Unknown);
        }
        if field == TYPE_WORD {
            return err(
                span,
                format!(
                    "'type' is the type of the value ({} here), which never changes",
                    self.written_type(base)
                ),
            );
        }
        match base {
            Type::Chan(_) => match field {
                "len" | "cap" => Ok(Type::Int),
                _ => err(span, format!("channel has no field '{}'; write '.len' or '.cap'", field)),
            },
            Type::Param(param) => self.pattern_field(param, field, span),
            Type::Applied(applied) => {
                let Some(shape) = self.shapes.get(&applied.name) else {
                    return err(span, format!("type {} has no fields", base));
                };
                let Some(found) = shape.fields.iter().find(|f| f.name == field) else {
                    return err(
                        span,
                        format!(
                            "shape '{}' has no field '{}'",
                            unqualified(&applied.name),
                            field
                        ),
                    );
                };
                if found.private && module_of(&applied.name) != self.current_module {
                    return err(
                        span,
                        format!(
                            "'{}' is a private field of '{}', which only its own file can use",
                            field,
                            unqualified(&applied.name)
                        ),
                    );
                }
                let given: HashMap<&str, &Type> = shape
                    .types
                    .iter()
                    .map(|param| param.name.as_str())
                    .zip(&applied.types)
                    .collect();
                let ty = found
                    .ty
                    .map_params(&mut |name| given.get(name).map(|ty| (*ty).clone()));
                Ok(self.field_in(&ty, &applied.region))
            }
            Type::Named(name, region) => {
                let Some(shape) = self.shapes.get(name) else {
                    return err(
                        span,
                        format!(
                            "'{}' is a kind and has no fields; use match to read its values",
                            name
                        ),
                    );
                };
                for f in &shape.fields {
                    if f.name == field {
                        if f.private && module_of(name) != self.current_module {
                            return err(
                                span,
                                format!(
                                    "'{}' is a private field of '{}', which only its own file can use",
                                    field, name
                                ),
                            );
                        }
                        return Ok(self.field_in(&f.ty, region));
                    }
                }
                if shape.shared.iter().any(|member| member.field.name == field) {
                    return err(
                        span,
                        format!(
                            "'{0}' is a shared field of '{1}', one value for the whole program rather than part of each value, so it is read as '{1}.{0}'",
                            field, name
                        ),
                    );
                }
                err(span, format!("shape '{}' has no field '{}'", name, field))
            }
            Type::Tuple(items) if group_in_tuple(items).is_some() => match field.parse::<usize>() {
                Ok(n) => Ok(Type::Param(group_item(
                    &group_in_tuple(items).unwrap_or_default(),
                    n,
                ))),
                Err(_) => err(
                    span,
                    format!(
                        "type {} has no field '{}'; a tuple's items are read by position, as in 't.0'",
                        base, field
                    ),
                ),
            },
            Type::Tuple(items) => match field.parse::<usize>() {
                Ok(n) => items.get(n).cloned().ok_or_else(|| {
                    Error::at(
                        span,
                        format!(
                            "this tuple has {} items, 't.0' to 't.{}', so it has no item {}",
                            items.len(),
                            items.len() - 1,
                            n
                        ),
                    )
                }),
                Err(_) => err(
                    span,
                    format!(
                        "type {} has no field '{}'; a tuple's items are read by position, as in 't.0'",
                        base, field
                    ),
                ),
            },
            _ if field.parse::<u64>().is_ok() => err(
                span,
                format!(
                    "'.{}' reads an item of a tuple, but this value is {}{}",
                    field,
                    base,
                    extract_hint(&[base])
                ),
            ),
            Type::Array(..) | Type::Slice(..) | Type::Map(..) | Type::Text(_) if field == LEN => {
                Ok(Type::Int)
            }
            Type::Map(..) if field == "keys" || field == "values" => {
                let one = if field == "keys" { "k" } else { "v" };
                err(
                    span,
                    format!(
                        "'m.{0}' alone is only gone through, as in 'each {1} in m.{0}'; 'm.{0} at r' makes a slice of them in a region",
                        field, one
                    ),
                )
            }
            Type::Map(..) => err(
                span,
                format!(
                    "type {} has no field '{}'; its number of keys is '.len', and its keys and values are '.keys at r' and '.values at r'",
                    base, field
                ),
            ),
            Type::Text(_) => err(
                span,
                format!(
                    "type {} has no field '{}'; how many bytes it has is '.len'",
                    base, field
                ),
            ),
            Type::Array(..) | Type::Slice(..) => err(
                span,
                format!(
                    "type {} has no field '{}'; its number of items is '.len'",
                    base, field
                ),
            ),
            Type::Ptr(..) => err(
                span,
                format!(
                    "type {} has no fields; dereference it first, as in 'p^.{}'",
                    base, field
                ),
            ),
            Type::Maybe(_) | Type::Or(..) => err(
                span,
                format!(
                    "type {} has no fields; extract its value first, as in 'when x is {{value}}'",
                    base
                ),
            ),
            _ => err(span, format!("type {} has no fields", base)),
        }
    }

    fn field_in(&self, ty: &Type, region: &Option<String>) -> Type {
        match region {
            Some(region) => self.in_region(ty, region),
            None => ty.clone(),
        }
    }

    fn region_of_value(&self, name: &str, region: String) -> Option<String> {
        if self.regional.contains(name) {
            return Some(region);
        }
        (self.takes_region.contains(name) && region != ANY_REGION).then_some(region)
    }

    fn check_fields_of_value(
        &mut self,
        values: &mut [&mut Expr],
        declared: &[Field],
        filled: Option<(usize, &str)>,
    ) -> Result<String> {
        // Separated helper keeps stack frames small for deeply nested struct/variant literals.
        let from = filled.map_or(usize::MAX, |(from, _)| from);
        for (at, value) in values.iter_mut().enumerate().take(declared.len()) {
            if let Some(field) = declared.get(at) {
                self.prepare_shortcut_lambda(value, &field.ty)?;
            }
            if at < from {
                self.check_expr(value)
            } else {
                self.check_in_module(value, filled)
            }?;
        }
        self.fields_region(values, declared)
    }

    fn fields_region(&mut self, values: &mut [&mut Expr], declared: &[Field]) -> Result<String> {
        const OWN: &str = "";
        let mut regions = HashMap::new();
        for (value, field) in values.iter().zip(declared) {
            let ty = value.ty()?.clone();
            self.match_regions(&self.in_region(&field.ty, OWN), &ty, &mut regions);
        }
        let region = regions
            .remove(OWN)
            .unwrap_or_else(|| ANY_REGION.to_string());
        for (value, field) in values.iter_mut().zip(declared) {
            self.coerce(value, &self.in_region(&field.ty, &region))?;
        }
        Ok(region)
    }

    /// Outlined (`#[inline(never)]`) to avoid bloating literal-checking stack frames.
    #[inline(never)]
    fn check_in_module(&mut self, value: &mut Expr, filled: Option<(usize, &str)>) -> Result<Type> {
        let Some((_, module)) = filled else {
            return self.check_expr(value);
        };
        let outer = std::mem::replace(&mut self.current_module, module.to_string());
        let checked = self.check_expr(value);
        self.current_module = outer;
        checked
    }

    fn owner_of(&self, ty: &Type) -> Option<String> {
        match self.unmade(ty) {
            Type::Named(name, _) => Some(name),
            Type::Applied(applied) => Some(applied.name.clone()),
            _ => None,
        }
    }

    fn declared_field(&self, owner: &str, field: &str) -> Option<&Field> {
        self.shapes
            .get(owner)?
            .fields
            .iter()
            .find(|declared| declared.name == field)
    }

    fn methods_of(&self, owner: &str) -> Vec<&str> {
        let prefix = method_name(owner, "");
        self.tasks
            .keys()
            .filter_map(|name| name.strip_prefix(prefix.as_str()))
            .collect()
    }

    fn no_method(&self, base: &Type, name: &str, span: Span) -> Error {
        if name == TYPE_WORD {
            return Error::at(
                span,
                "'type' is the type of a value, read without '(…)', as in 'x.type'",
            );
        }
        let instead = match name {
            "push" | "append" | "insert" => {
                "; a slice adds an item with 'add', as in 'xs.add(v)' or 'xs.add(i, v)'"
            }
            "pop" | "remove" | "delete" => {
                "; a slice takes an item out with 'del', as in 'xs.del(i)' or 'xs.del()'"
            }
            LEN if matches!(base, Type::Text(_)) => {
                "; how many bytes text has is read without '(…)', as in 't.len'"
            }
            LEN => "; how many items a slice holds is read without '(…)', as in 'xs.len'",
            _ => "",
        };
        if let Some(owner) = self
            .owner_of(base)
            .filter(|owner| self.shapes.contains_key(owner) || self.kinds.contains_key(owner))
        {
            let what = if self.kinds.contains_key(&owner) {
                "kind"
            } else {
                "shape"
            };
            let written = unqualified(&owner);
            if name == STR || name == JSON {
                return Error::at(
                    span,
                    format!(
                        "'{}' can't write {}; or give {} '{}' its own method '{}(r: region) -> text@r'",
                        name,
                        self.why_unwritable(base),
                        what,
                        written,
                        name
                    ),
                );
            }
            if self
                .shapes
                .get(&owner)
                .is_some_and(|shape| shape.fields.iter().any(|field| field.name == name))
            {
                return Error::at(
                    span,
                    format!(
                        "'{}' is a field of {} '{}', not a method, so it is read without '(…)'",
                        name, what, written
                    ),
                );
            }
            if self.methods_of(&owner).is_empty() {
                return Error::at(
                    span,
                    format!(
                        "{} '{}' has no methods; they are written inside it, below its {}",
                        what,
                        written,
                        if what == "kind" { "variants" } else { "fields" }
                    ),
                );
            }
            return Error::at(
                span,
                format!("{} '{}' has no method '{}'", what, written, name),
            );
        }
        if let Type::Param(param) = base
            && name != STR
            && name != JSON
        {
            let followed: Vec<&str> = self
                .type_param(param)
                .map(|declared| {
                    declared
                        .patterns
                        .iter()
                        .map(|followed| unqualified(&followed.name))
                        .collect()
                })
                .unwrap_or_default();
            if !followed.is_empty() {
                return Error::at(
                    span,
                    format!(
                        "type {} has no method '{}': none of the patterns it follows ({}) asks for one",
                        base,
                        name,
                        followed.join(", ")
                    ),
                );
            }
            let mut having: Vec<&str> = self
                .patterns
                .values()
                .filter(|pattern| pattern.method(name).is_some())
                .map(|pattern| unqualified(&pattern.name))
                .collect();
            having.sort_unstable();
            if let Some(pattern) = having.first() {
                return Error::at(
                    span,
                    format!(
                        "type {} has no methods; a type a declaration takes has the methods of the patterns it follows, and '{}' asks for '{}', as in '<{}: {}>'",
                        base, pattern, name, base, pattern
                    ),
                );
            }
        }
        match base {
            Type::Param(_) if name == STR => Error::at(
                span,
                format!(
                    "'str' turns a value into text, and {} {}",
                    base,
                    self.why_not(Need::Shown, base)
                ),
            ),
            Type::Param(_) if name == JSON => Error::at(
                span,
                format!(
                    "'json' turns a value into JSON text, and {} {}",
                    base,
                    self.why_not(Need::Shown, base)
                ),
            ),
            _ if name == STR => Error::at(
                span,
                format!("'str' can't write {}", self.why_unwritable(base)),
            ),
            _ if name == JSON => Error::at(
                span,
                format!("'json' can't write {}", self.why_unwritable(base)),
            ),
            Type::Ptr(..) => Error::at(
                span,
                format!(
                    "type {} has no methods; call it on the value it points to, as in 'p^.{}(…)'",
                    base, name
                ),
            ),
            Type::Maybe(_) | Type::Or(..) => Error::at(
                span,
                format!(
                    "type {} has no methods; extract its value first, as in 'when x is {{value}}'",
                    base
                ),
            ),
            _ => Error::at(span, format!("type {} has no methods{}", base, instead)),
        }
    }

    /// Checks `value.name(...)` and rewrites it to a direct task call, re-checking the receiver as first argument.
    fn check_method_call(&mut self, expr: &mut Expr) -> Result<()> {
        let span = expr.span;
        let ExprKind::MethodCall { value, name, .. } = &mut expr.kind else {
            return Ok(());
        };
        let name = name.clone();
        let copies = self.unsettled_copies.len();
        let untold = self.unsettled_types.len();
        let found = match value.kind {
            ExprKind::Ref(_) if name != STR => {
                return err(
                    value.span,
                    format!(
                        "an address, '&x', is only shown, turned into text with 'str', or compared with '=='; it has no '{}'",
                        name
                    ),
                );
            }
            ExprKind::Ref(_) => self.check_address(value),
            _ => {
                self.reaching = matches!(value.kind, ExprKind::Var(_) | ExprKind::Field(..));
                let found = self.check_expr(value);
                self.reaching = false;
                found
            }
        };
        self.unsettled_copies.truncate(copies);
        self.unsettled_types.truncate(untold);
        let ty = found?;
        if untold_kind(&ty)
            && let Some(error) = self.untold_kind_error(value.span)
        {
            return Err(error);
        }
        if ty.unknown() {
            return Ok(());
        }
        if name == STR && matches!(&expr.kind, ExprKind::MethodCall { args, .. } if args.is_empty())
        {
            let region = self.region_or_default(None, span, || STR_NEEDS_REGION.to_string())?;
            if let ExprKind::MethodCall { args, .. } = &mut expr.kind {
                args.push(Expr::new(ExprKind::Var(region), span));
            }
        }
        if name == JSON && matches!(&expr.kind, ExprKind::MethodCall { args, .. } if args.is_empty())
        {
            let region = self.region_or_default(None, span, || JSON_NEEDS_REGION.to_string())?;
            if let ExprKind::MethodCall { args, .. } = &mut expr.kind {
                args.push(Expr::new(ExprKind::Var(region), span));
            }
        }
        if name == STR && self.has_builtin_str(&ty) {
            if let ExprKind::MethodCall { args, .. } = &mut expr.kind
                && let Some(at) = region_after(args)
            {
                if args.len() > 1 {
                    return err(
                        at,
                        "'str' is given its region in the parentheses already, so this is a second one; name it once",
                    );
                }
                if let Some(arg) = args.last_mut()
                    && let ExprKind::RegionAfter(region) = &mut arg.kind
                {
                    arg.kind = ExprKind::Var(std::mem::take(region));
                }
            }
            return self.builtin_str(expr);
        }
        if name == JSON && self.has_builtin_json(&ty) {
            if let ExprKind::MethodCall { args, .. } = &mut expr.kind
                && let Some(at) = region_after(args)
            {
                if args.len() > 1 {
                    return err(
                        at,
                        "'json' is given its region in the parentheses already, so this is a second one; name it once",
                    );
                }
                if let Some(arg) = args.last_mut()
                    && let ExprKind::RegionAfter(region) = &mut arg.kind
                {
                    arg.kind = ExprKind::Var(std::mem::take(region));
                }
            }
            return self.builtin_json(expr);
        }
        if let Type::Map(..) = ty
            && let Some(op) = MapOp::from_word(&name)
        {
            if op != MapOp::Has {
                return err(
                    span,
                    format!(
                        "'{0}' is written without parentheses, with the region its slice goes in after it, as in 'm.{0} at r'",
                        name
                    ),
                );
            }
            let taken = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
            let ExprKind::MethodCall {
                value, mut args, ..
            } = taken
            else {
                return Err(Error::internal_at(
                    span,
                    "a method call that is no longer one",
                ));
            };
            if args.len() != 1 {
                return err(
                    span,
                    format!(
                        "'has' takes the key to look for, as in 'm.has(k)', got {}",
                        count(args.len(), "argument")
                    ),
                );
            }
            let key = Box::new(args.remove(0));
            expr.kind = ExprKind::MapOp {
                map: value,
                op,
                key: Some(key),
                region: None,
                region_span: span,
            };
            return Ok(());
        }
        if name == AT && matches!(ty, Type::Text(_)) {
            let taken = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
            let ExprKind::MethodCall {
                value, mut args, ..
            } = taken
            else {
                return Err(Error::internal_at(
                    span,
                    "a method call that is no longer one",
                ));
            };
            if args.len() != 1 {
                return err(
                    span,
                    format!(
                        "'at' takes the index of one byte, as in 't.at(i)', got {}",
                        count(args.len(), "argument")
                    ),
                );
            }
            expr.kind = ExprKind::Lookup(value, Box::new(args.remove(0)));
            return Ok(());
        }
        if matches!(ty, Type::Chan(_)) && matches!(name.as_str(), "send" | "recv" | "try_recv" | "close") {
            let taken = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
            let ExprKind::MethodCall { value, mut args, .. } = taken else {
                return Err(Error::internal_at(span, "a method call that is no longer one"));
            };
            args.insert(0, *value);
            expr.kind = ExprKind::Call {
                name,
                types: Vec::new(),
                args,
            };
            return Ok(());
        }
        if let Type::Param(param) = &ty
            && let Some(pattern) = self.pattern_with_method(param, &name, span)?
        {
            let written = format!("{}{}{}", unqualified(&pattern), MODULE_SEPARATOR, name);
            let takes = self
                .patterns
                .get(&pattern)
                .and_then(|def| def.method(&name))
                .map_or(0, |method| method.params.len().saturating_sub(1));
            let given = match &expr.kind {
                ExprKind::MethodCall { args, .. } => args.len(),
                _ => 0,
            };
            if given != takes {
                return err(
                    span,
                    format!(
                        "method '{}' expects {}, got {}",
                        written,
                        count(takes, "argument"),
                        given
                    ),
                );
            }
            let alters = self
                .patterns
                .get(&pattern)
                .and_then(|def| def.method(&name))
                .and_then(|method| method.owner.as_ref())
                .is_some_and(|owner| owner.alters);
            if alters {
                let ExprKind::MethodCall { value, .. } = &expr.kind else {
                    return Ok(());
                };
                self.altered_place(value, &written)?;
                self.hand_written(value, Some(&written));
            }
            let taken = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
            let ExprKind::MethodCall { value, args, .. } = taken else {
                return Err(Error::internal_at(
                    span,
                    "a method call that is no longer one",
                ));
            };
            let mut all = Vec::with_capacity(args.len() + 1);
            all.push(*value);
            all.extend(args);
            let bound: Vec<Type> = self
                .type_param(param)
                .and_then(|declared| {
                    declared
                        .patterns
                        .iter()
                        .find(|followed| followed.name == pattern)
                })
                .map(|followed| followed.types.clone())
                .unwrap_or_default();
            let types = match bound.is_empty() {
                true => Vec::new(),
                false => std::iter::once(Type::Param(param.clone()))
                    .chain(bound)
                    .map(|ty| (ty, span))
                    .collect(),
            };
            expr.kind = ExprKind::Call {
                name: pattern_call(&pattern, &name),
                types,
                args: all,
            };
            return Ok(());
        }
        let method = self
            .owner_of(&ty)
            .is_some_and(|owner| self.tasks.contains_key(&method_name(&owner, &name)));
        if !method
            && let Ok(field) = self.field_type(&ty, &name, span)
            && (is_callable(&field) || matches!(&field, Type::Maybe(inner) if is_callable(inner)))
        {
            let taken = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
            let ExprKind::MethodCall { value, args, .. } = taken else {
                return Err(Error::internal_at(
                    span,
                    "a method call that is no longer one",
                ));
            };
            let callee = Expr::new(ExprKind::Field(value, name), span);
            expr.kind = ExprKind::Invoke {
                callee: Box::new(callee),
                args,
            };
            return Ok(());
        }
        // Slices gain `Iterator` chain methods via `SliceIter` when `std/collections` is included.
        if matches!(ty, Type::Slice(..)) {
            const CHAIN: &[&str] = &[
                "map",
                "filter",
                "take",
                "skip",
                "zip",
                "enumerate",
                "collect",
                "fold",
                "find",
                "all",
                "any",
            ];
            let included = self.modules.get(&self.current_module).is_some_and(|scope| {
                scope
                    .includes
                    .iter()
                    .any(|include| include.id == "std/collections")
            });
            let members = match included {
                true => self
                    .patterns
                    .get("std/collections.Iterator")
                    .map(|pattern| {
                        pattern
                            .methods
                            .iter()
                            .filter_map(|method| {
                                method.owner.as_ref().map(|owner| owner.name.clone())
                            })
                            .collect::<Vec<_>>()
                    }),
                false => None,
            };
            if members
                .as_ref()
                .is_some_and(|members| members.contains(&name))
            {
                let taken = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
                let ExprKind::MethodCall {
                    value, name, args, ..
                } = taken
                else {
                    return Err(Error::internal_at(
                        span,
                        "a method call that is no longer one",
                    ));
                };
                let at = value.span;
                let iter = Expr::new(
                    ExprKind::StructInit {
                        name: "std/collections.SliceIter".to_string(),
                        types: Vec::new(),
                        fields: vec![
                            FieldInit {
                                name: "items".to_string(),
                                span: at,
                                value: *value,
                                filled: false,
                            },
                            FieldInit {
                                name: "place".to_string(),
                                span: at,
                                value: Expr::new(ExprKind::IntLit(0), at),
                                filled: false,
                            },
                        ],
                    },
                    at,
                );
                expr.kind = ExprKind::MethodCall {
                    value: Box::new(iter),
                    name,
                    args,
                    dotted: None,
                };
                return self.check_method_call(expr);
            }
            if members.is_none() && CHAIN.contains(&name.as_str()) {
                return err(
                    span,
                    format!(
                        "type {} has no method '{}'; a slice has the chain members of std/collections in a file that includes it — the makers map, filter, take, skip, zip, enumerate and the consumers collect, fold, find, all, any; write 'include std/collections'",
                        ty, name
                    ),
                );
            }
        }
        let owner = self
            .owner_of(&ty)
            .ok_or_else(|| self.no_method(&ty, &name, span))?;
        let full = method_name(&owner, &name);
        let info = self
            .tasks
            .get(&full)
            .filter(|_| self.sees(&full))
            .cloned()
            .ok_or_else(|| self.no_method(&ty, &name, span))?;
        let written = format!("{}{}{}", unqualified(&owner), MODULE_SEPARATOR, name);
        if info.owner.as_ref().is_some_and(|owner| owner.shared) {
            return err(
                span,
                format!(
                    "'{0}' is a shared method, called on '{1}' itself, not on a value of it: write '{1}.{2}(…)'",
                    written,
                    unqualified(&owner),
                    name
                ),
            );
        }
        if self.private.contains(&full) && module_of(&owner) != self.current_module {
            return err(
                span,
                format!(
                    "'{}' is a private method of '{}', which only its own file can use",
                    name,
                    unqualified(&owner)
                ),
            );
        }
        if let ExprKind::MethodCall { args, .. } = &mut expr.kind {
            self.settle_call_region(
                span,
                &format!("method '{}'", written),
                args,
                info.params.get(1..).unwrap_or_default(),
            )?;
        }
        let given = match &expr.kind {
            ExprKind::MethodCall { args, .. } => args.len(),
            _ => 0,
        };
        let needed = self
            .param_defaults
            .get(&full)
            .and_then(|defaults| defaults.iter().position(Option::is_some))
            .unwrap_or(info.params.len());
        if given + 1 > info.params.len() || given + 1 < needed {
            return err(
                span,
                format!(
                    "method '{}' expects {}, got {}",
                    written,
                    self.expected_args(&full, info.params.len(), 1),
                    given
                ),
            );
        }
        if info.owner.as_ref().is_some_and(|owner| owner.alters) {
            let ExprKind::MethodCall { value, .. } = &expr.kind else {
                return Ok(());
            };
            self.altered_place(value, &written)?;
            self.hand_written(value, Some(&written));
        }
        let taken = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
        let ExprKind::MethodCall { value, args, .. } = taken else {
            return Err(Error::internal_at(
                span,
                "a method call that is no longer one",
            ));
        };
        let mut all = Vec::with_capacity(args.len() + 1);
        all.push(*value);
        all.extend(args);
        expr.kind = ExprKind::Call {
            name: full,
            types: Vec::new(),
            args: all,
        };
        Ok(())
    }

    fn has_builtin_str(&self, ty: &Type) -> bool {
        !self.has_own_str(ty) && self.writable(ty)
    }

    fn builtin_str(&mut self, expr: &mut Expr) -> Result<()> {
        let span = expr.span;
        let taken = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
        let ExprKind::MethodCall { value, args, .. } = taken else {
            return Err(Error::internal_at(
                span,
                "a 'str' that is no longer a method call",
            ));
        };
        let region = match <[Expr; 1]>::try_from(args) {
            Ok(
                [
                    Expr {
                        kind: ExprKind::Var(region),
                        span: region_span,
                        ..
                    },
                ],
            ) => (region, region_span),
            Ok([other]) => {
                return err(
                    other.span,
                    "'str' takes the region the text goes in, as in 'x.str(r)' or 'x.str() at r'",
                );
            }
            Err(args) => {
                return err(
                    span,
                    format!(
                        "'str' takes the region the text goes in, as in 'x.str(r)' or 'x.str() at r', got {}",
                        count(args.len(), "argument")
                    ),
                );
            }
        };
        expr.kind = ExprKind::ToText {
            value,
            region: region.0,
            region_span: region.1,
        };
        Ok(())
    }

    fn check_to_text(&mut self, value: &mut Expr, region: &str, region_span: Span) -> Result<Type> {
        let ty = match value.kind {
            ExprKind::Ref(_) => self.check_address(value)?,
            _ => self.check_expr(value)?,
        };
        self.note_written_strs(&ty, value.span);
        self.visible_region(region, region_span, true)?;
        Ok(Type::Text(Some(region.to_string())))
    }

    /// Refuses JSON for a value holding what JSON has no form for: a pointer (what it points
    /// to may point back), a task, or a lambda.
    fn json_writes(&self, ty: &Type, span: Span) -> Result<()> {
        let Some(part) = self.unjsonable_in(ty, &mut Vec::new()) else {
            return Ok(());
        };
        let what = match part {
            Type::Ptr(..) => "a pointer, since what one points to may point back",
            Type::Task(_) => "a task",
            _ => "a lambda",
        };
        if part == *ty {
            return err(span, format!("'json' can't write {}: JSON has no form for {}", ty, what));
        }
        err(
            span,
            format!(
                "'json' can't write {}, since it holds {}: JSON has no form for {}; give the shape holding it its own method 'json(r: region) -> text@r'",
                ty, part, what
            ),
        )
    }

    fn unjsonable_in(&self, ty: &Type, seen: &mut Vec<String>) -> Option<Type> {
        match ty {
            Type::Ptr(..) | Type::Task(_) | Type::Closure(_) => Some(ty.clone()),
            Type::Maybe(inner) | Type::Array(inner, _) | Type::Slice(inner, _) => {
                self.unjsonable_in(inner, seen)
            }
            Type::Map(key, value, _) => self
                .unjsonable_in(key, seen)
                .or_else(|| self.unjsonable_in(value, seen)),
            Type::Tuple(items) => items.iter().find_map(|item| self.unjsonable_in(item, seen)),
            Type::Named(..) | Type::Applied(_) if self.has_own_json(ty) => None,
            Type::Named(..) | Type::Applied(_) => {
                let name = match ty {
                    Type::Applied(applied) => applied.name.clone(),
                    Type::Named(name, _) => name.clone(),
                    _ => return None,
                };
                if seen.contains(&name) {
                    return None;
                }
                let parts = self.written_parts(ty)?;
                seen.push(name);
                let found = parts.iter().find_map(|part| self.unjsonable_in(part, seen));
                seen.pop();
                found
            }
            _ => None,
        }
    }

    fn has_builtin_json(&self, ty: &Type) -> bool {
        !self.has_own_json(ty) && self.writable(ty)
    }

    fn has_own_json(&self, ty: &Type) -> bool {
        let Some(owner) = self.owner_of(ty) else {
            return false;
        };
        self.tasks.contains_key(&method_name(&owner, JSON))
    }

    fn builtin_json(&mut self, expr: &mut Expr) -> Result<()> {
        let span = expr.span;
        let taken = std::mem::replace(&mut expr.kind, ExprKind::NoneLit);
        let ExprKind::MethodCall { value, args, .. } = taken else {
            return Err(Error::internal_at(
                span,
                "a 'json' that is no longer a method call",
            ));
        };
        let region = match <[Expr; 1]>::try_from(args) {
            Ok(
                [
                    Expr {
                        kind: ExprKind::Var(region),
                        span: region_span,
                        ..
                    },
                ],
            ) => (region, region_span),
            Ok([other]) => {
                return err(
                    other.span,
                    "'json' takes the region the text goes in, as in 'x.json(r)' or 'x.json() at r'",
                );
            }
            Err(args) => {
                return err(
                    span,
                    format!(
                        "'json' takes the region the text goes in, as in 'x.json(r)' or 'x.json() at r', got {}",
                        count(args.len(), "argument")
                    ),
                );
            }
        };
        expr.kind = ExprKind::ToJson {
            value,
            region: region.0,
            region_span: region.1,
        };
        Ok(())
    }

    fn check_to_json(&mut self, value: &mut Expr, region: &str, region_span: Span) -> Result<Type> {
        let ty = match value.kind {
            ExprKind::Ref(_) => self.check_address(value)?,
            _ => self.check_expr(value)?,
        };
        self.json_writes(&ty, value.span)?;
        self.note_written_strs(&ty, value.span);
        self.visible_region(region, region_span, true)?;
        Ok(Type::Text(Some(region.to_string())))
    }

    fn check_number_cast(
        &mut self,
        into: &Type,
        types: &[TypeArg],
        args: &mut [Expr],
        span: Span,
    ) -> Result<Type> {
        if let Some((_, at)) = types.first() {
            return err(
                *at,
                format!(
                    "'{0}' takes no types, only the value to turn into {0}, as in '{0}(x)'",
                    into
                ),
            );
        }
        let takes = match into {
            Type::Int => "'int' takes an int, a unit, a char, a float, a bool, or text".to_string(),
            Type::Unit => {
                "'unit' takes an int, a unit, a char, a float, a bool, or text".to_string()
            }
            Type::Char => {
                "'char' takes an int, a unit, or a char, the code of the character".to_string()
            }
            _ if into.is_float() => format!("'{}' takes an int, a unit, a float, or text", into),
            _ => format!(
                "'{}' takes an int, a unit, a char, a float, a bool, or text",
                into
            ),
        };
        let [value] = args else {
            return err(
                span,
                format!(
                    "'{0}(…)' turns one value into {0}, as in '{0}(x)', got {1}",
                    into,
                    count(args.len(), "value")
                ),
            );
        };
        let ty = self.check_expr(value)?;
        let fits = match into {
            Type::Char => ty.is_integer() || ty == Type::Char,
            _ if into.is_float() => ty.is_numeric() && ty != Type::Bool,
            _ => ty.is_numeric() || ty == Type::Bool || ty == Type::Char,
        };
        if (into.is_integer() || *into == Type::Char)
            && let Some(n) = constant_int(value)
        {
            fits_type(i128::from(n), into, value.span)?;
        }
        if fits || ty.unknown() {
            return Ok(into.clone());
        }
        if matches!(ty, Type::Text(_)) && *into != Type::Char {
            return Ok(Type::Or(
                Box::new(into.clone()),
                Box::new(Type::Named(PARSE_ERROR.to_string(), None)),
            ));
        }
        let hint = match &ty {
            Type::Text(_) if *into == Type::Char => {
                "; a byte of text is read with 't[i]', or 't.at(i)', which gives none out of range"
                    .to_string()
            }
            Type::Bool => format!(
                "; a bool becomes a number with 'int', as in '{}(int(ok))'",
                into
            ),
            Type::Ptr(..) => format!(
                "; to turn the value it points to into a number, write '{}(p^)'",
                into
            ),
            Type::Maybe(_) | Type::Or(..) => extract_hint(&[&ty]),
            Type::Nothing => "; this has no value".to_string(),
            Type::Named(..) | Type::Applied(_) => {
                "; a shape or kind becomes a number only through a task that reads it".to_string()
            }
            Type::Param(_) => format!("; {} is any type here, and no word requires a number", ty),
            _ => String::new(),
        };
        err(
            value.span,
            format!("{}, but this value is {}{}", takes, ty, hint),
        )
    }

    fn altered_place(&self, value: &Expr, method: &str) -> Result<()> {
        // Temporaries produced on the spot (`xs.map(f).collect(r)`) can be mutated safely.
        if matches!(
            value.kind,
            ExprKind::Call { .. }
                | ExprKind::MethodCall { .. }
                | ExprKind::Invoke { .. }
                | ExprKind::StructInit { .. }
        ) {
            return Ok(());
        }
        self.altered_part(value, method, &self.written_text(value))
    }

    fn altered_part(&self, value: &Expr, method: &str, written: &str) -> Result<()> {
        let refuse = |what: String| {
            err(
                value.span,
                format!(
                    "'{}' changes the value it is called on, so {}",
                    method, what
                ),
            )
        };
        match &value.kind {
            ExprKind::Var(name) => {
                let info = self.lookup_or_err(name, value.span)?;
                let has_contents = self.bind_has_contents(&info.ty);
                if info.mode.can_change_contents(has_contents) {
                    let kind_name = match &info.ty {
                        Type::Named(name, _) => Some(name.as_str()),
                        Type::Applied(applied) => Some(applied.name.as_str()),
                        _ => None,
                    };
                    if info.mode == Mode::Bind && kind_name.is_some_and(|name| self.kinds.contains_key(name)) {
                        return refuse("it needs a place that can be assigned as a whole, and a 'bind' name can't have that; an 'alters' method of a kind may replace the whole value".to_string());
                    }
                    return Ok(());
                }
                if name == THIS {
                    return Err(self.this_cannot_change(value.span, &format!("calling '{}'", method)));
                }
                if info.result {
                    return refuse(format!("it needs a place that can change, and '{}' is a result, which only '<-' sets", name));
                }
                if info.refers.is_some() {
                    return refuse(format!("it needs a place that can change, and '{0}' only reads the place it names; a reference that changes it is written 'flex& {0} = &…'", name));
                }
                if info.param && info.passing == Passing::FixedRef {
                    return refuse(format!(
                        "it needs a place that can change, and '{0}' is a 'fixed&' parameter, which only reads the caller's place; write 'flex& {0}: {1}' to change it",
                        name, info.ty
                    ));
                }
                if info.param {
                    return refuse(format!(
                        "it needs a place that can change, and '{0}' is a parameter, which never does; write 'flex {0}: {1}' to change the task's own copy, or 'flex& {0}: {1}' to change the caller's",
                        name,
                        info.ty
                    ));
                }
                if info.kept {
                    return refuse(format!("it needs a place that can change, and '{}' never does{}", name, self.param_hint(name, info)));
                }
                if info.mode == Mode::Bind {
                    return refuse(format!(
                        "it needs a place that can change, and '{}' is 'bind' of a type with no contents that can change, so it acts as 'fixed'",
                        name
                    ));
                }
                refuse(format!(
                    "it needs a place that can change, and '{}' never does (declared at {}:{}); a value declared with 'flex' can",
                    name, info.span.line, info.span.col
                ))
            }
            ExprKind::Field(base, field) => {
                if let Some(ty) = &base.ty {
                    if matches!(ty, Type::Tuple(_)) {
                        return refuse("it needs a place that can change, and a tuple's items never change; give the whole tuple a new value instead, as in 't = (1, 2)'".to_string());
                    }
                    self.read_only_field(ty, field, value.span)?;
                }
                self.altered_part(base, method, written)
            }
            ExprKind::Index(base, _) if matches!(base.ty, Some(Type::Slice(..) | Type::Map(..))) => self.written_through(base, written, Some(method)),
            ExprKind::Index(base, _) => self.altered_part(base, method, written),
            ExprKind::Deref(pointer) => self.written_through(pointer, written, Some(method)),
            ExprKind::Shared { shape, field } => self.changeable_shared(shape, field, value.span, &format!("'{}' changes the value it is called on, and ", method), false),
            _ => refuse("it needs a place that can change, such as a 'flex' variable, a field or item of one, or what a pointer points to, and not part of a value made here".to_string()),
        }
    }

    fn needs_alters(&self, span: Span, what: &str, owner: &Owner) -> Error {
        Error::at(
            span,
            format!(
                "{} changes the value this method is called on, so '{1}' goes before its name, as in '{1} {2}(…)'",
                what, ALTERS, owner.name
            ),
        )
    }

    fn this_cannot_change(&self, span: Span, what: &str) -> Error {
        match &self.current_method {
            Some(owner) if !owner.shared => self.needs_alters(span, what, owner),
            _ => Error::at(span, self.not_a_method(THIS)),
        }
    }

    fn cannot_allocate_in_this(&self, what_to_do: &str) -> String {
        format!(
            "'@{0}' is the region the value this method is called on lives in, which a method isn't given, so it can't allocate there, and a region it takes is another one, which the value can't point into; {1}",
            THIS_WORD, what_to_do
        )
    }

    /// Outlined (`#[inline(never)]`) because `infer_expr` recurses per nesting level.
    #[inline(never)]
    fn check_shared_use(&mut self, expr: &mut Expr) -> Result<Type> {
        let span = expr.span;
        let ExprKind::Shared { shape, field } = &expr.kind else {
            return Err(Error::internal_at(span, "a shared field without its name"));
        };
        let (shape, field) = (shape.clone(), field.clone());
        if self.broken.contains(&shape) {
            return Ok(Type::Unknown);
        }
        let task = method_name(&shape, &field);
        if let Some(owner) = self.tasks.get(&task).and_then(|info| info.owner.clone()) {
            let written = unqualified(&shape);
            if !owner.shared {
                let value = if self.kinds.contains_key(&shape) {
                    "k"
                } else {
                    "p"
                };
                return err(
                    span,
                    format!(
                        "'{0}' is a method of every value of '{1}', so it is called on a value, as in '{2}.{0}(…)'; only a shared method is a value, named on its type",
                        field, written, value
                    ),
                );
            }
            if self.private.contains(&task) && module_of(&shape) != self.current_module {
                return err(
                    span,
                    format!(
                        "'{}' is a private method of '{}', which only its own file can use",
                        field, written
                    ),
                );
            }
            expr.kind = ExprKind::TaskValue(task);
            return self.infer_expr(expr);
        }
        if self.kinds.contains_key(&shape) {
            if field == TYPE_WORD {
                return err(
                    span,
                    format!(
                        "'type' is read on a value, as in 'k.type', and '{}' is a kind, whose type is its name",
                        unqualified(&shape)
                    ),
                );
            }
            return err(
                span,
                format!(
                    "kind '{}' has no variant or shared method '{}'",
                    unqualified(&shape),
                    field
                ),
            );
        }
        let Some(def) = self.shapes.get(&shape) else {
            return Err(Error::internal_at(
                span,
                format!("shared field of unknown shape '{}'", shape),
            ));
        };
        let Some(index) = def
            .shared
            .iter()
            .position(|member| member.field.name == field)
        else {
            if def.fields.iter().any(|declared| declared.name == field) {
                return err(
                    span,
                    format!(
                        "'{0}' is a field of every value of '{1}', not a shared one, so it is read on a value, as in 'p.{0}'",
                        field, shape
                    ),
                );
            }
            if field == TYPE_WORD {
                return err(
                    span,
                    format!(
                        "'type' is read on a value, as in 'p.type', and '{}' is a shape, whose type is its name",
                        unqualified(&shape)
                    ),
                );
            }
            if self.variants.values().any(|info| info.variant.tag == field) {
                return err(
                    span,
                    format!(
                        "'{}' is a shape, not a kind, so it has no variant '{}'",
                        shape, field
                    ),
                );
            }
            return err(
                span,
                format!(
                    "shape '{}' has no shared field or shared method '{}'",
                    shape, field
                ),
            );
        };
        let Some(member) = def.shared.get(index).cloned() else {
            return Ok(Type::Unknown);
        };
        if member.field.private && module_of(&shape) != self.current_module {
            return err(
                span,
                format!(
                    "'{}' is a private shared field of '{}', which only its own file can use",
                    field, shape
                ),
            );
        }
        if let Some((within, above)) = self.in_shared.clone() {
            if within == shape && index >= above {
                let what = if index == above {
                    "its own".to_string()
                } else {
                    format!(
                        "'{}', declared below it at {}:{}",
                        shared_key(&shape, &field),
                        member.field.span.line,
                        member.field.span.col
                    )
                };
                return err(
                    span,
                    format!(
                        "a shared field's first value can name the shared fields above it in its shape, not {}",
                        what
                    ),
                );
            }
        } else if let Some(falls_back) = self.in_default.clone() {
            if member.changes() {
                return err(
                    span,
                    format!(
                        "the value {} falls back on is worked out before the program runs, and shared field '{}' can change, so it can't be named there; one that never changes can",
                        falls_back,
                        shared_key(&shape, &field)
                    ),
                );
            }
        } else {
            expr.ty = Some(member.field.ty.clone());
            return Ok(member.field.ty);
        }
        let value = self.shared_value(&shape, index, span)?;
        let ty = value.ty.clone().unwrap_or(Type::Unknown);
        *expr = Expr { span, ..value };
        Ok(ty)
    }

    fn changeable_shared(
        &self,
        shape: &str,
        field: &str,
        span: Span,
        lead: &str,
        whole: bool,
    ) -> Result<()> {
        let Some(member) = self
            .shapes
            .get(shape)
            .and_then(|def| def.shared.iter().find(|member| member.field.name == field))
        else {
            if self
                .tasks
                .get(&method_name(shape, field))
                .is_some_and(|info| info.owner.is_some())
            {
                return err(
                    span,
                    format!(
                        "{}'{}.{}' is a method, whose value is the task itself, so it never changes",
                        lead,
                        unqualified(shape),
                        field
                    ),
                );
            }
            return Ok(());
        };
        let written = shared_key(shape, field);
        if !member.changes() {
            return err(
                span,
                format!(
                    "{}'{}' never changes (declared at {}:{}); a shared field that changes is 'shared flex {}', 'shared bind {}', or 'shared read {}', which only the methods of '{}' change",
                    lead,
                    written,
                    member.field.span.line,
                    member.field.span.col,
                    field,
                    field,
                    field,
                    shape
                ),
            );
        }
        let outside = self.current_shape.as_deref() != Some(shape);
        if whole {
            if member.flex {
                return Ok(());
            }
            if member.field.read && !outside {
                return Ok(());
            }
            if outside && member.field.read {
                return err(
                    span,
                    format!(
                        "{}'{}' is a read-only shared field, which only the methods of '{}' change",
                        lead, written, shape
                    ),
                );
            }
            return err(
                span,
                format!(
                    "{}'{}' is a 'shared bind' field, so its contents may change but it is never assigned as a whole; use 'shared flex {}' to assign it whole",
                    lead, written, field
                ),
            );
        }
        if member.can_change_outside() {
            return Ok(());
        }
        if member.field.read && !outside {
            return Ok(());
        }
        err(
            span,
            format!(
                "{}'{}' is a read-only shared field, which only the methods of '{}' change",
                lead, written, shape
            ),
        )
    }

    fn shared_value(&mut self, shape: &str, index: usize, span: Span) -> Result<Expr> {
        let Some(member) = self
            .shapes
            .get(shape)
            .and_then(|def| def.shared.get(index))
            .cloned()
        else {
            return Err(Error::internal_at(
                span,
                "a shared field that isn't declared",
            ));
        };
        let key = shared_key(shape, &member.field.name);
        let written = shared_key(shape, &member.field.name);
        match self.shared_values.get(&key) {
            Some(Some(value)) => return Ok(value.clone()),
            Some(None) => {
                return err(
                    span,
                    format!("the first value of '{}' has a mistake of its own", written),
                );
            }
            None => {}
        }
        if let Some(at) = self
            .shared_checking
            .iter()
            .position(|checking| *checking == key)
        {
            let mut circle: Vec<String> =
                self.shared_checking.get(at..).unwrap_or_default().to_vec();
            circle.push(key);
            return err(
                span,
                format!(
                    "the first values of shared fields name one another in a circle, {}, so none of them has one",
                    circle.join(" → ")
                ),
            );
        }
        let Some(mut value) = member.field.default.clone() else {
            return Err(Error::internal_at(
                span,
                "a shared field with no first value",
            ));
        };
        self.shared_checking.push(key.clone());
        let module = std::mem::replace(&mut self.current_module, module_of(shape).to_string());
        let outer_shared = self.in_shared.replace((shape.to_string(), index));
        let outer_default = self.in_default.take();
        let checked = self.check_first_value(&mut value, &member.field);
        self.in_default = outer_default;
        self.in_shared = outer_shared;
        self.current_module = module;
        self.shared_checking.pop();
        let kept = checked.map(|()| value);
        self.shared_values.insert(key, kept.as_ref().ok().cloned());
        kept
    }

    fn check_first_value(&mut self, value: &mut Expr, field: &Field) -> Result<()> {
        self.check_expr(value)?;
        if !constant_value(value) {
            return err(
                value.span,
                format!(
                    "the first value of shared field '{}' must be one the compiler works out without running the program: a number, text, 'true', 'false', 'none', a variant, a shared field above it, or a tuple, an array, or a literal of those",
                    field.name
                ),
            );
        }
        self.coerce(value, &field.ty)
    }

    fn check_global_region(&mut self, items: &mut [Item]) {
        let Some(Item::GlobalRegion(g)) = items.iter_mut().find(|i| matches!(i, Item::GlobalRegion(_))) else {
            return;
        };
        let cap = g.capacity;
        let span = g.span;
        self.globals.insert(
            "global".to_string(),
            VarInfo {
                ty: Type::Region,
                mode: Mode::Fixed,
                span,
                allocates: true,
                result: false,
                param: false,
                passing: Passing::Fixed,
                refers: None,
                kept: false,
                owners: Vec::new(),
                family: None,
                bind_reads: false,
            },
        );
        let mut total_bytes: usize = 0;
        self.push_scope();
        for stmt in &mut g.stmts {
            let StmtKind::Binding { names, init, mode, .. } = &mut stmt.kind else {
                continue;
            };
            let mode = *mode;
            let Some(first_bound) = names.first_mut() else {
                continue;
            };
            let name = first_bound.name.clone();
            let b_span = first_bound.span;
            let explicit_ty = first_bound.ty.clone();

            let Some(val) = init.first_mut() else {
                continue;
            };
            let val_ty = match self.check_expr(val) {
                Ok(t) => t,
                Err(e) => {
                    self.errors.push(e);
                    Type::Unknown
                }
            };
            let final_ty = if let Some(exp) = &explicit_ty {
                if let Err(e) = self.coerce(val, exp) {
                    self.errors.push(e);
                }
                exp.clone()
            } else {
                val_ty
            };
            first_bound.ty = Some(final_ty.clone());

            if matches!(final_ty, Type::Slice(..) | Type::Map(..)) {
                self.errors.push(Error::at(
                    b_span,
                    "a variable in 'region global' cannot hold a slice or map: they grow dynamically and can exhaust the fixed global segment; use a fixed array '[T#N]' or allocate in a task region instead",
                ));
            }
            if self.holds_file(&final_ty) {
                self.errors.push(Error::at(
                    b_span,
                    "a variable in 'region global' cannot hold a 'File', which the region it is opened in closes, and a global variable lives as long as the program",
                ));
            }
            if holds_pointers(&final_ty, &self.regional) {
                let regions = final_ty.regions();
                for r in regions {
                    if r != "global" && r != ANY_REGION {
                        self.errors.push(Error::at(
                            b_span,
                            format!(
                                "a variable in 'region global' cannot hold a pointer into region '{}': 'global' lives for the entire program, but region '{}' ends before it",
                                r, r
                            ),
                        ));
                    }
                }
            }

            let size = if mode == Mode::Bind {
                0
            } else {
                self.size_of(&final_ty)
            };
            total_bytes = total_bytes.saturating_add(size);

            let info = VarInfo {
                ty: final_ty,
                mode,
                span: b_span,
                allocates: false,
                result: false,
                param: false,
                passing: Passing::Fixed,
                refers: None,
                kept: false,
                owners: Vec::new(),
                family: None,
                bind_reads: false,
            };
            self.globals.insert(name.clone(), info.clone());
            if let Some(scope) = self.scopes.last_mut() {
                scope.names.insert(name, info);
            }
        }
        self.pop_scope();

        if (total_bytes as u64) > cap {
            self.errors.push(Error::at(
                span,
                format!(
                    "variables declared in 'region global' take {} bytes, which exceeds the region's size of {} bytes",
                    total_bytes, cap
                ),
            ));
        }
    }

    fn check_shared_fields(&mut self, items: &mut [Item]) {
        for item in items.iter_mut() {
            let Item::Shape(shape) = item else { continue };
            if self.broken.contains(&shape.name) {
                continue;
            }
            for index in 0..shape.shared.len() {
                let Some(member) = shape.shared.get(index) else {
                    continue;
                };
                let key = shared_key(&shape.name, &member.field.name);
                if !self.shared_values.contains_key(&key) {
                    let span = member
                        .field
                        .default
                        .as_ref()
                        .map_or(member.field.span, |value| value.span);
                    let checked = self.shared_value(&shape.name, index, span).map(|_| ());
                    self.keep_going(checked);
                }
                if let (Some(Some(value)), Some(member)) =
                    (self.shared_values.get(&key), shape.shared.get_mut(index))
                {
                    member.field.default = Some(value.clone());
                }
            }
        }
    }

    fn called_on_a_value(&self) -> bool {
        self.current_method
            .as_ref()
            .is_some_and(|owner| !owner.shared)
    }

    fn not_a_method(&self, written: &str) -> String {
        if self.in_shared.is_some() {
            return format!(
                "'{}' reads the value a method is called on, and a shared field belongs to no value",
                written
            );
        }
        if let Some(field) = &self.in_default {
            return format!(
                "'{}' reads the value a method is called on, and the value {} falls back on is worked out before there is one, so it reads {}",
                written,
                field,
                if field.starts_with("field") {
                    "no other field"
                } else {
                    "none of its fields"
                }
            );
        }
        let names = if written == THIS {
            "is the value a method is called on"
        } else {
            "names a member of the value a method is called on"
        };
        if self
            .current_lambda
            .as_ref()
            .is_some_and(|lambda| self.kept_lambdas.contains_key(lambda))
        {
            let field = written.trim_start_matches('.');
            let example = if written == THIS {
                "fixed value = .this".to_string()
            } else {
                format!("fixed {0} = .{0}", field)
            };
            return format!(
                "'{}' {}, which a lambda doesn't keep; keep a variable of it in the method first, as in '{}', and use that",
                written, names, example
            );
        }
        if self.current_lambda.is_some() {
            return format!(
                "'{}' {}, and a lambda takes nothing from the method around it; give the value as a parameter",
                written, names
            );
        }
        if let Some(owner) = self.current_method.as_ref().filter(|owner| owner.shared) {
            return format!(
                "'{}' {}, and '{}' is a shared method, called on its shape or kind rather than on a value; take the value as a parameter, or make '{}' a method of the value",
                written, names, owner.name, owner.name
            );
        }
        format!(
            "'{}' {}, and this is a task, which is called on no value",
            written, names
        )
    }

    fn check_call_args(
        &mut self,
        span: Span,
        task: &str,
        written: &mut Vec<TypeArg>,
        args: &mut [Expr],
        info: &TaskInfo,
    ) -> Result<Type> {
        let given = self.written_types(span, task, written, info)?;
        let regions = self
            .kept_call
            .take()
            .map(|region| (region.clone(), region))
            .into_iter()
            .collect();
        let mut found = Box::new(CallTypes {
            given,
            shown: HashMap::new(),
            regions,
            taken: HashMap::new(),
            untold: false,
        });
        // Argument checking and settling live in separate helpers to keep recursive call stack frames small.
        let mut info = Box::new(info.clone());
        self.check_args_of(task, args, &mut info, &mut found)?;
        self.settle_call_args(span, task, written, args, &info, *found)
    }

    fn note_group_taken(
        ty: &mut Type,
        actual: &Type,
        at: Span,
        found: &mut CallTypes,
    ) -> Result<()> {
        let (Type::Task(pattern), Type::Task(actual)) = (ty, actual) else {
            return Ok(());
        };
        if pattern.params.len() != actual.params.len() {
            return Ok(());
        }
        for (i, param) in pattern.params.iter().enumerate() {
            let (Type::Param(name), Some(how)) = (param, actual.taken.get(i)) else {
                continue;
            };
            if !name.contains(GROUP_ITEM) {
                continue;
            }
            match found.taken.get(name) {
                Some(before) if before != how => {
                    let item = name
                        .rsplit(GROUP_ITEM)
                        .next()
                        .and_then(|k| k.parse::<usize>().ok())
                        .map_or(0, |k| k + 1);
                    let way = |how: &Taken| match how {
                        Taken::Value => "as a value".to_string(),
                        Taken::Flex => "as a value it changes, 'flex'".to_string(),
                        Taken::Bind => "as a value it changes the contents of, 'bind'".to_string(),
                        Taken::Place(passing) => format!("as a place, '{}'", passing.word()),
                        Taken::Region(_) => "as a region".to_string(),
                    };
                    return err(
                        at,
                        format!(
                            "this task value takes value {} of the group {}, and another task value the call gives takes it {}, so the call can't give it to both; give task values taking it the same way",
                            item,
                            way(how),
                            way(before)
                        ),
                    );
                }
                Some(_) => {}
                None => {
                    found.taken.insert(name.clone(), how.clone());
                }
            }
            if let Some(slot) = pattern.taken.get_mut(i) {
                *slot = how.clone();
            }
        }
        Ok(())
    }

    fn group_place(
        &self,
        task: &str,
        arg: &Expr,
        param: &str,
        name: &str,
        found: &CallTypes,
    ) -> Result<Option<Passing>> {
        match found.taken.get(name) {
            Some(Taken::Place(passing)) => Ok(Some(*passing)),
            Some(Taken::Region(region)) => err(
                arg.span,
                format!(
                    "task '{0}' gives a task value its group's values, and that task value takes a region there, '@{1}', which a group never holds; '{0}' takes the region as a parameter of its own and names it in the task value's type, as in 'next: (@a, P...) -> R, a: region, args: P...'",
                    unqualified(task),
                    region
                ),
            ),
            None if found.untold && matches!(arg.kind, ExprKind::Ref(_)) => {
                Ok(Some(Passing::FixedRef))
            }
            _ if matches!(arg.kind, ExprKind::Ref(_)) => err(
                arg.span,
                format!(
                    "'{}' is a value of a group, which holds a place only where the call gives it to a task value taking one there, as in 'next: (P...) -> R' given a task taking 'flex& n: int'; give the value itself",
                    param
                ),
            ),
            _ => Ok(None),
        }
    }

    fn check_args_of(
        &mut self,
        task: &str,
        args: &mut [Expr],
        info: &mut TaskInfo,
        found: &mut CallTypes,
    ) -> Result<()> {
        let what = if info.owner.is_some() {
            "method"
        } else {
            "task"
        };
        let mut deferred = Vec::new();
        // Check group arguments after trailing callback args so `note_group_taken` knows which args need `&`.
        let group_item = |ty: &Type| matches!(ty, Type::Param(name) if name.contains(GROUP_ITEM));
        let first_item = info.params.iter().position(|(_, ty)| group_item(ty));
        let last_task = info.params.iter().rposition(
            |(_, ty)| matches!(ty, Type::Task(task) if task.params.iter().any(group_item)),
        );
        let reorder_groups = match (first_item, last_task) {
            (Some(first), Some(last)) => first < last,
            _ => false,
        };
        let has_shortcut = args.iter().any(|arg| self.is_shortcut_lambda(arg));
        let (params, passing_list, types) = (&mut info.params, &mut info.passing, &info.types);
        if reorder_groups || has_shortcut {
            let is_shortcut = |i: usize| args.get(i).is_some_and(|arg| self.is_shortcut_lambda(arg));
            let mut order: Vec<usize> =
                (0..args.len().min(params.len()).min(passing_list.len())).collect();
            order.sort_by_key(|&i| {
                (
                    reorder_groups && params.get(i).is_some_and(|(_, ty)| group_item(ty)),
                    is_shortcut(i),
                )
            });
            let shortcuts: Vec<bool> = (0..args.len()).map(is_shortcut).collect();
            for i in order {
                // Check array-vs-slice mismatches before trailing shortcut lambdas so error attribution points at the array.
                if shortcuts.get(i).copied().unwrap_or(false)
                    && let Some((at, got)) = (0..args.len())
                        .filter(|&j| !shortcuts.get(j).copied().unwrap_or(false))
                        .find_map(|j| {
                            let (_, want) = params.get(j)?;
                            let arg = args.get(j)?;
                            let got = arg.ty.as_ref()?;
                            matches!((got, want), (Type::Array(..), Type::Slice(..)))
                                .then(|| (arg.span, got.clone()))
                        })
                {
                    if let Some(lambda) = args
                        .get(i)
                        .and_then(|arg| self.shortcut_lambda_name(arg))
                        .map(str::to_string)
                    {
                        self.inferred_shortcut_lambdas.insert(lambda);
                    }
                    return err(
                        at,
                        format!(
                            "expected a slice, got {}; an array never becomes a slice: write the values as a slice, as in '[1, 2, ...] at r', or copy them into one, as in 'new [int](xs) at r'",
                            got
                        ),
                    );
                }
                let (Some(arg), Some((param, ty)), Some(passing)) = (
                    args.get_mut(i),
                    params.get_mut(i),
                    passing_list.get_mut(i),
                ) else {
                    continue;
                };
                self.check_single_arg(
                    task,
                    what,
                    i,
                    arg,
                    param,
                    ty,
                    passing,
                    types,
                    found,
                    &mut deferred,
                )?;
            }
        } else {
            let n = args.len().min(params.len()).min(passing_list.len());
            for i in 0..n {
                let (Some(arg), Some((param, ty)), Some(passing)) = (
                    args.get_mut(i),
                    params.get_mut(i),
                    passing_list.get_mut(i),
                ) else {
                    continue;
                };
                self.check_single_arg(
                    task,
                    what,
                    i,
                    arg,
                    param,
                    ty,
                    passing,
                    types,
                    found,
                    &mut deferred,
                )?;
            }
        }
        for (ty, actual) in deferred {
            let actual = in_callers_regions(&ty, &actual, &found.given);
            self.match_params(&ty, &actual, &mut found.given);
            self.match_params(&ty, &actual, &mut found.shown);
        }
        self.solve_bounds(&info.types, &mut found.given);
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    #[inline(never)]
    fn check_single_arg(
        &mut self,
        task: &str,
        what: &str,
        i: usize,
        arg: &mut Expr,
        param: &str,
        ty: &mut Type,
        passing: &mut Passing,
        types: &[TypeParam],
        found: &mut CallTypes,
        deferred: &mut Vec<(Type, Type)>,
    ) -> Result<()> {
        if let Type::Own(_) = ty
            && !matches!(arg.kind, ExprKind::Own(_))
        {
            return err(
                arg.span,
                format!(
                    "expected 'own' value for parameter '{}' of type '{}'; write 'own ...'",
                    param, ty
                ),
            );
        }
        if *ty != Type::Region {
            if let Type::Param(name) = &*ty
                && name.contains(GROUP_ITEM)
                && let Some(place) = self.group_place(task, arg, param, name, found)?
            {
                *passing = place;
            }
            let expected = in_copy(ty, &found.given);
            self.prepare_shortcut_lambda(arg, &expected)?;
            // A method is called on a held value where it is: its receiver only reads it, and a method that
            // changes it takes it as a place.
            self.reaching = param == THIS
                && matches!(arg.kind, ExprKind::Var(_) | ExprKind::Field(..));
            let callee_desc = format!("{} '{}'", what, task);
            let actual = if self.filled_default(task, i, arg) {
                let outer =
                    std::mem::replace(&mut self.current_module, module_of(task).to_string());
                let actual =
                    self.check_argument(arg, *passing, &callee_desc, param);
                self.current_module = outer;
                self.reaching = false;
                actual?
            } else {
                let actual = self.check_argument(arg, *passing, &callee_desc, param);
                self.reaching = false;
                actual?
            };
            let actual = self.coerce_slice_iter(arg, ty, actual, types)?;
            self.match_regions(ty, &actual, &mut found.regions);
            Self::note_group_taken(ty, &actual, arg.span, found)?;
            found.untold |= matches!(ty, Type::Task(_)) && actual.unknown();
            if let (Type::Task(_), Type::Task(task)) = (&*ty, &actual)
                && (task
                    .params
                    .iter()
                    .chain([&task.ret])
                    .any(|ty| !ty.regions().is_empty())
                    || task.taken.iter().any(|how| matches!(how, Taken::Region(_))))
            {
                deferred.push((ty.clone(), actual));
                return Ok(());
            }
            self.match_params(ty, &actual, &mut found.given);
            self.match_params(ty, &actual, &mut found.shown);
            self.solve_bounds(types, &mut found.given);
            return Ok(());
        }
        self.check_region_argument(task, arg, param, &mut found.regions)
    }

    #[inline(never)]
    fn coerce_slice_iter(
        &mut self,
        arg: &mut Expr,
        ty: &Type,
        actual: Type,
        types: &[TypeParam],
    ) -> Result<Type> {
        let (Type::Param(name), Type::Slice(..)) = (ty, &actual) else {
            return Ok(actual);
        };
        let bounded = types.iter().any(|type_param| {
            type_param.name == *name
                && type_param
                    .patterns
                    .iter()
                    .any(|followed| followed.name == "std/collections.Iterator")
        });
        if !bounded {
            return Ok(actual);
        }
        let at = arg.span;
        let taken = std::mem::replace(&mut arg.kind, ExprKind::NoneLit);
        let mut iter = Expr::new(
            ExprKind::StructInit {
                name: "std/collections.SliceIter".to_string(),
                types: Vec::new(),
                fields: vec![
                    FieldInit {
                        name: "items".to_string(),
                        span: at,
                        value: Expr::new(taken, at),
                        filled: false,
                    },
                    FieldInit {
                        name: "place".to_string(),
                        span: at,
                        value: Expr::new(ExprKind::IntLit(0), at),
                        filled: false,
                    },
                ],
            },
            at,
        );
        let iter_ty = self.check_expr(&mut iter)?;
        arg.kind = iter.kind;
        arg.ty = Some(iter_ty.clone());
        Ok(iter_ty)
    }

    fn check_bounds_allow(&self, types: &[TypeParam]) -> Result<()> {
        for followed in types.iter().flat_map(|param| &param.patterns) {
            let Some(pattern) = self.patterns.get(&followed.name) else {
                continue;
            };
            for (asked, given) in pattern.types.iter().zip(&followed.types) {
                self.check_need(
                    "pattern",
                    &followed.name,
                    asked,
                    &named_params(given, types),
                    followed.span,
                )?;
            }
        }
        Ok(())
    }

    fn solve_bounds(&self, types: &[TypeParam], given: &mut HashMap<String, Type>) {
        loop {
            let before = given.len();
            for param in types {
                let Some(ty) = given.get(&param.name).cloned() else {
                    continue;
                };
                for followed in param
                    .patterns
                    .iter()
                    .filter(|followed| !followed.types.is_empty())
                {
                    let Some(actual) = self.followed_by(&ty, &followed.name) else {
                        continue;
                    };
                    for (bound, actual) in followed.types.iter().zip(&actual) {
                        self.match_params(&named_params(bound, types), actual, given);
                    }
                }
            }
            if given.len() == before {
                return;
            }
        }
    }

    fn check_bound_types(
        &self,
        task: &str,
        types: &[TypeParam],
        param: &TypeParam,
        ty: &Type,
        given: &HashMap<String, Type>,
        at: Span,
    ) -> Result<()> {
        for followed in param
            .patterns
            .iter()
            .filter(|followed| !followed.types.is_empty())
        {
            let Some(actual) = self.followed_by(ty, &followed.name) else {
                continue;
            };
            let wanted: Vec<Type> = followed
                .types
                .iter()
                .map(|bound| in_copy(&named_params(bound, types), given))
                .collect();
            let fits = wanted.len() == actual.len()
                && wanted.iter().zip(&actual).all(|(wanted, actual)| {
                    wanted.unknown()
                        || actual.unknown()
                        || !wanted.params().is_empty()
                        || self.unmade(wanted).without_regions()
                            == self.unmade(actual).without_regions()
                });
            if !fits {
                let list = |types: &[Type]| {
                    types
                        .iter()
                        .map(Type::to_string)
                        .collect::<Vec<_>>()
                        .join(", ")
                };
                return err(
                    at,
                    format!(
                        "{} '{}' takes a type that follows '{}<{}>' as '{}', and {} follows '{}<{}>'",
                        if self.shapes.contains_key(task) {
                            "shape"
                        } else {
                            "task"
                        },
                        unqualified(task),
                        unqualified(&followed.name),
                        list(&wanted),
                        param.name,
                        ty,
                        unqualified(&followed.name),
                        list(&actual)
                    ),
                );
            }
        }
        Ok(())
    }

    fn check_region_argument(
        &mut self,
        task: &str,
        arg: &mut Expr,
        param: &str,
        regions: &mut HashMap<String, String>,
    ) -> Result<()> {
        let ExprKind::Var(region) = &arg.kind else {
            return err(
                arg.span,
                format!(
                    "task '{}' takes a region as '{}', such as a 'region r' declared before the call",
                    task, param
                ),
            );
        };
        self.visible_region(region, arg.span, true)?;
        if let Some(bound) = regions.get(param)
            && bound != region
        {
            return err(
                arg.span,
                format!("expected region '{}', got '{}'", bound, region),
            );
        }
        regions.insert(param.to_string(), region.clone());
        arg.ty = Some(Type::Region);
        Ok(())
    }

    fn settle_call_args(
        &mut self,
        span: Span,
        task: &str,
        written: &mut Vec<TypeArg>,
        args: &mut [Expr],
        info: &TaskInfo,
        found: CallTypes,
    ) -> Result<Type> {
        let CallTypes {
            mut given,
            shown,
            regions,
            taken,
            untold,
        } = found;
        let params = &info.params;
        let ret = &info.ret;
        let places: Vec<Span> = info
            .types
            .iter()
            .enumerate()
            .map(|(i, _)| written.get(i).map_or(span, |(_, at)| *at))
            .collect();
        let what = if info.owner.is_some() {
            "method"
        } else {
            "task"
        };
        for ((param, at), (ty, _)) in info.types.iter().zip(&places).zip(written.iter()) {
            if let Some(held) = shown.get(&param.name)
                && held.without_regions() == ty.without_regions()
                && !fits_regions(held, ty)
            {
                return err(
                    *at,
                    format!(
                        "task '{0}' is given {1} as '{2}', but its argument holds {3}; a written type names its regions, so write '{0}<{3}>(…)'",
                        task, ty, param.name, held
                    ),
                );
            }
        }
        for (param, at) in info.types.iter().zip(&places) {
            if let Some(ty) = given.get(&param.name) {
                let held = |ty: &Type| held_value(ty, &self.held_types) || holds_held(ty, &self.held_types);
                if held(ty)
                    || group_items(&given, &param.name)
                        .is_some_and(|(types, _)| types.iter().any(held))
                {
                    return err(
                        *at,
                        format!(
                            "task '{}' takes '{}' as a type, and is given {} for it, which changes what it keeps and is never copied, as its body may copy a value of that type; give it a '[@r]' lambda, or a task taking it as 'flex& f: {}'",
                            unqualified(task),
                            param.name,
                            if held_lambda(ty) {
                                "a '[flex @r]' lambda".to_string()
                            } else {
                                format!("'{}', which holds a '[flex @r]' lambda", ty)
                            },
                            ty
                        ),
                    );
                }
                self.check_need("task", task, param, ty, *at)?;
                self.check_bound_types(task, &info.types, param, ty, &given, *at)?;
            }
        }
        for (param, at) in info.types.iter().zip(&places) {
            if let Some(ty) = given.get(&param.name)
                && ty.regions().contains(&OWN_REGION)
            {
                return err(*at, own_region_type(what, task, &param.name, ty));
            }
        }
        if !info.types.is_empty() || self.default_copies.contains(task) {
            self.check_kept_regions(span, task, info, &regions, &given)?;
        }
        let lasting_this = self.default_copies.contains(task)
            && !regions.contains_key(THIS_WORD)
            && args.first().and_then(|arg| arg.ty.as_ref()).is_some_and(
                |ty| matches!(ty, Type::Named(name, None) if self.takes_region.contains(name)),
            );
        let lasting = |ty: &Type| match lasting_this {
            true => ty.map_regions(&mut |region| (region != THIS_WORD).then(|| region.to_string())),
            false => ty.clone(),
        };
        for ((arg, (param, ty)), passing) in args.iter_mut().zip(params).zip(&info.passing) {
            if *ty == Type::Region {
                continue;
            }
            let expected = self.settled_type(&lasting(ty), &regions, &given, span)?;
            let actual = arg.ty()?.clone();
            // `flex&`/`fixed&` places require exact types without implicit wrapping or promotion.
            if passing.is_ref() {
                // Regionless slots accept only program-lifetime text unless a concrete region is bound.
                let lasting = expected
                    .map_regions(&mut |region| (region != ANY_REGION).then(|| region.to_string()));
                if actual != expected
                    && actual != lasting
                    && !actual.unknown()
                    && !expected.unknown()
                {
                    let reads = *passing == Passing::FixedRef;
                    if actual.without_regions() == expected.without_regions() && !reads {
                        return err(
                            arg.span,
                            format!(
                                "expected type {0}, got {1}; the {2} may write a {0} in the place given as '{3}', which a place of type {1} can't hold",
                                expected, actual, what, param
                            ),
                        );
                    }
                    let does = if reads {
                        "reads where it is"
                    } else {
                        "changes"
                    };
                    return err(
                        arg.span,
                        format!(
                            "expected type {}, got {}; '{}' is given the place itself, which the {} {}, so the place is of exactly its type",
                            expected, actual, param, what, does
                        ),
                    );
                }
                continue;
            }
            let same_but_region = [Some(&expected), expected.extracted()]
                .into_iter()
                .flatten()
                .any(|e| actual.without_regions() == e.without_regions());
            match self.coerce(arg, &expected) {
                Err(_) if same_but_region && expected.regions().is_empty() => {
                    let example = expected.map_regions_of_names(&mut |_| Some("r".to_string()));
                    return err(
                        arg.span,
                        format!(
                            "expected type {}, got {}; {} '{}' takes text that lasts as long as the program here, as a literal does; to take text of any region, its parameter can name one, as in '{}: {}'",
                            expected, actual, what, task, param, example
                        ),
                    );
                }
                Err(_)
                    if same_but_region
                        && info.owner.is_some()
                        && ty.regions().contains(&THIS_WORD) =>
                {
                    return err(
                        arg.span,
                        format!(
                            "expected type {}, got {}; method '{}' takes '{}' in '@{}', the region the value it is called on lives in, so it must be in that region too",
                            expected, actual, task, param, THIS_WORD
                        ),
                    );
                }
                Err(_) if same_but_region && !expected.regions().contains(&ANY_REGION) => {
                    return err(
                        arg.span,
                        format!(
                            "expected type {}, got {}; {} '{}' names one region for this and another argument, so they must be in the same region",
                            expected, actual, what, task
                        ),
                    );
                }
                result => result?,
            }
        }
        self.check_aliasing(args, info)?;
        for ((arg, passing), (param, _)) in args.iter().zip(&info.passing).zip(&info.params) {
            match (passing, &arg.kind) {
                (Passing::Flex | Passing::Bind, _) => self.hand(
                    arg,
                    HandedTo::Param {
                        task: task.to_string(),
                        param: param.clone(),
                    },
                ),
                (Passing::FlexRef | Passing::BindRef, ExprKind::Ref(place)) => {
                    self.hand_written(place, None)
                }
                _ => {}
            }
        }
        let sent = self.settled_type(&lasting(ret), &regions, &given, span)?;
        for param in info.types.iter().filter(|param| param.group) {
            given
                .entry(param.name.clone())
                .or_insert_with(|| Type::Tuple(Vec::new()));
        }
        let missing: Vec<&TypeParam> = info
            .types
            .iter()
            .filter(|param| !given.contains_key(&param.name))
            .collect();
        if untold && !missing.is_empty() {
            return Ok(Type::Unknown);
        }
        let shown = sent.params();
        if let Some(param) = missing
            .iter()
            .find(|param| !shown.contains(&param.name.as_str()))
        {
            return err(span, self.untold_type(task, &param.name));
        }
        if let Some(param) = missing.first() {
            self.unsettled_types
                .push((span, task.to_string(), param.name.clone()));
        }
        *written = packed_groups(
            info.types
                .iter()
                .zip(&places)
                .map(|(param, at)| {
                    (
                        param.name.as_str(),
                        (
                            given
                                .get(&param.name)
                                .cloned()
                                .unwrap_or_else(|| Type::Param(param.name.clone())),
                            *at,
                        ),
                    )
                })
                .collect(),
            &taken,
        );
        self.note_instance(span, task, written);
        Ok(sent)
    }

    fn check_reference(
        &mut self,
        names: &mut [Bound],
        mode: Mode,
        init: &mut [Expr],
    ) -> Result<()> {
        let word = match mode {
            Mode::Fixed => "fixed&",
            Mode::Bind => "bind&",
            Mode::Flex => "flex&",
            Mode::Hold => "hold&",
        };
        let (Some(bound), Some(value)) = (names.first_mut(), init.first_mut()) else {
            return Ok(());
        };
        self.resolve_bound_types(bound)?;
        let name = bound.name.clone();
        if name == DISCARD {
            return err(
                bound.span,
                format!(
                    "a reference names a place for as long as its block lasts, so '{}' takes a name, not '_'",
                    word
                ),
            );
        }
        let ExprKind::Ref(place) = &mut value.kind else {
            self.check_expr(value)?;
            let example =
                place_path(value).map_or_else(|| "x".to_string(), |path| path_text(&path));
            return err(
                value.span,
                format!(
                    "'{} {}' is another name for a place, marked with '&', as in '&{}'",
                    word, name, example
                ),
            );
        };
        self.calling = matches!(place.kind, ExprKind::Var(_));
        let ty = self.check_expr(place);
        self.calling = false;
        let ty = ty?;
        let has_contents = self.bind_has_contents(&ty);
        let changing = mode.can_change_contents(has_contents);
        if changing {
            let taker = match mode {
                Mode::Bind => Taker::BindReference(&name),
                _ => Taker::Reference(&name),
            };
            if let Err(error) = self.given_place(place, &taker) {
                return match (self.read_place(place), self.resolved_path(place)) {
                    (Ok(()), Some(path)) => Err(Error {
                        message: format!(
                            "{}; 'fixed& {} = &{}' names it only to read it",
                            error.message,
                            name,
                            path_text(&path)
                        ),
                        ..error
                    }),
                    _ => Err(error),
                };
            }
        } else {
            self.read_place(place)?;
        }
        let Some(path) = self.resolved_path(place) else {
            return err(
                place.span,
                format!(
                    "'{} {}' names a place: a variable, a field or an item of one, or what a pointer points to",
                    word, name
                ),
            );
        };
        if let Some(annotated) = &bound.ty
            && *annotated != ty
            && !ty.unknown()
        {
            return err(
                bound.ty_span.unwrap_or(bound.span),
                format!(
                    "'{}' names a place of type {}, and a reference is of its place's type exactly, since what either writes the other reads",
                    name, ty
                ),
            );
        }
        bound.ty = Some(ty.clone());
        value.ty = Some(ty.clone());
        let at = bound.span;
        if mode.can_change_contents(true) {
            self.hand_written(place, None);
        } else {
            let owners = self.owners(place);
            if !owners.is_empty() {
                self.bound_owners.push((at, owners));
            }
        }
        self.define(&name, ty, mode, at)?;
        if let Some(info) = self
            .scopes
            .last_mut()
            .and_then(|scope| scope.names.get_mut(&name))
        {
            info.refers = Some(path);
        }
        Ok(())
    }

    fn read_place(&self, place: &Expr) -> Result<()> {
        let refuse = |why: &str| {
            err(
                place.span,
                format!(
                    "a reference names a place for as long as its block lasts, so {}",
                    why
                ),
            )
        };
        match &place.kind {
            ExprKind::Var(name) => {
                if self.lookup_or_err(name, place.span)?.result {
                    return refuse(&format!(
                        "it can't name '{}', a result, which is read by its name",
                        name
                    ));
                }
                Ok(())
            }
            ExprKind::Field(base, field) if worked_out(base) => refuse(&format!(
                "it can't name '{}', which is worked out from the value, not kept in it",
                field
            )),
            ExprKind::Field(base, _) => self.read_place(base),
            ExprKind::Index(_, index) if matches!(index.kind, ExprKind::Range(..)) => {
                refuse("it can't name a part taken of a value, which is a new value, not a place")
            }
            ExprKind::Index(base, _) if matches!(base.ty, Some(Type::Text(_))) => refuse(
                "it can't name a byte of text, which never changes; copy the byte into a variable",
            ),
            ExprKind::Index(base, _) if matches!(base.ty, Some(Type::Slice(..))) => refuse(
                "it can't name an item of a slice, which moves when the slice grows; hold the item's index, or copy the item into a variable",
            ),
            ExprKind::Index(base, _) if matches!(base.ty, Some(Type::Map(..))) => refuse(
                "it can't name a value in a map, which moves when the map grows; hold the key, or copy the value into a variable",
            ),
            ExprKind::Index(base, _) => self.read_place(base),
            ExprKind::Deref(_) | ExprKind::Shared { .. } => Ok(()),
            _ => refuse(
                "it names a variable, a field or an item of one, or what a pointer points to, and not a value made here",
            ),
        }
    }

    fn check_address(&mut self, e: &mut Expr) -> Result<Type> {
        let ExprKind::Ref(place) = &mut e.kind else {
            return Err(Error::internal_at(e.span, "an address of no place"));
        };
        let ty = self.check_expr(place)?;
        if ty.unknown() {
            e.ty = Some(Type::Unknown);
            return Ok(Type::Unknown);
        }
        if !self.is_place(place) {
            let what = no_place(place);
            return err(
                place.span,
                format!(
                    "'&' takes the address of a place: a variable, a field or an item of one, or what a pointer points to, and this is {}, with no place of its own",
                    what
                ),
            );
        }
        let written = place_path(place).map_or_else(|| "x".to_string(), |path| path_text(&path));
        self.warn_chosen(place, &format!("'&{}' is where the place is", written));
        let address = Type::Ptr(Box::new(ty), None);
        e.ty = Some(address.clone());
        Ok(address)
    }

    fn is_place(&self, e: &Expr) -> bool {
        let mut at = e;
        loop {
            match &at.kind {
                ExprKind::Var(name) => return self.lookup(name).is_some(),
                ExprKind::Shared { .. } | ExprKind::Deref(_) => return true,
                ExprKind::Field(base, _) if worked_out(base) => return false,
                ExprKind::Field(base, _) => at = base,
                ExprKind::Index(base, _) if matches!(base.ty, Some(Type::Text(_))) => return false,
                ExprKind::Index(base, index) if !matches!(index.kind, ExprKind::Range(..)) => {
                    at = base
                }
                _ => return false,
            }
        }
    }

    /// Compares addresses strictly by pointer identity; same-typed struct vs first field still share an address.
    fn check_address_compare(&mut self, l: &mut Expr, r: &mut Expr, span: Span) -> Result<Type> {
        let warned = self.warnings.len();
        let mut side_type = |side: &mut Expr| match side.kind {
            ExprKind::Ref(_) => self.check_address(side),
            _ => self.check_expr(side),
        };
        let (lt, rt) = (side_type(l)?, side_type(r)?);
        if let (ExprKind::Ref(a), ExprKind::Ref(b)) = (&l.kind, &r.kind)
            && same_root(a, b)
        {
            self.warnings.truncate(warned);
        }
        let (lt, rt) = (&lt, &rt);
        if lt.unknown() || rt.unknown() {
            return Ok(Type::Bool);
        }
        for (side, ty) in [(&*l, lt), (&*r, rt)] {
            if matches!(side.kind, ExprKind::Ref(_)) {
                continue;
            }
            let hint = match ty {
                Type::Maybe(inner) if matches!(inner.as_ref(), Type::Ptr(..)) => {
                    "; a maybe is opened first, as in 'when m is {p}'".to_string()
                }
                Type::Ptr(..) => String::new(),
                _ => {
                    let example =
                        place_path(side).map_or_else(|| "b".to_string(), |path| path_text(&path));
                    format!(
                        "; to compare where two places are, mark both, as in '&a == &{}'",
                        example
                    )
                }
            };
            if !hint.is_empty() {
                return err(
                    side.span,
                    format!(
                        "an address is compared with another place's address or with a pointer, but this value is {}{}",
                        ty, hint
                    ),
                );
            }
        }
        let place = |ty: &Type| match ty {
            Type::Ptr(inner, _) => inner.without_regions(),
            other => other.without_regions(),
        };
        let (left, right) = (place(lt), place(rt));
        if left != right {
            let pointed = match (&l.kind, &r.kind) {
                (ExprKind::Ref(_), ExprKind::Ref(_)) => None,
                (ExprKind::Ref(_), _) => Some((&right, &left)),
                _ => Some((&left, &right)),
            };
            return err(
                span,
                match pointed {
                    Some((to, place)) => format!(
                        "a pointer to {} never points at a place of type {}, so the two aren't compared",
                        to, place
                    ),
                    None => format!(
                        "places of two types are never one place, even where they start at the same address (as a shape and its first field do): this compares a place of {} with one of {}",
                        left, right
                    ),
                },
            );
        }
        Ok(Type::Bool)
    }

    /// Identifies params whose C ABI passing (`copy` vs `hidden_by_size` by-ptr) affects address/place-identity warnings.
    fn chosen_param(&self, e: &Expr) -> Option<(String, Type, Span)> {
        let (name, at) = param_root(e)?;
        let info = self.lookup(name)?;
        let chosen = info.param
            && info.passing == Passing::Copy
            && info.mode.is_fixed()
            && info.ty != Type::Region;
        chosen.then(|| (name.to_string(), info.ty.clone(), at))
    }

    fn compared_by_place(&self, symbol: &str, ty: &Type) -> String {
        match ty {
            Type::Named(name, _) if self.kinds.contains_key(name) => format!(
                "'{}' compares what {} carries by where it is",
                symbol,
                ty.without_regions()
            ),
            _ => format!(
                "'{}' compares {} by where it is",
                symbol,
                ty.without_regions()
            ),
        }
    }

    fn file_named(&self, file: usize, here: usize) -> String {
        if file == here {
            return String::new();
        }
        match self.modules.values().find(|module| module.file == file) {
            Some(module) if !module.name.is_empty() => format!(" in module '{}'", module.name),
            _ => " in the main file".to_string(),
        }
    }

    fn warn_chosen(&mut self, e: &Expr, what: &str) {
        let Some((name, ty, at)) = self.chosen_param(e) else {
            return;
        };
        if !ty.params().is_empty() {
            return;
        }
        let message = chosen_message(what, &name, &ty, &ty, self.size_of(&ty), None);
        self.warnings.push(Error::at(at, message));
    }

    fn size_of(&self, ty: &Type) -> usize {
        codegen::Layout {
            shapes: &self.shapes,
            kinds: &self.kinds,
        }
        .of(ty)
        .0
    }

    fn resolved_path(&self, e: &Expr) -> Option<Vec<Step>> {
        let mut path = place_path(e)?;
        if let Some(Step::Field(root)) = path.first()
            && let Some(refers) = self.lookup(root).and_then(|info| info.refers.clone())
        {
            path.splice(0..1, refers);
        }
        Some(path)
    }

    fn check_argument(
        &mut self,
        arg: &mut Expr,
        passing: Passing,
        callee: &str,
        param: &str,
    ) -> Result<Type> {
        match (&mut arg.kind, passing) {
            (ExprKind::Ref(place), Passing::FlexRef | Passing::FixedRef | Passing::BindRef) => {
                self.calling = matches!(place.kind, ExprKind::Var(_));
                let ty = self.check_expr(place);
                self.calling = false;
                let ty = ty?;
                self.check_given_place(place, passing, callee, param)?;
                arg.ty = Some(ty.clone());
                Ok(ty)
            }
            (ExprKind::Ref(_), _) => err(
                arg.span,
                format!(
                    "{} takes a copy as '{1}', so leave out '&'; a parameter written 'flex& {1}: …', 'fixed& {1}: …' or 'bind& {1}: …' is given the place itself",
                    callee, param
                ),
            ),
            (_, Passing::FixedRef | Passing::FlexRef | Passing::BindRef) => {
                self.check_expr(arg)?;
                Err(unmarked_place(arg, passing, callee, param))
            }
            _ => self.check_expr(arg),
        }
    }

    fn check_given_place(
        &mut self,
        place: &Expr,
        passing: Passing,
        callee: &str,
        param: &str,
    ) -> Result<()> {
        match passing {
            Passing::FlexRef => self.given_place(place, &Taker::Param(param)),
            Passing::BindRef => {
                // Scalar/value types have no interior contents, so `bind&` checks like `fixed&` on them.
                if self.bind_has_contents(place.ty.as_ref().unwrap_or(&Type::Unknown)) {
                    self.given_place(place, &Taker::BindParam(param))
                } else {
                    self.read_place(place).map_err(|error| Error {
                        message: error.message.replacen(
                            "a reference names a place for as long as its block lasts",
                            &format!(
                                "'{}' is read where the caller keeps it while the task runs",
                                param
                            ),
                            1,
                        ),
                        ..error
                    })
                }
            }
            _ => {
                if !self.is_place(place) {
                    return err(
                        place.span,
                        format!(
                            "{} reads '{}' where the caller keeps it, so it takes a place: a variable, a field or an item of one, or what a pointer points to, and this is {}",
                            callee,
                            param,
                            no_place(place)
                        ),
                    );
                }
                self.read_place(place).map_err(|error| Error {
                    message: error.message.replacen(
                        "a reference names a place for as long as its block lasts",
                        &format!(
                            "'{}' is read where the caller keeps it while the task runs",
                            param
                        ),
                        1,
                    ),
                    ..error
                })
            }
        }
    }

    fn given_place(&self, place: &Expr, taker: &Taker) -> Result<()> {
        self.given_part(place, taker, &self.written_text(place), !taker.is_bind())
    }

    fn given_part(&self, place: &Expr, taker: &Taker, written: &str, whole: bool) -> Result<()> {
        let refuse = |why: String| err(place.span, format!("{}, so {}", taker.lead(), why));
        match &place.kind {
            ExprKind::Var(name) => {
                let info = self.lookup_or_err(name, place.span)?;
                if info.result {
                    return refuse(format!("it needs a place that can change, and '{}' is a result, which only '<-' sets", name));
                }
                let bind_taker = taker.is_bind();
                if info.mode == Mode::Flex || (!whole && info.mode.can_change_contents(true)) {
                    return Ok(());
                }
                if info.mode == Mode::Bind {
                    return refuse(format!(
                        "it needs a place that can be assigned as a whole, and '{}' is a 'bind' name, which stays bound to one value; a 'bind&' takes it to change only its contents",
                        name
                    ));
                }
                if name == THIS {
                    return Err(self.this_cannot_change(place.span, &taker.using(THIS)));
                }
                if info.refers.is_some() {
                    return refuse(format!("it needs a place that can change, and '{}' is a 'fixed&', which only reads the place it names", name));
                }
                if info.param && info.passing == Passing::FixedRef {
                    let want = if bind_taker { "bind&" } else { "flex&" };
                    return refuse(format!(
                        "it needs a place that can change, and '{0}' is a 'fixed&' parameter, which only reads the caller's place; to pass it on to be changed, write '{2} {0}: {1}'",
                        name, info.ty, want
                    ));
                }
                if info.param {
                    let want = if bind_taker { "bind&" } else { "flex&" };
                    return refuse(format!(
                        "it needs a place that can change, and '{0}' is a parameter, which never does; to pass on the caller's place, write '{2} {0}: {1}'",
                        name, info.ty, want
                    ));
                }
                if info.kept {
                    return refuse(format!("it needs a place that can change, and '{}' never does{}", name, self.param_hint(name, info)));
                }
                let kind = if bind_taker { "a value declared with 'flex' or 'bind'" } else { "a value declared with 'flex'" };
                refuse(format!("it needs a place that can change, and '{}' never does (declared at {}:{}); {} can", name, info.span.line, info.span.col, kind))
            }
            ExprKind::Field(base, field) => {
                if matches!(&base.kind, ExprKind::Var(name) if name == THIS) && !self.lookup(THIS).is_some_and(|info| info.mode.can_change_contents(true)) {
                    return Err(self.this_cannot_change(place.span, &taker.using(&format!("{}{}", MODULE_SEPARATOR, field))));
                }
                match &base.ty {
                    Some(Type::Tuple(_)) => return refuse("it needs a place that can change, and a tuple's items never do".to_string()),
                    Some(Type::Array(..) | Type::Slice(..) | Type::Map(..) | Type::Text(_)) => {
                        return refuse(format!("it needs a place that can change, and '{}' is worked out from the value, not kept in it", field));
                    }
                    Some(ty) => self.read_only_field(ty, field, place.span)?,
                    None => {}
                }
                self.given_part(base, taker, written, false)
            }
            ExprKind::Index(_, index) if matches!(index.kind, ExprKind::Range(..)) => {
                refuse("it needs a place that can change, and a part taken of a value is a new value, not a place".to_string())
            }
            ExprKind::Index(base, _) => match &base.ty {
                Some(Type::Slice(..)) => refuse(
                    "it can't be an item of a slice, which moves when the slice grows; give the slice and the item's index, or copy the item into a 'flex' variable, change it, and put it back"
                        .to_string(),
                ),
                Some(Type::Map(..)) => refuse(
                    "it can't be a value in a map, which moves when the map grows; give the map and the key, or copy the value into a 'flex' variable, change it, and put it back"
                        .to_string(),
                ),
                Some(Type::Text(_)) => refuse("it needs a place that can change, and text never does".to_string()),
                _ => self.given_part(base, taker, written, false),
            },
            ExprKind::Deref(pointer) => self.written_through(pointer, written, None),
            ExprKind::Shared { shape, field } => self.changeable_shared(shape, field, place.span, &format!("{}, and ", taker.lead()), whole),
            _ => refuse("it needs a place that can change: a 'flex' variable, a field or array item of one, or what a pointer points to (p^), not a value made here".to_string()),
        }
    }

    fn widen_literal(&mut self, l: &mut Expr, r: &mut Expr, lt: Type, rt: Type) -> (Type, Type) {
        let literal = |e: &Expr| {
            matches!(
                e.kind,
                ExprKind::Tuple(_) | ExprKind::Array(_) | ExprKind::Repeat { .. }
            )
        };
        if lt.without_regions() == rt.without_regions()
            || lt.unknown()
            || rt.unknown()
            || literal(l) == literal(r)
        {
            return (lt, rt);
        }
        let (written, other) = if literal(r) { (r, &lt) } else { (l, &rt) };
        let before = written.clone();
        match self.coerce(written, other) {
            Ok(()) => (other.clone(), other.clone()),
            Err(_) => {
                *written = before;
                (lt, rt)
            }
        }
    }

    /// Forbids aliasing a mutable parameter with another arg or `alters` receiver; `&p^`/`&q^` pointers cannot be disambiguated.
    fn check_aliasing(&self, args: &[Expr], info: &TaskInfo) -> Result<()> {
        let alters = info.owner.as_ref().is_some_and(|owner| owner.alters);
        let mut places: Vec<(Vec<Step>, bool, &str, Span)> = Vec::new();
        for (i, ((arg, (param, _)), passing)) in
            args.iter().zip(&info.params).zip(&info.passing).enumerate()
        {
            let (place, changed) = match (&arg.kind, passing) {
                (ExprKind::Ref(place), Passing::FlexRef | Passing::BindRef) => {
                    (place.as_ref(), true)
                }
                (ExprKind::Ref(place), Passing::FixedRef) => (place.as_ref(), false),
                (_, Passing::Flex | Passing::Fixed | Passing::Bind) => continue,
                _ => (arg, i == 0 && alters),
            };
            let Some(path) = self.resolved_path(place) else {
                continue;
            };
            for (before, before_changed, before_param, _) in &places {
                let read_there = *passing == Passing::FixedRef;
                let receiver_and_copy = alters
                    && !read_there
                    && ((i != 0 && !changed && *before_param == THIS)
                        || (i == 0 && !*before_changed));
                if (changed || *before_changed) && !receiver_and_copy && overlaps(before, &path) {
                    let name = |param: &str| {
                        if param == THIS {
                            "the value it is called on".to_string()
                        } else {
                            format!("'{}'", param)
                        }
                    };
                    let relation = if path.len() > before.len() {
                        "is part of the place given as"
                    } else if path.len() < before.len() {
                        "holds the place given as"
                    } else if path.contains(&Step::Item(None)) || before.contains(&Step::Item(None))
                    {
                        "may be the place given as"
                    } else {
                        "is given as"
                    };
                    let changing = if changed {
                        param.as_str()
                    } else {
                        *before_param
                    };
                    let mut how = if changing == THIS {
                        "the method changes the value it is called on".to_string()
                    } else {
                        format!("the call changes it through '{}'", changing)
                    };
                    if !changed {
                        how = format!("{} while it reads it through {}", how, name(param));
                    }
                    let written = place_path(place)
                        .map(|written| path_text(&written))
                        .unwrap_or_default();
                    let subject = if written != path_text(&path) {
                        format!("'{}' names '{}', which", written, path_text(&path))
                    } else {
                        format!("'{}'", written)
                    };
                    return err(
                        arg.span,
                        format!(
                            "{} {} {} too, and {}; a place the call changes is given once, so keep a copy of it in a variable first, and give that as the other",
                            subject,
                            relation,
                            name(before_param),
                            how
                        ),
                    );
                }
            }
            places.push((path, changed, param, arg.span));
        }
        Ok(())
    }

    fn settled_type(
        &mut self,
        ty: &Type,
        regions: &HashMap<String, String>,
        given: &HashMap<String, Type>,
        at: Span,
    ) -> Result<Type> {
        let ty = ty.map_regions(&mut |region| {
            Some(
                regions
                    .get(region)
                    .cloned()
                    .unwrap_or_else(|| ANY_REGION.to_string()),
            )
        });
        let ty = ty.map_group_items(&mut |name| group_items(given, name));
        let mut ty = ty.map_params(&mut |name| given.get(name).cloned());
        self.settle_applications(&mut ty, at)?;
        if !given.is_empty() {
            ty = ty.normalized_tasks();
        }
        Ok(ty)
    }

    fn check_kept_regions(
        &mut self,
        span: Span,
        task: &str,
        info: &TaskInfo,
        regions: &HashMap<String, String>,
        given: &HashMap<String, Type>,
    ) -> Result<()> {
        for ty in info
            .params
            .iter()
            .map(|(_, ty)| ty.clone())
            .chain([info.ret.clone()])
        {
            // Check before monomorphizing shapes/kinds, which collapses nested regions.
            let ty = ty.map_regions(&mut |region| {
                Some(
                    regions
                        .get(region)
                        .cloned()
                        .unwrap_or_else(|| ANY_REGION.to_string()),
                )
            });
            let ty = ty.map_group_items(&mut |name| group_items(given, name));
            let ty = ty.map_params(&mut |name| given.get(name).cloned());
            if let Some((outer, inner)) = region_conflict(&ty, None) {
                let fix = match has_closure(&ty) {
                    true => format!(
                        "make the lambda keep what it uses in '{0}', as in '[@{0}](…)'",
                        outer
                    ),
                    false => format!(
                        "copy it into '{0}' first, as in 'value.copy() at {0}'",
                        outer
                    ),
                };
                return err(
                    span,
                    format!(
                        "'{0}' would keep this in region '{1}' and in region '{2}', but everything a value in a region holds is in that region; {3}",
                        unqualified(task),
                        outer,
                        inner,
                        fix
                    ),
                );
            }
        }
        Ok(())
    }

    fn written_types(
        &mut self,
        span: Span,
        task: &str,
        written: &mut [TypeArg],
        info: &TaskInfo,
    ) -> Result<HashMap<String, Type>> {
        if written.is_empty() {
            return Ok(HashMap::new());
        }
        if info.types.is_empty() {
            return err(
                span,
                format!(
                    "task '{}' takes no types, so '< … >' has nothing to name",
                    task
                ),
            );
        }
        let partly = pattern_call_parts(task).is_some() && written.len() < info.types.len();
        if written.len() != info.types.len() && !partly {
            let names: Vec<&str> = info.types.iter().map(|param| param.name.as_str()).collect();
            return err(
                span,
                format!(
                    "task '{}' takes {}, so name all of them, as in '{}<{}>(…)'",
                    task,
                    count(info.types.len(), "type"),
                    unqualified(task),
                    names.join(", ")
                ),
            );
        }
        let mut given = HashMap::new();
        for ((ty, at), param) in written.iter_mut().zip(&info.types) {
            *ty = self.resolve_type(ty, *at, TypePlace::Body)?;
            given.insert(param.name.clone(), ty.clone());
        }
        Ok(given)
    }

    fn check_need(
        &self,
        what: &str,
        task: &str,
        param: &TypeParam,
        ty: &Type,
        at: Span,
    ) -> Result<()> {
        if let Some(Followed { name: pattern, .. }) = param
            .patterns
            .iter()
            .find(|followed| !self.follows(ty, &followed.name))
        {
            let pattern = unqualified(pattern);
            let how = match self.owner_of(ty) {
                Some(owner)
                    if self.shapes.contains_key(&owner) || self.kinds.contains_key(&owner) =>
                {
                    let source = self
                        .made_of
                        .get(&owner)
                        .map_or(owner.clone(), |made| made.name.clone());
                    let word = if self.kinds.contains_key(&source) {
                        "kind"
                    } else {
                        "shape"
                    };
                    format!(
                        "; a {} follows it with '::' after its name, as in '{} {}::{}'",
                        word,
                        word,
                        unqualified(&source),
                        pattern
                    )
                }
                _ => match ty {
                    Type::Param(name) => format!("; ask for it, as in '<{}: {}>'", name, pattern),
                    _ => ", which only a shape or a kind can".to_string(),
                },
            };
            if let Some((group, place)) = param.name.split_once(GROUP_ITEM) {
                return err(
                    at,
                    format!(
                        "{} '{}' asks each value of its group '{}...' to follow pattern '{}', and value {} is {}, which doesn't{}",
                        what,
                        unqualified(task),
                        group,
                        pattern,
                        place.parse::<usize>().map_or(0, |i| i + 1),
                        ty,
                        how
                    ),
                );
            }
            return err(
                at,
                format!(
                    "{} '{}' takes a type that follows pattern '{}' as '{}', and {} doesn't{}",
                    what,
                    unqualified(task),
                    pattern,
                    param.name,
                    ty,
                    how
                ),
            );
        }
        let Some(&(need, _)) = param.needs.iter().find(|(need, _)| !self.allows(*need, ty)) else {
            return Ok(());
        };
        if let Some((group, place)) = param.name.split_once(GROUP_ITEM) {
            let given = match ty {
                Type::Group(given) => format!(
                    "is given the group '{}...', which {}",
                    given,
                    self.why_not(need, ty)
                ),
                _ => format!(
                    "value {} is {}, which {}",
                    place.parse::<usize>().map_or(0, |i| i + 1),
                    ty,
                    self.why_not(need, ty)
                ),
            };
            return err(
                at,
                format!(
                    "{} '{}' asks each value of its group '{}...' to be '{}', and {}",
                    what,
                    unqualified(task),
                    group,
                    need.word(),
                    given
                ),
            );
        }
        err(
            at,
            format!(
                "{} '{}' takes a type that is '{}' as '{}', and {} {}",
                what,
                unqualified(task),
                need.word(),
                param.name,
                ty,
                self.why_not(need, ty)
            ),
        )
    }

    fn allows(&self, need: Need, ty: &Type) -> bool {
        if ty.unknown() || is_untold(ty) {
            return true;
        }
        if let Type::Param(name) | Type::Group(name) = ty {
            return self
                .type_param(name)
                .is_some_and(|param| param.needs.iter().any(|(own, _)| own.means(need)));
        }
        match need {
            Need::Ordered => ty.is_numeric() || matches!(ty, Type::Char | Type::Text(_)),
            Need::Shown => self.writable(ty),
            Need::Same => self.comparable(ty),
            Need::Similar => self.unsimilar_part(ty).is_none(),
            Need::Frozen => self.changeable_item(ty).is_none(),
        }
    }

    fn comparable(&self, ty: &Type) -> bool {
        match ty {
            _ if ty.is_numeric() => true,
            Type::Char
            | Type::Bool
            | Type::Text(_)
            | Type::Ptr(..)
            | Type::Slice(..)
            | Type::Map(..)
            | Type::Array(..)
            | Type::Tuple(_)
            | Type::Task(_) => true,
            Type::Named(name, _) if self.kinds.contains_key(name) => {
                self.kind_comparable(name, &mut Vec::new())
            }
            Type::Applied(applied) if self.kinds.contains_key(&applied.name) => {
                self.applied_parts(applied).is_some_and(|parts| {
                    parts.iter().all(|part| match part {
                        Type::Maybe(inner) => self.comparable(inner),
                        other => self.comparable(other),
                    })
                })
            }
            Type::Named(..) | Type::Applied(_) => self
                .owner_of(ty)
                .is_some_and(|owner| self.shapes.contains_key(&owner)),
            Type::Param(_) | Type::Group(_) => self.allows(Need::Same, ty),
            _ => false,
        }
    }

    fn kind_comparable(&self, name: &str, seen: &mut Vec<String>) -> bool {
        if seen.iter().any(|kind| kind == name) {
            return true;
        }
        let Some(kind) = self.kinds.get(name) else {
            return false;
        };
        seen.push(name.to_string());
        let found = kind
            .variants
            .iter()
            .flat_map(|variant| &variant.payload)
            .all(|field| {
                let carried = match &field.ty {
                    Type::Maybe(inner) => inner.as_ref(),
                    other => other,
                };
                match carried {
                    Type::Named(inner, _) if self.kinds.contains_key(inner) => {
                        self.kind_comparable(inner, seen)
                    }
                    other => self.comparable(other),
                }
            });
        seen.pop();
        found
    }

    fn by_place(&self, ty: &Type) -> bool {
        self.by_place_in(ty, &mut Vec::new())
    }

    fn by_place_in(&self, ty: &Type, seen: &mut Vec<String>) -> bool {
        match ty {
            Type::Array(..) | Type::Tuple(_) => true,
            Type::Named(name, _) if self.shapes.contains_key(name) => true,
            Type::Named(name, _) => {
                let Some(kind) = self.kinds.get(name) else {
                    return false;
                };
                if seen.contains(name) {
                    return false;
                }
                seen.push(name.clone());
                let found = kind
                    .variants
                    .iter()
                    .flat_map(|variant| &variant.payload)
                    .any(|field| {
                        let carried = match &field.ty {
                            Type::Maybe(inner) => inner.as_ref(),
                            other => other,
                        };
                        self.by_place_in(carried, seen)
                    });
                seen.pop();
                found
            }
            Type::Applied(_) => true,
            _ => false,
        }
    }

    /// Structural `~=` compares pointers by address to avoid cyclic traversal.
    fn unsimilar_part(&self, ty: &Type) -> Option<Type> {
        self.unsimilar_in(ty, &mut Vec::new())
    }

    fn unsimilar_in(&self, ty: &Type, seen: &mut Vec<String>) -> Option<Type> {
        match ty {
            _ if ty.is_numeric() => None,
            Type::Char | Type::Bool | Type::Text(_) | Type::Ptr(..) | Type::Task(_) => None,
            Type::Maybe(inner) | Type::Array(inner, _) | Type::Slice(inner, _) => {
                self.unsimilar_in(inner, seen)
            }
            Type::Map(key, value, _) => self
                .unsimilar_in(key, seen)
                .or_else(|| self.unsimilar_in(value, seen)),
            Type::Tuple(items) => items.iter().find_map(|item| self.unsimilar_in(item, seen)),
            Type::Param(_) | Type::Group(_) if self.allows(Need::Similar, ty) => None,
            Type::Applied(applied) => self
                .applied_parts(applied)?
                .iter()
                .find_map(|part| self.unsimilar_in(part, seen)),
            Type::Named(name, _) if seen.contains(name) => None,
            Type::Named(name, _) => {
                let parts: Vec<Type> = if let Some(shape) = self.shapes.get(name) {
                    shape.fields.iter().map(|field| field.ty.clone()).collect()
                } else if let Some(kind) = self.kinds.get(name) {
                    kind.variants
                        .iter()
                        .flat_map(|variant| variant.payload.iter().map(|field| field.ty.clone()))
                        .collect()
                } else {
                    return Some(ty.clone());
                };
                seen.push(name.clone());
                let found = parts.iter().find_map(|part| self.unsimilar_in(part, seen));
                seen.pop();
                found
            }
            _ => Some(ty.clone()),
        }
    }

    fn why_not(&self, need: Need, ty: &Type) -> String {
        if let Type::Param(param) | Type::Group(param) = ty {
            let declared = self.type_param(param);
            let group =
                matches!(ty, Type::Group(_)) || declared.is_some_and(|declared| declared.group);
            let name = match declared {
                Some(declared) if group => format!("{}...", declared.name),
                _ => param.clone(),
            };
            let owned: Vec<Need> = declared
                .map(|param| param.needs.iter().map(|(own, _)| *own).collect())
                .unwrap_or_default();
            let own: Vec<&str> = owned.iter().map(|own| own.word()).collect();
            let mut wanted: Vec<&str> = owned
                .iter()
                .filter(|own| !need.means(**own))
                .map(|own| own.word())
                .collect();
            wanted.push(need.word());
            return match (own.is_empty(), group) {
                (false, false) => format!(
                    "is only '{}' here; require it too, as in '<{}: {}>'",
                    own.join(" & "),
                    name,
                    wanted.join(" & ")
                ),
                (true, false) => format!(
                    "is any type here; require it, as in '<{}: {}>'",
                    name,
                    need.word()
                ),
                (false, true) => format!(
                    "asks only '{}' of its types here; require it too, as in '<{}: {}>'",
                    own.join(" & "),
                    name,
                    wanted.join(" & ")
                ),
                (true, true) => format!(
                    "asks nothing of its types here; require it, as in '<{}: {}>'",
                    name,
                    need.word()
                ),
            };
        }
        match need {
            Need::Ordered => "has no order, so '<' can't compare it".to_string(),
            Need::Shown => "can't be shown".to_string(),
            Need::Same => "can't be compared with '=='".to_string(),
            Need::Similar => match self.unsimilar_part(ty) {
                Some(part) if part != *ty => {
                    format!("holds {}, which can't be compared item by item", part)
                }
                _ => "can't be compared item by item".to_string(),
            },
            Need::Frozen => match self.changeable_item(ty) {
                Some(what) => format!("holds {}", what),
                None => "can change".to_string(),
            },
        }
    }

    fn untold_type(&self, task: &str, param: &str) -> String {
        if self
            .tasks
            .get(task)
            .is_some_and(|info| info.types.iter().any(|param| param.group))
        {
            return format!(
                "can't tell which type '{}' is for this call of '{}', since no argument and nothing this value goes into names one; a call of a task taking a group of types doesn't write its types yet, so give the value a place whose type names it, as in 'fixed x: int = {}(…)'",
                param,
                unqualified(task),
                unqualified(task)
            );
        }
        if self
            .tasks
            .get(task)
            .is_some_and(|info| info.owner.is_some())
        {
            return format!(
                "can't tell which type '{}' is for this call of '{}', since no argument and nothing this value goes into names one; a method's types aren't written at a call yet, so give the value a place whose type names it, as in 'fixed x: maybe int = …'",
                param,
                self.written_names
                    .get(task)
                    .cloned()
                    .unwrap_or_else(|| unqualified(task).to_string())
            );
        }
        let count = self
            .tasks
            .get(task)
            .map_or(1, |info| info.types.len().max(1));
        format!(
            "can't tell which type '{}' is for this call of '{}', since no argument and nothing this value goes into names one; write it, as in '{}<{}>(…)'",
            param,
            unqualified(task),
            unqualified(task),
            vec!["int"; count].join(", ")
        )
    }

    fn untold_param(&self, ty: &Type) -> Option<String> {
        let name = ty
            .params()
            .into_iter()
            .find(|name| self.type_param(name).is_none())?;
        let (_, task, _) = self.unsettled_types.iter().rev().find(|(_, task, param)| {
            param == name
                || self
                    .tasks
                    .get(task)
                    .is_some_and(|info| info.types.iter().any(|p| p.name == name))
        })?;
        Some(self.untold_type(task, name))
    }

    fn note_instance(&mut self, at: Span, task: &str, given: &[TypeArg]) {
        if given.is_empty() || given.iter().any(|(ty, _)| !ty.params().is_empty()) {
            return;
        }
        let types: Vec<Type> = given.iter().map(|(ty, _)| ty.clone()).collect();
        let key = instance_name(task, &types);
        if self.noted_instances.insert(key.clone()) {
            self.instances.push((key, task.to_string(), types, at));
        }
    }

    fn coerce(&mut self, expr: &mut Expr, expected: &Type) -> Result<()> {
        if self.is_shortcut_lambda(expr) {
            self.prepare_shortcut_lambda(expr, expected)?;
        }
        if expected.unknown() || expr.ty.as_ref().is_some_and(Type::unknown) {
            return Ok(());
        }
        self.settle_types(expr, expected)?;
        self.settle_variant(expr, expected)?;
        let numeric = match expected {
            Type::Maybe(inner) | Type::Or(inner, _) => inner,
            other => other,
        };
        if numeric.is_numeric() {
            numeric_literal(expr, numeric)?;
            if *numeric == Type::Float32 && expr.ty == Some(Type::Float) {
                float32_literal(expr);
            }
        }
        let actual = expr.ty()?.clone();
        let unmade_actual = self.unmade(&actual);
        let unmade_expected = self.unmade(expected);
        if fits_regions(&actual, expected) || fits_regions(&unmade_actual, &unmade_expected) {
            expr.ty = Some(expected.clone());
            return self.settle_copies(expr, expected);
        }
        if self.widen(expr, &actual, expected) {
            return self.coerce(expr, expected);
        }
        if let (Type::Task(task), Type::Closure(closure)) = (&actual, expected)
            && task.normalized_avoiding(&closure.region) == closure.task
        {
            if let ExprKind::Kept { .. } = &expr.kind {
                expr.ty = Some(expected.clone());
                return Ok(());
            }
            let region = match &expr.kind {
                ExprKind::TaskValue(_) => None,
                ExprKind::Var(name) if is_lambda(name) => None,
                _ if closure.region == ANY_REGION => {
                    let shown = expected.map_regions(&mut |_| Some("r".to_string()));
                    return err(
                        expr.span,
                        format!(
                            "this task value goes where a lambda that keeps what it uses is expected, {0}, and keeps itself in a region, which no other value of this call names; give a task by its name, or keep this one first, as in 'fixed kept: {0} = …'",
                            shown
                        ),
                    );
                }
                _ => {
                    self.visible_region(&closure.region, expr.span, true)?;
                    Some(closure.region.clone())
                }
            };
            let value = std::mem::replace(expr, Expr::new(ExprKind::NoneLit, expr.span));
            *expr = Expr::new(
                ExprKind::Kept {
                    value: Box::new(value),
                    region,
                },
                expr.span,
            );
            expr.ty = Some(expected.clone());
            return Ok(());
        }
        // Coerce `Choice` expressions arm-by-arm unless the branches already fail to fit `expected`.
        if let ExprKind::Choice(stmt) = &mut expr.kind
            && fits(&actual, expected)
        {
            self.settle_branch_values(stmt, expected)?;
            expr.ty = Some(expected.clone());
            return Ok(());
        }
        if self.coerce_items(expr, expected)? {
            return Ok(());
        }
        if let (ExprKind::PlanB { value, .. }, Type::Maybe(held)) = (&expr.kind, &actual)
            && fits_regions(held, expected)
            && value.ty.as_ref().is_some_and(|ty| !matches!(ty, Type::Maybe(inner) | Type::Or(inner, _) if matches!(**inner, Type::Maybe(_))))
        {
            return err(
                expr.span,
                format!("this plan B can give none, so the whole is {}, with no value when the plan B runs, but {} is expected here; make the plan B give a value of type {}, or expect {}", actual, expected, expected, actual),
            );
        }
        match expected {
            Type::Maybe(inner)
                if actual == Type::None
                    || fits_regions(&actual, inner)
                    || self.coerce_items(expr, inner)? =>
            {
                if fits_regions(&actual, inner) {
                    expr.ty = Some((**inner).clone());
                    self.settle_copies(expr, inner)?;
                }
                wrap(expr, expected);
                return Ok(());
            }
            Type::Maybe(inner) if matches!(**inner, Type::Or(..)) && fits(&actual, inner) => {
                self.coerce(expr, inner)?;
                wrap(expr, expected);
                return Ok(());
            }
            Type::Or(value, error) => {
                if let Type::Fail(given) = &actual {
                    if !fits_regions(given, error) {
                        return err(
                            expr.span,
                            format!(
                                "expected an error of type {}, got {}{}",
                                error,
                                given,
                                mismatch_hint(given, error)
                            ),
                        );
                    }
                    if let ExprKind::Fail(inner) = &mut expr.kind {
                        self.settle_copies(inner, error)?;
                    }
                    wrap(expr, expected);
                    return Ok(());
                }
                if **value != Type::Nothing {
                    let fits_value = fits_regions(&actual, value)
                        || matches!(value.as_ref(), Type::Maybe(inner) if actual == Type::None || fits_regions(&actual, inner))
                        || self.coerce_items(expr, value)?;
                    if fits_value {
                        self.coerce(expr, value)?;
                        wrap(expr, expected);
                        return Ok(());
                    }
                }
            }
            _ => {}
        }
        if let Some(untold) = self.untold_param(expected) {
            return err(expr.span, untold);
        }
        if actual == Type::Float
            && *expected == Type::Int
            && let ExprKind::Binary(BinaryOp::Pow, l, r) = &expr.kind
            && l.ty == Some(Type::Int)
            && r.ty == Some(Type::Int)
        {
            return err(
                expr.span,
                "expected type int, got float: an int raised to an int that may be negative is a float; raise it to a unit, as in 'n ** unit(k)', or to a constant 0 or more, as in 'n ** 2', for an int",
            );
        }
        if let Some((from, to)) = self.widened_inside(&actual, expected) {
            return err(
                expr.span,
                format!(
                    "expected type {}, got {}; {} imitates {}, but only a value of {} itself becomes one, never one inside another value, which would be remade; take it out first, or make the value with {} inside",
                    expected, actual, to, from, from, to
                ),
            );
        }
        if self.widens(expected, &actual) {
            return err(
                expr.span,
                format!(
                    "expected type {0}, got {1}; {1} imitates {0}, so a value of {0} goes where {1} is expected, but not the other way: a value of {1} may be a variant {0} doesn't have, and a 'match' makes one from the other",
                    expected, actual
                ),
            );
        }
        if let (Type::Named(name, Some(region)), Type::Named(expected_name, None)) =
            (&actual, expected)
            && name == expected_name
            && self.shapes.get(name).is_some_and(|shape| {
                shape.fields.iter().any(
                |field| matches!(&field.ty, Type::Closure(closure) if closure.region == THIS_WORD),
            )
            })
        {
            return err(
                expr.span,
                format!(
                    "expected type {0}, got {1}; this value holds what lives in region '{2}', such as a lambda that keeps what it uses there, and a '{0}' here holds only what lasts as long as the program; to keep it, name the region, as in '{0}@{2}'",
                    expected, actual, region
                ),
            );
        }
        err(
            expr.span,
            format!(
                "expected type {}, got {}{}",
                expected,
                actual,
                mismatch_hint(&actual, expected)
            ),
        )
    }

    fn widen(&mut self, expr: &mut Expr, actual: &Type, expected: &Type) -> bool {
        let target = match expected {
            _ if self.widens(actual, expected) => expected,
            Type::Maybe(inner) if self.widens(actual, inner) => inner,
            Type::Or(value, _) if self.widens(actual, value) => value,
            Type::Or(_, error) => {
                let (Type::Fail(given), ExprKind::Fail(inner)) = (actual, &mut expr.kind) else {
                    return false;
                };
                if !self.widens(given, error) {
                    return false;
                }
                let span = inner.span;
                let value = std::mem::replace(&mut **inner, Expr::new(ExprKind::NoneLit, span));
                **inner = Expr {
                    kind: ExprKind::Widen(Box::new(value)),
                    span,
                    ty: Some((**error).clone()),
                };
                expr.ty = Some(Type::Fail(error.clone()));
                return true;
            }
            _ => return false,
        };
        let value = std::mem::replace(expr, Expr::new(ExprKind::NoneLit, expr.span));
        *expr = Expr {
            kind: ExprKind::Widen(Box::new(value)),
            span: expr.span,
            ty: Some(target.clone()),
        };
        true
    }

    fn widened_inside(&self, from: &Type, to: &Type) -> Option<(Type, Type)> {
        let found = |a: &Type, b: &Type| {
            if self.widens(a, b) {
                Some((a.without_regions(), b.without_regions()))
            } else {
                self.widened_inside(a, b)
            }
        };
        match (from, to) {
            (Type::Maybe(a), Type::Maybe(b))
            | (Type::Slice(a, _), Type::Slice(b, _))
            | (Type::Ptr(a, _), Type::Ptr(b, _))
            | (Type::Array(a, _), Type::Array(b, _)) => found(a, b),
            (Type::Map(k, a, _), Type::Map(j, b, _)) => found(k, j).or_else(|| found(a, b)),
            (Type::Tuple(a), Type::Tuple(b)) if a.len() == b.len() => {
                a.iter().zip(b).find_map(|(a, b)| found(a, b))
            }
            _ => None,
        }
    }

    fn widens(&self, from: &Type, to: &Type) -> bool {
        let (Some(source), Some(target)) = (self.kind_made(from), self.kind_made(to)) else {
            return false;
        };
        fits_regions(&in_region_of(to, from), to) && self.imitates(&target, &source, 0)
    }

    fn kind_made(&self, ty: &Type) -> Option<(String, Vec<Type>)> {
        match self.unmade(ty) {
            Type::Named(name, _) if self.kinds.contains_key(&name) => Some((name, Vec::new())),
            Type::Applied(applied) if self.kinds.contains_key(&applied.name) => Some((
                applied.name,
                applied.types.iter().map(Type::without_regions).collect(),
            )),
            _ => None,
        }
    }

    fn imitates(&self, to: &(String, Vec<Type>), from: &(String, Vec<Type>), depth: usize) -> bool {
        let Some(kind) = self.kinds.get(&to.0).filter(|_| depth <= MAX_TYPE_DEPTH) else {
            return false;
        };
        let given: HashMap<&str, &Type> = kind
            .types
            .iter()
            .map(|param| param.name.as_str())
            .zip(&to.1)
            .collect();
        kind.imitates.iter().any(|(base, _)| {
            let base = base.map_params(&mut |param| given.get(param).map(|ty| (*ty).clone()));
            self.kind_made(&base)
                .is_some_and(|base| base == *from || self.imitates(&base, from, depth + 1))
        })
    }

    fn settle_types(&mut self, expr: &mut Expr, expected: &Type) -> Result<()> {
        let ExprKind::Call { name, types, .. } = &expr.kind else {
            return Ok(());
        };
        if types.iter().all(|(ty, _)| ty.params().is_empty()) {
            return Ok(());
        }
        let name = name.clone();
        let sent = expr.ty.clone().unwrap_or(Type::Nothing);
        let mut given: HashMap<String, Type> = HashMap::new();
        self.match_params(&sent, expected, &mut given);
        if given.is_empty() {
            return Ok(());
        }
        let ExprKind::Call { types, .. } = &mut expr.kind else {
            return Ok(());
        };
        for (ty, _) in types.iter_mut() {
            *ty = ty.map_params(&mut |param| given.get(param).cloned());
        }
        let types = types.clone();
        expr.ty = Some(sent.map_params(&mut |param| given.get(param).cloned()));
        if let Some(untold) = types
            .iter()
            .find_map(|(ty, _)| ty.params().first().map(|param| param.to_string()))
        {
            if let Some(entry) = self
                .unsettled_types
                .iter_mut()
                .rev()
                .find(|(at, _, _)| *at == expr.span)
            {
                entry.2 = untold;
            }
            return Ok(());
        }
        if let Some(at) = self
            .unsettled_types
            .iter()
            .rposition(|(at, _, _)| *at == expr.span)
        {
            self.unsettled_types.remove(at);
        }
        if let Some(ty) = &mut expr.ty {
            self.settle_applications(ty, expr.span)?;
        }
        if let Some(info) = self.tasks.get(&name).cloned() {
            for (param, (ty, at)) in info.types.iter().zip(&types) {
                self.check_need("task", &name, param, ty, *at)?;
            }
        }
        self.note_instance(expr.span, &name, &types);
        Ok(())
    }

    fn coerce_items(&mut self, expr: &mut Expr, expected: &Type) -> Result<bool> {
        if let (Type::Tuple(items), ExprKind::Tuple(values)) = (expected, &mut expr.kind) {
            if items.len() != values.len() {
                return Ok(false);
            }
            for (value, item) in values.iter_mut().zip(items) {
                self.coerce(value, item)?;
            }
            expr.ty = Some(expected.clone());
            return Ok(true);
        }
        let Type::Array(items, count) = expected else {
            return Ok(false);
        };
        let written = match &expr.ty {
            Some(Type::Array(_, written)) => *written,
            _ => return Ok(false),
        };
        if written != *count {
            return Ok(false);
        }
        match &mut expr.kind {
            ExprKind::Array(values) => values
                .iter_mut()
                .try_for_each(|value| self.coerce(value, items))?,
            ExprKind::Repeat { value, .. } => self.coerce(value, items)?,
            _ => return Ok(false),
        }
        expr.ty = Some(expected.clone());
        Ok(true)
    }

    fn expect_type(&self, actual: &Type, expected: &Type, span: Span) -> Result<()> {
        if actual.unknown() || expected.unknown() {
            return Ok(());
        }
        if actual != expected {
            err(
                span,
                format!(
                    "expected type {}, got {}{}",
                    expected,
                    actual,
                    extract_hint(&[actual])
                ),
            )
        } else {
            Ok(())
        }
    }
}

fn item_type_example(array: &Type) -> Type {
    match array {
        Type::Array(items, _) => items.without_regions(),
        other => other.without_regions(),
    }
}

fn gives_a_maybe(extracted: &Type, given: &Type) -> Option<Type> {
    let plain = !matches!(extracted, Type::Maybe(_) | Type::Nothing) && !extracted.unknown();
    (plain && matches!(given, Type::None | Type::Maybe(_)))
        .then(|| Type::Maybe(Box::new(extracted.clone())))
}

struct WrapperTail {
    own: usize,
    pairs: Vec<(usize, usize)>,
    group: Option<usize>,
}

struct CallTypes {
    given: HashMap<String, Type>,
    /// Tracks arg-inferred types apart from explicit type args for accurate region-omission diagnostics.
    shown: HashMap<String, Type>,
    regions: HashMap<String, String>,
    taken: HashMap<String, Taken>,
    untold: bool,
}

fn unmarked_place(arg: &Expr, passing: Passing, callee: &str, param: &str) -> Error {
    if matches!(arg.kind, ExprKind::Piped(_)) {
        let does = if passing == Passing::FixedRef {
            "reads"
        } else {
            "changes"
        };
        return Error::at(
            arg.span,
            format!(
                "{} {} '{}' where the caller keeps it, so it takes a place, and a pipe gives a value; call it with the place marked, as in 'f(&a)'",
                callee, does, param
            ),
        );
    }
    let message = match (place_path(arg), passing) {
        (Some(path), Passing::FixedRef) => format!(
            "{} reads '{}' where the caller keeps it, so the call marks that place with '&', as in '&{}'",
            callee,
            param,
            path_text(&path)
        ),
        (None, Passing::FixedRef) => {
            format!(
                "{} reads '{}' where the caller keeps it, so it takes a place marked with '&', as in '&a', and this is a value made here; a parameter written '{}: …' takes a copy",
                callee, param, param
            )
        }
        (Some(path), _) => format!(
            "{} changes '{}', the place it is given, so the call marks that place with '&', as in '&{}'",
            callee,
            param,
            path_text(&path)
        ),
        (None, _) => format!(
            "{} changes '{}', the place it is given, so it takes a place that can change, marked with '&', as in '&a', and this is a value made here",
            callee, param
        ),
    };
    Error::at(arg.span, message)
}

enum CallSetup {
    Checked(Type),
    Call(TaskInfo, Option<(String, usize)>),
}

fn group_hint(mut error: Error, group: Option<&(String, usize)>) -> Error {
    if let Some((group, given)) = group
        && error.message.starts_with("expected type")
    {
        error.message.push_str(&format!(
            "; this call gives the group '{}...' {}, so the group is {}",
            group,
            count(*given, "value"),
            count(*given, "type")
        ));
    }
    error
}

fn misread_comparison(name: &str) -> String {
    format!(
        "'{0}' is a value, but '{0} < …, … > (…)' reads as a call of '{0}' given the types between '<' and '>'; to compare, put the comparison before the ',' in parentheses, as in '({0} < …), … > (…)'",
        name
    )
}

fn wrap(expr: &mut Expr, ty: &Type) {
    let span = expr.span;
    let inner = std::mem::replace(expr, Expr::new(ExprKind::NoneLit, span));
    *expr = Expr {
        kind: ExprKind::Wrap(Box::new(inner)),
        span,
        ty: Some(ty.clone()),
    };
}

fn extract_hint(types: &[&Type]) -> String {
    match types
        .iter()
        .find(|t| matches!(t, Type::Maybe(_) | Type::Or(..) | Type::Fail(_)))
    {
        Some(Type::Fail(_)) => {
            "; 'fail' takes only the value right after it, so write 'fail (a + b)'".to_string()
        }
        Some(Type::Or(value, error)) if **value == Type::Nothing => {
            format!(
                "; a 'nothing ~ {}' has no value, only an error to handle, as in 'x {{ failure e … }}'",
                error
            )
        }
        Some(ty) => format!(
            "; the value in this {} must be extracted first, as in 'x {{ … }}' or 'when x is {{value}}'",
            ty
        ),
        None => String::new(),
    }
}

pub fn lasting(ty: &Type, regional: &HashSet<String>) -> Type {
    let any = Some(ANY_REGION.to_string());
    match ty {
        Type::Text(region) if *region == any => Type::Text(None),
        Type::Named(name, region) if *region == any && !regional.contains(name) => {
            Type::Named(name.clone(), None)
        }
        Type::Applied(applied) if applied.region == any && !regional.contains(&applied.name) => {
            Type::Applied(Box::new(Applied {
                region: None,
                ..(**applied).clone()
            }))
        }
        Type::Maybe(inner) => Type::Maybe(Box::new(lasting(inner, regional))),
        Type::Array(inner, count) => Type::Array(Box::new(lasting(inner, regional)), *count),
        Type::Or(value, error) => Type::Or(
            Box::new(lasting(value, regional)),
            Box::new(lasting(error, regional)),
        ),
        Type::Tuple(items) => {
            Type::Tuple(items.iter().map(|item| lasting(item, regional)).collect())
        }
        other => other.clone(),
    }
}

pub fn regional_types(items: &[Item]) -> HashSet<String> {
    types_holding(items, holds_pointers)
}

pub fn textual_types(items: &[Item]) -> HashSet<String> {
    types_holding(items, holds_text)
}

fn types_holding(items: &[Item], holds: fn(&Type, &HashSet<String>) -> bool) -> HashSet<String> {
    let fields_of = |item: &Item| -> Vec<Type> {
        match item {
            Item::Shape(s) => s.fields.iter().map(|f| f.ty.clone()).collect(),
            Item::Kind(k) => k
                .variants
                .iter()
                .flat_map(|v| &v.payload)
                .map(|f| f.ty.clone())
                .collect(),
            Item::Task(_) | Item::Macro(_) | Item::GlobalRegion(_) => Vec::new(),
        }
    };
    let mut users: HashMap<String, Vec<usize>> = HashMap::new();
    for (i, item) in items.iter().enumerate() {
        for ty in fields_of(item) {
            for name in named_types(&ty) {
                users.entry(name.to_string()).or_default().push(i);
            }
        }
    }
    let mut regional = HashSet::new();
    let mut pending: Vec<usize> = (0..items.len()).collect();
    while let Some(i) = pending.pop() {
        let name = match items.get(i) {
            Some(Item::Shape(s)) => &s.name,
            Some(Item::Kind(k)) => &k.name,
            _ => continue,
        };
        if !regional.contains(name)
            && items
                .get(i)
                .map(fields_of)
                .unwrap_or_default()
                .iter()
                .any(|ty| holds(ty, &regional))
        {
            regional.insert(name.clone());
            pending.extend(users.get(name).into_iter().flatten().copied());
        }
    }
    regional
}

pub fn in_region(ty: &Type, region: &str, takes_region: &HashSet<String>) -> Type {
    ty.map_regions_of_names(&mut |name| {
        (name.is_empty() || takes_region.contains(name)).then(|| region.to_string())
    })
}

fn fits_regions(actual: &Type, expected: &Type) -> bool {
    if actual.unknown() || expected.unknown() {
        return true;
    }
    let region =
        |a: &Option<String>, e: &Option<String>| a == e || a.as_deref() == Some(ANY_REGION);
    let lasting = |a: &Option<String>, e: &Option<String>| {
        region(a, e) || a.is_none() || (a.as_deref() == Some("global") && e.is_some())
    };
    match (actual, expected) {
        (Type::Ptr(a, ar), Type::Ptr(e, er)) | (Type::Slice(a, ar), Type::Slice(e, er)) => {
            region(ar, er) && fits_regions(a, e)
        }
        (Type::Map(ak, av, ar), Type::Map(ek, ev, er)) => {
            region(ar, er) && fits_regions(ak, ek) && fits_regions(av, ev)
        }
        (Type::Array(a, an), Type::Array(e, en)) => an == en && fits_regions(a, e),
        (Type::Applied(a), Type::Applied(e))
            if a.name == e.name && a.types.len() == e.types.len() =>
        {
            lasting(&a.region, &e.region)
                && a.types
                    .iter()
                    .zip(&e.types)
                    .all(|(a, e)| fits_regions(a, e))
        }
        (Type::Text(ar), Type::Text(er)) => lasting(ar, er),
        (Type::Named(a, ar), Type::Named(e, er)) => a == e && lasting(ar, er),
        (Type::Range(a), Type::Range(e))
        | (Type::Maybe(a), Type::Maybe(e))
        | (Type::Fail(a), Type::Fail(e)) => fits_regions(a, e),
        (Type::Or(av, ae), Type::Or(ev, ee)) => fits_regions(av, ev) && fits_regions(ae, ee),
        (Type::Tuple(a), Type::Tuple(e)) => {
            a.len() == e.len() && a.iter().zip(e).all(|(a, e)| fits_regions(a, e))
        }
        (Type::Closure(a), Type::Closure(e)) => {
            a.region == e.region && task_fits(&a.task, &e.task) && a.mode <= e.mode
        }
        (Type::Task(a), Type::Task(e)) => task_fits(a, e),
        (Type::Chan(a), Type::Chan(e)) => {
            let a_inner = match a.as_ref() { Type::Own(t) => t.as_ref(), other => other };
            let e_inner = match e.as_ref() { Type::Own(t) => t.as_ref(), other => other };
            fits_regions(a_inner, e_inner)
        }
        (Type::Own(a), Type::Own(e)) => fits_regions(a, e),
        (Type::Own(a), e) => fits_regions(a, e),
        (a, Type::Own(e)) => fits_regions(a, e),
        _ => actual == expected,
    }
}

fn ordinal(k: usize) -> String {
    match k {
        1 => "first".to_string(),
        2 => "second".to_string(),
        3 => "third".to_string(),
        k if (11..=13).contains(&(k % 100)) => format!("{}th", k),
        k => format!(
            "{}{}",
            k,
            ["th", "st", "nd", "rd"].get(k % 10).unwrap_or(&"th")
        ),
    }
}

/// Tasks mutating less (`fixed`) fit callbacks expecting more (`flex`/`bind`), never the reverse.
fn task_fits(actual: &TaskType, expected: &TaskType) -> bool {
    // Normalize region names so `this` aligns cleanly across both signatures.
    let (actual, expected) = (actual.normalized(), expected.normalized());
    // Regionless params reject regional `@r` signatures, while wildcard `@_` lambdas fit explicit `@this`.
    actual.params.len() == expected.params.len()
        && actual.params.iter().zip(&expected.params).all(|(a, e)| {
            fits_regions(a, e) && !(a.regions().is_empty() && !e.regions().is_empty())
        })
        && fits_regions(&actual.ret, &expected.ret)
        && actual.taken.len() == expected.taken.len()
        && actual.taken.iter().zip(&expected.taken).all(|(a, e)| {
            a == e
                || (*a == Taken::Value && matches!(e, Taken::Flex | Taken::Bind))
                || (*a == Taken::Bind && *e == Taken::Flex)
        })
}

pub fn gives_value(stmt: &Stmt) -> bool {
    matches!(&stmt.kind, StmtKind::Match(..) | StmtKind::When(_, Some(_)))
}

fn fits(from: &Type, to: &Type) -> bool {
    if fits_regions(from, to) {
        return true;
    }
    match to {
        Type::Maybe(inner) => *from == Type::None || fits_regions(from, inner),
        Type::Or(value, error) => match from {
            Type::Fail(given) => fits_regions(given, error),
            other => fits_regions(other, value),
        },
        _ => false,
    }
}

/// True if converting `from` -> `to` would require rewriting existing container elements (disallowed).
fn remade_inside(from: &Type, to: &Type) -> bool {
    if fits(from, to) {
        return false;
    }
    match (from, to) {
        (Type::Maybe(a), Type::Maybe(b)) | (Type::Fail(a), Type::Fail(b)) => {
            fits(a, b) || remade_inside(a, b)
        }
        (Type::Or(value, error), Type::Or(other, known)) => {
            fits_regions(error, known) && (fits(value, other) || remade_inside(value, other))
        }
        (Type::Array(a, an), Type::Array(b, bn)) => an == bn && (fits(a, b) || remade_inside(a, b)),
        (Type::Tuple(a), Type::Tuple(b)) => {
            a.len() == b.len()
                && a.iter()
                    .zip(b)
                    .all(|(a, b)| fits(a, b) || remade_inside(a, b))
        }
        _ => false,
    }
}

/// Returns `(outer, inner)` if `ty` stores a value of one region inside another (ignoring literal text).
fn region_conflict(ty: &Type, inside: Option<&str>) -> Option<(String, String)> {
    let conflict = |region: &str| -> Option<(String, String)> {
        let inside = inside?;
        (region != inside && region != ANY_REGION && inside != ANY_REGION)
            .then(|| (inside.to_string(), region.to_string()))
    };
    match ty {
        Type::Ptr(inner, region) | Type::Slice(inner, region) => match region.as_deref() {
            Some(region) => conflict(region).or_else(|| region_conflict(inner, Some(region))),
            None => region_conflict(inner, inside),
        },
        Type::Map(key, value, region) => {
            let inside = region.as_deref().or(inside);
            region
                .as_deref()
                .and_then(conflict)
                .or_else(|| region_conflict(key, inside))
                .or_else(|| region_conflict(value, inside))
        }
        Type::Text(Some(region)) | Type::Named(_, Some(region)) => conflict(region),
        Type::Applied(applied) => match applied.region.as_deref() {
            Some(region) => conflict(region).or_else(|| {
                applied
                    .types
                    .iter()
                    .find_map(|ty| region_conflict(ty, Some(region)))
            }),
            None => applied
                .types
                .iter()
                .find_map(|ty| region_conflict(ty, inside)),
        },
        Type::Maybe(inner) | Type::Array(inner, _) | Type::Fail(inner) | Type::Range(inner) => {
            region_conflict(inner, inside)
        }
        Type::Or(value, error) => {
            region_conflict(value, inside).or_else(|| region_conflict(error, inside))
        }
        Type::Tuple(types) | Type::Results(types) => {
            types.iter().find_map(|ty| region_conflict(ty, inside))
        }
        Type::Closure(closure) => conflict(&closure.region),
        _ => None,
    }
}

fn type_size(ty: &Type) -> usize {
    let mut count = 0;
    let mut pending = vec![ty];
    while let Some(ty) = pending.pop() {
        count += 1;
        if count > MAX_TYPE_SIZE {
            break;
        }
        match ty {
            Type::Ptr(inner, _)
            | Type::Slice(inner, _)
            | Type::Array(inner, _)
            | Type::Range(inner)
            | Type::Maybe(inner)
            | Type::Fail(inner) => pending.push(inner),
            Type::Or(value, error) | Type::Map(value, error, _) => {
                pending.extend([&**value, &**error])
            }
            Type::Applied(applied) => pending.extend(&applied.types),
            Type::Tuple(types) | Type::Results(types) => pending.extend(types),
            Type::Task(task) => {
                pending.extend(&task.params);
                pending.push(&task.ret);
            }
            Type::Closure(closure) => {
                pending.extend(&closure.task.params);
                pending.push(&closure.task.ret);
            }
            _ => {}
        }
    }
    count
}

fn type_depth(ty: &Type) -> usize {
    let inner = match ty {
        Type::Ptr(inner, _)
        | Type::Slice(inner, _)
        | Type::Array(inner, _)
        | Type::Range(inner)
        | Type::Maybe(inner)
        | Type::Fail(inner) => type_depth(inner),
        Type::Or(value, error) | Type::Map(value, error, _) => {
            type_depth(value).max(type_depth(error))
        }
        Type::Applied(applied) => applied.types.iter().map(type_depth).max().unwrap_or(0),
        Type::Tuple(types) | Type::Results(types) => {
            types.iter().map(type_depth).max().unwrap_or(0)
        }
        Type::Task(task) => task
            .params
            .iter()
            .chain([&task.ret])
            .map(type_depth)
            .max()
            .unwrap_or(0),
        Type::Closure(closure) => closure
            .task
            .params
            .iter()
            .chain([&closure.task.ret])
            .map(type_depth)
            .max()
            .unwrap_or(0),
        _ => 0,
    };
    inner + 1
}

fn header_regions(task: &TaskDef) -> HashSet<String> {
    let mut regions: HashSet<String> = task
        .params
        .iter()
        .filter(|param| param.ty == Type::Region)
        .map(|param| param.name.clone())
        .collect();
    for ty in task
        .params
        .iter()
        .map(|param| &param.ty)
        .chain(task.ret.results())
    {
        regions.extend(ty.regions().into_iter().map(str::to_string));
    }
    regions
}

fn keeps_params(task: &TaskDef) -> HashMap<String, HashSet<String>> {
    let mut kept: HashMap<String, HashSet<String>> = HashMap::new();
    for ty in task
        .params
        .iter()
        .map(|param| &param.ty)
        .chain(task.ret.results())
    {
        keeps_params_of(ty, None, &mut kept);
    }
    kept
}

fn keeps_params_of(ty: &Type, inside: Option<&str>, kept: &mut HashMap<String, HashSet<String>>) {
    match ty {
        Type::Param(name) => {
            if let Some(region) = inside {
                kept.entry(name.clone())
                    .or_default()
                    .insert(region.to_string());
            }
        }
        Type::Ptr(inner, region) | Type::Slice(inner, region) => {
            keeps_params_of(inner, region.as_deref().or(inside), kept)
        }
        Type::Map(key, value, region) => {
            keeps_params_of(key, region.as_deref().or(inside), kept);
            keeps_params_of(value, region.as_deref().or(inside), kept);
        }
        Type::Array(inner, _) | Type::Range(inner) | Type::Maybe(inner) | Type::Fail(inner) => {
            keeps_params_of(inner, inside, kept)
        }
        Type::Or(value, error) => {
            keeps_params_of(value, inside, kept);
            keeps_params_of(error, inside, kept);
        }
        Type::Tuple(types) | Type::Results(types) => types
            .iter()
            .for_each(|ty| keeps_params_of(ty, inside, kept)),
        Type::Applied(applied) => applied
            .types
            .iter()
            .for_each(|ty| keeps_params_of(ty, applied.region.as_deref().or(inside), kept)),
        _ => {}
    }
}

#[derive(Default)]
struct Made {
    needed: Vec<(String, Vec<Type>, Span)>,
    copies: Vec<(String, String, Span)>,
    placeless: Vec<(Span, Type)>,
    chosen: HashMap<String, (Type, Type)>,
    reads_chosen: Vec<(Span, String, String)>,
    past_items: Vec<(Span, usize, usize)>,
}

impl Checker {
    fn substitute_task(
        &mut self,
        task: &mut TaskDef,
        given: &HashMap<String, Type>,
        made: &mut Made,
    ) -> Result<()> {
        if let Some(at) = task
            .params
            .iter()
            .position(|param| matches!(param.ty, Type::Group(_)))
            && let Some(Field {
                ty: Type::Group(group),
                ..
            }) = task.params.get(at)
            && let Some((types, taken)) = group_items(given, group)
        {
            let param = task.params.remove(at);
            let values = types
                .into_iter()
                .zip(taken)
                .enumerate()
                .map(|(i, (ty, how))| Field {
                    name: group_value(&param.name, i),
                    ty,
                    passing: task_passing(&how),
                    ..param.clone()
                });
            task.params.splice(at..at, values);
        }
        let alters = task.owner.as_ref().is_some_and(|owner| owner.alters);
        for param in &mut task.params {
            let takes = !param.ty.params().is_empty();
            let declared = param.ty.clone();
            self.substitute_type(&mut param.ty, given, param.ty_span)?;
            if takes
                && param.passing == Passing::Copy
                && param.ty != Type::Region
                && !(alters && param.name == THIS)
            {
                made.chosen
                    .insert(param.name.clone(), (param.ty.clone(), declared));
            }
        }
        let at = task.span;
        self.substitute_type(&mut task.ret, given, at)?;
        self.substitute_block(&mut task.body, given, made)
    }

    fn substitute_type(
        &mut self,
        ty: &mut Type,
        given: &HashMap<String, Type>,
        at: Span,
    ) -> Result<()> {
        *ty = in_copy(ty, given);
        self.settle_applications(ty, at)
    }

    fn substitute_block(
        &mut self,
        block: &mut Block,
        given: &HashMap<String, Type>,
        made: &mut Made,
    ) -> Result<()> {
        block
            .iter_mut()
            .try_for_each(|stmt| self.substitute_stmt(stmt, given, made))
    }

    fn substitute_stmt(
        &mut self,
        stmt: &mut Stmt,
        given: &HashMap<String, Type>,
        made: &mut Made,
    ) -> Result<()> {
        let at = stmt.span;
        match &mut stmt.kind {
            StmtKind::Expr(e) => self.substitute_expr(e, given, made),
            StmtKind::Step { target, value, .. } => {
                self.substitute_expr(target, given, made)?;
                self.substitute_expr(value, given, made)
            }
            StmtKind::Send(values) | StmtKind::SetResults(_, values) => values
                .iter_mut()
                .try_for_each(|value| self.substitute_expr(value, given, made)),
            StmtKind::Break(_, Some(value)) => self.substitute_expr(value, given, made),
            StmtKind::Region { .. } | StmtKind::Break(..) | StmtKind::Continue(_) => Ok(()),
            StmtKind::Named(_, inner) => self.substitute_stmt(inner, given, made),
            StmtKind::Turns(turns) => turns
                .iter_mut()
                .try_for_each(|turn| self.substitute_block(turn, given, made)),
            StmtKind::Binding { names, init, .. } => {
                for bound in names.iter_mut() {
                    self.substitute_bound(bound, given, at)?;
                }
                init.iter_mut()
                    .try_for_each(|value| self.substitute_expr(value, given, made))
            }
            StmtKind::Assign(targets, values) => {
                for target in targets.iter_mut() {
                    self.substitute_target(target, given, made)?;
                }
                values
                    .iter_mut()
                    .try_for_each(|value| self.substitute_expr(value, given, made))
            }
            StmtKind::When(arms, else_block) => {
                // Dead `when` arms known false at instantiation are cleared without dropping the enclosing expression.
                let (mut taken, mut cut) = (false, arms.len());
                for (i, arm) in arms.iter_mut().enumerate() {
                    self.substitute_condition(&mut arm.cond, &mut arm.body, given, made)?;
                    match known_condition(&arm.cond).filter(|_| !given.is_empty()) {
                        Some(false) => arm.body.clear(),
                        Some(true) => taken = true,
                        None => {}
                    }
                    self.substitute_block(&mut arm.body, given, made)?;
                    if taken {
                        cut = i + 1;
                        break;
                    }
                }
                if taken {
                    arms.truncate(cut);
                }
                if taken && let Some(dropped) = else_block {
                    dropped.clear();
                }
                match else_block {
                    Some(else_block) => self.substitute_block(else_block, given, made),
                    None => Ok(()),
                }
            }
            StmtKind::Block(body) => self.substitute_block(body, given, made),
            StmtKind::Loop(cond, body, finally) => {
                self.substitute_condition(cond, body, given, made)?;
                self.substitute_block(body, given, made)?;
                if let Some(finally) = finally {
                    self.substitute_block(finally, given, made)?;
                }
                Ok(())
            }
            StmtKind::Parted(parted) => {
                self.substitute_block(&mut parted.start, given, made)?;
                if let Some(cond) = &mut parted.cond {
                    self.substitute_condition(cond, &mut parted.body, given, made)?;
                }
                self.substitute_block(&mut parted.step, given, made)?;
                self.substitute_block(&mut parted.body, given, made)?;
                if let Some(finally) = &mut parted.finally {
                    self.substitute_block(finally, given, made)?;
                }
                Ok(())
            }
            StmtKind::Each(name, _, range, body, _) if matches!(&range.ty, Some(Type::Group(group)) if group_types(given, group).is_some()) =>
            {
                let (name, range, body) = (name.clone(), range.clone(), std::mem::take(body));
                stmt.kind = self.each_of_group(&name, &range, body, given, made, at)?;
                Ok(())
            }
            StmtKind::Each(_, _, range, body, finally) => {
                self.substitute_expr(range, given, made)?;
                self.substitute_block(body, given, made)?;
                if let Some(finally) = finally {
                    self.substitute_block(finally, given, made)?;
                }
                Ok(())
            }
            StmtKind::Match(subject, cases) => {
                self.substitute_expr(subject, given, made)?;
                cases
                    .iter_mut()
                    .try_for_each(|case| self.substitute_block(&mut case.body, given, made))
            }
        }
    }

    fn substitute_group_tuple(
        &mut self,
        e: &mut Expr,
        given: &HashMap<String, Type>,
        made: &mut Made,
    ) -> Result<bool> {
        let span = e.span;
        let ExprKind::Field(inner, member) = &mut e.kind else {
            return Ok(false);
        };
        let group = match &inner.ty {
            Some(Type::Group(group)) if member == GROUP_TUPLE => group.clone(),
            Some(Type::Tuple(items)) if group_in_tuple(items).is_some() => {
                group_in_tuple(items).unwrap_or_default()
            }
            _ => return Ok(false),
        };
        let Some(types) = group_types(given, &group) else {
            return Ok(false);
        };
        let generic = e.ty.clone().unwrap_or(Type::Unknown);
        let ty = in_copy(&generic, given);
        if member == GROUP_TUPLE {
            let ExprKind::Var(values) = &inner.kind else {
                return Err(Error::internal_at(
                    span,
                    "a group's tuple made of no group's values",
                ));
            };
            let value = |place: usize, ty: &Type| {
                let mut value = Expr::new(ExprKind::Var(group_value(values, place)), span);
                value.ty = Some(ty.clone());
                value
            };
            let typed = |kind: ExprKind, ty: Type| {
                let mut made = Expr::new(kind, span);
                made.ty = Some(ty);
                made
            };
            let made_value = match types.as_slice() {
                [] | [_] => {
                    let one = match types.first() {
                        Some(first) => typed(
                            ExprKind::Wrap(Box::new(value(0, first))),
                            Type::Maybe(Box::new(first.clone())),
                        ),
                        None => typed(
                            ExprKind::Wrap(Box::new(typed(ExprKind::NoneLit, Type::None))),
                            Type::Maybe(Box::new(placeholder_type())),
                        ),
                    };
                    let failed = one.ty.clone().unwrap_or(Type::Unknown);
                    typed(ExprKind::Fail(Box::new(one)), Type::Fail(Box::new(failed)))
                }
                _ => {
                    let values: Vec<Expr> = types
                        .iter()
                        .enumerate()
                        .map(|(place, ty)| value(place, ty))
                        .collect();
                    typed(ExprKind::Tuple(values), Type::Tuple(types.clone()))
                }
            };
            e.kind = ExprKind::Wrap(Box::new(made_value));
            e.ty = Some(ty);
            return Ok(true);
        }
        let safe = member.starts_with(SAFE_ITEM);
        let Ok(place) = member.trim_start_matches(SAFE_ITEM).parse::<usize>() else {
            return Ok(false);
        };
        let count = types.len();
        self.substitute_expr(inner, given, made)?;
        // Group tuples with < 2 elements never construct at runtime; keep index placeholders unevaluated.
        let there = place < count && count >= 2;
        if !safe {
            if place >= count.max(2) {
                made.past_items.push((span, place, count));
            }
            e.ty = Some(ty);
            return Ok(true);
        }
        let item = types.get(place).cloned().filter(|_| there);
        let mut read = Expr::new(ExprKind::Field(inner.clone(), place.to_string()), span);
        match item {
            Some(item) => {
                read.ty = Some(item);
                e.kind = ExprKind::Wrap(Box::new(read));
            }
            None => {
                read.kind = ExprKind::Field(inner.clone(), member.clone());
                read.ty = Some(Type::None);
                e.kind = ExprKind::Wrap(Box::new(read));
            }
        }
        e.ty = Some(ty);
        Ok(true)
    }

    fn each_of_group(
        &mut self,
        name: &str,
        range: &Expr,
        body: Block,
        given: &HashMap<String, Type>,
        made: &mut Made,
        at: Span,
    ) -> Result<StmtKind> {
        let (Some(Type::Group(group)), ExprKind::Var(values)) = (&range.ty, &range.kind) else {
            return Err(Error::internal_at(
                at,
                "a loop over a group's values that names none",
            ));
        };
        let mut turns = Vec::new();
        for (place, ty) in group_types(given, group)
            .unwrap_or_default()
            .into_iter()
            .enumerate()
        {
            let mut turn_given = given.clone();
            turn_given.insert(format!("{}{}", group, GROUP_TURN), ty.clone());
            let mut turn_body = body.clone();
            self.substitute_block(&mut turn_body, &turn_given, made)?;
            let bound = Bound {
                name: name.to_string(),
                span: at,
                ty: Some(ty.clone()),
                ty_span: None,
                parts: Vec::new(),
            };
            let mut value = Expr::new(ExprKind::Var(group_value(values, place)), at);
            value.ty = Some(ty);
            let mut turn = vec![Stmt::new(
                StmtKind::Binding {
                    names: vec![bound],
                    mode: Mode::Fixed,
                    reference: false,
                    init: vec![value],
                    colon: false,
                },
                at,
            )];
            turn.extend(turn_body);
            turns.push(turn);
        }
        Ok(StmtKind::Turns(turns))
    }

    fn substitute_bound(
        &mut self,
        bound: &mut Bound,
        given: &HashMap<String, Type>,
        at: Span,
    ) -> Result<()> {
        if let Some(ty) = &mut bound.ty {
            *ty = in_copy(ty, given);
            self.settle_applications(ty, at)?;
        }
        bound
            .parts
            .iter_mut()
            .try_for_each(|part| self.substitute_bound(part, given, at))
    }

    fn substitute_target(
        &mut self,
        target: &mut Target,
        given: &HashMap<String, Type>,
        made: &mut Made,
    ) -> Result<()> {
        match target {
            Target::Discard(_) => Ok(()),
            Target::Place(place) => self.substitute_expr(place, given, made),
            Target::Tuple(parts, _) => parts
                .iter_mut()
                .try_for_each(|part| self.substitute_target(part, given, made)),
        }
    }

    fn need_written_strs(&self, value: &Expr, made: &mut Made) {
        let Some(ty) = &value.ty else { return };
        let mut found = Vec::new();
        self.written_strs(ty, &mut Vec::new(), &mut found);
        made.needed.extend(
            found
                .into_iter()
                .map(|(method, types)| (method, types, value.span)),
        );
    }

    /// Prunes falsified condition tails per instantiation so guarded past-end tuple reads are never lowered.
    fn substitute_condition(
        &mut self,
        cond: &mut Condition,
        body: &mut Block,
        given: &HashMap<String, Type>,
        made: &mut Made,
    ) -> Result<()> {
        let mut done = 0;
        while let Some(current) = cond.part_mut(done) {
            self.substitute_expr(&mut current.value, given, made)?;
            self.settle_type_tests(cond, body);
            done += 1;
            let Some(last) = cond
                .parts()
                .take(done)
                .position(|part| known_part(part) == Some(false))
                .filter(|_| !given.is_empty())
            else {
                continue;
            };
            if cond
                .parts()
                .take(last + 1)
                .any(|part| !without_effects(&part.value))
                && let Some(part) = cond.part_mut(last)
            {
                part.and = None;
            } else {
                let mut never = Expr::new(ExprKind::BoolLit(false), cond.value.span);
                never.ty = Some(Type::Bool);
                *cond = Condition::new(never, None);
            }
            body.clear();
            break;
        }
        Ok(())
    }

    fn substitute_expr(
        &mut self,
        e: &mut Expr,
        given: &HashMap<String, Type>,
        made: &mut Made,
    ) -> Result<()> {
        if let ExprKind::Copy {
            region: Some(region),
            ..
        } = &e.kind
            && let Some(ty) = &e.ty
        {
            for param in ty.params() {
                made.copies
                    .push((param.to_string(), region.clone(), e.span));
            }
        }
        let at = e.span;
        if self.substitute_group_tuple(e, given, made)? {
            return Ok(());
        }
        if let Some(ty) = &mut e.ty {
            *ty = in_copy(ty, given);
            self.settle_applications(ty, at)?;
        }
        // Short-circuit known `false and b` / `true or b` so dead RHS indexing/reads are pruned.
        if let ExprKind::Binary(op @ (BinaryOp::And | BinaryOp::Or), a, _) = &mut e.kind {
            let decides = *op == BinaryOp::Or;
            self.substitute_expr(a, given, made)?;
            if !given.is_empty() && known_bool(a) == Some(decides) {
                if without_effects(a) {
                    e.kind = ExprKind::BoolLit(decides);
                } else if let ExprKind::Binary(_, _, b) = &mut e.kind {
                    let mut known = Expr::new(ExprKind::BoolLit(decides), b.span);
                    known.ty = Some(Type::Bool);
                    **b = known;
                }
            } else if let ExprKind::Binary(_, _, b) = &mut e.kind {
                self.substitute_expr(b, given, made)?;
            }
            return Ok(());
        }
        match &mut e.kind {
            ExprKind::Spread(inner)
            | ExprKind::Kept { value: inner, .. }
            | ExprKind::Own(inner) => {
                self.substitute_expr(inner, given, made)
            }
            ExprKind::Closure { .. } => Ok(()),
            ExprKind::Call { name, types, args } => {
                if let Some((pattern, method)) = pattern_call_parts(name)
                    && let Some(receiver) = args.first().and_then(|arg| arg.ty.as_ref())
                {
                    let own = self
                        .patterns
                        .get(pattern)
                        .and_then(|def| def.method(method))
                        .map_or(0, |def| def.types.len());
                    let own_types: Vec<TypeArg> = types
                        .iter()
                        .skip(types.len().saturating_sub(own))
                        .cloned()
                        .collect();
                    let method = method.to_string();
                    let mut receiver = in_copy(receiver, given);
                    self.settle_applications(&mut receiver, at)?;
                    let owner = match self.owner_of(&receiver) {
                        Some(owner) => owner,
                        None if !receiver.params().is_empty() => {
                            return args
                                .iter_mut()
                                .try_for_each(|arg| self.substitute_expr(arg, given, made));
                        }
                        None => {
                            return Err(Error::internal_at(
                                at,
                                format!(
                                    "a call of a pattern's method '{}' on {}, which follows no pattern",
                                    method, receiver
                                ),
                            ));
                        }
                    };
                    match self.unmade(&receiver) {
                        Type::Applied(made) => {
                            *name = method_name(&made.name, &method);
                            *types = made
                                .types
                                .iter()
                                .map(|ty| (ty.without_regions(), at))
                                .chain(own_types)
                                .collect();
                        }
                        _ => {
                            *name = method_name(&owner, &method);
                            *types = own_types;
                        }
                    }
                }
                // Group tuples shorter than 2 elements stay unpadded in type args; runtime tuples pad to 2 (`padded_group_tuples`).
                let groups: Vec<bool> = self
                    .tasks
                    .get(name.as_str())
                    .map(|info| info.types.iter().map(|param| param.group).collect())
                    .unwrap_or_default();
                for (i, (ty, _)) in types.iter_mut().enumerate() {
                    *ty = match groups.get(i) {
                        Some(true) => group_given_in_copy(ty, given),
                        _ => in_copy(ty, given),
                    };
                    self.settle_applications(ty, at)?;
                }
                if !types.is_empty() {
                    made.needed.push((
                        name.clone(),
                        types.iter().map(|(ty, _)| ty.clone()).collect(),
                        at,
                    ));
                }
                args.iter_mut()
                    .try_for_each(|arg| self.substitute_expr(arg, given, made))?;
                spread_values(args, given, name != "show");
                if name == "show" {
                    for arg in args.iter() {
                        self.need_written_strs(arg, made);
                        note_chosen_address(arg, made);
                    }
                }
                Ok(())
            }
            ExprKind::ToJson { value, .. } => {
                self.substitute_expr(value, given, made)?;
                if let Some(ty) = &value.ty {
                    self.json_writes(ty, value.span)?;
                }
                self.need_written_strs(value, made);
                note_chosen_address(value, made);
                Ok(())
            }
            ExprKind::ToText { value, .. } => {
                self.substitute_expr(value, given, made)?;
                self.need_written_strs(value, made);
                note_chosen_address(value, made);
                Ok(())
            }
            ExprKind::StructInit {
                name,
                types,
                fields,
            } => {
                for (ty, _) in types.iter_mut() {
                    self.substitute_type(ty, given, at)?;
                }
                if !types.is_empty() && types.iter().all(|(ty, _)| ty.params().is_empty()) {
                    let made_types: Vec<Type> = types.iter().map(|(ty, _)| ty.clone()).collect();
                    *name = self.shape_instance(&name.clone(), &made_types, at)?;
                    types.clear();
                }
                fields
                    .iter_mut()
                    .try_for_each(|field| self.substitute_expr(&mut field.value, given, made))
            }
            ExprKind::New {
                ty, ty_span, value, ..
            } => {
                let ty_span = *ty_span;
                self.substitute_type(ty, given, ty_span)?;
                self.substitute_expr(value, given, made)
            }
            ExprKind::TypeOf(ty) => {
                self.substitute_type(ty, given, at)?;
                if ty.params().is_empty() {
                    e.kind = ExprKind::TextLit(self.written_type(ty));
                }
                Ok(())
            }
            ExprKind::IntLit(_)
            | ExprKind::FloatLit(_)
            | ExprKind::CharLit(_)
            | ExprKind::BoolLit(_)
            | ExprKind::TextLit(_)
            | ExprKind::NoneLit
            | ExprKind::Macro { .. }
            | ExprKind::Var(_)
            | ExprKind::RegionAfter(_)
            | ExprKind::Shared { .. }
            | ExprKind::TaskValue(_) => Ok(()),
            ExprKind::Invoke { callee, args } => {
                self.substitute_expr(callee, given, made)?;
                args.iter_mut()
                    .try_for_each(|arg| self.substitute_expr(arg, given, made))?;
                spread_values(args, given, true);
                Ok(())
            }
            ExprKind::Field(inner, member)
                if member == "len"
                    && matches!(&inner.ty, Some(Type::Group(group)) if group_types(given, group).is_some()) =>
            {
                let count = match &inner.ty {
                    Some(Type::Group(group)) => {
                        group_types(given, group).map_or(0, |types| types.len())
                    }
                    _ => 0,
                };
                // Emit `count + 0` so C runtime bounds/arithmetic checks run instead of trusting `codegen::int_constant`.
                let int = |n: i64| {
                    let mut lit = Expr::new(ExprKind::IntLit(n), e.span);
                    lit.ty = Some(Type::Int);
                    Box::new(lit)
                };
                e.kind = ExprKind::Binary(
                    BinaryOp::Add,
                    int(i64::try_from(count).unwrap_or(i64::MAX)),
                    int(0),
                );
                Ok(())
            }
            ExprKind::Unary(_, inner)
            | ExprKind::Deref(inner)
            | ExprKind::Ref(inner)
            | ExprKind::Field(inner, _)
            | ExprKind::Fail(inner)
            | ExprKind::Wrap(inner)
            | ExprKind::Widen(inner)
            | ExprKind::Pipe(inner)
            | ExprKind::Piped(inner)
            | ExprKind::Copy { value: inner, .. }
            | ExprKind::Shortcut { value: inner, .. } => self.substitute_expr(inner, given, made),
            ExprKind::Pairs(pairs) => pairs.iter_mut().try_for_each(|(key, value)| {
                self.substitute_expr(key, given, made)?;
                self.substitute_expr(value, given, made)
            }),
            ExprKind::MapOp { map, key, .. } => {
                self.substitute_expr(map, given, made)?;
                key.as_deref_mut()
                    .map_or(Ok(()), |key| self.substitute_expr(key, given, made))
            }
            ExprKind::Binary(op @ (BinaryOp::Eq | BinaryOp::Ne), a, b) => {
                let symbol = if *op == BinaryOp::Ne { "!=" } else { "==" };
                self.substitute_expr(a, given, made)?;
                self.substitute_expr(b, given, made)?;
                if let Some(ty) = a.ty.clone()
                    && !matches!(a.kind, ExprKind::Ref(_))
                    && !matches!(b.kind, ExprKind::Ref(_))
                    && self.by_place(&ty)
                    && !(names_place(a) && names_place(b))
                {
                    made.placeless.push((at, ty.clone()));
                }
                let places = [&**a, &**b].map(|side| match &side.kind {
                    ExprKind::Ref(place) => place.as_ref(),
                    _ => side,
                });
                if same_root(places[0], places[1]) {
                } else if [&**a, &**b]
                    .iter()
                    .any(|side| matches!(side.kind, ExprKind::Ref(_)))
                {
                    note_chosen_address(a, made);
                    note_chosen_address(b, made);
                } else if let Some(ty) = &a.ty
                    && self.by_place(ty)
                {
                    let what = self.compared_by_place(symbol, ty);
                    for side in [&**a, &**b] {
                        if let Some((name, at)) =
                            param_root(side).filter(|(name, _)| made.chosen.contains_key(*name))
                        {
                            made.reads_chosen.push((at, what.clone(), name.to_string()));
                        }
                    }
                }
                Ok(())
            }
            ExprKind::Binary(_, a, b)
            | ExprKind::Index(a, b)
            | ExprKind::Lookup(a, b)
            | ExprKind::Range(a, b)
            | ExprKind::Repeat { value: a, count: b } => {
                self.substitute_expr(a, given, made)?;
                self.substitute_expr(b, given, made)
            }
            ExprKind::Construct { args, .. }
            | ExprKind::Array(args)
            | ExprKind::Tuple(args)
            | ExprKind::Scan { args, .. }
            | ExprKind::Join { parts: args, .. } => args
                .iter_mut()
                .try_for_each(|arg| self.substitute_expr(arg, given, made)),
            ExprKind::PlanB { value, body, .. } => {
                self.substitute_expr(value, given, made)?;
                self.substitute_block(body, given, made)
            }
            ExprKind::Choice(stmt) => self.substitute_stmt(stmt, given, made),
            ExprKind::LoopValue(value) => self.substitute_stmt(&mut value.stmt, given, made),
            ExprKind::Edit { items, args, .. } => {
                self.substitute_expr(items, given, made)?;
                args.iter_mut()
                    .try_for_each(|arg| self.substitute_expr(arg, given, made))
            }
            ExprKind::MethodCall { name, .. } => Err(Error::internal_at(
                at,
                format!("the method call '{}' was never rewritten", name),
            )),
        }
    }
}

fn unify_params(pattern: &Type, actual: &Type, given: &mut HashMap<String, Type>) {
    if *actual == Type::None || matches!(actual, Type::Fail(_)) || is_untold(actual) {
        return;
    }
    match (pattern, actual) {
        (Type::Param(name), _) => {
            given.entry(name.clone()).or_insert_with(|| actual.clone());
        }
        (Type::Ptr(p, _), Type::Ptr(a, _))
        | (Type::Slice(p, _), Type::Slice(a, _))
        | (Type::Array(p, _), Type::Array(a, _)) => unify_params(p, a, given),
        (Type::Map(pk, pv, _), Type::Map(ak, av, _)) => {
            unify_params(pk, ak, given);
            unify_params(pv, av, given)
        }
        (Type::Applied(p), Type::Applied(a))
            if p.name == a.name && p.types.len() == a.types.len() =>
        {
            p.types
                .iter()
                .zip(&a.types)
                .for_each(|(p, a)| unify_params(p, a, given));
        }
        (Type::Tuple(p), Type::Tuple(a)) | (Type::Results(p), Type::Results(a))
            if p.len() == a.len() =>
        {
            p.iter().zip(a).for_each(|(p, a)| unify_params(p, a, given))
        }
        (Type::Maybe(p), Type::Maybe(a))
        | (Type::Range(p), Type::Range(a))
        | (Type::Fail(p), Type::Fail(a))
        | (Type::Chan(p), Type::Chan(a))
        | (Type::Own(p), Type::Own(a)) => unify_params(p, a, given),
        (Type::Or(pv, pe), Type::Or(av, ae)) => {
            unify_params(pv, av, given);
            unify_params(pe, ae, given);
        }
        (Type::Closure(p), Type::Closure(a)) => unify_params(
            &Type::Task(Box::new(p.task.clone())),
            &Type::Task(Box::new(a.task.clone())),
            given,
        ),
        (Type::Closure(p), Type::Task(_)) => {
            unify_params(&Type::Task(Box::new(p.task.clone())), actual, given)
        }
        (Type::Task(p), Type::Task(a)) => {
            let Some((pairs, group)) = task_pairs(p, a) else {
                return;
            };
            let a = regions_named_as(p, a);
            for (pi, ai) in pairs {
                if let (Some(p), Some(a)) = (p.params.get(pi), a.params.get(ai)) {
                    unify_params(p, a, given);
                }
            }
            if let Some((group, range)) = group {
                let types = a.params.get(range.clone()).unwrap_or_default().to_vec();
                let taken = a.taken.get(range).unwrap_or_default().to_vec();
                given
                    .entry(group)
                    .or_insert_with(|| group_binding(types, taken));
            }
            unify_params(&p.ret, &a.ret, given);
        }
        (Type::Maybe(p), a) | (Type::Or(p, _), a) => unify_params(p, a, given),
        _ => {}
    }
}

/// Marks task-param regions owned by callback invocations as [`OWN_REGION`] so instantiations cannot unify them with caller regions.
fn regions_named_as(pattern: &TaskType, actual: &TaskType) -> TaskType {
    let mut found = HashMap::new();
    let pairs = task_pairs(pattern, actual).map_or_else(Vec::new, |(pairs, _)| pairs);
    for (pi, ai) in pairs {
        let (Some(p), Some(a)) = (pattern.params.get(pi), actual.params.get(ai)) else {
            continue;
        };
        if let (Some(p), Some(a)) = (pattern.region(pi), actual.region(ai)) {
            found.entry(p.to_string()).or_insert_with(|| a.to_string());
        }
        unify_regions(p, a, &mut found);
    }
    unify_regions(&pattern.ret, &actual.ret, &mut found);
    let own: HashSet<String> = found.into_values().collect();
    if own.is_empty() {
        return actual.clone();
    }
    let mut name = |region: &str| -> Option<String> {
        Some(if own.contains(region) {
            OWN_REGION.to_string()
        } else {
            region.to_string()
        })
    };
    TaskType {
        params: actual
            .params
            .iter()
            .map(|ty| ty.map_regions(&mut name))
            .collect(),
        taken: actual
            .taken
            .iter()
            .map(|how| match how {
                Taken::Region(region) => {
                    Taken::Region(name(region).unwrap_or_else(|| region.clone()))
                }
                other => other.clone(),
            })
            .collect(),
        ret: actual.ret.map_regions(&mut name),
    }
}

/// Maps generic-bound callback regions onto caller-resolved regions inferred from sibling arguments.
fn in_callers_regions(pattern: &Type, actual: &Type, given: &HashMap<String, Type>) -> Type {
    let (Type::Task(p), Type::Task(a)) = (pattern, actual) else {
        return actual.clone();
    };
    let Some((pairs, _)) = task_pairs(p, a) else {
        return actual.clone();
    };
    let mut rename = HashMap::new();
    for (pi, ai) in pairs {
        let (Some(p), Some(a)) = (p.params.get(pi), a.params.get(ai)) else {
            continue;
        };
        if p.params().is_empty() {
            continue;
        }
        let expected = p.map_params(&mut |name| given.get(name).cloned());
        if expected.params().is_empty() {
            unify_regions(a, &expected, &mut rename);
        }
    }
    if rename.is_empty() {
        return actual.clone();
    }
    let mut name = |region: &str| -> Option<String> {
        Some(
            rename
                .get(region)
                .cloned()
                .unwrap_or_else(|| region.to_string()),
        )
    };
    Type::Task(Box::new(TaskType {
        params: a
            .params
            .iter()
            .map(|ty| ty.map_regions(&mut name))
            .collect(),
        taken: a.taken.clone(),
        ret: a.ret.map_regions(&mut name),
    }))
}

type TaskPairs = (
    Vec<(usize, usize)>,
    Option<(String, std::ops::Range<usize>)>,
);

fn task_pairs(pattern: &TaskType, actual: &TaskType) -> Option<TaskPairs> {
    let Some(at) = pattern
        .params
        .iter()
        .position(|ty| matches!(ty, Type::Group(_)))
    else {
        return (pattern.params.len() == actual.params.len())
            .then(|| ((0..pattern.params.len()).map(|i| (i, i)).collect(), None));
    };
    let after = pattern.params.len() - at - 1;
    let end = actual
        .params
        .len()
        .checked_sub(after)
        .filter(|end| *end >= at)?;
    let mut pairs: Vec<(usize, usize)> = (0..at).map(|i| (i, i)).collect();
    pairs.extend((0..after).map(|k| (at + 1 + k, end + k)));
    let Some(Type::Group(group)) = pattern.params.get(at) else {
        return None;
    };
    Some((pairs, Some((group.clone(), at..end))))
}

pub fn unify_regions(pattern: &Type, actual: &Type, regions: &mut HashMap<String, String>) {
    let mut record = |p: &Option<String>, a: &Option<String>| {
        if let (Some(p), Some(a)) = (p, a)
            && a != ANY_REGION
        {
            regions.entry(p.clone()).or_insert_with(|| a.clone());
        }
    };
    match (pattern, actual) {
        (Type::Ptr(p, pr), Type::Ptr(a, ar)) | (Type::Slice(p, pr), Type::Slice(a, ar)) => {
            record(pr, ar);
            unify_regions(p, a, regions);
        }
        (Type::Map(pk, pv, pr), Type::Map(ak, av, ar)) => {
            record(pr, ar);
            unify_regions(pk, ak, regions);
            unify_regions(pv, av, regions);
        }
        (Type::Array(p, _), Type::Array(a, _)) => unify_regions(p, a, regions),
        (Type::Tuple(p), Type::Tuple(a)) => p
            .iter()
            .zip(a)
            .for_each(|(p, a)| unify_regions(p, a, regions)),
        (Type::Named(p, pr), Type::Named(a, ar)) if p == a => record(pr, ar),
        (Type::Applied(p), Type::Applied(a))
            if p.name == a.name && p.types.len() == a.types.len() =>
        {
            record(&p.region, &a.region);
            p.types
                .iter()
                .zip(&a.types)
                .for_each(|(p, a)| unify_regions(p, a, regions));
        }
        (Type::Text(pr), Type::Text(ar)) => record(pr, ar),
        (Type::Closure(p), Type::Closure(a)) => {
            record(&Some(p.region.clone()), &Some(a.region.clone()))
        }
        (Type::Maybe(p), Type::Maybe(a))
        | (Type::Range(p), Type::Range(a))
        | (Type::Fail(p), Type::Fail(a)) => unify_regions(p, a, regions),
        (Type::Or(pv, pe), Type::Or(av, ae)) => {
            unify_regions(pv, av, regions);
            unify_regions(pe, ae, regions);
        }
        (Type::Or(_, pe), Type::Fail(a)) => unify_regions(pe, a, regions),
        (Type::Or(pv, _), a) => unify_regions(pv, a, regions),
        (Type::Maybe(p), a) => unify_regions(p, a, regions),
        _ => {}
    }
}

fn holds_pointers(ty: &Type, regional: &HashSet<String>) -> bool {
    match ty {
        Type::Ptr(..) | Type::Slice(..) | Type::Map(..) => true,
        Type::Named(name, _) => regional.contains(name),
        Type::Applied(applied) => {
            regional.contains(&applied.name)
                || applied.types.iter().any(|ty| holds_pointers(ty, regional))
        }
        Type::Maybe(inner) | Type::Array(inner, _) => holds_pointers(inner, regional),
        Type::Or(value, error) => {
            holds_pointers(value, regional) || holds_pointers(error, regional)
        }
        Type::Tuple(items) => items.iter().any(|item| holds_pointers(item, regional)),
        _ => false,
    }
}

fn holds_twofold(ty: &Type, regional: &HashSet<String>, lambdas: bool) -> bool {
    match ty {
        Type::Results(items) | Type::Tuple(items) => items
            .iter()
            .any(|item| holds_twofold(item, regional, lambdas)),
        Type::Maybe(inner) | Type::Array(inner, _) | Type::Fail(inner) => {
            holds_twofold(inner, regional, lambdas)
        }
        Type::Or(value, error) => {
            holds_twofold(value, regional, lambdas) || holds_twofold(error, regional, lambdas)
        }
        Type::Closure(closure) => {
            lambdas && (closure.mode == KeptMode::Bind || holds_twofold(&closure.task.ret, regional, lambdas))
        }
        _ => holds_pointers(ty, regional),
    }
}

fn holds_changeable(ty: &Type, changeable: &HashSet<String>) -> bool {
    match ty {
        Type::Ptr(..) | Type::Slice(..) | Type::Map(..) | Type::Array(..) => true,
        Type::Named(name, _) => changeable.contains(name),
        Type::Applied(applied) => {
            changeable.contains(&applied.name)
                || applied
                    .types
                    .iter()
                    .any(|ty| holds_changeable(ty, changeable))
        }
        Type::Maybe(inner) => holds_changeable(inner, changeable),
        Type::Or(value, error) => {
            holds_changeable(value, changeable) || holds_changeable(error, changeable)
        }
        Type::Tuple(items) => items.iter().any(|item| holds_changeable(item, changeable)),
        _ => false,
    }
}

fn strip_all_regions(ty: &Type) -> Type {
    match ty {
        Type::Task(task) => Type::Task(Box::new(TaskType {
            params: task.params.iter().map(strip_all_regions).collect(),
            taken: task.taken.clone(),
            ret: strip_all_regions(&task.ret),
        })),
        other => other.without_regions(),
    }
}

fn is_task(ty: &Type) -> bool {
    matches!(ty, Type::Task(_))
}

fn is_callable(ty: &Type) -> bool {
    matches!(ty, Type::Task(_) | Type::Closure(_))
}

/// `[flex @r]` closures change their own copies, which every copy of one would share, so they are never copied.
/// A `[bind @r]` one changes only what its copies share already, so it is copied as a slice is.
fn held_lambda(ty: &Type) -> bool {
    matches!(ty, Type::Closure(closure) if closure.mode == KeptMode::Flex)
}

fn held_word(_: &Type) -> &'static str {
    "[flex @r]"
}

/// What a held value is, for a message: a `[flex @r]` lambda, or a value holding one.
fn held_phrase(ty: &Type) -> String {
    if held_lambda(ty) {
        "a '[flex @r]' lambda".to_string()
    } else {
        format!("a '{}', holding a '[flex @r]' lambda", ty)
    }
}

fn held_kind(ty: &Type) -> &'static str {
    match ty {
        Type::Closure(closure) if closure.mode == KeptMode::Bind => "[bind @r]",
        _ => "[flex @r]",
    }
}

/// A `[bind @r]` closure, which changes contents shared with every copy of it.
fn bind_lambda(ty: &Type) -> bool {
    matches!(ty, Type::Closure(closure) if closure.mode == KeptMode::Bind)
}

/// Whether every copy of a value of this type shares its contents: a slice's items, a map, what a pointer points
/// to. A `[bind @r]` lambda changes only these of what it keeps.
fn shared_contents(ty: &Type) -> bool {
    matches!(ty, Type::Slice(..) | Type::Map(..) | Type::Ptr(..))
}

fn has_closure(ty: &Type) -> bool {
    match ty {
        Type::Closure(_) => true,
        Type::Ptr(inner, _)
        | Type::Slice(inner, _)
        | Type::Array(inner, _)
        | Type::Range(inner)
        | Type::Maybe(inner)
        | Type::Fail(inner) => has_closure(inner),
        Type::Map(key, value, _) | Type::Or(key, value) => has_closure(key) || has_closure(value),
        Type::Tuple(items) | Type::Results(items) => items.iter().any(has_closure),
        Type::Applied(applied) => applied.types.iter().any(has_closure),
        _ => false,
    }
}

/// Whether a field of this type makes the value holding it held: a `[flex @this]` lambda, or a held shape.
fn holds_held_field(ty: &Type, held: &HashSet<String>) -> bool {
    match ty {
        Type::Closure(closure) => closure.mode == KeptMode::Flex,
        Type::Named(name, _) => held.contains(name),
        Type::Applied(applied) => held.contains(&applied.name),
        _ => false,
    }
}

/// A value never copied: a `[flex @r]` lambda, or a shape holding one.
fn held_value(ty: &Type, held: &HashSet<String>) -> bool {
    held_lambda(ty) || holds_held_field(ty, held)
}

/// A type holding a held value inside another value, a tuple, a slice, a maybe, which would copy it.
fn holds_held(ty: &Type, held: &HashSet<String>) -> bool {
    let inside = |ty: &Type| held_value(ty, held) || holds_held(ty, held);
    match ty {
        Type::Closure(_) => false,
        Type::Ptr(inner, _)
        | Type::Slice(inner, _)
        | Type::Array(inner, _)
        | Type::Range(inner)
        | Type::Maybe(inner)
        | Type::Fail(inner) => inside(inner),
        Type::Map(key, value, _) | Type::Or(key, value) => inside(key) || inside(value),
        Type::Tuple(items) => items.iter().any(inside),
        Type::Applied(applied) => applied.types.iter().any(inside),
        _ => false,
    }
}

#[allow(dead_code)]
fn holds_held_lambda(ty: &Type) -> bool {
    match ty {
        Type::Closure(_) => false,
        Type::Ptr(inner, _)
        | Type::Slice(inner, _)
        | Type::Array(inner, _)
        | Type::Range(inner)
        | Type::Maybe(inner)
        | Type::Fail(inner) => held_lambda(inner) || holds_held_lambda(inner),
        Type::Map(key, value, _) | Type::Or(key, value) => [key, value]
            .into_iter()
            .any(|ty| held_lambda(ty) || holds_held_lambda(ty)),
        Type::Tuple(items) => items
            .iter()
            .any(|ty| held_lambda(ty) || holds_held_lambda(ty)),
        Type::Applied(applied) => applied
            .types
            .iter()
            .any(|ty| held_lambda(ty) || holds_held_lambda(ty)),
        _ => false,
    }
}

fn region_after(args: &[Expr]) -> Option<Span> {
    args.last()
        .filter(|arg| matches!(arg.kind, ExprKind::RegionAfter(_)))
        .map(|arg| arg.span)
}

/// Outlined (`#[inline(never)]`) so error formatting stays off recursive literal-checking stacks.
#[inline(never)]
fn refuse<T>(make: impl FnOnce() -> Error) -> Result<T> {
    Err(make())
}

fn is_arithmetic(value: Option<&Expr>) -> bool {
    match value.map(|value| &value.kind) {
        Some(ExprKind::Binary(..) | ExprKind::Unary(..)) => true,
        Some(ExprKind::Call { name, .. }) => number_cast(name).is_some(),
        _ => false,
    }
}

fn constant_value(expr: &Expr) -> bool {
    match &expr.kind {
        ExprKind::IntLit(_)
        | ExprKind::FloatLit(_)
        | ExprKind::CharLit(_)
        | ExprKind::BoolLit(_)
        | ExprKind::TextLit(_)
        | ExprKind::NoneLit
        | ExprKind::Macro { .. }
        | ExprKind::TaskValue(_) => true,
        ExprKind::Unary(_, inner) | ExprKind::Wrap(inner) => constant_value(inner),
        ExprKind::Array(values) | ExprKind::Tuple(values) => values.iter().all(constant_value),
        ExprKind::Construct { args, .. } => args.iter().all(constant_value),
        ExprKind::Repeat { value, count } => constant_value(value) && constant_value(count),
        ExprKind::StructInit { fields, .. } => {
            fields.iter().all(|field| constant_value(&field.value))
        }
        _ => false,
    }
}

fn holds_text(ty: &Type, textual: &HashSet<String>) -> bool {
    match ty {
        Type::Text(_) => true,
        Type::Closure(closure) => closure.region == THIS_WORD,
        Type::Named(name, _) => textual.contains(name),
        Type::Applied(applied) => {
            textual.contains(&applied.name)
                || applied.types.iter().any(|ty| holds_text(ty, textual))
        }
        Type::Maybe(inner) | Type::Array(inner, _) => holds_text(inner, textual),
        Type::Or(value, error) => holds_text(value, textual) || holds_text(error, textual),
        Type::Tuple(items) => items.iter().any(|item| holds_text(item, textual)),
        _ => false,
    }
}

fn unsettled(ty: &Type) -> bool {
    match ty {
        Type::None | Type::Fail(_) => true,
        Type::Applied(_) => untold_kind(ty),
        Type::Array(items, _) => unsettled(items),
        Type::Tuple(items) => items.iter().any(unsettled),
        _ => false,
    }
}

fn settled_example(ty: &Type) -> Type {
    match ty {
        Type::None => Type::Maybe(Box::new(Type::Int)),
        Type::Fail(error) => Type::Or(Box::new(Type::Int), error.clone()),
        Type::Maybe(inner) if holds_untold(inner) => Type::Maybe(Box::new(settled_example(inner))),
        Type::Array(items, count) => Type::Array(Box::new(settled_example(items)), *count),
        Type::Tuple(items) => Type::Tuple(items.iter().map(settled_example).collect()),
        Type::Applied(applied) if untold_kind(ty) => Type::Applied(Box::new(
            applied.with_types(
                applied
                    .types
                    .iter()
                    .map(|ty| if is_untold(ty) { Type::Int } else { ty.clone() })
                    .collect(),
            ),
        )),
        other => other.clone(),
    }
}

fn untold_kind_message(kind: &str, tag: &str, param: &str, example: &str) -> String {
    format!(
        "can't tell which type '{}' is for this '{}', since its values don't say and nothing this value goes into names one; write {}, as in '{}<{}>.{}'",
        param,
        unqualified(kind),
        if example.contains(", ") { "them" } else { "it" },
        unqualified(kind),
        example,
        tag
    )
}

/// Prefix marking uninferred generic variant params (`Option<?T>`).
const UNTOLD: char = '?';

fn is_untold(ty: &Type) -> bool {
    matches!(ty, Type::Param(name) if name.starts_with(UNTOLD))
}

fn untold_written(ty: &Type) -> String {
    match ty {
        Type::Maybe(inner) | Type::Array(inner, _) => untold_written(inner),
        Type::Tuple(items) => items
            .iter()
            .find(|item| holds_untold(item))
            .map_or_else(String::new, untold_written),
        Type::Applied(applied) => format!(
            "{}<{}>.…",
            unqualified(&applied.name),
            applied
                .types
                .iter()
                .map(|ty| if is_untold(ty) {
                    "int".to_string()
                } else {
                    ty.to_string()
                })
                .collect::<Vec<_>>()
                .join(", ")
        ),
        other => other.to_string(),
    }
}

fn holds_untold(ty: &Type) -> bool {
    match ty {
        Type::Maybe(inner) | Type::Array(inner, _) => holds_untold(inner),
        Type::Tuple(items) => items.iter().any(holds_untold),
        other => untold_kind(other),
    }
}

fn untold_inside(ty: &Type) -> bool {
    match ty {
        Type::Maybe(inner) | Type::Array(inner, _) => untold_inside(inner),
        Type::Tuple(items) => items.iter().any(untold_inside),
        Type::Applied(applied) => applied
            .types
            .iter()
            .any(|ty| is_untold(ty) || untold_inside(ty)),
        _ => false,
    }
}

fn untold_kind(ty: &Type) -> bool {
    matches!(ty, Type::Applied(applied) if applied.types.iter().any(is_untold))
}

/// Joins two types (`none`/`fail` wrap *around* values; already-constructed containers are never rewritten inside).
fn join_types(a: &Type, b: &Type) -> Option<Type> {
    if fits_regions(b, a) {
        return Some(a.clone());
    }
    if fits_regions(a, b) {
        return Some(b.clone());
    }
    let plain = |ty: &Type| {
        !matches!(
            ty,
            Type::None | Type::Fail(_) | Type::Nothing | Type::Maybe(_) | Type::Or(..)
        )
    };
    match (a, b) {
        (Type::Array(x, n), Type::Array(y, m)) if n == m => {
            join_types(x, y).map(|items| Type::Array(Box::new(items), *n))
        }
        (Type::Tuple(x), Type::Tuple(y)) if x.len() == y.len() => x
            .iter()
            .zip(y)
            .map(|(x, y)| join_types(x, y))
            .collect::<Option<Vec<_>>>()
            .map(Type::Tuple),
        (Type::None, Type::Maybe(_)) => Some(b.clone()),
        (Type::Maybe(_), Type::None) => Some(a.clone()),
        (Type::None, other) | (other, Type::None) if plain(other) => {
            Some(Type::Maybe(Box::new(other.clone())))
        }
        (Type::None, Type::Or(..)) => Some(Type::Maybe(Box::new(b.clone()))),
        (Type::Or(..), Type::None) => Some(Type::Maybe(Box::new(a.clone()))),
        (Type::Maybe(inner), other) | (other, Type::Maybe(inner)) if plain(other) => {
            join_types(inner, other)
                .filter(plain)
                .filter(|joined| fits_regions(inner, joined))
                .map(|value| Type::Maybe(Box::new(value)))
        }
        (Type::Fail(error), Type::Or(_, known)) | (Type::Or(_, known), Type::Fail(error))
            if fits_regions(error, known) =>
        {
            Some(if matches!(a, Type::Or(..)) {
                a.clone()
            } else {
                b.clone()
            })
        }
        (Type::Fail(error), other) | (other, Type::Fail(error))
            if plain(other) || matches!(other, Type::Maybe(_)) =>
        {
            (!fits_regions(other, error) && !fits_regions(error, other))
                .then(|| Type::Or(Box::new(other.clone()), error.clone()))
        }
        (Type::Or(value, error), other) | (other, Type::Or(value, error))
            if !matches!(other, Type::Fail(_)) =>
        {
            join_types(value, other)
                .filter(|joined| !matches!(joined, Type::Or(..)))
                .filter(|joined| fits_regions(value, joined))
                .map(|joined| Type::Or(Box::new(joined), error.clone()))
        }
        _ => None,
    }
}

fn in_map_value(place: &Expr) -> bool {
    match &place.kind {
        ExprKind::Field(base, _) => in_map_value(base),
        ExprKind::Index(base, _) => matches!(base.ty, Some(Type::Map(..))) || in_map_value(base),
        _ => false,
    }
}

fn place_region(place: &Expr) -> Option<String> {
    match &place.kind {
        ExprKind::Deref(pointer) => match pointer.ty.as_ref()? {
            Type::Ptr(_, region) => region.clone(),
            _ => None,
        },
        ExprKind::Field(base, _) => place_region(base),
        ExprKind::Index(base, _) => match base.ty.as_ref()? {
            Type::Slice(_, region) | Type::Map(_, _, region) => region.clone(),
            _ => place_region(base),
        },
        _ => None,
    }
}

fn value_bytes(ty: &Type, sizes: &HashMap<String, u128>) -> u128 {
    match ty {
        Type::Nothing => 0,
        Type::Named(name, _) => sizes.get(name).copied().unwrap_or(8),
        Type::Applied(applied) => sizes.get(&applied.name).copied().unwrap_or(8),
        Type::Array(items, count) => value_bytes(items, sizes).saturating_mul(u128::from(*count)),
        Type::Slice(..) => 24,
        Type::Map(..) => 8,
        Type::Maybe(inner) => value_bytes(inner, sizes).saturating_add(8),
        Type::Or(value, error) => value_bytes(value, sizes)
            .saturating_add(value_bytes(error, sizes))
            .saturating_add(8),
        Type::Fail(inner) | Type::Range(inner) => value_bytes(inner, sizes),
        Type::Results(types) | Type::Tuple(types) => types
            .iter()
            .map(|ty| value_bytes(ty, sizes).max(8))
            .fold(0, u128::saturating_add),
        _ => 8,
    }
}

fn fields_bytes(fields: &[Field], sizes: &HashMap<String, u128>) -> u128 {
    fields
        .iter()
        .map(|field| value_bytes(&field.ty, sizes).max(8))
        .fold(8, u128::saturating_add)
}

fn sends_value(ret: &Type) -> bool {
    !matches!(ret, Type::Nothing) && !matches!(ret, Type::Or(value, _) if **value == Type::Nothing)
}

fn contained_by_value(ty: &Type) -> Vec<&str> {
    match ty {
        Type::Named(name, _) => vec![name.as_str()],
        Type::Applied(applied) => {
            let mut names = vec![applied.name.as_str()];
            names.extend(applied.types.iter().flat_map(contained_by_value));
            names
        }
        Type::Maybe(inner) | Type::Array(inner, _) => contained_by_value(inner),
        Type::Tuple(items) => items.iter().flat_map(contained_by_value).collect(),
        Type::Or(value, error) => {
            let mut names = contained_by_value(value);
            names.extend(contained_by_value(error));
            names
        }
        _ => Vec::new(),
    }
}

/// Receiver type substituted for `this` inside copied pattern default methods (`None` outside methods).
fn method_this(t: &TaskDef) -> Option<Type> {
    match &t.owner {
        Some(owner) if owner.shared => t.owner_type().map(Type::named),
        Some(_) => t.params.first().map(|this| this.ty.clone()),
        None => None,
    }
}

/// Substitutes `this` inside pattern defaults, stripping regions on type args to match field-type rules.
fn put_this(ty: &Type, this: &Type) -> Type {
    let whole = |ty: &Type| ty.replace_names(&|name| (name == THIS_TYPE).then(|| this.clone()));
    let given =
        |ty: &Type| ty.replace_names(&|name| (name == THIS_TYPE).then(|| this.without_regions()));
    let boxed = |ty: &Type| Box::new(put_this(ty, this));
    match ty {
        Type::Applied(applied) => Type::Applied(Box::new(
            applied.with_types(applied.types.iter().map(given).collect()),
        )),
        Type::Maybe(inner) => Type::Maybe(boxed(inner)),
        Type::Fail(error) => Type::Fail(boxed(error)),
        Type::Or(value, error) => Type::Or(boxed(value), boxed(error)),
        Type::Results(types) => Type::Results(types.iter().map(|ty| put_this(ty, this)).collect()),
        Type::Tuple(items) => Type::Tuple(items.iter().map(|ty| put_this(ty, this)).collect()),
        _ => whole(ty),
    }
}

fn mentions_name(ty: &Type, name: &str) -> bool {
    named_types(ty).contains(&name)
}

fn named_types(ty: &Type) -> Vec<&str> {
    match ty {
        Type::Named(name, _) => vec![name.as_str()],
        Type::Applied(applied) => {
            let mut names = vec![applied.name.as_str()];
            names.extend(applied.types.iter().flat_map(named_types));
            names
        }
        Type::Ptr(inner, _)
        | Type::Maybe(inner)
        | Type::Fail(inner)
        | Type::Array(inner, _)
        | Type::Slice(inner, _) => named_types(inner),
        Type::Map(key, value, _) => {
            let mut names = named_types(key);
            names.extend(named_types(value));
            names
        }
        Type::Tuple(items) => items.iter().flat_map(named_types).collect(),
        Type::Or(value, error) => {
            let mut names = named_types(value);
            names.extend(named_types(error));
            names
        }
        Type::Task(task) => task
            .params
            .iter()
            .chain([&task.ret])
            .flat_map(named_types)
            .collect(),
        Type::Closure(closure) => closure
            .task
            .params
            .iter()
            .chain([&closure.task.ret])
            .flat_map(named_types)
            .collect(),
        _ => Vec::new(),
    }
}

fn constructible(ty: &Type, can: &HashSet<&str>) -> bool {
    match ty {
        Type::Named(name, _) => can.contains(name.as_str()),
        Type::Applied(applied) => can.contains(applied.name.as_str()),
        Type::Ptr(inner, _) | Type::Array(inner, _) => constructible(inner, can),
        Type::Slice(..) | Type::Map(..) => true,
        Type::Or(value, error) => {
            **value == Type::Nothing || constructible(value, can) || constructible(error, can)
        }
        Type::Tuple(items) => items.iter().all(|item| constructible(item, can)),
        _ => true,
    }
}

fn always_sends(block: &Block) -> bool {
    block.iter().any(|stmt| match &stmt.kind {
        StmtKind::Send(_) => true,
        StmtKind::When(arms, else_block) => {
            for arm in arms {
                let known = known_condition(&arm.cond);
                if known == Some(false) {
                    continue;
                }
                if !always_sends(&arm.body) {
                    return false;
                }
                if known == Some(true) {
                    return true;
                }
            }
            else_block.as_ref().is_some_and(always_sends)
        }
        StmtKind::Match(_, cases) => cases.iter().all(|case| always_sends(&case.body)),
        StmtKind::Block(body) => always_sends(body),
        StmtKind::Named(name, inner) => never_finishes(inner, Some(name)),
        StmtKind::Loop(..) | StmtKind::Parted(_) => never_finishes(stmt, None),
        _ => false,
    })
}

fn never_finishes(stmt: &Stmt, name: Option<&str>) -> bool {
    match &stmt.kind {
        StmtKind::Loop(cond, body, _) if says_true(cond) => !stops_loop(&[body], name),
        StmtKind::Parted(parted) if parted.cond.as_ref().is_none_or(says_true) => {
            !stops_loop(&[&parted.start, &parted.step, &parted.body], name)
        }
        _ => false,
    }
}

fn stops_loop(parts: &[&Block], name: Option<&str>) -> bool {
    let mut effects = LoopEffects::default();
    parts
        .iter()
        .for_each(|part| loop_effects(part, &[], &mut Vec::new(), name, &mut effects));
    effects.stops
}

const ENDLESS_UNSAID: &str = "this loop never ends by its condition; write 'endless' to say so";

fn unused_in_loop(parted: &PartedLoop) -> Option<(String, Span)> {
    let mut closures = false;
    let mut used = |stmts: &[Stmt], names: &mut Vec<(String, Span)>| {
        walk_block(stmts, &mut |e| match &e.kind {
            ExprKind::Var(name) | ExprKind::Call { name, .. } => {
                names.retain(|(declared, _)| declared != name)
            }
            ExprKind::Closure { .. } => closures = true,
            _ => {}
        });
    };
    let mut declared: Vec<(String, Span)> = Vec::new();
    for (i, item) in parted.start.iter().enumerate() {
        if let StmtKind::Binding { names, .. } = &item.kind {
            for bound in names {
                bound_names(bound, &mut declared);
            }
        }
        used(parted.start.get(i + 1..).unwrap_or_default(), &mut declared);
    }
    if let Some(cond) = &parted.cond {
        let mut reads = Vec::new();
        walk_block(
            &[Stmt::new(
                StmtKind::Loop(cond.clone(), Vec::new(), None),
                cond.value.span,
            )],
            &mut |e| {
                if let ExprKind::Var(name) = &e.kind {
                    reads.push(name.clone());
                }
            },
        );
        declared.retain(|(name, _)| !reads.contains(name));
    }
    used(&parted.step, &mut declared);
    used(&parted.body, &mut declared);
    if closures {
        return None;
    }
    declared.into_iter().next()
}

fn bound_names(bound: &Bound, names: &mut Vec<(String, Span)>) {
    if bound.parts.is_empty() {
        if bound.name != DISCARD {
            names.push((bound.name.clone(), bound.span));
        }
    } else {
        bound.parts.iter().for_each(|part| bound_names(part, names));
    }
}

fn target_places<'a>(target: &'a Target, places: &mut Vec<&'a Expr>) {
    match target {
        Target::Place(place) => places.push(place),
        Target::Tuple(parts, _) => parts.iter().for_each(|part| target_places(part, places)),
        Target::Discard(_) => {}
    }
}

fn unchanging_reads(
    cond: &Condition,
    body: &[Stmt],
    step: &[Stmt],
    own: Option<&str>,
) -> Option<Vec<String>> {
    let mut names = Vec::new();
    if !cond
        .parts()
        .all(|part| part.pattern.is_none() && plain_reads(&part.value, &mut names))
        || names.is_empty()
    {
        return None;
    }
    let mut effects = LoopEffects::default();
    loop_effects(body, &names, &mut Vec::new(), own, &mut effects);
    loop_effects(step, &names, &mut Vec::new(), own, &mut effects);
    (!effects.leaves && !effects.changes).then_some(names)
}

fn plain_reads(e: &Expr, names: &mut Vec<String>) -> bool {
    match &e.kind {
        ExprKind::Var(name) => {
            if !names.contains(name) {
                names.push(name.clone());
            }
            true
        }
        ExprKind::IntLit(_)
        | ExprKind::FloatLit(_)
        | ExprKind::CharLit(_)
        | ExprKind::BoolLit(_)
        | ExprKind::TextLit(_) => true,
        ExprKind::Binary(_, left, right) => plain_reads(left, names) && plain_reads(right, names),
        ExprKind::Unary(_, inner) | ExprKind::Field(inner, _) => plain_reads(inner, names),
        _ => false,
    }
}

#[derive(Default)]
struct LoopEffects {
    leaves: bool,
    changes: bool,
    stops: bool,
    continued: Option<Span>,
}

fn loop_effects(
    stmts: &[Stmt],
    names: &[String],
    inner: &mut Vec<Option<String>>,
    own: Option<&str>,
    effects: &mut LoopEffects,
) {
    for stmt in stmts {
        stmt_effects(stmt, names, inner, own, effects);
    }
}

fn stmt_effects(
    stmt: &Stmt,
    names: &[String],
    inner: &mut Vec<Option<String>>,
    own: Option<&str>,
    effects: &mut LoopEffects,
) {
    let within = |inner: &[Option<String>], name: &str| {
        inner
            .iter()
            .any(|loop_name| loop_name.as_deref() == Some(name))
    };
    let exprs = |values: &[Expr], inner: &mut Vec<Option<String>>, effects: &mut LoopEffects| {
        values
            .iter()
            .for_each(|e| expr_effects(e, names, inner, own, effects))
    };
    match &stmt.kind {
        StmtKind::Send(values) => {
            effects.leaves = true;
            exprs(values, inner, effects);
        }
        StmtKind::Break(name, value) => {
            let stops = match name {
                None => inner.is_empty(),
                Some((name, _)) => !within(inner, name),
            };
            effects.leaves |= stops;
            effects.stops |= stops;
            if let Some(value) = value {
                expr_effects(value, names, inner, own, effects);
            }
        }
        StmtKind::Continue(name) => {
            let stops = name
                .as_ref()
                .is_some_and(|(name, _)| !within(inner, name) && own != Some(name.as_str()));
            effects.leaves |= stops;
            effects.stops |= stops;
            let own_pass = match name {
                None => inner.is_empty(),
                Some((name, _)) => own == Some(name.as_str()),
            };
            if own_pass && effects.continued.is_none() {
                effects.continued = Some(stmt.span);
            }
        }
        StmtKind::Assign(targets, values) => {
            let mut set = Vec::new();
            targets
                .iter()
                .for_each(|target| target_places(target, &mut set));
            effects.changes |= set
                .iter()
                .any(|place| place_root(place).is_some_and(|name| names.contains(&name)));
            set.into_iter()
                .for_each(|place| expr_effects(place, names, inner, own, effects));
            exprs(values, inner, effects);
        }
        StmtKind::Step { target, value, .. } => {
            effects.changes |= place_root(target).is_some_and(|name| names.contains(&name));
            expr_effects(target, names, inner, own, effects);
            expr_effects(value, names, inner, own, effects);
        }
        StmtKind::SetResults(set, values) => {
            effects.changes |= set.iter().any(|(name, _)| names.contains(name));
            exprs(values, inner, effects);
        }
        StmtKind::Binding { init, .. } => exprs(init, inner, effects),
        StmtKind::Expr(e) => expr_effects(e, names, inner, own, effects),
        StmtKind::When(arms, else_block) => {
            for arm in arms {
                arm.cond
                    .parts()
                    .for_each(|part| expr_effects(&part.value, names, inner, own, effects));
                loop_effects(&arm.body, names, inner, own, effects);
            }
            if let Some(block) = else_block {
                loop_effects(block, names, inner, own, effects);
            }
        }
        StmtKind::Match(subject, cases) => {
            expr_effects(subject, names, inner, own, effects);
            cases
                .iter()
                .for_each(|case| loop_effects(&case.body, names, inner, own, effects));
        }
        StmtKind::Block(block) => loop_effects(block, names, inner, own, effects),
        StmtKind::Turns(turns) => turns
            .iter()
            .for_each(|turn| loop_effects(turn, names, inner, own, effects)),
        StmtKind::Named(..) | StmtKind::Loop(..) | StmtKind::Each(..) | StmtKind::Parted(_) => {
            nested_loop_effects(stmt, None, names, inner, own, effects)
        }
        StmtKind::Region { .. } => {}
    }
}

fn nested_loop_effects(
    stmt: &Stmt,
    name: Option<String>,
    names: &[String],
    inner: &mut Vec<Option<String>>,
    own: Option<&str>,
    effects: &mut LoopEffects,
) {
    match &stmt.kind {
        StmtKind::Named(name, nested) => {
            return nested_loop_effects(nested, Some(name.clone()), names, inner, own, effects);
        }
        StmtKind::Each(_, _, source, _, _) => expr_effects(source, names, inner, own, effects),
        StmtKind::Parted(parted) => loop_effects(&parted.start, names, inner, own, effects),
        _ => {}
    }
    inner.push(name);
    match &stmt.kind {
        StmtKind::Loop(cond, block, _) => {
            cond.parts()
                .for_each(|part| expr_effects(&part.value, names, inner, own, effects));
            loop_effects(block, names, inner, own, effects);
        }
        StmtKind::Each(_, _, _, block, _) => loop_effects(block, names, inner, own, effects),
        StmtKind::Parted(parted) => {
            parted
                .cond
                .iter()
                .flat_map(Condition::parts)
                .for_each(|part| expr_effects(&part.value, names, inner, own, effects));
            loop_effects(&parted.step, names, inner, own, effects);
            loop_effects(&parted.body, names, inner, own, effects);
        }
        _ => {}
    }
    inner.pop();
    if let Some(finally) = stmt.finally() {
        loop_effects(finally, names, inner, own, effects);
    }
}

pub fn map_pass(ty: &Type, fails: bool) -> Type {
    let (collection, result) = match ty {
        Type::Or(collection, result) => (collection.as_ref(), Some(result)),
        other => (other, None),
    };
    let item = match collection {
        Type::Array(item, _) | Type::Slice(item, _) => (**item).clone(),
        other => other.clone(),
    };
    match result {
        Some(result) if fails => Type::Or(Box::new(item), result.clone()),
        _ => item,
    }
}

fn loop_value(e: &Expr) -> Option<&ValueLoop> {
    match &e.kind {
        ExprKind::LoopValue(value) => Some(value),
        ExprKind::PlanB { value, .. } => loop_value(value),
        _ => None,
    }
}

fn success_of(ty: &Type) -> Type {
    match ty {
        Type::Or(value, _) => (**value).clone(),
        other => other.clone(),
    }
}

// Even unreachable `continue` makes map-loop arrays `maybe` per language rule.
fn continues_loop(value: &ValueLoop) -> Option<Span> {
    let mut effects = LoopEffects::default();
    let own = value.name.as_ref().map(|(name, _)| name.as_str());
    if let StmtKind::Loop(cond, _, _) = &value.stmt.kind {
        cond.parts()
            .for_each(|part| expr_effects(&part.value, &[], &mut Vec::new(), own, &mut effects));
    }
    if let Some(body) = value.body() {
        loop_effects(body, &[], &mut Vec::new(), own, &mut effects);
    }
    effects.continued
}

fn expr_effects(
    e: &Expr,
    names: &[String],
    inner: &mut Vec<Option<String>>,
    own: Option<&str>,
    effects: &mut LoopEffects,
) {
    visit_expr(e, &mut |e| match &e.kind {
        ExprKind::Ref(place) => {
            effects.changes |= place_root(place).is_some_and(|name| names.contains(&name));
            true
        }
        ExprKind::MethodCall { value, .. } => {
            effects.changes |= place_root(value).is_some_and(|name| names.contains(&name));
            true
        }
        ExprKind::Edit {
            items: value, op, ..
        } => {
            effects.changes |=
                !op.makes_copy() && place_root(value).is_some_and(|name| names.contains(&name));
            true
        }
        ExprKind::Closure { places, .. } => {
            effects.changes |= places.iter().any(|place| names.contains(&place.name));
            true
        }
        ExprKind::PlanB { value, body, .. } => {
            expr_effects(value, names, inner, own, effects);
            loop_effects(body, names, inner, own, effects);
            false
        }
        ExprKind::Choice(choice) => {
            stmt_effects(choice, names, inner, own, effects);
            false
        }
        ExprKind::LoopValue(value) => {
            nested_loop_effects(
                &value.stmt,
                value.name.as_ref().map(|(name, _)| name.clone()),
                names,
                inner,
                own,
                effects,
            );
            false
        }
        _ => true,
    });
}

fn place_root(e: &Expr) -> Option<String> {
    let mut e = e;
    loop {
        match &e.kind {
            ExprKind::Var(name) => return Some(name.clone()),
            ExprKind::Field(base, _) | ExprKind::Index(base, _) => e = base,
            _ => return None,
        }
    }
}

fn always_leaves(block: &[Stmt]) -> bool {
    block.iter().any(|stmt| match &stmt.kind {
        StmtKind::Send(_) | StmtKind::Break(..) | StmtKind::Continue(_) => true,
        StmtKind::When(arms, else_block) => {
            for arm in arms {
                let known = known_condition(&arm.cond);
                if known == Some(false) {
                    continue;
                }
                if !always_leaves(&arm.body) {
                    return false;
                }
                if known == Some(true) {
                    return true;
                }
            }
            else_block
                .as_ref()
                .is_some_and(|block| always_leaves(block))
        }
        StmtKind::Match(_, cases) => cases.iter().all(|case| always_leaves(&case.body)),
        StmtKind::Block(body) => always_leaves(body),
        _ => false,
    })
}

fn task_passing(how: &Taken) -> Passing {
    match how {
        Taken::Place(passing) => *passing,
        Taken::Flex => Passing::Flex,
        Taken::Bind => Passing::Bind,
        _ => Passing::Copy,
    }
}

fn shown_param(name: &str, ty: &Type, passing: Passing) -> String {
    match passing {
        Passing::Copy => format!("{}: {}", name, ty),
        passing => format!("{} {}: {}", passing.word(), name, ty),
    }
}

fn taken_by(name: &str, ty: &Type, passing: Passing) -> Taken {
    match (ty, passing) {
        (Type::Region, _) => Taken::Region(name.to_string()),
        (_, passing) if passing.is_ref() => Taken::Place(passing),
        (_, Passing::Flex) => Taken::Flex,
        (_, Passing::Bind) => Taken::Bind,
        _ => Taken::Value,
    }
}

fn always_holds(cond: &Condition) -> bool {
    cond.parts().all(|part| matches!(&part.pattern, Some(pattern) if matches!(pattern.kind, PatternKind::Tuple(_))))
}

fn binary_symbol(op: BinaryOp) -> &'static str {
    match op {
        BinaryOp::Add => "+",
        BinaryOp::Sub => "-",
        BinaryOp::Mul => "*",
        BinaryOp::Div => "/",
        BinaryOp::Mod => "%",
        BinaryOp::Pow => "**",
        BinaryOp::Eq => "==",
        BinaryOp::Ne => "!=",
        BinaryOp::Similar => "~=",
        BinaryOp::NotSimilar => "<>",
        BinaryOp::Lt => "<",
        BinaryOp::Gt => ">",
        BinaryOp::Le => "<=",
        BinaryOp::Ge => ">=",
        BinaryOp::And => "and",
        BinaryOp::Or => "or",
    }
}

fn fold_cast(name: &str, value: Constant, span: Span) -> Result<Constant> {
    use Constant::*;
    let byte = |n: i64, ty: &str| {
        u8::try_from(n).map_err(|_| {
            Error::at(
                span,
                format!("the value, {}, is outside a {}'s 0..255", n, ty),
            )
        })
    };
    match (name, value) {
        (INT_CAST | "int64", Int(n)) => Ok(Int(n)),
        (INT_CAST | "int64", Unit(n) | Char(n)) => Ok(Int(i64::from(n))),
        (INT_CAST | "int64", Bool(b)) => Ok(Int(i64::from(b))),
        (INT_CAST | "int64", Float(x))
            if x.is_finite()
                && x.trunc() >= -9_223_372_036_854_775_808.0
                && x.trunc() < 9_223_372_036_854_775_808.0 =>
        {
            Ok(Int(x.trunc() as i64))
        }
        (INT_CAST | "int64", Float(_)) => err(span, "the value doesn't fit in an int"),
        (FLOAT_CAST | "float64" | "float32", Float(x)) => Ok(Float(x)),
        (FLOAT_CAST | "float64" | "float32", Int(n)) => Ok(Float(n as f64)),
        (FLOAT_CAST | "float64" | "float32", Unit(n)) => Ok(Float(f64::from(n))),
        (UNIT_CAST | "uint8", Int(n)) => Ok(Unit(byte(n, "unit")?)),
        (UNIT_CAST | "uint8", Unit(n) | Char(n)) => Ok(Unit(n)),
        (UNIT_CAST | "uint8", Bool(b)) => Ok(Unit(u8::from(b))),
        (UNIT_CAST | "uint8", Float(x)) if x.is_finite() && (0.0..256.0).contains(&x.trunc()) => {
            Ok(Unit(x.trunc() as u8))
        }
        (UNIT_CAST | "uint8", Float(x)) => err(
            span,
            format!("the value, {}, is outside a unit's 0..255", x.trunc()),
        ),
        (CHAR_CAST, Int(n)) => Ok(Char(byte(n, "char")?)),
        (CHAR_CAST, Unit(n) | Char(n)) => Ok(Char(n)),
        (name, Int(n)) if matches!(number_cast(name), Some(ref ty) if ty.is_integer()) => {
            if let Some(ty) = number_cast(name) {
                fits_type(i128::from(n), &ty, span)?;
            }
            Ok(Int(n))
        }
        (_, value) => err(
            span,
            format!(
                "'{}(…)' doesn't take a {} in a macro's value",
                name,
                value.ty()
            ),
        ),
    }
}

fn fold_binary(op: BinaryOp, a: Constant, b: Constant, span: Span) -> Result<Constant> {
    use Constant::*;
    let symbol = binary_symbol(op);
    let too_large = |what: &str| Error::at(span, format!("the value doesn't fit in {}", what));
    let byte = |n: i64, ty: &str| {
        u8::try_from(n).map_err(|_| {
            Error::at(
                span,
                format!("the value, {}, is outside a {}'s 0..255", n, ty),
            )
        })
    };
    let float = |x: f64, by_zero: bool| match x {
        _ if x.is_finite() => Ok(Float(x)),
        _ if by_zero => err(
            span,
            "the value is no number a float can hold, as dividing by zero gives",
        ),
        _ if x.is_nan() => err(
            span,
            "the value is no number at all (nan), which a float here can't be",
        ),
        _ => err(span, "the value is too large for a float"),
    };
    match (op, a, b) {
        (BinaryOp::And, Bool(x), Bool(y)) => Ok(Bool(x && y)),
        (BinaryOp::Or, Bool(x), Bool(y)) => Ok(Bool(x || y)),
        (
            BinaryOp::Eq | BinaryOp::Ne | BinaryOp::Lt | BinaryOp::Gt | BinaryOp::Le | BinaryOp::Ge,
            x @ (Unit(_) | Int(_)),
            y @ (Unit(_) | Int(_)),
        ) if x.ty() != y.ty() => {
            let unit = |c: Constant| match c {
                Int(n) => byte(n, "unit").map(Unit),
                other => Ok(other),
            };
            fold_binary(op, unit(x)?, unit(y)?, span)
        }
        (
            BinaryOp::Eq | BinaryOp::Ne | BinaryOp::Lt | BinaryOp::Gt | BinaryOp::Le | BinaryOp::Ge,
            x,
            y,
        ) if x.ty() == y.ty() => {
            let order = match (&x, &y) {
                (Int(x), Int(y)) => x.partial_cmp(y),
                (Unit(x), Unit(y)) | (Char(x), Char(y)) => x.partial_cmp(y),
                (Float(x), Float(y)) => x.partial_cmp(y),
                (Bool(x), Bool(y)) => x.partial_cmp(y),
                (Text(x), Text(y)) => x.as_bytes().partial_cmp(y.as_bytes()),
                _ => None,
            };
            let Some(order) = order else {
                return Ok(Bool(op == BinaryOp::Ne));
            };
            if matches!(x, Bool(_)) && !matches!(op, BinaryOp::Eq | BinaryOp::Ne) {
                return err(
                    span,
                    format!("'{}' orders numbers, chars, and text, not bools", symbol),
                );
            }
            Ok(Bool(match op {
                BinaryOp::Eq => order.is_eq(),
                BinaryOp::Ne => order.is_ne(),
                BinaryOp::Lt => order.is_lt(),
                BinaryOp::Gt => order.is_gt(),
                BinaryOp::Le => order.is_le(),
                _ => order.is_ge(),
            }))
        }
        (
            BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul | BinaryOp::Div | BinaryOp::Mod,
            Int(x),
            Int(y),
        ) => {
            if y == 0 && matches!(op, BinaryOp::Div | BinaryOp::Mod) {
                return err(
                    span,
                    if op == BinaryOp::Div {
                        "division by zero"
                    } else {
                        "remainder of division by zero"
                    },
                );
            }
            let value = match op {
                BinaryOp::Add => x.checked_add(y),
                BinaryOp::Sub => x.checked_sub(y),
                BinaryOp::Mul => x.checked_mul(y),
                BinaryOp::Div => x.checked_div(y),
                _ if y == -1 => Some(0),
                _ => x.checked_rem(y),
            };
            value.map(Int).ok_or_else(|| too_large("an int"))
        }
        (
            BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul | BinaryOp::Div | BinaryOp::Mod,
            x @ (Unit(_) | Int(_)),
            y @ (Unit(_) | Int(_)),
        ) => {
            let wide = |c: Constant| -> Result<i64> {
                match c {
                    Unit(n) => Ok(i64::from(n)),
                    Int(n) => Ok(i64::from(byte(n, "unit")?)),
                    _ => Ok(0),
                }
            };
            let (x, y) = (wide(x)?, wide(y)?);
            if y == 0 && matches!(op, BinaryOp::Div | BinaryOp::Mod) {
                return err(
                    span,
                    if op == BinaryOp::Div {
                        "division by zero"
                    } else {
                        "remainder of division by zero"
                    },
                );
            }
            let value = match op {
                BinaryOp::Add => x + y,
                BinaryOp::Sub => x - y,
                BinaryOp::Mul => x * y,
                BinaryOp::Div => x / y,
                _ => x % y,
            };
            Ok(Unit(byte(value, "unit")?))
        }
        (
            BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul | BinaryOp::Div | BinaryOp::Mod,
            Float(x),
            Float(y),
        ) => float(
            match op {
                BinaryOp::Add => x + y,
                BinaryOp::Sub => x - y,
                BinaryOp::Mul => x * y,
                BinaryOp::Div => x / y,
                _ => x % y,
            },
            matches!(op, BinaryOp::Div | BinaryOp::Mod) && y == 0.0,
        ),
        (BinaryOp::Add | BinaryOp::Sub, Char(c), Int(n)) | (BinaryOp::Add, Int(n), Char(c)) => {
            let value = if op == BinaryOp::Add {
                i128::from(c) + i128::from(n)
            } else {
                i128::from(c) - i128::from(n)
            };
            u8::try_from(value).map(Char).map_err(|_| {
                Error::at(
                    span,
                    format!("the value, {}, is outside a char's 0..255", value),
                )
            })
        }
        (BinaryOp::Sub, Char(c), Char(d)) => Ok(Int(i64::from(c) - i64::from(d))),
        (BinaryOp::Add, Text(x), Text(y)) => Ok(Text(x + &y)),
        (BinaryOp::Pow, Int(x), Int(y)) if y >= 0 => {
            int_power(x, y).map(Int).ok_or_else(|| too_large("an int"))
        }
        (BinaryOp::Pow, Int(x), Unit(y)) => int_power(x, i64::from(y))
            .map(Int)
            .ok_or_else(|| too_large("an int")),
        (BinaryOp::Pow, x @ (Unit(_) | Int(_)), y @ (Unit(_) | Int(_))) if matches!(x, Unit(_)) => {
            let (Unit(x), Int(_) | Unit(_)) = (&x, &y) else {
                return err(span, "a unit is raised to a unit's power");
            };
            let y = match y {
                Unit(y) => i64::from(y),
                Int(y) => i64::from(byte(y, "unit")?),
                _ => 0,
            };
            let value = int_power(i64::from(*x), y).ok_or_else(|| too_large("a unit"))?;
            Ok(Unit(byte(value, "unit")?))
        }
        (BinaryOp::Pow, x @ (Int(_) | Unit(_) | Float(_)), y @ (Int(_) | Unit(_) | Float(_))) => {
            let wide = |c: &Constant| match c {
                Int(n) => *n as f64,
                Unit(n) => f64::from(*n),
                Float(x) => *x,
                _ => 0.0,
            };
            let (x, y) = (wide(&x), wide(&y));
            float(x.powf(y), x == 0.0 && y < 0.0)
        }
        (
            BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul | BinaryOp::Div | BinaryOp::Mod,
            Int(_),
            Float(_),
        )
        | (
            BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul | BinaryOp::Div | BinaryOp::Mod,
            Float(_),
            Int(_),
        ) => err(
            span,
            "an int and a float don't mix in arithmetic: turn one into the other first, as in 'float(n) + 2.5' (or 'n + int(2.5)', which truncates)",
        ),
        (_, x, y) => err(
            span,
            format!(
                "'{}' isn't defined for {} and {} in a macro's value",
                symbol,
                x.ty(),
                y.ty()
            ),
        ),
    }
}

fn constant_int(e: &Expr) -> Option<i64> {
    match &e.kind {
        ExprKind::IntLit(n) => Some(*n),
        ExprKind::Macro { value, .. } => constant_int(value),
        ExprKind::Unary(UnaryOp::Neg, operand) => constant_int(operand)?.checked_neg(),
        ExprKind::Binary(op, l, r) => {
            let (a, b) = (constant_int(l)?, constant_int(r)?);
            match op {
                BinaryOp::Add => a.checked_add(b),
                BinaryOp::Sub => a.checked_sub(b),
                BinaryOp::Mul => a.checked_mul(b),
                BinaryOp::Div => a.checked_div(b),
                // Special-case `-1` remainder since Rust's `checked_rem` overflows on `i64::MIN % -1`.
                BinaryOp::Mod if b == -1 => Some(0),
                BinaryOp::Mod => a.checked_rem(b),
                BinaryOp::Pow if b >= 0 => int_power(a, b),
                _ => None,
            }
        }
        _ => None,
    }
}

fn check_constant_arithmetic(
    op: BinaryOp,
    l: &Expr,
    r: &Expr,
    ty: &Type,
    span: Span,
) -> Result<()> {
    let divisor = constant_int(r);
    if divisor == Some(0) {
        match op {
            BinaryOp::Div => return err(span, "division by zero"),
            BinaryOp::Mod => return err(span, "remainder of division by zero"),
            _ => {}
        }
    }
    let (Some(a), Some(b)) = (constant_int(l), divisor) else {
        return Ok(());
    };
    let (a, b) = (i128::from(a), i128::from(b));
    let exact = match op {
        BinaryOp::Add => a + b,
        BinaryOp::Sub => a - b,
        BinaryOp::Mul => a * b,
        BinaryOp::Div => a / b,
        _ => return Ok(()),
    };
    if *ty == Type::Int {
        fits_int(exact, span)
    } else {
        fits_type(exact, ty, span)
    }
}

fn constant_key(e: &Expr) -> Option<String> {
    match &e.kind {
        ExprKind::TextLit(text) => Some(format!("\"{}\"", text)),
        ExprKind::CharLit(c) => Some(format!("'{}'", char::from(*c).escape_default())),
        ExprKind::BoolLit(b) => Some(b.to_string()),
        ExprKind::Macro { value, .. } => constant_key(value),
        _ => constant_int(e).map(|n| n.to_string()),
    }
}

fn key_problem(key: &Type, is_param: &dyn Fn(&str) -> bool) -> Option<String> {
    match key {
        _ if key.is_integer() => None,
        Type::Char
        | Type::Bool
        | Type::Text(_)
        | Type::Ptr(..)
        | Type::Unknown
        | Type::Param(_) => None,
        Type::Named(name, _) if is_param(name) => None,
        Type::Tuple(items) => items.iter().find_map(|item| key_problem(item, is_param)),
        Type::Float => Some("a float, which nan makes unequal to itself".to_string()),
        other => Some(format!("{}", other)),
    }
}

fn integer_range(ty: &Type) -> Option<(i128, i128)> {
    match ty {
        Type::Int8 => Some((i8::MIN as i128, i8::MAX as i128)),
        Type::Int16 => Some((i16::MIN as i128, i16::MAX as i128)),
        Type::Int32 => Some((i32::MIN as i128, i32::MAX as i128)),
        Type::Int => Some((i64::MIN as i128, i64::MAX as i128)),
        Type::Unit | Type::Char => Some((0, 255)),
        Type::Uint16 => Some((0, u16::MAX as i128)),
        Type::Uint32 => Some((0, u32::MAX as i128)),
        Type::Uint64 => Some((0, u64::MAX as i128)),
        _ => None,
    }
}

fn fits_type(n: i128, ty: &Type, span: Span) -> Result<()> {
    if let Some((min, max)) = integer_range(ty) {
        if n >= min && n <= max {
            return Ok(());
        }
        return err(
            span,
            format!(
                "{} doesn't fit in {}, which holds {} to {}",
                n,
                a_type(ty),
                min,
                max
            ),
        );
    }
    Ok(())
}

fn numeric_literal(e: &mut Expr, target: &Type) -> Result<bool> {
    if e.ty != Some(Type::Int) {
        return Ok(false);
    }
    if !target.is_integer() {
        return Ok(false);
    }
    let Some(n) = constant_int(e) else {
        return Ok(false);
    };
    fits_type(i128::from(n), target, e.span)?;
    e.ty = Some(target.clone());
    Ok(true)
}

fn step_parts(value: Expr, region: &str, at: Span, parts: &mut Vec<Expr>) {
    match value.kind {
        ExprKind::Binary(BinaryOp::Add, left, right) => {
            step_parts(*left, region, at, parts);
            step_parts(*right, region, at, parts);
        }
        ExprKind::Join {
            parts: pieces,
            region: named,
            ..
        } if named.is_empty() => crate::parser::interpolated_parts(pieces, region, at, parts),
        kind => parts.push(Expr { kind, ..value }),
    }
}

fn changing_part(e: &Expr) -> Option<Span> {
    match &e.kind {
        ExprKind::Var(_)
        | ExprKind::Macro { .. }
        | ExprKind::Shared { .. }
        | ExprKind::IntLit(_)
        | ExprKind::FloatLit(_)
        | ExprKind::CharLit(_)
        | ExprKind::BoolLit(_)
        | ExprKind::TextLit(_) => None,
        ExprKind::Field(inner, _) | ExprKind::Deref(inner) | ExprKind::Unary(_, inner) => {
            changing_part(inner)
        }
        ExprKind::Index(a, b) | ExprKind::Binary(_, a, b) => {
            changing_part(a).or_else(|| changing_part(b))
        }
        ExprKind::Call { name, args, .. } if number_cast(name).is_some() => {
            args.iter().find_map(changing_part)
        }
        _ => Some(e.span),
    }
}

fn a_type(ty: &Type) -> String {
    match ty {
        Type::Text(_) => "text".to_string(),
        Type::Int | Type::Int8 | Type::Int16 | Type::Int32 => format!("an {}", ty),
        other => format!("a {}", other),
    }
}

fn check_power(l: &Expr, r: &Expr, lt: &Type, rt: &Type, span: Span) -> Result<Type> {
    let number = |ty: &Type| ty.is_numeric();
    if !number(lt) || !number(rt) {
        let other = if number(lt) { rt } else { lt };
        let hint = match other {
            Type::Char => {
                "; a char is a character, so turn it into its code first, as in 'int(c) ** 2'"
                    .to_string()
            }
            _ => extract_hint(&[lt, rt]),
        };
        let what = if matches!(other, Type::Text(_)) {
            format!("{}", other)
        } else {
            format!("a {}", other)
        };
        return err(
            span,
            format!(
                "'**' raises a number to a power, and this is {}{}",
                what, hint
            ),
        );
    }
    match (lt, rt) {
        (Type::Unit, Type::Unit) => Ok(Type::Unit),
        (Type::Unit, Type::Int) => err(
            r.span,
            "a unit is raised to a unit's power, as in 'b ** 2' or 'b ** unit(n)'; for an int, write 'int(b) ** n'",
        ),
        (Type::Int, Type::Unit) => Ok(Type::Int),
        (Type::Int, Type::Int) => match constant_int(r) {
            Some(exponent) if exponent >= 0 => {
                if let Some(base) = constant_int(l)
                    && int_power(base, exponent).is_none()
                {
                    return err(
                        span,
                        format!(
                            "integer overflow: {} ** {} doesn't fit in an int, which holds {} to {}",
                            base,
                            exponent,
                            i64::MIN,
                            i64::MAX
                        ),
                    );
                }
                Ok(Type::Int)
            }
            _ => Ok(Type::Float),
        },
        (Type::Float32, Type::Float32) => Ok(Type::Float32),
        (sized, power) if sized == power && sized.is_integer() => {
            if sized.is_signed_int() && !constant_int(r).is_some_and(|exponent| exponent >= 0) {
                return err(
                    r.span,
                    format!(
                        "{0} is raised to a constant power 0 or more, as in 'x ** 2', since a negative one makes a fraction; for another power, turn both into floats, as in 'float(x) ** float(k)'",
                        a_type(sized)
                    ),
                );
            }
            Ok(sized.clone())
        }
        (Type::Int | Type::Float | Type::Unit, Type::Int | Type::Float | Type::Unit) => {
            Ok(Type::Float)
        }
        _ => err(
            span,
            format!(
                "'**' takes a number and a power of one type, and this raises {} to {}; turn one into the other first, as in '{}(k)'",
                a_type(lt),
                a_type(rt),
                lt
            ),
        ),
    }
}

fn float32_literal(e: &mut Expr) -> bool {
    let written = match &mut e.kind {
        ExprKind::FloatLit(_) => true,
        ExprKind::Unary(UnaryOp::Neg, inner) => float32_literal(inner),
        _ => false,
    };
    if written {
        e.ty = Some(Type::Float32);
    }
    written
}

fn int_power(base: i64, exponent: i64) -> Option<i64> {
    match base {
        0 => Some(i64::from(exponent == 0)),
        1 => Some(1),
        -1 => Some(if exponent % 2 == 0 { 1 } else { -1 }),
        _ => base.checked_pow(u32::try_from(exponent).ok()?),
    }
}

fn char_arithmetic(
    op: BinaryOp,
    l: &Expr,
    r: &Expr,
    lt: &Type,
    rt: &Type,
    span: Span,
) -> Result<Type> {
    let symbol = match op {
        BinaryOp::Add => "+",
        BinaryOp::Sub => "-",
        BinaryOp::Mul => "*",
        BinaryOp::Div => "/",
        _ => "%",
    };
    let ty = match (op, lt, rt) {
        (BinaryOp::Add, Type::Char, Type::Int)
        | (BinaryOp::Add, Type::Int, Type::Char)
        | (BinaryOp::Sub, Type::Char, Type::Int) => Type::Char,
        (BinaryOp::Sub, Type::Char, Type::Char) => return Ok(Type::Int),
        (BinaryOp::Add, Type::Char, Type::Char) => {
            return err(
                span,
                "two chars don't add up to a char: move a char by a number, as in 'c + 1', or take one from another for how far apart they are, as in 'c - 'a''",
            );
        }
        (BinaryOp::Sub, Type::Int, Type::Char) => {
            return err(
                span,
                "a char is taken from a char, as in 'c - 'a'', or moved back by a number, as in 'c - 1'; to take a char's code from a number, write 'n - int(c)'",
            );
        }
        (BinaryOp::Add | BinaryOp::Sub, _, _) => {
            let other = if *lt == Type::Char { rt } else { lt };
            return err(
                span,
                format!(
                    "a char moves by an int, as in 'c {} 1', not by a {}{}",
                    symbol,
                    other,
                    extract_hint(&[other])
                ),
            );
        }
        _ => {
            return err(
                span,
                format!(
                    "'{}' works on numbers, and a char is a character; turn it into its code first, as in 'int(c) {} 2'",
                    symbol, symbol
                ),
            );
        }
    };
    let (char_side, number) = if *lt == Type::Char { (l, r) } else { (r, l) };
    if let (ExprKind::CharLit(c), Some(n)) = (&char_side.kind, constant_int(number)) {
        let moved = if op == BinaryOp::Add {
            i128::from(*c) + i128::from(n)
        } else {
            i128::from(*c) - i128::from(n)
        };
        if !(0..=255).contains(&moved) {
            return err(
                span,
                format!(
                    "the result, {}, doesn't fit in a char, which holds 0 to 255",
                    moved
                ),
            );
        }
    }
    Ok(ty)
}

fn fits_int(value: i128, span: Span) -> Result<()> {
    if value > i128::from(i64::MAX) {
        return err(
            span,
            format!(
                "integer overflow: the result, {}, is more than an int holds (at most {})",
                value,
                i64::MAX
            ),
        );
    }
    if value < i128::from(i64::MIN) {
        return err(
            span,
            format!(
                "integer overflow: the result, {}, is less than an int holds (at least {})",
                value,
                i64::MIN
            ),
        );
    }
    Ok(())
}

fn task_way_hint(actual: &Type, expected: &Type) -> String {
    let task_of = |ty: &Type| match ty {
        Type::Task(task) => Some(task.as_ref().clone()),
        Type::Closure(closure) => Some(closure.task.clone()),
        _ => None,
    };
    if let (Some(given), Some(wanted)) = (task_of(actual), task_of(expected))
        && given.params == wanted.params
        && given
            .taken
            .iter()
            .zip(&wanted.taken)
            .any(|(a, e)| *a == Taken::Flex && matches!(e, Taken::Value | Taken::Bind))
    {
        let marked = TaskType {
            taken: wanted
                .taken
                .iter()
                .zip(&given.taken)
                .map(|(e, a)| {
                    if *a == Taken::Flex {
                        Taken::Flex
                    } else {
                        e.clone()
                    }
                })
                .collect(),
            ..wanted
        };
        let marked = match expected {
            Type::Closure(closure) => Type::Closure(Box::new(ClosureType {
                task: marked,
                ..closure.as_ref().clone()
            })),
            _ => Type::Task(Box::new(marked)),
        };
        return format!(
            "; this task changes what a twofold value it is given reaches, a slice, a map or a pointer or what holds one, so it goes only where the type says 'flex' for that value, as in '{}', and nothing a fixed name owns is given to it there",
            marked
        );
    }
    if let (Some(given), Some(wanted)) = (task_of(actual), task_of(expected))
        && given.params == wanted.params
        && given
            .taken
            .iter()
            .zip(&wanted.taken)
            .any(|(a, e)| *a == Taken::Bind && *e == Taken::Value)
    {
        let marked = TaskType {
            taken: wanted
                .taken
                .iter()
                .zip(&given.taken)
                .map(|(e, a)| {
                    if *a == Taken::Bind {
                        Taken::Bind
                    } else {
                        e.clone()
                    }
                })
                .collect(),
            ..wanted
        };
        let marked = match expected {
            Type::Closure(closure) => Type::Closure(Box::new(ClosureType {
                task: marked,
                ..closure.as_ref().clone()
            })),
            _ => Type::Task(Box::new(marked)),
        };
        return format!(
            "; this task changes what a twofold value it is given reaches, a slice, a map or a pointer or what holds one, so it goes only where the type says 'bind' for that value, as in '{}', and nothing a fixed name owns is given to it there",
            marked
        );
    }
    if let (Some(given), Some(wanted)) = (task_of(actual), task_of(expected))
        && given.params == wanted.params
        && let Some(passing) =
            given
                .taken
                .iter()
                .zip(&wanted.taken)
                .find_map(|(a, e)| match (a, e) {
                    (Taken::Place(passing), Taken::Value | Taken::Flex | Taken::Bind) => {
                        Some(*passing)
                    }
                    _ => None,
                })
    {
        return format!(
            "; this task takes the caller's place, '{0}', which the call marks with '&', so the type says '{0}' for it too",
            passing.word()
        );
    }
    String::new()
}

fn mismatch_hint(actual: &Type, expected: &Type) -> String {
    if let (Type::Closure(closure), Type::Task(_)) = (actual, expected) {
        return format!(
            "; a lambda that keeps what it uses goes only where a type naming its region is expected, as '[@{0}](…)', since a task's type names none and the lambda could outlive '{0}'",
            closure.region
        );
    }
    let ways = task_way_hint(actual, expected);
    if !ways.is_empty() {
        return ways;
    }
    if let Some(item) = [actual, expected].into_iter().find_map(|ty| match ty {
        Type::Param(name) if name.contains(GROUP_ITEM) => Some(name.clone()),
        _ => None,
    }) {
        let (group, place) = item.split_once(GROUP_ITEM).unwrap_or((item.as_str(), "0"));
        let turn = [actual, expected]
            .into_iter()
            .any(|ty| matches!(ty, Type::Param(name) if name == group));
        let apart = if turn {
            format!(
                ", and '{}' alone is the type of the value of a turn of 'each v in args', so they may be different types",
                group
            )
        } else {
            String::new()
        };
        let value = place.parse::<usize>().map_or(1, |k| k + 1);
        return format!(
            "; {0} is the type of value {1} of the group '{2}...', item {3} of its tuple{4}",
            item, value, group, place, apart
        );
    }
    match (actual, expected) {
        (Type::Array(items, _), Type::Slice(wanted, _)) if items.without_regions() == wanted.without_regions() => {
            "; an array never becomes a slice: write the values as a slice, as in '[1, 2, ...] at r', or copy them into one, as in 'new [int](xs) at r'".to_string()
        }
        (Type::Int | Type::Float, Type::Unit) => "; turn it into a unit with 'unit(x)', which stops the program when it isn't from 0 to 255".to_string(),
        (Type::Int, Type::Float) => "; an int doesn't become a float on its own: write a float as '1.0', or turn an int into one with 'float(n)'".to_string(),
        (Type::Unit, Type::Int | Type::Float) => format!("; turn it into {0} with '{1}(b)'", if *expected == Type::Int { "an int" } else { "a float" }, expected),
        (Type::None, Type::Ptr(..)) => format!("; a pointer can't be none, so use 'maybe {}'", expected),
        (Type::None, Type::Slice(..)) => format!("; a slice can't be none, so use 'maybe {}'", expected),
        (Type::None, Type::Map(..)) => format!("; a map can't be none, so use 'maybe {}'", expected),
        (Type::None, Type::Or(value, _)) if value.ptr_inner().is_some() => {
            format!("; a pointer can't be none, so use 'maybe {}'", value)
        }
        (_, Type::Or(_, error)) if fits_regions(actual, error) => "; an error is given with 'fail', as in '<- fail e'".to_string(),
        (Type::Fail(_), _) => "; 'fail …' is an error, which only a 'T ~ E' can hold".to_string(),
        (Type::Task(_), Type::Task(_)) if strip_all_regions(actual) == strip_all_regions(expected) => {
            "; a task's type says which regions its values are in, as its header does: 'text' is text that lasts as long as the program, and 'text@r' text of any region the caller gives".to_string()
        }
        (Type::Maybe(inner) | Type::Or(inner, _), _) if fits_regions(inner, expected) => {
            "; extract its value first, as in 'x { … }' or 'when x is {value}'".to_string()
        }
        _ if actual.regions().contains(&UNNAMED_REGION) => {
            format!("; a type test on an item whose type each use gives takes what may be in a region of the caller's, written '{}', which only this task sees; to keep it, copy it into a region of its own, as in 's.copy()@r'", UNNAMED_REGION)
        }
        (Type::Text(Some(region)), Type::Text(None)) => {
            format!("; this text is in region '{}', and text here must last as long as the program, as a literal does", region)
        }
        (Type::Text(Some(region)), Type::Text(Some(other))) => format!("; this text is in region '{}', and text here is in region '{}'", region, other),
        (Type::Named(name, Some(region)), Type::Named(expected_name, Some(other))) if name == expected_name && region != ANY_REGION && other != ANY_REGION => {
            format!("; a value can't move to another region: what it holds in region '{}' is never stored in region '{}'", region, other)
        }
        (Type::Named(name, Some(region)), Type::Named(expected_name, None)) if name == expected_name => format!(
            "; this value holds text in region '{0}', and a '{1}' here holds text that lasts as long as the program; to keep text of a region, name it, as in '{1}@{0}'",
            region, name
        ),
        _ if [Some(expected), expected.extracted()].into_iter().flatten().any(|e| actual.without_regions() == e.without_regions()) => {
            let inner = [Some(expected), expected.extracted()]
                .into_iter()
                .flatten()
                .find_map(|e| region_mismatch(actual, e))
                .filter(|(a, e)| !std::ptr::eq(*a, actual) || !std::ptr::eq(*e, expected))
                .map(|(a, e)| mismatch_hint(a, e))
                .filter(|hint| !hint.is_empty());
            if let Some(hint) = inner {
                return hint;
            }
            if expected.regions().contains(&ANY_REGION) {
                "; this place holds a value without pointers (of no region), so it can't take a pointer into one".to_string()
            } else {
                "; a value can't move to another region: a pointer into one region is never stored in another".to_string()
            }
        }
        _ if remade_inside(actual, expected) => {
            let parts = match actual {
                Type::Tuple(items) => format!(", as in '({})'", (0..items.len()).map(|i| format!("v.{}", i)).collect::<Vec<_>>().join(", ")),
                Type::Maybe(_) | Type::Or(..) => ", taking its value out first, as in 'v { … }'".to_string(),
                _ => String::new(),
            };
            format!("; a value already made is never changed inside, so build one that is what this place holds{}", parts)
        }
        _ => String::new(),
    }
}

fn region_mismatch<'a>(actual: &'a Type, expected: &'a Type) -> Option<(&'a Type, &'a Type)> {
    match (actual, expected) {
        (Type::Text(a), Type::Text(e)) | (Type::Named(_, a), Type::Named(_, e)) => {
            (a != e).then_some((actual, expected))
        }
        (Type::Maybe(a), Type::Maybe(e))
        | (Type::Array(a, _), Type::Array(e, _))
        | (Type::Fail(a), Type::Fail(e)) => region_mismatch(a, e),
        (Type::Or(av, ae), Type::Or(ev, ee)) => {
            region_mismatch(av, ev).or_else(|| region_mismatch(ae, ee))
        }
        (Type::Tuple(a), Type::Tuple(e)) => {
            a.iter().zip(e).find_map(|(a, e)| region_mismatch(a, e))
        }
        _ => None,
    }
}

#[derive(Clone, Copy, PartialEq)]
enum Given {
    Sent,
    Items,
}

fn given_by(values: &[Expr]) -> Given {
    match values {
        [only] if matches!(only.ty, Some(Type::Tuple(_))) => Given::Items,
        _ => Given::Sent,
    }
}

fn fits_or_err(actual: &Type, expected: &Type, at: Span, given: Given) -> Result<()> {
    if fits_regions(actual, expected) {
        return Ok(());
    }
    let wrapping = match expected {
        Type::Maybe(inner) => *actual == Type::None || fits_regions(actual, inner),
        Type::Or(value, error) => match actual {
            Type::Fail(given) => fits_regions(given, error),
            _ => fits_regions(actual, value),
        },
        _ => false,
    };
    let hint = if wrapping && given == Given::Items {
        format!(
            "; a tuple's items are taken as they are, so an item doesn't become a {} on the way",
            expected
        )
    } else if wrapping {
        format!(
            "; a task sends each of its values as it is, so it doesn't become a {} on the way",
            expected
        )
    } else {
        mismatch_hint(actual, expected)
    };
    err(
        at,
        format!("expected type {}, got {}{}", expected, actual, hint),
    )
}

const SCAN_TAKES: &str = "'scan' takes the prompt it shows, and the type of a number to read, as in 'scan(\"Name: \") at r' or 'scan(\"Age: \", int)'";

fn scanned_type(arg: &Expr) -> Result<Type> {
    if let ExprKind::Var(name) = &arg.kind {
        if let Some(number) = number_cast(name).filter(|number| *number != Type::Char) {
            return Ok(number);
        }
        if matches!(Type::builtin(name), Some(Type::Text(_))) {
            return err(
                arg.span,
                "'scan' reads text on its own, so 'text' is left out: write 'scan(\"Name: \") at r'",
            );
        }
    }
    err(
        arg.span,
        "'scan' reads a number, so it names 'int', 'float', or 'unit', as in 'scan(\"Age: \", int)'",
    )
}

fn piped_arg(call: &mut Expr) -> Option<&mut Expr> {
    match &mut call.kind {
        ExprKind::Call { args, .. }
        | ExprKind::MethodCall { args, .. }
        | ExprKind::Invoke { args, .. }
        | ExprKind::Construct { args, .. } => args
            .iter_mut()
            .find(|arg| matches!(arg.kind, ExprKind::Piped(_))),
        _ => None,
    }
}

fn piped_name(call: &Expr) -> String {
    match &call.kind {
        ExprKind::Call { name, args, .. } => match (method_parts(name), args.first()) {
            (Some((_, method)), Some(value)) if !matches!(value.kind, ExprKind::Piped(_)) => {
                format!("x.{}", method)
            }
            (Some((owner, method)), _) => format!("{}.{}", unqualified(owner), method),
            _ => unqualified(name).to_string(),
        },
        _ => "f".to_string(),
    }
}

fn piped_position(call: &Expr) -> usize {
    match &call.kind {
        ExprKind::Call { args, .. }
        | ExprKind::MethodCall { args, .. }
        | ExprKind::Invoke { args, .. }
        | ExprKind::Construct { args, .. } => args
            .iter()
            .position(|arg| matches!(arg.kind, ExprKind::Piped(_)))
            .map_or(1, |at| at + 1),
        _ => 1,
    }
}

fn piped_callee(call: &Expr) -> String {
    match &call.kind {
        ExprKind::Call { name, .. } => format!("'{}'", name),
        ExprKind::MethodCall { name, .. } => format!("'{}'", name),
        ExprKind::Construct { tag, .. } => format!("'{}'", tag),
        _ => "the task after it".to_string(),
    }
}

fn ignored_error(task: &str) -> String {
    if let Some((owner, method)) = method_parts(task) {
        return format!(
            "the error '{0}{1}{2}' may send is ignored; handle it with a plan B, as in 'value.{2}(…) {{ failure e … }}', or with match",
            owner, MODULE_SEPARATOR, method
        );
    }
    format!(
        "the error '{0}' may send is ignored; handle it with a plan B, as in '{0}(…) {{ failure e … }}', or with match",
        task
    )
}

fn dropped_error(ty: &Type) -> String {
    format!(
        "'_' would drop the error in a value of type {}; give it a name, then handle it with a plan B or match",
        ty
    )
}

fn example_names(n: usize) -> String {
    let names: Vec<String> = (0..n.min(3))
        .filter_map(|i| u8::try_from(i).ok())
        .map(|i| char::from(b'a' + i).to_string())
        .collect();
    if n > 3 {
        format!("{}, …", names.join(", "))
    } else {
        names.join(", ")
    }
}

fn check_str_method(t: &TaskDef) -> Result<()> {
    let written = "a method named 'str' turns the value it is called on into text, so it is written 'str(r: region) -> text@r'";
    if t.private {
        return err(
            t.span,
            "a method named 'str' says how the value is written as text wherever it is shown, so it isn't 'priv'",
        );
    }
    if let Some(at) = t.owner.as_ref().and_then(|owner| owner.alters_span) {
        return err(
            at,
            "a method named 'str' turns the value it is called on into text without changing it, so it isn't marked 'alters'",
        );
    }
    let region = match t.params.get(1..) {
        Some([param]) if param.ty == Type::Region => &param.name,
        _ => return err(t.span, written),
    };
    if t.ret != Type::Text(Some(region.clone())) {
        return err(t.span, written);
    }
    Ok(())
}

fn check_json_method(t: &TaskDef) -> Result<()> {
    let written = "a method named 'json' turns the value it is called on into JSON text, so it is written 'json(r: region) -> text@r'";
    if t.private {
        return err(
            t.span,
            "a method named 'json' says how the value is written as JSON wherever it is shown, so it isn't 'priv'",
        );
    }
    if let Some(at) = t.owner.as_ref().and_then(|owner| owner.alters_span) {
        return err(
            at,
            "a method named 'json' turns the value it is called on into JSON text without changing it, so it isn't marked 'alters'",
        );
    }
    let region = match t.params.get(1..) {
        Some([param]) if param.ty == Type::Region => &param.name,
        _ => return err(t.span, written),
    };
    if t.ret != Type::Text(Some(region.clone())) {
        return err(t.span, written);
    }
    Ok(())
}

fn count(n: usize, noun: &str) -> String {
    if n == 1 {
        format!("1 {}", noun)
    } else {
        format!("{} {}s", n, noun)
    }
}

/// Rewrites region/variable diagnostics into startup-context messages for decorators and wrapper args.
fn at_start_error(mut error: Error, what: &str) -> Error {
    let no_region = format!(
        "{} are worked out where the program starts, before any region exists, so none of them can be made in one",
        what
    );
    if error.message.starts_with("unknown region") {
        error.message = no_region;
    } else if error.message.starts_with("unknown variable") {
        error.message.push_str(&format!(
            "; {} are worked out where the program starts, where no variable exists yet",
            what
        ));
    } else if error.message.contains("region") {
        error.message = format!("{}; but {}", error.message, no_region);
    }
    error
}

fn wrapper_call(body: &mut Block) -> Option<&mut Expr> {
    match &mut body.first_mut()?.kind {
        StmtKind::Expr(call) => Some(call),
        StmtKind::Send(values) => values.first_mut(),
        _ => None,
    }
}

#[derive(Default)]
struct Calls {
    tasks: Vec<String>,
    invokes: bool,
}

/// Call graph used to topologically order startup wrapper value initializers.
struct CallGraph {
    calls: HashMap<String, Calls>,
    named: HashMap<String, Vec<String>>,
    values: Vec<String>,
}

#[derive(Clone)]
enum Reached {
    Start,
    From(String),
    ThroughValue(String),
}

impl CallGraph {
    fn of(items: &[Item], checker: &Checker) -> CallGraph {
        let mut calls = HashMap::new();
        let mut named = HashMap::new();
        let mut values = Vec::new();
        for item in items {
            match item {
                Item::Task(task) => {
                    let mut found = Calls::default();
                    let mut names = Vec::new();
                    walk_block(&task.body, &mut |e| {
                        checker.note_calls(e, &mut found);
                        note_value(e, &mut names);
                    });
                    calls.insert(task.name.clone(), found);
                    named.insert(task.name.clone(), names);
                }
                Item::Shape(shape) => {
                    for value in shape
                        .shared
                        .iter()
                        .filter_map(|member| member.field.default.as_ref())
                    {
                        walk_expr(value, &mut |e| note_value(e, &mut values));
                    }
                }
                Item::GlobalRegion(g) => {
                    for stmt in &g.stmts {
                        if let StmtKind::Binding { init, .. } = &stmt.kind {
                            for value in init {
                                walk_expr(value, &mut |e| note_value(e, &mut values));
                            }
                        }
                    }
                }
                Item::Kind(_) | Item::Macro(_) => {}
            }
        }
        CallGraph {
            calls,
            named,
            values,
        }
    }

    fn settle_values(&mut self, roots: &Calls, values: Vec<String>) {
        for name in values {
            if !self.values.contains(&name) {
                self.values.push(name);
            }
        }
        loop {
            let before = self.values.len();
            let reached: Vec<String> = self.reach(roots).into_keys().collect();
            for task in reached {
                for name in self.named.get(&task).cloned().unwrap_or_default() {
                    if !self.values.contains(&name) {
                        self.values.push(name);
                    }
                }
            }
            if self.values.len() == before {
                return;
            }
        }
    }

    fn reach(&self, roots: &Calls) -> HashMap<String, Reached> {
        let mut reached: HashMap<String, Reached> = HashMap::new();
        let mut next: Vec<String> = Vec::new();
        let visit = |name: &String,
                     how: Reached,
                     reached: &mut HashMap<String, Reached>,
                     next: &mut Vec<String>| {
            if !reached.contains_key(name) {
                reached.insert(name.clone(), how);
                next.push(name.clone());
            }
        };
        for name in &roots.tasks {
            visit(name, Reached::Start, &mut reached, &mut next);
        }
        if roots.invokes {
            for name in &self.values {
                visit(
                    name,
                    Reached::ThroughValue(String::new()),
                    &mut reached,
                    &mut next,
                );
            }
        }
        while let Some(task) = next.pop() {
            let Some(calls) = self.calls.get(&task) else {
                continue;
            };
            for name in &calls.tasks {
                visit(name, Reached::From(task.clone()), &mut reached, &mut next);
            }
            if calls.invokes {
                for name in &self.values {
                    visit(
                        name,
                        Reached::ThroughValue(task.clone()),
                        &mut reached,
                        &mut next,
                    );
                }
            }
        }
        reached
    }

    fn path(&self, reached: &HashMap<String, Reached>, target: &str) -> String {
        let mut steps: Vec<Option<String>> = Vec::new();
        let mut at = target.to_string();
        for _ in 0..reached.len() {
            match reached.get(&at) {
                Some(Reached::From(from)) => at = from.clone(),
                Some(Reached::ThroughValue(from)) => {
                    if steps.last() != Some(&None) {
                        steps.push(None);
                    }
                    if from.is_empty() {
                        break;
                    }
                    at = from.clone();
                }
                Some(Reached::Start) | None => break,
            }
            let shown = Some(called_name(&at));
            if steps.last() != Some(&shown) && at != target {
                steps.push(shown);
            }
        }
        steps.reverse();
        let through: Vec<String> = steps
            .iter()
            .map(|step| match step {
                Some(name) => format!("'{}'", name),
                None => "a task held as a value".to_string(),
            })
            .collect();
        match through.len() {
            0 => String::new(),
            _ => format!(" through {}", through.join(", then ")),
        }
    }
}

fn note_value(e: &Expr, names: &mut Vec<String>) {
    if let ExprKind::TaskValue(name) = &e.kind
        && !name.contains(LAYER)
        && !names.contains(name)
    {
        names.push(name.clone());
    }
}

fn called_name(name: &str) -> String {
    let name = name.split(LAYER).next().unwrap_or(name);
    if is_lambda(name) {
        return "a lambda".to_string();
    }
    match method_parts(name) {
        Some((owner, method)) => format!("{}{}{}", owner, MODULE_SEPARATOR, method),
        None => name.to_string(),
    }
}

fn start_order<'a>(
    units: &[&'a str],
    needs: &HashMap<&'a str, Vec<(&'a str, &'a StartValue)>>,
) -> std::result::Result<Vec<&'a str>, Vec<(&'a StartValue, String)>> {
    // Iterative DFS avoids overflowing compiler stack on deep start-value chains.
    let mut state: HashMap<&str, bool> = HashMap::new();
    let mut order = Vec::new();
    for &unit in units {
        if state.contains_key(unit) {
            continue;
        }
        state.insert(unit, false);
        let mut stack: Vec<(&str, usize)> = vec![(unit, 0)];
        while let Some((task, i)) = stack.last_mut() {
            let task: &str = task;
            let wanted = needs.get(task).and_then(|wanted| wanted.get(*i)).copied();
            *i += 1;
            match wanted {
                Some((other, _)) => match state.get(other) {
                    None => {
                        state.insert(other, false);
                        stack.push((other, 0));
                    }
                    Some(false) => {
                        let from = stack.iter().position(|(on, _)| *on == other).unwrap_or(0);
                        let tasks: Vec<&str> = stack
                            .get(from..)
                            .unwrap_or_default()
                            .iter()
                            .map(|(on, _)| *on)
                            .collect();
                        let circle = tasks
                            .iter()
                            .enumerate()
                            .filter_map(|(k, &on)| {
                                let then = tasks.get(k + 1).copied().unwrap_or(other);
                                needs
                                    .get(on)?
                                    .iter()
                                    .find(|(called, _)| *called == then)
                                    .map(|(_, start)| (*start, then.to_string()))
                            })
                            .collect();
                        return Err(circle);
                    }
                    Some(true) => {}
                },
                None => {
                    state.insert(task, true);
                    order.push(task);
                    stack.pop();
                }
            }
        }
    }
    Ok(order)
}

fn walk_block(block: &[Stmt], f: &mut dyn FnMut(&Expr)) {
    for stmt in block {
        walk_stmt(stmt, f);
    }
}

fn walk_stmt(stmt: &Stmt, f: &mut dyn FnMut(&Expr)) {
    visit_stmt(stmt, &mut |e| {
        f(e);
        true
    });
}

fn visit_stmt(stmt: &Stmt, f: &mut dyn FnMut(&Expr) -> bool) {
    match &stmt.kind {
        StmtKind::Expr(e) => visit_expr(e, f),
        StmtKind::Step { target, value, .. } => {
            visit_expr(target, f);
            visit_expr(value, f);
        }
        StmtKind::Send(values)
        | StmtKind::SetResults(_, values)
        | StmtKind::Binding { init: values, .. } => values.iter().for_each(|e| visit_expr(e, f)),
        StmtKind::Assign(targets, values) => {
            targets.iter().for_each(|target| visit_target(target, f));
            values.iter().for_each(|e| visit_expr(e, f));
        }
        StmtKind::When(arms, else_block) => {
            for arm in arms {
                arm.cond.parts().for_each(|part| visit_expr(&part.value, f));
                visit_block(&arm.body, f);
            }
            if let Some(block) = else_block {
                visit_block(block, f);
            }
        }
        StmtKind::Loop(cond, block, finally) => {
            cond.parts().for_each(|part| visit_expr(&part.value, f));
            visit_block(block, f);
            if let Some(finally) = finally {
                visit_block(finally, f);
            }
        }
        StmtKind::Parted(parted) => {
            visit_block(&parted.start, f);
            parted
                .cond
                .iter()
                .flat_map(Condition::parts)
                .for_each(|part| visit_expr(&part.value, f));
            visit_block(&parted.step, f);
            visit_block(&parted.body, f);
            if let Some(finally) = &parted.finally {
                visit_block(finally, f);
            }
        }
        StmtKind::Block(block) => visit_block(block, f),
        StmtKind::Turns(turns) => turns.iter().for_each(|turn| visit_block(turn, f)),
        StmtKind::Named(_, inner) => visit_stmt(inner, f),
        StmtKind::Each(_, _, source, block, finally) => {
            visit_expr(source, f);
            visit_block(block, f);
            if let Some(finally) = finally {
                visit_block(finally, f);
            }
        }
        StmtKind::Match(subject, cases) => {
            visit_expr(subject, f);
            cases.iter().for_each(|case| visit_block(&case.body, f));
        }
        StmtKind::Break(_, Some(value)) => visit_expr(value, f),
        StmtKind::Region { .. } | StmtKind::Break(..) | StmtKind::Continue(_) => {}
    }
}

fn visit_target(target: &Target, f: &mut dyn FnMut(&Expr) -> bool) {
    match target {
        Target::Discard(_) => {}
        Target::Place(place) => visit_expr(place, f),
        Target::Tuple(parts, _) => parts.iter().for_each(|part| visit_target(part, f)),
    }
}

fn walk_expr(e: &Expr, f: &mut dyn FnMut(&Expr)) {
    visit_expr(e, &mut |e| {
        f(e);
        true
    });
}

fn visit_block(block: &[Stmt], f: &mut dyn FnMut(&Expr) -> bool) {
    for stmt in block {
        visit_stmt(stmt, f);
    }
}

fn visit_expr(e: &Expr, f: &mut dyn FnMut(&Expr) -> bool) {
    if !f(e) {
        return;
    }
    let each = |values: &[Expr], f: &mut dyn FnMut(&Expr) -> bool| {
        values.iter().for_each(|value| visit_expr(value, f))
    };
    match &e.kind {
        ExprKind::IntLit(_)
        | ExprKind::FloatLit(_)
        | ExprKind::CharLit(_)
        | ExprKind::BoolLit(_)
        | ExprKind::TextLit(_)
        | ExprKind::NoneLit
        | ExprKind::Macro { .. }
        | ExprKind::Var(_)
        | ExprKind::TaskValue(_)
        | ExprKind::RegionAfter(_)
        | ExprKind::Shared { .. }
        | ExprKind::TypeOf(_)
        | ExprKind::Closure { .. } => {}
        ExprKind::Kept { value: inner, .. }
        | ExprKind::Spread(inner)
        | ExprKind::Own(inner)
        | ExprKind::Field(inner, _)
        | ExprKind::Unary(_, inner)
        | ExprKind::Deref(inner)
        | ExprKind::Ref(inner)
        | ExprKind::Fail(inner)
        | ExprKind::Wrap(inner)
        | ExprKind::Widen(inner)
        | ExprKind::Pipe(inner)
        | ExprKind::Piped(inner) => visit_expr(inner, f),
        ExprKind::New { value, .. }
        | ExprKind::Copy { value, .. }
        | ExprKind::Shortcut { value, .. }
        | ExprKind::ToText { value, .. }
        | ExprKind::ToJson { value, .. } => visit_expr(value, f),
        ExprKind::Index(a, b)
        | ExprKind::Lookup(a, b)
        | ExprKind::Binary(_, a, b)
        | ExprKind::Range(a, b)
        | ExprKind::Repeat { value: a, count: b } => {
            visit_expr(a, f);
            visit_expr(b, f);
        }
        ExprKind::Invoke { callee, args } => {
            visit_expr(callee, f);
            each(args, f);
        }
        ExprKind::Call { args, .. }
        | ExprKind::Construct { args, .. }
        | ExprKind::Array(args)
        | ExprKind::Tuple(args)
        | ExprKind::Scan { args, .. } => each(args, f),
        ExprKind::Join { parts, .. } => each(parts, f),
        ExprKind::MethodCall { value, args, .. } => {
            visit_expr(value, f);
            each(args, f);
        }
        ExprKind::Edit { items, args, .. } => {
            visit_expr(items, f);
            each(args, f);
        }
        ExprKind::StructInit { fields, .. } => {
            fields.iter().for_each(|field| visit_expr(&field.value, f))
        }
        ExprKind::Pairs(pairs) => pairs.iter().for_each(|(key, value)| {
            visit_expr(key, f);
            visit_expr(value, f);
        }),
        ExprKind::MapOp { map, key, .. } => {
            visit_expr(map, f);
            if let Some(key) = key {
                visit_expr(key, f);
            }
        }
        ExprKind::PlanB { value, body, .. } => {
            visit_expr(value, f);
            visit_block(body, f);
        }
        ExprKind::Choice(stmt) => visit_stmt(stmt, f),
        ExprKind::LoopValue(value) => visit_stmt(&value.stmt, f),
    }
}

fn add_startups(items: &mut Vec<Item>) {
    let mut startups: Vec<TaskDef> = Vec::new();
    for item in items.iter_mut() {
        let Item::Task(task) = item else { continue };
        if task.decorators.is_empty() {
            continue;
        }
        let name = qualify(module_of(&task.name), STARTUP);
        let passes: Vec<bool> = std::mem::take(&mut task.passes).into_iter().rev().collect();
        let calls = std::mem::take(&mut task.decorators)
            .into_iter()
            .rev()
            .map(|call| {
                let span = call.span;
                Stmt::new(StmtKind::Expr(call), span)
            });
        match startups.iter_mut().find(|startup| startup.name == name) {
            Some(startup) => {
                startup.body.extend(calls);
                startup.passes.extend(passes);
            }
            None => startups.push(TaskDef {
                name,
                types: Vec::new(),
                given: Vec::new(),
                params: Vec::new(),
                ret: Type::Nothing,
                results: Vec::new(),
                body: calls.collect(),
                span: task.span,
                private: true,
                native: false,
                owner: None,
                decorators: Vec::new(),
                passes,
                wrappers: Vec::new(),
                kept: None,
                shortcut: false,
            }),
        }
    }
    items.extend(startups.into_iter().map(Item::Task));
}

pub const BUILTIN_TYPE_WORDS: &[&str] = &[
    "int", "int64", "int32", "int16", "int8", "uint", "uint64", "uint32", "uint16", "uint8",
    "unit", "float", "float64", "float32", "text", "bool", "char",
];

/// Placeholder region for unknown-type tuple item tests so borrows never escape the call.
const UNNAMED_REGION: &str = "#item";

fn callee_text(callee: &Expr) -> String {
    match &callee.kind {
        ExprKind::Var(name) => name.clone(),
        ExprKind::Field(base, field) => format!("{}.{}", callee_text(base), field),
        ExprKind::Index(base, _) => format!("{}[…]", callee_text(base)),
        ExprKind::Call { name, .. } => format!("{}(…)", unqualified(name)),
        ExprKind::Invoke { callee, .. } => format!("{}(…)", callee_text(callee)),
        ExprKind::Shared { shape, field } => format!("{}.{}", shape, field),
        _ => "value".to_string(),
    }
}

fn own_region_type(what: &str, task: &str, param: &str, ty: &Type) -> String {
    let shown = ty.map_regions(&mut |region| {
        Some(if region == OWN_REGION {
            "a".to_string()
        } else {
            region.to_string()
        })
    });
    format!(
        "{0} '{1}' takes '{2}' from a task value, where it is {3}, with '@a' a region that task value takes; which region that is only the body of '{1}' says, when it gives the task value one, so '{2}' can't be in it; write that type out in the header of '{1}', with the region it takes as a parameter of its own, 'a: region', as in '(next: (@a, int) -> [int]@a, a: region, n: int) -> [int]@a'",
        what,
        unqualified(task),
        param,
        shown
    )
}

fn bound_text(bound: &Bound) -> String {
    if bound.parts.is_empty() {
        return bound.name.clone();
    }
    format!(
        "({})",
        bound
            .parts
            .iter()
            .map(bound_text)
            .collect::<Vec<_>>()
            .join(", ")
    )
}

fn bound_spans(bound: &Bound, spans: &mut Vec<Span>) {
    if bound.parts.is_empty() {
        spans.push(bound.span);
    }
    bound.parts.iter().for_each(|part| bound_spans(part, spans));
}

fn copy_region(ty: &Type) -> &str {
    // Methods cannot allocate directly in the receiver's own region.
    ty.regions()
        .into_iter()
        .find(|region| !unnamed_region(region) && *region != THIS_WORD)
        .unwrap_or("r")
}

/// Sentinel placeholder replaced by the containing literal when suggesting `.copy()` fixes.
const OWNER_MARK: &str = "\u{0}";

fn loop_values<'a>(stmt: &'a Stmt, values: &mut Vec<&'a Expr>) {
    match &stmt.kind {
        StmtKind::Loop(_, body, finally) | StmtKind::Each(_, _, _, body, finally) => {
            last_values(finally.as_ref().unwrap_or(body), values);
            body.iter().for_each(|stmt| break_values(stmt, values));
        }
        StmtKind::Parted(parted) => {
            last_values(parted.finally.as_ref().unwrap_or(&parted.body), values);
            parted
                .body
                .iter()
                .for_each(|stmt| break_values(stmt, values));
        }
        StmtKind::Named(_, inner) => loop_values(inner, values),
        _ => {}
    }
}

fn break_values<'a>(stmt: &'a Stmt, values: &mut Vec<&'a Expr>) {
    let mut blocks: Vec<&'a [Stmt]> = Vec::new();
    match &stmt.kind {
        StmtKind::Break(_, Some(value)) => values.push(value),
        StmtKind::When(arms, else_block) => {
            blocks.extend(arms.iter().map(|arm| arm.body.as_slice()));
            blocks.extend(else_block.iter().map(Vec::as_slice));
        }
        StmtKind::Match(_, cases) => blocks.extend(cases.iter().map(|case| case.body.as_slice())),
        StmtKind::Block(body) => blocks.push(body),
        StmtKind::Loop(_, body, finally) | StmtKind::Each(_, _, _, body, finally) => blocks.extend(
            [Some(body), finally.as_ref()]
                .into_iter()
                .flatten()
                .map(Vec::as_slice),
        ),
        StmtKind::Parted(parted) => blocks.extend(
            [Some(&parted.body), parted.finally.as_ref()]
                .into_iter()
                .flatten()
                .map(Vec::as_slice),
        ),
        StmtKind::Named(_, inner) => break_values(inner, values),
        _ => {}
    }
    for block in blocks {
        block.iter().for_each(|stmt| break_values(stmt, values));
    }
}

fn unnamed_region(region: &str) -> bool {
    [ANY_REGION, UNNAMED_REGION, OWN_REGION].contains(&region)
}

/// Sentinel region for nested callback params so instantiations cannot unify them with caller regions.
const OWN_REGION: &str = "#own";

const TYPE_TEST_ON_A_READ: &str = "a type after 'is' tests a tuple's item read with '.#' from a tuple with a name, as in 'when t.#2 is maybe int {x}'";

fn item_state(read: &Expr) -> Option<Option<Type>> {
    match &read.kind {
        ExprKind::Wrap(inner) if matches!(inner.kind, ExprKind::Field(..)) => match &inner.ty {
            Some(Type::None) => Some(None),
            Some(found) if found.params().is_empty() => Some(Some(found.clone())),
            _ => None,
        },
        ExprKind::Field(_, item) if item.starts_with(SAFE_ITEM) && read.ty == Some(Type::None) => {
            Some(None)
        }
        _ => None,
    }
}

fn safe_read_of(read: &Expr) -> Option<(String, usize)> {
    let (ExprKind::Field(base, item), safe) = (match &read.kind {
        ExprKind::Wrap(inner) => (&inner.kind, true),
        other => (other, false),
    }) else {
        return None;
    };
    if !safe && !item.starts_with(SAFE_ITEM) {
        return None;
    }
    let ExprKind::Var(tuple) = &base.kind else {
        return None;
    };
    Some((
        tuple.clone(),
        item.trim_start_matches(SAFE_ITEM).parse().ok()?,
    ))
}

fn same_ignoring_regions(a: &Type, b: &Type) -> bool {
    a.without_regions() == b.without_regions()
}

/// Sentinel type for past-end tuple Plan Bs (`t.#5 { 0 }`).
const PAST_END: &str = "#past";

fn past_end(e: &Expr) -> bool {
    matches!(&e.kind, ExprKind::Field(_, item) if item.starts_with(SAFE_ITEM))
        && e.ty == Some(Type::None)
}

const GROUP_TUPLE_UNPACKED: &str = "this is the tuple of a group's values, which holds as many items as each use gives, so no list of names fits it; read its items as 't.0', or as 't.#0', a maybe";

fn copy_type(given: &HashMap<String, Type>, name: &str) -> Option<Type> {
    if given.is_empty() {
        return None;
    }
    if given.contains_key(&format!("{}{}", name, GROUP_MARK)) {
        return Some(
            given
                .get(&format!("{}{}", name, GROUP_TURN))
                .cloned()
                .unwrap_or_else(placeholder_type),
        );
    }
    given
        .get(name)
        .cloned()
        .or_else(|| name.contains(GROUP_ITEM).then(placeholder_type))
}

fn in_copy(ty: &Type, given: &HashMap<String, Type>) -> Type {
    if given.is_empty() {
        return ty.clone();
    }
    padded_group_tuples(
        &ty.map_group_items(&mut |name| group_items(given, name))
            .map_params(&mut |name| copy_type(given, name)),
    )
}

fn placeholder_type() -> Type {
    Type::Int
}

/// Pads `< 2`-element tuples in runtime type positions because C lacks 0/1-element structs.
fn padded_group_tuples(ty: &Type) -> Type {
    let boxed = |inner: &Type| Box::new(padded_group_tuples(inner));
    match ty {
        Type::Tuple(items) => {
            let mut items: Vec<Type> = items.iter().map(padded_group_tuples).collect();
            while items.len() < 2 {
                items.push(placeholder_type());
            }
            Type::Tuple(items)
        }
        Type::Or(value, error) => Type::Or(boxed(value), boxed(error)),
        Type::Maybe(inner) => Type::Maybe(boxed(inner)),
        Type::Fail(inner) => Type::Fail(boxed(inner)),
        Type::Ptr(inner, region) => Type::Ptr(boxed(inner), region.clone()),
        Type::Array(inner, count) => Type::Array(boxed(inner), *count),
        Type::Slice(inner, region) => Type::Slice(boxed(inner), region.clone()),
        Type::Results(types) => Type::Results(types.iter().map(padded_group_tuples).collect()),
        Type::Map(key, value, region) => Type::Map(boxed(key), boxed(value), region.clone()),
        Type::Range(inner) => Type::Range(boxed(inner)),
        Type::Applied(applied) => Type::Applied(Box::new(Applied {
            name: applied.name.clone(),
            types: applied.types.iter().map(padded_group_tuples).collect(),
            region: applied.region.clone(),
        })),
        Type::Task(task) => Type::Task(Box::new(TaskType {
            params: task.params.iter().map(padded_group_tuples).collect(),
            taken: task.taken.clone(),
            ret: padded_group_tuples(&task.ret),
        })),
        other => other.clone(),
    }
}

fn name_value_loop(value: &mut ValueLoop, name: &str, at: Span) -> Result<()> {
    if let Some((written, written_at)) = value.name.as_ref().filter(|_| value.arrow) {
        return err(
            *written_at,
            format!(
                "this loop gives '{0}' its value, which names it '{0}', so it takes no name of its own; leave out '{1} =>' and write 'break {0}'",
                name, written
            ),
        );
    }
    value.name = Some((name.to_string(), at));
    Ok(())
}

fn last_values<'a>(block: &'a [Stmt], values: &mut Vec<&'a Expr>) {
    match block.last().map(|stmt| &stmt.kind) {
        Some(StmtKind::Expr(e)) => values.push(e),
        Some(StmtKind::When(arms, else_block)) => {
            arms.iter().for_each(|arm| last_values(&arm.body, values));
            if let Some(block) = else_block {
                last_values(block, values);
            }
        }
        Some(StmtKind::Match(_, cases)) => cases
            .iter()
            .for_each(|case| last_values(&case.body, values)),
        _ => {}
    }
}

fn last_values_mut(block: &mut [Stmt], f: &mut dyn FnMut(&mut Expr)) {
    match block.last_mut().map(|stmt| &mut stmt.kind) {
        Some(StmtKind::Expr(e)) => f(e),
        Some(StmtKind::When(arms, else_block)) => {
            arms.iter_mut()
                .for_each(|arm| last_values_mut(&mut arm.body, f));
            if let Some(block) = else_block {
                last_values_mut(block, f);
            }
        }
        Some(StmtKind::Match(_, cases)) => cases
            .iter_mut()
            .for_each(|case| last_values_mut(&mut case.body, f)),
        _ => {}
    }
}

fn last_loop_gives(last: &mut Stmt) {
    if let StmtKind::Expr(Expr {
        kind: ExprKind::PlanB { value, .. },
        ..
    }) = &mut last.kind
        && let ExprKind::LoopValue(value) = &mut value.kind
    {
        value.gives = true;
    }
}

fn may_fail(e: &Expr) -> bool {
    let e = match &e.kind {
        ExprKind::Wrap(inner) => inner,
        _ => e,
    };
    matches!(e.ty, Some(Type::Or(..) | Type::Fail(_)))
}

fn says_true(cond: &Condition) -> bool {
    cond.single() && cond.pattern.is_none() && matches!(cond.value.kind, ExprKind::BoolLit(true))
}

fn known_condition(cond: &Condition) -> Option<bool> {
    let mut taken = Some(true);
    for part in cond.parts() {
        match known_part(part) {
            Some(false) => return Some(false),
            Some(true) => {}
            None => taken = None,
        }
    }
    taken
}

fn known_part(part: &Condition) -> Option<bool> {
    let item = item_state(&part.value);
    match part.pattern.as_ref().map(|pattern| &pattern.kind) {
        None => known_bool(&part.value),
        Some(PatternKind::Tuple(_)) => Some(true),
        Some(PatternKind::Value(_)) if matches!(item, Some(Some(_))) => Some(true),
        Some(PatternKind::None) => item.map(|found| found.is_none()),
        _ => None,
    }
}

fn known_bool(e: &Expr) -> Option<bool> {
    match &e.kind {
        ExprKind::BoolLit(b) => Some(*b),
        ExprKind::Unary(UnaryOp::Not, inner) => known_bool(inner).map(|b| !b),
        ExprKind::Binary(op @ (BinaryOp::And | BinaryOp::Or), a, b) => {
            let decides = *op == BinaryOp::Or;
            match (known_bool(a), known_bool(b)) {
                (Some(side), _) | (_, Some(side)) if side == decides => Some(decides),
                (Some(_), Some(_)) => Some(!decides),
                _ => None,
            }
        }
        ExprKind::Binary(op, a, b) => {
            let (a, b) = (known_int(a)?, known_int(b)?);
            match op {
                BinaryOp::Eq => Some(a == b),
                BinaryOp::Ne => Some(a != b),
                BinaryOp::Lt => Some(a < b),
                BinaryOp::Gt => Some(a > b),
                BinaryOp::Le => Some(a <= b),
                BinaryOp::Ge => Some(a >= b),
                _ => None,
            }
        }
        _ => None,
    }
}

fn known_int(e: &Expr) -> Option<i64> {
    match &e.kind {
        ExprKind::IntLit(n) => Some(*n),
        ExprKind::Binary(BinaryOp::Add, a, b) => known_int(a)?.checked_add(known_int(b)?),
        ExprKind::Binary(BinaryOp::Sub, a, b) => known_int(a)?.checked_sub(known_int(b)?),
        _ => None,
    }
}

fn group_tuple_type(group: &str) -> Type {
    Type::Or(
        Box::new(Type::Tuple(vec![Type::Group(group.to_string())])),
        Box::new(Type::Maybe(Box::new(Type::Param(group_item(group, 0))))),
    )
}

fn group_in_tuple(items: &[Type]) -> Option<String> {
    match items {
        [Type::Group(group)] => Some(group.clone()),
        _ => None,
    }
}

fn group_item(group: &str, place: usize) -> String {
    format!("{}{}{}", group, GROUP_ITEM, place)
}

fn group_types(given: &HashMap<String, Type>, name: &str) -> Option<Vec<Type>> {
    group_items(given, name).map(|(types, _)| types)
}

fn group_items(given: &HashMap<String, Type>, name: &str) -> Option<(Vec<Type>, Vec<Taken>)> {
    match given.get(name) {
        Some(Type::Tuple(types)) => Some((types.clone(), vec![Taken::Value; types.len()])),
        Some(Type::Task(task)) if task.ret == GROUP_SENDS => {
            Some((task.params.clone(), task.taken.clone()))
        }
        _ => None,
    }
}

/// Encodes variadic group types with passing modes (value vs place) so monomorphized C signatures stay distinct.
fn group_binding(types: Vec<Type>, taken: Vec<Taken>) -> Type {
    if taken.iter().all(|how| *how == Taken::Value) {
        return Type::Tuple(types);
    }
    Type::Task(Box::new(TaskType {
        params: types,
        taken,
        ret: GROUP_SENDS,
    }))
}

fn packed_groups(types: Vec<(&str, TypeArg)>, taken: &HashMap<String, Taken>) -> Vec<TypeArg> {
    let mut packed: Vec<(Vec<Type>, Vec<Taken>, Span, bool)> = Vec::new();
    let mut group: Option<&str> = None;
    for (name, (ty, at)) in types {
        let how = taken.get(name).cloned().unwrap_or(Taken::Value);
        match name.split_once(GROUP_ITEM) {
            Some((of, _)) if group == Some(of) => {
                if let Some((items, hows, _, _)) = packed.last_mut() {
                    items.push(ty);
                    hows.push(how);
                }
            }
            Some((of, _)) => {
                group = Some(of);
                packed.push((vec![ty], vec![how], at, true));
            }
            None => {
                group = None;
                packed.push((vec![ty], Vec::new(), at, false));
            }
        }
    }
    packed
        .into_iter()
        .map(|(mut items, hows, at, grouped)| {
            (
                if grouped {
                    group_binding(items, hows)
                } else {
                    items.remove(0)
                },
                at,
            )
        })
        .collect()
}

fn group_value(name: &str, i: usize) -> String {
    format!("{}__{}", name, i + 1)
}

fn spread_values(args: &mut Vec<Expr>, given: &HashMap<String, Type>, places: bool) {
    let Some(at) = args
        .iter()
        .position(|arg| matches!(arg.kind, ExprKind::Spread(_)))
    else {
        return;
    };
    let Some(Expr {
        kind: ExprKind::Spread(inner),
        span,
        ..
    }) = args.get(at)
    else {
        return;
    };
    let (ExprKind::Var(name), Some(Type::Group(group))) = (&inner.kind, &inner.ty) else {
        return;
    };
    let Some((types, taken)) = group_items(given, group) else {
        return;
    };
    let (name, span) = (name.clone(), *span);
    let values: Vec<Expr> = types
        .into_iter()
        .zip(taken)
        .enumerate()
        .map(|(i, (ty, how))| {
            let mut value = Expr::new(ExprKind::Var(group_value(&name, i)), span);
            value.ty = Some(ty.clone());
            if places && matches!(how, Taken::Place(_)) {
                value = Expr {
                    kind: ExprKind::Ref(Box::new(value)),
                    span,
                    ty: Some(ty),
                };
            }
            value
        })
        .collect();
    args.splice(at..=at, values);
}

fn group_given_in_copy(ty: &Type, given: &HashMap<String, Type>) -> Type {
    let Type::Tuple(items) = ty else {
        return ty
            .map_groups(&mut |name| group_types(given, name))
            .map_params(&mut |name| copy_type(given, name));
    };
    let (mut types, mut taken) = (Vec::new(), Vec::new());
    for item in items {
        match item {
            Type::Group(name) if let Some((group, how)) = group_items(given, name) => {
                types.extend(group);
                taken.extend(how);
            }
            other => {
                types.push(
                    other
                        .map_groups(&mut |name| group_types(given, name))
                        .map_params(&mut |name| copy_type(given, name)),
                );
                taken.push(Taken::Value);
            }
        }
    }
    group_binding(types, taken)
}

pub const SAFE_ITEM: char = '#';

/// Key suffix marking a group type-parameter entry.
const GROUP_MARK: &str = "...";

/// Key suffix storing the per-iteration element type for `each v in group`.
const GROUP_TURN: &str = "*";

/// Separator between a group param name and element index (`P#0`).
const GROUP_ITEM: char = '#';

fn qualify(module: &str, name: &str) -> String {
    if module.is_empty() {
        name.to_string()
    } else {
        format!("{}{}{}", module, MODULE_SEPARATOR, name)
    }
}

fn in_region_of(ty: &Type, of: &Type) -> Type {
    let region = match of {
        Type::Named(_, region) => region.clone(),
        Type::Applied(applied) => applied.region.clone(),
        _ => None,
    };
    match ty {
        Type::Named(name, _) => Type::Named(name.clone(), region),
        Type::Applied(applied) => Type::Applied(Box::new(Applied {
            region,
            ..(**applied).clone()
        })),
        other => other.clone(),
    }
}

fn variant_name(kind: &KindDef, i: usize, variant: &Variant) -> String {
    if i < kind.imitated {
        imitated_variant(&kind.name, &variant.tag)
    } else {
        qualify(module_of(&kind.name), &variant.tag)
    }
}

fn err<T>(span: Span, msg: impl Into<String>) -> Result<T> {
    Err(Error::at(span, msg))
}

/// Sorts deduplicated errors by `(file == main, line, col)` with span-less internal errors last.
fn in_source_order(errors: Vec<Error>) -> Vec<Error> {
    let mut seen = HashSet::new();
    let mut errors: Vec<Error> = errors
        .into_iter()
        .filter(|error| seen.insert((error.span.map(Span::place_key), error.message.clone())))
        .collect();
    // Stable sort preserves discovery order for ties at the same span.
    errors.sort_by_key(|error| match error.span {
        Some(span) => (0, span.file, span.line, span.col),
        None => (1, 0, 0, 0),
    });
    errors
}

fn chosen_message(
    what: &str,
    name: &str,
    ty: &Type,
    declared: &Type,
    size: usize,
    given: Option<String>,
) -> String {
    let written = ty.without_regions();
    let address = what.starts_with("'&");
    let (whose, subject, words) = match (name == THIS, address) {
        (true, false) => (
            "the value the method is called on",
            "'.this'".to_string(),
            "; compare items with '~='".to_string(),
        ),
        (true, true) => (
            "the value the method is called on",
            "'.this'".to_string(),
            String::new(),
        ),
        (false, false) => (
            "a parameter",
            format!("'{}'", name),
            format!(
                "; write 'fixed& {0}: {1}' for the caller's place, 'fixed {0}: {1}' for a copy of its own, or compare items with '~='",
                name, declared
            ),
        ),
        (false, true) => (
            "a parameter",
            format!("'{}'", name),
            format!(
                "; write 'fixed& {0}: {1}' for the caller's place, or 'fixed {0}: {1}' for a copy of its own",
                name, declared
            ),
        ),
    };
    let given = given
        .map(|given| format!(" ({})", given))
        .unwrap_or_default();
    let went = if codegen::hidden_by_size(size) {
        format!(
            "{} takes {} bytes, more than {}, so {} is where the caller keeps it, or a copy the caller makes first of a value that might change while the task runs, such as one behind a pointer, in a slice or a shared field, or named by a reference",
            written,
            size,
            codegen::HIDDEN_ABOVE,
            subject
        )
    } else {
        format!(
            "{} takes {} bytes, so {} is a copy, a place of its own, never the caller's",
            written, size, subject
        )
    };
    format!(
        "{}, and {} is {}, given as the compiler chose{}: {}{}",
        what, subject, whose, given, went, words
    )
}

fn param_hint_for(name: &str, info: &VarInfo, shares: bool) -> String {
    if info.kept && info.passing == Passing::FixedRef {
        return format!(
            "; this lambda keeps '{0}' as 'fixed& {0}', which only reads it, and one that changes it keeps it as 'flex& {0}'",
            name
        );
    }
    if info.bind_reads {
        return format!(
            "; '{0}' is the copy this lambda keeps of a variable of the code around it, and a '[bind @r]' lambda changes only what every copy of it shares, the items of a slice, a map, what a pointer points to, so it only reads its own copy of anything else; one that changes its copies is written '[flex @r](…)'",
            name
        );
    }
    if info.kept {
        return format!(
            "; '{0}' is the copy this lambda keeps of a variable of the code around it, which a '[@r]' lambda never changes; one that changes its copies is written '[flex @r](…)', and one that changes the variable itself keeps it as a place, '[flex& {0}, @r]'",
            name
        );
    }
    if info.refers.is_some() {
        return format!(
            "; '{0}' only reads the place it names, and a reference that changes it is written 'flex& {0} = &…'",
            name
        );
    }
    if !info.param || name == THIS {
        return String::new();
    }
    if info.passing == Passing::FixedRef {
        return format!(
            "; '{0}' is a 'fixed&' parameter, which only reads the caller's place, and one that changes it is written 'flex& {0}: {1}'",
            name, info.ty
        );
    }
    let own = match &info.ty {
        Type::Slice(..) => "the task's own copy of the slice, whose items are the caller's",
        Type::Map(..) => "the task's own copy of the map, which names the caller's map",
        Type::Ptr(..) => "the task's own copy of the pointer, which points to the caller's value",
        _ if shares => "the task's own copy of a twofold value, which names what the caller's does",
        _ => "and is the task's own copy",
    };
    format!(
        "; a parameter that changes is written 'flex {}: {}', {}",
        name, info.ty, own
    )
}

#[derive(Debug, Clone, PartialEq)]
enum Step {
    Field(String),
    Item(Option<i64>),
    Deref,
}

fn no_place(place: &Expr) -> &'static str {
    match &place.kind {
        ExprKind::Index(_, index) if matches!(index.kind, ExprKind::Range(..)) => {
            "a part taken of a value, which is a new value"
        }
        ExprKind::Index(base, _) if matches!(base.ty, Some(Type::Text(_))) => {
            "a byte of text, read out of text that never changes"
        }
        ExprKind::Lookup(..) => "a maybe that '[#…]' or 'at' made here",
        ExprKind::Field(base, _) if worked_out(base) => "a length, worked out from the value",
        ExprKind::Call { .. } | ExprKind::MethodCall { .. } => "a call's value, which is made here",
        ExprKind::Construct { .. } => "a variant, which is a value",
        ExprKind::Var(_) => "a variant, which is a value",
        ExprKind::Macro { .. } => "a macro, a value the compiler computed",
        _ => "a value made here",
    }
}

fn worked_out(base: &Expr) -> bool {
    matches!(
        base.ty,
        Some(Type::Array(..) | Type::Slice(..) | Type::Map(..) | Type::Text(_))
    )
}

fn note_chosen_address(e: &Expr, made: &mut Made) {
    let ExprKind::Ref(place) = &e.kind else {
        return;
    };
    if let Some((name, at)) = param_root(place).filter(|(name, _)| made.chosen.contains_key(*name))
    {
        let written = place_path(place).map_or_else(|| name.to_string(), |path| path_text(&path));
        made.reads_chosen.push((
            at,
            format!("'&{}' is where the place is", written),
            name.to_string(),
        ));
    }
}

fn param_root(e: &Expr) -> Option<(&str, Span)> {
    match &e.kind {
        ExprKind::Var(name) => Some((name, e.span)),
        ExprKind::Field(base, _) => param_root(base),
        ExprKind::Index(base, index)
            if !matches!(index.kind, ExprKind::Range(..))
                && !matches!(base.ty, Some(Type::Slice(..) | Type::Map(..))) =>
        {
            param_root(base)
        }
        _ => None,
    }
}

fn same_root(a: &Expr, b: &Expr) -> bool {
    matches!((param_root(a), param_root(b)), (Some((x, _)), Some((y, _))) if x == y)
}

fn names_place(e: &Expr) -> bool {
    match &e.kind {
        ExprKind::Var(_) | ExprKind::Shared { .. } | ExprKind::Deref(_) => true,
        ExprKind::Field(base, _) => names_place(base),
        ExprKind::Index(base, index) => {
            !matches!(index.kind, ExprKind::Range(..))
                && !matches!(base.ty, Some(Type::Text(_)))
                && names_place(base)
        }
        _ => false,
    }
}

fn place_path(e: &Expr) -> Option<Vec<Step>> {
    let mut steps = Vec::new();
    let mut at = e;
    loop {
        match &at.kind {
            ExprKind::Var(name) => {
                steps.push(Step::Field(name.clone()));
                steps.reverse();
                return Some(steps);
            }
            ExprKind::Shared { shape, field } => {
                steps.push(Step::Field(shared_key(shape, field)));
                steps.reverse();
                return Some(steps);
            }
            ExprKind::Field(base, field) => {
                steps.push(Step::Field(field.clone()));
                at = base;
            }
            ExprKind::Index(base, index) if !matches!(index.kind, ExprKind::Range(..)) => {
                steps.push(Step::Item(match index.kind {
                    ExprKind::IntLit(n) => Some(n),
                    _ => None,
                }));
                at = base;
            }
            ExprKind::Deref(pointer) => {
                steps.push(Step::Deref);
                at = pointer;
            }
            _ => return None,
        }
    }
}

fn overlaps(a: &[Step], b: &[Step]) -> bool {
    let (shorter, longer) = if a.len() <= b.len() { (a, b) } else { (b, a) };
    if longer.get(shorter.len()) == Some(&Step::Deref) {
        return false;
    }
    a.iter().zip(b).all(|pair| match pair {
        (Step::Item(Some(x)), Step::Item(Some(y))) => x == y,
        (Step::Item(_), Step::Item(_)) => true,
        (x, y) => x == y,
    })
}

fn path_text(path: &[Step]) -> String {
    let mut text = String::new();
    for (i, step) in path.iter().enumerate() {
        match step {
            Step::Field(name) if i == 0 && name == THIS && path.len() > 1 => {}
            Step::Field(name) if i == 0 => text.push_str(name),
            Step::Field(name) => {
                text.push('.');
                text.push_str(name);
            }
            Step::Item(Some(n)) => text.push_str(&format!("[{}]", n)),
            Step::Item(None) => text.push_str("[…]"),
            Step::Deref => text.push('^'),
        }
    }
    text
}

enum Taker<'a> {
    Param(&'a str),
    BindParam(&'a str),
    Reference(&'a str),
    BindReference(&'a str),
    Kept(&'a str),
    KeptBind(&'a str),
}

impl Taker<'_> {
    fn is_bind(&self) -> bool {
        matches!(
            self,
            Taker::BindParam(_) | Taker::BindReference(_) | Taker::KeptBind(_)
        )
    }

    fn lead(&self) -> String {
        match self {
            Taker::Param(name) => format!("'{}' is given the place itself, to change", name),
            Taker::BindParam(name) => format!(
                "'{}' is given the place itself, to change its contents",
                name
            ),
            Taker::Reference(name) => format!("'flex& {}' names a place to change it", name),
            Taker::BindReference(name) => {
                format!("'bind& {}' names a place to change its contents", name)
            }
            Taker::Kept(name) => {
                format!("this lambda keeps '{0}' as 'flex& {0}', to change it", name)
            }
            Taker::KeptBind(name) => format!(
                "this lambda keeps '{0}' as 'bind& {0}', to change its contents",
                name
            ),
        }
    }

    fn using(&self, place: &str) -> String {
        match self {
            Taker::Param(name) | Taker::BindParam(name) => {
                format!("giving '{}' to '{}'", place, name)
            }
            Taker::Reference(name) => format!("naming '{}' with 'flex& {}'", place, name),
            Taker::BindReference(name) => format!("naming '{}' with 'bind& {}'", place, name),
            Taker::Kept(name) => format!("keeping '{}' as 'flex& {}'", place, name),
            Taker::KeptBind(name) => format!("keeping '{}' as 'bind& {}'", place, name),
        }
    }
}

fn named_params(ty: &Type, types: &[TypeParam]) -> Type {
    ty.replace_names(&|name| {
        types
            .iter()
            .any(|param| param.name == name)
            .then(|| Type::Param(name.to_string()))
    })
}

fn with_given(pattern: &PatternDef, given: &HashMap<String, Type>) -> PatternDef {
    if given.is_empty() {
        return pattern.clone();
    }
    let put = |ty: &Type| ty.map_params(&mut |name| given.get(name).cloned());
    let mut pattern = pattern.clone();
    for field in &mut pattern.fields {
        field.ty = put(&field.ty);
    }
    for method in &mut pattern.methods {
        for param in &mut method.params {
            param.ty = put(&param.ty);
        }
        method.ret = put(&method.ret);
    }
    pattern
}
